      build = mod.exports.__beta26.build,
      stateOwner = "nuzlocke",
      screens = {
          NuzlockeConfigScreen = {
              role = "rules",
              stateOwner = "nuzlocke",
              preferredLayout = "classic",
              nativeFallback = true,
