  local function ruleDescriptionForDisplay(rule, preGame)
      local base = tostring(Strings(rule and rule.desc or ""))
      if rule and rule.key == "difficulty_profile" then
          local selectedId = preGame and pendingNewGameRules
              and pendingNewGameRules.difficulty_provider_id
              or mod.save:get("difficulty_provider_id", "vanilla")
          local prefix = {}
          local summaryFn = mod.exports.__beta26
              and mod.exports.__beta26.difficultyProfileSummary
          if type(summaryFn) == "function" then
              local ok, summary = pcall(summaryFn, selectedId)
              if ok and type(summary) == "string" and summary ~= "" then
                  prefix[#prefix + 1] = summary
              end
          end
          local warningFn = mod.exports.__beta26
              and mod.exports.__beta26.difficultyStackWarning
          if type(warningFn) == "function" then
              local ok, warning = pcall(warningFn, selectedId)
              if ok and type(warning) == "string" and warning ~= "" then
                  prefix[#prefix + 1] = warning
              end
          end
          if #prefix > 0 then
              return table.concat(prefix, "\n") .. "\n" .. base
          end
      end
      if rule and rule.key == "no_catching"
          and mod.save:get("no_catching_legacy_ambiguous_29313", false) == true then
          return base .. "\n" .. tostring(Strings(
              "LEGACY SAVE REVIEW: an older partial Ball-ban migration may have enabled this. Confirm the setting you actually want; this beta did not guess and overwrite it."))
      end
      if rule and externalRuleDelegation then
          local delegated = externalRuleDelegation(rule.key, currentGame or mod.game)
          if delegated then
              local provider = tostring(delegated.name or delegated.id or "EXTERNAL MOD")
              local version = delegated.version and (" " .. tostring(delegated.version)) or ""
              local cap = tostring(delegated.capability or "provider")
              return base .. "\n" .. tostring(Strings(
                  "HANDLED BY %s%s. Nuzlocke's duplicate %s control is OFF and locked while this active provider owns the mechanic. Disable/remove that provider to restore your saved Nuzlocke choice.",
                  provider, version, cap))
          end
      end
      return base
  end


  ---------------------------------------------------------------------
  -- AREA GUIDE STATE
  --
  -- Area Guide is a normal Nuzlocke setting. The creator's mod uses
  -- mod.save for Nuzlocke state, so keep the setting there rather than
  -- using a separate storage layer that can return stale data.
  ---------------------------------------------------------------------
  local areaGuideEnabled = true

  local function loadAreaGuideState()
      local saved = mod.save:get("area_guide_enabled", nil)

      if type(saved) ~= "boolean" then
          saved = mod.save:get("route_list_all_areas", nil)
      end
      if type(saved) ~= "boolean" then
          saved = mod.save:get("show_checklist", nil)
      end

      if type(saved) == "boolean" then
          areaGuideEnabled = saved
      end

      return areaGuideEnabled
  end

  local function saveAreaGuideState(value)
      areaGuideEnabled = value == true
      mod.save:set("area_guide_enabled", areaGuideEnabled)
      return areaGuideEnabled
  end

  mod.exports.__beta26.legacySetupProfileFile = "nuzlocke_setup_profile.lua"
  mod.exports.__beta26.setupProfileFiles = {
      gen1 = "nuzlocke_setup_profile_gen1.lua",
      gold = "nuzlocke_setup_profile_gold.lua",
  }

  function mod.exports.__beta26.runtimeIsGold(game)
      if game and tonumber(game.generation) == 2 then return true end
      local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
      if okVersion and type(GameVersion) == "table"
          and type(GameVersion.isGold) == "function" then
          local okGold, isGold = pcall(GameVersion.isGold)
          if okGold then return isGold == true end
      end
      return false
  end

  function mod.exports.__beta26.profileScopeForGame(game)
      return mod.exports.__beta26.runtimeIsGold(game) and "gold" or "gen1"
  end

  function mod.exports.__beta26.setupProfileFilename()
      return mod.exports.__beta26.setupProfileFiles[mod.exports.__beta26.setupProfileScope]
          or mod.exports.__beta26.setupProfileFiles.gen1
  end

  -- Shared rules profile used by the title-screen setup and the active save.
  -- When no save is loaded yet this is the staged setup for the next save.
  -- When a save is active it mirrors that save, so both menus stay in sync.
  local pendingNewGameRules = nil
  local pendingRulesDirty = false
  local pendingNewGameRulesForNextSave = false
  -- Immutable snapshot captured at the instant NEW GAME is selected.
  -- This is deliberately separate from the live UI mirror so later save
  -- initialization cannot replace selected OFF->ON values with defaults.
  local newGameRulesSnapshot = nil
  local newGameRulesCommitPending = false
  local newGameCommitPassesRemaining = 0

  function mod.exports.__beta26.selectSetupProfileScope(game)
      local scope = mod.exports.__beta26.profileScopeForGame(game)
      if mod.exports.__beta26.setupProfileScope ~= scope then
          mod.exports.__beta26.setupProfileScope = scope
          pendingNewGameRules = nil
          -- Live changes were written to mod.save above, so the synchronized
      -- title representation is intentionally clean. Pre-game edits are staged
      -- only and therefore set pendingRulesDirty=true in the other branch.
      pendingRulesDirty = false
          pendingNewGameRulesForNextSave = false
          newGameRulesSnapshot = nil
          newGameRulesCommitPending = false
          newGameCommitPassesRemaining = 0
      end
      return scope
  end

  -- These keys persist the staged setup independently of the active save-rule
  -- keys.  They are declared here and used after copyRuleProfile is defined.
  local STAGED_PROFILE_KEY = "__nuzlocke_staged_new_game_profile"
  local STAGED_INTENT_KEY = "__nuzlocke_staged_new_game_intent"

  local function stagedProfileKey()
      return STAGED_PROFILE_KEY .. ":" .. mod.exports.__beta26.setupProfileScope
  end

  local function stagedIntentKey()
      return STAGED_INTENT_KEY .. ":" .. mod.exports.__beta26.setupProfileScope
  end

  ---------------------------------------------------------------------
  -- NEW GAME STARTER SETTINGS
  -- These values are read only when a brand-new save is constructed.
  -- Existing saves are never rewritten by this hook.
  ---------------------------------------------------------------------
  mod.exports.__beta26.resolveNewGameStartingResources = function(profile)
      profile = type(profile) == "table" and profile or {}
      local function bounded(value, fallback, maximum)
          local n = tonumber(value)
          if n == nil or n ~= n or n == math.huge or n == -math.huge then
              n = fallback
          end
          return math.max(0, math.min(maximum, math.floor(n)))
      end
      local candies
      if type(profile.starting_rare_candies) == "boolean" then
          candies = profile.starting_rare_candies and 99 or 0
      else
          candies = bounded(profile.starting_rare_candies, 0, 99)
      end
      return {
          money = bounded(profile.starting_money, 3000, 9999),
          balls = bounded(profile.starting_pokeballs, 0, 99),
          candies = candies,
      }
  end

  -- Deterministic regression matrix for the NEW GAME resource boundary.
  -- This is intentionally pure so headless/static smoke tests and future
  -- engine tests can exercise the exact fallback semantics without a save.
  mod.exports.__beta26.auditStartingResourceProfiles = function()
      local cases = {
          { {}, 3000, 0, 0 },
          { { starting_money = 0 }, 0, 0, 0 },
          { { starting_money = 3000, starting_pokeballs = 5, starting_rare_candies = 10 }, 3000, 5, 10 },
          { { starting_money = "bad", starting_pokeballs = -4, starting_rare_candies = 999 }, 3000, 0, 99 },
          { { starting_money = 999999, starting_pokeballs = 999 }, 9999, 99, 0 },
      }
      for _, row in ipairs(cases) do
          local got = mod.exports.__beta26.resolveNewGameStartingResources(row[1])
          if got.money ~= row[2] or got.balls ~= row[3] or got.candies ~= row[4] then
              return false, row
          end
      end
      return true
  end

  mod.hooks:wrap("save.new_game", function(next, save)
      local result = next(save)
      local targetSave = result or save
      currentSave = targetSave or currentSave
      if currentGame and currentSave then currentGame.save = currentSave end

      -- Resolve NEW GAME resources through one narrow boundary. Missing/invalid
      -- values preserve the vanilla/default $3000 wallet; an explicit 0 remains
      -- a legitimate player choice. This helper is exported so regression tests
      -- can assert the exact same defaults the save hook consumes.
      local profile = newGameRulesSnapshot or pendingNewGameRules
      local resources = mod.exports.__beta26.resolveNewGameStartingResources(profile)
      local startingMoney = resources.money
      local startingBalls = resources.balls
      local startingCandies = resources.candies

      if targetSave then
          -- Gold's Route 29 tutorial occurs after title staging has been
          -- cleared. Carry this NEW GAME-only choice on the save, just as the
          -- delayed Gold Rival-name shortcut does, without inventing a story
          -- flag before the real Route 29 script reaches it.
          targetSave.nuzlockeSkipCatchTutorial =
              profile and profile.skip_catch_tutorial == true or nil

          -- Starting Money / Balls / Rare Candies are currently an R/B/Y Setup
          -- feature. Gold exposes a deliberately smaller beta Setup surface, so
          -- never overwrite Gold's native starting resources from hidden/stale
          -- Gen1 profile fields. In particular, do not defer Gold Poke Balls:
          -- the R/B/Y release seam is intentionally disabled for generation 2.
          local version = getGameVersion and getGameVersion() or "RED"
          local saveVersion = tostring(targetSave.version
              or targetSave.gameVersion or ""):upper()
          local gen2Start = version == "GOLD" or version == "SILVER"
              or version == "CRYSTAL"
              or saveVersion:find("GOLD", 1, true) ~= nil
              or saveVersion:find("SILVER", 1, true) ~= nil
              or saveVersion:find("CRYSTAL", 1, true) ~= nil

          -- 2.2.21 Quick Nuzlocke Start is a NEW GAME transaction, not a
          -- persistent in-run toggle. Carry only the one-shot request and the
          -- resolved Ball amount onto the actual save so the world can apply it
          -- after native fresh-save initialization has completed. Five Balls is
          -- the minimum capture-ready checkpoint; a larger R/B/Y Start Balls
          -- choice remains authoritative.
          local quickStart = profile and profile.quick_nuzlocke_start == true
          targetSave.nuzlockeQuickStartPending = quickStart and true or nil
          targetSave.nuzlockeQuickStartBallCount = quickStart
              and (gen2Start and 5 or math.max(5, startingBalls)) or nil

          -- QoL: a fresh-save-only vitamin kit. It is deliberately stored in
          -- the PC rather than the Bag and marked on the save so even an
          -- unusual repeated save.new_game wrapper cannot duplicate it. The
          -- items do not bypass No Stat EXP Gain or any other use restriction.
          local delegatedRule = mod.exports.__beta26.externalRuleDelegation
          local delegationGame = currentGame or mod.game
          local vitaminsDelegated = type(delegatedRule) == "function"
              and delegatedRule("pc_starting_vitamins", delegationGame) ~= nil
          local healItemsDelegated = type(delegatedRule) == "function"
              and delegatedRule("pc_starting_heal_items", delegationGame) ~= nil

          if profile and profile.pc_starting_vitamins == true
              and not vitaminsDelegated
              and targetSave.nuzlockePcVitaminsGranted ~= true then
              targetSave.pcItems = targetSave.pcItems or {}
              local vitamins = mod.exports.__beta26.nativeStatVitamins
              for _, itemId in ipairs(vitamins) do
                  targetSave.pcItems[itemId] = math.max(0,
                      math.floor(tonumber(targetSave.pcItems[itemId]) or 0)) + 10
              end
              targetSave.nuzlockePcVitaminsGranted = true
          end

          -- QoL: optional fresh-save PC medicine kit. Keep this independent
          -- from challenge item-use policy: it only seeds storage once.
          if profile and profile.pc_starting_heal_items == true
              and not healItemsDelegated
              and targetSave.nuzlockePcHealItemsGranted ~= true then
              targetSave.pcItems = targetSave.pcItems or {}
              local healItems = {
                  "POTION", "SUPER_POTION", "MAX_POTION",
                  "ANTIDOTE", "BURN_HEAL", "ICE_HEAL", "AWAKENING",
                  "PARLYZ_HEAL", "FULL_HEAL",
              }
              for _, itemId in ipairs(healItems) do
                  targetSave.pcItems[itemId] = math.max(0,
                      math.floor(tonumber(targetSave.pcItems[itemId]) or 0)) + 10
              end
              targetSave.nuzlockePcHealItemsGranted = true
          end

          if not gen2Start then
              targetSave.money = startingMoney
              targetSave.pcItems = targetSave.pcItems or {}

              -- Immutable run-start snapshot for the Nuzlocke side of the
              -- Trainer Card. These values describe the selected NEW GAME setup,
              -- not the player's current inventory/money, and are never rewritten
              -- by normal gameplay. Keeping them on the actual save object avoids
              -- depending on title-screen mod.save state during the NEW GAME seam.
              targetSave.nuzlockeRunStartMoney = startingMoney
              targetSave.nuzlockeRunStartBalls = startingBalls
              targetSave.nuzlockeRunStartCandies = startingCandies

              -- beta.26 Soft Start: configured starting Balls are intentionally
              -- held until Oak's Pokedex handoff. This prevents the challenge
              -- from arming during the pre-Pokedex portion of a fresh R/B/Y run.
              targetSave.nuzlockeDeferredStartingBalls =
                  startingBalls > 0 and startingBalls or nil
              targetSave.pcItems.POKE_BALL = nil
              targetSave.pcItems.RARE_CANDY =
                  startingCandies > 0 and startingCandies or nil
          else
              -- Clean up only stale mod-owned deferral metadata. Do not touch
              -- Gold's money, PC items, or any other native New Game resources.
              targetSave.nuzlockeDeferredStartingBalls = nil
              targetSave.nuzlockeRunStartMoney = nil
              targetSave.nuzlockeRunStartBalls = nil
              targetSave.nuzlockeRunStartCandies = nil
          end
      end

      return result or targetSave
  end)

  ---------------------------------------------------------------------
  -- LOCKE TYPE PRESETS
  --
  -- These presets only expose playstyles the current rule engine can already
  -- enforce without inventing a new subsystem. Optional clauses (Dupes/Shiny,
  -- gifts/trades, legendary bans), UI options, world-building, Gym Guide,
  -- and starting resources remain independent of the selected preset.
  --
  -- CUSTOM    = preserve the player's hand-built rules.
  -- NUZLOCKE  = classic core: permadeath, first encounter, failed encounter,
  --             and required nicknames.
  -- HARDCORE  = NUZLOCKE + caps through Champion + no healing/X items in battle
  --             + Whiteout loss. Gym/Dungeon lock-ins remain optional because
  --             they are not part of the conventional Hardcore ruleset.
  --             Gen1Recomp's native Battle Style option remains authoritative;
  --             players who want full Hardcore should set it to SET.
  -- SOLO      = NUZLOCKE + Solo Only + Whiteout, so the active solo faint ends
  --             the run. PC swaps remain available because that is how the
  --             existing Solo Only rule is intentionally implemented.
  -- IRONMON   = an IronMON-style loadout using only rules this mod actually
  --             owns: Solo, Whiteout, no healing/X items, no escape, no field
  --             healing/PP helpers, and no shops/Centers/Mom. It intentionally
  --             does not claim to reproduce every external IronMON rule.
  ---------------------------------------------------------------------
  local LockePreset = {
      -- Saved numeric IDs 1-4 are intentionally preserved for compatibility
      -- with every pre-2.4.18 save. VANILLA is added as ID 5, while cycleOrder
      -- presents it first without renumbering historical loadouts.
      labels = {
          [0] = Strings.source("CUSTOM"),
          [1] = Strings.source("NUZ"),
          [2] = Strings.source("HARD"),
          [3] = Strings.source("SOLO"),
          [4] = Strings.source("IRON"),
          [5] = Strings.source("VANILLA"),
      },
      names = {
          [0] = Strings.source("CUSTOM"),
          [1] = Strings.source("NUZLOCKE"),
          [2] = Strings.source("HARDCORE"),
          [3] = Strings.source("SOLO"),
          [4] = Strings.source("IRONMON"),
          [5] = Strings.source("VANILLA"),
      },
      cycleOrder = { 0, 5, 1, 2, 3, 4 },
      -- Only these rules are owned by Nuzlocke Loadouts. Optional clauses,
      -- encounter variants, Type Locke, BST limits, Badge Boosts, Randomizer,
      -- Difficulty, World Building, QoL, UI and area splits remain independent.
      managed = {
          nuzlocke_enabled = true,
          permadeath = true,
          first_rival_forgiveness = true,
          encounter_limit = true,
          failed_encounter = true,
          nickname_rule = true,
          level_cap_scope = true,
          no_healing_items = true,
          no_battle_items = true,
          no_escape = true,
          no_repels = true,
          no_escape_rope = true,
          no_field_healing = true,
          no_pp_items = true,
          no_tm_use = true,
          no_rare_candy_use = true,
          no_buying = true,
          no_selling = true,
          no_poke_center = true,
          no_mom_heal = true,
          whiteout_clause = true,
          party_size_limit = true,
          gym_team_size = true,
      },
      presets = {
          -- Exact neutral values for every loadout-owned challenge rule. This
          -- intentionally does NOT reset independent mod features such as QoL,
          -- Difficulty or Randomizer; VANILLA here means vanilla challenge rules.
          [5] = {
              nuzlocke_enabled = false,
