  local function defaultRuleValue(key)
      if key == "locke_type" then
          return 1      -- NUZLOCKE; startup defaults now describe a conventional run
      end
      if key == "starting_money" then
          return 3000   -- preserve the vanilla R/B/Y starting wallet by default
      end
      if key == "starting_pokeballs" then
          return 0      -- NEW GAME default; placed in the room PC
      end
      if key == "starting_rare_candies" then
          return 0      -- NEW GAME default; configurable 00-99 in the room PC
      end
      if key == "nuzlocke_enabled" or key == "permadeath"
          or key == "first_rival_forgiveness" or key == "badge_boosts" then
          return true
      end
      if key == "world_building_tier" then
          return 1
      end
      if key == "level_cap_scope" then
          return 0
      end
      if key == "difficulty_profile" then
          return 0      -- VANILLA game difficulty; Nuzlocke Loadout is independent
      end
      if key == "exp_edging" then
          return false
      end
      if key == "dupes_mode" then
          return 2      -- FAMILY is the conventional Nuzlocke default
      end
      if key == "evolution_limit" then
          return 0      -- NORMAL / vanilla evolution behavior
      end
      if key == "travel_restrictions" then
          return 0      -- NORMAL / native field travel behavior
      end
      if key == "party_size_limit" then
          return 6      -- vanilla active-party capacity
      end
      if key == "shiny_clause" then
          return 0      -- OFF is the fresh/new-profile default; existing saved values remain authoritative
      end
      if key == "encounter_ball_limit" then
          return 0      -- OFF by default
      end
      if key == "rule_lock" then return false end
      if key == "encounter_spend_indicator" then return true end
      if key == "dev_mode" then return false end
      if key == "type_lock_mode" then return 0 end
      if key == "type_lock_draft" then return false end
      if key == "type_lock_primary" then return 0 end  -- NORMAL
      if key == "type_lock_secondary" then return 9 end -- WATER
      if key == "type_lock_tertiary" then return 10 end -- GRASS
      if key == "type_lock_quaternary" then return 8 end -- FIRE
      if key == "type_lock_quinary" then return 11 end -- ELECTRIC
      if key == "type_lock_senary" then return 2 end -- FLYING
      if key == "randomizer_seed" then return 0 end -- AUTO until the first Nuzlocke randomizer is enabled
      if key == "random_starter_style" then return 0 end -- ANY
      if key == "random_encounter_balance" then return 0 end -- CHAOS preserves historical behavior
      if key == "randomizer_info_policy" then return 0 end -- OPEN INFO preserves historical compatibility
      if key == "random_learnset_generation" then return 0 end -- AUTO / active merged move registry
      if key == "random_species_generation" then return 0 end -- AUTO / preserve 2.2.9 live species pool
      if key == "route_forgiveness" then
          return 0      -- OFF; enabling starts at 0 or 1 token
      end
      if key == "trainer_money_multiplier" then
          return 4      -- 100% / vanilla
      end
      if key == "no_catching" then
          return false
      end
      if key == "maximum_bst" then
          return 0
      end
      if key == "player_start_stat_exp" or key == "wild_start_stat_exp"
          or key == "trainer_start_stat_exp" then
          return 0
      end
      if key == "mt_moon_splits" or key == "safari_zone_splits"
          or key == "gold_egg_encounter_mode" or key == "gold_bug_contest_mode" then
          return 0
      end
      if key == "route_2_split" or key == "route_10_split"
          or key == "route_20_split" then
          return false
      end
      if key == "area_guide_enabled" then
          return true
      end
      if key == "rules_locked" then
          return false
      end
      -- Core/general defaults for a new Nuzlocke run.
      -- These are the requested startup defaults; once the save exists,
      -- the active save is authoritative and in-game toggles override them.
      if key == "encounter_limit" or key == "failed_encounter" or key == "allow_gifts"
          or key == "allow_trades" or key == "catch_info"
          or key == "stat_info" or key == "move_info"
          or key == "nickname_rule" then
          return true
      end
      if key == "overworld_encounters" or key == "town_catches"
          or key == "no_healing_items" or key == "no_battle_items"
          or key == "no_escape" or key == "no_mom_heal"
          or key == "no_buying" or key == "no_selling"
          or key == "no_repels" or key == "no_fishing" or key == "no_escape_rope"
          or key == "no_field_healing" or key == "no_pp_items"
          or key == "no_tm_use" or key == "no_rare_candy_use"
          or key == "allow_glitch_pokemon"
          or key == "automatic_running_shoes"
          or key == "automatic_default_names"
          or key == "skip_opening_intro"
          or key == "quick_nuzlocke_start"
          or key == "skip_catch_tutorial"
          or key == "skip_cherrygrove_tour"
          or key == "pc_starting_vitamins"
          or key == "pc_starting_heal_items"
          or key == "random_starter"
          or key == "random_encounter_tables"
          or key == "physical_special_split"
          or key == "gym_team_size"
          or key == "gold_time_split" or key == "gold_headbutt_split"
          or key == "gold_roamer_clause" or key == "gold_radio_world_building"
          or key == "random_learnsets"
          or key == "gym_lock_in" or key == "dungeon_lock_in"
          or key == "infinite_rare_candies" or key == "wonderlocke" then
          return false
      end
      return false
  end

  ---------------------------------------------------------------------
  -- MACHINE-READABLE RULE + SAVE CONFIG DESCRIPTORS (2.5.17)
  --
  -- Keep the existing battle-tested ruleCategories/defaultRuleValue paths as
  -- the behavior source.  These descriptors are derived from those paths so
  -- CI, Dev Mode, migration tests, and companion tooling can reason about the
  -- same configuration surface without maintaining a second handwritten rule
  -- list.  This is intentionally descriptive/read-only and does not bump Save
  -- Schema 4. Compatibility API 28 is bumped only because this child adds
  -- public per-capability contract-version negotiation.
  ---------------------------------------------------------------------
  do
      local function copyTable(value)
          if type(value) ~= "table" then return value end
          local out = {}
          for key, item in pairs(value) do out[key] = copyTable(item) end
          return out
      end

      local rows, byKey, collisions = {}, {}, {}
      local function addDescriptor(rule, category, source)
          if type(rule) ~= "table" or type(rule.key) ~= "string"
              or rule.key == "" then return end
          if byKey[rule.key] then
              collisions[#collisions + 1] = {
                  key = rule.key,
                  first_source = byKey[rule.key].source,
                  duplicate_source = tostring(source or "ruleCategories"),
              }
              return
          end
          local default = rule.default
          if default == nil then default = defaultRuleValue(rule.key) end
          local valueType = rule.value_type
              or (rule.numeric == true and "number" or type(default))
          if valueType == "nil" then valueType = "boolean" end
          local generation = "both"
          if rule.goldOnly == true then generation = "gold"
          elseif rule.rbyOnly == true then generation = "rby" end
          local row = {
              key = rule.key,
              category = tostring(category or "SYSTEM"),
              value_type = valueType,
              default = default,
              generation = generation,
              persisted = rule.persisted ~= false,
              setup_only = rule.setupOnly == true,
              numeric = rule.numeric == true,
              min = rule.min,
              max = rule.max,
              source = tostring(source or "ruleCategories"),
          }
          rows[#rows + 1] = row
          byKey[row.key] = row
      end

      for _, category in ipairs(ruleCategories or {}) do
          for _, rule in ipairs(category.rules or {}) do
              addDescriptor(rule, category.title, "ruleCategories")
          end
      end
      for _, meta in ipairs({
          { key="locke_type", value_type="number", default=defaultRuleValue("locke_type") },
          { key="rule_lock", value_type="boolean", default=defaultRuleValue("rule_lock") },
          { key="rules_locked", value_type="boolean", default=defaultRuleValue("rules_locked") },
          { key="rules_permanently_locked", value_type="boolean", default=false },
          { key="randomizer_seed", value_type="number", default=defaultRuleValue("randomizer_seed") },
          { key="difficulty_provider_id", value_type="string", default="vanilla" },
      }) do
          addDescriptor(meta, "SYSTEM", "profile_metadata")
      end

      table.sort(rows, function(a, b) return a.key < b.key end)

      local RuleRegistry = {}
      RuleRegistry.version = 1
      RuleRegistry.count = #rows
      function RuleRegistry.describe()
          return {
              api = 1,
              count = #rows,
              collision_count = #collisions,
              collisions = copyTable(collisions),
              rows = copyTable(rows),
          }
      end
      function RuleRegistry.get(key)
          local row = byKey[tostring(key or "")]
          return row and copyTable(row) or nil
      end
      function RuleRegistry.audit()
          local errors = {}
          for _, collision in ipairs(collisions) do
              errors[#errors + 1] = "duplicate:" .. tostring(collision.key)
          end
          local seen = {}
          for _, row in ipairs(rows) do
              if seen[row.key] then
                  errors[#errors + 1] = "duplicate:" .. row.key
              end
              seen[row.key] = true
              if row.value_type == "number" and type(row.default) ~= "number" then
                  errors[#errors + 1] = "default_type:" .. row.key
              elseif row.value_type == "boolean"
                  and type(row.default) ~= "boolean" then
                  errors[#errors + 1] = "default_type:" .. row.key
              elseif row.value_type == "string"
                  and type(row.default) ~= "string" then
                  errors[#errors + 1] = "default_type:" .. row.key
              end
          end
          return {
              ok = #errors == 0,
              count = #rows,
              errors = errors,
          }
      end
      mod.exports.__beta26.ruleRegistry = RuleRegistry

      local fields = {
          [SAVE_SCHEMA_KEY] = {
              key = SAVE_SCHEMA_KEY, value_type = "number",
              required = true, default = CURRENT_SAVE_SCHEMA,
              role = "schema_version",
          },
          [SAVE_MIGRATION_KEY] = {
              key = SAVE_MIGRATION_KEY, value_type = "string",
              required = false, role = "migration_checkpoint",
          },
      }
      for _, row in ipairs(rows) do
          fields[row.key] = {
              key = row.key,
              value_type = row.value_type,
              default = row.default,
              required = false,
              role = "configuration",
              generation = row.generation,
              source = row.source,
          }
      end
      -- Schema 4 retains a few persisted compatibility mirrors and migration-
      -- only inputs that are not independent current rules.  Describe them so
      -- migration tooling can distinguish them from undocumented gameplay
      -- state without pretending they are canonical configuration sources.
      fields.hardcore_mode = {
          key = "hardcore_mode", value_type = "boolean", default = false,
          required = false, role = "compatibility_mirror",
          canonical = "level_cap_scope", source = "level_cap_scope_mirror",
      }
      fields.elite_four_caps = {
          key = "elite_four_caps", value_type = "boolean", default = false,
          required = false, role = "compatibility_mirror",
          canonical = "level_cap_scope", source = "level_cap_scope_mirror",
      }
      for key, row in pairs({
          solo_active = { value_type = "boolean", canonical = "party_size_limit" },
          no_shopping = { value_type = "boolean", canonical = "no_buying/no_selling" },
          ball_use_ban_tier = { value_type = "number", canonical = "no_catching", migration = "retired_ball_ban_no_catching" },
          route_splits = { value_type = "number", canonical = "route_2_split/route_10_split/route_20_split", migration = "legacy_route_split_selectors" },
      }) do
          fields[key] = {
              key = key, value_type = row.value_type, required = false,
              role = "legacy_migration_input", canonical = row.canonical,
              migration = row.migration,
              source = "schema_migration",
          }
      end
      for key, row in pairs({
          nuzlocke_rule_revision = { value_type = "number", source = "rule_edit_revision" },
          no_catching_migrated_2934 = { value_type = "boolean", source = "retired_ball_ban_no_catching" },
          no_catching_migration_reviewed_29313 = { value_type = "boolean", source = "retired_ball_ban_review" },
          route_split_rules_migrated = { value_type = "boolean", source = "legacy_route_split_selectors" },
          route_forgiveness_initialized = { value_type = "boolean", source = "route_forgiveness_initialization" },
          nuzlocke_provenance_initialized = { value_type = "boolean", source = "pokemon_provenance_reconstruction" },
      }) do
          fields[key] = {
              key = key, value_type = row.value_type, required = false,
              role = "migration_bookkeeping", source = row.source,
          }
      end

      local SaveSchemaDescriptor = {}
      SaveSchemaDescriptor.version = CURRENT_SAVE_SCHEMA
      SaveSchemaDescriptor.descriptor_api = 1
      SaveSchemaDescriptor.coverage = "configuration_and_schema_control"
      SaveSchemaDescriptor.complete_gameplay_state = false
      function SaveSchemaDescriptor.describe()
          return {
              descriptor_api = SaveSchemaDescriptor.descriptor_api,
              save_schema = CURRENT_SAVE_SCHEMA,
              coverage = SaveSchemaDescriptor.coverage,
              complete_gameplay_state = false,
              fields = copyTable(fields),
          }
      end
      function SaveSchemaDescriptor.audit()
          local errors = {}
          local configCount, mirrorCount, legacyCount, bookkeepingCount = 0, 0, 0, 0
          for key, field in pairs(fields) do
              if field.role == "configuration" then configCount = configCount + 1
              elseif field.role == "compatibility_mirror" then mirrorCount = mirrorCount + 1
              elseif field.role == "legacy_migration_input" then legacyCount = legacyCount + 1
              elseif field.role == "migration_bookkeeping" then bookkeepingCount = bookkeepingCount + 1 end
              local default = field.default
              if default ~= nil and field.value_type == "number"
                  and type(default) ~= "number" then
                  errors[#errors + 1] = "default_type:" .. tostring(key)
              elseif default ~= nil and field.value_type == "boolean"
                  and type(default) ~= "boolean" then
                  errors[#errors + 1] = "default_type:" .. tostring(key)
              elseif default ~= nil and field.value_type == "string"
                  and type(default) ~= "string" then
                  errors[#errors + 1] = "default_type:" .. tostring(key)
              end
          end
          for _, row in ipairs(rows) do
              if not fields[row.key] then
                  errors[#errors + 1] = "missing_field:" .. row.key
              end
          end
          return {
              ok = #errors == 0,
              save_schema = CURRENT_SAVE_SCHEMA,
              total_field_count = configCount + mirrorCount + legacyCount + bookkeepingCount + 2,
              configuration_count = configCount,
              compatibility_mirror_count = mirrorCount,
              legacy_input_count = legacyCount,
              migration_bookkeeping_count = bookkeepingCount,
              errors = errors,
          }
      end
      mod.exports.__beta26.saveSchemaDescriptor = SaveSchemaDescriptor
  end

  -- Machine-readable lineage.  Filename/version labels are not authoritative
  -- on their own; CI and Dev Mode can bind this build to its exact immediate
  -- parent package hash before it is promoted as the next canonical child.
  mod.exports.__beta26.buildProvenance = function()
      return {
          descriptor_api = 1,
          version = mod.exports.__beta26.build,
          parent_version = mod.exports.__beta26.parentVersion,
          parent_sha256 = mod.exports.__beta26.parentSha256,
          save_schema = CURRENT_SAVE_SCHEMA,
          compatibility_api = mod.exports.__beta26.compatibilityApi,
          diagnostics_api = mod.exports.__beta26.diagnosticsApi,
          mod_api = 2,
          audited_recomp = mod.exports.__beta26.recompCompatAudited,
          player_package_files = 15,
      }
  end
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.build_provenance =
          mod.exports.__beta26.buildProvenance
  end

  -- 29.3.13 default audit: new restrictive systems default OFF, economy and
  -- difficulty remain vanilla, and the conventional Nuzlocke core remains the
  -- only challenge behavior enabled by default. Keep this pure for smoke tests.
  mod.exports.__beta26.auditNewRuleDefaults = function()
      local expected = {
          type_lock_mode = 0, no_day_care = false, shiny_clause = 0,
          gym_lock_in = false, dungeon_lock_in = false,
          travel_restrictions = 0, party_size_limit = 6, gym_team_size = false,
          route_forgiveness = 0, trainer_money_multiplier = 4,
          difficulty_profile = 0, randomizer_info_policy = 0,
          badge_boosts = true, no_catching = false,
          no_held_items = false,
          player_start_stat_exp = 0, wild_start_stat_exp = 0,
          trainer_start_stat_exp = 0,
          pc_starting_vitamins = false, pc_starting_heal_items = false, random_starter = false,
          skip_opening_intro = false, quick_nuzlocke_start = false,
          skip_cherrygrove_tour = false, encounter_spend_indicator = true,
          encounter_ball_limit = 0,
          dev_mode = false,
      }
      for key, value in pairs(expected) do
          if defaultRuleValue(key) ~= value then return false, key end
      end
      return true
  end

  -- Numeric setup/profile values can be supplied by old saves or external
  -- editing tools. Keep NaN/Inf from surviving normalization and later
  -- becoming invalid persisted Lua-source values. This boundary guard is
  -- intentionally narrow; ordinary gameplay math remains unchanged.
  mod.exports.__beta26.finiteNumber = function(value, fallback)
      local number = tonumber(value)
      if number == nil or number ~= number
          or number == math.huge or number == -math.huge then
          return fallback
      end
      return number
  end

  local function normalizeRuleValue(rule, value)
      if type(rule) ~= "table" then return value end

      if rule.numeric then
          -- Old Dupes Clause saves used a boolean. Preserve ON as FAMILY,
          -- which matches the behavior those saves previously had.
          if rule.key == "dupes_mode" and type(value) == "boolean" then
              value = value and 2 or 0
          elseif rule.key == "shiny_clause" and type(value) == "boolean" then
              -- 2.4.20 migration: historical ON meant unlimited shiny exceptions.
              value = value and 4 or 0
          elseif (rule.key == "gold_egg_encounter_mode"
              or rule.key == "gold_bug_contest_mode")
              and type(value) == "boolean" then
              -- Older builds could collapse these enum rows through the
              -- shared boolean setter. Preserve true as the first enabled
              -- mode rather than silently resetting it OFF.
              value = value and 1 or 0
          end

          local fallback = mod.exports.__beta26.finiteNumber(
              defaultRuleValue(rule.key), nil)
              or mod.exports.__beta26.finiteNumber(rule.min, 0)
          local number = math.floor(mod.exports.__beta26.finiteNumber(value, fallback))
          local minValue = mod.exports.__beta26.finiteNumber(rule.min, nil)
          local maxValue = mod.exports.__beta26.finiteNumber(rule.max, nil)
          if minValue then number = math.max(minValue, number) end
          if maxValue then number = math.min(maxValue, number) end
          return number
      end

      return value == true
  end

  local function legacyLevelCapScope()
      local hardcore = mod.save:get("hardcore_mode", false) == true
      if not hardcore then return 0 end
      return mod.save:get("elite_four_caps", false) == true and 2 or 1
  end

  -- 2.5.4: Solo Only is retired. Party Size Limit now owns Solo runs.
  -- Preserve old saves by converting Solo=true to a one-Pokemon cap.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "solo_to_party_limit_254", function()
          local legacySolo = mod.save:get("solo_active", nil)
          if legacySolo == true then
              local limit = tonumber(mod.save:get("party_size_limit", 6)) or 6
              if limit > 1 then mod.save:set("party_size_limit", 1) end
          end
          return true
      end)

  -- 2.4.98 numeric selector setter repair. 2.4.97 and earlier could
  -- write booleans when Shiny Clause or Encounter Ball Limit was edited
  -- because those numeric keys fell through setConfigValue's boolean branch.
  -- The exact attempted selection is not recoverable from `false`, so use the
  -- conservative canonical OFF value and let the player reselect explicitly.
  -- `true` for Shiny Clause retains its historical UNLIMITED meaning; there
  -- was never a defined boolean-true Encounter Ball Limit, so it also becomes
  -- OFF rather than guessing a throw budget.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "selector_boolean_repair_2498", function()
          local shiny = mod.save:get("shiny_clause", nil)
          if type(shiny) == "boolean" then
              mod.save:set("shiny_clause", shiny and 4 or 0)
          end
          local ballLimit = mod.save:get("encounter_ball_limit", nil)
          if type(ballLimit) == "boolean" then
              mod.save:set("encounter_ball_limit", 0)
          end
          return true
      end)

  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "legacy_level_cap_scope", function()
          -- Older saves stored two booleans instead of the unified scope. Only
          -- materialize the new key when legacy evidence actually exists;
          -- fresh/vanilla saves keep their normal default path.
          local oldHardcore = mod.save:get("hardcore_mode", nil)
          local oldElite = mod.save:get("elite_four_caps", nil)
          if mod.save:get("level_cap_scope", nil) == nil
              and (oldHardcore ~= nil or oldElite ~= nil) then
              mod.save:set("level_cap_scope", legacyLevelCapScope())
          end
          return true
      end)

  -- 2.4.84 legacy enum canonicalization.
  --
  -- Several old rule rows were booleans before becoming numeric selectors.
  -- Runtime readers already understood those booleans, but leaving the raw
  -- value in storage meant an old save could repeatedly project back to its
  -- legacy state after an edit. Canonicalize the unambiguous legacy shapes
  -- once through the central semantic migration pipeline.
  mod.exports.__beta26.registerSaveUpgradeStep("semantic",
      "legacy_numeric_rule_shapes_2484", function()
          local conversions = {
              shiny_clause = function(v) return v and 4 or 0 end,
              dupes_mode = function(v) return v and 2 or 0 end,
              gold_egg_encounter_mode = function(v) return v and 1 or 0 end,
              gold_bug_contest_mode = function(v) return v and 1 or 0 end,
          }
          for key, convert in pairs(conversions) do
              local raw = mod.save:get(key, nil)
              if type(raw) == "boolean" then
                  mod.save:set(key, convert(raw))
              end
          end
          -- Historical starting Rare Candies was also boolean. It is a setup
          -- resource selector rather than an ordinary rule toggle, but its
          -- old shape is equally unambiguous and safe to canonicalize.
          local oldCandies = mod.save:get("starting_rare_candies", nil)
          if type(oldCandies) == "boolean" then
              mod.save:set("starting_rare_candies", oldCandies and 99 or 0)
          end
          return true
      end)

  -- 2.3.20 translation-tooling seam:
  -- Rule/section source strings are already marked with Strings.source().
  -- Expose the live definitions so translation tooling can discover them
  -- without maintaining a duplicate catalog that drifts as rules evolve.
  mod.exports.nuzlocke_translation.sources = function()
      local seen, out = {}, {}
      local function add(value, kind, key)
          if type(value) ~= "string" or value == "" or seen[value] then return end
          seen[value] = true
          out[#out + 1] = { source = value, kind = kind, key = key }
      end
      for _, category in ipairs(ruleCategories) do
          add(category.title, "section", nil)
          add(category.shortTitle, "section_short", nil)
          for _, rule in ipairs(category.rules or {}) do
              add(rule.name, "rule_name", rule.key)
              add(rule.shortName, "rule_short_name", rule.key)
              add(rule.desc, "rule_description", rule.key)
          end
      end
      table.sort(out, function(a, b)
          if tostring(a.kind) == tostring(b.kind) then
              return tostring(a.source) < tostring(b.source)
          end
          return tostring(a.kind) < tostring(b.kind)
      end)
      return out
  end

  mod.exports.nuzlocke_translation.catalog = function()
      local out = {}
      for _, row in ipairs(mod.exports.nuzlocke_translation.sources()) do
          out[row.source] = Strings.lookup(row.source)
      end
      return out
  end

  local function makeDefaultPreGameRules()
      local values = {}
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              values[rule.key] = defaultRuleValue(rule.key)
          end
      end
      values.locke_type = defaultRuleValue("locke_type")
      values.starting_money = defaultRuleValue("starting_money")
      values.starting_pokeballs = defaultRuleValue("starting_pokeballs")
      values.starting_rare_candies = defaultRuleValue("starting_rare_candies")
      values.infinite_rare_candies = defaultRuleValue("infinite_rare_candies")
      values.difficulty_provider_id = "vanilla"
      return values
  end

  local function makeRulesFromCurrentSave()
      local values = makeDefaultPreGameRules()
      local liveTypeDraft = mod.save:get("type_lock_draft", false) == true

      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local raw = mod.save:get(rule.key, nil)
              if rule.key == "level_cap_scope" and raw == nil then
                  raw = legacyLevelCapScope()
              elseif raw == nil and (rule.key == "route_2_split"
                  or rule.key == "route_10_split"
                  or rule.key == "route_20_split") then
                  -- Old setup/save data had one blanket Route Splits flag.
                  -- Preserve its intent for the three routes that remain
                  -- independently supported; every other old split collapses
                  -- safely to its parent during encounter reprojection.
                  raw = mod.save:get("route_splits", 0) == 1
              end
              if raw == nil and liveTypeDraft and mod.exports.__beta26.typeLockSlotIndex(rule.key) then
                  values[rule.key] = nil
              else
                  if raw == nil then raw = defaultRuleValue(rule.key) end
                  values[rule.key] = normalizeRuleValue(rule, raw)
              end
          end
      end

      values.locke_type = math.max(0, math.min(5,
          math.floor(mod.exports.__beta26.finiteNumber(
              mod.save:get("locke_type", defaultRuleValue("locke_type")),
              defaultRuleValue("locke_type")))))
      values.area_guide_enabled = loadAreaGuideState()
      values.rule_lock =
          mod.save:get("rule_lock", defaultRuleValue("rule_lock")) == true
      values.rules_locked =
          mod.save:get("rules_locked", defaultRuleValue("rules_locked")) == true
      values.infinite_rare_candies =
          mod.save:get("infinite_rare_candies",
              defaultRuleValue("infinite_rare_candies")) == true
      local storedDifficultyId = mod.save:get("difficulty_provider_id", nil)
      values.difficulty_provider_id = type(storedDifficultyId) == "string"
          and storedDifficultyId ~= "" and storedDifficultyId or nil

      return values
  end

  local function routeListShowsAll()
      return areaGuideEnabled == true
  end

  ---------------------------------------------------------------------
  -- COMMIT STAGED NEW-GAME RULES
  --
  -- NEW GAME is identified by the explicit staging flag set by the title
  -- menu. Do not inspect whether mod.save already contains rule keys: the
  -- engine may populate defaults before save.loaded, which can otherwise
  -- make valid startup selections look like they were never chosen.
  --
  -- The helper runs from BOTH save.loaded and game.ready. Whichever lifecycle
  -- event sees the staged flag first commits it; the other event simply
  -- mirrors the now-authoritative save.
  ---------------------------------------------------------------------
  local function copyRuleProfile(source)
      local copy = {}
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local v = source and source[rule.key]
              if v == nil and source and (rule.key == "route_2_split"
                  or rule.key == "route_10_split"
                  or rule.key == "route_20_split") then
                  v = tonumber(source.route_splits) == 1
              end
              if v == nil and source and source.type_lock_draft == true
                  and mod.exports.__beta26.typeLockSlotIndex(rule.key) then
                  copy[rule.key] = nil
              else
                  if v == nil then v = defaultRuleValue(rule.key) end
                  copy[rule.key] = normalizeRuleValue(rule, v)
              end
          end
      end
      copy.locke_type = math.max(0, math.min(5,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.locke_type, defaultRuleValue("locke_type")))))
      if source and source.area_guide_enabled ~= nil then
          copy.area_guide_enabled = source.area_guide_enabled == true
      else
          copy.area_guide_enabled = defaultRuleValue("area_guide_enabled")
      end
      copy.rule_lock = source and source.rule_lock == true or false
      copy.rules_locked = source and source.rules_locked == true or false
      copy.infinite_rare_candies = source and source.infinite_rare_candies == true
          or defaultRuleValue("infinite_rare_candies")
      local difficultyId = source and source.difficulty_provider_id
      copy.difficulty_provider_id = type(difficultyId) == "string"
          and difficultyId ~= "" and difficultyId or nil
      copy.starting_money = math.max(0, math.min(9999,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.starting_money, defaultRuleValue("starting_money")))))
      copy.starting_pokeballs = math.max(0, math.min(99,
          math.floor(mod.exports.__beta26.finiteNumber(
              source and source.starting_pokeballs, defaultRuleValue("starting_pokeballs")))))
      local rawCandies = source and source.starting_rare_candies
      if type(rawCandies) == "boolean" then rawCandies = rawCandies and 99 or 0 end
      copy.starting_rare_candies = math.max(0, math.min(99,
          math.floor(mod.exports.__beta26.finiteNumber(
              rawCandies, defaultRuleValue("starting_rare_candies")))))
      copy.hardcore_mode = (tonumber(copy.level_cap_scope) or 0) > 0
      copy.elite_four_caps = (tonumber(copy.level_cap_scope) or 0) >= 2
      return copy
  end

  local function serializeSetupValue(v)
      if type(v) == "boolean" then
          return v and "true" or "false"
      elseif type(v) == "number" then
          if mod.exports.__beta26.finiteNumber(v, nil) == nil then return "nil" end
          return tostring(v)
      elseif type(v) == "string" then
          return string.format("%q", v)
      end
      return "nil"
  end

  local function serializeSetupProfile(profile)
      local keys = {}
      for k, _ in pairs(profile or {}) do keys[#keys + 1] = k end
      table.sort(keys)
      local out = { "return {" }
      for _, k in ipairs(keys) do
          out[#out + 1] = "[" .. string.format("%q", k) .. "]="
              .. serializeSetupValue(profile[k]) .. ","
      end
      out[#out + 1] = "}"
      return table.concat(out, "\n")
  end

  -- beta.30.1.5: Gen1Recomp 0.1.86+ blocks the legacy direct
  -- filesystem facade in sandboxed mods. The old Setup profile loader touched
  -- that blocked facade before opening the configuration screen, so the title
  -- SETUP path could crash before any screen-level guard ran.
  --
  -- Compatibility bridge: keep per-generation Setup profile preferences only
  -- for the current process/session. This avoids creating/adopting a
  -- playthrough identity merely by browsing fresh-game Setup at title.
  mod.exports.__beta26.sessionSetupProfiles =
      mod.exports.__beta26.sessionSetupProfiles or {}

  local function saveSetupProfileToDisk(profile)
      local scope = tostring(mod.exports.__beta26.setupProfileScope or "gen1")
      mod.exports.__beta26.sessionSetupProfiles[scope] =
          copyRuleProfile(profile or {})
      return true
  end

  local function loadSetupProfileFromDisk()
      local scope = tostring(mod.exports.__beta26.setupProfileScope or "gen1")
      local profile = mod.exports.__beta26.sessionSetupProfiles[scope]
      if type(profile) ~= "table" then return nil end
      return copyRuleProfile(profile)
  end

  local function persistStagedProfile(profile)
      if not profile then return end
      mod.save:set(stagedProfileKey(), copyRuleProfile(profile))
      mod.save:set(stagedIntentKey(), true)
  end

  local function loadPersistedStagedProfile()
      if mod.save:get(stagedIntentKey(), false) ~= true then
          return nil
      end
      local profile = mod.save:get(stagedProfileKey(), nil)
      if type(profile) ~= "table" then
          return nil
      end
      return copyRuleProfile(profile)
  end

  local function clearPersistedStagedProfile()
      mod.save:set(stagedIntentKey(), false)
      mod.save:set(stagedProfileKey(), nil)
  end

  local function saveCurrentSetupProfile()
      if not pendingNewGameRules then
          pendingNewGameRules = makeDefaultPreGameRules()
      end
      local profile = copyRuleProfile(pendingNewGameRules)
      return saveSetupProfileToDisk(profile)
  end

  local function saveCurrentInGameRules()
      if not pendingNewGameRules then
          pendingNewGameRules = makeRulesFromCurrentSave()
      end

      local profile = copyRuleProfile(pendingNewGameRules)
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              if profile.type_lock_draft == true and mod.exports.__beta26.typeLockSlotIndex(rule.key)
                  and profile[rule.key] == nil then
                  mod.save:set(rule.key, nil)
              else
                  mod.save:set(rule.key, normalizeRuleValue(rule, profile[rule.key]))
              end
          end
      end
      mod.save:set("locke_type", math.max(0, math.min(5,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))))
      saveAreaGuideState(profile.area_guide_enabled == true)
      mod.save:set("rule_lock", profile.rule_lock == true)
      local permanentlyLocked = mod.save:get("rules_permanently_locked", false) == true
      if permanentlyLocked then profile.rules_locked = true end
      mod.save:set("rules_locked", profile.rules_locked == true)
      if profile.rules_locked == true then mod.save:set("rules_permanently_locked", true) end
      mod.save:set("infinite_rare_candies", profile.infinite_rare_candies == true)

      pendingNewGameRules = copyRuleProfile(profile)
      pendingRulesDirty = false
      areaGuideEnabled = profile.area_guide_enabled == true
      return true
  end

  local function stageNewGameProfile()
      -- The durable profile is the preferred source at the NEW GAME boundary.
      -- If the player changed the screen and did not press SAVE, use the live
      -- profile they are looking at; otherwise recover the explicitly saved
      -- profile from disk.
      local saved = loadSetupProfileFromDisk()
      if saved and not pendingRulesDirty then
          pendingNewGameRules = saved
      end
      pendingNewGameRules = copyRuleProfile(pendingNewGameRules or makeDefaultPreGameRules())
      mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
      newGameRulesSnapshot = copyRuleProfile(pendingNewGameRules)
      persistStagedProfile(newGameRulesSnapshot)
      pendingNewGameRulesForNextSave = true
      newGameRulesCommitPending = true
      newGameCommitPassesRemaining = 12
  end

  local function applyNewGameSnapshot()
      if saveSchemaTooNew then
          return false
      end
      if not newGameRulesCommitPending or not newGameRulesSnapshot then
          return false
      end

      local profile = newGameRulesSnapshot
      local allVerified = true

      -- Explicitly write EVERY registered rule, including false values.
      -- This is the critical distinction from relying on missing save keys:
      -- an OFF selection is a real selection, not permission to use defaults.
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local expected
              if profile.type_lock_draft == true and mod.exports.__beta26.typeLockSlotIndex(rule.key)
                  and profile[rule.key] == nil then
                  expected = nil
              else
                  expected = normalizeRuleValue(rule, profile[rule.key])
              end
              mod.save:set(rule.key, expected)
          end
      end

      -- `locke_type` is profile metadata rather than a registered rule row,
      -- so the loop above does not persist it. Write it explicitly before the
      -- verification block below; otherwise a fresh setup can save every owned
      -- rule correctly while retaining an older loadout label (or repeatedly
      -- failing snapshot verification).
      mod.save:set("locke_type", math.max(0, math.min(5,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))))
      saveAreaGuideState(profile.area_guide_enabled == true)
      mod.save:set("rule_lock", profile.rule_lock == true)
      if mod.save:get("rules_permanently_locked", false) == true then profile.rules_locked = true end
      mod.save:set("rules_locked", profile.rules_locked == true)
      if profile.rules_locked == true then mod.save:set("rules_permanently_locked", true) end
      mod.save:set("infinite_rare_candies", profile.infinite_rare_candies == true)
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= "" then
          mod.save:set("difficulty_provider_id", profile.difficulty_provider_id)
      end
      if mod.save:get("route_forgiveness_initialized", false) ~= true then
          local rf = math.floor(tonumber(profile.route_forgiveness) or 0)
          mod.save:set("route_forgiveness_tokens", rf == 2 and 1 or 0)
          mod.save:set("route_forgiveness_initialized", true)
          mod.save:set("route_forgiveness_gym_trainers", {})
      end

      -- Verify against the active save.  Keep the snapshot alive if another
      -- engine initialization pass overwrites it; the next lifecycle pass
      -- will stamp the same snapshot again.
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local expected
              if profile.type_lock_draft == true and mod.exports.__beta26.typeLockSlotIndex(rule.key)
                  and profile[rule.key] == nil then
                  expected = nil
              else
                  expected = normalizeRuleValue(rule, profile[rule.key])
              end
              local actual = mod.save:get(rule.key, nil)
              if actual ~= expected then
                  allVerified = false
              end
          end
      end
      local lockeTypeActual = math.max(0, math.min(5,
          math.floor(tonumber(mod.save:get("locke_type",
              defaultRuleValue("locke_type")))
              or defaultRuleValue("locke_type"))))
      if lockeTypeActual ~= math.max(0, math.min(5,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))) then
          allVerified = false
      end
      local guideActual = mod.save:get("area_guide_enabled", nil)
      if guideActual ~= (profile.area_guide_enabled == true) then
          allVerified = false
      end
      if mod.save:get("rule_lock", nil) ~= (profile.rule_lock == true) then
          allVerified = false
      end
      if mod.save:get("rules_locked", nil) ~= (profile.rules_locked == true) then
          allVerified = false
      end
      local rareCandyActual = mod.save:get("infinite_rare_candies", nil)
      if rareCandyActual ~= (profile.infinite_rare_candies == true) then
          allVerified = false
      end
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= ""
          and mod.save:get("difficulty_provider_id", nil)
              ~= profile.difficulty_provider_id then
          allVerified = false
      end

      if allVerified then
          newGameRulesCommitPending = false
          pendingNewGameRulesForNextSave = false
          pendingRulesDirty = false
          pendingNewGameRules = copyRuleProfile(profile)
          areaGuideEnabled = profile.area_guide_enabled == true
          newGameRulesSnapshot = nil
          newGameCommitPassesRemaining = 0
          clearPersistedStagedProfile()
          return true
      end

      return false
  end

  local function refreshRuleMirrorFromSave()
      -- Do not replace a still-pending new-game profile with the save's
      -- defaults.  That was the source of setup choices such as Level Caps
      -- and No X Items being lost when a fresh save was first loaded.
      if pendingNewGameRulesForNextSave and pendingNewGameRules then
          return
      end
      pendingNewGameRules = makeRulesFromCurrentSave()
      areaGuideEnabled = pendingNewGameRules.area_guide_enabled ~= false
      pendingRulesDirty = false
  end

  local function recoverNewGameSnapshotIfNeeded()
      if newGameRulesCommitPending and newGameRulesSnapshot then
          return true
      end
      local persisted = loadPersistedStagedProfile()
      if persisted then
          newGameRulesSnapshot = persisted
          pendingNewGameRules = copyRuleProfile(persisted)
          pendingNewGameRulesForNextSave = true
          newGameRulesCommitPending = true
          newGameCommitPassesRemaining = math.max(newGameCommitPassesRemaining, 12)
          return true
      end
      return false
  end

  ---------------------------------------------------------------------
  -- DEFINITIVE NEW-GAME COMMIT
  --
  -- RBY exposes intro.oak_speech.finished after its introduction. It remains
  -- a useful RBY commit point. Gold uses the shared intro step-list hook below
  -- after its real post-game.ready save.created event identifies NEW GAME.
  ---------------------------------------------------------------------
  local function commitDurableSetupProfileToActiveSave()
      local profile = loadSetupProfileFromDisk()
      if not profile then return false end

      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              mod.save:set(rule.key, normalizeRuleValue(rule, profile[rule.key]))
          end
      end
      mod.save:set("locke_type", math.max(0, math.min(5,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))))
      saveAreaGuideState(profile.area_guide_enabled == true)
      mod.save:set("rule_lock", profile.rule_lock == true)
      mod.save:set("rules_locked", profile.rules_locked == true)
      mod.save:set("infinite_rare_candies", profile.infinite_rare_candies == true)
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= "" then
          mod.save:set("difficulty_provider_id", profile.difficulty_provider_id)
      end

      local verified = true
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules) do
              local expected = normalizeRuleValue(rule, profile[rule.key])
              if mod.save:get(rule.key, nil) ~= expected then
                  verified = false
                  break
              end
          end
          if not verified then break end
      end
      local durableLockeType = math.max(0, math.min(5,
          math.floor(tonumber(mod.save:get("locke_type",
              defaultRuleValue("locke_type")))
              or defaultRuleValue("locke_type"))))
      if durableLockeType ~= math.max(0, math.min(5,
          math.floor(tonumber(profile.locke_type)
              or defaultRuleValue("locke_type")))) then
          verified = false
      end
      if mod.save:get("area_guide_enabled", nil) ~= (profile.area_guide_enabled == true) then
          verified = false
      end
      if mod.save:get("rule_lock", nil) ~= (profile.rule_lock == true) then
          verified = false
      end
      if mod.save:get("rules_locked", nil) ~= (profile.rules_locked == true) then
          verified = false
      end
      if mod.save:get("infinite_rare_candies", nil) ~= (profile.infinite_rare_candies == true) then
          verified = false
      end
      if type(profile.difficulty_provider_id) == "string"
          and profile.difficulty_provider_id ~= ""
          and mod.save:get("difficulty_provider_id", nil)
              ~= profile.difficulty_provider_id then
          verified = false
      end

      if verified then
          pendingNewGameRules = copyRuleProfile(profile)
          pendingNewGameRulesForNextSave = false
          pendingRulesDirty = false
          areaGuideEnabled = profile.area_guide_enabled == true
          newGameRulesSnapshot = nil
          newGameRulesCommitPending = false
          newGameCommitPassesRemaining = 0
          clearPersistedStagedProfile()
      end
      return verified
  end

  mod.events:on("intro.oak_speech.finished", function()
      local ver = getGameVersion and getGameVersion() or "RED"
      if ver == "RED" or ver == "BLUE" or ver == "YELLOW" then
          commitDurableSetupProfileToActiveSave()
      end
  end)

  mod.events:on("save.loaded", function(ev)
      if ev and ev.save then currentSave = ev.save end
      if recoverNewGameSnapshotIfNeeded() then
          applyNewGameSnapshot()
      else
          refreshRuleMirrorFromSave()
      end
  end)

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      currentGame = game or currentGame
      currentSave = (game and game.save) or currentSave
      if recoverNewGameSnapshotIfNeeded() then
          applyNewGameSnapshot()
      else
          refreshRuleMirrorFromSave()
      end
  end)

  -- A few engine systems initialize save-backed data during the first frames
  -- after game.ready.  Re-apply the immutable NEW GAME snapshot during that
  -- short window.  This is intentionally finite and only runs for a staged
  -- brand-new game; existing saves are never touched.
  mod.events:on("world.stepped", function()
      if recoverNewGameSnapshotIfNeeded() and newGameCommitPassesRemaining > 0 then
          newGameCommitPassesRemaining = newGameCommitPassesRemaining - 1
          applyNewGameSnapshot()
      end
  end)

  ---------------------------------------------------------------------
  -- NEW-GAME DEFAULT NAMES
  --
  -- This deliberately patches the three story-owned naming seams instead of
  -- NamingScreen itself. The shared keyboard is also used for Pokemon, boxes,
  -- and other editable strings; a global shortcut would silently rename them.
  -- Each shortcut writes through the same save fields and continuation the
  -- vanilla screen uses, so Oak's confirmations and Gold's officer script keep
  -- their ordinary order.
  ---------------------------------------------------------------------
  mod.exports.__beta26.quickStartRequested = function(game)
      if saveSchemaTooNew then return false end
      local runtimeGame = game or currentGame or mod.game
      if externalRuleDelegation
          and externalRuleDelegation("quick_nuzlocke_start", runtimeGame) then
          return false
      end
      local save = runtimeGame and runtimeGame.save
      if save and save.nuzlockeQuickStartPending == true then return true end
      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.quick_nuzlocke_start ~= nil then
          return profile.quick_nuzlocke_start == true
      end
      return mod.save:get("quick_nuzlocke_start", false) == true
  end

  mod.exports.__beta26.skipOpeningIntroRequested = function(game)
      if saveSchemaTooNew then return false end
      -- NEW GAME presentation-only shortcut. A dedicated intro provider wins
      -- only this presentation seam; Quick Start may still apply its later
      -- capture-ready progression transaction after that provider finishes.
      if externalRuleDelegation
          and externalRuleDelegation("skip_opening_intro",
              game or currentGame or mod.game) then
          return false
      end
      if mod.exports.__beta26.quickStartRequested(game) then return true end
      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.skip_opening_intro ~= nil then
          return profile.skip_opening_intro == true
      end
      return mod.save:get("skip_opening_intro", false) == true
  end

  local function automaticDefaultNamesEnabled(game)
      if saveSchemaTooNew then return false end
      -- Provider ownership wins over both carried NEW GAME state and dormant
      -- local settings. This mirrors the other non-core delegation seams: the
      -- stored choice can return if the provider leaves, but never double-runs.
      if externalRuleDelegation
          and externalRuleDelegation("automatic_default_names", game or currentGame or mod.game) then
          return false
      end
      if mod.exports.__beta26.quickStartRequested(game) then return true end
      if mod.exports.__beta26.skipOpeningIntroRequested(game) then return true end
      local save = game and game.save
      if save and save.nuzlockeAutomaticDefaultNames == true then return true end

      local profile = newGameRulesSnapshot or pendingNewGameRules
      if profile and profile.automatic_default_names ~= nil then
          return profile.automatic_default_names == true
      end
      return mod.save:get("automatic_default_names", false) == true
  end

  local function rememberAutomaticDefaultNames(game)
      if game and game.save then
          -- Gold's Rival is named hours after Oak's speech. Carry the NEW GAME
          -- choice on the actual save so that later story special does not rely
          -- on title-menu staging state that has correctly been cleared.
          game.save.nuzlockeAutomaticDefaultNames = true
      end
  end

  local function configuredNamePreset(game, who, explicit, fallback)
      if type(explicit) == "table" and type(explicit[1]) == "string"
          and explicit[1] ~= "" then
          return explicit[1]
      end
      local boot = game and game.data and game.data.field
          and game.data.field.boot
      local presets = boot and boot.namePresets and boot.namePresets[who]
      if type(presets) == "table" and type(presets[1]) == "string"
          and presets[1] ~= "" then
          return presets[1]
      end
      return fallback
  end

  -- 2.2.20: Skip Oak's presentation without replacing New Game itself.
  -- Named intro steps are an upstream mod seam. Keep only semantic setup that
  -- must still happen: R/B/Y name writes (resolved invisibly by the existing
  -- Default Names adapter), and Gold's InitClock plus player-name write.
  mod.hooks:wrap("intro.oak_speech.build", function(next, steps, speech)
      local downstream = next(steps, speech)
      if type(downstream) ~= "table" then return downstream end
      local game = speech and speech.game or currentGame or mod.game
      if not mod.exports.__beta26.skipOpeningIntroRequested(game) then return downstream end

      local keep = {}
      local gold = mod.exports.__beta26.runtimeIsGold(game)
      for _, step in ipairs(downstream) do
          local id = type(step) == "table" and step.id or nil
          local wanted = gold
              and (id == "init_clock" or id == "name_player")
              or (not gold and (id == "name_player" or id == "name_rival"))
          if wanted then keep[#keep + 1] = step end
      end
      return keep
  end)

  local function installAutomaticDefaultNameAdapters()
      if mod.exports.__beta26.isSaveEditorSession() then return false end

      local okRby, RbyOak = pcall(require, "src.ui.OakSpeech")
      if okRby and type(RbyOak) == "table"
          and type(RbyOak.runStep) == "function"
          and not (RbyOak.__nuzlockeDefaultNamesOwner == mod
              and RbyOak.runStep == RbyOak.__nuzlockeDefaultNamesFunction) then
          if RbyOak.runStep == RbyOak.__nuzlockeDefaultNamesFunction
              and type(RbyOak.__nuzlockeDefaultNamesPrevious) == "function" then
              RbyOak.runStep = RbyOak.__nuzlockeDefaultNamesPrevious
          end
          local previous = RbyOak.runStep
          local wrapper = function(self, step)
              local game = self and self.game
              if type(step) == "table" and step.kind == "name"
                  and automaticDefaultNamesEnabled(game) then
                  local who = step.who == "rival" and "rival" or "player"
                  local fallback = who == "rival" and "BLUE" or "RED"
                  local name = configuredNamePreset(game, who, step.presets,
                      fallback)
                  if game and game.save then
                      game.save.player = game.save.player or {}
                      if who == "rival" then
                          game.save.player.rival = name
                      else
                          game.save.player.name = name
                      end
                      rememberAutomaticDefaultNames(game)
                  end
                  if type(self.recordAnswer) == "function" then
                      self:recordAnswer(step, 1, name, name)
                  end
                  if type(self.advance) == "function" then self:advance() end
                  return
              end
              return previous(self, step)
          end
          RbyOak.runStep = wrapper
          RbyOak.__nuzlockeDefaultNamesOwner = mod
          RbyOak.__nuzlockeDefaultNamesPrevious = previous
          RbyOak.__nuzlockeDefaultNamesFunction = wrapper
      end

      local okGoldOak, GoldOak = pcall(require, "src.ui.gen2.OakSpeech")
      if okGoldOak and type(GoldOak) == "table"
          and type(GoldOak.openNamePick) == "function"
          and not (GoldOak.__nuzlockeDefaultNamesOwner == mod
              and GoldOak.openNamePick == GoldOak.__nuzlockeDefaultNamesFunction) then
          if GoldOak.openNamePick == GoldOak.__nuzlockeDefaultNamesFunction
              and type(GoldOak.__nuzlockeDefaultNamesPrevious) == "function" then
              GoldOak.openNamePick = GoldOak.__nuzlockeDefaultNamesPrevious
          end
          local previous = GoldOak.openNamePick
          local wrapper = function(self, step)
              local game = self and self.game
              if automaticDefaultNamesEnabled(game) then
                  local name = configuredNamePreset(game, "player",
                      step and step.presets, "GOLD")
                  if game and game.save then
                      game.save.player = game.save.player or {}
                      game.save.player.name = name
                      rememberAutomaticDefaultNames(game)
                  end
                  if type(self.recordAnswer) == "function" then
                      self:recordAnswer(step or {}, 1, name, name)
                  end
                  self.busy = false
                  if type(self.advance) == "function" then self:advance() end
                  return
              end
              return previous(self, step)
          end
          GoldOak.openNamePick = wrapper
          GoldOak.__nuzlockeDefaultNamesOwner = mod
          GoldOak.__nuzlockeDefaultNamesPrevious = previous
          GoldOak.__nuzlockeDefaultNamesFunction = wrapper
      end

      local okWorld, GoldWorld = pcall(require, "src.world.gen2.World")
      if okWorld and type(GoldWorld) == "table"
          and type(GoldWorld.nameRival) == "function"
          and not (GoldWorld.__nuzlockeDefaultNamesOwner == mod
              and GoldWorld.nameRival == GoldWorld.__nuzlockeDefaultNamesFunction) then
          if GoldWorld.nameRival == GoldWorld.__nuzlockeDefaultNamesFunction
              and type(GoldWorld.__nuzlockeDefaultNamesPrevious) == "function" then
              GoldWorld.nameRival = GoldWorld.__nuzlockeDefaultNamesPrevious
          end
          local previous = GoldWorld.nameRival
          local wrapper = function(self, onDone)
              local game = self and self.game
              if automaticDefaultNamesEnabled(game) then
                  local name = "SILVER"
                  if game and game.save then
                      game.save.rival = game.save.rival or {}
                      game.save.rival.name = name
                      rememberAutomaticDefaultNames(game)
                  end
                  if onDone then onDone(name) end
                  return
              end
              return previous(self, onDone)
          end
          GoldWorld.nameRival = wrapper
          GoldWorld.__nuzlockeDefaultNamesOwner = mod
          GoldWorld.__nuzlockeDefaultNamesPrevious = previous
          GoldWorld.__nuzlockeDefaultNamesFunction = wrapper
      end
      return true
  end

  -- 2.3.10: do not import OakSpeech/Gold World modules merely to reach the
  -- title screen. Install on NEW GAME selection below, with game.ready as a
  -- reload/continuation repair point.
  mod.events:on("game.ready", function()
      pcall(installAutomaticDefaultNameAdapters)
  end)

  ---------------------------------------------------------------------
  -- WRITE / TRACKING / ENFORCEMENT POLICY
  ---------------------------------------------------------------------
  -- 2.5.20: these are deliberately separate questions. Passive progression
  -- (Gym/E4/Champion synchronization) is allowed while the player's Nuzlocke
  -- master switch is OFF, but no Nuzlocke-owned persistent state may be changed
  -- when an unsupported newer save schema has forced this build read-only.
  -- Rule consequences additionally require the challenge itself to be enabled.
  mod.exports.__beta26.canWriteNuzlockeSave = function(game)
      return saveSchemaTooNew ~= true and game ~= nil and game.save ~= nil
  end

  mod.exports.__beta26.isNuzlockeEnabled = function()
      return mod.save:get("nuzlocke_enabled", true) ~= false
  end

  mod.exports.__beta26.shouldEnforceNuzlocke = function(game, battle)
      if not mod.exports.__beta26.canWriteNuzlockeSave(game) then
          return false
      end
      if not mod.exports.__beta26.isNuzlockeEnabled() then
          return false
      end
      if battle and (battle.demo or battle.ghost) then
          return false
      end
      return true
  end

  -- Historical/internal callers keep using active(); its meaning is now
  -- explicitly the RULE_ENFORCEMENT policy rather than generic persistence.
  active = function(game, battle)
      return mod.exports.__beta26.shouldEnforceNuzlocke(game, battle)
  end

  ---------------------------------------------------------------------
  -- EVOLUTION LIMITS (2.4.19)
  ---------------------------------------------------------------------
  -- Gen1Recomp exposes evolution.check as the shared R/B/Y + Gold decision
  -- seam. The rule is deliberately independent of Nuzlocke Loadout presets.
  -- NO FINAL blocks only a target confirmed terminal by the live merged data.
  -- Missing/malformed provider data fails open instead of guessing.
  local function evolutionLimitMode()
      return math.max(0, math.min(2, math.floor(tonumber(
          mod.save:get("evolution_limit", defaultRuleValue("evolution_limit"))) or 0)))
  end

  local function evolutionTargetId(evo)
      if type(evo) ~= "table" then return nil end
      local species = evo.species
      if type(species) == "table" then species = species.id or species.key or species.name end
      if species == nil then return nil end
      species = tostring(species):upper()
      return species ~= "" and species or nil
  end

  mod.exports.__beta26.evolutionLimitAllows = function(game, evo, mode)
      mode = math.max(0, math.min(2, math.floor(tonumber(mode) or evolutionLimitMode())))
      if mode <= 0 then return true end
      if mode >= 2 then return false end
      local target = evolutionTargetId(evo)
      local pokemon = game and game.data and game.data.pokemon
      local def = target and type(pokemon) == "table" and pokemon[target] or nil
      if type(def) ~= "table" or type(def.evolutions) ~= "table" then return true end
      local methods = game and game.data and game.data.evolution_methods
      if type(methods) ~= "table" then
          local okEvolution, Evolution = pcall(require, "src.pokemon.Evolution")
          methods = okEvolution and Evolution and Evolution.METHODS or nil
      end
      if type(methods) ~= "table" then return true end
      -- A target is non-terminal only when at least one outgoing evolution is
      -- executable by the final merged method registry. Dormant National-Dex
      -- rows (location/move-count/etc. without a registered method) do not
      -- falsely make a currently terminal species count as non-final.
      for _, nextEvo in ipairs(def.evolutions) do
          local method = type(nextEvo) == "table" and methods[nextEvo.method] or nil
          local nextTarget = evolutionTargetId(nextEvo)
          if type(method) == "table" and type(method.check) == "function"
              and nextTarget and type(pokemon[nextTarget]) == "table" then
              return true
          end
      end
      return false
  end

  if mod.hooks and type(mod.hooks.wrap) == "function" then
      mod.hooks:wrap("evolution.check", function(next, game, mon, evo, trigger)
          local vanilla = next(game, mon, evo, trigger)
          if vanilla ~= true or not active(game) then return vanilla end
          local mode = evolutionLimitMode()
          if mode <= 0 then return vanilla end
          return mod.exports.__beta26.evolutionLimitAllows(game, evo, mode) and vanilla or false
      end, 100)
  end

  mod.exports.__beta26.ruleActive = function(game, key, battle)
      local fallback = defaultRuleValue(key)
      return active(game or currentGame or mod.game, battle)
          and mod.save:get(key, fallback) == true
  end

  -- 2.4.51 GOLD-only No Held Items.
  -- Gold exposes every held-item check through held_item.trigger. Compose with
  -- downstream providers first, then suppress the final effect only for exact
  -- members of the player's battle.party. Enemy/trainer held items remain
  -- native, and the held item value itself is never deleted or rewritten.
  if mod.hooks and type(mod.hooks.wrap) == "function" then
      mod.hooks:wrap("held_item.trigger", function(next, ctx)
          local effect, parameter = next(ctx)
          local game = currentGame or mod.game
          if not mod.exports.__beta26.runtimeIsGold(game)
              or not active(game, type(ctx) == "table" and ctx.battle or nil)
              or mod.save:get("no_held_items", false) ~= true
              or type(ctx) ~= "table" or type(ctx.battle) ~= "table"
              or type(ctx.mon) ~= "table" then
              return effect, parameter
          end

          local party = ctx.battle.party
          if type(party) ~= "table" then return effect, parameter end
          for _, mon in ipairs(party) do
              if mon == ctx.mon then
                  return nil, 0
              end
          end
          return effect, parameter
      end, 1000)
  end

  ---------------------------------------------------------------------
  -- SHARED B-BUTTON RUNNING SHOES
  -- Gen1Recomp exposes the same composable movement.speed hook in R/B/Y and
  -- Gold. Apply the multiplier after downstream mods so no implementation is
  -- replaced, and limit it to player-controlled walking: the generations'
  -- native bike, surf, script, collision, and menu paths remain authoritative.
  ---------------------------------------------------------------------
  mod.hooks:wrap("movement.speed", function(next, frames, ctx)
      local downstream = next(frames, ctx)
      local baseFrames = tonumber(downstream) or tonumber(frames)
      if not baseFrames then return downstream end
      local game = type(ctx) == "table" and ctx.game or currentGame or mod.game
      if (externalRuleDelegation and externalRuleDelegation("automatic_running_shoes", game))
          or mod.save:get("automatic_running_shoes", false) ~= true then
          return downstream
      end
      if type(ctx) ~= "table" or ctx.onBike == true or ctx.surfing == true
          or ctx.scripted == true or ctx.playerControlled == false then
          return downstream
      end
      -- Running Shoes are a hold-to-run feature, never an automatic speed
      -- toggle. Resolve the engine's live mapped input first so controller B
      -- and the user's keyboard binding for the B action behave identically.
      -- Only fall back to the hook context's input object when it is the same
      -- input-style API and no live Game reference was supplied.
      local input = game and game.input or ctx.input
      if not (input and type(input.isDown) == "function"
          and input:isDown("b") == true) then
          return downstream
      end
      return math.max(1, math.floor(baseFrames / 2))
  end)


  ---------------------------------------------------------------------
  -- PUBLIC INTEROP / CAPABILITY API (30.0.0.3)
  --
  -- Stable, capability-first seams for UI replacements, encounter/gift
  -- providers, quest packs, EXP providers, registry consumers, and other
  -- mods.  No FAFF0x mod IDs are required: providers advertise what they do.
  ---------------------------------------------------------------------
  do
      local Interop = { api = 1, providers = {}, listeners = {} }

      local function norm(v)
          return tostring(v or ""):upper():gsub("[^A-Z0-9]+", "_"):gsub("^_+", ""):gsub("_+$", "")
      end

      local function shallowCopy(t)
          local out = {}
          for k, v in pairs(type(t) == "table" and t or {}) do out[k] = v end
          return out
      end

      function Interop.registerProvider(provider)
          if type(provider) ~= "table" then return false, "provider table required" end
          local id = norm(provider.id or provider.name)
          if id == "" then return false, "provider id required" end
          local copy = shallowCopy(provider)
          copy.id = id
          copy.capabilities = shallowCopy(provider.capabilities)
          Interop.providers[id] = copy
          return true, id
      end

      function Interop.unregisterProvider(id)
          id = norm(id)
          local existed = Interop.providers[id] ~= nil
          Interop.providers[id] = nil
          return existed
      end

      function Interop.getProvider(id) return Interop.providers[norm(id)] end

      function Interop.hasCapability(capability)
          capability = norm(capability)
          for _, provider in pairs(Interop.providers) do
              local caps = provider.capabilities or {}
              if caps[capability] == true or caps[capability:lower()] == true then
                  return true, provider
              end
              for k, v in pairs(caps) do
                  if v == true and norm(k) == capability then return true, provider end
              end
          end
          return false, nil
      end

      function Interop.providersWith(capability)
          local out, wanted = {}, norm(capability)
          for _, provider in pairs(Interop.providers) do
              for k, v in pairs(provider.capabilities or {}) do
                  if v == true and norm(k) == wanted then out[#out + 1] = provider break end
              end
          end
          table.sort(out, function(a,b) return tostring(a.id) < tostring(b.id) end)
          return out
      end

      function Interop.resolveCapability(capability)
          local requested = norm(capability)
          local aliases = {
              -- 2.4.2: an alternate Bag/pocket/favorites UI is presentation,
              -- not evidence that the mod owns item effects or challenge
              -- legality. Automatic-use and machine providers remain mechanic
              -- providers because they may initiate use outside the Bag UI.
              ALTERNATE_ITEM_UI="ITEM_PRESENTATION",
              AUTOMATIC_ITEM_USE="ITEM_USE_ENTRYPOINT",
              MACHINE_PROVIDER="MACHINE_MECHANICS",
              ALTERNATE_PC_UI="STORAGE_PROVIDER",
              EXTERNAL_ENCOUNTER_START="ENCOUNTER_PROVIDER",
              ENCOUNTER_SELECTOR="ENCOUNTER_SELECTOR",
              CAPTURE_MECHANICS="CAPTURE_MECHANICS",
              BATTLE_INFORMATION="BATTLE_INFORMATION",
              EXP_DISTRIBUTION="EXP_DISTRIBUTION",
              QUEST_FRAMEWORK="QUEST_FRAMEWORK",
              QUEST_PRESENTATION="QUEST_PRESENTATION",
              QUEST_PROVIDER="QUEST_CONTENT_PROVIDER",
          }
          local canonical = aliases[requested] or requested
          local explicit, automatic = {}, {}
          for _, provider in pairs(Interop.providers) do
              local matched = false
              for k, v in pairs(provider.capabilities or {}) do
                  local key = norm(k)
                  if v == true and (key == requested or key == canonical
                      or (aliases[key] or key) == canonical) then
                      matched = true
                      break
                  end
              end
              if matched then
                  if provider.automatic == true then automatic[#automatic+1]=provider
                  else explicit[#explicit+1]=provider end
              end
          end
          table.sort(explicit, function(a,b) return tostring(a.id)<tostring(b.id) end)
          table.sort(automatic, function(a,b) return tostring(a.id)<tostring(b.id) end)
          return {
              capability=canonical:lower(),
              supplied=(#explicit + #automatic) > 0,
              explicit=explicit,
              automatic=automatic,
              preferred=explicit[1] or automatic[1],
          }
      end

      function Interop.on(topic, fn)
          if type(fn) ~= "function" then return false end
          topic = norm(topic)
          Interop.listeners[topic] = Interop.listeners[topic] or {}
          Interop.listeners[topic][#Interop.listeners[topic] + 1] = fn
          return true
      end

      function Interop.emit(topic, payload)
          topic = norm(topic)
          for _, fn in ipairs(Interop.listeners[topic] or {}) do pcall(fn, payload) end
          if mod.events and mod.events.emit then pcall(mod.events.emit, mod.events, "nuzlocke." .. topic:lower(), payload) end
      end

      local Acquisition = {}
      Acquisition.KINDS = {
          wild=true, gift=true, trade=true, starter=true, scripted=true,
          editor=true, summon=true, quest=true, forced=true, wonder_trade=true,
          trainer_capture=true,
      }
      function Acquisition.classify(context)
          context = type(context) == "table" and context or {}
          local declared = norm(context.kind or context.sourceKind or context.acquisitionType)
          local aliases = {
              WILD="wild", GIFT="gift", TRADE="trade", STARTER="starter",
              SCRIPTED="scripted", EDITOR="editor", SUMMON="summon",
              QUEST="quest", FORCED="forced", WONDER_TRADE="wonder_trade",
              TRAINER_CAPTURE="trainer_capture", TRAINER_CATCH="trainer_capture",
              SNAG="trainer_capture",
          }
          if aliases[declared] then return aliases[declared] end
          if context.editor == true then return "editor" end
          if context.trainerCapture == true or context.trainer_capture == true
              or context.snag == true then return "trainer_capture" end
          if context.quest == true then return "quest" end
          if context.summon == true then return "summon" end
          if context.trade == true then return "trade" end
          if context.gift == true then return "gift" end
          if context.starter == true then return "starter" end
          if context.wild == true or context.encounter == true then return "wild" end
          return "scripted"
      end

      function Acquisition.evaluate(context)
          context = type(context) == "table" and context or {}
          local game = context.game or currentGame or mod.game
          -- Registered quest/content source metadata fills gaps without
          -- requiring provider-specific conditionals.
          if mod.exports.nuzlocke and mod.exports.nuzlocke.content then
              local sourceId = norm(context.sourceId or context.contentId)
              local c = mod.exports.nuzlocke.content
              local meta = sourceId ~= "" and (c.gifts[sourceId] or c.encounters[sourceId]) or nil
              if meta then
                  if not context.kind then context.kind = meta.kind end
                  if not context.species then context.species = meta.species end
                  if not context.areaId then context.areaId = meta.areaId end
                  if meta.repeatable ~= nil and context.repeatable == nil then context.repeatable = meta.repeatable end
              end
          end
          local kind = Acquisition.classify(context)
          local concrete = type(context.mon) == "table" and context.mon
              or (type(context.pokemon) == "table" and context.pokemon or nil)
          local species = tostring(context.species or context.pokemonId or context.id
              or (concrete and concrete.species) or ""):upper()
          local result = { allowed=true, kind=kind, species=species, reason=nil, rule=nil }
          if context.progressionRequired == true and context.allowProgressionException == true then
              result.exempt, result.reason = true, "progression_exception"
              return result
          end
          if kind == "wild" or kind == "summon" or kind == "quest"
              or kind == "trainer_capture" then
              if mod.save:get("no_catching", false) == true and context.captureAttempt == true then
                  result.allowed, result.rule, result.reason = false, "no_catching", "catching_banned"
                  return result
              end
          end
          if (species ~= "" or concrete ~= nil) and mod.exports.__beta26 then
              local evaluator = concrete and mod.exports.__beta26.typeLockAllowsPokemon
                  or mod.exports.__beta26.typeLockAllowsSpecies
              if type(evaluator) == "function" then
                  local ok, allowed = pcall(evaluator, game, concrete or species)
                  if ok and allowed == false then
                      result.allowed, result.rule, result.reason = false, "type_lock", "type_lock"
                      return result
                  end
              end
          end
          if species ~= "" and type(specialAcquisitionDenied) == "function"
              and (kind == "gift" or kind == "trade") then
              local area = context.areaId or context.area or context.location
              local policyKind = kind
              local ok, reason = pcall(specialAcquisitionDenied, game, species, area, policyKind, concrete)
              if ok and reason then
                  result.allowed, result.rule, result.reason = false, reason, reason
                  return result
              end
          end
          return result
      end

      function Acquisition.begin(context)
          local result = Acquisition.evaluate(context)
          Interop.emit("acquisition_evaluated", {context=context, result=result})
          return result
      end

      function Acquisition.commit(context)
          context = type(context) == "table" and context or {}
          local result = Acquisition.evaluate(context)
          if result.allowed then
              Interop.emit("acquisition_committed", {context=context, result=result})
          end
          return result
      end

      local ItemAPI = {}
      function ItemAPI.classify(context)
          context = type(context) == "table" and context or { itemId=context }
          local data = context.data or (context.game and context.game.data) or (currentGame and currentGame.data) or (mod.game and mod.game.data)
          local itemId = context.itemId or context.id or context.item
          if ItemPolicy.isFishingRod(data, itemId) then return "fishing_rod" end
          local id = ItemPolicy.normalize(itemId)
          if ItemPolicy.repels[id] then return "repel" end
          if ItemPolicy.escapeRopes[id] then return "escape_rope" end
          if ItemPolicy.rareCandies[id] then return "rare_candy" end
          if ItemPolicy.xItems[id] then return "battle_item" end
          if ItemPolicy.isBall(data, itemId, context.itemEffects) then return "ball" end
          return "item"
      end

      function ItemAPI.evaluate(context)
          context = type(context) == "table" and context or { itemId=context }
          local game = context.game or currentGame or mod.game
          local data = context.data or (game and game.data)
          local save = context.save or (game and game.save) or currentSave
          local itemId = context.itemId or context.id or context.item
          local target = context.target or context.pokemon or context.mon
          if type(evaluateItemUsePolicy) == "function" then
              local ok, allowed, decision = pcall(evaluateItemUsePolicy,
                  game, data, save, itemId, target, context)
              if ok then
                  if allowed == false then
                      return { allowed=false,
                          rule=decision and (decision.rule or decision.code),
                          reason=decision and (decision.reason or decision.code),
                          code=decision and decision.code,
                          kind=ItemAPI.classify(context), decision=decision }
                  end
                  return { allowed=true, kind=ItemAPI.classify(context),
                      decision=decision }
              end
          end
          return {allowed=true, kind=ItemAPI.classify(context)}
      end

      function ItemAPI.beforeUse(context)
          local result = ItemAPI.evaluate(context)
          Interop.emit("item_use_evaluated", {context=context, result=result})
          return result
      end

      function ItemAPI.canUse(context)
          local result = ItemAPI.beforeUse(context)
          return result.allowed == true, result.rule, result.reason, result
      end

      -- Alternate inventory UIs should call this immediately before invoking
      -- the engine item effect.  The alias names make migration easy for Bag,
      -- shortcut, favorite-item, auto-repel, and similar mods.
      ItemAPI.check = ItemAPI.canUse
      ItemAPI.checkUse = ItemAPI.canUse

      local Registry = { revision = 0 }
      function Registry.effectivePokemon(game) game=game or currentGame or mod.game; return game and game.data and game.data.pokemon or nil end
      function Registry.effectiveEncounters(game)
          game = game or currentGame or mod.game
          local data = game and game.data
          -- The shared engine registry name is `encounters`, but Gold's live
          -- merge target is data.gen2Encounters.  Return the same final table
          -- the generation actually consumes so DexNav/guide/provider clients
          -- never receive a nil Gen 1 alias on a Gold boot (Gen1Recomp 0.2.7
          -- also adds TimeFishGroups/day-night fishing under this target).
          if not data then return nil end
          if mod.exports.__beta26.runtimeIsGold(game) then
              return data.gen2Encounters or data.encounters
          end
          return data.encounters
      end

      -- Gameplay consumers must always use the final composed live encounter
      -- registry. Information/presentation consumers may additionally respect
      -- the run's reveal policy without changing encounter generation.
      function Registry.encounterInformationPolicy(game)
          local randomized = not (externalRuleDelegation
              and externalRuleDelegation("random_encounter_tables", game or currentGame or mod.game))
              and mod.save:get("random_encounter_tables", false) == true
          local mode = math.max(0, math.min(1,
              math.floor(tonumber(mod.save:get("randomizer_info_policy", 0)) or 0)))
          return {
              mode = mode == 1 and "blind" or "open",
              randomized = randomized,
              gameplayRegistry = Registry.effectiveEncounters(game),
              revealRandomizedTables = not randomized or mode == 0,
          }
      end

      function Registry.canRevealEncounterInformation(context)
          context = type(context)=="table" and context or {}
          local policy = Registry.encounterInformationPolicy(context.game)
          if policy.revealRandomizedTables then return true, policy end
          -- Explicitly discovered/owned information may be shown even under a
          -- blind run. Providers can set any of these semantic facts without
          -- exposing the entire hidden table.
          if context.discovered == true or context.encountered == true
              or context.caught == true or context.owned == true then
              return true, policy
          end
          return false, policy
      end

      function Registry.encounterInformation(context)
          context = type(context)=="table" and context or {}
          local allowed, policy = Registry.canRevealEncounterInformation(context)
          return {
              allowed = allowed,
              policy = policy.mode,
              randomized = policy.randomized,
              registry = allowed and policy.gameplayRegistry or nil,
              reason = allowed and nil or "randomized_encounters_undiscovered",
          }
      end

      -- Targeted encounter tools (DexNav, radar, search/summon UIs) are
      -- gameplay selectors, not merely information panels. They must still
      -- use the final live registry, but under BLIND randomized info they
      -- should not deliberately select an undiscovered hidden species.
      --
      -- This is cooperative: providers call this before choosing a target.
      -- Ordinary random encounter generation is never blocked by BLIND INFO.
      function Registry.encounterSelection(context)
          context = type(context)=="table" and context or {}
          local policy = Registry.encounterInformationPolicy(context.game)
          local targeted = context.targeted == true
              or context.targetedSelection == true
              or context.selectSpecies == true
              or context.uncaughtOnly == true
              or context.selector == true

          local discovered = context.discovered == true
              or context.encountered == true
              or context.caught == true
              or context.owned == true

          local allowed = true
          local reason = nil
          if targeted and policy.randomized and policy.mode == "blind"
              and not discovered then
              allowed = false
              reason = "blind_targeted_encounter"
          end

          return {
              allowed = allowed,
              policy = policy.mode,
              randomized = policy.randomized,
              targeted = targeted,
              registry = allowed and policy.gameplayRegistry or nil,
              reason = reason,
              fallback = allowed and nil or "random_encounter",
          }
      end

      function Registry.canSelectEncounter(context)
          local result = Registry.encounterSelection(context)
          return result.allowed == true, result
      end

      function Registry.effectiveMoves(game) game=game or currentGame or mod.game; return game and game.data and game.data.moves or nil end
      function Registry.effectiveLearnset(species, game)
          local p = Registry.effectivePokemon(game)
          local def = p and p[tostring(species or ""):upper()]
          if type(def) ~= "table" then return nil end
          return { level1Moves=def.level1Moves, learnset=def.learnset }
      end
      function Registry.changed(kind, game, source)
          Registry.revision = Registry.revision + 1
          Interop.emit("registry_changed", {kind=kind or "all", revision=Registry.revision, game=game or currentGame or mod.game, source=source or "nuzlocke"})
      end
      function Registry.getRevision() return Registry.revision end
      function Registry.describe(game)
          game = game or currentGame or mod.game
          return {
              revision=Registry.revision,
              pokemon=game and game.data and game.data.pokemon or nil,
              encounters=Registry.effectiveEncounters(game),
              moves=game and game.data and game.data.moves or nil,
              randomEncounters=(not (externalRuleDelegation and externalRuleDelegation("random_encounter_tables", currentGame or mod.game)) and mod.save:get("random_encounter_tables", false) == true),
              randomLearnsets=(not (externalRuleDelegation and externalRuleDelegation("random_learnsets", currentGame or mod.game)) and mod.save:get("random_learnsets", false) == true),
              encounterInformation=Registry.encounterInformationPolicy(game),
          }
      end

      local Experience = { api = 2 }
      function Experience.getCap(game)
          game = game or currentGame or mod.game
          if mod.exports.__beta26 and mod.exports.__beta26.getNextLevelCapInfo then
              local ok, info = pcall(mod.exports.__beta26.getNextLevelCapInfo, game)
              if ok and type(info) == "table" then return info.level or info.cap, info end
          end
          return nil, nil
      end
      function Experience.capAward(context)
          context = type(context)=="table" and context or {}
          local requested = math.max(0,
              math.floor(tonumber(context.amount or context.gained) or 0))
          -- Rebound after the level-cap helpers enter lexical scope. Early
          -- callers fail open rather than relying on a forward reference.
          return {
              allowed=true, requested=requested, amount=requested,
              overflow=0, owner="pending_cap_policy", mutates=false,
          }
      end
      Experience.evaluateAward = Experience.capAward
      Experience.preflight = Experience.capAward

      local PartyPC = {}
      PartyPC.api = 2

      local function storageAction(value)
          local action = norm(value)
          if action == "WITHDRAW" or action == "DEPOSIT" or action == "RELEASE"
              or action == "SWAP" then return action end
          return action
      end

      function PartyPC.describe(context)
          context = type(context)=="table" and context or {}
          local action = storageAction(context.action or context.kind)
          local incoming = context.incoming or context.toParty
          local outgoing = context.outgoing or context.fromParty
          local mon = context.mon or context.pokemon
          if action == "WITHDRAW" and incoming == nil then incoming = mon end
          if (action == "DEPOSIT" or action == "RELEASE") and outgoing == nil then outgoing = mon end
          if action == "SWAP" then
              incoming = incoming or context.boxMon or context.boxPokemon
              outgoing = outgoing or context.partyMon or context.partyPokemon
          end
          return {
              action=action,
              incoming=incoming,
              outgoing=outgoing,
              source=context.source or context.provider,
              phase=context.phase or "before",
              transactionId=context.transactionId or context.id,
          }
      end

      function PartyPC.evaluate(context)
          context = type(context)=="table" and context or {}
          local tx = PartyPC.describe(context)
          local result = {
              allowed=true, action=tx.action, reason=nil, rule=nil,
              incoming=tx.incoming, outgoing=tx.outgoing,
              transactionId=tx.transactionId,
          }
          -- Challenge legality follows the Pokemon entering the active party,
          -- not the menu verb that moved it.  This makes WITHDRAW and direct
          -- party/box SWAP equivalent for alternate PC implementations.
          if type(tx.incoming)=="table" and tx.incoming.nuzlockeDead == true then
              result.allowed, result.rule, result.reason =
                  false, "death", "dead_pokemon_unusable"
          elseif type(tx.incoming)=="table" and tx.outgoing == nil
              and active(currentGame or mod.game, nil)
              and #(currentSave and currentSave.party or {}) >= math.max(1, math.min(6,
                  math.floor(tonumber(mod.save:get("party_size_limit",
                      defaultRuleValue("party_size_limit"))) or 6))) then
              result.allowed, result.rule, result.reason =
                  false, "party_size_limit", "party_size_limit"
          end
          Interop.emit("pc_action_evaluated", {context=context, transaction=tx, result=result})
          return result
      end

      function PartyPC.can(context)
          local r=PartyPC.evaluate(context); return r.allowed, r.rule, r.reason, r
      end

      function PartyPC.begin(context)
          local tx = PartyPC.describe(context)
          local r = PartyPC.evaluate(context)
          Interop.emit("storage_transaction_begin", {transaction=tx, result=r, context=context})
          return r
      end

      function PartyPC.commit(context)
          local tx = PartyPC.describe(context)
          tx.phase = "after"
          Interop.emit("storage_transaction_commit", {transaction=tx, context=context})
          return true, tx
      end

      -- Aliases use storage terminology so future PC replacements do not need
      -- to pretend they are using the vanilla Bill's-PC menu.
      PartyPC.evaluateTransaction = PartyPC.evaluate
      PartyPC.canTransaction = PartyPC.can

      local EncounterAPI = {}
      function EncounterAPI.evaluate(context)
          context=type(context)=="table" and context or {}
          local copy=shallowCopy(context)
          copy.encounter=true
          if context.source == "dexnav" or context.dexnav == true then copy.kind="wild" end
          if context.source == "summon" or context.summon == true then copy.kind="summon" end

          local targeted = context.targeted == true
              or context.targetedSelection == true
              or context.selectSpecies == true
              or context.uncaughtOnly == true
              or context.selector == true
          if targeted and Registry and type(Registry.encounterSelection) == "function" then
              local selection = Registry.encounterSelection(context)
              if selection.allowed ~= true then
                  return {
                      allowed=false,
                      kind=Acquisition.classify(copy),
                      species=tostring(context.species or ""):upper(),
                      rule="randomizer_info_policy",
                      reason=selection.reason or "blind_targeted_encounter",
                      selection=selection,
                  }
              end
          end

          local result = Acquisition.begin(copy)
          if targeted and Registry and type(Registry.encounterSelection) == "function" then
              result.selection = Registry.encounterSelection(context)
          end
          return result
      end
      EncounterAPI.selection = Registry.encounterSelection
      EncounterAPI.canSelect = Registry.canSelectEncounter

      local Content = {
          areas = {}, dungeons = {}, dungeonMapIndex = {},
          bosses = {}, gifts = {}, encounters = {},
          randomizerEncounterPolicies = {}, randomizerLearnsetPolicies = {},
      }

      local function contentId(value)
          return norm(value)
      end

      function Content.registerArea(def)
          if type(def) ~= "table" then return false, "area table required" end
          local id = contentId(def.id or def.mapId or def.areaId)
          if id == "" then return false, "area id required" end
          local row = shallowCopy(def)
          row.id = id
          row.name = def.name or def.displayName or id
          Content.areas[id] = row
          -- Feed the existing dynamic tracker catalogue rather than creating
          -- a parallel area namespace.
          pcall(registerArea, id, row.name)
          Interop.emit("content_area_registered", row)
          return true, id
      end

      function Content.registerDungeon(def)
          if type(def) ~= "table" then return false, "dungeon table required" end
          local id = contentId(def.id or def.family or def.name)
          if id == "" then return false, "dungeon id required" end
          local row = shallowCopy(def)
          row.id = id
          row.maps = {}
          local maps = def.maps or def.mapIds or {}
          if type(maps) == "string" then maps = { maps } end
          for _, mapId in ipairs(type(maps) == "table" and maps or {}) do
              local key = contentId(mapId)
              if key ~= "" then
                  row.maps[#row.maps + 1] = key
                  Content.dungeonMapIndex[key] = id
                  Content.registerArea({id=key, name=(def.mapNames and def.mapNames[mapId]) or key,
                      dungeon=id, provider=def.provider})
              end
          end
          Content.dungeons[id] = row
          Interop.emit("content_dungeon_registered", row)
          return true, id
      end

      function Content.dungeonFamily(mapId)
          return Content.dungeonMapIndex[contentId(mapId)]
      end

      function Content.registerBoss(def)
          if type(def) ~= "table" then return false, "boss table required" end
          local id = contentId(def.id or def.name or def.trainerId)
          if id == "" then return false, "boss id required" end
          local row = shallowCopy(def)
          row.id = id
          row.mapId = contentId(def.mapId or def.areaId)
          Content.bosses[id] = row
          Interop.emit("content_boss_registered", row)
          return true, id
      end

      function Content.registerGift(def)
          if type(def) ~= "table" then return false, "gift table required" end
          local id = contentId(def.id or def.sourceId or ((def.species or "GIFT") .. "_" .. (def.mapId or def.areaId or "")))
          if id == "" then return false, "gift id required" end
          local row = shallowCopy(def)
          row.id = id
          row.species = def.species and tostring(def.species):upper() or nil
          row.areaId = contentId(def.areaId or def.mapId)
          row.kind = def.kind or "quest"
          Content.gifts[id] = row
          if row.areaId ~= "" then Content.registerArea({id=row.areaId, name=def.areaName or row.areaId, provider=def.provider}) end
          Interop.emit("content_gift_registered", row)
          return true, id
      end

      function Content.registerEncounter(def)
          if type(def) ~= "table" then return false, "encounter table required" end
          local id = contentId(def.id or def.sourceId or ((def.species or "ENCOUNTER") .. "_" .. (def.mapId or def.areaId or "")))
          if id == "" then return false, "encounter id required" end
          local row = shallowCopy(def)
          row.id = id
          row.species = def.species and tostring(def.species):upper() or nil
          row.areaId = contentId(def.areaId or def.mapId)
          row.kind = def.kind or "quest"
          if def.repeatable == true then row.repeatable = true end
          if def.randomizable == false then row.randomizable = false end
          Content.encounters[id] = row
          if row.areaId ~= "" then Content.registerArea({id=row.areaId, name=def.areaName or row.areaId, provider=def.provider}) end
          Interop.emit("content_encounter_registered", row)
          return true, id
      end

      function Content.setEncounterRandomizerPolicy(id, policy)
          id = contentId(id)
          if id == "" then return false end
          Content.randomizerEncounterPolicies[id] = policy
          return true
      end

      function Content.setLearnsetRandomizerPolicy(species, policy)
          species = tostring(species or ""):upper()
          if species == "" then return false end
          Content.randomizerLearnsetPolicies[species] = policy
          return true
      end

      function Content.shouldRandomizeEncounter(context)
          context = type(context) == "table" and context or {}
          if context.randomizable == false then return false, "record_opt_out" end
          local sourceId = contentId(context.sourceId or context.id)
          local policy = sourceId ~= "" and Content.randomizerEncounterPolicies[sourceId] or nil
          if policy == false or policy == "preserve" or policy == "story" then return false, "provider_policy" end
          local mapId = contentId(context.mapId or context.areaId)
          for _, encounter in pairs(Content.encounters) do
              if encounter.randomizable == false
                  and (sourceId ~= "" and encounter.id == sourceId
                      or mapId ~= "" and encounter.areaId == mapId
                          and (not encounter.species or encounter.species == tostring(context.species or ""):upper())) then
                  return false, "content_opt_out"
              end
          end
          return true
      end

      function Content.shouldRandomizeLearnset(species, def)
          species = tostring(species or ""):upper()
          if type(def) == "table" and def.nuzlockeRandomizable == false then return false, "record_opt_out" end
          local policy = Content.randomizerLearnsetPolicies[species]
          if policy == false or policy == "preserve" or policy == "story" then return false, "provider_policy" end
          return true
      end

      function Content.describe()
          return {
              areas=Content.areas, dungeons=Content.dungeons, bosses=Content.bosses,
              gifts=Content.gifts, encounters=Content.encounters,
          }
      end

      -- A convenience provider bundle for quest/content mods. This is the
      -- preferred integration point for FAFF0x-style quest packs: one call
      -- can register dynamic maps, dungeons, bosses, gifts and encounters.
      function Content.registerBundle(bundle)
          if type(bundle) ~= "table" then return false, "bundle table required" end
          local provider = bundle.provider or bundle.id or bundle.name
          local function each(list, fn)
              if type(list) == "table" then
                  for _, def in pairs(list) do
                      if type(def) == "table" then
                          local row = shallowCopy(def)
                          row.provider = row.provider or provider
                          fn(row)
                      end
                  end
              end
          end
          each(bundle.areas, Content.registerArea)
          each(bundle.dungeons, Content.registerDungeon)
          each(bundle.bosses, Content.registerBoss)
          each(bundle.gifts, Content.registerGift)
          each(bundle.encounters, Content.registerEncounter)
          if type(bundle.randomizerEncounterPolicies) == "table" then
              for id, policy in pairs(bundle.randomizerEncounterPolicies) do
                  Content.setEncounterRandomizerPolicy(id, policy)
              end
          end
          if type(bundle.randomizerLearnsetPolicies) == "table" then
              for species, policy in pairs(bundle.randomizerLearnsetPolicies) do
                  Content.setLearnsetRandomizerPolicy(species, policy)
              end
          end
          Interop.emit("content_bundle_registered", {provider=provider})
          return true
      end

      local AutoCompat = {
          api = 1, detected = {}, adapters = {}, lastParty = {}, lastPC = {},
          lastArea = nil,
          -- Canonical behavior capabilities used by automatic adapters.
          -- Aliases below remain accepted for older integrations.
          capabilityAliases = {
              ALTERNATE_ITEM_UI = "item_presentation",
              AUTOMATIC_ITEM_USE = "item_use_entrypoint",
              ALTERNATE_PC_UI = "storage_provider",
              EXTERNAL_ENCOUNTER_START = "encounter_provider",
              ENCOUNTER_SELECTOR = "encounter_selector",
              CAPTURE_MECHANICS = "capture_mechanics",
              BATTLE_INFORMATION = "battle_information",
              REGISTRY_CONSUMER = "registry_consumer",
              EXP_DISTRIBUTION = "exp_distribution",
              QUEST_FRAMEWORK = "quest_framework",
              QUEST_PRESENTATION = "quest_presentation",
              QUEST_PROVIDER = "quest_content_provider",
              MACHINE_PROVIDER = "machine_mechanics",
          },
      }

      local function activeMods()
          local out = {}
          local function remember(id, info)
              id = norm(id)
              if id == "" then return end
              if out[id] == nil then
                  out[id] = type(info) == "table" and info or { id = id }
              end
          end

          -- 2.4.2: prefer the authoritative Gen1Recomp loaded-mod graph.
          -- This prevents disabled/removed mods from lingering as phantom
          -- automatic providers when an old global compatibility table is stale.
          local game = currentGame or mod.game
          local loader = game and game.mods
          if loader and type(loader.status) == "function" then
              local okStatus, status = pcall(function() return loader:status() end)
              if okStatus and type(status) == "table"
                  and type(status.loaded) == "table" then
                  for _, manifest in ipairs(status.loaded) do
                      if type(manifest) == "table" and manifest.id then
                          local okFind, found = pcall(mod.find, manifest.id)
                          remember(manifest.id, okFind and found or manifest)
                      end
                  end
              end
          end

          -- Older runtimes/fallback adapters may only expose these tables.
          local sources = {
              rawget(_G, "mods"), rawget(_G, "activeMods"),
              mod and mod.mods, mod and mod.activeMods,
          }
          for _, source in ipairs(sources) do
              if type(source) == "table" then
                  for k, v in pairs(source) do
                      if type(v) == "table" then
                          remember(v.id or v.name or k, v)
                      elseif v == true then
                          remember(k, { id = k })
                      end
                  end
              end
          end
          return out
      end

      local function canonicalCapability(name)
          local key = norm(name)
          return AutoCompat.capabilityAliases[key] or key:lower()
      end

      local function addCapability(caps, name)
          caps[name] = true
          caps[canonicalCapability(name)] = true
      end

      local function detectCapabilities(id)
          local caps = {}
          -- These are behavior-family hints, not enforcement branches. They
          -- allow current released mods that predate our API to be described
          -- until they adopt provider registration themselves.
          --
          -- 2.4.97: activeMods() normalizes existing separators but cannot
          -- infer word boundaries in compact IDs such as CatchHelper. Match
          -- both separated and joined spellings for every multi-word hint.
          local function has(separated, joined)
              if id:find(separated, 1, true) then return true end
              return joined ~= nil and id:find(joined, 1, true) ~= nil
          end

          if id:find("BAG",1,true) then addCapability(caps, "alternate_item_ui") end
          if has("ITEM_SHORTCUT", "ITEMSHORTCUT") or id:find("REPEL",1,true) then
              addCapability(caps, "automatic_item_use")
          end
          if id:find("BOX",1,true) or id:find("PC",1,true) then addCapability(caps, "alternate_pc_ui") end
          if id:find("DEXNAV",1,true) or id:find("SUMMON",1,true) then
              addCapability(caps, "external_encounter_start")
          end
          if id:find("DEXNAV",1,true) or id:find("SUMMON",1,true) then
              -- DexNav chooses from a live registry; Summon chooses an
              -- explicit species. Both are targeted encounter selectors.
              addCapability(caps, "encounter_selector")
          end
          if has("CATCH_HELPER", "CATCHHELPER") then
              -- Current Catch Helper both presents catch information and
              -- intentionally retunes Ultra Ball capture math.
              addCapability(caps, "capture_mechanics")
              addCapability(caps, "battle_information")
          end
          if id == "OVERWORLD_WILD_SPAWNS"
              or id == "OVERWORLDWILDSPAWNS" then
              addCapability(caps, "external_encounter_start")
              addCapability(caps, "capture_mechanics")
          end
          if id == "MODERN_PARTY_UI"
              or id == "MODERNPARTYUI" then
              addCapability(caps, "party_presentation")
          end
          if id == "KANTO_ASCENDANT"
              or id == "KANTO-ASCENDANT"
              or id == "KANTOASCENDANT" then
              -- Kanto Ascendant 6.5.4 owns badge-phased trainer/wild
              -- difficulty and additional Trainer Card presentation.
              -- Classify those surfaces explicitly so Nuzlocke can compose
              -- instead of stacking its own difficulty transforms.
              addCapability(caps, "difficulty")
              addCapability(caps, "trainer_levels")
              addCapability(caps, "wild_levels")
              addCapability(caps, "trainer_card_presentation")
          end
          if id:find("POKEDEX",1,true) or has("MOVES_MANAGER", "MOVESMANAGER") then addCapability(caps, "registry_consumer") end
          if has("EXP_SHARE", "EXPSHARE") then addCapability(caps, "exp_distribution") end
          if has("QUEST_SYSTEM", "QUESTSYSTEM") then
              addCapability(caps, "quest_framework")
              addCapability(caps, "quest_presentation")
          elseif id:find("QUEST",1,true) then
              addCapability(caps, "quest_provider")
          end
          if has("REUSABLE_MACHINE", "REUSABLEMACHINE") or id:find("TM",1,true) then addCapability(caps, "machine_provider") end
          if id:find("RANDOMIZER",1,true) then addCapability(caps, "randomizer_provider") end
          if has("LEVEL_CAP", "LEVELCAP") then addCapability(caps, "level_cap_provider") end
          if has("RUNNING_SHOE", "RUNNINGSHOE") then addCapability(caps, "running_shoes_provider") end
          if id:find("SNAG",1,true) then addCapability(caps, "trainer_capture_provider") end
          if id:find("BALL",1,true) then addCapability(caps, "custom_ball_provider") end
          return caps
      end

      function AutoCompat.scan()
          -- Automatic legacy adapters are a fresh projection of the active
          -- mod graph. Never let a provider that was disabled/removed remain
          -- registered and keep a Nuzlocke control delegated.
          for id, provider in pairs(Interop.providers) do
              if type(provider) == "table" and provider.automatic == true
                  and provider.source == "legacy_adapter" then
                  Interop.providers[id] = nil
              end
          end
          AutoCompat.detected = {}
          local mods = activeMods()
          for id, info in pairs(mods) do
              if id ~= norm(mod.id or mod.name or "NUZLOCKE") and not Interop.getProvider(id) then
                  local caps = detectCapabilities(id)
                  local any = false; for _, v in pairs(caps) do if v then any=true break end end
                  if any then
                      Interop.registerProvider({id=id, name=info.name or id,
                          capabilities=caps, automatic=true, source="legacy_adapter"})
                      AutoCompat.detected[id] = caps
                  end
              end
          end
          return AutoCompat.detected
      end

      local function pokemonIdentityLite(mon)
          if type(mon) ~= "table" then return nil end
          if mod.exports.__beta26 and mod.exports.__beta26.Identity
              and mod.exports.__beta26.Identity.pokemonIdentity then
              local ok, id = pcall(mod.exports.__beta26.Identity.pokemonIdentity, mon)
              if ok and id then return tostring(id) end
          end
          return tostring(mon.id or mon.personality or mon.uid or "") .. ":" .. tostring(mon.species or "")
      end

      local function collectMons(game)
          local out = {}
          local save = game and game.save
          for _, mon in ipairs(save and save.party or {}) do out[#out+1]=mon end
          for _, box in pairs(save and save.boxes or {}) do
              if type(box)=="table" then
                  for _, mon in pairs(box) do
                      if type(mon)=="table" and mon.species then out[#out+1]=mon end
                  end
              end
          end
          return out
      end

      function AutoCompat.snapshotPokemon(game)
          game=game or currentGame or mod.game
          local snap={}
          for _, mon in ipairs(collectMons(game)) do
              local id=pokemonIdentityLite(mon)
              if id and id ~= ":" then snap[id]={mon=mon,species=mon.species} end
          end
          return snap
      end

      function AutoCompat.reconcilePokemon(game, sourceHint)
          game=game or currentGame or mod.game
          local now=AutoCompat.snapshotPokemon(game)
          local before=AutoCompat.lastParty
          for id, row in pairs(now) do
              if not before[id] then
                  local mon=row.mon
                  local ctx={game=game, pokemon=mon, species=mon and mon.species,
                      sourceId=sourceHint, kind=(sourceHint and "quest" or "scripted"),
                      areaId=(game and game.map and (game.map.id or game.map.name))}
                  local result=Acquisition.begin(ctx)
                  Interop.emit("legacy_acquisition_detected", {context=ctx,result=result,mon=mon})
              end
          end
          AutoCompat.lastParty=now
          return now
      end


      -- 2.4.11: Wilds of Kanto 2.1.7 can complete an overworld Ball catch
      -- without entering the engine's normal battle-capture lifecycle.  Its
      -- public exports expose the live catching object and GameCompat facade,
      -- so compose at those exported seams instead of patching Wilds files.
      --
      -- Pre-commit: convert a successful overworld wobble into a normal escape
      -- when Nuzlocke capture policy rejects the target.  The consumed Ball is
      -- refunded, matching the native denied-Ball path, and Wilds keeps the
      -- entity alive/aggro-capable through its own failure resolver.
      --
      -- Post-commit: emit the standard pokemon.caught event after Wilds has
      -- successfully placed the Pokemon in party/box.  This reuses Nuzlocke's
      -- proven tracker/provenance listener instead of duplicating tracker code.
      function AutoCompat.installWildsOfKanto()
          local okFind, wilds = pcall(mod.find, "overworld_wild_spawns")
          if not okFind or type(wilds) ~= "table"
              or type(wilds.exports) ~= "table" then
              return false, "not_loaded"
          end
          local exports = wilds.exports
          local catching = exports.catching
          local gameCompat = exports.gameCompat
          if type(catching) ~= "table" or type(catching._resolveCapture) ~= "function"
              or type(gameCompat) ~= "table"
              or type(gameCompat.giveCaughtPokemon) ~= "function" then
              return false, "unsupported_surface"
          end

          local prior = catching.__nuzlockeCompat2411
          if type(prior) == "table" and prior.owner == mod
              and catching._resolveCapture == prior.resolveWrapper
              and gameCompat.giveCaughtPokemon == prior.giveWrapper then
              return true
          end
          if type(prior) == "table" then
              if catching._resolveCapture == prior.resolveWrapper
                  and type(prior.previousResolve) == "function" then
                  catching._resolveCapture = prior.previousResolve
              end
              if gameCompat.giveCaughtPokemon == prior.giveWrapper
                  and type(prior.previousGive) == "function" then
                  gameCompat.giveCaughtPokemon = prior.previousGive
              end
          end

          local previousResolve = catching._resolveCapture
          local previousGive = gameCompat.giveCaughtPokemon

          local function syntheticBattle(game, cap, mon)
              local enemyMon = mon or {
                  species = cap and cap.species,
                  shiny = cap and cap.entity and cap.entity.shiny,
                  variant = cap and cap.entity and cap.entity.variant,
                  level = cap and cap.level,
              }
              return {
                  game = game,
                  wild = true,
                  overworld = true,
                  isOverworld = true,
                  overworldEncounter = true,
                  source = "overworld",
                  encounterType = "overworld",
                  nuzlockeEncounterMethod = "overworld",
                  enemy = { mon = enemyMon },
              }
          end

          local resolveWrapper
          resolveWrapper = function(self, game, ow, caught)
              if caught == true and active(game, nil)
                  and type(catchDeniedReason) == "function" then
                  local cap = self and self.activeCapture
                  local species = cap and cap.species
                  local battle = syntheticBattle(game, cap)
                  local okPolicy, reason = pcall(catchDeniedReason,
                      game, battle, species)
                  if okPolicy and reason then
                      if self and type(self._refundBall) == "function"
                          and cap and cap.ballType then
                          pcall(self._refundBall, self, game, cap.ballType)
                      end
                      if self and self.hud
                          and type(self.hud.showFeedback) == "function" then
                          pcall(self.hud.showFeedback, self.hud,
                              "NUZLOCKE!", 0.85)
                      end
                      return previousResolve(self, game, ow, false)
                  end
              end
              return previousResolve(self, game, ow, caught)
          end

          local giveWrapper
          giveWrapper = function(game, mon, context)
              local result = previousGive(game, mon, context)
              if type(mon) == "table" and active(game, nil)
                  and type(result) == "table"
                  and (result.destination == "party"
                      or result.destination == "box") then
                  local cap = catching and catching.activeCapture
                  local battle = syntheticBattle(game, cap, mon)
                  -- Provider provenance is attached before the normal listener
                  -- runs so Catch Info/Tracker retain the actual acquisition
                  -- source even though no BattleState owned this catch.
                  mon.nuzlockeEncounterSource = "provider"
                  mon.nuzlockeEncounterProvider = "overworld_wild_spawns"
                  mon.nuzlockeEncounterProviderVersion =
                      tostring(exports.version or "")
                  if mod.events and type(mod.events.emit) == "function" then
                      pcall(mod.events.emit, mod.events, "pokemon.caught", {
                          game = game,
                          battle = battle,
                          mon = mon,
                          species = mon.species
                              or (context and context.species),
                          source = "overworld_wild_spawns",
                          ball = cap and cap.ballType,
                      })
                  end
              end
              return result
          end

          catching._resolveCapture = resolveWrapper
          gameCompat.giveCaughtPokemon = giveWrapper
          catching.__nuzlockeCompat2411 = {
              owner = mod,
              previousResolve = previousResolve,
              previousGive = previousGive,
              resolveWrapper = resolveWrapper,
              giveWrapper = giveWrapper,
              providerVersion = tostring(exports.version or ""),
          }
          return true
      end

      -- Modern Party UI intentionally preserves the engine party controller and
      -- owns presentation records only.  Record that relationship explicitly;
      -- no controller monkey-patch is necessary or desirable.
      function AutoCompat.noteModernPartyUI()
          local okFind, partyUI = pcall(mod.find, "modern_party_ui")
          if not okFind or type(partyUI) ~= "table" then return false end
          local provider = Interop.getProvider("MODERN_PARTY_UI")
          if not provider then
              Interop.registerProvider({
                  id = "MODERN_PARTY_UI",
                  name = "Modern Party UI",
                  capabilities = { party_presentation = true },
                  automatic = true,
                  source = "audited_adapter",
              })
          end
          return true
      end

      -- 2.4.12: Kanto Ascendant 6.5.4 explicitly owns its
      -- badge-phased difficulty curve and expanded Trainer Card presentation.
      -- Registration is metadata/composition only: do not patch Ascendant's
      -- trainer.party, encounter.species, randomizer, follower, or storage code.
      function AutoCompat.noteKantoAscendant()
          local ids = {
              "kanto_ascendant",
              "kanto-ascendant",
              "kantoascendant",
          }
          local found = nil
          for _, id in ipairs(ids) do
              local okFind, candidate = pcall(mod.find, id)
              if okFind and type(candidate) == "table" then
                  found = candidate
                  break
              end
          end
          if not found then return false end

          local provider = Interop.getProvider("KANTO_ASCENDANT")
          if not provider then
              Interop.registerProvider({
                  id = "KANTO_ASCENDANT",
                  name = "Kanto Ascendant",
                  capabilities = {
                      difficulty = true,
                      trainer_levels = true,
                      wild_levels = true,
                      trainer_card_presentation = true,
                  },
                  automatic = true,
                  source = "audited_adapter",
                  version = "6.5.4",
              })
          end
          return true
      end

      function AutoCompat.beforeExternalItemUse(context)
          return ItemAPI.beforeUse(context)
      end

      function AutoCompat.beforeExternalEncounter(context)
          context=type(context)=="table" and context or {}
          if not context.kind then
              local source=norm(context.source or context.sourceId)
              context.kind=source:find("SUMMON",1,true) and "summon" or "wild"
          end
          return EncounterAPI.evaluate(context)
      end

      function AutoCompat.beforeExternalPCAction(context)
          return PartyPC.evaluate(context)
      end

      function AutoCompat.registrySnapshot(game)
          return Registry.describe(game)
      end

      function AutoCompat.install()
          AutoCompat.scan()
          AutoCompat.lastParty=AutoCompat.snapshotPokemon(currentGame or mod.game)
          Interop.emit("legacy_adapters_ready", {detected=AutoCompat.detected})
          return true
      end

      -- Re-scan after the mod graph is authoritative. Reconciliation is
      -- deliberately observational: it never deletes an externally granted
      -- Pokémon. It emits provenance/policy information so existing recovery
      -- and provider paths can classify it safely instead of crashing or
      -- silently pretending it was a vanilla catch.
      mod.events:on("mods.loaded", function()
          pcall(AutoCompat.install)
          pcall(AutoCompat.installWildsOfKanto)
          pcall(AutoCompat.noteModernPartyUI)
          pcall(AutoCompat.noteKantoAscendant)
      end)
      mod.events:on("game.ready", function(ev)
          local game=type(ev)=="table" and ev.game or ev
          pcall(AutoCompat.install)
          pcall(AutoCompat.installWildsOfKanto)
          pcall(AutoCompat.noteModernPartyUI)
          pcall(AutoCompat.noteKantoAscendant)
          pcall(AutoCompat.reconcilePokemon, game or currentGame or mod.game)
      end)
      mod.events:on("save.loaded", function()
          pcall(AutoCompat.install)
          pcall(AutoCompat.installWildsOfKanto)
          pcall(AutoCompat.noteModernPartyUI)
          pcall(AutoCompat.noteKantoAscendant)
          pcall(AutoCompat.reconcilePokemon, currentGame or mod.game)
      end)

      mod.exports.nuzlocke = mod.exports.nuzlocke or {}
      mod.exports.nuzlocke.api = 1
      mod.exports.nuzlocke.build = mod.exports.__beta26.build
      mod.exports.nuzlocke.interop = Interop
      mod.exports.nuzlocke.ownership = {
          -- External providers may own mechanics/presentation; Nuzlocke
          -- remains the challenge-policy authority unless a selected rule
          -- explicitly delegates that policy.
          item_presentation="provider",
          item_use_entrypoint="provider",
          item_mechanics="provider",
          machine_mechanics="provider",
          item_policy="nuzlocke",
          encounter_mechanics="provider",
          encounter_selection="provider",
          encounter_policy="nuzlocke",
          capture_mechanics="provider",
          capture_policy="nuzlocke",
          battle_information="provider",
          quest_framework="provider",
          quest_presentation="provider",
          quest_content="provider",
          quest_reward_policy="source_mod",
          storage_mechanics="provider",
          exp_distribution="provider",
          exp_cap_policy="nuzlocke",
          challenge_policy="nuzlocke",
          provenance="nuzlocke",
      }
      mod.exports.nuzlocke.capabilities = {
          acquisition_policy=true, item_policy=true, effective_registry=true,
          registry_notifications=true, provider_registration=true,
          exp_post_distribution_seam=true, pc_policy=true,
          storage_transaction_policy=true, storage_swap_policy=true,
          encounter_entry_policy=true, encounter_information_policy=true,
          encounter_selection_policy=true, encounter_spend_indicator=true,
          final_encounter_registry=true,
          capture_mechanics=true, capture_policy=true, battle_information=true,
          quest_framework=true, quest_presentation=true, quest_content=true,
          alternate_item_ui=true,
          item_presentation=true, item_use_entrypoint=true,
          machine_mechanics=true, exp_distribution=true, exp_cap_policy=true,
          registry_revision=true, content_provider=true,
          dynamic_areas=true, dynamic_dungeons=true, quest_acquisitions=true,
          custom_boss_metadata=true, randomizer_opt_out=true,
          legacy_auto_adapter=true, passive_acquisition_detection=true,
      }
      mod.exports.nuzlocke.acquisitionPolicy = Acquisition
      mod.exports.nuzlocke.itemPolicy = ItemAPI
      mod.exports.nuzlocke.registry = Registry
      mod.exports.nuzlocke.experience = Experience
      mod.exports.nuzlocke.pcPolicy = PartyPC
      mod.exports.nuzlocke.encounterPolicy = EncounterAPI
      mod.exports.nuzlocke.content = Content
      mod.exports.nuzlocke.autoCompat = AutoCompat
      mod.exports.nuzlocke.delegation = {
          api = 1,
          statusForRule = function(key, game)
              return externalRuleDelegation and externalRuleDelegation(key, game) or nil
          end,
          rules = function() return NON_CORE_DELEGATION or {} end,
      }
      mod.exports.registerNuzlockeProvider = Interop.registerProvider
      -- Compatibility aliases for consumers written against the older
      -- nuzlocke_compat export. Keep these additive and read-only.
      if mod.exports.nuzlocke_compat then
          mod.exports.nuzlocke_compat.interop = mod.exports.nuzlocke
          mod.exports.nuzlocke_compat.evaluateItemUse = ItemAPI.evaluate
          mod.exports.nuzlocke_compat.evaluateAcquisition = Acquisition.evaluate
          mod.exports.nuzlocke_compat.effectiveRegistries = Registry.describe
          mod.exports.nuzlocke_compat.evaluateStorageTransaction = PartyPC.evaluate
          mod.exports.nuzlocke_compat.encounterInformation = Registry.encounterInformation
          mod.exports.nuzlocke_compat.encounterSelection = Registry.encounterSelection
          mod.exports.nuzlocke_compat.canSelectEncounter = Registry.canSelectEncounter
          mod.exports.nuzlocke_compat.encounterSpendIndicator =
              function(battle)
                  return mod.exports.__beta26.encounterSpendIndicator
                      and mod.exports.__beta26.encounterSpendIndicator(battle)
                      or nil
              end
          mod.exports.nuzlocke_compat.content = Content
          mod.exports.nuzlocke_compat.registerContentBundle = Content.registerBundle
          mod.exports.nuzlocke_compat.autoCompat = AutoCompat
          mod.exports.nuzlocke_compat.scanCompatibility = AutoCompat.scan
          mod.exports.nuzlocke_compat.resolveCapability = Interop.resolveCapability
      end
  end

  ---------------------------------------------------------------------
  -- TABLE / LEARNSET RANDOMIZERS (30.0.0.1)
  --
  -- These transform only the live merged registries and keep a pristine
  -- snapshot of the fields they own. This makes toggling reversible and lets
  -- upstream/provider registry composition happen first. Random choices are
  -- persisted by semantic slot key so reloads do not silently reroll a run.
  ---------------------------------------------------------------------
  do
      local Randomizer = {
          encounterSnapshot = nil,
          learnsetSnapshot = nil,
          encounterRegistry = nil,
          learnsetRegistry = nil,
      }

      local function copy(value)
          if type(value) ~= "table" then return value end
          local out = {}
          for k, v in pairs(value) do out[k] = copy(v) end
          return out
      end

      Randomizer.algorithmVersion = 1

      local function seedHash(text)
          local value = 5381
          text = tostring(text or "")
          for i = 1, #text do
              value = (value * 33 + text:byte(i)) % 2147483647
          end
          return value
      end

      local function entropySeed()
          local rng = love and love.math and love.math.random or math.random
          local ok, value = pcall(rng, 1, 99999999)
          if ok and tonumber(value) and tonumber(value) > 0 then
              return math.floor(tonumber(value))
          end
          local now = os and os.time and os.time() or 1
          return 1 + (seedHash(tostring(now) .. ":NUZLOCKE") % 99999999)
      end

      mod.exports.__beta26.randomizerSeed = function(profile, create)
          local value
          if type(profile) == "table" then
              value = tonumber(profile.randomizer_seed) or 0
          else
              value = tonumber(mod.save:get("randomizer_seed", 0)) or 0
          end
          value = math.max(0, math.min(99999999, math.floor(value)))
          if value == 0 and create == true then
              value = entropySeed()
              if type(profile) == "table" then
                  profile.randomizer_seed = value
              else
                  mod.save:set("randomizer_seed", value)
              end
          end
          return value
      end

      mod.exports.__beta26.randomizerAlgorithmVersion = function()
          return Randomizer.algorithmVersion
      end

      local function seededIndex(stream, slot, count)
          if count <= 1 then return 1 end
          local seed = mod.exports.__beta26.randomizerSeed(nil, true)
          if seed <= 0 then
              local rng = love and love.math and love.math.random or math.random
              return rng(1, count)
          end
          local value = seedHash(table.concat({
              tostring(Randomizer.algorithmVersion), tostring(seed),
              tostring(stream or "RNG"), tostring(slot or "")
          }, ":"))
          return 1 + (value % count)
      end

      -- Cross-phase consumers must use an exported helper rather than reaching
      -- for this block's local seededIndex/Randomizer names. Lua resolves an
      -- out-of-scope local as a global at runtime, which is exactly how the
      -- 2.5.22 starter regression escaped compile-only validation.
      mod.exports.__beta26.randomizerSeededIndex = seededIndex

      mod.exports.__beta26.randomSpeciesGeneration = function(def)
          if type(def) ~= "table" then return nil end
          local explicit = tonumber(def.generation or def.gen)
          if explicit and explicit >= 1 then return math.floor(explicit) end
          local index = tonumber(def.index or def.dex or def.dexNumber or def.number)
          if not index then return nil end
          if index >= 1 and index <= 151 then return 1 end
          if index >= 152 and index <= 251 then return 2 end
          if index >= 252 and index <= 386 then return 3 end
          return nil
      end

      mod.exports.__beta26.randomSpeciesPoolAllows = function(def, mode)
          mode = math.max(0, math.min(3, math.floor(tonumber(mode) or 0)))
          if mode == 0 then return true end
          local generation = mod.exports.__beta26.randomSpeciesGeneration(def)
          if mode == 1 then return generation == 1 end
          if mode == 2 then return generation == 2 end
          return generation == 1 or generation == 2
      end

      local function effectiveRandomSpeciesGeneration()
          if mod.save:get("random_encounter_tables", false) ~= true then
              return 0
          end
          return math.max(0, math.min(3, math.floor(tonumber(
              mod.save:get("random_species_generation", 0)) or 0)))
      end

      local function effectiveRandomLearnsetGeneration()
          if mod.save:get("random_learnsets", false) ~= true then
              return 0
          end
          return math.max(0, math.min(2, math.floor(tonumber(
              mod.save:get("random_learnset_generation", 0)) or 0)))
      end

      mod.exports.__beta26.effectiveRandomSpeciesGeneration =
          effectiveRandomSpeciesGeneration
      mod.exports.__beta26.effectiveRandomLearnsetGeneration =
          effectiveRandomLearnsetGeneration

      mod.exports.__beta26.randomEncounterRuntimeSafe = function(game, species, level)
          species = tostring(species or ""):upper()
          level = math.max(1, math.floor(tonumber(level) or 5))
          local data = game and game.data
          local def = data and data.pokemon and data.pokemon[species]
          if type(def) ~= "table" or type(def.name) ~= "string" or def.name == ""
              or type(def.baseStats) ~= "table" or type(def.types) ~= "table" then
              return false
          end
          if mod.exports.__beta26.runtimeIsGold(game) then
              if type(def.levelMoves) ~= "table" or type(def.evolutions) ~= "table"
                  or def.growthRate == nil or tonumber(def.catchRate) == nil
                  or tonumber(def.baseExp) == nil
                  or type(def.spriteFront) ~= "string" or def.spriteFront == ""
                  or type(def.spriteBack) ~= "string" or def.spriteBack == "" then
                  return false
              end
              local required = { "hp", "attack", "defense", "speed",
                  "specialAttack", "specialDefense" }
              for _, key in ipairs(required) do
                  if tonumber(def.baseStats[key]) == nil then return false end
              end
              for _, entry in ipairs(def.levelMoves) do
                  if type(entry) ~= "table" or tonumber(entry.level) == nil
                      or entry.move == nil then return false end
                  if tonumber(entry.level) <= level then
                      local move = data.moves and data.moves[entry.move]
                      if type(move) ~= "table" or tonumber(move.pp) == nil
                          or type(move.name) ~= "string" then return false end
                  end
              end
              return true
          end
          return type(mod.exports.__beta26.randomStarterRuntimeSafe) ~= "function"
              or mod.exports.__beta26.randomStarterRuntimeSafe(game, species, level)
      end

      local function speciesPool(game)
          local out = {}
          local mode = effectiveRandomSpeciesGeneration()
          for id, def in pairs(game and game.data and game.data.pokemon or {}) do
              local species = tostring(id or ""):upper()
              local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
              if species ~= "" and species ~= "EGG" and species ~= "NONE"
                  and type(def) == "table" and not glitch.isGlitch
                  and mod.exports.__beta26.randomSpeciesPoolAllows(def, mode)
                  and mod.exports.__beta26.randomEncounterRuntimeSafe(game, species, 5)
                  and (type(specialAcquisitionDenied) ~= "function"
                      or specialAcquisitionDenied(game, species, nil, "random_encounter") == nil) then
                  out[#out + 1] = species
              end
          end
          table.sort(out)
          return out
      end

      local function movePool(game, generation)
          local out = {}
          generation = math.max(0, math.min(2, math.floor(tonumber(generation) or 0)))
          for id, def in pairs(game and game.data and game.data.moves or {}) do
              if type(def) == "table" then
                  local index = tonumber(def.index or def.id or def.number)
                  local allowed = generation == 0
                      or (generation == 1 and index and index >= 1 and index <= 165)
                      or (generation == 2 and index and index >= 166 and index <= 251)
                  local key = tostring(id or ""):upper()
                  if allowed and key ~= "" and key ~= "NONE"
                      and key ~= "NO_MOVE" and key ~= "STRUGGLE" then
                      out[#out + 1] = key
                  end
              end
          end
          table.sort(out)
          return out
      end

      local function persistedMap(key)
          local value = mod.save:get(key, {})
          return type(value) == "table" and value or {}
      end

      local function stableChoice(key, slot, pool, valid, stream, scope)
          if #pool == 0 then return nil end
          local map = persistedMap(key)
          local seed = mod.exports.__beta26.randomizerSeed(nil, true)
          local scoped = seed > 0 and table.concat({
              "v" .. tostring(Randomizer.algorithmVersion),
              "s" .. tostring(seed), tostring(scope or "default"), tostring(slot)
          }, ":") or tostring(slot)
          local saved = tostring(map[scoped] or ""):upper()
          if saved ~= "" and (not valid or valid(saved)) then return saved end

          -- Preserve pre-seed randomizer results on upgraded runs. Copy a
          -- still-valid legacy slot into the new scoped namespace once rather
          -- than silently rerolling the player's existing world. Fresh runs do
          -- not have this unscoped entry and are fully seed-reproducible.
          local legacy = tostring(map[slot] or ""):upper()
          local legacyMarker = "__legacy_adopted:" .. tostring(slot)
          if map[legacyMarker] ~= true and legacy ~= "" and map[scoped] == nil
              and (not valid or valid(legacy)) then
              map[scoped] = legacy
              map[legacyMarker] = true
              mod.save:set(key, map)
              return legacy
          end

          local choice = pool[seededIndex(stream, scoped, #pool)]
          map[scoped] = choice
          mod.save:set(key, map)
          return choice
      end

      local function evolutionShape(game)
          local pokemon = game and game.data and game.data.pokemon or {}
          local incoming, children = {}, {}
          for species, def in pairs(pokemon) do
              species = tostring(species or ""):upper()
              children[species] = children[species] or {}
              for _, evo in ipairs(type(def) == "table" and def.evolutions or {}) do
                  local target = type(evo) == "table" and tostring(evo.species or ""):upper() or ""
                  if target ~= "" and type(pokemon[target]) == "table" then
                      children[species][#children[species] + 1] = target
                      incoming[target] = (incoming[target] or 0) + 1
                  end
              end
          end
          local function stage(species)
              species = tostring(species or ""):upper()
              local hasParent = (incoming[species] or 0) > 0
              local hasChild = children[species] and #children[species] > 0
              if not hasParent and not hasChild then return "single" end
              if not hasParent then return "base" end
              if hasChild then return "middle" end
              return "final"
          end
          local function threeStageBase(species)
              species = tostring(species or ""):upper()
              if (incoming[species] or 0) > 0 then return false end
              for _, child in ipairs(children[species] or {}) do
                  if children[child] and #children[child] > 0 then return true end
              end
              return false
          end
          return stage, threeStageBase
      end

      local function similarBstPool(game, original, pool)
          local base = mod.exports.__beta26.getSpeciesBST(game, original)
          if not base then return {} end
          local tolerance = math.max(25, math.floor(base * 0.15 + 0.5))
          local out = {}
          for _, species in ipairs(pool) do
              local bst = mod.exports.__beta26.getSpeciesBST(game, species)
              if bst and math.abs(bst - base) <= tolerance then
                  out[#out + 1] = species
              end
          end
          return out
      end

      local function liveEncounterRegistry(game)
          if not (game and game.data) then return nil end
          if mod.exports.__beta26.runtimeIsGold(game) then
              return game.data.gen2Encounters or game.data.encounters
          end
          return game.data.encounters
      end

      local function restoreEncounterRegistry(game)
          local registry = liveEncounterRegistry(game)
          if Randomizer.encounterSnapshot and Randomizer.encounterRegistry
              and registry == Randomizer.encounterRegistry then
              for k in pairs(registry) do registry[k] = nil end
              for k, v in pairs(Randomizer.encounterSnapshot) do
                  registry[k] = copy(v)
              end
          end
      end

      local function snapshotEncounters(game)
          local registry = liveEncounterRegistry(game)
          if type(registry) ~= "table" then return false end
          if Randomizer.encounterRegistry ~= registry then
              Randomizer.encounterRegistry = registry
              Randomizer.encounterSnapshot = copy(registry)
          end
          return true
      end

      local function randomizeEncounterNode(game, node, path, pool, pokemon)
          if type(node) ~= "table" then return end
          if type(node.species) == "string" then
              local allow = true
              if mod.exports.nuzlocke and mod.exports.nuzlocke.content then
                  local ok, permitted = pcall(mod.exports.nuzlocke.content.shouldRandomizeEncounter, {
                      id=node.nuzlockeSourceId or node.sourceId,
                      sourceId=node.nuzlockeSourceId or node.sourceId,
                      mapId=node.mapId or node.areaId,
                      species=node.species,
                      randomizable=node.nuzlockeRandomizable ~= nil
                          and node.nuzlockeRandomizable or node.randomizable,
                      path=path,
                  })
                  if ok and permitted == false then allow = false end
              end
              if allow then
                  local slot = path .. ".species"
                  local original = tostring(node.species or ""):upper()
                  local balance = math.max(0, math.min(3, math.floor(tonumber(
                      mod.save:get("random_encounter_balance", 0)) or 0)))
                  local generation = effectiveRandomSpeciesGeneration()
                  local candidates = pool
                  if balance > 0 then
                      local byBst = similarBstPool(game, original, pool)
                      local stage = evolutionShape(game)
                      local originalStage = stage(original)
                      local byStage = {}
                      for _, species in ipairs(pool) do
                          if stage(species) == originalStage then
                              byStage[#byStage + 1] = species
                          end
                      end
                      if balance == 1 then
                          if #byBst > 0 then candidates = byBst end
                      elseif balance == 2 then
                          if #byStage > 0 then candidates = byStage end
                      else
                          local both = {}
                          local stageSet = {}
                          for _, species in ipairs(byStage) do stageSet[species] = true end
                          for _, species in ipairs(byBst) do
                              if stageSet[species] then both[#both + 1] = species end
                          end
                          if #both > 0 then
                              candidates = both
                          elseif #byStage > 0 then
                              candidates = byStage
                          elseif #byBst > 0 then
                              candidates = byBst
                          end
                      end
                  end
                  local scope = "b" .. tostring(balance) .. ".g" .. tostring(generation)
                  local choice = stableChoice("__nuzlocke_random_encounter_slots",
                      slot, candidates, function(id)
                          if type(pokemon[id]) ~= "table" then return false end
                          for _, candidate in ipairs(candidates) do
                              if candidate == id then return true end
                          end
                          return false
                      end, "ENCOUNTERS", scope)
                  if choice then node.species = choice end
              end
          end
          local keys = {}
          for k, v in pairs(node) do
              if k ~= "species" and type(v) == "table" then keys[#keys + 1] = k end
          end
          table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
          for _, k in ipairs(keys) do
              randomizeEncounterNode(game, node[k], path .. "." .. tostring(k),
                  pool, pokemon)
          end
      end

      function Randomizer.applyEncounters(game)
          if saveSchemaTooNew then return false end
          game = game or currentGame or mod.game
          local delegated = externalRuleDelegation
              and externalRuleDelegation("random_encounter_tables", game)
          if delegated then
              -- Do not repaint a snapshot over an externally owned randomizer.
              -- If ownership later returns, snapshot the then-authoritative
              -- encounter registry before applying Nuzlocke's pass.
              Randomizer.encounterSnapshot = nil
              Randomizer.encounterRegistry = nil
              return true
          end
          if not snapshotEncounters(game) then return false end
          restoreEncounterRegistry(game)
          if mod.save:get("random_encounter_tables", false) ~= true then return true end
          local pool = speciesPool(game)
          if #pool == 0 then return false end
          randomizeEncounterNode(game, liveEncounterRegistry(game), "encounters",
              pool, game.data.pokemon or {})
          if mod.exports.nuzlocke and mod.exports.nuzlocke.registry then
              mod.exports.nuzlocke.registry.changed("encounters", game, "random_encounters")
          end
          return true
      end

      local function restoreLearnsets(game)
          local pokemon = game and game.data and game.data.pokemon
          if not (Randomizer.learnsetSnapshot and Randomizer.learnsetRegistry
              and pokemon == Randomizer.learnsetRegistry) then return end
          for species, original in pairs(Randomizer.learnsetSnapshot) do
              local def = pokemon[species]
              if type(def) == "table" then
                  def.level1Moves = copy(original.level1Moves)
                  def.learnset = copy(original.learnset)
                  def.levelMoves = copy(original.levelMoves)
              end
          end
      end

      local function snapshotLearnsets(game)
          local pokemon = game and game.data and game.data.pokemon
          if type(pokemon) ~= "table" then return false end
          if Randomizer.learnsetRegistry ~= pokemon then
              Randomizer.learnsetRegistry = pokemon
              Randomizer.learnsetSnapshot = {}
              for species, def in pairs(pokemon) do
                  if type(def) == "table" then
                      Randomizer.learnsetSnapshot[species] = {
                          level1Moves = copy(def.level1Moves or {}),
                          learnset = copy(def.learnset or {}),
                          levelMoves = copy(def.levelMoves or {}),
                      }
                  end
              end
          end
          return true
      end

      function Randomizer.applyLearnsets(game)
          if saveSchemaTooNew then return false end
          game = game or currentGame or mod.game
          local delegated = externalRuleDelegation
              and externalRuleDelegation("random_learnsets", game)
          if delegated then
              -- Provider ownership is provider-agnostic. Once another active
              -- randomizer owns learnsets, Nuzlocke must not restore a stale
              -- snapshot over that registry. Forget local ownership so a later
              -- hand-back snapshots whatever registry is authoritative then.
              Randomizer.learnsetSnapshot = nil
              Randomizer.learnsetRegistry = nil
              return true
          end
          if not snapshotLearnsets(game) then return false end
          restoreLearnsets(game)
          if mod.save:get("random_learnsets", false) ~= true then return true end
          local generation = effectiveRandomLearnsetGeneration()
          local pool = movePool(game, generation)
          -- GEN2 on an R/B/Y registry intentionally fails open: no fake moves.
          if #pool == 0 then return false end
          local moves = game.data.moves or {}
          local speciesIds = {}
          for species in pairs(game.data.pokemon or {}) do speciesIds[#speciesIds + 1] = species end
          table.sort(speciesIds, function(a, b) return tostring(a) < tostring(b) end)
          for _, species in ipairs(speciesIds) do
              local def = game.data.pokemon[species]
              local allowSpecies = type(def) == "table"
              if allowSpecies and mod.exports.nuzlocke and mod.exports.nuzlocke.content then
                  local ok, permitted = pcall(mod.exports.nuzlocke.content.shouldRandomizeLearnset,
                      species, def)
                  if ok and permitted == false then allowSpecies = false end
              end
              if allowSpecies then
                  for i in ipairs(def.level1Moves or {}) do
                      local slot = tostring(species) .. ".level1." .. tostring(i)
                      local choice = stableChoice("__nuzlocke_random_learnset_slots",
                          slot, pool,
                          function(id) return type(moves[id]) == "table" end,
                          "LEARNSETS", "g" .. tostring(generation))
                      if choice then def.level1Moves[i] = choice end
                  end
                  for i, entry in ipairs(def.learnset or {}) do
                      if type(entry) == "table" then
                          local slot = tostring(species) .. ".level." .. tostring(i)
                          local choice = stableChoice("__nuzlocke_random_learnset_slots",
                              slot, pool,
                              function(id) return type(moves[id]) == "table" end,
                              "LEARNSETS", "g" .. tostring(generation))
                          if choice then entry.move = choice end
                      end
                  end
                  -- Gold/Gen2 species use levelMoves rather than the Gen1
                  -- level1Moves/learnset pair. Preserve the level and row count
                  -- exactly; only replace the move id through the same seeded
                  -- LEARNSETS stream. If a provider exposes both shapes, both
                  -- remain deterministic and internally consistent.
                  for i, entry in ipairs(def.levelMoves or {}) do
                      if type(entry) == "table" then
                          local slot = tostring(species) .. ".levelMoves." .. tostring(i)
                          local choice = stableChoice("__nuzlocke_random_learnset_slots",
                              slot, pool,
                              function(id) return type(moves[id]) == "table" end,
                              "LEARNSETS", "g" .. tostring(generation))
                          if choice then entry.move = choice end
                      end
                  end
              end
          end
          if mod.exports.nuzlocke and mod.exports.nuzlocke.registry then
              mod.exports.nuzlocke.registry.changed("learnsets", game, "random_learnsets")
          end
          return true
      end

      function Randomizer.applyAll(game)
          if saveSchemaTooNew then return false end
          game = game or currentGame or mod.game
          Randomizer.applyEncounters(game)
          Randomizer.applyLearnsets(game)
      end

      mod.exports.__beta26.Randomizer = Randomizer
      -- 2.2.10 optional modern Physical/Special Split.  The source table is
      -- intentionally keyed by move id so provider-owned records can keep their
      -- own names/categories unless they use one of the canonical Gen 1/2 ids.
      -- Every other damaging canonical move in 1-251 is physical under the
      -- modern split; status moves retain their engine category unchanged.
      mod.exports.__beta26.MODERN_SPECIAL_MOVES = {
          RAZOR_WIND=true, GUST=true, SONIC_BOOM=true, ACID=true,
          EMBER=true, FLAMETHROWER=true, WATER_GUN=true, HYDRO_PUMP=true,
          SURF=true, ICE_BEAM=true, BLIZZARD=true, PSYBEAM=true,
          BUBBLE_BEAM=true, AURORA_BEAM=true, HYPER_BEAM=true,
          ABSORB=true, MEGA_DRAIN=true, SOLAR_BEAM=true, PETAL_DANCE=true,
          DRAGON_RAGE=true, FIRE_SPIN=true, THUNDER_SHOCK=true,
          THUNDERBOLT=true, THUNDER=true, CONFUSION=true, PSYCHIC=true,
          NIGHT_SHADE=true, SMOG=true, SLUDGE=true, FIRE_BLAST=true,
          SWIFT=true, DREAM_EATER=true, BUBBLE=true, PSYWAVE=true,
          TRI_ATTACK=true, SNORE=true, AEROBLAST=true, POWDER_SNOW=true,
          SLUDGE_BOMB=true, MUD_SLAP=true, OCTAZOOKA=true, ZAP_CANNON=true,
          ICY_WIND=true, GIGA_DRAIN=true, DRAGON_BREATH=true,
          HIDDEN_POWER=true, TWISTER=true, ANCIENT_POWER=true,
          SHADOW_BALL=true, FUTURE_SIGHT=true, WHIRLPOOL=true,
      }

      mod.exports.__beta26.modernMoveCategory = function(move, moveId)
          if type(move) ~= "table" then return nil end
          if move.category == "status" then return "status" end
          -- Only recategorize actual damaging records.  Fixed-damage/special
          -- effect moves retain their engine handling rather than being forced
          -- through the ordinary Attack/Defense formula.
          if (tonumber(move.power) or 0) <= 0 then return move.category end
          local id = tostring(moveId or move.id or ""):upper()
          if id == "" then return move.category end
          if mod.exports.__beta26.MODERN_SPECIAL_MOVES[id] then return "special" end
          local index = tonumber(move.index or move.number or move.id)
          if index and index >= 1 and index <= 251 then return "physical" end
          -- Provider/future-generation moves keep an explicit per-move category
          -- when one exists.  This makes Hoenn/content providers additive.
          return move.category
      end

      mod.hooks:wrap("battle.damage", function(next, ctx)
          if mod.save:get("physical_special_split", false) ~= true
              or type(ctx) ~= "table" or type(ctx.move) ~= "table" then
              return next(ctx)
          end
          local category = mod.exports.__beta26.modernMoveCategory(
              ctx.move, ctx.moveId)
          if category ~= "physical" and category ~= "special" then
              return next(ctx)
          end

          if mod.exports.__beta26.runtimeIsGold(currentGame or mod.game) then
              -- Gold's formula asks its type table for physical/special.  Give
              -- this one calculation a shallow type-record override; never
              -- mutate the shared registry or another mod's move record.
              local opts = ctx.opts
              local moveType = ctx.move.type
              if type(opts) == "table" and moveType ~= nil then
                  local scopedCtx = {}
                  for key, value in pairs(ctx) do scopedCtx[key] = value end
                  local scopedOpts = {}
                  for key, value in pairs(opts) do scopedOpts[key] = value end
                  local originalTypes = opts.types
                  local copiedTypes = {}
                  for key, value in pairs(originalTypes or {}) do
                      copiedTypes[key] = value
                  end
                  local typeRecord = {}
                  for key, value in pairs((originalTypes or {})[moveType] or {}) do
                      typeRecord[key] = value
                  end
                  typeRecord.category = category
                  copiedTypes[moveType] = typeRecord
                  scopedOpts.types = copiedTypes
                  -- hitOnce computed the native screen category before the
                  -- hook. Recompute it only on this copied calculation.
                  if ctx.battle and type(ctx.battle.screenActive) == "function" then
                      scopedOpts.screen = ctx.battle:screenActive(
                          ctx.target, category == "physical")
                  end
                  scopedCtx.opts = scopedOpts
                  return next(scopedCtx)
              end
              return next(ctx)
          end

          -- Gen 1 Damage.compute already gives move.category priority over the
          -- native type category.  Copy the move so the registry stays owned by
          -- the engine/provider and only this damage calculation is changed.
          local move = {}
          for key, value in pairs(ctx.move) do move[key] = value end
          move.category = category
          ctx.move = move
          return next(ctx)
      end)

      mod.exports.randomizer = {
          api = 1,
          build = mod.exports.__beta26.build,
          rngVersion = Randomizer.algorithmVersion,
          seed = function(create) return mod.exports.__beta26.randomizerSeed(nil, create == true) end,
          apply = Randomizer.applyAll,
          applyEncounters = Randomizer.applyEncounters,
          applyLearnsets = Randomizer.applyLearnsets,
      }

      -- Re-apply after provider registries have settled and when a save/game
      -- becomes authoritative. Idempotent snapshots prevent stacking rolls.
      mod.events:on("mods.loaded", function() pcall(Randomizer.applyAll, currentGame or mod.game) end)
      mod.events:on("game.ready", function(ev)
          local game = type(ev) == "table" and ev.game or ev
          pcall(Randomizer.applyAll, game or currentGame or mod.game)
      end)
      mod.events:on("save.loaded", function()
          pcall(Randomizer.applyAll, currentGame or mod.game)
      end)
  end

  ---------------------------------------------------------------------
  -- STARTER-ONLY RANDOMIZER
  -- One choice is persisted per new run so retries/reloads cannot reroll the
  -- starter. Story selection flags deliberately continue to describe the
  -- ball the player chose; this preserves every Rival and progression branch.
  ---------------------------------------------------------------------
  -- A starter candidate has to satisfy more than "there is a pokemon
  -- record".  Pokemon.new consumes growth/base-stat/learnset data, and the
  -- party SummaryMenu immediately dereferences the species types plus every
  -- move definition the new level-5 mon knows.  Compatibility providers may
  -- legitimately expose partial species metadata for BST/type legality; those
  -- records must never enter the concrete starter pool or Yellow can receive a
  -- mon that exists in the registry but crashes as soon as its status page is
  -- opened.
  mod.exports.__beta26.randomStarterRuntimeSafe = function(game, species, level)
      species = tostring(species or ""):upper()
      level = math.max(1, math.floor(tonumber(level) or 5))
      local data = game and game.data
      local pokemon = data and data.pokemon or {}
      local moves = data and data.moves or {}
      local def = pokemon[species]
      if type(def) ~= "table" or type(def.name) ~= "string"
          or def.name == "" or def.growthRate == nil
          or type(def.types) ~= "table"
          or type(def.level1Moves) ~= "table"
          or type(def.learnset) ~= "table" then
          return false
      end

      -- Pokemon.movesAtLevel dedupes level-1 and learned moves.  Validate the
      -- same source rows here because SummaryMenu page 2 expects every stored
      -- move to resolve to a real move definition with a printable name.
      local needed = {}
      for _, moveId in ipairs(def.level1Moves) do
          needed[moveId] = true
      end
      for _, entry in ipairs(def.learnset) do
          if type(entry) ~= "table" or tonumber(entry.level) == nil
              or entry.move == nil then
              return false
          end
          if tonumber(entry.level) <= level then needed[entry.move] = true end
      end
      for moveId in pairs(needed) do
          local moveDef = moves[moveId]
          if type(moveDef) ~= "table" or type(moveDef.name) ~= "string"
              or tonumber(moveDef.pp) == nil then
              return false
          end
      end

      -- Stats.calc is the final concrete construction contract.  Keep this
      -- guarded so a provider's partial base-stat record is skipped rather than
      -- turning a random-starter roll into a runtime crash.
      local okStats, Stats = pcall(require, "src.pokemon.Stats")
      if okStats and type(Stats) == "table" and type(Stats.calc) == "function" then
          local dvs = { hp = 7, attack = 7, defense = 7, speed = 7, special = 7 }
          local okCalc, calculated = pcall(Stats.calc, def, level, dvs, {
              hp = 0, attack = 0, defense = 0, speed = 0, special = 0,
          })
          if not okCalc or type(calculated) ~= "table"
              or tonumber(calculated.hp) == nil then
              return false
          end
      end
      return true
  end

  mod.exports.__beta26.randomStarterCandidates = function(game, original)
      local all = {}
      local pokemon = game and game.data and game.data.pokemon or {}
      local gold = mod.exports.__beta26.runtimeIsGold(game)
      original = tostring(original or ""):upper()
      for id, def in pairs(pokemon) do
          local species = tostring(id or ""):upper()
          local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
          if species ~= "" and species ~= original and species ~= "EGG"
              and species ~= "NONE" and type(def) == "table"
              and not glitch.isGlitch
              and (not gold or tonumber(def.index) ~= nil)
              and mod.exports.__beta26.randomSpeciesPoolAllows(def,
                  0)
              and mod.exports.__beta26.randomStarterRuntimeSafe(game, species, 5)
              and mod.exports.__beta26.typeLockAllowsSpecies(game, species)
              and (type(specialAcquisitionDenied) ~= "function"
                  or specialAcquisitionDenied(game, species, nil, "starter") == nil) then
              all[#all + 1] = species
          end
      end
      table.sort(all)
      if #all == 0 then return all end

      local style = math.max(0, math.min(3, math.floor(tonumber(
          mod.save:get("random_starter_style", 0)) or 0)))
      if style == 0 then return all end
      local stage, threeStageBase
      do
          local incoming, children = {}, {}
          for species, def in pairs(pokemon) do
              species = tostring(species or ""):upper()
              children[species] = children[species] or {}
              for _, evo in ipairs(type(def) == "table" and def.evolutions or {}) do
                  local target = type(evo) == "table" and tostring(evo.species or ""):upper() or ""
                  if target ~= "" and type(pokemon[target]) == "table" then
                      children[species][#children[species] + 1] = target
                      incoming[target] = (incoming[target] or 0) + 1
                  end
              end
          end
          stage = function(species)
              species = tostring(species or ""):upper()
              local hasParent = (incoming[species] or 0) > 0
              local hasChild = children[species] and #children[species] > 0
              if not hasParent and not hasChild then return "single" end
              if not hasParent then return "base" end
              if hasChild then return "middle" end
              return "final"
          end
          threeStageBase = function(species)
              species = tostring(species or ""):upper()
              if (incoming[species] or 0) > 0 then return false end
              for _, child in ipairs(children[species] or {}) do
                  if children[child] and #children[child] > 0 then return true end
              end
              return false
          end
      end

      local filtered = {}
      if style == 1 then
          for _, species in ipairs(all) do
              if threeStageBase(species) then filtered[#filtered + 1] = species end
          end
      elseif style == 2 then
          for _, species in ipairs(all) do
              local shape = stage(species)
              if shape == "base" or shape == "single" then
                  filtered[#filtered + 1] = species
              end
          end
      else
          local originalBst = mod.exports.__beta26.getSpeciesBST(game, original)
          local tolerance = originalBst and math.max(25, math.floor(originalBst * 0.15 + 0.5)) or nil
          if tolerance then
              for _, species in ipairs(all) do
                  local bst = mod.exports.__beta26.getSpeciesBST(game, species)
                  if bst and math.abs(bst - originalBst) <= tolerance then
                      filtered[#filtered + 1] = species
                  end
              end
          end
      end
      return #filtered > 0 and filtered or all
  end

  local function randomStarterChoiceValid(game, species)
      species = tostring(species or ""):upper()
      if species == "" then return false end
      local pokemon = game and game.data and game.data.pokemon or {}
      local def = pokemon[species]
      return type(def) == "table"
          and (not mod.exports.__beta26.runtimeIsGold(game)
              or tonumber(def.index) ~= nil)
          and mod.exports.__beta26.randomSpeciesPoolAllows(def,
              0)
          and mod.exports.__beta26.randomStarterRuntimeSafe(game, species, 5)
          and mod.exports.__beta26.typeLockAllowsSpecies(game, species)
          and (type(specialAcquisitionDenied) ~= "function"
              or specialAcquisitionDenied(game, species, nil, "starter") == nil)
  end

  local function randomStarterMap()
      local raw = mod.save:get("__nuzlocke_random_starter_choices", {})
      local out = {}
      if type(raw) == "table" then
          for original, choice in pairs(raw) do
              original = tostring(original or ""):upper()
              choice = tostring(choice or ""):upper()
              if original ~= "" and choice ~= "" then out[original] = choice end
          end
      end
      return out
  end

  -- Previewing a starter must not commit the run's chosen starter. R/B and
  -- Gold both let the player inspect multiple balls before deciding, so each
  -- vanilla ball gets one persisted random result. The actual selected ball
  -- is committed separately at the transaction seam.
  mod.exports.__beta26.selectRandomStarter = function(game, original)
      original = tostring(original or ""):upper()
      if (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) or mod.save:get("random_starter", false) ~= true then return original end

      local choices = randomStarterMap()
      local seed = mod.exports.__beta26.randomizerSeed(nil, true)
      local style = math.max(0, math.min(3, math.floor(tonumber(
          mod.save:get("random_starter_style", 0)) or 0)))
      -- Species Pool belongs to Random Encounters. Random Starter's
      -- deterministic namespace therefore stays on the full legal live pool.
      local generation = 0

      -- Pre-seed builds stored one choice directly under the vanilla starter.
      -- On the first 2.2.19 seed, preserve that established result for the
      -- default ANY style by copying it into the seed-scoped namespace. If the
      -- player later chooses a structured Starter Style, its different scope
      -- gets a fresh deterministic result instead of reviving the legacy roll.
      local saved = tostring(choices[original] or ""):upper()
      local legacyOriginal = tostring(mod.save:get(
          "__nuzlocke_random_starter_original", "") or ""):upper()
      local legacyChoice = tostring(mod.save:get(
          "__nuzlocke_random_starter_choice", "") or ""):upper()
      if saved == "" and legacyOriginal == original then saved = legacyChoice end

      local candidates = mod.exports.__beta26.randomStarterCandidates(
          game, original)
      if #candidates == 0 then return original end

      -- Legacy unseeded previews preferred distinct choices. Seeded runs use
      -- the full sorted legal pool so a ball's result depends only on its seed
      -- and semantic identity, never on which starter ball the player inspected
      -- first. Distinctness may occur naturally but reproducibility wins.
      local used = {}
      for otherOriginal, choice in pairs(choices) do
          if tostring(otherOriginal):upper() ~= original
              and randomStarterChoiceValid(game, choice) then
              used[tostring(choice):upper()] = true
          end
      end
      local unused = {}
      for _, choice in ipairs(candidates) do
          if not used[choice] then unused[#unused + 1] = choice end
      end
      local algorithmVersion = mod.exports.__beta26.randomizerAlgorithmVersion()
      local scopeKey = table.concat({
          "v" .. tostring(algorithmVersion), "s" .. tostring(seed),
          "style" .. tostring(style), "g" .. tostring(generation), original }, ":")
      local scopedSaved = tostring(choices[scopeKey] or ""):upper()
      if randomStarterChoiceValid(game, scopedSaved) then return scopedSaved end
      local legacyMarker = "__LEGACY_ADOPTED_" .. original
      if style == 0 and choices[legacyMarker] ~= "YES" and saved ~= ""
          and randomStarterChoiceValid(game, saved) then
          choices[scopeKey] = saved
          choices[original] = saved
          choices[legacyMarker] = "YES"
          mod.save:set("__nuzlocke_random_starter_choices", choices)
          return saved
      end

      local pool = seed > 0 and candidates or (#unused > 0 and unused or candidates)
      local choice
      if seed > 0 then
          -- Use the same versioned hash/stream path as encounter and learnset
          -- randomization. Algorithm v1 produces the exact same hash input as
          -- the historical starter implementation, so current seeded results
          -- remain stable while any future version bump stays synchronized.
          choice = pool[mod.exports.__beta26.randomizerSeededIndex(
              "STARTER", scopeKey, #pool)]
          choices[scopeKey] = choice
      else
          local rng = love and love.math and love.math.random or math.random
          choice = pool[rng(1, #pool)]
      end
      choices[original] = choice
      mod.save:set("__nuzlocke_random_starter_choices", choices)
      return choice
  end

  mod.exports.__beta26.commitRandomStarter = function(game, original, choice)
      original = tostring(original or ""):upper()
      choice = tostring(choice or ""):upper()
      if (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) or mod.save:get("random_starter", false) ~= true
          or original == "" or choice == "" then return choice end

      local choices = randomStarterMap()
      choices[original] = choice
      mod.save:set("__nuzlocke_random_starter_choices", choices)
      -- These legacy/current scalar fields now mean the starter the player
      -- ACTUALLY accepted, not whichever ball happened to be previewed first.
      mod.save:set("__nuzlocke_random_starter_choice", choice)
      mod.save:set("__nuzlocke_random_starter_original", original)
      return choice
  end

  mod.exports.starter_randomizer = {
      api = 2,
      build = mod.exports.__beta26.build,
      select = mod.exports.__beta26.selectRandomStarter,
      commit = mod.exports.__beta26.commitRandomStarter,
  }
  mod.exports.nuzlocke_compat.selectRandomStarter =
      mod.exports.__beta26.selectRandomStarter
  mod.exports.nuzlocke_compat.commitRandomStarter =
      mod.exports.__beta26.commitRandomStarter

  -- R/B/Y's supported pre-creation gift event lets the actual Pokemon be
  -- transformed without replacing Commands.give_pokemon. Restrict it to the
  -- first party acquisition and Oak's canonical starter species.
  mod.events:on("pokemon.before_give", function(gift)
      local ctx = type(gift) == "table" and gift.ctx or nil
      local game = ctx and ctx.game or currentGame or mod.game
      local save = ctx and ctx.save or game and game.save
      if mod.exports.__beta26.runtimeIsGold(game)
          or not save or #(save.party or {}) ~= 0 then return end
      local original = tostring(gift and gift.species or ""):upper()
      if original ~= "BULBASAUR" and original ~= "CHARMANDER"
          and original ~= "SQUIRTLE" and original ~= "PIKACHU" then return end
      local area = tostring((ctx and (ctx.mapId or ctx.map))
          or (ctx and ctx.overworld and ctx.overworld.map
              and ctx.overworld.map.id)
          or (save.player and save.player.map) or ""):upper()
      if area ~= "PALLET_TOWN" and not area:find("OAK", 1, true)
          and not area:find("LAB", 1, true) then return end
      gift.nuzlockeOriginalStarter = original
      gift.species = mod.exports.__beta26.selectRandomStarter(game, original)
      if (not (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) and mod.save:get("random_starter", false) == true) then
          mod.exports.__beta26.commitRandomStarter(
              game, original, gift.species)
      end
  end)

  -- Oak's received-mon line appears immediately before give_pokemon. Rewrite
  -- only that reveal buffer so R/B/Y names the species the persisted roll will
  -- actually grant; the earlier ball/Dex preview still describes the player's
  -- chosen vanilla ball and therefore keeps the intended choice semantics.
  -- 2.3.32 primary Gym Team Size gate.
  -- Standard R/B/Y Gym Leaders (including Yellow Brock) enter through
  -- OverworldState:engageTrainer -> trainer.before_battle, not necessarily
  -- through the script.command/start_battle path. Defer here, show the
  -- tiered refusal, then cancel cleanly before BattleState.newTrainer exists.
  mod.hooks:wrap("trainer.before_battle",
      function(next, game, context, continueBattle)
          if mod.save:get("nuzlocke_enabled", true) ~= true
              or mod.save:get("gym_team_size", false) ~= true then
              return next(game, context, continueBattle)
          end

          local info = mod.exports.__beta26.isNextGymLeaderBattleContext(
              game, context)
          if not info then
              return next(game, context, continueBattle)
          end

          local save = game and game.save or currentSave
          local have = mod.exports.__beta26.playerGymTeamCount(save)
          local limit = tonumber(info.limit or info.teamSize)
          if not limit or have <= limit then
              return next(game, context, continueBattle)
          end

          -- 2.4.8: the refusal text may be observed through more than one
          -- pre-battle callback in the same trainer engagement. Show it once
          -- for this battle-attempt transaction, but never weaken enforcement.
          --
          -- A later talk/challenge gets a fresh context and can explain again.
          if type(context) == "table" and context.nuzlockeGymCapTextShown == true then
              continueBattle({ cancel = true })
              return true
          end
          if type(context) == "table" then
              context.nuzlockeGymCapTextShown = true
          end

          local completed = false
          local function cancelAfterDialogue()
              if completed then return end
              completed = true
              continueBattle({ cancel = true })
          end
          mod.exports.__beta26.rejectGymTeamSize(
              game, info, have, "trainer.before_battle", cancelAfterDialogue)

          -- trainer.before_battle interprets true as "a preparation provider
          -- owns this decision for now"; cancelAfterDialogue resolves that
          -- deferred transaction after the player closes the refusal text.
          return true
      end, 95000)

  mod.hooks:wrap("script.command", function(next, ctx, name, args, cmd)
      -- R/B starter Dex preview: keep the selected ball/story branch vanilla,
      -- but show the same persisted randomized species that will actually be
      -- granted a few rows later. This fixes a Charmander/Squirtle/Bulbasaur
      -- portrait mismatch without rerolling or changing Rival counter-picks.
      if ctx and ctx.generation ~= 2 and name == "ask"
          and type(args) == "table" and ctx.save
          and #(ctx.save.party or {}) == 0
          and (not (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) and mod.save:get("random_starter", false) == true) then
          local textId = tostring(args[1] or "")
          local original = textId:find("Charmander", 1, true) and "CHARMANDER"
              or textId:find("Squirtle", 1, true) and "SQUIRTLE"
              or textId:find("Bulbasaur", 1, true) and "BULBASAUR" or nil
          if original then
              local choice = mod.exports.__beta26.selectRandomStarter(
                  ctx.game or currentGame or mod.game, original)
              local rewritten = {}
              for i, value in ipairs(args) do rewritten[i] = value end
              rewritten[1] = "So! You want " .. choice .. "?"
              return next(ctx, name, rewritten, cmd)
          end
      end

      if ctx and ctx.generation ~= 2 and name == "push_screen"
          and type(args) == "table" and args[1] == "DexEntryMenu"
          and type(args[2]) == "table" and ctx.save
          and #(ctx.save.party or {}) == 0
          and (not (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) and mod.save:get("random_starter", false) == true) then
          local original = tostring(args[2].species or ""):upper()
          if original == "BULBASAUR" or original == "CHARMANDER"
              or original == "SQUIRTLE" then
              local rewritten, opts = {}, {}
              for i, value in ipairs(args) do rewritten[i] = value end
              for key, value in pairs(args[2]) do opts[key] = value end
              opts.species = mod.exports.__beta26.selectRandomStarter(
                  ctx.game or currentGame or mod.game, original)
              rewritten[2] = opts
              return next(ctx, name, rewritten, cmd)
          end
      end

      -- Yellow's native post-lab-battle sequence assumes the starter is
      -- Pikachu: it spawns the Pikachu follower, plays Pikachu's cry, and
      -- prints two Pikachu-specific lines. When Random Starter chose anything
      -- else, suppress only that presentation. Battle-result/story flags and
      -- Rival progression have already been committed and remain untouched.
      if ctx and ctx.generation ~= 2 and getGameVersion() == "YELLOW"
          and (not (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) and mod.save:get("random_starter", false) == true) then
          local choice = tostring(mod.save:get(
              "__nuzlocke_random_starter_choice", "") or ""):upper()
          local mapId = tostring((ctx.overworld and ctx.overworld.map
              and ctx.overworld.map.id) or ctx.mapId or ""):upper()
          if choice ~= "" and choice ~= "PIKACHU"
              and (mapId == "OAKS_LAB" or mapId:find("OAK", 1, true)) then
              if name == "spawn_pikachu_follower" then return nil end
              if name == "play_cry" and type(args) == "table"
                  and tostring(args[1] or ""):upper() == "PIKACHU" then
                  return nil
              end
              if name == "show_text" and type(args) == "table" then
                  local textId = tostring(args[1] or "")
                  if textId == "_OaksLabPikachuDislikesPokeballsText1" then
                      local rewritten = {}
                      for i, value in ipairs(args) do rewritten[i] = value end
                      rewritten[1] = choice .. " looks ready to travel with you!"
                      return next(ctx, name, rewritten, cmd)
                  elseif textId == "_OaksLabPikachuDislikesPokeballsText2" then
                      return nil
                  end
              end
          end
      end

      if ctx and ctx.generation ~= 2 and name == "show_text"
          and type(args) == "table"
          and tostring(args[1] or "") == "_OaksLabRivalMyPokemonLooksStrongerText" then
          local rewritten = {}
          for i, value in ipairs(args) do rewritten[i] = value end
          rewritten[1] = "My Pokemon's ready.\nMeet me outside!"
          return next(ctx, name, rewritten, cmd)
      end

      if ctx and ctx.generation ~= 2 and name == "show_text"
          and type(args) == "table" and type(args[2]) == "table"
          and (args[1] == "_OaksLabReceivedMonText"
              or args[1] == "_OaksLabReceivedText")
          and ctx.save and #(ctx.save.party or {}) == 0
          and (not (externalRuleDelegation and externalRuleDelegation("random_starter", currentGame or mod.game)) and mod.save:get("random_starter", false) == true) then
          local original = tostring(args[2].RAM or ""):upper()
          if original == "BULBASAUR" or original == "CHARMANDER"
              or original == "SQUIRTLE" or original == "PIKACHU" then
              local reveal = {}
              for key, value in pairs(args[2]) do reveal[key] = value end
              reveal.RAM = mod.exports.__beta26.selectRandomStarter(
                  ctx.game or currentGame or mod.game, original)
              local rewritten = {}
              for i, value in ipairs(args) do rewritten[i] = value end
              rewritten[2] = reveal
              return next(ctx, name, rewritten, cmd)
          end
      end
      return next(ctx, name, args, cmd)
  end)

  -- Static status is provenance, not a species list. Script-command adapters
  -- stamp fixed wild battles before battle.started; compatible encounter mods
  -- may also provide one of these explicit fields themselves. This keeps
  -- randomizers correct when a normally static species appears in grass.
  mod.exports.__beta26.isStaticEncounter = function(game, battle)
      if type(battle) ~= "table" then return false end
      local encounterType = tostring(battle.encounterType
          or battle.encounterSource or battle.source or ""):lower()
      return battle.nuzlockeStaticEncounter == true
          or battle.staticEncounter == true
          or battle.isStaticEncounter == true
          or battle.fixedEncounter == true
          or encounterType == "static"
          or encounterType == "fixed"
  end

  ---------------------------------------------------------------------
  -- WORLD BUILDING / FLAVOR
  -- Cosmetic only: never changes a rule result or owns an engine hook.
  -- T1 = core feedback, T2 = snark, T3 = occasional Kanto-aware flavor.
  -- T3 story lines are once-per-save where appropriate.
  ---------------------------------------------------------------------
  local function worldTier(game)
      -- World Building is cosmetic and shared by both supported backends.
      -- Enforcement never depends on the selected tier: T0 still receives a
      -- plain rule explanation from the owning mechanic, while T1-T3 select
      -- progressively more flavorful presentation.
      local fallback = defaultRuleValue("world_building_tier")
      local value = tonumber(mod.save:get("world_building_tier", fallback)) or fallback
      value = math.max(0, math.min(3, value))
      if not (game and game.save) then return 0 end
      if mod.save:get("nuzlocke_enabled", true) ~= true then return 0 end
      return value
  end

