  mod.exports.__beta26.worldRuleTriplet = function(game, key, fallback1, fallback2, fallback3)
      local row = mod.exports.__beta26.worldRuleCatalog[tostring(key or "")]
      if type(row) ~= "table" then
          return fallback1, fallback2 or fallback1, fallback3 or fallback2 or fallback1
      end
      local region = mod.exports.__beta26.runtimeIsGold(game) and "johto" or "kanto"
      return Strings(row.t1 or fallback1 or "Rule blocked."),
          Strings(row.t2 or fallback2 or row.t1 or fallback1 or "Rule blocked."),
          Strings(row[region] or fallback3 or row.t2 or fallback2 or row.t1 or fallback1 or "Rule blocked.")
  end

  mod.exports.__beta26.worldRuleText = function(game, key, fallback1, fallback2, fallback3)
      local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
          game, key, fallback1, fallback2, fallback3)
      local tier = worldTier(game)
      if tier >= 3 then return t3 end
      if tier >= 2 then return t2 end
      return t1
  end

  mod.exports.__beta26.catchRejectionMessage = function(game, reason, species)
      local keyByReason = {
          area = "encounter_area", dupes = "dupes",
          overworld = "overworld_encounters", town = "town_catches",
          legendary = "ban_legendaries", mythical = "ban_mythicals",
          pseudo = "ban_pseudos", static = "no_static_encounters",
          glitch = "allow_glitch_pokemon",
          party_size = "party_size_limit",
          no_catching = "no_catching", type_lock = "type_lock_mode",
      }
      if reason == "type_lock" then
          local allowed = mod.exports.__beta26.typeLockAllowedTypes()
          local labels = {}
          for _, key in ipairs(allowed) do
              labels[#labels + 1] = key == "PSYCHIC_TYPE" and "PSYCHIC" or key
          end
          local base = mod.exports.__beta26.worldRuleText(game, "type_lock_mode")
          if #labels > 0 then
              return Strings("%s\nAllowed: %s", tostring(base), table.concat(labels, " / "))
          end
          return base
      end
      if reason == "bst" then
          local bst = mod.exports.__beta26.getSpeciesBST(game, species)
          local limit = mod.exports.__beta26.getMaximumBST()
          local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
              game, "maximum_bst",
              Strings("BST %s exceeds your maximum of %d.", tostring(bst or "?"), limit),
              Strings("BST %s is over your chosen limit of %d.", tostring(bst or "?"), limit),
              Strings("That Pokemon clocks in at BST %s; your challenge ceiling is %d.", tostring(bst or "?"), limit))
          local tier = worldTier(game)
          return tier >= 3 and t3 or (tier >= 2 and t2 or t1)
      end
      local key = keyByReason[reason]
      if key then return mod.exports.__beta26.worldRuleText(game, key) end
      return Strings("That catch is not allowed by your Nuzlocke rules.")
  end

  ---------------------------------------------------------------------
  -- OWNER-AWARE DIRECT WRAPPER HELPER (2.5.15)
  --
  -- Several older compatibility seams are direct module-method wrappers rather
  -- than hook-bus registrations. Gen1Recomp may keep those module tables alive
  -- across a fresh ModLoader session, so a boolean "installed" flag is not
  -- enough: it can leave a function closing over an obsolete mod/save object.
  -- Record the exact owner/previous/wrapper triple, unwrap only when our stale
  -- wrapper is still the live top-level function, then compose around whatever
  -- function is current. Never replace a different mod's live top-level.
  ---------------------------------------------------------------------
  local function installOwnedMethodWrapper(container, sessionKey, method, factory)
      if type(container) ~= "table" or type(sessionKey) ~= "string"
          or type(method) ~= "string" or type(factory) ~= "function" then
          return false
      end
      if type(container[method]) ~= "function" then return false end

      local session = container[sessionKey]
      if type(session) == "table" then
          if session.owner == mod and container[method] == session.wrapper then
              return true
          end
          if container[method] == session.wrapper
              and type(session.previous) == "function" then
              container[method] = session.previous
          end
          container[sessionKey] = nil
      end

      local previous = container[method]
      if type(previous) ~= "function" then return false end
      local wrapper = factory(previous)
      if type(wrapper) ~= "function" then return false end
      container[method] = wrapper
      container[sessionKey] = {
          owner = mod, method = method, previous = previous, wrapper = wrapper,
      }
      return true
  end

  ---------------------------------------------------------------------
  -- NO DAY CARE: semantic deposit gates, non-destructive on existing saves.
  ---------------------------------------------------------------------
  do
  local function noDayCareActive(game)
      return active(game or currentGame or mod.game, nil)
          and mod.save:get("no_day_care", false) == true
  end

  local function installNoDayCareHooks()
      local okStory, Story2 = pcall(require, "data.scripts.story2")
      if okStory and type(Story2) == "table" and type(Story2.DAYCARE) == "table"
          and type(Story2.DAYCARE.talk) == "table"
          and type(Story2.DAYCARE.talk.TEXT_DAYCARE_GENTLEMAN) == "function" then
          installOwnedMethodWrapper(
              Story2.DAYCARE.talk, "__nuzlockeNoDayCareTalkSession29315",
              "TEXT_DAYCARE_GENTLEMAN", function(vanilla)
                  return function(game, ow, npc, done)
                      local dc = game and game.save and game.save.daycare
                      local occupied = type(dc) == "table" and dc.mon ~= nil
                      if noDayCareActive(game) and not occupied then
                          local TextBox = require("src.render.TextBox")
                          game.stack:push(TextBox.new(game,
                              mod.exports.__beta26.worldRuleText(
                                  game, "no_day_care"), done))
                          return
                      end
                      return vanilla(game, ow, npc, done)
                  end
              end)
          Story2.__nuzlockeNoDayCare29310 = true -- historical marker only
      end

      local okBreed, Breeding = pcall(require, "src.core.gen2.Breeding")
      if okBreed and type(Breeding) == "table"
          and type(Breeding.canDeposit) == "function" then
          installOwnedMethodWrapper(
              Breeding, "__nuzlockeNoDayCareDepositSession29315",
              "canDeposit", function(vanillaCanDeposit)
                  return function(data, save, which, partyIndex)
                      if noDayCareActive(currentGame or mod.game) then
                          return false, "nuzlocke_no_day_care"
                      end
                      return vanillaCanDeposit(data, save, which, partyIndex)
                  end
              end)
          Breeding.__nuzlockeNoDayCare29310 = true -- historical marker only
      end

      local okMenu, DayCareMenu = pcall(require, "src.ui.gen2.DayCareMenu")
      if okMenu and type(DayCareMenu) == "table"
          and type(DayCareMenu.refuse) == "function" then
          installOwnedMethodWrapper(
              DayCareMenu, "__nuzlockeNoDayCareRefuseSession29315",
              "refuse", function(vanillaRefuse)
                  return function(self, key)
                      if key == "nuzlocke_no_day_care" then
                          local tier = worldTier(
                              self and self.game or currentGame or mod.game)
                          local lines
                          if tier >= 3 then
                              local occupied = self and self.save and self.save.breeding
                              local hasParents = type(occupied) == "table"
                                  and (occupied.mother or occupied.father
                                      or occupied.mon1 or occupied.mon2)
                              if hasParents then
                                  lines = { "No new trainees.",
                                      "Your old partners may leave." }
                              else
                                  lines = { "The DAY-CARE couple",
                                      "honors your sealed roster." }
                              end
                          elseif tier >= 2 then
                              lines = { "Your challenge bans",
                                  "DAY-CARE training." }
                          else
                              lines = { "NO DAY CARE is", "active." }
                          end
                          self.TEXT[key] = { lines }
                      end
                      return vanillaRefuse(self, key)
                  end
              end)
          DayCareMenu.__nuzlockeNoDayCare29310 = true -- historical marker only
      end
  end

  -- 2.3.10: deferred until game.ready/save.loaded for boot safety.
  mod.events:on("game.ready", function() pcall(installNoDayCareHooks) end)
  mod.events:on("save.loaded", function() pcall(installNoDayCareHooks) end)
  end

  local function worldFlags()
      local flags = mod.save:get("nuzlocke_world_flags", {})
      if type(flags) ~= "table" then flags = {} end
      return flags
  end

  -- Keep every mod-authored World Building line well-formed before it reaches
  -- either a TextBox or an engine message queue. This deliberately preserves
  -- explicit newlines/page breaks while removing accidental doubled spaces,
  -- spaces beside line breaks, and spaces before punctuation.
  mod.exports.__beta26.cleanWorldText = function(message)
      -- World-building, rule-denial, and item-policy callers pass their stable
      -- English source text through this shared presentation boundary.  That
      -- gives translation mods one reliable key without changing rule logic.
      local text = Strings(tostring(message or ""))
      text = text:gsub("\r\n", "\n"):gsub("\r", "\n")
      text = text:gsub("[ \t]+\n", "\n"):gsub("\n[ \t]+", "\n")
      text = text:gsub("[ \t]+\v", "\v"):gsub("\v[ \t]+", "\v")
      text = text:gsub("[ \t]+", " ")
      text = text:gsub(" +([,%.%!%?;:])", "%1")
      text = text:gsub("^%s+", ""):gsub("%s+$", "")
      return text
  end

  -- 2.1.23: every Nuzlocke-owned overworld/world-building message shares one
  -- paginator. Gen1's native \v continuation scroll deliberately retains the
  -- previous line; that is correct for vanilla text but made mod-authored T3
  -- dialogue look duplicated/stitched across Mom, lab, tutorial, and other
  -- interactions. Convert our own continuation markers to ordinary logical
  -- line boundaries, wrap to the native 18-glyph dialogue width, and emit at
  -- most two lines per explicit page. Vanilla engine text is never rewritten.
  mod.exports.__beta26.formatWorldText = function(message)
      local text = mod.exports.__beta26.cleanWorldText(message)
      if text == "" then return text end
      text = text:gsub("\v", "\n")
      local pages = {}
      local function appendWrappedBlock(block)
          local lines = {}
          for raw in (tostring(block or "") .. "\n"):gmatch("(.-)\n") do
              local words = {}
              for word in raw:gmatch("%S+") do words[#words + 1] = word end
              if #words == 0 then
                  if #lines > 0 then lines[#lines + 1] = "" end
              else
                  local line = ""
                  for _, word in ipairs(words) do
                      if nuzGlyphLen(word) > 18 then
                          if line ~= "" then lines[#lines + 1], line = line, "" end
                          local rest = word
                          while nuzGlyphLen(rest) > 18 do
                              lines[#lines + 1] = nuzGlyphSlice(rest, 1, 18)
                              rest = nuzGlyphSlice(rest, 19)
                          end
                          line = rest
                      else
                          local candidate = line == "" and word or (line .. " " .. word)
                          if nuzGlyphLen(candidate) <= 18 then
                              line = candidate
                          else
                              if line ~= "" then lines[#lines + 1] = line end
                              line = word
                          end
                      end
                  end
                  if line ~= "" then lines[#lines + 1] = line end
              end
          end
          local i = 1
          while i <= #lines do
              local first = lines[i] or ""
              local second = lines[i + 1]
              pages[#pages + 1] = second ~= nil and (first .. "\n" .. second) or first
              i = i + 2
          end
      end
      local start = 1
      while true do
          local cut = text:find("\f", start, true)
          if cut then
              appendWrappedBlock(text:sub(start, cut - 1))
              start = cut + 1
          else
              appendWrappedBlock(text:sub(start))
              break
          end
      end
      return table.concat(pages, "\f")
  end

  -- Own one active World Building TextBox at a time. Compatibility fallbacks
  -- can observe the same transaction through more than one seam; suppress an
  -- identical message only while its first box is still active, then release
  -- ownership when the player closes it so later legitimate interactions keep
  -- giving rule feedback.
  mod.exports.__beta26.pushWorldText = function(game, message, onDone)
      if not (game and game.stack) then return false end

      -- beta.30.0.0.20: never layer optional Nuzlocke World Building text over
      -- an already-active vanilla/other-mod TextBox. Gen1Recomp TextBox is a
      -- foreground blocking state; nesting cosmetic dialogue over it can cause
      -- the underlying script text to resume at an already-presented scroll/
      -- wrap boundary. This is presentation-only: callers treat false as
      -- "do not show flavor text"; rule enforcement must never depend on it.
      local top = type(game.stack.top) == "function" and game.stack:top() or nil
      if type(top) == "table" and top.isTextBox == true then
          return false
      end
      local states = game.stack.states
      if type(states) == "table" then
          for _, state in ipairs(states) do
              if type(state) == "table" and state.isTextBox == true then
                  return false
              end
          end
      end

      local text = mod.exports.__beta26.formatWorldText(message)
      if text == "" then return false end
      local state = mod.exports.__beta26.worldPresentation
      if type(state) ~= "table" then
          state = {}
          mod.exports.__beta26.worldPresentation = state
      end
      if state.game == game and state.activeText == text then return false end
      local okText, TextBox = pcall(require, "src.render.TextBox")
      if not okText or not TextBox or type(TextBox.new) ~= "function" then
          return false
      end
      state.game, state.activeText = game, text
      local ok = pcall(function()
          game.stack:push(TextBox.new(game, text, function(...)
              if state.game == game and state.activeText == text then
                  state.activeText = nil
              end
              if type(onDone) == "function" then return onDone(...) end
          end))
      end)
      if not ok then state.activeText = nil end
      return ok
  end

  local function worldOnce(game, key, message, minimumTier)
      minimumTier = minimumTier or 3
      if worldTier(game) < minimumTier then return false end
      local flags = worldFlags()
      if flags[key] then return false end
      if not mod.exports.__beta26.pushWorldText(game, message) then return false end
      flags[key] = true
      mod.save:set("nuzlocke_world_flags", flags)
      return true
  end

  local function worldMessage(game, tier1, tier2, tier3)
      local tier = worldTier(game)
      if tier <= 0 then return false end
      local message = tier == 1 and tier1 or (tier == 2 and (tier2 or tier1) or (tier3 or tier2 or tier1))
      return message and mod.exports.__beta26.pushWorldText(game, message) or false
  end

  local function worldMechanic(game, key, tier1, tier2, tier3)
      local tier = worldTier(game)
      if tier <= 0 then return false end
      if key then
          local flags = worldFlags()
          -- One gameplay/story event speaks once for the life of the save.
          -- Changing World Building tiers later must not replay the same beat.
          if flags[key] then return false end
          if not worldMessage(game, tier1, tier2, tier3) then return false end
          flags[key] = true
          mod.save:set("nuzlocke_world_flags", flags)
          return true
      end
      return worldMessage(game, tier1, tier2, tier3)
  end

  ---------------------------------------------------------------------
  -- R/B/Y INTRO TRANSITION SAFETY (25D4-RBY2)
  --
  -- Do not push a TextBox from intro.oak_speech.finished. On the current
  -- Gen1Recomp lifecycle this event sits directly on the fade/handoff into
  -- the player's house. The beta.25 game.ready payload fix makes currentGame
  -- a live Game here, which means the old cosmetic worldOnce() call can now
  -- actually push a screen during that transition. Older builds often held
  -- the game.ready event wrapper instead, leaving this cosmetic path inert.
  --
  -- The setup-profile commit listener above remains unchanged. Only this
  -- optional T3 Oak flavor line is suppressed for the diagnostic build.
  ---------------------------------------------------------------------


  ---------------------------------------------------------------------
  -- LEVEL CAP ENFORCEMENT
  --
  -- One player-facing scope controls the entire progression:
  -- 0 NONE, 1 GYMS, 2 E4, 3 CHAMPION, 4 POSTGAME.
  -- Each higher scope includes everything before it. Legacy saves that still
  -- contain hardcore_mode / elite_four_caps are upgraded in the central
  -- semantic migration phase; read-time fallback remains defensive only.
  ---------------------------------------------------------------------
  -- Version-family progression. RBY keeps the established beta.20 tables.
  -- GSC uses one shared family ladder with version-specific profiles so Gold
  -- can be exercised now without turning Silver/Crystal groundwork into a
  -- support claim. Kanto stages after Lance never lower the active cap.
  local VersionCompat = {
      profiles = {
          RED={family="RBY",region="KANTO",status="supported"},
          BLUE={family="RBY",region="KANTO",status="supported"},
          YELLOW={family="RBY",region="KANTO",status="supported"},
          GOLD={family="GSC",region="JOHTO_KANTO",status="experimental"},
          SILVER={family="GSC",region="JOHTO_KANTO",status="groundwork"},
          CRYSTAL={family="GSC",region="JOHTO_KANTO",status="groundwork"},
      },
      rbyGymCaps = {
          RED={14,21,24,29,43,43,47,50}, BLUE={14,21,24,29,43,43,47,50},
          YELLOW={12,21,28,32,50,50,54,55},
      },
      rbyGymNames = {"BROCK","MISTY","LT SURGE","ERIKA","KOGA","SABRINA","BLAINE","GIOVANNI"},
      gscStages = {
          {name="FALKNER",cap=9,phase="GYM"},{name="BUGSY",cap=16,phase="GYM"},
          {name="WHITNEY",cap=20,phase="GYM"},{name="MORTY",cap=25,phase="GYM"},
          {name="CHUCK",cap=30,phase="GYM"},{name="PRYCE",cap=31,phase="GYM"},
          {name="JASMINE",cap=35,phase="GYM"},{name="CLAIR",cap=40,phase="GYM"},
          {name="WILL",cap=42,phase="E4"},{name="KOGA",cap=44,phase="E4"},
          {name="BRUNO",cap=46,phase="E4"},{name="KAREN",cap=47,phase="E4"},
          {name="LANCE",cap=50,phase="CHAMP"},
          {name="LT SURGE",cap=50,phase="POST"},{name="SABRINA",cap=50,phase="POST"},
          {name="MISTY",cap=50,phase="POST"},{name="ERIKA",cap=50,phase="POST"},
          {name="JANINE",cap=50,phase="POST"},{name="BROCK",cap=50,phase="POST"},
          {name="BLAINE",cap=50,phase="POST"},{name="BLUE",cap=58,phase="POST"},
          {name="RED",cap=81,phase="POST"},
      },
  }
  local LEVEL_CAPS_BY_VERSION = VersionCompat.rbyGymCaps
  local LEVEL_CAP_GYM_LEADERS = VersionCompat.rbyGymNames
  local ELITE_FOUR_CAPS = {
      { id = "OPP_LORELEI", name = "LORELEI", cap = 56 },
      { id = "OPP_BRUNO",   name = "BRUNO",   cap = 58 },
      { id = "OPP_AGATHA",  name = "AGATHA",  cap = 60 },
      { id = "OPP_LANCE",   name = "LANCE",   cap = 62 },
  }
  local CHAMPION_CAP = { name = "CHAMPION", cap = 65 }

  -- Live boss-cap compatibility. Content mods commonly patch the merged
  -- trainer registry without exporting a dedicated level-cap provider. Read
  -- that final registry at point of use so enforcement and every UI surface
  -- see the same ace level. A trainer.party observer also remembers a roster
  -- returned by runtime hook composition, which helps retry/rematch flows for
  -- mods whose changes are computed rather than data-patched.
  mod.exports.__beta26.levelCapBosses = {
      rbyGyms = {
          BROCK       = { id = "OPP_BROCK",     party = 1 },
          MISTY       = { id = "OPP_MISTY",     party = 1 },
          ["LT SURGE"] = { id = "OPP_LT_SURGE", party = 1 },
          ERIKA       = { id = "OPP_ERIKA",     party = 1 },
          KOGA        = { id = "OPP_KOGA",      party = 1 },
          SABRINA     = { id = "OPP_SABRINA",  party = 1 },
          BLAINE      = { id = "OPP_BLAINE",   party = 1 },
          GIOVANNI    = { id = "OPP_GIOVANNI", party = 3 },
      },
      observed = {},
  }

  mod.exports.__beta26.partyAceLevel = function(party)
      if type(party) ~= "table" then return nil end
      -- Trainer-content mods do not all preserve the vanilla immediate-array
      -- party shape. Walk only a small, cycle-safe party subtree so wrappers
      -- such as { team = {...} }, { pokemon = {...} }, or nested roster rows
      -- still contribute their live levels without treating arbitrary trainer
      -- metadata as Pokemon.
      local ace, seen = nil, {}
      local function scan(node, depth)
          if type(node) ~= "table" or seen[node] or depth > 4 then return end
          seen[node] = true
          local level = tonumber(node.level or node.lvl)
          local monLike = node.species ~= nil or node.moves ~= nil
              or node.dvs ~= nil or node.statExp ~= nil
          if monLike and level and level > 0 and level <= 100
              and (not ace or level > ace) then
              ace = level
          end
          for key, child in pairs(node) do
              if type(child) == "table" then
                  local k = tostring(key):lower()
                  if type(key) == "number" or k == "party" or k == "team"
                      or k == "pokemon" or k == "mons" or k == "roster"
                      or k == "members" then
                      scan(child, depth + 1)
                  end
              end
          end
      end
      scan(party, 0)
      return ace
  end

  mod.exports.__beta26.trainerPartyKey = function(classId, partyIndex)
      return tostring(classId or ""):upper():gsub("[^A-Z0-9]", "")
          .. "#" .. tostring(partyIndex or 1)
  end

  mod.exports.__beta26.runtimeComposedTrainerAce = function(game, classId, partyIndex, party)
      -- Some trainer-balance mods compute their final roster only inside the
      -- public trainer.party composition hook.  UI level-cap surfaces need the
      -- next boss ace before that battle starts, so when such a mod is active
      -- preview the same semantic hook with the same vanilla party payload.
      -- The call is protected and falls back to merged data on any failure.
      local status = game and game.modStatus
      local hasRuntimeTrainerMod = false
      local function scanStatus(node, depth)
          if hasRuntimeTrainerMod or type(node) ~= "table" or depth > 3 then return end
          local id = tostring(node.id or node.modId or node.name or ""):lower()
          if id == "stronger_trainers" or id == "stronger trainers" then
              local state = tostring(node.state or ""):lower()
              if state ~= "disabled" and state ~= "errored" and state ~= "blocked" then
                  hasRuntimeTrainerMod = true
                  return
              end
          end
          for _, child in pairs(node) do
              if type(child) == "table" then scanStatus(child, depth + 1) end
          end
      end
      scanStatus(status, 0)

      -- Nuzlocke's own built-in Difficulty profiles have a stronger preview
      -- seam than generic runtime providers: use the SAME composeParty()
      -- function that will transform the eventual trainer battle. 2.3.30
      -- runtime showed that relying only on a synthetic re-entry through the
      -- generic trainer.party chain could leave NUZ STATUS on the vanilla cap
      -- after switching VANILLA -> NUZ MEDIUM / historical profiles.
      --
      -- Difficulty is assigned later during init, but this function is called
      -- only at runtime after initialization is complete. External Difficulty
      -- providers remain generic and are still previewed through Runtime.call.
      local difficulty = mod.exports.__beta26.Difficulty
      local selected = type(difficulty) == "table"
          and type(difficulty.selected) == "function"
          and difficulty.selected() or nil
      local internalDifficulty = type(selected) == "table"
          and selected.id ~= nil
          and tostring(selected.id) ~= "vanilla"
          and selected.external ~= true
          and type(difficulty.composeParty) == "function"

      if internalDifficulty then
          local success, resolved = pcall(
              difficulty.composeParty, classId, partyIndex or 1, party)
          if success then
              local ace = mod.exports.__beta26.partyAceLevel(resolved)
              if ace then return ace end
          end
          -- Fail open to the ordinary merged-data fallback below rather than
          -- invent a cap if a modded party has an unsupported shape.
          return nil
      end

      if not hasRuntimeTrainerMod then return nil end
      local ok, Runtime = pcall(require, "src.mods.Runtime")
      if not ok or not Runtime or type(Runtime.call) ~= "function"
          or not Runtime.wantsHook or not Runtime.wantsHook("trainer.party") then
          return nil
      end
      local success, resolved = pcall(function()
          return Runtime.call("trainer.party", function(_, _, base)
              return base
          end, classId, partyIndex or 1, party)
      end)
      if not success then return nil end
      return mod.exports.__beta26.partyAceLevel(resolved)
  end

  mod.exports.__beta26.liveTrainerAce = function(game, classId, partyIndex)
      local observed = mod.exports.__beta26.levelCapBosses.observed
      local key = mod.exports.__beta26.trainerPartyKey(classId, partyIndex)
      if tonumber(observed[key]) then return tonumber(observed[key]), "HOOK" end

      -- 2.4.1: use the same canonical party reader/composer already used by
      -- Gym Team Size. Gen1Recomp's R/B/Y trainer.parties[partyIndex] is the
      -- party ARRAY itself, not necessarily { party = {...} }. The older cap
      -- preview unwrapped only .party/.roster/.team after selecting the row,
      -- so ordinary R/B/Y parties became nil and NEXT CAP silently fell back
      -- to vanilla even while Difficulty changed the real battle roster.
      -- baseTrainerParty accepts both direct arrays and provider wrappers;
      -- composedTrainerParty then runs the real trainer.party chain, keeping
      -- cap display/enforcement on the same final roster as battle creation.
      local baseFn = mod.exports.__beta26.baseTrainerParty
      local composeFn = mod.exports.__beta26.composedTrainerParty
      if type(baseFn) == "function" then
          local base = baseFn(game, classId, partyIndex or 1)
          if type(base) == "table" then
              local composed = base
              if type(composeFn) == "function" then
                  composed = composeFn(game, classId, partyIndex or 1, base)
                      or base
              else
                  local preview = mod.exports.__beta26.runtimeComposedTrainerAce(
                      game, classId, partyIndex or 1, base)
                  if preview then return preview, "HOOK_PREVIEW" end
              end
              local ace = mod.exports.__beta26.partyAceLevel(composed)
              if ace then return ace, "COMPOSED_PARTY" end
          end
      end

      -- Defensive legacy fallback for unusual provider registries loaded
      -- before the canonical helper is available. Direct-array rows are
      -- accepted here too instead of being discarded.
      local data = game and game.data
      local g2 = data and data.gen2Trainers
      local classes = type(g2) == "table" and g2.classes or nil
      local trainer
      if type(classes) == "table" then
          local cls = classes[classId]
          local rows = type(cls) == "table" and cls.trainers or nil
          trainer = type(rows) == "table" and rows[partyIndex or 1] or nil
      end
      if trainer == nil then
          local trainers = data and data.trainers
          trainer = type(trainers) == "table" and trainers[classId] or nil
          local parties = type(trainer) == "table"
              and (trainer.parties or trainer.rosters) or nil
          if type(parties) == "table" then trainer = parties[partyIndex or 1] end
      end
      local party = type(trainer) == "table"
          and (trainer.party or trainer.roster or trainer.team or trainer) or nil
      local preview = mod.exports.__beta26.runtimeComposedTrainerAce(
          game, classId, partyIndex or 1, party)
      if preview then return preview, "HOOK_PREVIEW" end
      local ace = mod.exports.__beta26.partyAceLevel(party)
      if ace then return ace, "MERGED_DATA" end
      return nil
  end

  mod.exports.__beta26.championPartyIndex = function(game, save)
      local version = getGameVersion and getGameVersion() or "RED"
      if version == "YELLOW" then
          return math.max(1, math.min(3,
              math.floor(tonumber(save and save.rivalStarter) or 1)))
      end
      local flags = save and save.flags or {}
      local offsets = game and game.data and game.data.field
          and game.data.field.starterCounterpicks
      if type(offsets) == "table" then
          for flag, offset in pairs(offsets) do
              if flags[flag] == true or tonumber(flags[flag]) == 1 then
                  return 1 + (tonumber(offset) or 0)
              end
          end
      end
      if flags.EVENT_CHOSE_SQUIRTLE == true
          or tonumber(flags.EVENT_CHOSE_SQUIRTLE) == 1 then return 2 end
      if flags.EVENT_CHOSE_BULBASAUR == true
          or tonumber(flags.EVENT_CHOSE_BULBASAUR) == 1 then return 3 end
      return 1
  end

  mod.exports.__beta26.liveRbyBossAce = function(name, fallback, save)
      local game = currentGame
      local spec = mod.exports.__beta26.levelCapBosses.rbyGyms[name]
      if spec then
          return mod.exports.__beta26.liveTrainerAce(
              game, spec.id, spec.party) or fallback
      end
      if tostring(name) == "CHAMPION" then
          local party = mod.exports.__beta26.championPartyIndex(game, save)
          return mod.exports.__beta26.liveTrainerAce(
              game, "OPP_RIVAL3", party) or fallback
      end
      local id = tostring(name or "")
      if not id:find("^OPP_", 1) then id = "OPP_" .. id end
      return mod.exports.__beta26.liveTrainerAce(game, id, 1) or fallback
  end

  mod.exports.__beta26.liveGscStageAce = function(stageName, fallback)
      local data = currentGame and currentGame.data
      -- Gold's real merged trainer registry is gen2Trainers. Older adapter
      -- paths exposed a `.trainers` spelling, so retain that only as fallback.
      local trainers = data and (data.gen2Trainers or data.trainers)
      local classes = type(trainers) == "table"
          and (trainers.classes or trainers) or nil
      if type(classes) ~= "table" then return fallback end
      local target = tostring(stageName or ""):upper():gsub("[^A-Z0-9]", "")
      local best, bestScore
      for classId, class in pairs(classes) do
          if type(class) == "table" then
              local classKey = tostring(classId):upper():gsub("[^A-Z0-9]", "")
              local className = tostring(class.name or ""):upper():gsub("[^A-Z0-9]", "")
              for member, row in pairs(class.trainers or {}) do
                  if type(row) == "table" then
                      local rowName = tostring(row.name or row.id or ""):upper()
                          :gsub("[^A-Z0-9]", "")
                      local score = rowName == target and 3
                          or ((classKey == target or className == target) and 2)
                          or ((rowName:find(target, 1, true)
                              or target:find(rowName, 1, true)) and 1)
                      if score then
                          local observed = mod.exports.__beta26.levelCapBosses.observed
                          local observedAce = observed[
                              mod.exports.__beta26.trainerPartyKey(
                                  class.index or classId, member)]
                              or observed[mod.exports.__beta26.trainerPartyKey(
                                  classId, member)]
                          local ace = tonumber(observedAce)
                          if not ace then
                              ace = mod.exports.__beta26.partyAceLevel(row.party)
                              local difficulty = mod.exports.__beta26.Difficulty
                              local selected = type(difficulty) == "table"
                                  and type(difficulty.selected) == "function"
                                  and difficulty.selected() or nil
                              if ace and type(selected) == "table"
                                  and tostring(selected.id or "vanilla") ~= "vanilla"
                                  and selected.external ~= true then
                                  local pct = tonumber(selected.bossLevelPct
                                      or selected.levelPct) or 100
                                  ace = math.max(1, math.min(100,
                                      math.floor(ace * pct / 100 + 0.5)))
                              end
                          end
                          if ace and (not bestScore or score > bestScore
                              or (score == bestScore and ace > best)) then
                              best, bestScore = ace, score
                          end
                      end
                  end
              end
          end
      end
      return best or fallback
  end


  -- 2.2.16 Gym Team Size: derive the next Leader's party count from the same
  -- live merged/composed trainer data used by NEXT CAP.  This is deliberately
  -- a battle-entry rule, not a storage rule: Nuzlocke never auto-boxes or
  -- deletes party members.  The player may carry/train a larger party between
  -- Gyms, but must box extras before the actual Leader battle begins.
  mod.exports.__beta26.partyMemberCount = function(party)
      if type(party) ~= "table" then return nil end
      local node = party.party or party.team or party.roster or party.pokemon
          or party.mons or party.members or party
      if type(node) ~= "table" then return nil end
      local count = 0
      for key, mon in pairs(node) do
          if type(key) == "number" and type(mon) == "table"
              and (mon.species ~= nil or mon.level ~= nil or mon.lvl ~= nil) then
              count = count + 1
          end
      end
      return count > 0 and count or nil
  end

  mod.exports.__beta26.baseTrainerParty = function(game, classId, partyIndex)
      local data = game and game.data
      local g2 = data and data.gen2Trainers
      local classes = type(g2) == "table" and g2.classes or nil
      if type(classes) == "table" then
          local cls = classes[classId]
          if cls == nil then
              for id, candidate in pairs(classes) do
                  if tostring(id) == tostring(classId)
                      or tonumber(id) == tonumber(classId) then
                      cls = candidate
                      break
                  end
              end
          end
          local rows = type(cls) == "table" and cls.trainers or nil
          local trainer = type(rows) == "table" and rows[partyIndex or 1] or nil
          if type(trainer) == "table" then
              return trainer.party or trainer.roster or trainer.team, trainer
          end
      end
      local trainers = data and data.trainers
      local trainer = type(trainers) == "table" and trainers[classId] or nil
      local parties = type(trainer) == "table"
          and (trainer.parties or trainer.rosters) or nil
      if type(parties) == "table" then
          local row = parties[partyIndex or 1]
          if type(row) == "table" then
              return row.party or row.roster or row.team or row, row
          end
      elseif type(trainer) == "table" then
          return trainer.party or trainer.roster or trainer.team, trainer
      end
      return nil, trainer
  end

  mod.exports.__beta26.composedTrainerParty = function(game, classId, partyIndex, base)
      local party = base
      if type(party) ~= "table" then
          party = mod.exports.__beta26.baseTrainerParty(game, classId, partyIndex)
      end
      if type(party) ~= "table" then return nil end
      local ok, Runtime = pcall(require, "src.mods.Runtime")
      if not ok or not Runtime or type(Runtime.call) ~= "function"
          or not Runtime.wantsHook or not Runtime.wantsHook("trainer.party") then
          return party
      end
      local success, resolved = pcall(function()
          return Runtime.call("trainer.party", function(_, _, fallback)
              return fallback
          end, classId, partyIndex or 1, party)
      end)
      if success and type(resolved) == "table" then return resolved end
      return party
  end

  mod.exports.__beta26.findGscStageTrainer = function(stageName)
      local game = currentGame or mod.game
      local data = game and game.data
      local trainers = data and (data.gen2Trainers or data.trainers)
      local classes = type(trainers) == "table"
          and (trainers.classes or trainers) or nil
      if type(classes) ~= "table" then return nil end
      local target = tostring(stageName or ""):upper():gsub("[^A-Z0-9]", "")
      local best, bestScore
      for classId, class in pairs(classes) do
          if type(class) == "table" then
              local classKey = tostring(classId):upper():gsub("[^A-Z0-9]", "")
              local className = tostring(class.name or ""):upper():gsub("[^A-Z0-9]", "")
              for member, row in pairs(class.trainers or {}) do
                  if type(row) == "table" then
                      local rowName = tostring(row.name or row.id or ""):upper()
                          :gsub("[^A-Z0-9]", "")
                      local score = rowName == target and 3
                          or ((classKey == target or className == target) and 2)
                          or ((rowName ~= "" and target ~= ""
                              and (rowName:find(target, 1, true)
                                  or target:find(rowName, 1, true))) and 1)
                      if score and (not bestScore or score > bestScore) then
                          bestScore = score
                          best = {
                              classId = class.index or classId,
                              rawClassId = classId,
                              partyIndex = member,
                              trainer = row,
                          }
                      end
                  end
              end
          end
      end
      return best
  end

  mod.exports.__beta26.liveRbyBossPartySize = function(name, save)
      local game = currentGame or mod.game
      local spec = mod.exports.__beta26.levelCapBosses.rbyGyms[name]
      if not spec then return nil end
      local base = mod.exports.__beta26.baseTrainerParty(game, spec.id, spec.party)
      local party = mod.exports.__beta26.composedTrainerParty(
          game, spec.id, spec.party, base)
      return mod.exports.__beta26.partyMemberCount(party), spec.id, spec.party
  end

  mod.exports.__beta26.liveGscStagePartySize = function(stageName)
      local game = currentGame or mod.game
      local hit = mod.exports.__beta26.findGscStageTrainer(stageName)
      if type(hit) ~= "table" then return nil end
      local base = type(hit.trainer) == "table"
          and (hit.trainer.party or hit.trainer.roster or hit.trainer.team) or nil
      local party = mod.exports.__beta26.composedTrainerParty(
          game, hit.classId, hit.partyIndex, base)
      return mod.exports.__beta26.partyMemberCount(party), hit.classId,
          hit.partyIndex, hit.trainer
  end

  mod.exports.__beta26.getNextGymTeamInfo = function(save)
      save = save or currentSave or (currentGame and currentGame.save)
      local game = currentGame or mod.game
      if not (save and game) then return nil end
      if mod.exports.__beta26.runtimeIsGold(game) then
          local progress = gscProgress(save)
          for _, stage in ipairs(VersionCompat.gscStages or {}) do
              local isGym = stage.phase == "GYM"
                  or (stage.phase == "POST" and tostring(stage.name) ~= "RED")
              if isGym and progress[stage.name] ~= true then
                  local size, classId, partyIndex =
                      mod.exports.__beta26.liveGscStagePartySize(stage.name)
                  if size then
                      return { leader=stage.name, name=stage.name, limit=size,
                          teamSize=size, classId=classId, partyIndex=partyIndex,
                          source="LIVE_COMPOSED_TRAINER_PARTY" }
                  end
                  return nil
              end
          end
          return nil
      end
      local badges = currentGymProgressCount(save)
      local leader = LEVEL_CAP_GYM_LEADERS[badges + 1]
      if not leader then return nil end
      local size, classId, partyIndex =
          mod.exports.__beta26.liveRbyBossPartySize(leader, save)
      if not size then return nil end
      return { leader=leader, name=leader, limit=size, teamSize=size,
          classId=classId, partyIndex=partyIndex,
          source="LIVE_COMPOSED_TRAINER_PARTY" }
  end

  mod.exports.__beta26.playerGymTeamCount = function(save)
      local count = 0
      for _, mon in ipairs(save and save.party or {}) do
          local species = tostring(type(mon) == "table" and mon.species or ""):upper()
          -- Gym Team Size is a "what you bring through the Leader's door"
          -- rule, not a usable-battler count. Fainted/Nuzlocke-dead Pokemon
          -- still occupy an active party slot and must be boxed; Eggs are not
          -- battle-team Pokemon and remain excluded.
          if type(mon) == "table" and species ~= "" and species ~= "EGG"
              and mon.isEgg ~= true then
              count = count + 1
          end
      end
      return count
  end

  mod.exports.__beta26.isNextGymLeaderBattleContext = function(game, context)
      game = game or currentGame or mod.game
      context = type(context) == "table" and context or {}
      local save = game and game.save or currentSave
      local info = mod.exports.__beta26.getNextGymTeamInfo(save)
      if type(info) ~= "table" then return nil end

      local classId = context.trainerClass or context.classId
          or context.class or context.oppClass
      local partyIndex = context.partyIndex or context.party
          or context.member or 1
      if classId == nil then return nil end

      if tostring(classId) ~= tostring(info.classId or "") then
          return nil
      end
      if tonumber(partyIndex or 1) ~= tonumber(info.partyIndex or 1) then
          return nil
      end
      return info
  end

  mod.exports.__beta26.gymTeamSizeRejectionText = function(game, info, have)
      local limit = tonumber(info and (info.limit or info.teamSize)) or 0
      local leader = tostring(info and (info.leader or info.name) or "Gym Leader")
      local base = mod.exports.__beta26.worldRuleText(game, "gym_team_size",
          "Your party is too large for this Gym Leader.",
          "This Leader will not start the match until your party fits the team-size rule.",
          "The Leader counts the POKé BALLS at your belt and refuses the match. Box the extras and return.")
      local extras = math.max(0, (tonumber(have) or 0) - limit)
      local detail
      if extras == 1 then
          detail = Strings("%s allows %d. You brought %d. Box 1 Pokemon and return.",
              leader, limit, tonumber(have) or 0)
      else
          detail = Strings("%s allows %d. You brought %d. Box %d Pokemon and return.",
              leader, limit, tonumber(have) or 0, extras)
      end
      return tostring(base or "") .. "\n" .. detail
  end

  mod.exports.__beta26.rejectGymTeamSize = function(game, info, have, source, onDone)
      local message = mod.exports.__beta26.gymTeamSizeRejectionText(game, info, have)
      if type(mod.exports.__beta26.emitSystem) == "function" then
          mod.exports.__beta26.emitSystem("gym_team_size_rejected", {
              gym = info and (info.name or info.leader),
              leader = info and info.leader,
              allowed = info and (info.limit or info.teamSize),
              party = have,
              source = source,
          })
      end
      local shown = mod.exports.__beta26.pushWorldText(game, message, onDone)
      if not shown and type(onDone) == "function" then onDone() end
      return shown
  end

  mod.exports.__beta26.isNextGymLeaderCommand = function(ctx, name, args)
      local game = ctx and ctx.game or currentGame or mod.game
      local save = ctx and ctx.save or game and game.save or currentSave
      local info = mod.exports.__beta26.getNextGymTeamInfo(save)
      if type(info) ~= "table" then return nil end
      if not mod.exports.__beta26.runtimeIsGold(game) then
          if name ~= "start_battle" or type(args) ~= "table"
              or tostring(args[1] or ""):lower() ~= "trainer" then return nil end
          if tostring(args[2] or "") ~= tostring(info.classId or "")
              or tonumber(args[3] or 1) ~= tonumber(info.partyIndex or 1) then
              return nil
          end
          return info
      end
      if name ~= "startbattle" then return nil end
      local vm = ctx and ctx.vm
      local trainer = vm and vm.trainer
      if type(trainer) ~= "table" then return nil end
      local want = tostring(info.leader or ""):upper():gsub("[^A-Z0-9]", "")
      local got = tostring(trainer.name or trainer.id or ""):upper()
          :gsub("[^A-Z0-9]", "")
      if got ~= "" and got == want then return info end
      local classId = trainer.classId or trainer.class or trainer.trainerClass
      local member = trainer.member or trainer.memberId or trainer.index
      if classId ~= nil and tostring(classId) == tostring(info.classId)
          and (member == nil or tonumber(member) == tonumber(info.partyIndex)) then
          return info
      end
      return nil
  end

  mod.hooks:wrap("script.command", function(next, ctx, name, args, cmd)
      local game = ctx and ctx.game or currentGame or mod.game
      if mod.save:get("nuzlocke_enabled", true) == true
          and mod.save:get("gym_team_size", false) == true then
          local info = mod.exports.__beta26.isNextGymLeaderCommand(ctx, name, args)
          if info then
              local save = ctx and ctx.save or game and game.save or currentSave
              local have = mod.exports.__beta26.playerGymTeamCount(save)
              local limit = tonumber(info.limit)
              if limit and have > limit then
                  local message = mod.exports.__beta26.gymTeamSizeRejectionText(
                      game, info, have)
                  local vm = ctx and ctx.vm
                  if vm and type(vm.showRaw) == "function" then
                      vm:showRaw(message)
                      if type(mod.exports.__beta26.emitSystem) == "function" then
                          mod.exports.__beta26.emitSystem("gym_team_size_rejected", {
                              leader=info.leader, allowed=limit, party=have,
                              source="script.command",
                          })
                      end
                  else
                      mod.exports.__beta26.rejectGymTeamSize(
                          game, info, have, "script.command")
                  end
                  return "end"
              end
          end
      end
      return next(ctx, name, args, cmd)
  end, 95000)

  mod.hooks:wrap("trainer.party", function(next, classId, partyIndex, party)
      local resolved = next(classId, partyIndex, party) or party
      local ace = mod.exports.__beta26.partyAceLevel(resolved)
      if ace then
          mod.exports.__beta26.levelCapBosses.observed[
              mod.exports.__beta26.trainerPartyKey(classId, partyIndex)] = ace
      end
      return resolved
  end, 100000)

  mod.events:on("battle.started", function(ev)
      local battle = ev and (ev.battle or ev)
      if type(battle) ~= "table" then return end
      local trainer = battle.trainer
      local party = battle.enemyParty
          or (type(trainer) == "table" and trainer.party)
      local ace = mod.exports.__beta26.partyAceLevel(party)
      if not ace then return end
      local classId = battle.oppClass or battle.trainerClass
          or (type(trainer) == "table"
              and (trainer.classId or trainer.class or trainer.id))
          or (ev and ev.trainerId)
      local member = battle.partyIndex
          or (type(trainer) == "table"
              and (trainer.memberId or trainer.member or trainer.index))
          or 1
      if classId then
          mod.exports.__beta26.levelCapBosses.observed[
              mod.exports.__beta26.trainerPartyKey(classId, member)] = ace
      end
  end)

  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.game_profiles = VersionCompat.profiles
      mod.exports.nuzlocke_compat.getGameVersion = function() return getGameVersion and getGameVersion() or "RED" end
      mod.exports.nuzlocke_compat.getGameProfile = function()
          local v = getGameVersion and getGameVersion() or "RED"
          return VersionCompat.profiles[v]
      end
  end

  local function levelCapScope()
      if mod.save:get("nuzlocke_enabled", true) == false then return 0 end
      local raw = mod.save:get("level_cap_scope", nil)
      if raw ~= nil then
          -- Scope is an enum, not a continuous value.  Normalize malformed
          -- or hand-edited saves before any UI/enforcement comparison.
          return math.floor(math.max(0, math.min(4, tonumber(raw) or 0)))
      end
      -- Backward compatibility with beta 6 and earlier saves.
      return legacyLevelCapScope()
  end

  mod.exports.__beta26.saveFlagTrue = function(save, name)
      local flags = save and save.flags
      local value = type(flags) == "table" and flags[name]
      return value == true or tonumber(value) == 1
  end

  local function eliteFourDefeated()
      local defeated = mod.save:get("nuzlocke_e4_defeated")
      if type(defeated) ~= "table" then
          defeated = {}
      end
      local save = currentSave or (currentGame and currentGame.save)
      local allDone = mod.exports.__beta26.saveFlagTrue(
          save, "EVENT_BEAT_CHAMPION_RIVAL")
      local flags = {
          OPP_LORELEI = "EVENT_BEAT_LORELEIS_ROOM_TRAINER_0",
          OPP_BRUNO = "EVENT_BEAT_BRUNOS_ROOM_TRAINER_0",
          OPP_AGATHA = "EVENT_BEAT_AGATHAS_ROOM_TRAINER_0",
          OPP_LANCE = "EVENT_BEAT_LANCE",
      }
      for id, flag in pairs(flags) do
          if allDone or mod.exports.__beta26.saveFlagTrue(save, flag)
              or (id == "OPP_LANCE" and mod.exports.__beta26.saveFlagTrue(
                  save, "EVENT_BEAT_LANCES_ROOM_TRAINER_0")) then
              defeated[id] = true
          end
      end
      mod.save:set("nuzlocke_e4_defeated", defeated)
      return defeated
  end

  local function championDefeated()
      if mod.save:get("nuzlocke_champion_defeated", false) == true then
          return true
      end
      local save = currentSave or (currentGame and currentGame.save)
      if mod.exports.__beta26.saveFlagTrue(
          save, "EVENT_BEAT_CHAMPION_RIVAL") then
          mod.save:set("nuzlocke_champion_defeated", true)
          return true
      end
      return false
  end

  -- Shared reader for external cap providers. Both normal and post-game
  -- providers use the same small contract, so keep parsing in one place.
  local function providerCapInfo(capability, save, fallbackName, allowMax)
      local provider = activeCompatProvider(capability, currentGame, nil)
      local value = provider and provider.value
      if not provider then return nil end

      local getter = type(value) == "function" and value
          or (type(value) == "table" and (value.get_next_cap
              or value.getNextCap or value.get_cap or value.getLevelCap
              or value.get_level_cap or value.next_cap or value.nextCap))
      if type(getter) ~= "function" then return nil end

      local ok, result = pcall(getter, currentGame, save)
      if (not ok or result == nil) and type(value) == "table" then
          ok, result = pcall(getter, value, currentGame, save)
      end
      if not ok or result == nil then return nil end

      local cap
      local name = fallbackName

      if type(result) == "table" then
          if result.enabled == false or result.active == false then return nil end
          cap = tonumber(result.cap or result.level or result.ace
              or result.max_level or result.maxLevel or result.levelCap)
          name = tostring(result.name or result.boss or result.stage
              or result.trainer or fallbackName)
      else
          cap = tonumber(result)
      end

      local maxAllowed = allowMax and 100 or 99
      if cap and cap > 0 and cap <= maxAllowed then
          return cap, name
      end

      return nil
  end

  local function postgameCapInfo(save)
      -- POSTGAME is the inclusive fourth Level Cap Scope. It is the one and
      -- only opt-in for provider stages; the retired Expanded Postgame toggle
      -- must not silently gate this newer scope.
      if levelCapScope() < 4 then return nil end
      local provider = activeCompatProvider("postgame_caps", currentGame, nil)
      local value = provider and provider.value
      if type(value) == "table" then
          local stages = value.stages or value.postgameStages
          local stageGetter = value.get_stages or value.getStages
          if type(stageGetter) == "function" then
              local ok, got = pcall(stageGetter, currentGame, save)
              if (not ok or type(got) ~= "table") then
                  ok, got = pcall(stageGetter, value, currentGame, save)
              end
              if ok and type(got) == "table" then stages = got end
          end
          if type(stages) == "table" then
              for _, stage in ipairs(stages) do
                  if type(stage) == "table" then
                      local defeated = stage.defeated
                      local done = defeated == true
                      if type(defeated) == "function" then
                          local ok, got = pcall(defeated, currentGame, save, stage)
                          done = ok and got == true
                      elseif type(defeated) == "string" then
                          done = mod.save:get(defeated, false) == true
                      end
                      if not done then
                          local cap = tonumber(stage.cap or stage.level
                              or stage.ace or stage.max_level
                              or stage.maxLevel or stage.levelCap)
                          if cap and cap > 0 and cap <= 100 then
                              return cap, tostring(stage.name or stage.id or "POSTGAME")
                          end
                      end
                  end
              end
          end
      end
      return providerCapInfo("postgame_caps", save, "POSTGAME", true)
  end

  local function nextEliteFourCapInfo(floor)
      local defeated = eliteFourDefeated()
      floor = tonumber(floor) or 0
      for _, entry in ipairs(ELITE_FOUR_CAPS) do
          local ace = mod.exports.__beta26.liveRbyBossAce(
              entry.id, entry.cap, currentSave)
          if defeated[entry.id] ~= true then
              return math.max(floor, ace), entry.name
          end
          floor = math.max(floor, ace)
      end
      return nil, nil, floor
  end

  local function currentBadgeCount(save)
      local inventory = save and save.inventory or {}
      local coreData = require("src.core.Data")
      local badges = coreData.constants and coreData.constants.badges or {
          { id = "BOULDERBADGE" }, { id = "CASCADEBADGE" },
          { id = "THUNDERBADGE" }, { id = "RAINBOWBADGE" },
          { id = "SOULBADGE" }, { id = "MARSHBADGE" },
          { id = "VOLCANOBADGE" }, { id = "EARTHBADGE" },
      }
      local count = 0
      for i, badge in ipairs(badges) do
          local id = badge.id or badge.item or badge.key
          if id and (inventory[id] == true or tonumber(inventory[id]) and tonumber(inventory[id]) > 0) then
              count = i
          else
              break
          end
      end
      return count
  end

  -- Gym progression is tracked separately from badge inventory. This keeps a
  -- later scope change from manufacturing League progress.
  local GYM_PROGRESS_KEY = "nuzlocke_gym_defeated"

  local function gymProgress(save)
      local progress = mod.save:get(GYM_PROGRESS_KEY, nil)
      if type(progress) ~= "table" then
          progress = {}
          local badgeCount = currentBadgeCount(save)
          for i = 1, math.min(badgeCount, #LEVEL_CAP_GYM_LEADERS) do
              progress[LEVEL_CAP_GYM_LEADERS[i]] = true
          end
          mod.save:set(GYM_PROGRESS_KEY, progress)
      end
      return progress
  end

  local function currentGymProgressCount(save)
      local progress = gymProgress(save)
      local count = 0
      for i, leader in ipairs(LEVEL_CAP_GYM_LEADERS) do
          if progress[leader] == true then
              count = i
          else
              break
          end
      end
      return count
  end

  local function currentGymLevelCaps()
      local version = getGameVersion and getGameVersion() or "RED"
      -- Unknown/future Gen 1 editions should degrade to the canonical Red
      -- table instead of crashing every cap consumer on a nil length/index.
      return LEVEL_CAPS_BY_VERSION[version] or LEVEL_CAPS_BY_VERSION.RED
  end

  mod.exports.__beta26.badgeOwned = function(save, store, name, index)
      local badges = save and save.player and save.player[store]
      if type(badges) ~= "table" then return false end
      local direct = badges[name]
      local positional = index and badges[index]
      return direct == true or tonumber(direct) == 1
          or positional == true or tonumber(positional) == 1
  end

  mod.exports.__beta26.gscBadgeStages = {
      FALKNER = { "badges", "ZEPHYR", 1 },
      BUGSY = { "badges", "HIVE", 2 },
      WHITNEY = { "badges", "PLAIN", 3 },
      MORTY = { "badges", "FOG", 4 },
      CHUCK = { "badges", "STORM", 5 },
      JASMINE = { "badges", "MINERAL", 6 },
      PRYCE = { "badges", "GLACIER", 7 },
      CLAIR = { "badges", "RISING", 8 },
      ["LT SURGE"] = { "kantoBadges", "THUNDER", 3 },
      SABRINA = { "kantoBadges", "MARSH", 6 },
      MISTY = { "kantoBadges", "CASCADE", 2 },
      ERIKA = { "kantoBadges", "RAINBOW", 4 },
      JANINE = { "kantoBadges", "SOUL", 5 },
      BROCK = { "kantoBadges", "BOULDER", 1 },
      BLAINE = { "kantoBadges", "VOLCANO", 7 },
      BLUE = { "kantoBadges", "EARTH", 8 },
  }

  local function gscProgress(save)
      local progress = mod.save:get("nuzlocke_gsc_defeated", nil)
      if type(progress) ~= "table" then progress = {} end
      for name, badge in pairs(mod.exports.__beta26.gscBadgeStages) do
          if mod.exports.__beta26.badgeOwned(
              save, badge[1], badge[2], badge[3])
              or mod.exports.__beta26.saveFlagTrue(
                  save, "EVENT_BEAT_" .. name:gsub(" ", "_")) then
              progress[name] = true
          end
      end
      local leagueDone = mod.exports.__beta26.saveFlagTrue(
          save, "EVENT_BEAT_ELITE_FOUR")
          or mod.exports.__beta26.saveFlagTrue(
              save, "EVENT_BEAT_CHAMPION_LANCE")
      local leagueFlags = {
          WILL = "EVENT_BEAT_ELITE_4_WILL",
          KOGA = "EVENT_BEAT_ELITE_4_KOGA",
          BRUNO = "EVENT_BEAT_ELITE_4_BRUNO",
          KAREN = "EVENT_BEAT_ELITE_4_KAREN",
          LANCE = "EVENT_BEAT_CHAMPION_LANCE",
      }
      for name, flag in pairs(leagueFlags) do
          if leagueDone or mod.exports.__beta26.saveFlagTrue(save, flag) then
              progress[name] = true
          end
      end
      mod.save:set("nuzlocke_gsc_defeated", progress)
      return progress
  end

  ---------------------------------------------------------------------
  -- GYM / DUNGEON LOCK-INS (beta.29.2.2)
  --
  -- Gym exits are gated at the engine's public warp.destination seam. The
  -- source map is read from the live overworld and a blocked door is rerouted
  -- one cell back into the same map, so story flags and destination scripts
  -- never run. Dungeons intentionally cover only known multi-exit families:
  -- the entrance used to enter is sealed, while a different legitimate exit
  -- releases the lock. This conservative rule avoids trapping the player in
  -- dead-end/single-exit locations.
  ---------------------------------------------------------------------
  mod.exports.__beta26.gymLeaderForMap = function(mapId, game)
      local id = tostring(mapId or ""):upper():gsub("[^A-Z0-9]", "")
      local gold = mod.exports.__beta26.runtimeIsGold(game)
      local rby = {
          PEWTERGYM="BROCK", CERULEANGYM="MISTY", VERMILIONGYM="LT SURGE",
          CELADONGYM="ERIKA", FUCHSIAGYM="KOGA", SAFFRONGYM="SABRINA",
          CINNABARGYM="BLAINE", VIRIDIANGYM="GIOVANNI",
      }
      if not gold then return rby[id] end
      local gsc = {
          VIOLETGYM="FALKNER", AZALEAGYM="BUGSY", GOLDENRODGYM="WHITNEY",
          ECRUTEAKGYM="MORTY", CIANWOODGYM="CHUCK", OLIVINEGYM="JASMINE",
          MAHOGANYGYM="PRYCE", BLACKTHORNGYM="CLAIR",
          VERMILIONGYM="LT SURGE", SAFFRONGYM="SABRINA", CERULEANGYM="MISTY",
          CELADONGYM="ERIKA", FUCHSIAGYM="JANINE", PEWTERGYM="BROCK",
          CINNABARGYM="BLAINE", VIRIDIANGYM="BLUE",
      }
      return gsc[id]
  end

  mod.exports.__beta26.gymLockCleared = function(game, mapId)
      local save = game and game.save or currentSave
      local leader = mod.exports.__beta26.gymLeaderForMap(mapId, game)
      if not (save and leader) then return true end -- unknown Gym: fail open
      if mod.exports.__beta26.runtimeIsGold(game) then
          return gscProgress(save)[leader] == true
      end
      return gymProgress(save)[leader] == true
  end

  mod.exports.__beta26.dungeonFamily = function(mapId)
      local rawMapId = tostring(mapId or ""):upper()
      if mod.exports.nuzlocke and mod.exports.nuzlocke.content
          and mod.exports.nuzlocke.content.dungeonFamily then
          local ok, family = pcall(mod.exports.nuzlocke.content.dungeonFamily, rawMapId)
          if ok and family then return family end
      end
      local id = rawMapId:gsub("[^A-Z0-9]", "")

      -- Dungeon families describe traversable dungeon maps, not every service
      -- building whose engine id happens to share a nearby landmark prefix.
      -- In R/B/Y the Route 4 Pokemon Center beside Mt. Moon can be exposed as
      -- an MT_MOON-prefixed map by some map/provider paths. Prefix-only
      -- classification therefore trapped the player inside the Center.
      -- Fail this class of adjacent service interiors open before matching
      -- dungeon prefixes. This is intentionally generic so another
      -- dungeon-adjacent Center/Mart cannot inherit the same bug.
      if id:find("POKECENTER", 1, true)
          or id:find("POKEMONCENTER", 1, true)
          or id:find("PKMNCENTER", 1, true)
          or id:find("POKEMART", 1, true)
          or id:find("POKEMONMART", 1, true)
          or id:find("PKMNMART", 1, true) then
          return nil
      end

      local families = {
          { "MTMOON", "MT_MOON" }, { "ROCKTUNNEL", "ROCK_TUNNEL" },
          { "SEAFOAMISLAND", "SEAFOAM_ISLANDS" }, { "VICTORYROAD", "VICTORY_ROAD" },
          { "DIGLETTSCAVE", "DIGLETTS_CAVE" }, { "UNIONCAVE", "UNION_CAVE" },
          { "ILEXFOREST", "ILEX_FOREST" }, { "ICEPATH", "ICE_PATH" },
          { "DARKCAVE", "DARK_CAVE" }, { "WHIRLISLAND", "WHIRL_ISLANDS" },
          { "MTMORTAR", "MT_MORTAR" }, { "TOHJOFALLS", "TOHJO_FALLS" },
      }
      for _, row in ipairs(families) do
          if id:find("^" .. row[1]) then return row[2] end
      end
      return nil
  end

  mod.exports.__beta26.dungeonLockActive = function(game)
      if mod.save:get("nuzlocke_enabled", true) ~= true
          or mod.save:get("dungeon_lock_in", false) ~= true then return false end
      local source = game and game.overworld and game.overworld.map
          and game.overworld.map.id
          or game and game.save and game.save.player and game.save.player.map
      local family = mod.exports.__beta26.dungeonFamily(source)
      local state = mod.save:get("nuzlocke_dungeon_lock_state", nil)
      return family ~= nil and type(state) == "table" and state.family == family
  end

  -- 2.3.21 transient-world-state reconciliation.
  -- Dungeon lock ownership is valid only while the player is physically in
  -- the dungeon family that created it. A compatible map/teleport provider
  -- may move the player without traversing warp.destination, so validate the
  -- saved transient record against the engine's actual entered map as well.
  -- This mirrors the rule used by the normal warp state machine but catches
  -- out-of-band transitions and prevents stale state from surviving them.
  mod.exports.__beta26.reconcileDungeonLockState = function(game, mapId)
      local state = mod.save:get("nuzlocke_dungeon_lock_state", nil)
      if type(state) ~= "table" then return false end

      if mod.save:get("nuzlocke_enabled", true) ~= true
          or mod.save:get("dungeon_lock_in", false) ~= true then
          mod.save:set("nuzlocke_dungeon_lock_state", nil)
          return true
      end

      local currentFamily = mod.exports.__beta26.dungeonFamily(mapId)
      if currentFamily == nil or currentFamily ~= state.family then
          mod.save:set("nuzlocke_dungeon_lock_state", nil)
          return true
      end
      return false
  end

  mod.events:on("map.entered", function(ev)
      local mapId = ev and ev.mapId
          or currentGame and currentGame.overworld and currentGame.overworld.map
              and currentGame.overworld.map.id
      if mapId ~= nil then
          mod.exports.__beta26.reconcileDungeonLockState(currentGame, mapId)
      end
  end)

  mod.exports.__beta26.lockInRejection = function(game, kind)
      local key = kind == "gym" and "gym_lock_in" or "dungeon_lock_in"
      mod.exports.__beta26.pushWorldText(
          game, mod.exports.__beta26.worldRuleText(game, key))
  end

  mod.exports.__beta26.lockInBounce = function(game, sourceMap)
      local ow = game and game.overworld
      local player = ow and ow.player
      local map = ow and ow.map
      local x = tonumber(player and player.cellX) or tonumber(game and game.save
          and game.save.player and game.save.player.x) or 0
      local y = tonumber(player and player.cellY) or tonumber(game and game.save
          and game.save.player and game.save.player.y) or 0
      local facing = tostring(player and player.facing or game and game.save
          and game.save.player and game.save.player.facing or "down")
      local dx, dy = 0, 0
      if facing == "up" then dy = 1 elseif facing == "down" then dy = -1
      elseif facing == "left" then dx = 1 elseif facing == "right" then dx = -1 end
      local bx, by = x + dx, y + dy
      if map and type(map.inBounds) == "function" and not map:inBounds(bx, by) then
          bx, by = x, y
      end
      return sourceMap, bx, by
  end

  -- Enforce after downstream warp providers have resolved their destination.
  -- warp.destination is a pure resolver, so calling next() first has no world
  -- side effects; this lets Nuzlocke classify the FINAL composed destination
  -- instead of an intermediate one. High priority makes this wrapper the outer
  -- policy layer while still giving every downstream provider one normal pass.
  mod.hooks:wrap("warp.destination", function(next, destMap, x, y, ctx)
      local resolvedMap, resolvedX, resolvedY = next(destMap, x, y, ctx)
      local game = currentGame
      if not (game and game.save) then
          return resolvedMap, resolvedX, resolvedY
      end
      if mod.save:get("nuzlocke_enabled", true) ~= true then
          if mod.save:get("nuzlocke_dungeon_lock_state", nil) ~= nil then
              mod.save:set("nuzlocke_dungeon_lock_state", nil)
          end
          return resolvedMap, resolvedX, resolvedY
      end
      local sourceMap = game.overworld and game.overworld.map and game.overworld.map.id
          or game.save.player and game.save.player.map
      if not sourceMap then return resolvedMap, resolvedX, resolvedY end
      sourceMap = tostring(sourceMap):upper()
      destMap = tostring(resolvedMap or ""):upper()
      x, y = resolvedX, resolvedY

      if mod.save:get("gym_lock_in", false) == true then
          local leader = mod.exports.__beta26.gymLeaderForMap(sourceMap, game)
          if leader and destMap ~= sourceMap
              and not mod.exports.__beta26.gymLockCleared(game, sourceMap) then
              mod.exports.__beta26.lockInRejection(game, "gym")
              if type(ctx) == "table" then ctx.nuzlockeLockBlocked = "gym" end
              return mod.exports.__beta26.lockInBounce(game, sourceMap)
          end
      end

      local sourceFamily = mod.exports.__beta26.dungeonFamily(sourceMap)
      local destFamily = mod.exports.__beta26.dungeonFamily(destMap)
      local state = mod.save:get("nuzlocke_dungeon_lock_state", nil)
      if mod.save:get("dungeon_lock_in", false) ~= true then
          if state ~= nil then mod.save:set("nuzlocke_dungeon_lock_state", nil) end
          return resolvedMap, resolvedX, resolvedY
      end

      if not sourceFamily and destFamily then
          local warp = type(ctx) == "table" and ctx.warp or nil
          local player = game.overworld and game.overworld.player
          local entryX = tonumber(type(warp) == "table" and warp.x)
              or tonumber(player and player.cellX)
          local entryY = tonumber(type(warp) == "table" and warp.y)
              or tonumber(player and player.cellY)
          -- Store the exact exterior warp cell. Multiple cave mouths can share
          -- one outside map; comparing only the map id would seal every one of
          -- those exits and can create a softlock.
          mod.save:set("nuzlocke_dungeon_lock_state", {
              family = destFamily, entryOutside = sourceMap,
              entryX = entryX, entryY = entryY,
          })
          return resolvedMap, resolvedX, resolvedY
      end
      if sourceFamily and destFamily == sourceFamily then
          return resolvedMap, resolvedX, resolvedY
      end
      if sourceFamily and destFamily and destFamily ~= sourceFamily then
          -- 2.2.9: make the state machine exhaustive. A direct warp into
          -- another dungeon family re-seeds ownership instead of carrying
          -- stale entry state from the previous family.
          local warp = type(ctx) == "table" and ctx.warp or nil
          local player = game.overworld and game.overworld.player
          local entryX = tonumber(type(warp) == "table" and warp.x)
              or tonumber(player and player.cellX)
          local entryY = tonumber(type(warp) == "table" and warp.y)
              or tonumber(player and player.cellY)
          mod.save:set("nuzlocke_dungeon_lock_state", {
              family = destFamily, entryOutside = sourceMap,
              entryX = entryX, entryY = entryY,
          })
          return resolvedMap, resolvedX, resolvedY
      end
      if sourceFamily and not destFamily then
          if type(state) ~= "table" or state.family ~= sourceFamily
              or not state.entryOutside
              or tonumber(state.entryX) == nil or tonumber(state.entryY) == nil then
              -- 29.3.12 and older state remembered only the outside MAP, which
              -- is insufficient when one map owns multiple entrances. Fail open
              -- rather than guessing and potentially sealing every exit.
              mod.save:set("nuzlocke_dungeon_lock_state", nil)
              return resolvedMap, resolvedX, resolvedY
          end
          local sameOutside = destMap == tostring(state.entryOutside):upper()
          local sameWarp = sameOutside
              and tonumber(x) == tonumber(state.entryX)
              and tonumber(y) == tonumber(state.entryY)
          if sameWarp then
              mod.exports.__beta26.lockInRejection(game, "dungeon")
              if type(ctx) == "table" then ctx.nuzlockeLockBlocked = "dungeon" end
              return mod.exports.__beta26.lockInBounce(game, sourceMap)
          end
          -- A genuinely different exterior warp completes the lock-in, even
          -- when it lands on the same outside map through another cave mouth.
          mod.save:set("nuzlocke_dungeon_lock_state", nil)
          return resolvedMap, resolvedX, resolvedY
      end
      return resolvedMap, resolvedX, resolvedY
  end, 90000)

  -- Escape-style field moves can bypass a physical entrance warp entirely.
  -- fieldmove.eligibility is shared by Gen 1 and Gold and uses the same
  -- (moveId, ctx) contract. Dungeon Lock-In keeps its existing DIG/TELEPORT/FLY
  -- denial while active. 2.4.21 Travel Restrictions reuses this same seam so
  -- only player-invoked field moves are affected; scripted/story transportation
  -- never passes through this rule and therefore remains untouched.
  mod.hooks:wrap("fieldmove.eligibility", function(next, moveId, ctx)
      local game = currentGame or mod.game
      local id = tostring(moveId or ""):upper()
      if mod.exports.__beta26.dungeonLockActive(game)
          and (id == "DIG" or id == "TELEPORT" or id == "FLY") then
          return nil
      end
      if mod.save:get("nuzlocke_enabled", true) == true then
          local travel = math.max(0, math.min(2, math.floor(tonumber(
              mod.save:get("travel_restrictions",
                  defaultRuleValue("travel_restrictions"))) or 0)))
          if id == "FLY" and travel >= 1 then return nil end
          if id == "TELEPORT" and travel >= 2 then return nil end
      end
      return next(moveId, ctx)
  end, 100000)

  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.dungeonFamily =
          mod.exports.__beta26.dungeonFamily
      mod.exports.nuzlocke_compat.dungeonLockActive =
          mod.exports.__beta26.dungeonLockActive
      mod.exports.nuzlocke_compat.reconcileDungeonLockState =
          mod.exports.__beta26.reconcileDungeonLockState
      mod.exports.nuzlocke_compat.getDungeonLockState = function()
          local state = mod.save:get("nuzlocke_dungeon_lock_state", nil)
          if type(state) ~= "table" then return nil end
          local copy = {}
          for k, v in pairs(state) do copy[k] = v end
          return copy
      end
  end

  local function nextGscCapInfo(save, scope)
      local progress = gscProgress(save)
      local floor = 0
      for _, stage in ipairs(VersionCompat.gscStages) do
          local allowed = stage.phase == "GYM" or (stage.phase == "E4" and scope >= 2)
              or (stage.phase == "CHAMP" and scope >= 3) or (stage.phase == "POST" and scope >= 4)
          local ace = mod.exports.__beta26.liveGscStageAce(
              stage.name, stage.cap)
          if allowed and progress[stage.name] ~= true then
              return math.max(floor, ace), stage.name
          end
          if not allowed and progress[stage.name] ~= true then return 100, "MAX" end
          if progress[stage.name] == true then
              floor = math.max(floor, ace)
          end
      end
      if scope >= 4 then
          local cap, name = postgameCapInfo(save)
          if cap then return math.max(floor, cap), name end
      end
      return 100, "MAX"
  end

  local function externalLevelCapInfo(save)
      return providerCapInfo("level_caps", save, "EXTERNAL", true)
  end

  -- Kanto Reforged 1.2.0 keeps its optional soft-cap state in its own
  -- mod.save and owns the canonical cap calculation in ui/level_caps.lua.
  -- Read that state/module only after mod.find confirms KR is actually loaded.
  -- This adapter never writes KR options/save and never disables either system.
  local function kantoReforgedLevelCapInfo(save)
      local provider
      for _, id in ipairs({ "Kanto-Reforged", "kanto-reforged", "kanto_reforged" }) do
          local okFind, found = pcall(mod.find, id)
          if okFind and type(found) == "table" then provider = found break end
      end
      if not provider then return nil end

      local providerSave = provider.save
      if not (providerSave and type(providerSave.get) == "function") then return nil end
      local okEnabled, enabled = pcall(providerSave.get, providerSave, "level_caps_on", false)
      if not okEnabled or enabled ~= true then return nil end

      local okModule, LevelCaps = pcall(require, "mods.Kanto-Reforged.ui.level_caps")
      if not okModule or type(LevelCaps) ~= "table"
          or type(LevelCaps.capFor) ~= "function" then
          return nil
      end

      local game = currentGame or mod.game
      local liveSave = save or (game and game.save) or currentSave
      local data = game and game.data
      if not (liveSave and data) then return nil end

      local okCap, cap = pcall(LevelCaps.capFor, data, liveSave)
      cap = okCap and tonumber(cap) or nil
      if not cap or cap <= 0 or cap > 100 then return nil end

      return cap, "KANTO REFORGED", {
          id = provider.id or "Kanto-Reforged",
          name = provider.name or (provider.manifest and provider.manifest.name)
              or "Kanto Reforged",
          version = provider.version or (provider.manifest and provider.manifest.version)
              or "1.2.0",
          relationship = "co_owner_stricter",
          active = true,
      }
  end
  mod.exports.__beta26.kantoReforgedLevelCapInfo = kantoReforgedLevelCapInfo

  -- First compute the Nuzlocke/provider cap exactly as before. A separate
  -- wrapper then composes KR's independently active cap by taking the stricter
  -- value. This keeps every existing Nuzlocke progression calculation intact.
  local function nuzlockeLevelCapInfo(save)
      local scope = levelCapScope()
      if scope <= 0 then return 100, "MAX" end

      local externalCap, externalName = externalLevelCapInfo(save)
      if externalCap then return externalCap, externalName end

      local version = getGameVersion and getGameVersion() or "RED"
      local profile = VersionCompat.profiles[version]
      if profile and profile.family == "GSC" then
          return nextGscCapInfo(save, scope)
      end

      local badges = currentGymProgressCount(save)
      local gymCaps = currentGymLevelCaps()
      local floor = 0
      for i = 1, math.min(badges, #gymCaps) do
          floor = math.max(floor, mod.exports.__beta26.liveRbyBossAce(
              LEVEL_CAP_GYM_LEADERS[i], gymCaps[i] or 100, save))
      end
      if badges < #gymCaps then
          local leader = LEVEL_CAP_GYM_LEADERS[badges + 1] or "MAX"
          return math.max(floor, mod.exports.__beta26.liveRbyBossAce(
              leader, gymCaps[badges + 1] or 100, save)), leader
      end

      if scope >= 2 then
          local e4Cap, e4Name, e4Floor = nextEliteFourCapInfo(floor)
          if e4Cap then return e4Cap, e4Name end
          floor = e4Floor or floor
      end

      if scope >= 3 and not championDefeated() then
          return math.max(floor, mod.exports.__beta26.liveRbyBossAce(
              CHAMPION_CAP.name, CHAMPION_CAP.cap, save)), CHAMPION_CAP.name
      elseif scope >= 3 and championDefeated() then
          floor = math.max(floor, mod.exports.__beta26.liveRbyBossAce(
              CHAMPION_CAP.name, CHAMPION_CAP.cap, save))
      end

      if scope >= 4 then
          local postCap, postName = postgameCapInfo(save)
          if postCap then return math.max(floor, postCap), postName end
      end

      return 100, "MAX"
  end

  -- One authoritative calculation feeds enforcement, tracker, Trainer Card,
  -- Gym Guide text, and any other cap display. KR co-ownership is composed only
  -- while the player's Nuzlocke Level Cap Scope is active; with Nuzlocke caps
  -- OFF, KR remains solely responsible for its own soft-cap enforcement.
  local function nextLevelCapInfo(save)
      local scope = levelCapScope()
      local nuzCap, nuzName = nuzlockeLevelCapInfo(save)
      if scope <= 0 then return nuzCap, nuzName end

      local krCap, krName, kr = kantoReforgedLevelCapInfo(save)
      if not krCap then
          return nuzCap, nuzName, { source = "NUZLOCKE", kantoReforged = nil }
      end

      if krCap < nuzCap then
          return krCap, krName, {
              source = "NUZLOCKE+KANTO_REFORGED",
              effectiveOwner = kr.name,
              nuzlockeCap = nuzCap,
              kantoReforgedCap = krCap,
              kantoReforged = kr,
          }
      elseif krCap == nuzCap then
          return nuzCap, tostring(nuzName or "CAP") .. " + KR", {
              source = "NUZLOCKE+KANTO_REFORGED",
              effectiveOwner = "shared",
              nuzlockeCap = nuzCap,
              kantoReforgedCap = krCap,
              kantoReforged = kr,
          }
      end

      return nuzCap, nuzName, {
          source = "NUZLOCKE+KANTO_REFORGED",
          effectiveOwner = "Nuzlocke",
          nuzlockeCap = nuzCap,
          kantoReforgedCap = krCap,
          kantoReforged = kr,
      }
  end

  local function nextLevelCap(save)
      local cap = nextLevelCapInfo(save)
      return cap
  end

  -- Stable public read surface for HUD/status mods. It is deliberately the
  -- same calculation used by EXP/Rare Candy enforcement and our own screens.
  mod.exports.__beta26.getNextLevelCapInfo = function(save)
      local cap, boss, ownership = nextLevelCapInfo(save
          or currentSave or (currentGame and currentGame.save))
      ownership = type(ownership) == "table" and ownership or {}
      return {
          cap = cap,
          level = cap,
          boss = boss,
          name = boss,
          maximum = cap and cap >= 100 or false,
          source = ownership.source or "AUTHORITATIVE_LIVE",
          effectiveOwner = ownership.effectiveOwner,
          nuzlockeCap = ownership.nuzlockeCap,
          kantoReforgedCap = ownership.kantoReforgedCap,
          kantoReforged = ownership.kantoReforged,
      }
  end
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.getNextLevelCapInfo =
          mod.exports.__beta26.getNextLevelCapInfo
      mod.exports.nuzlocke_compat.level_cap_source =
          "provider_or_live_merged_trainer_ace"
      mod.exports.nuzlocke_compat.getNextGymTeamInfo =
          mod.exports.__beta26.getNextGymTeamInfo
      mod.exports.nuzlocke_compat.isNextGymLeaderBattleContext =
          mod.exports.__beta26.isNextGymLeaderBattleContext
      mod.exports.nuzlocke_compat.gymTeamSizeRejectionText =
          mod.exports.__beta26.gymTeamSizeRejectionText
      mod.exports.nuzlocke_compat.gym_team_size_source =
          "live_composed_trainer_party"
  end

  local function capExperienceForMon(mon, cap)
      if not mon or not cap then return nil end

      -- Prefer the live merged registries so mod-added Pokemon and custom
      -- growth curves obey the same cap as vanilla species.
      local data = currentGame and currentGame.data or require("src.core.Data")
      local pokemon = data and data.pokemon
      local species = mon.species
      local def = type(pokemon) == "table"
          and (pokemon[species] or pokemon[tostring(species or ""):upper()])
          or nil
      if not def then return nil end

      local rates = data and data.growth_rates
      local Growth = mod.exports.__beta26.getGrowthModule()
      if not Growth or type(Growth.expForLevel) ~= "function" then return nil end
      local ok, value = pcall(Growth.expForLevel, def.growthRate, cap, rates)
      if ok then return value end
      return nil
  end

  -- Provider-facing read-only EXP ceiling preflight. Canonical
  -- Experience.apply -> exp.gain remains preferred because that path preserves
  -- level-up, move-learning, evolution, notifications, and EXP Edging banking.
  do
      local expApi = mod.exports.nuzlocke and mod.exports.nuzlocke.experience
      if type(expApi) == "table" then
          local function evaluateExternalExpAward(context)
              context = type(context) == "table" and context or {}
              local game = context.game or currentGame or mod.game
              local save = context.save or (game and game.save) or currentSave
              local mon = context.mon or context.pokemon
              local requested = math.max(0,
                  math.floor(tonumber(context.amount or context.gained) or 0))
              local result = {
                  allowed=true, requested=requested, amount=requested,
                  overflow=0, cap=nil, atCap=false, edging=false,
                  banked=type(mon) == "table" and math.max(0,
                      math.floor(tonumber(mon.nuzlockeBankedExp) or 0)) or 0,
                  owner="nuzlocke_exp_cap_policy", mutates=false,
              }

              if levelCapScope() <= 0 or type(mon) ~= "table" or not save then
                  return result
              end

              local cap = nextLevelCap(save)
              if not tonumber(cap) then return result end
              cap = tonumber(cap)
              result.cap = cap
              if cap >= 100 then return result end

              result.atCap = (tonumber(mon.level) or 1) >= cap
              result.edging = not (externalRuleDelegation
                      and externalRuleDelegation("exp_edging", game))
                  and mod.save:get("exp_edging", false) == true

              if result.atCap then
                  result.amount = 0
                  result.overflow = requested
                  result.allowed = requested == 0
                  return result
              end

              local maxExp = capExperienceForMon(mon, cap)
              if not maxExp then return result end
              local currentExp = math.max(0, math.floor(tonumber(mon.exp) or 0))
              local room = math.max(0, math.floor(maxExp - currentExp))
              result.amount = math.min(requested, room)
              result.overflow = math.max(0, requested - result.amount)
              result.allowed = result.amount > 0 or requested == 0
              return result
          end
          expApi.capAward = evaluateExternalExpAward
          expApi.evaluateAward = evaluateExternalExpAward
          expApi.preflight = evaluateExternalExpAward
          if mod.exports.nuzlocke_compat then
              mod.exports.nuzlocke_compat.experience = expApi
          end
      end
  end

  ---------------------------------------------------------------------
  -- STAT EXP / DV RULES (beta.28.15)
  --
  -- Keep this implementation in a lexical block and publish the two helpers
  -- that later acquisition adapters need. This is not cosmetic: main.lua is
  -- one large Lua 5.1 function. beta.28.11 crossed Lua's 200-active-local
  -- compiler limit; this lexical block is the confirmed fix that keeps the
  -- post-release Stat EXP/DV additions below that compiler ceiling.
  ---------------------------------------------------------------------
  do
      local StatRules = {}
      local STAT_KEYS = { "hp", "attack", "defense", "speed", "special" }

      local function statExpPresetValue(ruleKey)
          local idx = math.max(0, math.min(5, math.floor(tonumber(
              mod.save:get(ruleKey, 0)) or 0)))
          return mod.exports.__beta26.statExpPresetValues[idx] or 0
      end

      local function recalcMonStats(data, mon, preserveCurrentHP)
          if type(mon) ~= "table" or not data or type(data.pokemon) ~= "table" then return end
          local def = data.pokemon[mon.species]
          if not def then return end
          local oldHP = tonumber(mon.hp) or 0
          local oldMaxHP = type(mon.stats) == "table"
              and tonumber(mon.stats.hp or mon.maxHp) or tonumber(mon.maxHp)
          local wasFullHP = oldMaxHP ~= nil and oldHP >= oldMaxHP

          -- Gold species have split Special Attack / Special Defense and must
          -- use the Gen 2 mon calculator.  The old shared helper always called
          -- src.pokemon.Stats, which is a Gen 1 shape and could silently apply
          -- difficulty Stat EXP/DVs through the wrong calculation path.
          local base = type(def.baseStats) == "table" and def.baseStats or nil
          local splitSpecial = base and (base.specialAttack ~= nil
              or base.specialDefense ~= nil)
          if splitSpecial then
              local okMon, Mon = pcall(require, "src.battle.gen2.Mon")
              if not okMon or type(Mon) ~= "table"
                  or type(Mon.refreshStats) ~= "function" then return end
              Mon.refreshStats(mon, data)
          else
              local ok, Stats = pcall(require, "src.pokemon.Stats")
              if not ok or type(Stats) ~= "table"
                  or type(Stats.calc) ~= "function" then return end
              mon.stats = Stats.calc(def, tonumber(mon.level) or 1,
                  mon.dvs or {}, mon.statExp or {})
          end

          local newMax = type(mon.stats) == "table" and tonumber(mon.stats.hp)
              or tonumber(mon.maxHp)
          if not newMax then return end
          mon.maxHp = splitSpecial and newMax or mon.maxHp
          if preserveCurrentHP then
              -- A full-health gift/starter should stay full after a rule raises
              -- its max HP; a damaged catch keeps its actual battle damage.
              mon.hp = wasFullHP and newMax or math.min(newMax, oldHP)
          else
              mon.hp = newMax
          end
      end

      local function applyPerfectDVs(mon)
          if type(mon) ~= "table" then return end
          -- HP DV is 15 when all four stored Gen 1/2 DVs are 15. Keep hp in
          -- the normalized table too because Gen1Recomp Stats.calc reads it.
          mon.dvs = { hp = 15, attack = 15, defense = 15, speed = 15, special = 15 }
      end

      function StatRules.applyDVFloor(mon, floor)
          if type(mon) ~= "table" then return end
          floor = math.max(0, math.min(15, math.floor(tonumber(floor) or 0)))
          if floor <= 0 then return end
          local dvs = type(mon.dvs) == "table" and mon.dvs or {}
          for _, key in ipairs({ "attack", "defense", "speed", "special" }) do
              dvs[key] = math.max(floor, math.min(15,
                  math.floor(tonumber(dvs[key]) or 0)))
          end
          -- Gen 1/2 HP DV is composed from the low bits of the four stored DVs.
          dvs.hp = (dvs.attack % 2) * 8 + (dvs.defense % 2) * 4
              + (dvs.speed % 2) * 2 + (dvs.special % 2)
          mon.dvs = dvs
      end

      function StatRules.applyStarting(data, mon, statRule, perfectRule, preserveCurrentHP)
          if type(mon) ~= "table" then return end
          if mod.save:get("nuzlocke_enabled", true) == false then return end
          local amount = statExpPresetValue(statRule)
          mon.statExp = mon.statExp or {}
          for _, key in ipairs(STAT_KEYS) do mon.statExp[key] = amount end
          if mod.save:get(perfectRule, false) == true then applyPerfectDVs(mon) end
          recalcMonStats(data, mon, preserveCurrentHP == true)
      end

      function StatRules.applyPlayer(game, mon)
          game = game or currentGame or mod.game
          local data = game and game.data or (currentGame and currentGame.data)
          StatRules.applyStarting(data, mon, "player_start_stat_exp", "perfect_player_ivs", true)
      end

      -- Built-in Game Difficulty owns trainer creation stats independently of
      -- Nuzlocke rules.  Keep the implementation beside the ordinary Stat EXP
      -- helpers so Gen 1 and Gold use one canonical DV/Stat EXP calculator.
      function StatRules.applyDifficulty(data, mon, selected, preserveCurrentHP)
          if type(mon) ~= "table" or type(selected) ~= "table" then return end
          if tostring(selected.id or "vanilla") == "vanilla"
              or selected.external == true then return end
          local taggedPreset = tonumber(mon.nuzlockeDifficultyStatExp)
          local preset = math.max(0, math.min(5,
              math.floor(taggedPreset ~= nil and taggedPreset
                  or tonumber(selected.statExp) or 0)))
          local amount = mod.exports.__beta26.statExpPresetValues[preset] or 0
          mon.statExp = mon.statExp or {}
          for _, key in ipairs(STAT_KEYS) do mon.statExp[key] = amount end
          local perfect = mon.nuzlockeDifficultyPerfectIV
          if perfect == nil then perfect = selected.perfectIV == true end
          if perfect == true then
              applyPerfectDVs(mon)
          else
              StatRules.applyDVFloor(mon,
                  mon.nuzlockeDifficultyDvFloor or selected.dvFloor)
          end
          mon.nuzlockeDifficultyProfile = selected.id
          mon.nuzlockeDifficultyStatExp = preset
          mon.nuzlockeDifficultyPerfectIV = perfect == true
          recalcMonStats(data, mon, preserveCurrentHP == true)
      end

      -- Catches and compatible provider transactions expose the exact Pokemon.
      mod.events:on("pokemon.received", function(ev)
          if ev and ev.mon then StatRules.applyPlayer(ev.game or currentGame, ev.mon) end
      end)
      mod.events:on("pokemon.caught", function(ev)
          if ev and ev.mon then StatRules.applyPlayer(ev.game or currentGame, ev.mon) end
      end)

      local function installPokemonStatRules()
          if mod.exports.__beta26.isSaveEditorSession() then return true end
          local okBattle, BattleState = pcall(require, "src.battle.BattleState")
          if okBattle and type(BattleState) == "table" then
              if type(BattleState.newWild) == "function"
                  and not (BattleState.__nuzlockeStatWildOwner == mod
                      and BattleState.newWild == BattleState.__nuzlockeStatWildFunction) then
                  if BattleState.__nuzlockeStatWildOwner ~= nil
                      and BattleState.__nuzlockeStatWildOwner ~= mod
                      and BattleState.newWild == BattleState.__nuzlockeStatWildFunction
                      and type(BattleState.__nuzlockeStatWildPrevious) == "function" then
                      BattleState.newWild = BattleState.__nuzlockeStatWildPrevious
                  end
                  local previousWild = BattleState.newWild
                  local wildWrapper = function(game, species, level, opts)
                      local battle = previousWild(game, species, level, opts)
                      local mon = battle and battle.enemy and battle.enemy.mon
                      if mon then
                          StatRules.applyStarting(game and game.data, mon,
                              "wild_start_stat_exp", "perfect_wild_ivs", false)
                          if battle.enemy then
                              battle.enemy.curStats = mon.stats
                              battle.enemy.shownHP = mon.hp
                          end
                      end
                      return battle
                  end
                  BattleState.newWild = wildWrapper
                  BattleState.__nuzlockeStatWildOwner = mod
                  BattleState.__nuzlockeStatWildFunction = wildWrapper
                  BattleState.__nuzlockeStatWildPrevious = previousWild
              end

              if type(BattleState.newTrainer) == "function"
                  and not (BattleState.__nuzlockeStatTrainerOwner == mod
                      and BattleState.newTrainer == BattleState.__nuzlockeStatTrainerFunction) then
                  if BattleState.__nuzlockeStatTrainerOwner ~= nil
                      and BattleState.__nuzlockeStatTrainerOwner ~= mod
                      and BattleState.newTrainer == BattleState.__nuzlockeStatTrainerFunction
                      and type(BattleState.__nuzlockeStatTrainerPrevious) == "function" then
                      BattleState.newTrainer = BattleState.__nuzlockeStatTrainerPrevious
                  end
                  local previousTrainer = BattleState.newTrainer
                  local trainerWrapper = function(game, oppClass, partyIndex)
                      local battle = previousTrainer(game, oppClass, partyIndex)
                      local difficulty = mod.exports.__beta26.Difficulty
                      local selected = type(difficulty) == "table"
                          and type(difficulty.selected) == "function"
                          and difficulty.selected() or nil
                      local difficultyOwns = type(selected) == "table"
                          and tostring(selected.id or "vanilla") ~= "vanilla"
                      for _, mon in ipairs((battle and battle.enemyParty) or {}) do
                          -- VANILLA leaves the independent Nuzlocke trainer-stat
                          -- controls authoritative.  Any selected difficulty
                          -- profile owns trainer construction instead; external
                          -- providers are never overwritten by our stat rules.
                          if not difficultyOwns then
                              StatRules.applyStarting(game and game.data, mon,
                                  "trainer_start_stat_exp", "perfect_trainer_ivs", false)
                          end
                          StatRules.applyDifficulty(game and game.data, mon,
                              selected, false)
                      end
                      local activeMon = battle and battle.enemyParty
                          and battle.enemyParty[battle.enemyIndex or 1]
                      if activeMon and battle.enemy and battle.enemy.mon == activeMon then
                          battle.enemy.curStats = activeMon.stats
                          battle.enemy.shownHP = activeMon.hp
                      end
                      return battle
                  end
                  BattleState.newTrainer = trainerWrapper
                  BattleState.__nuzlockeStatTrainerOwner = mod
                  BattleState.__nuzlockeStatTrainerFunction = trainerWrapper
                  BattleState.__nuzlockeStatTrainerPrevious = previousTrainer
              end
          end

          -- Experience.apply mutates Stat EXP before the public exp.gain hook.
          -- Zero only the defeated base-stat award before predecessor mutation.
          local okExp, Experience = pcall(require, "src.battle.Experience")
          if okExp and type(Experience) == "table" and type(Experience.apply) == "function"
              and not (Experience.__nuzlockeStatExpOwner == mod
                  and Experience.apply == Experience.__nuzlockeStatExpFunction) then
              if Experience.__nuzlockeStatExpOwner ~= nil
                  and Experience.__nuzlockeStatExpOwner ~= mod
                  and Experience.apply == Experience.__nuzlockeStatExpFunction
                  and type(Experience.__nuzlockeStatExpPrevious) == "function" then
                  Experience.apply = Experience.__nuzlockeStatExpPrevious
              end
              local previousApply = Experience.apply
              local expWrapper = function(data, mon, defeatedDef, level, isTrainer, numParticipants, traded)
                  if mod.save:get("nuzlocke_enabled", true) == false
                      or mod.save:get("no_player_stat_exp_gain", false) ~= true
                      or type(mon) ~= "table" or type(defeatedDef) ~= "table" then
                      return previousApply(data, mon, defeatedDef, level, isTrainer, numParticipants, traded)
                  end
                  local blockedDef = {}
                  for k, v in pairs(defeatedDef) do blockedDef[k] = v end
                  blockedDef.baseStats = { hp = 0, attack = 0, defense = 0, speed = 0, special = 0 }
                  return previousApply(data, mon, blockedDef, level, isTrainer, numParticipants, traded)
              end
              Experience.apply = expWrapper
              Experience.__nuzlockeStatExpOwner = mod
              Experience.__nuzlockeStatExpFunction = expWrapper
              Experience.__nuzlockeStatExpPrevious = previousApply
          end
          return true
      end

      mod.exports.__beta26.StatRules = StatRules
      pcall(installPokemonStatRules)
      mod.events:on("game.ready", function() pcall(installPokemonStatRules) end)
      mod.events:on("save.loaded", function() pcall(installPokemonStatRules) end)
      mod.events:on("mods.loaded", function() pcall(installPokemonStatRules) end)
  end

  -- GAME DIFFICULTY is deliberately independent from Nuzlocke Loadout.
  -- Historical choices are documented, conservative *inspired* profiles: they
  -- reproduce difficulty characteristics that Gen1Recomp exposes safely rather
  -- than claiming byte-identical ROM-hack trainer tables. External providers
  -- remain capability-first and may supply their own composed trainer.party.
  local Difficulty = {}
  local function difficultyGameKey()
      local g = currentGame or mod.game
      local id = tostring((g and (g.id or g.gameId or g.version or g.name)) or ""):lower()
      if id:find("yellow",1,true) then return "yellow" end
      if id:find("gold",1,true) or id:find("gen2",1,true) then return "gold" end
      if id:find("blue",1,true) then return "blue" end
      return "red"
  end
  -- Built-ins intentionally advertise only dimensions this mod actually
  -- enforces.  Historical names marked * are inspired profiles, not cloned
  -- trainer tables.  Every transformation is applied over the live composed
  -- trainer party so registry/content mods remain the base instead of being
  -- overwritten wholesale.
  --
  -- levelPct / bossLevelPct: ordinary/boss trainer level scaling.
  -- statExp / perfectIV: trainer creation stats.
  -- teamChance / bossTeamChance / bstBoost: deterministic same-type roster
  --   upgrades selected from the live merged species registry.
  -- moveTier: 0 vanilla, 1 level-up optimization, 2 + damaging TM/HM candidates,
  --   3 aggressive competitive-style scoring over the same legal live pool.
  -- aiTier: native Gen 1 scoring layers or Gold AI bitfields.
  -- heldTier: Gold-only held-item enrichment; existing provider items win.
