  mod.exports.__beta26.detectDifficultyProviders = function()
      local found, seen = {}, {}
      local historical = { stronger_trainers=true, ironmon_ultimate=true, indigo_conference=true }
      local function add(id)
          id = tostring(id or ""):lower():gsub("[^a-z0-9_%-]", "_")
          if id == "" or id == "nuzlocke" or seen[id] then return end
          local ok, other = pcall(mod.find, id)
          -- 2.3.30: historical IDs are recognition hints, not evidence that a
          -- provider is installed. Earlier code allowed historical[id] alone
          -- to create a provider row after mod.find() returned nil, producing
          -- phantom Indigo Conference / IronMON multi-mod warnings.
          if not ok or other == nil then return end
          local exports = other.exports
          local d = type(exports)=="table" and (exports.nuzlocke_difficulty or exports.difficulty_profiles) or nil
          local caps = type(exports)=="table" and providerValue(exports, "level_caps") or nil
          local trainer = type(exports)=="table" and providerValue(exports, "trainer_party") or nil
          if historical[id] or d ~= nil or caps ~= nil or trainer ~= nil then
              seen[id]=true
              table.insert(found, { id="mod:"..id, providerId=id, name=((other and other.name) or id).." [MOD]", profiles=d, level_caps=caps, external=true })
          end
      end
      local function scan(node, depth)
          if type(node)~="table" or depth>4 then return end
          local state=tostring(node.state or ""):lower()
          if state~="disabled" and state~="errored" and state~="blocked" then add(node.id or node.modId) end
          for _,child in pairs(node) do if type(child)=="table" then scan(child, depth+1) end end
      end
      scan((currentGame or mod.game) and (currentGame or mod.game).modStatus, 0)
      -- Known historical trainer-provider IDs are queried directly, but
      -- add() now requires mod.find() to resolve a real loaded provider.
      -- The allowlist can recognize an installed legacy mod; it can never
      -- synthesize one merely because its ID is known to Nuzlocke.
      for id in pairs(historical) do add(id) end
      for id in pairs(mod.exports.__beta26.compat.Mods.discovered or {}) do add(id) end
      table.sort(found, function(a,b) return tostring(a.name) < tostring(b.name) end)
      return found
  end
  mod.exports.__beta26.difficultyOptions = function()
      local out = { {id="vanilla", name="VANILLA"}, Difficulty.medium }
      for _,row in ipairs(Difficulty.historical[difficultyGameKey()] or {}) do table.insert(out,row) end
      for _,row in ipairs(mod.exports.__beta26.detectDifficultyProviders()) do table.insert(out,row) end
      return out
  end
  local function difficultyOptionById(options, id)
      id = type(id) == "string" and id or nil
      if not id or id == "" then return nil, nil end
      for index, row in ipairs(options or {}) do
          if type(row) == "table" and tostring(row.id or "") == id then
              return row, index - 1
          end
      end
      return nil, nil
  end

  -- 2.2.17: External trainer/difficulty mods are engine-level actors, so
  -- choosing VANILLA or a built-in Nuzlocke profile cannot disable their own
  -- hooks. Make that composition explicit at the selector instead of letting a
  -- built-in label imply exclusive ownership.
  mod.exports.__beta26.difficultyStackWarning = function(selectedId)
      local options = mod.exports.__beta26.difficultyOptions()
      local selected = difficultyOptionById(options, selectedId)
      selected = selected or options[1]
      local selectedExternal = selected and selected.external == true
      local active = mod.exports.__beta26.detectDifficultyProviders()
      local others = {}
      for _, provider in ipairs(active or {}) do
          if not selectedExternal or tostring(provider.id) ~= tostring(selected.id) then
              others[#others + 1] = provider
          end
      end
      if #others == 0 then return nil end

      local names = {}
      for _, provider in ipairs(others) do
          names[#names + 1] = tostring(provider.name or provider.providerId
              or provider.id or "EXTERNAL TRAINER MOD")
      end
      local providerNames = table.concat(names, ", ")
      local selectedName = tostring((selected and selected.name) or "VANILLA")

      if selectedExternal then
          return tostring(Strings(
              "MULTI-MOD WARNING: %s is also active. Selecting %s makes that provider authoritative to Nuzlocke, but Nuzlocke cannot disable the other trainer mod's own hooks. Their trainer changes may still compose.",
              providerNames, selectedName))
      end
      if tostring(selected and selected.id or "vanilla") == "vanilla" then
          return tostring(Strings(
              "WARNING: %s is active. VANILLA disables only Nuzlocke's built-in Difficulty transforms; it does not disable the external trainer mod, so trainer battles may still be modified.",
              providerNames))
      end
      return tostring(Strings(
          "STACK WARNING: %s is active. Its trainer changes remain in the composed base party, and %s can transform that result again. Select the trainer mod's [MOD] Difficulty entry or disable the mod to avoid stacking.",
          providerNames, selectedName))
  end

  Difficulty.selection = function()
      local opts = mod.exports.__beta26.difficultyOptions()
      local storedId = mod.save:get("difficulty_provider_id", nil)
      if type(storedId) == "string" and storedId ~= "" then
          local row, idx = difficultyOptionById(opts, storedId)
          if row then
              return row, {
                  requestedId = storedId, activeId = row.id,
                  index = idx, available = true, fallback = false,
              }
          end
          return opts[1], {
              requestedId = storedId, activeId = "vanilla",
              index = 0, available = false, fallback = true,
          }
      end

      -- Legacy saves predate the stable provider/profile ID. Interpret their
      -- numeric index exactly once against today's list, then persist that ID.
      -- After this bootstrap, dynamic provider ordering is never authoritative.
      local idx = math.max(0, math.floor(tonumber(
          mod.save:get("difficulty_profile", 0)) or 0))
      local row = opts[idx + 1] or opts[1]
      local id = tostring(row and row.id or "vanilla")
      mod.save:set("difficulty_provider_id", id)
      return row or opts[1], {
          requestedId = id, activeId = id,
          index = row and (idx < #opts and idx or 0) or 0,
          available = true, fallback = false, migratedIndex = true,
      }
  end

  Difficulty.selected = function()
      local row = Difficulty.selection()
      return row
  end

  Difficulty.indexForSelection = function()
      local _, state = Difficulty.selection()
      return state and state.index or 0
  end

  Difficulty.optionById = function(id)
      return difficultyOptionById(mod.exports.__beta26.difficultyOptions(), id)
  end
  Difficulty.profileSummary = function(row)
      if type(row) ~= "table" then return "" end
      if row.external == true then
          return tostring(Strings("ACTIVE DIFFICULTY: %s — external provider.",
              tostring(row.name or row.id or "MOD")))
      end
      if tostring(row.id or "vanilla") == "vanilla" then
          return tostring(Strings("ACTIVE DIFFICULTY: VANILLA — no built-in trainer transforms."))
      end

      local function n(value, fallback)
          value = tonumber(value)
          if value == nil then return fallback or 0 end
          return math.floor(value + 0.5)
      end
      local function pair(key)
          return n(Difficulty.profileValue(row, false, key)),
              n(Difficulty.profileValue(row, true, key))
      end
      local level, bossLevel = pair("levelPct")
      local team, bossTeam = pair("teamChance")
      local bst, bossBst = pair("bstBoost")
      local moves, bossMoves = pair("moveTier")
      local ai, bossAi = pair("aiTier")
      local stat, bossStat = pair("statExp")
      local dv, bossDv = pair("dvFloor")
      local held, bossHeld = pair("heldTier")
      local labels = mod.exports.__beta26.statExpPresetLabels or {}
      local statLabel = tostring(Strings(labels[math.max(0, math.min(5, stat))] or "0%"))
      local bossStatLabel = tostring(Strings(labels[math.max(0, math.min(5, bossStat))] or "0%"))
      local perfect = Difficulty.profileValue(row, false, "perfectIV") == true
      local bossPerfect = Difficulty.profileValue(row, true, "perfectIV") == true

      local parts = {
          tostring(Strings("ACTIVE: %s", tostring(row.name or row.id))),
          tostring(Strings("LV %d%%/%d%%  TEAM %d%%/%d%%  BST +%d/+%d",
              level, bossLevel, team, bossTeam, bst, bossBst)),
          tostring(Strings("MOVES T%d/T%d  AI T%d/T%d  STAT EXP %s/%s",
              moves, bossMoves, ai, bossAi, statLabel, bossStatLabel)),
      }
      if perfect or bossPerfect then
          parts[#parts + 1] = tostring(Strings("DVs %s/%s",
              perfect and "PERFECT" or ("FLOOR " .. tostring(dv)),
              bossPerfect and "PERFECT" or ("FLOOR " .. tostring(bossDv))))
      elseif dv > 0 or bossDv > 0 then
          parts[#parts + 1] = tostring(Strings("DV FLOOR %d/%d", dv, bossDv))
      end
      if held > 0 or bossHeld > 0 then
          parts[#parts + 1] = tostring(Strings("GOLD HELD T%d/T%d", held, bossHeld))
      end
      if row.noBadgeBoosts == true then
          parts[#parts + 1] = tostring(Strings("BADGE BOOSTS: OFF"))
      end
      if type(row.note) == "string" and row.note ~= "" then
          parts[#parts + 1] = tostring(Strings(row.note))
      end
      parts[#parts + 1] = tostring(Strings(
          "* Inspired behavior only; live composed trainer data remains the base."))
      return table.concat(parts, "\n")
  end
  mod.exports.__beta26.difficultyProfileSummary = function(id)
      local row = Difficulty.optionById(id)
      if not row then row = Difficulty.selected() end
      return Difficulty.profileSummary(row)
  end
  Difficulty.isBoss = function(classId)
      local id = tostring(classId or ""):upper()
      return Difficulty.BOSSES[id] == true
  end

  Difficulty.profileValue = function(selected, boss, key)
      if type(selected) ~= "table" or type(key) ~= "string" then return nil end
      if boss then
          local bossKey = "boss" .. key:sub(1, 1):upper() .. key:sub(2)
          if selected[bossKey] ~= nil then return selected[bossKey] end
      end
      return selected[key]
  end

  Difficulty.hash = function(text)
      local value = 5381
      text = tostring(text or "")
      for i = 1, #text do
          value = (value * 33 + text:byte(i)) % 2147483647
      end
      return value
  end

  Difficulty.sameType = function(a, b)
      if type(a) ~= "table" or type(b) ~= "table" then return false end
      local seen = {}
      for _, value in ipairs(a) do seen[tostring(value)] = true end
      for _, value in ipairs(b) do
          if seen[tostring(value)] then return true end
      end
      return false
  end

  Difficulty.completeSpecies = function(game, species)
      local def = speciesDefinition(game, species)
      if type(def) ~= "table" or type(def.baseStats) ~= "table"
          or type(def.types) ~= "table" or #def.types == 0 then return nil end
      -- A difficulty party must never create a species whose battle art is not
      -- present in the live merged registry.  This is especially important for
      -- optional Gen 2 species providers running under R/B/Y.
      if not def.spriteFront or not def.spriteBack then return nil end
      if mod.exports.__beta26.getGlitchSpeciesInfo(game, species).isGlitch then return nil end
      return def
  end

  Difficulty.chooseSpecies = function(game, baseSpecies, selected, classId,
      partyIndex, slotIndex, boss)
      if type(selected) ~= "table" then return baseSpecies end
      local classKey = tostring(classId or ""):upper()
      -- Rival starter identity is story state, not a difficulty dimension.
      -- Keep all rival species stable while still upgrading their levels,
      -- moves, stats and AI.
      if classKey:find("RIVAL", 1, true) then return baseSpecies end
      local chance = tonumber(Difficulty.profileValue(
          selected, boss, "teamChance")) or 0
      if chance <= 0 then return baseSpecies end
      local roll = Difficulty.hash(table.concat({selected.id or "", classKey,
          tostring(partyIndex or 1), tostring(slotIndex or 1), "species"}, ":")) % 100
      if roll >= chance then return baseSpecies end

      local baseDef = Difficulty.completeSpecies(game, baseSpecies)
      local baseBst = mod.exports.__beta26.getSpeciesBST(game, baseSpecies)
      local data = game and game.data
      local registry = data and data.pokemon
      if not baseDef or not baseBst or type(registry) ~= "table" then
          return baseSpecies
      end
      local target = baseBst + (tonumber(Difficulty.profileValue(
          selected, boss, "bstBoost")) or 0) + (boss and 12 or 0)
      local maxBst = math.min(600, target + (boss and 55 or 40))
      local candidates = {}
      for species, def in pairs(registry) do
          if type(species) == "string" and type(def) == "table"
              and Difficulty.completeSpecies(game, species)
              and not isLegendarySpecies(game, species)
              and not isMythicalSpecies(game, species)
              and Difficulty.sameType(baseDef.types, def.types) then
              local bst = mod.exports.__beta26.getSpeciesBST(game, species)
              if bst and bst >= baseBst and bst <= maxBst then
                  candidates[#candidates + 1] = {
                      species = species, bst = bst,
                      distance = math.abs(bst - target),
                  }
              end
          end
      end
      if #candidates == 0 then return baseSpecies end
      table.sort(candidates, function(a, b)
          if a.distance ~= b.distance then return a.distance < b.distance end
          if a.bst ~= b.bst then return a.bst > b.bst end
          return tostring(a.species) < tostring(b.species)
      end)
      local top = math.min(5, #candidates)
      local pick = 1 + (Difficulty.hash(table.concat({selected.id or "",
          classKey, tostring(partyIndex or 1), tostring(slotIndex or 1),
          "pick"}, ":")) % top)
      return candidates[pick].species or baseSpecies
  end

  Difficulty.currentMoveIds = function(mon, gold)
      local out = {}
      for _, move in ipairs((type(mon) == "table" and mon.moves) or {}) do
          -- Provider-created Gen 1 rows may already use the richer {id, pp}
          -- shape, while Gold always does. Accept both without assuming which
          -- generation supplied the party.
          local id = type(move) == "table" and move.id or move
          if type(id) == "string" then out[#out + 1] = id end
      end
      return out
  end

  Difficulty.copyParty = function(party)
      if type(party) ~= "table" then return party end
      local out = {}
      -- Preserve provider metadata/non-array keys attached to the party itself.
      for key, value in pairs(party) do out[key] = value end
      for index, mon in ipairs(party) do
          if type(mon) ~= "table" then
              out[index] = mon
          else
              local copy = {}
              for key, value in pairs(mon) do copy[key] = value end
              if getmetatable(mon) ~= nil then setmetatable(copy, getmetatable(mon)) end
              -- Moves are the only nested record this transform replaces/read-
              -- modifies. Copy it too so a provider/shared trainer record is
              -- never changed by a Difficulty preview or a repeated battle.
              if type(mon.moves) == "table" then
                  copy.moves = {}
                  for moveIndex, move in ipairs(mon.moves) do
                      if type(move) == "table" then
                          local moveCopy = {}
                          for key, value in pairs(move) do moveCopy[key] = value end
                          if getmetatable(move) ~= nil then
                              setmetatable(moveCopy, getmetatable(move))
                          end
                          copy.moves[moveIndex] = moveCopy
                      else
                          copy.moves[moveIndex] = move
                      end
                  end
              end
              out[index] = copy
          end
      end
      if getmetatable(party) ~= nil then setmetatable(out, getmetatable(party)) end
      return out
  end

  Difficulty.movePool = function(game, species, level, current, tier)
      local def = speciesDefinition(game, species)
      local moves = game and game.data and game.data.moves
      if type(def) ~= "table" or type(moves) ~= "table" then return {} end
      local pool, seen, currentSet = {}, {}, {}
      for _, id in ipairs(current or {}) do currentSet[id] = true end
      local function add(id)
          if type(id) ~= "string" or seen[id] or type(moves[id]) ~= "table" then return end
          seen[id] = true
          pool[#pool + 1] = id
      end
      for _, id in ipairs(current or {}) do add(id) end
      for _, id in ipairs(def.level1Moves or {}) do add(id) end
      for _, row in ipairs(def.learnset or {}) do
          if type(row) == "table" and (tonumber(row.level) or 0) <= (level or 1) then
              add(row.move)
          end
      end
      for _, row in ipairs(def.levelMoves or {}) do
          if type(row) == "table" and (tonumber(row.level) or 0) <= (level or 1) then
              add(row.move)
          end
      end
      if (tonumber(tier) or 0) >= 2 then
          -- Higher difficulty tiers may add compatible damaging TM/HM moves.
          -- Do not inject an arbitrary status TM whose effect implementation
          -- may differ by generation/provider; native/current status moves
          -- remain in the pool above and can still be retained by scoring.
          for _, id in ipairs(def.tmhm or {}) do
              local move = moves[id]
              if type(move) == "table" and (tonumber(move.power) or 0) > 0 then
                  add(id)
              end
          end
      end
      return pool, currentSet
  end

  Difficulty.moveScore = function(game, species, moveId, currentSet, tier)
      local data = game and game.data
      local move = data and data.moves and data.moves[moveId]
      local def = speciesDefinition(game, species)
      if type(move) ~= "table" or type(def) ~= "table" then return -9999 end
      local power = tonumber(move.power) or 0
      local accuracy = tonumber(move.accuracy)
      if not accuracy or accuracy <= 0 then accuracy = 100 end
      local score
      if power > 0 then
          score = power * math.min(100, accuracy) / 100
          for _, t in ipairs(def.types or {}) do
              if tostring(t) == tostring(move.type) then score = score + 24 break end
          end
          score = score + math.max(-7, math.min(7, tonumber(move.priority) or 0)) * 8
          if move.highCrit == true then score = score + 8 end
          local effect = tostring(move.effect or ""):upper()
          if effect:find("SELFDESTRUCT", 1, true) then score = score - 80 end
          if effect:find("RECHARGE", 1, true) or effect:find("HYPER_BEAM", 1, true) then
              score = score - ((tonumber(tier) or 0) >= 3 and 5 or 18)
          end
      else
          score = (tonumber(tier) or 0) >= 2 and 38 or 18
          local effect = tostring(move.effect or ""):upper()
          if effect:find("SLEEP", 1, true) or effect:find("PARAL", 1, true)
              or effect:find("TOXIC", 1, true) then score = score + 24 end
          if effect:find("HEAL", 1, true) or effect:find("RECOVER", 1, true)
              or effect:find("LIGHT_SCREEN", 1, true)
              or effect:find("REFLECT", 1, true) then score = score + 22 end
          if effect:find("ATTACK_UP", 1, true) or effect:find("SP_ATK_UP", 1, true)
              or effect:find("SPEED_UP", 1, true) then score = score + 16 end
      end
      if currentSet and currentSet[moveId] then score = score + 10 end
      return score
  end

  Difficulty.buildMoves = function(game, species, level, current, tier,
      selected, classId, partyIndex, slotIndex)
      tier = math.max(0, math.min(3, math.floor(tonumber(tier) or 0)))
      if tier <= 0 then return current end
      local pool, currentSet = Difficulty.movePool(game, species, level, current, tier)
      local ranked = {}
      for _, id in ipairs(pool) do
          ranked[#ranked + 1] = {
              id = id,
              score = Difficulty.moveScore(game, species, id, currentSet, tier),
              tie = Difficulty.hash(table.concat({selected and selected.id or "",
                  tostring(classId or ""), tostring(partyIndex or 1),
                  tostring(slotIndex or 1), id}, ":")),
          }
      end
      table.sort(ranked, function(a, b)
          if a.score ~= b.score then return a.score > b.score end
          if a.tie ~= b.tie then return a.tie < b.tie end
          return a.id < b.id
      end)
      local out = {}
      for i = 1, math.min(4, #ranked) do out[#out + 1] = ranked[i].id end
      return #out > 0 and out or current
  end

  Difficulty.setMoves = function(game, mon, ids, gold)
      if type(mon) ~= "table" or type(ids) ~= "table" or #ids == 0 then return end
      if not gold then
          mon.moves = ids
          return
      end
      local moves = game and game.data and game.data.moves or {}
      mon.moves = {}
      for _, id in ipairs(ids) do
          local def = moves[id]
          if type(def) == "table" then
              mon.moves[#mon.moves + 1] = {
                  id = id, pp = tonumber(def.pp) or 0,
                  maxPp = tonumber(def.pp) or 0,
              }
          end
      end
  end

  Difficulty.heldItem = function(game, mon, selected, classId, partyIndex,
      slotIndex, boss)
      local tier = math.max(0, math.min(3,
          math.floor(tonumber(Difficulty.profileValue(
              selected, boss, "heldTier")) or 0)))
      if tier <= 0 or type(mon) ~= "table" or mon.item ~= nil then return nil end
      local items = game and game.data and game.data.items
      if type(items) ~= "table" then return nil end
      local def = speciesDefinition(game, mon.species)
      local candidates = {}
      local function add(id)
          if id and items[id] then candidates[#candidates + 1] = id end
      end
      if boss and tier >= 3 then
          add("LEFTOVERS"); add("MIRACLEBERRY"); add("GOLD_BERRY")
      elseif boss and tier >= 2 then
          add("GOLD_BERRY"); add("MIRACLEBERRY")
      elseif boss and tier >= 1 then
          add("BERRY")
      end
      if type(def) == "table" then
          for _, t in ipairs(def.types or {}) do add(Difficulty.TYPE_ITEMS[t]) end
      end
      if tier >= 2 then add("BERRY") end
      if #candidates == 0 then return nil end
      local pick = 1 + (Difficulty.hash(table.concat({selected.id or "",
          tostring(classId or ""), tostring(partyIndex or 1),
          tostring(slotIndex or 1), "item"}, ":")) % #candidates)
      return candidates[pick]
  end

  Difficulty.composeParty = function(classId, partyIndex, party)
      local selected = Difficulty.selected()
      if not selected or selected.id == "vanilla" or selected.external then return party end
      if type(party) ~= "table" then return party end
      -- The Gen 1 hook receives the merged trainer table by reference. 2.2.11
      -- scaled that table in place, so a second construction (or merely a cap
      -- preview) could scale the already-scaled roster again. Treat downstream
      -- composition as immutable input and return a transformed copy instead.
      party = Difficulty.copyParty(party)
      local game = currentGame or mod.game
      local gold = mod.exports.__beta26.runtimeIsGold(game)
      local boss = Difficulty.isBoss(classId)
      local pct = tonumber(Difficulty.profileValue(
          selected, boss, "levelPct")) or 100
      for slotIndex, mon in ipairs(party) do
          if type(mon) == "table" then
              local field = mon.level ~= nil and "level" or (mon.lvl ~= nil and "lvl" or nil)
              if field then
                  local base = tonumber(mon[field])
                  if base then
                      mon[field] = math.max(1, math.min(100,
                          math.floor(base * pct / 100 + 0.5)))
                  end
              end
              local species = mon.species
              if species then
                  local upgraded = Difficulty.chooseSpecies(game, species, selected,
                      classId, partyIndex, slotIndex, boss)
                  if upgraded then mon.species = upgraded end
                  local current = Difficulty.currentMoveIds(mon, gold)
                  local ids = Difficulty.buildMoves(game, mon.species,
                      tonumber(mon[field or "level"]) or tonumber(mon.level) or 1,
                      current, Difficulty.profileValue(selected, boss, "moveTier"),
                      selected, classId, partyIndex, slotIndex)
                  Difficulty.setMoves(game, mon, ids, gold)
                  if gold then
                      local item = Difficulty.heldItem(game, mon, selected,
                          classId, partyIndex, slotIndex, boss)
                      if item then mon.item = item end
                  end
              end
              mon.nuzlockeDifficultyProfile = selected.id
              mon.nuzlockeDifficultyStatExp = Difficulty.profileValue(
                  selected, boss, "statExp")
              mon.nuzlockeDifficultyPerfectIV = Difficulty.profileValue(
                  selected, boss, "perfectIV") == true
              mon.nuzlockeDifficultyDvFloor = Difficulty.profileValue(
                  selected, boss, "dvFloor")
              mon.nuzlockeDifficultyTeam = (tonumber(Difficulty.profileValue(
                  selected, boss, "teamChance")) or 0) > 0
              mon.nuzlockeDifficultyMoves = tonumber(Difficulty.profileValue(
                  selected, boss, "moveTier")) or 0
              mon.nuzlockeDifficultyHeld = gold and (tonumber(
                  Difficulty.profileValue(selected, boss, "heldTier")) or 0) or 0
          end
      end
      return party
  end

  Difficulty.mergeBits = function(a, b)
      a, b = math.max(0, math.floor(tonumber(a) or 0)),
          math.max(0, math.floor(tonumber(b) or 0))
      local out, bit = 0, 1
      while a > 0 or b > 0 do
          if (a % 2) >= 1 or (b % 2) >= 1 then out = out + bit end
          a, b, bit = math.floor(a / 2), math.floor(b / 2), bit * 2
      end
      return out
  end

  Difficulty.applyBadgeBoostPolicy = function(game, battle)
      if type(battle) ~= "table" then return end
      local selected = Difficulty.selected()

      -- 2.4.17: Badge Boosts is now a normal saved battle-mechanics rule.
      -- ON preserves native behavior. OFF feeds the same proven suppression
      -- seam used by historical difficulty profiles. Composition is
      -- intentionally restrictive: if either the player rule disables boosts
      -- or the selected internal difficulty profile disables them, boosts stay
      -- disabled. External difficulty providers are not inspected or rewritten.
      local badgeBoostsEnabled = mod.save:get("badge_boosts",
          defaultRuleValue("badge_boosts")) == true
      local profileDisablesBadgeBoosts = type(selected) == "table"
          and selected.external ~= true and selected.noBadgeBoosts == true
      if not badgeBoostsEnabled or profileDisablesBadgeBoosts then
          battle.nuzlockeDisableBadgeBoosts = true
          -- Gen 1 battlers carry a private copy of the player's owned badge
          -- set, so clearing that copy removes the four battle-only stat boosts
          -- without touching the save or overworld badge ownership.
          if not mod.exports.__beta26.runtimeIsGold(game)
              and type(battle.player) == "table" then
              battle.player.badges = nil
          end
      end
  end

  Difficulty.applyBattleAI = function(game, battle)
      local selected = Difficulty.selected()
      if type(battle) ~= "table" then return end
      if type(selected) ~= "table" or selected.id == "vanilla"
          or selected.external == true then return end
      local trainer = battle.trainer
      local classId = battle.oppClass or battle.trainerClass
          or (type(trainer) == "table"
              and (trainer.classId or trainer.class or trainer.id))
      local boss = Difficulty.isBoss(classId)
      local tier = math.max(0, math.min(3,
          math.floor(tonumber(Difficulty.profileValue(
              selected, boss, "aiTier")) or 0)))
      if tier <= 0 then return end
      if mod.exports.__beta26.runtimeIsGold(game) then
          if type(trainer) ~= "table" then return end
          local attrs = {}
          for i, value in ipairs(trainer.attributes or {}) do attrs[i] = value end
          for i = #attrs + 1, 8 do attrs[i] = 0 end
          local existing = (tonumber(attrs[4]) or 0) + (tonumber(attrs[5]) or 0) * 256
          local wanted = Difficulty.GOLD_AI[tier] or 0
          if boss and tier >= 3 then wanted = Difficulty.mergeBits(wanted, 0x0200) end
          local flags = Difficulty.mergeBits(existing, wanted)
          attrs[4], attrs[5] = flags % 256, math.floor(flags / 256) % 256
          trainer.attributes = attrs
          battle.nuzlockeDifficultyAI = flags
      else
          local desired = tier == 1 and {1}
              or (tier == 2 and {1, 3} or {1, 2, 3})
          if boss and tier == 1 then desired = {1, 3} end
          local out, seen = {}, {}
          for _, value in ipairs(battle.enemyAIMods or {}) do
              local key = tostring(value)
              if not seen[key] then seen[key] = true; out[#out + 1] = value end
          end
          for _, value in ipairs(desired) do
              local key = tostring(value)
              if not seen[key] then seen[key] = true; out[#out + 1] = value end
          end
          battle.enemyAIMods = out
          battle.nuzlockeDifficultyAI = tier
      end
  end

  Difficulty.applyTrainerStats = function(game, mon)
      local selected = Difficulty.selected()
      local rules = mod.exports.__beta26.StatRules
      if type(rules) == "table" and type(rules.applyDifficulty) == "function" then
          rules.applyDifficulty(game and game.data, mon, selected, false)
      end
  end

  Difficulty.installGoldMechanics = function()
      local game = currentGame or mod.game
      if not mod.exports.__beta26.runtimeIsGold(game) then return true end
      local ok, Battle = pcall(require, "src.battle.gen2.Battle")
      if not ok or type(Battle) ~= "table" then return false end

      if type(Battle.battleStat) == "function"
          and not (Battle.__nuzlockeDifficultyStatOwner == mod
              and Battle.battleStat == Battle.__nuzlockeDifficultyStatFunction) then
          if Battle.__nuzlockeDifficultyStatOwner ~= nil
              and Battle.__nuzlockeDifficultyStatOwner ~= mod
              and Battle.battleStat == Battle.__nuzlockeDifficultyStatFunction
              and type(Battle.__nuzlockeDifficultyStatPrevious) == "function" then
              Battle.battleStat = Battle.__nuzlockeDifficultyStatPrevious
          end
          local previous = Battle.battleStat
          local wrapper = function(self, mon, key)
              if self and self.nuzlockeDisableBadgeBoosts == true then
                  return (mon and mon.stats and mon.stats[key]) or 1
              end
              return previous(self, mon, key)
          end
          Battle.battleStat = wrapper
          Battle.__nuzlockeDifficultyStatOwner = mod
          Battle.__nuzlockeDifficultyStatFunction = wrapper
          Battle.__nuzlockeDifficultyStatPrevious = previous
      end

      if type(Battle.badgeTypeBoost) == "function"
          and not (Battle.__nuzlockeDifficultyTypeOwner == mod
              and Battle.badgeTypeBoost == Battle.__nuzlockeDifficultyTypeFunction) then
          if Battle.__nuzlockeDifficultyTypeOwner ~= nil
              and Battle.__nuzlockeDifficultyTypeOwner ~= mod
              and Battle.badgeTypeBoost == Battle.__nuzlockeDifficultyTypeFunction
              and type(Battle.__nuzlockeDifficultyTypePrevious) == "function" then
              Battle.badgeTypeBoost = Battle.__nuzlockeDifficultyTypePrevious
          end
          local previous = Battle.badgeTypeBoost
          local wrapper = function(self, attacker, moveType)
              if self and self.nuzlockeDisableBadgeBoosts == true then return false end
              return previous(self, attacker, moveType)
          end
          Battle.badgeTypeBoost = wrapper
          Battle.__nuzlockeDifficultyTypeOwner = mod
          Battle.__nuzlockeDifficultyTypeFunction = wrapper
          Battle.__nuzlockeDifficultyTypePrevious = previous
      end
      return true
  end

  -- 2.3.10: deferred until lifecycle events for boot safety.
  mod.events:on("game.ready", function() pcall(Difficulty.installGoldMechanics) end)
  mod.events:on("save.loaded", function() pcall(Difficulty.installGoldMechanics) end)
  mod.events:on("mods.loaded", function() pcall(Difficulty.installGoldMechanics) end)

  mod.hooks:wrap("trainer.party", function(next, classId, partyIndex, party)
      local resolved=next(classId,partyIndex,party) or party
      return Difficulty.composeParty(classId,partyIndex,resolved)
  end, 90000)
  mod.exports.__beta26.Difficulty = Difficulty

  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.detectDifficultyProviders = mod.exports.__beta26.detectDifficultyProviders
      mod.exports.nuzlocke_compat.difficultyOptions = mod.exports.__beta26.difficultyOptions
      mod.exports.nuzlocke_compat.selectedDifficulty = function()
          local row=Difficulty.selected(); return row and row.id or "vanilla"
      end
      mod.exports.nuzlocke_compat.getDifficultySelection = function()
          local row, state = Difficulty.selection()
          local out = {}
          for k, v in pairs(state or {}) do out[k] = v end
          out.name = row and row.name or "VANILLA"
          out.external = row and row.external == true or false
          return out
      end
      mod.exports.nuzlocke_compat.currentBattleSnapshot = function(game)
          return mod.exports.__beta26.currentBattleSnapshot
              and mod.exports.__beta26.currentBattleSnapshot(game) or nil
      end
  end

  -- 2.4.38: notification frequency is presentation-only. Enforcement and
  -- EXP Edging still run on every canonical EXP transaction.
  mod.exports.__beta26.currentBattleState = function(game)
      local stack = game and game.stack
      if not (stack and type(stack.states) == "table") then return nil end
      for i = #stack.states, 1, -1 do
          local state = stack.states[i]
          if type(state) == "table" and (state.isBattleState == true
              or state.isBattle == true) then return state end
      end
      return nil
  end

  -- 2.4.81: consume newer Gen1Recomp's generation-neutral read-only
  -- BattleAPI only for compatibility/diagnostics. Rule enforcement remains
  -- on Nuzlocke's established semantic seams.
  mod.exports.__beta26.currentBattleSnapshot = function(game)
      if not game then return nil end
      local gold = game.version == "gold" or game.generation == 2
      local path = gold and "src.battle.gen2.BattleAPI" or "src.battle.BattleAPI"
      local ok, BattleAPI = pcall(require, path)
      if not ok or type(BattleAPI) ~= "table"
          or type(BattleAPI.new) ~= "function" then return nil end
      local okNew, api = pcall(BattleAPI.new, game)
      if not okNew or type(api) ~= "table"
          or type(api.snapshot) ~= "function" then return nil end
      local okSnap, snapshot = pcall(api.snapshot, api)
      return okSnap and snapshot or nil
  end

  -- 2.5.4: cap notices use one fixed policy. Show the first time EXP is
  -- actually blocked/banked by the active cap in a battle, then stay quiet
  -- for the rest of that battle.
  mod.exports.__beta26.levelCapNoticeFrequency = function()
      return 1 -- compatibility export: fixed once-per-battle policy
  end

  mod.exports.__beta26.showLevelCapNotice = function(game, mon, cap, leader, bankedNow)
      local mode = 1
      local battle = mod.exports.__beta26.currentBattleState(game)
      if battle and battle.nuzlockeLevelCapNoticeShown == true then
          return false
      end
      local who = tostring(mon and (mon.nickname or mon.species) or "Pokemon")
      local shown
      if bankedNow then
          shown = worldMessage(game,
              Strings("LEVEL CAP REACHED!\n%s stays at LV. %d; extra EXP is banked.", who, cap),
              Strings("LV. %d is the ceiling.\nExtra EXP is banked for the next cap.", cap),
              Strings("Gym Guide: %s sets the current ceiling.\nExtra EXP is banked for later.", tostring(leader)))
      else
          shown = worldMessage(game,
              Strings("LEVEL CAP REACHED!\n%s cannot go past LV. %d.", who, cap),
              Strings("Nice try.\nThe Nuzlocke says LV. %d is enough for now.", cap),
              Strings("Gym Guide: %s is expecting you at the current cap.\nLet's not hand them an overleveled surprise.", tostring(leader)))
      end
      if shown then
          if battle then battle.nuzlockeLevelCapNoticeShown = true end
          if mon then mon.nuzlockeWorldCapNotified = cap end
          if mod.exports.nuzlocke_dev and mod.exports.nuzlocke_dev.breadcrumb then
              pcall(mod.exports.nuzlocke_dev.breadcrumb, "level_cap_notice",
                  { mode=mode, cap=cap, species=mon and mon.species })
          end
      end
      return shown == true
  end

  -- Experience.apply exposes exp.gain as a public hook.  The engine's EXP
  -- hook context contains the Pokemon but not the Game/Save object, so use the
  -- save reference maintained by save.loaded/save.new_game/game.ready rather
  -- than a potentially stale game object.  The level check is authoritative:
  -- once a Pokemon is at the current cap, it gets zero EXP; below the cap, its
  -- normal EXP gain is preserved and only the amount that would cross the cap
  -- is trimmed.
  mod.hooks:wrap("exp.gain", function(next, ctx)
      if not ctx or not ctx.mon then
          return next(ctx)
      end

      if levelCapScope() <= 0 then
          return next(ctx)
      end

      -- Delegate only when the active provider says it owns enforcement.
      -- A provider that explicitly declares compose may supply the cap while
      -- this gate still enforces that shared result.
      local capProvider = activeCompatProvider("level_caps", currentGame, nil)
      local capRelationship = capProvider and
          mod.exports.__beta26.compat.Mods.relationshipFor(
              capProvider.id, "level_caps")
      if capProvider and (capRelationship == "delegate"
          or capRelationship == "exclusive") then
          return next(ctx)
      end

      local save = currentSave or (currentGame and currentGame.save)
      local cap = nextLevelCap(save)
      if not cap then
          return next(ctx)
      end

      local edging = not (externalRuleDelegation and externalRuleDelegation("exp_edging", currentGame or mod.game))
          and mod.save:get("exp_edging", false) == true
      local banked = math.max(0, math.floor(tonumber(ctx.mon.nuzlockeBankedExp) or 0))

      if (tonumber(ctx.mon.level) or 1) >= cap then
          local rawGain = next(ctx)
          local bankedNow = edging and (tonumber(rawGain) or 0) > 0
          if bankedNow then
              ctx.mon.nuzlockeBankedExp = banked
                  + math.max(0, math.floor(tonumber(rawGain) or 0))
          end
          local _, leader = nextLevelCapInfo(save)
          mod.exports.__beta26.showLevelCapNotice(
              currentGame, ctx.mon, cap, leader, bankedNow)
          return 0
      end

      local maxExp = capExperienceForMon(ctx.mon, cap)
      local currentExp = tonumber(ctx.mon.exp) or 0
      local gained = math.max(0, math.floor(tonumber(next(ctx)) or 0))
      if not maxExp then
          return gained
      end

      local allowed = math.max(0, maxExp - currentExp)
      if not edging then
          local used = math.max(0, math.min(gained, allowed))
          if gained > used then
              local _, leader = nextLevelCapInfo(save)
              mod.exports.__beta26.showLevelCapNotice(
                  currentGame, ctx.mon, cap, leader, false)
          end
          return used
      end

      -- Current battle EXP is considered first; any blocked portion and any
      -- previously banked EXP remain attached to the Pokemon. When a later cap
      -- increase creates room, the normal EXP pipeline releases as much bank as
      -- can legally fit, preserving level-up/move/evolution side effects.
      local currentUsed = math.min(gained, allowed)
      local currentBlocked = math.max(0, gained - currentUsed)
      local roomForBank = math.max(0, allowed - currentUsed)
      local bankUsed = math.min(banked, roomForBank)
      ctx.mon.nuzlockeBankedExp = math.max(0, banked - bankUsed + currentBlocked)
      if currentBlocked > 0 then
          local _, leader = nextLevelCapInfo(save)
          mod.exports.__beta26.showLevelCapNotice(
              currentGame, ctx.mon, cap, leader, true)
      end
      return currentUsed + bankUsed
  end, 1000)

  local function countTrackerCatches()
      local total = 0
      for key, entries in pairs(trackerLog()) do
          if key ~= "__LEGACY__" and type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  if type(entry) == "table" and entry.species then total = total + 1 end
              end
          end
      end
      return total
  end

  local function countCaughtAreas()
      local total = 0
      for key, value in pairs(caughtAreas()) do
          if key ~= "__LEGACY__" and value ~= nil then total = total + 1 end
      end
      return total
  end

  local function countVisitedAreas(game)
      -- Historical visited data is imported from the vanilla save on load,
      -- while future visits are recorded by map.entered/world.stepped.
      -- The current map is already synchronized by the tracker lifecycle and
      -- by getDisplayRoutes() during this same draw.
      local total = 0
      for key, value in pairs(visitedAreas()) do
          if key ~= "__LEGACY__" and value == true and isTrackedArea(key) then
              total = total + 1
          end
      end
      return total
  end

