  local function lockeRuleDisplayName(key)
      for _, cat in ipairs(ruleCategories) do
          for _, rule in ipairs(cat.rules or {}) do
              if rule.key == key then
                  return tostring(Strings(rule.shortName or rule.name or key))
              end
          end
      end
      return tostring(key or "RULE"):gsub("_", " "):upper()
  end

  local function lockeRuleValueLabel(key, value)
      if key == "level_cap_scope" then
          return ({ [0]="NONE", [1]="GYMS", [2]="E4", [3]="CHAMP", [4]="POST" })[
              math.floor(tonumber(value) or 0)] or "NONE"
      end
      return value == true and "ON" or "OFF"
  end

  LockePreset.modeMatches = function(mode, preGame)
      local preset = LockePreset.presets[mode]
      if type(preset) ~= "table" then return false end
      for key, wanted in pairs(preset) do
          -- A currently delegated rule is owned by another provider. It must
          -- neither be rewritten by the loadout nor force the Nuzlocke label
          -- to CUSTOM merely because the external owner exposes a neutral row.
          local delegated = externalRuleDelegation
              and externalRuleDelegation(key, currentGame or mod.game)
          if not delegated then
              local actual = getConfigValue(key, preGame)
              if type(wanted) == "number" then
                  if tonumber(actual) ~= wanted then return false end
              elseif (actual == true) ~= (wanted == true) then
                  return false
              end
          end
      end
      return true
  end

  LockePreset.classify = function(preGame)
      -- Prefer the exact named loadouts in visible order. CUSTOM is reserved
      -- for combinations that do not exactly match any preset footprint.
      for _, mode in ipairs({ 5, 1, 2, 3, 4 }) do
          if LockePreset.modeMatches(mode, preGame) then return mode end
      end
      return 0
  end

  LockePreset.nextMode = function(current, step)
      local order = LockePreset.cycleOrder
      local pos = 1
      current = math.floor(tonumber(current) or 0)
      for i, mode in ipairs(order) do
          if mode == current then pos = i break end
      end
      step = (tonumber(step) or 1) >= 0 and 1 or -1
      pos = ((pos - 1 + step) % #order) + 1
      return order[pos]
  end

  LockePreset.preview = function(mode, preGame)
      local changes = {}
      local preset = LockePreset.presets[mode]
      if type(preset) ~= "table" then return changes end
      for key, wanted in pairs(preset) do
          local delegated = externalRuleDelegation
              and externalRuleDelegation(key, currentGame or mod.game)
          if not delegated then
              local actual = getConfigValue(key, preGame)
              local differs = type(wanted) == "number"
                  and tonumber(actual) ~= wanted
                  or type(wanted) ~= "number"
                      and ((actual == true) ~= (wanted == true))
              if differs then
                  changes[#changes + 1] = {
                      key = key,
                      name = lockeRuleDisplayName(key),
                      from = lockeRuleValueLabel(key, actual),
                      to = lockeRuleValueLabel(key, wanted),
                  }
              end
          end
      end
      table.sort(changes, function(a, b)
          return tostring(a.name) < tostring(b.name)
      end)
      return changes
  end


  mod.exports.__beta26.configRulesLocked = function(preGame)
      -- Ordinary Rule Lock is deliberately reversible. Permanent Rule Seal
      -- remains a separate dormant/WIP path and joins the effective lock only
      -- after that feature is deliberately re-enabled.
      if getConfigValue("rule_lock", preGame) == true then return true end
      if not mod.exports.__beta26.permanentRuleSealWip
          and getConfigValue("rules_locked", preGame) == true then
          return true
      end
      return false
  end

  local function setConfigValue(key, value, preGame, preserveDormant)
      -- Use lifecycle-stable Type Locke slot tables throughout this update.
      -- Yellow 2.5.7 runtime testing showed Type Locke edits can still reach
      -- the generic error dialog even after unrelated-rule sync was hardened.
      local typeLockKeys = mod.exports.__beta26.typeLockSlotKeys()
      local typeLockDefaults = mod.exports.__beta26.typeLockSlotDefaults()
      if key == "rules_locked"
          and mod.exports.__beta26.permanentRuleSealWip then
          value = false
      end
      if not preserveDormant and externalRuleDelegation
          and externalRuleDelegation(key, currentGame or mod.game) then
          return false
      end
      if key == "difficulty_profile" then
          value = math.max(0, math.min(15, math.floor(tonumber(value) or 0)))
      elseif key == "locke_type" then
          value = math.max(0, math.min(5, math.floor(tonumber(value) or 0)))
      elseif key == "starting_money" then
          value = math.max(0, math.min(9999, math.floor(tonumber(value) or 0)))
      elseif key == "starting_pokeballs" or key == "starting_rare_candies" then
          value = math.max(0, math.min(99, math.floor(tonumber(value) or 0)))
      elseif key == "world_building_tier" then
          value = math.max(0, math.min(3, math.floor(tonumber(value) or 1)))
      elseif key == "level_cap_scope" then
          value = math.max(0, math.min(4, math.floor(tonumber(value) or 0)))
      elseif key == "dupes_mode" then
          value = math.max(0, math.min(2, math.floor(tonumber(value) or 0)))
      elseif key == "party_size_limit" then
          value = math.max(1, math.min(6, math.floor(tonumber(value) or 6)))
      elseif key == "evolution_limit" or key == "travel_restrictions" then
          value = math.max(0, math.min(2, math.floor(tonumber(value) or 1)))
      elseif key == "type_lock_mode" then
          value = math.max(0, math.min(6, math.floor(tonumber(value) or 0)))
      elseif key == "type_lock_primary" or key == "type_lock_secondary" or key == "type_lock_tertiary" or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary" then
          value = math.max(0, math.min(18, math.floor(tonumber(value) or 0)))
      elseif key == "randomizer_seed" then
          value = math.max(0, math.min(99999999,
              math.floor(tonumber(value) or 0)))
      elseif key == "random_starter_style" or key == "random_encounter_balance" then
          value = math.max(0, math.min(3, math.floor(tonumber(value) or 0)))
      elseif key == "randomizer_info_policy" then
          value = math.max(0, math.min(1, math.floor(tonumber(value) or 0)))
      elseif key == "gold_egg_encounter_mode" then
          value = math.max(0, math.min(3, math.floor(tonumber(value) or 0)))
      elseif key == "gold_bug_contest_mode" then
          value = math.max(0, math.min(2, math.floor(tonumber(value) or 0)))
      elseif key == "random_learnset_generation" then
          value = math.max(0, math.min(2, math.floor(tonumber(value) or 0)))
      elseif key == "random_species_generation" then
          value = math.max(0, math.min(3, math.floor(tonumber(value) or 0)))
      elseif key == "route_forgiveness" then
          value = math.max(0, math.min(2, math.floor(tonumber(value) or 0)))
      elseif key == "shiny_clause" then
          value = math.max(0, math.min(4, math.floor(tonumber(value) or 0)))
      elseif key == "encounter_ball_limit" then
          value = math.max(0, math.min(5, math.floor(tonumber(value) or 0)))
      elseif key == "trainer_money_multiplier" then
          value = math.max(0, math.min(8, math.floor(tonumber(value) or 4)))
      elseif key == "mt_moon_splits" or key == "safari_zone_splits" then
          value = math.max(0, math.min(1, math.floor(tonumber(value) or 0)))
      elseif key == "maximum_bst" then
          value = math.max(0, math.min(999, math.floor(tonumber(value) or 0)))
      elseif key == "player_start_stat_exp" or key == "wild_start_stat_exp"
          or key == "trainer_start_stat_exp" then
          value = math.max(0, math.min(5, math.floor(tonumber(value) or 0)))
      else
          value = value == true
      end

      if preGame then
          if not pendingNewGameRules then
              pendingNewGameRules = makeDefaultPreGameRules()
          end
          pendingNewGameRules[key] = value
          if (key == "random_starter" or key == "random_encounter_tables"
              or key == "random_learnsets") and value == true
              and mod.exports.__beta26.randomizerSeed then
              mod.exports.__beta26.randomizerSeed(pendingNewGameRules, true)
          end
          if key == "randomizer_seed" and tonumber(value) and tonumber(value) > 0 then
              pendingNewGameRules.__randomizer_legacy = nil
          end
          if key == "type_lock_draft" and value == true then
              for _, slotKey in ipairs(typeLockKeys) do pendingNewGameRules[slotKey] = nil end
          end
          if key == "type_lock_mode" then
              local mode = value
              if mode <= 0 then
                  for _, slotKey in ipairs(typeLockKeys) do pendingNewGameRules[slotKey] = nil end
              elseif pendingNewGameRules.type_lock_draft == true then
                  for i = mode + 1, #typeLockKeys do pendingNewGameRules[typeLockKeys[i]] = nil end
              else
                  for i = 1, mode do local sk=typeLockKeys[i]; if pendingNewGameRules[sk] == nil then pendingNewGameRules[sk]=defaultRuleValue(sk) end end
                  mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
              end
          elseif key == "type_lock_draft" and value == false then
              local mode = math.max(0, math.min(6, math.floor(tonumber(pendingNewGameRules.type_lock_mode) or 0)))
              for i=1,mode do local sk=typeLockKeys[i]; if pendingNewGameRules[sk]==nil then pendingNewGameRules[sk]=defaultRuleValue(sk) end end
              mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
          elseif key:match("^type_lock_") and key ~= "type_lock_mode" and key ~= "type_lock_draft" then
              mod.exports.__beta26.resolveRandomTypeLockSelection(pendingNewGameRules)
          end
          if key == "difficulty_profile" and not LockePreset.applying then
              local options = mod.exports.__beta26.difficultyOptions()
              local row = options[(tonumber(value) or 0) + 1]
              pendingNewGameRules.difficulty_provider_id = row and row.id or nil
          end
          if key ~= "locke_type" and LockePreset.managed[key]
              and not LockePreset.applying then
              pendingNewGameRules.locke_type = LockePreset.classify(true)
          end
          if key == "level_cap_scope" then
              pendingNewGameRules.hardcore_mode = value > 0
              pendingNewGameRules.elite_four_caps = value >= 2
          end
          pendingRulesDirty = true

          if key == "area_guide_enabled" then
              areaGuideEnabled = value
          end
          return
      end

      if key == "area_guide_enabled" then
          saveAreaGuideState(value)
      else
          mod.save:set(key, value)
          if key == "type_lock_draft" and value == true then
              for _, slotKey in ipairs(typeLockKeys) do mod.save:set(slotKey, nil) end
          end
          if key == "type_lock_mode" then
              local mode = value
              if mode <= 0 then
                  for _, slotKey in ipairs(typeLockKeys) do mod.save:set(slotKey, nil) end
              elseif mod.save:get("type_lock_draft", false) == true then
                  for i=mode+1,#typeLockKeys do mod.save:set(typeLockKeys[i], nil) end
              else
                  local live={type_lock_mode=mode,type_lock_draft=false}
                  for i=1,mode do local sk=typeLockKeys[i]; live[sk]=mod.save:get(sk,defaultRuleValue(sk)) end
                  mod.exports.__beta26.resolveRandomTypeLockSelection(live)
                  for i=1,#typeLockKeys do mod.save:set(typeLockKeys[i], live[typeLockKeys[i]]) end
              end
          elseif key == "type_lock_draft" and value == false then
              local mode=math.max(0,math.min(6,math.floor(tonumber(mod.save:get("type_lock_mode",0)) or 0)))
              local live={type_lock_mode=mode,type_lock_draft=false}
              for i=1,mode do local sk=typeLockKeys[i]; live[sk]=mod.save:get(sk,defaultRuleValue(sk)) end
              mod.exports.__beta26.resolveRandomTypeLockSelection(live)
              for i=1,#typeLockKeys do mod.save:set(typeLockKeys[i], live[typeLockKeys[i]]) end
          end
          if (key == "random_starter" or key == "random_encounter_tables"
              or key == "random_learnsets") and value == true
              and mod.exports.__beta26.randomizerSeed then
              mod.exports.__beta26.randomizerSeed(nil, true)
          end
          if (key == "random_encounter_tables" or key == "random_learnsets"
              or key == "randomizer_seed"
              or key == "random_learnset_generation" or key == "random_species_generation"
              or key == "random_encounter_balance")
              and mod.exports.__beta26.Randomizer then
              pcall(mod.exports.__beta26.Randomizer.applyAll,
                  currentGame or mod.game)
          end
          if (key == "type_lock_mode" or key == "type_lock_draft" or key == "type_lock_primary"
              or key == "type_lock_secondary" or key == "type_lock_tertiary"
              or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary"
              or key == "ban_legendaries" or key == "ban_mythicals"
              or key == "ban_pseudos" or key == "maximum_bst")
              and mod.exports.__beta26.Randomizer
              and type(mod.exports.__beta26.Randomizer.applyEncounters) == "function" then
              pcall(mod.exports.__beta26.Randomizer.applyEncounters,
                  currentGame or mod.game)
          end
          if key == "no_catching" then
              mod.save:set("no_catching_legacy_ambiguous_29313", nil)
          end
          if key == "difficulty_profile" then
              local options = mod.exports.__beta26.difficultyOptions()
              local row = options[(tonumber(value) or 0) + 1]
              mod.save:set("difficulty_provider_id", row and row.id or nil)
          end
          if key == "level_cap_scope" then
              mod.save:set("hardcore_mode", value > 0)
              mod.save:set("elite_four_caps", value >= 2)
          end
          if key:match("^type_lock_") and key ~= "type_lock_mode" and key ~= "type_lock_draft" and mod.save:get("type_lock_draft", false) ~= true then
              local mode=math.max(0,math.min(6,math.floor(tonumber(mod.save:get("type_lock_mode",0)) or 0)))
              local live={type_lock_mode=mode,type_lock_draft=false}
              for i=1,mode do local sk=typeLockKeys[i]; live[sk]=mod.save:get(sk,defaultRuleValue(sk)) end
              mod.exports.__beta26.resolveRandomTypeLockSelection(live)
              for i=1,#typeLockKeys do mod.save:set(typeLockKeys[i], live[typeLockKeys[i]]) end
              value=live[key]
          end
      end

      if key ~= "locke_type" and LockePreset.managed[key]
          and not LockePreset.applying then
          mod.save:set("locke_type", LockePreset.classify(false))
      end

      -- A dungeon lock is transient state, not a permanent route flag. Turning
      -- either the master switch or Dungeon Lock-In OFF must release it now so
      -- re-enabling the rule later cannot resurrect an entrance from an older
      -- ruleset state.
      if (key == "nuzlocke_enabled" and value ~= true)
          or (key == "dungeon_lock_in" and value ~= true) then
          mod.save:set("nuzlocke_dungeon_lock_state", nil)
      end

      if (key == "route_2_split" or key == "route_10_split"
          or key == "route_20_split" or key == "mt_moon_splits"
          or key == "safari_zone_splits")
          and type(mod.exports.__beta26.reprojectEncounterAreas) == "function" then
          pcall(mod.exports.__beta26.reprojectEncounterAreas)
      end

      -- Trainer Card and other live UI consumers can use this revision as a
      -- cheap invalidation signal. The actual value remains mod.save's source
      -- of truth, so toggles take effect immediately without requiring a save.
      mod.save:set("nuzlocke_rule_revision", (tonumber(mod.save:get("nuzlocke_rule_revision", 0)) or 0) + 1)

      -- Keep the title-screen representation synchronized with the active save.
      if not pendingNewGameRules then
          pendingNewGameRules = makeDefaultPreGameRules()
      end
      pendingNewGameRules[key] = value
      if key == "difficulty_profile" and not LockePreset.applying then
          -- Live changes are already persisted, but the staged/title model
          -- also carries the stable provider id. Keep both representations
          -- aligned so dynamic provider ordering cannot revive a stale id.
          pendingNewGameRules.difficulty_provider_id =
              mod.save:get("difficulty_provider_id", nil)
      end
      local syncedTypeMode = math.max(0, math.min(6, math.floor(tonumber(pendingNewGameRules.type_lock_mode) or 0)))
      pendingNewGameRules.type_lock_draft = mod.save:get("type_lock_draft", pendingNewGameRules.type_lock_draft == true) == true
      -- 2.5.6: ordinary NUZ RULES edits must never depend on a live Type Locke
      -- table reference just to mirror the active save back into title/setup state.
      -- Blue 2.5.5 runtime evidence showed this unconditional sync reaching
      -- ipairs(nil) after otherwise-valid rule writes. Preserve the canonical slot
      -- order as a local fallback so unrelated toggles remain usable even if a
      -- stale/reloaded closure does not retain the shared table reference.
      local syncTypeLockKeys = typeLockKeys
      local syncTypeLockDefaults = typeLockDefaults
      for i, slotKey in ipairs(syncTypeLockKeys) do
          if syncedTypeMode >= i then
              local raw=mod.save:get(slotKey,pendingNewGameRules[slotKey])
              local fallback = syncTypeLockDefaults[i]
              if fallback == nil then fallback = defaultRuleValue(slotKey) end
              if raw ~= nil then pendingNewGameRules[slotKey]=math.max(0,math.min(18,math.floor(tonumber(raw) or tonumber(fallback) or 0))) else pendingNewGameRules[slotKey]=nil end
          else pendingNewGameRules[slotKey]=nil end
      end
      if key ~= "locke_type" and LockePreset.managed[key]
          and not LockePreset.applying then
          pendingNewGameRules.locke_type = tonumber(mod.save:get(
              "locke_type", defaultRuleValue("locke_type")))
              or defaultRuleValue("locke_type")
      end
      if key == "level_cap_scope" then
          pendingNewGameRules.hardcore_mode = value > 0
          pendingNewGameRules.elite_four_caps = value >= 2
      end
      pendingRulesDirty = false
      if key == "infinite_rare_candies" and refreshGymGuideVisibility and currentGame then
          refreshGymGuideVisibility(currentGame)
      end
      if key == "dev_mode" and value == true
          and mod.exports.__beta26.Dev then
          mod.exports.__beta26.Dev.push("dev_mode", "enabled from NUZ RULES",
              currentGame or mod.game)
          pcall(mod.exports.__beta26.Dev.logSnapshot, "dev_mode_enabled",
              currentGame or mod.game)
      end
  end

  LockePreset.apply = function(mode, preGame)
      mode = math.max(0, math.min(5, math.floor(tonumber(mode) or 0)))

      -- CUSTOM is intentionally non-destructive: it only drops the preset label
      -- and keeps the player's current rule combination intact.
      if mode == 0 then
          setConfigValue("locke_type", 0, preGame)
          return true
      end

      local preset = LockePreset.presets[mode]
      if type(preset) ~= "table" then return false end

      LockePreset.applying = true
      for key, value in pairs(preset) do
          setConfigValue(key, value, preGame, false)
      end
      setConfigValue("locke_type", mode, preGame, true)
      LockePreset.applying = false
      return true
  end

  ---------------------------------------------------------------------
  -- SET MODE
  --
  -- Set Mode is intentionally NOT duplicated in the Nuzlocke rules.
  -- The game's native OPTIONS -> BATTLE STYLE setting is the sole source
  -- of truth.  This mod does not add a second Set Mode toggle or attempt
  -- to synchronize a duplicate setting.
  ---------------------------------------------------------------------

  ---------------------------------------------------------------------
  -- GENERIC MENU MARQUEE

  -- Keep text inside the original menu-width budget.  It waits 3 seconds
  -- before slowly scrolling back and forth.
  ---------------------------------------------------------------------
  local function marqueeText(text, width, elapsed, secondsPerStep)
      text = tostring(text or "")
      width = math.max(1, math.floor(tonumber(width) or 1))
      local okFont, Font = pcall(require, "src.render.Font")
      local spans = okFont and type(Font) == "table"
          and type(Font.split) == "function" and Font.split(text) or nil
      if type(spans) ~= "table" or #spans == 0 then
          -- Never byte-split translated text when glyph spans are unavailable.
          return text
      end
      if #spans <= width then return text end
      if (tonumber(elapsed) or 0) < 3 then
          return text:sub(spans[1].from, spans[width].to)
      end
      local maxOffset = #spans - width
      secondsPerStep = secondsPerStep or 2.4
      local step = math.floor(((tonumber(elapsed) or 0) - 3) / secondsPerStep)
      local cycle = maxOffset * 2
      local pos = 0
      if cycle > 0 then
          local phase = step % cycle
          if phase <= maxOffset then
              pos = phase
          else
              pos = cycle - phase
          end
      end
      local first = pos + 1
      local last = math.min(#spans, first + width - 1)
      return text:sub(spans[first].from, spans[last].to)
  end

  -- UI-only fold state. Keep Setup, active Rules, and generation surfaces
  -- independent, but do not put navigation preferences into gameplay saves.
  -- The state survives closing/reopening the screen for this mod session.
  local collapsedConfigSections = {}

  ---------------------------------------------------------------------
  -- VANILLA MENU SAFETY
  -- Do not monkey-patch src.ui.Menu.draw. Gen1Recomp v0.1.76 owns menu
  -- scrolling/anchoring there, and replacing the global draw method affects
  -- every title/start/submenu in the game. Our injected title/start entries
  -- intentionally use short labels (SETUP / RULES / TRACKER) instead.
  -- marqueeText remains local to Nuzlocke-owned screens only.
  ---------------------------------------------------------------------

  ---------------------------------------------------------------------
  -- ROUTE FORGIVENESS PROMPT (beta.29.3.4)
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeForgivenessPrompt", {
      new = function(game, ctx)
          local self = { game = game, isOpaque = true, cursor = 1, ctx = ctx or {} }
          function self:update(dt)
              if game.input:wasPressed("left") or game.input:wasPressed("right") then
                  self.cursor = self.cursor == 1 and 2 or 1
              elseif game.input:wasPressed("b") then
                  game.stack:pop()
                  if self.ctx.onChoice then self.ctx.onChoice(false) end
              elseif game.input:wasPressed("a") then
                  local yes = self.cursor == 1
                  game.stack:pop()
                  if self.ctx.onChoice then self.ctx.onChoice(yes) end
              end
          end
          function self:draw()
              -- Gold gets its own native 20x18 tile-grid presentation instead
              -- of the Gen 1 pixel-positioned panel. Keep the decision logic
              -- shared; only the chrome/cursor vocabulary differs.
              if mod.exports.__beta26.runtimeIsGold(game) then
                  local Chrome = require("src.ui.gen2.Chrome")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)
                  Chrome.print(Strings("FORGIVE ENCOUNTER?"), 2, 2)
                  Chrome.printWrapped(Strings("Spend 1 token to keep this area's encounter open?"),
                      2, 5, 16, 3)
                  if self.cursor == 1 then Chrome.cursor(3, 10) end
                  if self.cursor == 2 then Chrome.cursor(10, 10) end
                  Chrome.print(Strings("YES"), 4, 10)
                  Chrome.print(Strings("NO"), 11, 10)
                  local tokens = math.max(0, math.floor(tonumber(
                      mod.save:get("route_forgiveness_tokens", 0)) or 0))
                  Chrome.print(Strings("TOKENS %d", tokens), 4, 13)
                  Chrome.print(Strings("B:CANCEL"), 4, 15)
                  return
              end

              local Font = mod.ui.Font

              -- 2.4.37: true opaque modal card; battle UI may remain visible
              -- outside this frame but can never bleed through its interior.
              local x, y, w, h = 8, 10, 144, 124
              love.graphics.setColor(0.12, 0.12, 0.12, 1)
              love.graphics.rectangle("fill", x, y, w, h)
              love.graphics.setColor(0.88, 0.88, 0.88, 1)
              Font.drawBox(x, y, 18, 15)

              Font.draw(Strings("FORGIVE ENCOUNTER?"), 18, 24)
              Font.draw(Strings("Spend 1 token to keep"), 16, 46)
              Font.draw(Strings("this area's encounter"), 16, 58)
              Font.draw(Strings("open?"), 16, 70)
              Font.draw((self.cursor == 1 and "> " or "  ") .. Strings("YES"), 30, 92)
              Font.draw((self.cursor == 2 and "> " or "  ") .. Strings("NO"), 92, 92)

              local tokens = math.max(0, math.floor(tonumber(
                  mod.save:get("route_forgiveness_tokens", 0)) or 0))
              Font.draw(Strings("TOKENS: %d", tokens), 46, 112)
              love.graphics.setColor(1, 1, 1, 1)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- MANUAL-PAGED ERROR TEXT (2.5.9)
  -- Error details are diagnostic evidence. Soft wrapping more than two lines
  -- makes the native TextBox scroll automatically, which can move the useful
  -- line before a tester can capture it. Pre-wrap to two 18-column lines per
  -- explicit page so every error page waits for A/B.
  ---------------------------------------------------------------------
  mod.exports.__beta26.manualPagedErrorText = function(title, detail)
      local width = 18
      local lines = {}
      local function pushWrapped(raw)
          raw = tostring(raw or "")
          for paragraph in (raw .. "\n"):gmatch("(.-)\n") do
              paragraph = paragraph:gsub("^%s+", ""):gsub("%s+$", "")
              if paragraph ~= "" then
                  while #paragraph > width do
                      local cut = width
                      for i = width, 1, -1 do
                          if paragraph:sub(i, i) == " " then
                              cut = i
                              break
                          end
                      end
                      local part = paragraph:sub(1, cut):gsub("%s+$", "")
                      if part == "" then
                          part = paragraph:sub(1, width)
                          cut = width
                      end
                      lines[#lines + 1] = part
                      paragraph = paragraph:sub(cut + 1):gsub("^%s+", "")
                  end
                  if paragraph ~= "" then lines[#lines + 1] = paragraph end
              end
          end
      end
      pushWrapped(title or "NUZ ERROR")
      pushWrapped(detail or "unknown error")
      pushWrapped("Please report this text.")
      local pages = {}
      for i = 1, #lines, 2 do
          local page = lines[i] or ""
          if lines[i + 1] then page = page .. "\n" .. lines[i + 1] end
          pages[#pages + 1] = page
      end
      return table.concat(pages, "\f")
  end

  ---------------------------------------------------------------------
  -- LOADOUT CHANGE CONFIRMATION (2.4.18)
  -- A preset is never applied until this modal has shown the player exactly
  -- how many loadout-owned rules will change. B cancels with zero mutation.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeLoadoutConfirm", {
      new = function(game, ctx)
          ctx = ctx or {}
          local self = {
              game = game,
              screenId = "NuzlockeLoadoutConfirm",
              isOpaque = true,
              uiModLayout = "classic",
              keepClassicUi = true,
              cursor = 2, -- safe default: NO
              elapsed = 0,
              scroll = 0,
              mode = math.max(0, math.min(5, math.floor(tonumber(ctx.mode) or 0))),
              changes = type(ctx.changes) == "table" and ctx.changes or {},
              onChoice = ctx.onChoice,
          }
          function self:update(dt)
              self.elapsed = self.elapsed + (dt or 0)
              local maxScroll = math.max(0, #self.changes - 4)
              if game.input:wasPressed("up") then
                  self.scroll = math.max(0, (self.scroll or 0) - 1)
              elseif game.input:wasPressed("down") then
                  self.scroll = math.min(maxScroll, (self.scroll or 0) + 1)
              elseif game.input:wasPressed("left") or game.input:wasPressed("right") then
                  self.cursor = self.cursor == 1 and 2 or 1
              elseif game.input:wasPressed("b") then
                  game.stack:pop()
                  if self.onChoice then self.onChoice(false) end
              elseif game.input:wasPressed("a") then
                  local yes = self.cursor == 1
                  game.stack:pop()
                  if self.onChoice then self.onChoice(yes) end
              end
          end
          function self:draw()
              local name = tostring(Strings(LockePreset.names[self.mode] or "CUSTOM"))
              local count = #self.changes
              if mod.exports.__beta26.runtimeIsGold(game) then
                  local Chrome = require("src.ui.gen2.Chrome")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)
                  Chrome.print(Strings("LOADOUT WARNING"), 2, 1)
                  Chrome.printWrapped(Strings("%s will change %d loadout-owned rules.",
                      name, count), 2, 3, 16, 3)
                  local y = 7
                  local first = math.min(count + 1, (self.scroll or 0) + 1)
                  local last = math.min(count, first + 3)
                  for i = first, last do
                      local ch = self.changes[i]
                      Chrome.printWrapped(Strings("%s -> %s", ch.name, ch.to),
                          2, y, 16, 1)
                      y = y + 1
                  end
                  if count > 4 then
                      Chrome.print(Strings("%d-%d/%d UP/DN", first, last, count), 2, 11)
                  end
                  if self.cursor == 1 then Chrome.cursor(2, 14) end
                  if self.cursor == 2 then Chrome.cursor(10, 14) end
                  Chrome.print(Strings("APPLY"), 3, 14)
                  Chrome.print(Strings("CANCEL"), 11, 14)
                  Chrome.print(Strings("B:CANCEL"), 4, 16)
                  return
              end

              local Font = mod.ui.Font
              -- 2.5.8 Yellow runtime repair: keep the confirmation fully on the
              -- native 160x144 surface. Each change row gets a fixed 16-glyph
              -- budget with the destination value first; long rule names
              -- marquee inside the remaining budget instead of crossing the box.
              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 0, 0, 160, 144)
              Font.drawBox(0, 0, 20, 18)
              Font.draw(Strings("LOADOUT WARNING"), 20, 10)
              Font.draw(marqueeText(Strings("%s changes %d", name, count),
                  16, self.elapsed, 1.2), 14, 28)
              local y = 46
              local first = math.min(count + 1, (self.scroll or 0) + 1)
              local last = math.min(count, first + 3)
              for i = first, last do
                  local ch = self.changes[i]
                  local to = tostring(Strings(ch.to or ""))
                  local nameBudget = 10
                  local label = marqueeText(ch.name or ch.key or "RULE",
                      nameBudget, self.elapsed, 1.2)
                  Font.draw(Strings("%s %s", to, label), 14, y)
                  y = y + 12
              end
              if count > 4 then
                  Font.draw(Strings("%d-%d/%d UP/DN", first, last, count), 14, 96)
              end
              Font.draw((self.cursor == 1 and "> " or "  ") .. Strings("APPLY"), 22, 116)
              Font.draw((self.cursor == 2 and "> " or "  ") .. Strings("CANCEL"), 84, 116)
          end
          return self
      end,
  })

  ---------------------------------------------------------------------
  -- REGISTER CONFIG SCREEN
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeConfigScreen", {
      new = function(game, ctx)
          local preGame = ctx and ctx.preGame == true
          local autoNewGame = ctx and ctx.autoNewGame == true
          -- Gold and R/B/Y share this screen, but their supported rule
          -- surfaces are intentionally different. Resolve the mode from the
          -- explicit caller hint first, then from the live game. B9 left this
          -- lexical undefined, which made Gold render the R/B/Y setup surface.
          local goldMode = (ctx and ctx.goldMode == true)
              or mod.exports.__beta26.runtimeIsGold(game)

          if preGame and not pendingNewGameRules then
              pendingNewGameRules = loadSetupProfileFromDisk()
                  or makeDefaultPreGameRules()
          elseif not preGame then
              discoverAllKnownAreas(game)
              -- The active save is authoritative when entering the in-game menu.
              if not pendingRulesDirty then
                  pendingNewGameRules = makeRulesFromCurrentSave()
              end
              areaGuideEnabled =
                  pendingNewGameRules.area_guide_enabled ~= false
          end

          local allItemList = buildFlatItemList(preGame, goldMode)
          local collapseSurface = (preGame and "setup:" or "rules:")
              .. (goldMode and "gold" or "rby")
          collapsedConfigSections[collapseSurface] =
              collapsedConfigSections[collapseSurface] or {}
          local collapsedSections = collapsedConfigSections[collapseSurface]
          local flatItemList = {}

          local function sectionKey(item)
              return tostring(item and item.name or "")
          end

          local function rebuildVisibleItems(preferred)
              local visible, currentSection = {}, nil
              for _, candidate in ipairs(allItemList) do
                  if candidate.isHeader then
                      currentSection = sectionKey(candidate)
                      candidate.sectionKey = currentSection
                      visible[#visible + 1] = candidate
                  else
                      local key = candidate.rule and candidate.rule.key
                      local typeLockMode = math.max(0, math.min(6, math.floor(tonumber(getConfigValue("type_lock_mode", preGame)) or 0)))
                      local typeLockDraft = getConfigValue("type_lock_draft", preGame) == true
                      local typeSlotIndex = ({ type_lock_primary=1, type_lock_secondary=2, type_lock_tertiary=3, type_lock_quaternary=4, type_lock_quinary=5, type_lock_senary=6 })[key]
                      local hiddenByTypeLock = (key == "type_lock_draft" and typeLockMode == 0) or (typeSlotIndex ~= nil and (typeLockMode < typeSlotIndex or typeLockDraft))

                      -- 2.3.29 dependent randomizer selectors:
                      -- keep the saved child value, but hide the row entirely
                      -- while its owning randomizer is OFF. This applies to
                      -- both staged Setup values and the live in-game Rules UI.
                      local hiddenByNoCatching =
                          (key == "encounter_ball_limit"
                              and getConfigValue("no_catching", preGame) == true)

                      local hiddenByRandomizerParent =
                          (key == "random_starter_style"
                              and getConfigValue("random_starter", preGame) ~= true)
                          or ((key == "random_encounter_balance"
                                  or key == "randomizer_info_policy"
                                  or key == "random_species_generation")
                              and getConfigValue("random_encounter_tables", preGame) ~= true)
                          or (key == "random_learnset_generation"
                              and getConfigValue("random_learnsets", preGame) ~= true)

                      if not hiddenByTypeLock and not hiddenByNoCatching
                          and not hiddenByRandomizerParent
                          and (candidate.alwaysVisible
                              or currentSection == nil
                              or collapsedSections[currentSection] ~= true) then
                          visible[#visible + 1] = candidate
                      end
                  end
              end
              flatItemList = visible
              local target = 1
              if preferred then
                  for i, candidate in ipairs(flatItemList) do
                      if candidate == preferred then target = i break end
                  end
              end
              return target
          end

          local initialCursor = rebuildVisibleItems(nil)

          local self = {
              game = game,
              screenId = "NuzlockeConfigScreen",
              isOpaque = true,
              preGame = preGame,
              goldMode = goldMode,
              autoNewGame = autoNewGame,
              onDone = ctx and ctx.onDone,
              cursor = initialCursor,
              scroll = 0,
              pageSize = 3,
              descScroll = 0,
              marqueeTime = 0,
              editingNumber = false,
              digitIndex = 1,
              inGameSaveFlash = 0,
              lockConfirmStage = 0,
              lockConfirmReadyAt = 0
          }

          -- Wide Menus coexistence safety (2.1.9).
          --
          -- Wide Menus auto-widens opaque mod-owned screens unless they
          -- explicitly declare a classic layout. Merely declining claim() is
          -- not enough: fresh NEW GAME Setup is still auto-classified as wide
          -- later by the provider's Screens/StateStack hooks. Mark every
          -- NuzlockeConfigScreen instance classic up front so Setup and NUZ
          -- RULES both remain on the validated 160px/native-width path.
          self.uiModLayout = "classic"
          self.keepClassicUi = true
          self.nuzlockeUi = mod.exports.nuzlocke_ui.describeScreen(self)
          self.presentationRole = "rules"
          self.presentationStateOwner = "nuzlocke"
          self.presentationNativeFallback = true

          function self:update(dt)
              -- The title-screen setup has no active save.  Do not query or
              -- mutate save-backed map state while editing the staged setup.
              if not self.preGame then
                  local currentKey = areaKey(self.game, nil)
                  if currentKey then
                      markVisited(currentKey)
                  end
              end

              self.marqueeTime = self.marqueeTime + (dt or 0)
              if self.setupSaveFlash and self.setupSaveFlash > 0 then
                  self.setupSaveFlash = math.max(0, self.setupSaveFlash - (dt or 0))
              elseif self.setupSaveFlash and self.setupSaveFlash < 0 then
                  self.setupSaveFlash = math.min(0, self.setupSaveFlash + (dt or 0))
              end

              if self.inGameSaveFlash and self.inGameSaveFlash > 0 then
                  self.inGameSaveFlash = math.max(0, self.inGameSaveFlash - (dt or 0))
              elseif self.inGameSaveFlash and self.inGameSaveFlash < 0 then
                  self.inGameSaveFlash = math.min(0, self.inGameSaveFlash + (dt or 0))
              end

              if self.game.input:wasPressed("b") then
                  self.lockConfirmStage = 0
                  self.lockConfirmReadyAt = 0
                  if self.editingNumber then
                      self.editingNumber = false
                      self.digitIndex = 1
                      self.descScroll = 0
                  else
                      if self.preGame and self.autoNewGame then
                          saveCurrentSetupProfile()
                          stageNewGameProfile()
                          applyNewGameSnapshot()
                          commitDurableSetupProfileToActiveSave()
                      end
                      self.game.stack:pop()
                      if type(self.onDone) == "function" then
                          local cb = self.onDone
                          self.onDone = nil
                          cb()
                      end
                  end
                  return
              end

              -- Declare this before moveCursor so the closure captures the local
              -- helper instead of resolving a nonexistent global on UP/DOWN.
              local function isSelectableItem(item)
                  if not item then return false end
                  if item.isHeader then return true end
                  if item.rule and (item.rule.key == "wonderlocke"
                      or (item.rule.key == "rules_locked"
                          and mod.exports.__beta26.permanentRuleSealWip)) then
                      return false
                  end
                  return true
              end

              local function moveCursor(dir)
                  local count = #flatItemList
                  if count <= 0 then return end

                  local target = self.cursor
                  local guard = 0
                  repeat
                      target = target + dir
                      if target < 1 then
                          target = count
                      elseif target > count then
                          target = 1
                      end
                      guard = guard + 1
                      if guard > count then
                          return
                      end
                  until isSelectableItem(flatItemList[target])

                  if target ~= self.cursor then
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                  end
                  self.cursor = target
                  self.descScroll = 0
              end

              local function jumpSection(dir)
                  local count = #flatItemList
                  if count <= 0 then return false end
                  dir = tonumber(dir) or 1

                  local target = nil
                  if dir > 0 then
                      for i = self.cursor + 1, count do
                          if flatItemList[i] and flatItemList[i].isHeader then
                              target = i
                              break
                          end
                      end
                      if not target then
                          for i = 1, math.min(self.cursor, count) do
                              if flatItemList[i] and flatItemList[i].isHeader then
                                  target = i
                                  break
                              end
                          end
                      end
                  else
                      for i = self.cursor - 1, 1, -1 do
                          if flatItemList[i] and flatItemList[i].isHeader then
                              target = i
                              break
                          end
                      end
                      if not target then
                          for i = count, math.max(1, self.cursor), -1 do
                              if flatItemList[i] and flatItemList[i].isHeader then
                                  target = i
                                  break
                              end
                          end
                      end
                  end

                  if not target then return false end
                  if target ~= self.cursor then
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                  end
                  self.cursor = target
                  self.descScroll = 0
                  self.editingNumber = false
                  return true
              end

              local function setAllSectionsCollapsed(value)
                  value = value == true
                  local preferred = flatItemList[self.cursor]
                  local seen = {}
                  for _, candidate in ipairs(allItemList) do
                      if candidate and candidate.isHeader then
                          local key = candidate.sectionKey or sectionKey(candidate)
                          if not seen[key] then
                              seen[key] = true
                              collapsedSections[key] = value
                          end
                      end
                  end
                  self.cursor = rebuildVisibleItems(preferred)
                  self.scroll = math.max(0,
                      math.min(self.scroll, math.max(0, #flatItemList - 1)))
                  self.descScroll = 0
                  self.editingNumber = false
                  self.lockConfirmStage = 0
                  self.lockConfirmReadyAt = 0
                  return true
              end

              local function selectedItem()
                  return flatItemList[self.cursor]
              end

              local function refreshDependentRows(changedKey, preferred)
                  if changedKey ~= "random_starter"
                      and changedKey ~= "random_encounter_tables"
                      and changedKey ~= "random_learnsets"
                      and changedKey ~= "type_lock_mode"
                      and changedKey ~= "type_lock_draft"
                      and changedKey ~= "no_catching" then
                      return
                  end
                  self.cursor = rebuildVisibleItems(preferred)
                  self.scroll = math.max(0,
                      math.min(self.scroll, math.max(0, #flatItemList - 1)))
                  self.descScroll = 0
              end

              local function setHeaderCollapsed(item, value)
                  if not (item and item.isHeader) then return false end
                  local key = item.sectionKey or sectionKey(item)
                  if value == nil then value = collapsedSections[key] ~= true end
                  collapsedSections[key] = value == true
                  self.cursor = rebuildVisibleItems(item)
                  self.scroll = math.max(0,
                      math.min(self.scroll, math.max(0, #flatItemList - 1)))
                  self.descScroll = 0
                  self.editingNumber = false
                  self.lockConfirmStage = 0
                  self.lockConfirmReadyAt = 0
                  return true
              end

              local function activateControl(item, delta)
                  if not item or not item.isControl then return false end
                  if item.rule and item.rule.key == "rules_locked"
                      and mod.exports.__beta26.permanentRuleSealWip then
                      -- DORMANT/WIP: preserve the full activation block below,
                      -- but never enter it while the feature is disabled.
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                      return false
                  end
                  local isPermanentSeal = item.rule
                      and item.rule.key == "rules_locked"
                  if not isPermanentSeal then
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                  end
                  if item.isLockeTypeControl then
                      if mod.exports.__beta26.configRulesLocked(self.preGame) then
                          return true
                      end
                      local current = tonumber(getConfigValue("locke_type",
                          self.preGame)) or 0
                      local nextMode = LockePreset.nextMode(current, delta)
                      -- CUSTOM never changes rules, so it needs no warning.
                      if nextMode == 0 then
                          LockePreset.apply(0, self.preGame)
                          self.descScroll = 0
                          return true
                      end
                      local changes = LockePreset.preview(nextMode, self.preGame)
                      if #changes == 0 then
                          LockePreset.apply(nextMode, self.preGame)
                          self.descScroll = 0
                          return true
                      end
                      mod.ui.push(self.game, "NuzlockeLoadoutConfirm", {
                          mode = nextMode,
                          changes = changes,
                          onChoice = function(yes)
                              if yes then
                                  LockePreset.apply(nextMode, self.preGame)
                                  self.descScroll = 0
                              end
                          end,
                      })
                      return true
                  end
                  if item.isSetupSave and self.preGame then
                      local ok = saveCurrentSetupProfile()
                      self.setupSaveFlash = ok and 1.5 or -1.5
                      return true
                  end
                  if item.isInGameSave and not self.preGame then
                      local ok = saveCurrentInGameRules()
                      self.inGameSaveFlash = ok and 1.5 or -1.5
                      return true
                  end
                  if item.isRecoveryControl and not self.preGame then
                      mod.ui.push(self.game, "NuzlockeLegacyRecoveryScreen")
                      return true
                  end
                  if item.isRuleLockControl and item.rule
                      and item.rule.key == "rule_lock" then
                      setConfigValue("rule_lock",
                          not getConfigValue("rule_lock", self.preGame), self.preGame)
                      self.descScroll = 0
                      return true
                  end
                  if item.rule and item.rule.key == "rules_locked" then
                      local cur = getConfigValue("rules_locked", self.preGame)
                      if cur then return true end

                      -- Two explicit warnings are required before the third,
                      -- deliberate activation permanently seals challenge rules.
                      -- A short debounce prevents one keyboard/gamepad press from
                      -- accidentally advancing more than one stage.
                      if (self.marqueeTime or 0) < (self.lockConfirmReadyAt or 0) then
                          return true
                      end

                      if self.lockConfirmStage == 0 then
                          self.lockConfirmStage = 1
                          self.lockConfirmReadyAt = (self.marqueeTime or 0) + 0.35
                          if not self.preGame then
                              pcall(mod.exports.__beta26.pushWorldText, self.game,
                                  "PERMANENT RULE SEAL - WARNING 1/2\nThis cannot be undone on this save.\nSelect SEAL again only if you want to continue.")
                          end
                          self.descScroll = 0
                          return true
                      end

                      if self.lockConfirmStage == 1 then
                          self.lockConfirmStage = 2
                          self.lockConfirmReadyAt = (self.marqueeTime or 0) + 0.35
                          if not self.preGame then
                              pcall(mod.exports.__beta26.pushWorldText, self.game,
                                  "PERMANENT RULE SEAL - FINAL WARNING 2/2\nChallenge rules will be permanently locked.\nSelect SEAL one final time to seal them.")
                          end
                          self.descScroll = 0
                          return true
                      end

                      setConfigValue("rules_locked", true, self.preGame)
                      self.lockConfirmStage = 0
                      self.lockConfirmReadyAt = 0
                      if not self.preGame then
                          local ok = mod.exports.__beta26.persistPermanentRuleSeal(
                              self.game)
                          if ok ~= true then
                              -- mod.save still locks the current session; the
                              -- lifecycle retry below will mirror it once a
                              -- playthrough storage context becomes available.
                              mod.save:set("rules_permanently_locked", true)
                          end
                      end
                      return true
                  end
                  return false
              end

              local function canChangeSelected(item)
                  if not item or item.isHeader then
                      return false
                  end

                  -- Save/recovery controls remain usable while locked. The permanent
                  -- lock itself is monotonic: once true it cannot be toggled off.
                  if item.isControl and (item.isInGameSave or item.isSetupSave
                      or item.isRecoveryControl) then
                      return true
                  end
                  if item.isRuleLockControl and item.rule.key == "rule_lock" then
                      return true
                  end
                  if item.isControl and item.rule.key == "rules_locked" then
                      if mod.exports.__beta26.permanentRuleSealWip then
                          return false
                      end
                      return not mod.exports.__beta26.configRulesLocked(self.preGame)
                  end
                  if item.isLockeTypeControl then
                      return not mod.exports.__beta26.configRulesLocked(self.preGame)
                  end

                  if item.rule and item.rule.key == "wonderlocke" then
                      return false
                  end
                  if item.rule and externalRuleDelegation
                      and externalRuleDelegation(item.rule.key, self.game) then
                      return false
                  end
                  if item.rule and (item.rule.key == "world_building_tier"
                      or item.rule.key == "difficulty_profile"
                      or item.rule.key == "automatic_running_shoes"
                      or item.rule.key == "automatic_default_names"
                      or item.rule.key == "skip_opening_intro"
                      or item.rule.key == "quick_nuzlocke_start"
                      or item.rule.key == "skip_catch_tutorial"
                      or item.rule.key == "pc_starting_vitamins"
                      or item.rule.key == "pc_starting_heal_items"
                      or item.rule.key == "infinite_rare_candies"
                      or item.rule.key == "starting_money"
                      or item.rule.key == "starting_pokeballs"
                      or item.rule.key == "starting_rare_candies"
                      or item.rule.key == "skip_cherrygrove_tour"
                      or item.rule.key == "catch_info"
                      or item.rule.key == "stat_info"
                      or item.rule.key == "move_info"
                      or item.rule.key == "area_guide_enabled"
                      or item.rule.key == "encounter_spend_indicator"
                      or item.rule.key == "dev_mode") then
                      -- Permanent Rule Seal applies only to challenge rules.
                      -- Difficulty, World Building, QoL and presentation remain
                      -- independently adjustable after a seal.
                      return true
                  end
                  return not mod.exports.__beta26.configRulesLocked(self.preGame)
              end

              local function isStartingResourceRule(rule)
                  if not rule then return false end
                  return rule.key == "starting_money"
                      or rule.key == "starting_pokeballs"
                      or rule.key == "starting_rare_candies"
                      or rule.key == "randomizer_seed"
              end

              local function cycleNumericRule(rule, dir)
                  if not rule then return false end
                  if rule.key == "difficulty_profile" then
                      local options = mod.exports.__beta26.difficultyOptions()
                      local count = #options
                      if count <= 0 then return false end
                      local currentId = self.preGame
                          and pendingNewGameRules.difficulty_provider_id
                          or mod.save:get("difficulty_provider_id", "vanilla")
                      local _, currentIndex = difficultyOptionById(options, currentId)
                      local index = tonumber(currentIndex) or 0
                      local step = tonumber(dir) or 1
                      index = (index + step) % count
                      if index < 0 then index = index + count end
                      local row = options[index + 1] or options[1]
                      setConfigValue(rule.key, index, self.preGame)
                      if self.preGame then
                          pendingNewGameRules.difficulty_provider_id = row and row.id or "vanilla"
                      else
                          mod.save:set("difficulty_provider_id", row and row.id or "vanilla")
                          -- Difficulty is explicitly changeable mid-game.
                          -- Observed trainer ace levels belong to the previous
                          -- composition and must not pin NEXT CAP after a change.
                          if mod.exports.__beta26.levelCapBosses then
                              mod.exports.__beta26.levelCapBosses.observed = {}
                          end
                      end
                      self.descScroll = 0
                      return true
                  end
                  if rule.key == "maximum_bst" then
                      local current = tonumber(getConfigValue(
                          rule.key, self.preGame)) or 0
                      local index = mod.exports.__beta26.maximumBstPresetIndex(
                          current)
                      local step = tonumber(dir) or 1
                      index = (index + step) % 5
                      if index < 0 then index = index + 5 end
                      setConfigValue(rule.key,
                          mod.exports.__beta26.maximumBstPresetValues[index],
                          self.preGame)
                      self.descScroll = 0
                      return true
                  end
                  local minValue = tonumber(rule.min) or 0
                  local maxValue = tonumber(rule.max) or minValue
                  local current = tonumber(getConfigValue(rule.key, self.preGame)) or minValue
                  local step = tonumber(dir) or 1
                  local nextValue = current + step
                  if nextValue > maxValue then nextValue = minValue end
                  if nextValue < minValue then nextValue = maxValue end
                  setConfigValue(rule.key, nextValue, self.preGame)
                  if rule.key == "type_lock_mode" or rule.key == "type_lock_draft" then
                      refreshDependentRows(rule.key, selectedItem())
                  end
                  self.descScroll = 0
                  return true
              end

              local item = selectedItem()
              local editingAtStart = self.editingNumber

              if self.editingNumber and item and item.rule.numeric
                  and isStartingResourceRule(item.rule) then
                  local rule = item.rule
                  local value = tonumber(getConfigValue(rule.key, self.preGame)) or rule.min
                  local digits = rule.digits or 1
                  local text = ("%0" .. tostring(digits) .. "d"):format(value)

                  if self.game.input:wasPressed("left") then
                      self.digitIndex = math.max(1, self.digitIndex - 1)
                  elseif self.game.input:wasPressed("right") then
                      self.digitIndex = math.min(digits, self.digitIndex + 1)
                  elseif self.game.input:wasPressed("up") or self.game.input:wasPressed("down") then
                      local step = self.game.input:wasPressed("up") and 1 or -1
                      local chars = {}
                      for i = 1, #text do chars[i] = tonumber(text:sub(i, i)) or 0 end
                      chars[self.digitIndex] = (chars[self.digitIndex] + step) % 10
                      local newValue = tonumber(table.concat(chars)) or 0
                      if newValue >= rule.min and newValue <= rule.max then
                          setConfigValue(rule.key, newValue, self.preGame)
                      end
                  elseif self.game.input:wasPressed("a") or self.game.input:wasPressed("select") then
                      if rule.key == "randomizer_seed" and mod.exports.__beta26.randomizerSeed then
                          local anyRandomizer = getConfigValue("random_starter", self.preGame) == true
                              or getConfigValue("random_encounter_tables", self.preGame) == true
                              or getConfigValue("random_learnsets", self.preGame) == true
                          if anyRandomizer then
                              if self.preGame then
                                  mod.exports.__beta26.randomizerSeed(pendingNewGameRules, true)
                              else
                                  mod.exports.__beta26.randomizerSeed(nil, true)
                                  if mod.exports.__beta26.Randomizer then
                                      pcall(mod.exports.__beta26.Randomizer.applyAll, self.game)
                                  end
                              end
                          end
                      end
                      self.editingNumber = false
                      self.digitIndex = 1
                      self.descScroll = 0
                  end

              elseif self.game.input:wasPressed("down") then
                  local selectHeld = type(self.game.input.isDown) == "function"
                      and self.game.input:isDown("select")
                  if selectHeld then
                      jumpSection(1)
                  else
                      moveCursor(1)
                  end
              elseif self.game.input:wasPressed("up") then
                  local selectHeld = type(self.game.input.isDown) == "function"
                      and self.game.input:isDown("select")
                  if selectHeld then
                      jumpSection(-1)
                  else
                      moveCursor(-1)
                  end
              elseif self.game.input:wasPressed("right") or self.game.input:wasPressed("left") then
                  local selectHeld = type(self.game.input.isDown) == "function"
                      and self.game.input:isDown("select")
                  if item and item.isHeader and selectHeld then
                      setAllSectionsCollapsed(
                          self.game.input:wasPressed("left"))
                  elseif item and item.isHeader then
                      setHeaderCollapsed(item,
                          self.game.input:wasPressed("left"))
                  elseif item and item.isLockeTypeControl and canChangeSelected(item) then
                      activateControl(item,
                          self.game.input:wasPressed("right") and 1 or -1)
                  elseif item and item.rule and item.rule.key ~= "wonderlocke"
                      and item.rule.numeric and canChangeSelected(item) then
                      if isStartingResourceRule(item.rule) then
                          self.editingNumber = true
                          self.digitIndex = 1
                          self.descScroll = 0
                      else
                          cycleNumericRule(item.rule,
                              self.game.input:wasPressed("right") and 1 or -1)
                      end
                  elseif item and item.isControl then
                      activateControl(item)
                  elseif canChangeSelected(item) then
                      local key = item.rule.key
                      local preferred = item
                      local cur = getConfigValue(key, self.preGame)
                      setConfigValue(key, not cur, self.preGame)
                      refreshDependentRows(key, preferred)
                  end
              elseif self.game.input:wasPressed("select") then
                  if item and not item.isHeader then
                      local descLines = wrapText(ruleDescriptionForDisplay(item.rule, self.preGame), 16)
                      local maxScroll = math.max(0, #descLines - 3)
                      if maxScroll > 0 then
                          self.descScroll = (self.descScroll + 1) % (maxScroll + 1)
                      end
                  end
              end

              if self.game.input:wasPressed("a") and not editingAtStart then
                  if item and item.isHeader then
                      setHeaderCollapsed(item)
                  elseif item and item.isLockeTypeControl then
                      if canChangeSelected(item) then activateControl(item, 1) end
                  elseif item and item.isControl then
                      activateControl(item)
                  elseif item and item.rule and item.rule.key ~= "wonderlocke"
                      and item.rule.numeric and canChangeSelected(item) then
                      if isStartingResourceRule(item.rule) then
                          self.editingNumber = true
                          self.digitIndex = 1
                          self.descScroll = 0
                      else
                          cycleNumericRule(item.rule, 1)
                      end
                  elseif canChangeSelected(item) then
                      local key = item.rule.key
                      local preferred = item
                      local cur = getConfigValue(key, self.preGame)
                      setConfigValue(key, not cur, self.preGame)
                      refreshDependentRows(key, preferred)
                  end
              end
          end

          function self:draw()
              -- Gold owns a different menu language from R/B/Y. In particular,
              -- src.ui.OptionRows is explicitly not a Gen2 compatibility facade:
              -- painting the Gen 1 option chrome over Gold is an upstream-documented
              -- trap. Keep all configuration state/update logic shared, but draw the
              -- Gold surface with src.ui.gen2.Chrome's native tile boxes, cursor and
              -- down-arrow. This is presentation-only and does not change rule
              -- semantics, save keys, presets, or the protected R/B/Y screen.
              if self.goldMode then
                  local Chrome = require("src.ui.gen2.Chrome")
                  local GoldFont = require("src.render.Font")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 11)
                  Chrome.box(0, 11, 20, 7)

                  local locked = mod.exports.__beta26.configRulesLocked(self.preGame)
                  Chrome.print(self.preGame and Strings("NUZLOCKE GOLD")
                      or Strings("NUZ RULES"), 2, 1)
                  Chrome.print(self.preGame and Strings("BETA SETUP")
                      or Strings("GOLD BETA"), 2, 2)
                  if not self.preGame and locked then
                      Chrome.print(Strings("LOCKED"), 13, 1)
                  end

                  if self.cursor > self.scroll + self.pageSize then
                      self.scroll = self.cursor - self.pageSize
                  end
                  if self.cursor <= self.scroll then
                      self.scroll = math.max(0, self.cursor - 1)
                  end

                  local function clipped(text, width)
                      return marqueeText(Strings(tostring(text or "")), width,
                          self.marqueeTime, 3.8)
                  end

                  -- 2.4.28: Gold now follows the same compact-label policy as
                  -- R/B/Y. Prefer the full translated label whenever it fits.
                  -- If it does not fit, use shortName/shortTitle only when the
                  -- shorthand is safe for the active translation; otherwise
                  -- keep the translated full label and let the native Gold
                  -- marquee expose it instead of injecting an English
                  -- abbreviation into a translated menu.
                  local function goldMenuLabel(fullSource, shortSource, width)
                      local fullRaw = tostring(fullSource or "")
                      local fullText = Strings(fullRaw)
                      width = math.max(1, math.floor(tonumber(width) or 1))
                      local pixelBudget = width * 8
                      local fullFits = type(GoldFont.width) ~= "function"
                          and #fullText <= width or GoldFont.width(fullText) <= pixelBudget
                      if fullFits then return fullText end

                      if shortSource ~= nil then
                          local shortRaw = tostring(shortSource)
                          local shortText = Strings(shortRaw)
                          local fullWasTranslated = tostring(fullText) ~= fullRaw
                          local shortWasTranslated = tostring(shortText) ~= shortRaw
                          if not fullWasTranslated or shortWasTranslated then
                              local shortFits = type(GoldFont.width) ~= "function"
                                  and #shortText <= width or GoldFont.width(shortText) <= pixelBudget
                              if shortFits then return shortText end
                              return marqueeText(shortText, width, self.marqueeTime, 3.8)
                          end
                      end

                      return marqueeText(fullText, width, self.marqueeTime, 3.8)
                  end

                  local function goldValueText(item, val)
                      if item.isLockeTypeControl then
                          local mode = math.max(0, math.min(5,
                              math.floor(tonumber(val) or 0)))
                          return LockePreset.labels[mode] or "CUSTOM"
                      elseif item.isRecoveryControl then
                          local legacy = trackerLog().__LEGACY__
                          return tostring(type(legacy) == "table" and #legacy or 0)
                      elseif item.isSetupSave then
                          if self.setupSaveFlash and self.setupSaveFlash > 0 then return "SAVED" end
                          if self.setupSaveFlash and self.setupSaveFlash < 0 then return "ERROR" end
                          return "SAVE"
                      elseif item.isInGameSave then
                          if self.inGameSaveFlash and self.inGameSaveFlash > 0 then return "SAVED" end
                          if self.inGameSaveFlash and self.inGameSaveFlash < 0 then return "ERROR" end
                          return "SAVE"
                      end

                      local key = item.rule and item.rule.key
                      if not item.rule then return "" end
                      if key == "wonderlocke"
                          or (key == "rules_locked"
                              and mod.exports.__beta26.permanentRuleSealWip) then
                          return "WIP"
                      end
                      if not item.rule.numeric then
                          if key == "dev_self_test_export" then return "RUN" end
                          return val and "ON" or "OFF"
                      end
                      if key == "difficulty_profile" then
                          local options = mod.exports.__beta26.difficultyOptions()
                          local row = options[(tonumber(val) or 0) + 1]
                          return row and tostring(row.name or "VANILLA"):upper() or "VANILLA"
                      elseif key == "starting_money" then
                          return Chrome.money(tonumber(val) or 0)
                      elseif key == "world_building_tier" then
                          return ({ [0]="OFF", [1]="T1", [2]="T2", [3]="T3" })[tonumber(val) or 0] or "OFF"
                      elseif key == "level_cap_scope" then
                          return ({ [0]="NONE", [1]="GYMS", [2]="E4", [3]="CHAMP", [4]="POST" })[tonumber(val) or 0] or "NONE"
                      elseif key == "dupes_mode" then
                          return ({ [0]="OFF", [1]="SPEC", [2]="FAM" })[tonumber(val) or 0] or "OFF"
                      elseif key == "evolution_limit" then
                          return ({ [0]="NORMAL", [1]="NO FINAL", [2]="NO EVO" })[tonumber(val) or 0] or "NORMAL"
                      elseif key == "travel_restrictions" then
                          return ({ [0]="NORMAL", [1]="NO FLY", [2]="NO FLY+TP" })[tonumber(val) or 0] or "NORMAL"
                      elseif key == "shiny_clause" then
                          return ({ [0]="OFF", [1]="1", [2]="2", [3]="3", [4]="UNLIMITED" })[tonumber(val) or 4] or "UNLIMITED"
                      elseif key == "encounter_ball_limit" then
                          return ({ [0]="OFF", [1]="1", [2]="2", [3]="3", [4]="5", [5]="10" })[tonumber(val) or 0] or "OFF"
                      elseif key == "type_lock_mode" then
                          return mod.exports.__beta26.typeLockModeLabel(val)
                      elseif key == "type_lock_primary" or key == "type_lock_secondary" or key == "type_lock_tertiary" or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary" then
                          return mod.exports.__beta26.typeLockTypeLabel(val)
                      elseif key == "randomizer_seed" then
                          local seed = tonumber(val) or 0
                          return seed > 0 and ("%08d"):format(seed) or "AUTO"
                      elseif key == "random_starter_style" then
                          return ({ [0]="ANY", [1]="3-STAGE", [2]="BASE", [3]="SIM BST" })[tonumber(val) or 0] or "ANY"
                      elseif key == "random_encounter_balance" then
                          return ({ [0]="CHAOS", [1]="SIM BST", [2]="EVO", [3]="BALANCED" })[tonumber(val) or 0] or "CHAOS"
                      elseif key == "randomizer_info_policy" then
                          return ({ [0]="OPEN INFO", [1]="BLIND INFO" })[tonumber(val) or 0] or "OPEN INFO"
                      elseif key == "gold_egg_encounter_mode" then
                          return ({ [0]="OFF", [1]="RECEIVED", [2]="HATCHED", [3]="GIFT" })[tonumber(val) or 0] or "OFF"
                      elseif key == "gold_bug_contest_mode" then
                          return ({ [0]="NORMAL", [1]="EXEMPT", [2]="SLOT" })[tonumber(val) or 0] or "NORMAL"
                      elseif key == "random_learnset_generation" then
                          return ({ [0]="AUTO", [1]="GEN1", [2]="GEN2" })[tonumber(val) or 0] or "AUTO"
                      elseif key == "random_species_generation" then
                          return ({ [0]="AUTO", [1]="GEN1", [2]="GEN2", [3]="BOTH" })[tonumber(val) or 0] or "AUTO"
                      elseif key == "route_forgiveness" then
                          return ({ [0]="OFF", [1]="0", [2]="1" })[tonumber(val) or 0] or "OFF"
                      elseif key == "trainer_money_multiplier" then
                          return mod.exports.__beta26.trainerMoneyPresetLabels[
                              tonumber(val) or 4] or Strings.source("100%")
                      elseif key == "mt_moon_splits" or key == "safari_zone_splits" then
                          return ({ [0]="OFF", [1]="COMMON" })[tonumber(val) or 0] or "OFF"
                      elseif key == "player_start_stat_exp" or key == "wild_start_stat_exp"
                          or key == "trainer_start_stat_exp" then
                          return mod.exports.__beta26.statExpPresetLabels[tonumber(val) or 0] or "0%"
                      elseif key == "maximum_bst" then
                          return mod.exports.__beta26.maximumBstDisplayLabel(val)
                      end
                      return tostring(math.floor(tonumber(val) or item.rule.min or 0))
                  end

                  for slot = 1, self.pageSize do
                      local i = self.scroll + slot
                      local item = flatItemList[i]
                      if not item then break end
                      local rowY = 4 + (slot - 1) * 2
                      local selected = i == self.cursor
                      local rowWip = item.rule and (
                          item.rule.key == "wonderlocke"
                          or (item.rule.key == "rules_locked"
                              and mod.exports.__beta26.permanentRuleSealWip))
                      if selected and not rowWip then
                          Chrome.cursor(1, rowY)
                      end
                      if item.isHeader then
                          local headerText = goldMenuLabel(item.name, item.shortName, 14)
                          local headerWidth = type(GoldFont.width) == "function"
                              and GoldFont.width(headerText) or (#headerText * 8)
                          -- +1px tracking keeps the one-pixel bold echo from
                          -- visually welding adjacent glyphs together.
                          local trackedWidth = headerWidth + math.max(0, #headerText - 1)
                          local headerX = math.max(16, math.floor((144 - trackedWidth) / 2))
                          local glyphX = headerX
                          for ci = 1, #headerText do
                              local ch = headerText:sub(ci, ci)
                              GoldFont.draw(ch, glyphX, rowY * 8)
                              GoldFont.draw(ch, glyphX + 1, rowY * 8)
                              glyphX = glyphX + (type(GoldFont.width) == "function"
                                  and GoldFont.width(ch) or 8) + 1
                          end
                          local key = item.sectionKey or sectionKey(item)
                          if collapsedSections[key] then
                              Chrome.cursor(18, rowY, true)
                          else
                              GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, rowY * 8)
                          end
                      else
                          local delegated = externalRuleDelegation
                              and externalRuleDelegation(item.rule.key, self.game)
                          local rowIsWip = item.rule.key == "wonderlocke"
                              or (item.rule.key == "rules_locked"
                                  and mod.exports.__beta26.permanentRuleSealWip)
                          if rowIsWip or delegated then
                              love.graphics.setColor(0.55, 0.55, 0.55, 1)
                          end
                          -- 2.2.1: keep the wider Gold rule-label field from
                          -- 2.1.23, but pull the right-aligned value/toggle column one
                          -- native tile back from the frame. Runtime 2.1.24 testing
                          -- showed the previous edge anchor could crowd/clip the border.
                          -- Long money/type values still receive up to seven tiles.
                          Chrome.print(goldMenuLabel(item.rule.name, item.rule.shortName, 10), 2, rowY)
                          local shownValue = goldValueText(item,
                              getConfigValue(item.rule.key, self.preGame))
                          local valueText = item.rule.key == "starting_money"
                              and shownValue or clipped(shownValue, 7)
                          local valuePixels = type(GoldFont.width) == "function"
                              and GoldFont.width(valueText) or (#tostring(valueText) * 8)
                          local valueTiles = math.max(1, math.min(7,
                              math.ceil((tonumber(valuePixels) or 8) / 8)))
                          Chrome.print(valueText, math.max(12, 19 - valueTiles), rowY)
                          if rowIsWip or delegated then
                              love.graphics.setColor(1, 1, 1, 1)
                          end
                      end
                  end

                  if self.scroll + self.pageSize < #flatItemList then
                      GoldFont.drawCode(Chrome.DOWN_ARROW, 1 * 8, 9 * 8)
                  end

                  local selItem = flatItemList[self.cursor]
                  if selItem and selItem.isHeader then
                      local key = selItem.sectionKey or sectionKey(selItem)
                      Chrome.print(Strings("SEL+UD:JUMP"), 2, 12)
                      Chrome.print(Strings("SEL+LR:ALL"), 2, 14)
                      Chrome.print(Strings("A/LR:THIS"), 2, 15)
                  elseif selItem and selItem.rule then
                      local displayedDescription = ruleDescriptionForDisplay(selItem.rule, self.preGame)
                      if selItem.rule.key == "rules_locked"
                      and not mod.exports.__beta26.permanentRuleSealWip then
                          if self.lockConfirmStage == 1 then
                              displayedDescription = Strings(
                                  "WARNING 1/2: Permanent Rule Seal cannot be undone. Select SEAL again to continue, or move away/B to cancel.")
                          elseif self.lockConfirmStage == 2 then
                              displayedDescription = Strings(
                                  "FINAL WARNING 2/2: One more SEAL activation permanently locks challenge rules. Move away/B to cancel.")
                          end
                      end
                      local descLines = Chrome.wrap(displayedDescription, 16)
                      local maxScroll = math.max(0, #descLines - 4)
                      self.descScroll = math.max(0, math.min(self.descScroll or 0, maxScroll))
                      for row = 1, 4 do
                          local line = descLines[self.descScroll + row]
                          if not line then break end
                          Chrome.print(line, 2, 11 + row)
                      end
                      if self.descScroll < maxScroll then
                          GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, 15 * 8)
                      end
                      if self.editingNumber then
                          Chrome.print(Strings("A:OK B:BACK"), 7, 16)
                      elseif locked then
                          Chrome.print(Strings("RULES SEALED"), 7, 16)
                      end
                  end
                  return
              end

              local Font = mod.ui.Font
              local wideMode = self.uiModLayout == "wide"
              local menuCols = wideMode and 38 or 20
              local valueShift = wideMode and 144 or 0

              -- 2.1.4: now that the Gen1 variable-width Font path is active,
              -- measure Nuzlocke-owned text in pixels instead of character
              -- counts. Marquee scrolling is no longer the normal R/B/Y
              -- presentation; labels truncate only when they genuinely cannot
              -- fit, and descriptions wrap to the full pixel width.
              local function fitPixelText(text, budget)
                  text = Strings(tostring(text or ""))
                  budget = math.max(0, tonumber(budget) or 0)
                  if type(Font.width) ~= "function"
                      or type(Font.split) ~= "function"
                      or type(Font.spansFitting) ~= "function" then
                      return text
                  end
                  if Font.width(text) <= budget then return text end
                  local spans = Font.split(text)
                  local fit = Font.spansFitting(spans, budget)
                  if fit <= 0 then return "" end
                  return text:sub(1, spans[fit].to)
              end

              local function marqueePixelText(text, budget, elapsed, secondsPerStep)
                  text = Strings(tostring(text or ""))
                  budget = math.max(0, tonumber(budget) or 0)
                  if type(Font.width) ~= "function"
                      or type(Font.split) ~= "function"
                      or type(Font.spansFitting) ~= "function"
                      or Font.width(text) <= budget then
                      return text
                  end

                  local spans = Font.split(text)
                  if #spans == 0 then return "" end
                  local visible = math.max(1, Font.spansFitting(spans, budget))
                  if visible >= #spans then return text end

                  -- Long labels stay still briefly, then bounce by whole glyph
                  -- spans. Text that fits never enters this path at all.
                  elapsed = tonumber(elapsed) or 0
                  if elapsed < 3.0 then
                      return text:sub(1, spans[visible].to)
                  end

                  secondsPerStep = secondsPerStep or 2.4
                  local maxOffset = #spans - visible
                  local cycle = math.max(1, maxOffset * 2)
                  local step = math.floor((elapsed - 3.0) / secondsPerStep)
                  local phase = step % cycle
                  local offset = phase <= maxOffset and phase
                      or (cycle - phase)

                  local first = offset + 1
                  local last = math.min(#spans, first + visible - 1)

                  -- Because advances vary, a fixed glyph count can still run
                  -- a few pixels long after the window moves. Shrink the end
                  -- until this exact substring fits the pixel budget.
                  while last > first
                      and Font.width(text:sub(spans[first].from,
                          spans[last].to)) > budget do
                      last = last - 1
                  end
                  return text:sub(spans[first].from, spans[last].to)
              end

              local function menuLabelText(fullSource, shortSource,
                  budget, elapsed)
                  local fullRaw = tostring(fullSource or "")
                  local fullText = Strings(fullRaw)
                  if type(Font.width) ~= "function"
                      or Font.width(fullText) <= budget then
                      return fullText
                  end

                  if shortSource ~= nil then
                      local shortRaw = tostring(shortSource)
                      local shortText = Strings(shortRaw)
                      local fullWasTranslated = tostring(fullText) ~= fullRaw
                      local shortWasTranslated = tostring(shortText) ~= shortRaw

                      -- Never substitute an English shorthand into a translated
                      -- label unless that shorthand was translated too. Existing
                      -- translation packs can continue to translate the natural
                      -- canonical label and get a slow marquee if needed.
                      if not fullWasTranslated or shortWasTranslated then
                          if type(Font.width) ~= "function"
                              or Font.width(shortText) <= budget then
                              return shortText
                          end
                          return marqueePixelText(shortRaw, budget, elapsed)
                      end
                  end

                  return marqueePixelText(fullRaw, budget, elapsed)
              end

              local function wrapPixelText(text, budget)
                  text = Strings(tostring(text or ""))
                  budget = math.max(1, tonumber(budget) or 1)
                  if type(Font.width) ~= "function" then
                      return wrapText(text, math.max(1,
                          math.floor(budget / 8)))
                  end
                  local lines, line = {}, ""
                  for word in text:gmatch("%S+") do
                      local candidate = line == "" and word
                          or (line .. " " .. word)
                      if line == "" or Font.width(candidate) <= budget then
                          line = candidate
                          if Font.width(line) > budget then
                              line = fitPixelText(line, budget)
                          end
                      else
                          lines[#lines + 1] = line
                          line = word
                          -- Pathological translated single words should never
                          -- draw through the frame. Keep the UI safe rather
                          -- than reintroducing horizontal marquee behavior.
                          if Font.width(line) > budget then
                              line = fitPixelText(line, budget)
                          end
                      end
                  end
                  if line ~= "" then lines[#lines + 1] = line end
                  if #lines == 0 then lines[1] = "" end
                  return lines
              end

              Font.drawBox(0, 0, menuCols, 11)
              Font.drawBox(0, 11, menuCols, 7)

              -- Title: centred in the 160px canvas (inner X=8..152=144px wide).
              -- "NUZLOCKE RULES" = 14 chars * ~10px = 140px => start at X=10.
              -- "NZLCKE SETUP"  = 12 chars * ~10px = 120px => start at X=20.
              local locked = mod.exports.__beta26.configRulesLocked(self.preGame)
              if self.preGame then
                  if self.goldMode then
                      Font.draw(fitPixelText("NUZLOCKE GOLD",
                          wideMode and 280 or 138), 10, 10)
                      Font.draw(fitPixelText("BETA SETUP",
                          wideMode and 280 or 138), 10, 22)
                  else
                      Font.draw(fitPixelText("NUZLOCKE SETUP",
                          wideMode and 280 or 138), 10, 10)
                      Font.draw(fitPixelText("NEW GAME ONLY",
                          wideMode and 280 or 138), 10, 22)
                  end
              else
                  Font.draw(fitPixelText("NUZLOCKE RULES",
                      wideMode and 280 or 116), 10, 10)
                  if self.goldMode then Font.draw(fitPixelText("GOLD BETA", wideMode and 280 or 116), 10, 22) end
                  if locked then
                      Font.draw(Strings("[LK]"), 116 + valueShift, 10)
                  else
                      Font.draw(Strings("R1"), 136 + valueShift, 10)
                  end
              end

              if self.cursor > self.scroll + self.pageSize then
                  self.scroll = self.cursor - self.pageSize
              end

              if self.cursor <= self.scroll then
                  self.scroll = math.max(0, self.cursor - 1)
              end

              -- List starts lower in preGame to clear the two-line header.
              local startY = (self.preGame or self.goldMode) and 40 or 28

              for i = self.scroll + 1,
                  math.min(self.scroll + self.pageSize, #flatItemList) do

                  local item = flatItemList[i]
                  local drawY =
                      startY + ((i - (self.scroll + 1)) * 18)

                  if item.isHeader then
                      local isSelected = (i == self.cursor)
                      local key = item.sectionKey or sectionKey(item)
                      local Theme = require("src.ui.Theme")

                      -- Use the engine-native cursor glyph: it is proven
                      -- readable across Yellow's palette path. Position it at
                      -- the far-left edge and start text at X=22, reclaiming
                      -- eight pixels versus the historical X=30 layout.
                      if isSelected then
                          Font.drawCode(Theme.cursor, 8, drawY)
                      end

                      local headerText = menuLabelText(item.name, item.shortName,
                          wideMode and 256 or 116, self.marqueeTime)
                      local headerWidth = type(Font.width) == "function"
                          and Font.width(headerText) or (#headerText * 6)
                      local trackedWidth = headerWidth + math.max(0, #headerText - 1)
                      local headerAreaRight = 132 + valueShift
                      local headerX = math.max(16, math.floor((8 + headerAreaRight - trackedWidth) / 2))
                      local glyphX = headerX
                      for ci = 1, #headerText do
                          local ch = headerText:sub(ci, ci)
                          Font.draw(ch, glyphX, drawY)
                          Font.draw(ch, glyphX + 1, drawY)
                          glyphX = glyphX + (type(Font.width) == "function"
                              and Font.width(ch) or 6) + 1
                      end

                      Font.drawCode(collapsedSections[key]
                          and Theme.cursor or (Theme.moreArrow or 0xEE),
                          138 + valueShift, drawY)
                  else
                      local isSelected = (i == self.cursor)
                      local key = item.rule.key
                      local val = getConfigValue(key, self.preGame)

                      local isWip = (key == "wonderlocke")
                          or (key == "rules_locked"
                              and mod.exports.__beta26.permanentRuleSealWip)
                      local delegated = externalRuleDelegation
                          and externalRuleDelegation(key, self.game)
                      if isWip or delegated then
                          love.graphics.setColor(0.55, 0.55, 0.55, 1)
                      else
                          love.graphics.setColor(1, 1, 1, 1)
                      end

                      -- Delegated rows remain selectable for hover/help text,
                      -- but canChangeSelected() prevents mutation. Use the
                      -- native cursor at X=10 and start the label at X=22:
                      -- reliable selection visibility with a smaller gutter
                      -- than the old X=30 layout.
                      if isSelected and not isWip then
                          local Theme = require("src.ui.Theme")
                          Font.drawCode(Theme.cursor, 8, drawY)
                      end

                      -- 2.4.41: the label budget must follow the ACTUAL
                      -- value-column geometry. Several wide-value rows begin
                      -- left of the generic x=112 column; the old fixed 90px
                      -- budget let a label pass the width test even though its
                      -- rendered value started underneath it (Shiny Clause was
                      -- the visible failure). Keep a small gutter between the
                      -- label and whichever value column this row uses.
                      local valueStartX = 112 + valueShift
                      if item.isLockeTypeControl then
                          valueStartX = wideMode and 244 or 108
                      elseif item.isRecoveryControl then
                          valueStartX = 118 + valueShift
                      elseif item.isSetupSave or item.isInGameSave then
                          valueStartX = 112 + valueShift
                      elseif item.rule.numeric then
                          if key == "difficulty_profile" or key == "level_cap_scope"
                              or key == "randomizer_seed"
                              or key == "random_starter_style"
                              or key == "random_encounter_balance"
                              or key == "randomizer_info_policy"
                              or key == "evolution_limit" then
                              valueStartX = 104 + valueShift
                          elseif key == "travel_restrictions"
                              or key == "shiny_clause" then
                              valueStartX = 96 + valueShift
                          elseif key == "encounter_ball_limit" then
                              valueStartX = 112 + valueShift
                          elseif key == "starting_money"
                              or key == "difficulty_profile" then
                              valueStartX = 110 + valueShift
                          elseif key == "world_building_tier"
                              or key == "route_forgiveness" then
                              valueStartX = 118 + valueShift
                          end
                      end
                      local nameBudget = wideMode and 228
                          or math.max(42, valueStartX - 16 - 6)
                      Font.draw(menuLabelText(item.rule.name,
                          item.rule.shortName, nameBudget,
                          self.marqueeTime), 16, drawY)

                      if item.isLockeTypeControl then
                          local mode = math.max(0, math.min(5,
                              math.floor(tonumber(val) or 0)))
                          Font.draw(marqueePixelText(LockePreset.labels[mode] or "CUSTOM",
                              wideMode and 68 or 44, self.marqueeTime), 108, drawY)
                      elseif item.isRecoveryControl then
                          local legacy = trackerLog().__LEGACY__
                          local count = type(legacy) == "table" and #legacy or 0
                          Font.draw(tostring(count), 118 + valueShift, drawY)
                      elseif item.isSetupSave then
                          local label = "SAVE"
                          if self.setupSaveFlash and self.setupSaveFlash > 0 then
                              label = "SAVED"
                          elseif self.setupSaveFlash and self.setupSaveFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.isInGameSave then
                          local label = "SAVE"
                          if self.inGameSaveFlash and self.inGameSaveFlash > 0 then
                              label = "SAVED"
                          elseif self.inGameSaveFlash and self.inGameSaveFlash < 0 then
                              label = "ERROR"
                          end
                          Font.draw(marqueePixelText(label, 42, self.marqueeTime), 112 + valueShift, drawY)
                      elseif item.rule.numeric then
                          local digits = item.rule.digits or 1
                          local numberText = ("%0" .. tostring(digits) .. "d"):format(tonumber(val) or item.rule.min or 0)
                          if key == "difficulty_profile" then
                              local options = mod.exports.__beta26.difficultyOptions()
                              local row = options[(tonumber(val) or 0) + 1]
                              local label = row and row.name or "VANILLA"
                              Font.draw(marqueePixelText(tostring(label):upper(), 44, self.marqueeTime), 110 + valueShift, drawY)
                          elseif key == "starting_money" then
                              Font.draw(Strings("¥%s", numberText), 110 + valueShift, drawY)
                          elseif key == "world_building_tier" then
                              local labels = { [0] = "OFF", [1] = "T1", [2] = "T2", [3] = "T3" }
                              Font.draw(Strings(labels[tonumber(val) or 0] or "OFF"), 118 + valueShift, drawY)
                          elseif key == "level_cap_scope" then
                              local labels = { [0] = "NONE", [1] = "GYMS", [2] = "E4", [3] = "CHAMP", [4] = "POST" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "NONE", 44, self.marqueeTime), 110 + valueShift, drawY)
                          elseif key == "dupes_mode" then
                              local labels = { [0] = "OFF", [1] = "SPEC", [2] = "FAM" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "evolution_limit" then
                              local labels = { [0] = "NORMAL", [1] = "NO FINAL", [2] = "NO EVO" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "NORMAL", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "travel_restrictions" then
                              local labels = { [0] = "NORMAL", [1] = "NO FLY", [2] = "NO FLY+TP" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "NORMAL", 58, self.marqueeTime), 96 + valueShift, drawY)
                          elseif key == "shiny_clause" then
                              local labels = { [0] = "OFF", [1] = "1", [2] = "2", [3] = "3", [4] = "UNLIMITED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 58, self.marqueeTime), 96 + valueShift, drawY)
                          elseif key == "encounter_ball_limit" then
                              local labels = { [0] = "OFF", [1] = "1", [2] = "2", [3] = "3", [4] = "5", [5] = "10" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "type_lock_mode" then
                              Font.draw(marqueePixelText(mod.exports.__beta26.typeLockModeLabel(val), 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "type_lock_primary" or key == "type_lock_secondary" or key == "type_lock_tertiary" or key == "type_lock_quaternary" or key == "type_lock_quinary" or key == "type_lock_senary" then
                              Font.draw(marqueePixelText(
                                  mod.exports.__beta26.typeLockTypeLabel(val),
                                  42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "randomizer_seed" then
                              local seed = tonumber(val) or 0
                              local label = seed > 0 and ("%08d"):format(seed) or "AUTO"
                              Font.draw(marqueePixelText(label, 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_starter_style" then
                              local labels = { [0]="ANY", [1]="3-STAGE", [2]="BASE", [3]="SIM BST" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "ANY", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_encounter_balance" then
                              local labels = { [0]="CHAOS", [1]="SIM BST", [2]="EVO", [3]="BALANCED" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "CHAOS", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "randomizer_info_policy" then
                              local labels = { [0]="OPEN INFO", [1]="BLIND INFO" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OPEN INFO", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "random_learnset_generation" then
                              local labels = { [0]="AUTO", [1]="GEN1", [2]="GEN2" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "AUTO", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "random_species_generation" then
                              local labels = { [0]="AUTO", [1]="GEN1", [2]="GEN2", [3]="BOTH" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "AUTO", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "route_forgiveness" then
                              local labels = { [0] = "OFF", [1] = "0", [2] = "1" }
                              Font.draw(Strings(labels[tonumber(val) or 0] or "OFF"), 118 + valueShift, drawY)
                          elseif key == "trainer_money_multiplier" then
                              local label = mod.exports.__beta26.trainerMoneyPresetLabels[
                                  tonumber(val) or 4] or Strings.source("100%")
                              Font.draw(marqueePixelText(label, 44, self.marqueeTime), 110 + valueShift, drawY)
                          elseif key == "mt_moon_splits"
                              or key == "safari_zone_splits" then
                              local labels = { [0] = "OFF", [1] = "COMMON" }
                              Font.draw(marqueePixelText(labels[tonumber(val) or 0]
                                  or "OFF", 50, self.marqueeTime), 104 + valueShift, drawY)
                          elseif key == "player_start_stat_exp" or key == "wild_start_stat_exp"
                              or key == "trainer_start_stat_exp" then
                              Font.draw(marqueePixelText(
                                  mod.exports.__beta26.statExpPresetLabels[tonumber(val) or 0]
                                      or "0%", 42, self.marqueeTime), 112 + valueShift, drawY)
                          elseif key == "maximum_bst" then
                              Font.draw(marqueePixelText(
                                  mod.exports.__beta26.maximumBstDisplayLabel(val),
                                  42, self.marqueeTime), 112 + valueShift, drawY)
                          else
                              Font.draw(numberText, 118 + valueShift, drawY)
                          end
                          if isSelected and self.editingNumber then
                              local prefix = key == "starting_money" and 1 or 0
                              local editX = key == "randomizer_seed" and 104 or 118
                              Font.draw(Strings("^"), editX + valueShift + ((self.digitIndex - 1) + prefix) * 6, drawY - 8)
                          end
                      else
                          local status = key == "dev_self_test_export" and "RUN"
                              or (isWip and "WIP" or (val and "ON" or "OFF"))
                          Font.draw(Strings(status), 118 + valueShift, drawY)
                      end

                      love.graphics.setColor(1, 1, 1, 1)
                  end
              end

              local selItem = flatItemList[self.cursor]

              if selItem and not selItem.isHeader then
                  -- 2.4.16: editingNumber can only be entered from a real numeric
                  -- rule row, so its instructions must live in this selected-row
                  -- branch. The old placement in the outer else was unreachable.
                  if self.editingNumber then
                      Font.draw(Strings("LR:Digit  UD:Value"), 14, 96)
                      Font.draw(Strings("A:Confirm  B:Back"), 14, 112)
                  else
                      local displayedDescription = ruleDescriptionForDisplay(selItem.rule, self.preGame)
                      if selItem.rule.key == "rules_locked"
                          and not mod.exports.__beta26.permanentRuleSealWip then
                          if self.lockConfirmStage == 1 then
                              displayedDescription = Strings(
                                  "WARNING 1/2: Permanent Rule Seal cannot be undone. Select SEAL again to continue, or move away/B to cancel.")
                          elseif self.lockConfirmStage == 2 then
                              displayedDescription = Strings(
                                  "FINAL WARNING 2/2: One more SEAL activation permanently locks challenge rules. Move away/B to cancel.")
                          end
                      end
                      local descLines = wrapPixelText(displayedDescription,
                          wideMode and 276 or 132)
                      local maxScroll = math.max(0, #descLines - 3)

                      if self.descScroll > maxScroll then
                          self.descScroll = maxScroll
                      end

                      local startLine = self.descScroll + 1
                      -- Show up to 3 lines; third line stays clear for the
                      -- scroll arrow so it never overlaps text.
                      local endLine = math.min(#descLines, startLine + 2)

                      local descY = 94
                      for li = startLine, endLine do
                          Font.draw(descLines[li], 14, descY)
                          descY = descY + 14
                      end

                      -- Blinking native Gen 1 more-below arrow when more text exists below.
                      if self.descScroll < maxScroll then
                          local blinkOn = math.floor(self.marqueeTime / 0.8) % 2 == 0
                          if blinkOn then
                              local Theme = require("src.ui.Theme")
                              Font.drawCode(Theme.moreArrow or 0xEE, wideMode and 216 or 72, 132)
                          end
                      end
                  end
              else
                  -- Help text when no rule is focused (e.g. on a header row,
                  -- which shouldn't happen with the cursor skip logic, but
                  -- show sensible hints anyway).
                  if selItem and selItem.isHeader then
                      local key = selItem.sectionKey or sectionKey(selItem)
                      Font.draw(Strings("SEL+UD: JUMP"), 14, 102)
                      Font.draw(Strings("SEL+LR: ALL"), 14, 116)
                      Font.draw(Strings("A/LR: THIS"), 14, 130)
                  elseif locked then
                      Font.draw(Strings("Rules are LOCKED."), 14, 96)
                      Font.draw(Strings("A on Lock to open."), 14, 112)
                  else
                      Font.draw(Strings("A or LR: Toggle"), 14, 96)
                      Font.draw(Strings("SEL: More text"), 14, 110)
                      Font.draw(Strings("B: Back"), 14, 124)
                  end
              end
          end

          -- 2.1.20: protect first runtime frames without mutating the
          -- StateStack from inside draw(). 2.1.19 could catch a draw exception
          -- and then pop the screen while StateStack/Renderer was iterating it,
          -- turning a recoverable custom-screen failure into a hard crash.
          -- Record draw failures and surface them on the next update tick.
          do
              local function queueRuntimeFail(phase, err)
                  if self.__nuzRuntimeError then return end
                  local msg = tostring(err or "unknown config-screen runtime error")
                  self.__nuzRuntimeError = {
                      phase = tostring(phase or "runtime"),
                      message = msg,
                  }
                  mod.exports.__beta26.lastConfigScreenError =
                      self.__nuzRuntimeError.phase .. ": " .. msg
                  -- 2.4.60: preserve the full xpcall/debug.traceback payload in
                  -- Dev Mode before the player-facing dialog shortens it.
                  local Dev = mod.exports.__beta26.Dev
                  if Dev and type(Dev.recordError) == "function" then
                      pcall(Dev.recordError,
                          "config_screen_" .. self.__nuzRuntimeError.phase,
                          msg, self.game)
                  end
              end

              local function presentRuntimeFail()
                  local failure = self.__nuzRuntimeError
                  if not failure or self.__nuzRuntimeErrorPresented then return false end
                  self.__nuzRuntimeErrorPresented = true
                  local game = self.game
                  if not (game and game.stack) then return true end
                  pcall(function()
                      if type(game.stack.pop) == "function" then game.stack:pop() end
                  end)
                  local short = tostring(failure.message):gsub("^.-:%s*", "")
                  if #short > 180 then short = short:sub(1, 180) .. "..." end
                  local surface = self.preGame and "SETUP" or "RULES"
                  local body = mod.exports.__beta26.manualPagedErrorText(
                      "NUZ " .. surface .. " "
                          .. tostring(failure.phase):upper() .. " ERROR",
                      short)
                  local okText, TextBox = pcall(require, "src.render.TextBox")
                  if okText and TextBox then
                      pcall(function() game.stack:push(TextBox.new(game, body)) end)
                  end
                  return true
              end

              local rawUpdate = self.update
              if type(rawUpdate) == "function" then
                  self.update = function(...)
                      if presentRuntimeFail() then return end
                      local args = { ... }
                      local ok, result = xpcall(function()
                          return rawUpdate((table.unpack or unpack)(args))
                      end, debug and debug.traceback or tostring)
                      if not ok then
                          queueRuntimeFail("update", result)
                          presentRuntimeFail()
                          return
                      end
                      return result
                  end
              end

              local rawDraw = self.draw
              if type(rawDraw) == "function" then
                  self.draw = function(...)
                      if self.__nuzRuntimeError then return end
                      local args = { ... }
                      local ok, result = xpcall(function()
                          return rawDraw((table.unpack or unpack)(args))
                      end, debug and debug.traceback or tostring)
                      if not ok then
                          queueRuntimeFail("draw", result)
                          return
                      end
                      return result
                  end
              end
          end

          return self
      end
  })

  ---------------------------------------------------------------------
  -- BUILD DISPLAY ROUTE LIST
  -- RouteList OFF: only visited/caught areas are shown.
  -- RouteList ON: every tracked area is shown.
  ---------------------------------------------------------------------
  local function syncCurrentArea(game)
      if not game then
          return
      end

      discoverAllKnownAreas(game)

      -- Check every save/runtime representation of the current location.
      -- Different engine paths populate these at slightly different times
      -- during map transitions, so relying on only one of them can miss a city
      -- on an older save.
      local candidates = {}

      if game.overworld and game.overworld.map then
          candidates[#candidates + 1] = game.overworld.map.id
      end

      if game.world and game.world.map then
          candidates[#candidates + 1] = game.world.map.id
      end

      if game.save and game.save.player then
          candidates[#candidates + 1] = game.save.player.map
      end

      if game.save and type(game.save.lastOutdoor) == "table" then
          candidates[#candidates + 1] = game.save.lastOutdoor.id
      end

      for _, rawId in ipairs(candidates) do
          local key = registerArea(rawId)
          if key then
              markVisited(key)
          end
      end
  end

  local TOWN_AREA_IDS = {
      PALLET_TOWN = true, VIRIDIAN_CITY = true, PEWTER_CITY = true,
      CERULEAN_CITY = true, VERMILION_CITY = true, LAVENDER_TOWN = true,
      FUCHSIA_CITY = true, CELADON_CITY = true, SAFFRON_CITY = true,
      CINNABAR_ISLAND = true,
  }

  local TOWN_PREFIXES = {
      -- Keep "vermillion" as a common custom-map misspelling for tolerance;
      -- canonical Gen 1 IDs continue to use the correct "vermilion".
      "pallet", "viridian", "pewter", "cerulean", "vermillion",
      "vermilion", "lavender", "fuchsia", "celadon", "saffron",
      "cinnabar",
  }

  local TOWN_INTERIOR_WORDS = {
      "mart", "pokemart", "poke mart", "pokemon mart", "pkmn mart",
      "center", "pokemon center", "pokecenter", "poke center",
      "gym", "hotel", "house", "lab", "museum", "shop", "gate",
      "dept store", "department store", "game corner", "bike shop",
      "fishing guru", "name rater",
  }

  isTownArea = function(id, name)
      id = tostring(id or "")
      if TOWN_AREA_IDS[id] then return true end

      local text = tostring(name or id or ""):lower()
      text = text:gsub("_+", " ")
      text = text:gsub("([a-z])([A-Z])", "%1 %2"):lower()
      if text:find("city", 1, true)
          or text:find("town", 1, true)
          or text:find("village", 1, true) then
          return true
      end

      -- Treat named town/city interiors as town locations even when their
      -- individual map ID has no CITY/TOWN suffix (e.g. CeruleanMart4).
      local hasTownPrefix = false
      for _, prefix in ipairs(TOWN_PREFIXES) do
          if text:find(prefix, 1, true) == 1 then
              hasTownPrefix = true
              break
          end
      end
      if hasTownPrefix then
          for _, word in ipairs(TOWN_INTERIOR_WORDS) do
              if text:find(word, 1, true) then return true end
          end
      end

      return false
  end

  local function areaAllowedByConfig(area)
      if not area then
          return false
      end

      local routeFamily = mod.exports.__beta26.splitFamilyFor(area.id)
      if routeFamily and routeFamily.parent:match("^ROUTE_%d+$") then
          local selector = routeFamily.selector
          return selector ~= nil and mod.exports.__beta26.routeSplitActive(selector)
      end
      if mod.exports.__beta26.routeCardinalAxes[area.id] then
          local selectedFamily = mod.exports.__beta26.encounterSplitAreas[
              "route_" .. tostring(area.id):match("ROUTE_(%d+)")]
          local splitOn = selectedFamily and selectedFamily.selector
              and mod.exports.__beta26.routeSplitActive(selectedFamily.selector)
          return not splitOn
              or (type(trackerLog()[area.id]) == "table"
                  and #trackerLog()[area.id] > 0)
              or caughtAreas()[area.id] ~= nil
              or (type(mod.save:get("encounter_states", {})) == "table"
                  and mod.save:get("encounter_states", {})[area.id] ~= nil)
      end

      local moon = mod.exports.__beta26.encounterSplitAreas.mt_moon
      local moonMode = math.max(0, math.min(1,
          math.floor(tonumber(mod.save:get("mt_moon_splits", 0)) or 0)))
      if area.id == moon.parent then
          return moonMode == 0
              or (type(trackerLog()[moon.parent]) == "table"
                  and #trackerLog()[moon.parent] > 0)
              or caughtAreas()[moon.parent] ~= nil
              or (type(mod.save:get("encounter_states", {})) == "table"
                  and mod.save:get("encounter_states", {})[moon.parent] ~= nil)
      end
      if moon.members[area.id] then return moonMode == 1 end

      local safari = mod.exports.__beta26.encounterSplitAreas.safari
      local safariMode = math.max(0, math.min(1,
          math.floor(tonumber(mod.save:get("safari_zone_splits", 0)) or 0)))
      if area.id == safari.parent then
          return safariMode == 0
              or (type(trackerLog()[safari.parent]) == "table"
                  and #trackerLog()[safari.parent] > 0)
              or caughtAreas()[safari.parent] ~= nil
              or (type(mod.save:get("encounter_states", {})) == "table"
                  and mod.save:get("encounter_states", {})[safari.parent] ~= nil)
      end
      if safari.members[area.id] then return safariMode == 1 end

      -- Pallet Town is the mandatory starter slot. Keep it visible on the
      -- encounter MAP even when ordinary town catches are disabled.
      if area.id == "PALLET_TOWN" then
          return true
      end

      if isTownArea(area.id, area.name) and not mod.save:get("town_catches", false) then
          return false
      end
      return true
  end

  getDisplayRoutes = function(game)
      if type(mod.exports.__beta26.ensureEncounterProjection) == "function" then
          pcall(mod.exports.__beta26.ensureEncounterProjection)
      end
      syncCurrentArea(game)
      local list = {}

      for _, r in ipairs(ALL_ROUTES) do
          if areaAllowedByConfig(r) then
              table.insert(list, r)
          end
      end

      table.sort(list, function(a, b)
          local ao = ROUTE_ORDER[a.id] or 999999
          local bo = ROUTE_ORDER[b.id] or 999999
          if ao == bo then
              return tostring(a.name) < tostring(b.name)
          end
          return ao < bo
      end)

      return list
  end

  -- beta.26 canonical starter cleanup: older diagnostic runs could record
  -- the same starter in PALLET_TOWN and OAKS_LAB. Remove only the provable
  -- duplicate starter row; never delete unrelated custom-area catches.
  mod.exports.__beta26.cleanupStarterDuplicate = function()
      local log = trackerLog()
      local pallet = log["PALLET_TOWN"]
      if type(pallet) ~= "table" or #pallet == 0 then return false end

      -- Keep this helper self-contained. In earlier B7 code it referenced the
      -- later local mod.exports.__beta26.isStarterSpecies() definition and therefore resolved a nil
      -- global from this earlier lexical position.
      local starters = {}
      for _, entry in ipairs(pallet) do
          local sp = tostring(entry and entry.species or ""):upper()
          if sp == "BULBASAUR" or sp == "CHARMANDER" or sp == "SQUIRTLE"
              or sp == "PIKACHU" then
              starters[sp] = true
          end
      end
      if next(starters) == nil then return false end

      local changed = false
      local areas = caughtAreas()
      local states = mod.save:get("encounter_states", {})
      if type(states) ~= "table" then states = {} end

      for key, entries in pairs(log) do
          local k = tostring(key or ""):upper()
          if key ~= "PALLET_TOWN" and type(entries) == "table"
              and (k:find("OAK", 1, true) or k:find("LAB", 1, true)) then
              local kept = {}
              local removedStarter = false
              for _, entry in ipairs(entries) do
                  local sp = tostring(entry and entry.species or ""):upper()
                  if starters[sp] then
                      changed = true
                      removedStarter = true
                  else
                      kept[#kept + 1] = entry
                  end
              end
              if #kept > 0 then log[key] = kept else log[key] = nil end
              if removedStarter and starters[tostring(areas[key] or ""):upper()] then
                  areas[key] = nil
              end
              local st = states[key]
              if removedStarter and type(st) == "table"
                  and starters[tostring(st.species or ""):upper()] then
                  states[key] = nil
              end
          end
      end

      if changed then
          mod.save:set("tracker_log", log)
          mod.save:set("caught_areas", areas)
          mod.save:set("encounter_states", states)
      end
      return changed
  end

  ---------------------------------------------------------------------
  -- TRACKER DEATH PROJECTION
  --
  -- Tracker rows describe the encounter/catch event, while nuzlocke_history
  -- owns later lifecycle events. Project DEAD history back onto the exact
  -- caught Pokemon by persistent pokemonId so removing a dead Pokemon from
  -- the party cannot make its area row look alive again.
  --
  -- Legacy rows without IDs get a conservative fallback only when one
  -- same-species catch exists in the recorded catch area.
  ---------------------------------------------------------------------
  mod.exports.__beta26.syncTrackerDeathProjection = function()
      local history = mod.save:get("nuzlocke_history", {})
      local log = trackerLog()
      if type(history) ~= "table" or type(log) ~= "table" then return false end

      local deadById = {}
      local legacyDead = {}
      for _, row in ipairs(history) do
          if type(row) == "table" and row.status == "DEAD" then
              if row.pokemonId ~= nil then
                  deadById[tostring(row.pokemonId)] = row
              elseif row.catchLocation ~= nil and row.species ~= nil then
                  legacyDead[#legacyDead + 1] = row
              end
          end
      end

      local changed = false
      local function applyDeath(catch, row)
          if type(catch) ~= "table" or type(row) ~= "table" then return end
          if catch.dead ~= true or catch.status ~= "DEAD"
              or catch.deathCause ~= row.deathCause
              or catch.deathLocation ~= row.deathLocation then
              catch.dead = true
              catch.status = "DEAD"
              catch.deathCause = row.deathCause
              catch.deathLocation = row.deathLocation
              catch.deathOpponentSpecies = row.deathOpponentSpecies
              catch.deathMove = row.deathMove
              catch.deathCritical = row.deathCritical
              catch.deathStatusCondition = row.deathStatusCondition
              changed = true
          end
      end

      for _, entries in pairs(log) do
          if type(entries) == "table" then
              for _, catch in ipairs(entries) do
                  if type(catch) == "table" and catch.pokemonId ~= nil then
                      local row = deadById[tostring(catch.pokemonId)]
                      if row then applyDeath(catch, row) end
                  end
              end
          end
      end

      -- Pre-ID compatibility: only mark when catchLocation + species resolves
      -- to exactly one saved tracker row. Ambiguous old data is left alone.
      for _, row in ipairs(legacyDead) do
          local area = routeKey(row.catchLocation) or row.catchLocation
          local entries = log[area]
          if type(entries) == "table" then
              local candidate, count = nil, 0
              for _, catch in ipairs(entries) do
                  if type(catch) == "table"
                      and tostring(catch.species or ""):upper()
                          == tostring(row.species or ""):upper() then
                      candidate = catch
                      count = count + 1
                  end
              end
              if count == 1 then applyDeath(candidate, row) end
          end
      end

      if changed then mod.save:set("tracker_log", log) end
      return changed
  end

  ---------------------------------------------------------------------
  -- TRACKER DISPLAY ROWS
  -- The save is grouped by area, but the tracker is displayed row-by-row.
  -- Never comma-join multiple catches from the same area.
  ---------------------------------------------------------------------
  local function getTrackerLogRows(prepared)
      if prepared ~= true then
          if type(mod.exports.__beta26.ensureEncounterProjection) == "function" then
              pcall(mod.exports.__beta26.ensureEncounterProjection)
          end
          mod.exports.__beta26.cleanupStarterDuplicate()
      end
      local log = trackerLog()
      local states = mod.save:get("encounter_states", {})
      if type(states) ~= "table" then states = {} end
      local keys, known = {}, {}
      for key, entries in pairs(log) do
          if type(entries) == "table" and #entries > 0 then
              table.insert(keys, key)
              known[key] = true
          end
      end
      -- Failed encounters are real route outcomes even without a catch.
      -- Surface them in LOG instead of leaving the route visually blank.
      for key, state in pairs(states) do
          if key ~= "__LEGACY__" and not known[key]
              and type(state) == "table" and state.status == "FAILED" then
              table.insert(keys, key)
              known[key] = true
          end
      end
      table.sort(keys, function(a, b)
          local ao = (a == "__LEGACY__") and 999998 or (ROUTE_ORDER[a] or 999999)
          local bo = (b == "__LEGACY__") and 999998 or (ROUTE_ORDER[b] or 999999)
          if ao == bo then return tostring(a) < tostring(b) end
          return ao < bo
      end)
      local rows = {}
      for _, key in ipairs(keys) do
          local entries = log[key]
          if type(entries) == "table" and #entries > 0 then
              for _, catch in ipairs(entries) do
                  if type(catch) == "table" then
                      table.insert(rows, { area = key, catch = catch })
                  end
              end
          else
              local state = states[key]
              if type(state) == "table" and state.status == "FAILED" then
                  table.insert(rows, { area = key, catch = {
                      species = state.species,
                      encounterType = state.encounterType or "wild",
                      failed = true,
                  } })
              end
          end
      end
      return rows
  end

  local function getTrackerMapRows(game, prepared)
      if prepared ~= true then
          mod.exports.__beta26.cleanupStarterDuplicate()
      end
      local log = trackerLog()
      local states = mod.save:get("encounter_states", {})
      if type(states) ~= "table" then states = {} end
      local rows = {}
      for _, route in ipairs(getDisplayRoutes(game)) do
          local catches = log[route.id]
          if type(catches) == "table" and #catches > 0 then
              for _, catch in ipairs(catches) do
                  if type(catch) == "table" then
                      table.insert(rows, { area = route, catch = catch })
                  end
              end
          else
              local state = states[route.id]
              if type(state) == "table" and state.status == "FAILED" then
                  table.insert(rows, { area = route, catch = {
                      species = state.species,
                      encounterType = state.encounterType or "wild",
                      failed = true,
                  } })
              elseif caughtAreas()[route.id] ~= nil then
                  table.insert(rows, { area = route, catch = {
                      species = caughtAreas()[route.id],
                      encounterType = "unknown",
                      retroactive = true,
                  } })
              else
                  table.insert(rows, { area = route, catch = nil })
              end
          end
      end
      return rows
  end

  ---------------------------------------------------------------------
  -- TRAINER CARD Nuzlocke status page
  --
  -- The vanilla Trainer Card remains the front page.  A flips to a live
  -- Nuzlocke status page whose rule list is read directly from mod.save.
  -- Changes made in the in-game RULES menu therefore appear immediately
  -- the next time this page is drawn.
  --
  -- MONEY intentionally stays off this page because it is already shown on
  -- the vanilla front of the Trainer Card.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeTrainerCardScreen", {
      new = function(game, ctx)
          ctx = ctx or {}
          -- 2.1.18: statusOnly is the compatibility-safe START-menu surface.
          -- It never constructs or wraps the engine TrainerCard, so opening the
          -- native NAME/card row remains 100% upstream-owned. The historical
          -- combined card/status mode is retained only for compatibility with
          -- an external caller that explicitly requests it.
          local statusOnly = ctx.statusOnly == true
          local vanilla
          if not statusOnly then
              local okCard, TrainerCard = pcall(require, "src.ui.TrainerCard")
              if okCard and TrainerCard and type(TrainerCard.new) == "function" then
                  local okVanilla, card = pcall(TrainerCard.new, game, { onCancel = nil })
                  if okVanilla then vanilla = card end
              end
              -- If the native card cannot be constructed, degrade to the
              -- standalone status page instead of crashing the game.
              if not vanilla then statusOnly = true end
          end

          local self = {
              game = game,
              screenId = "NuzlockeTrainerCardScreen",
              vanilla = vanilla,
              statusOnly = statusOnly,
              isOpaque = true,
              nuzlockeStatusPage = statusOnly,
              ruleScroll = 0,
              ruleArrowTime = 0,
              ruleMarqueeTime = 0,
              ruleRevision = tonumber(mod.save:get("nuzlocke_rule_revision", 0)) or 0,
          }

          local function activeRuleNames()
              -- The Trainer Card must use the exact same active-save state as
              -- the in-game Rules screen.  Never read the staged NEW GAME
              -- table here; once the save exists, mod.save is authoritative.
              local names = {}
              if mod.save:get("nuzlocke_enabled", true) ~= true then
                  return { Strings("Nuzlocke OFF") }
              end
              local lockeType = math.max(0, math.min(5,
                  math.floor(tonumber(mod.save:get("locke_type",
                      defaultRuleValue("locke_type")))
                      or defaultRuleValue("locke_type"))))
              if lockeType > 0 then
                  names[#names + 1] = Strings("Locke %s",
                      Strings(LockePreset.names[lockeType] or "CUSTOM"))
              end
              local function boolSetting(value)
                  if value == true then return true end
                  if type(value) == "number" then return value ~= 0 end
                  if type(value) == "string" then
                      local v = value:lower()
                      return v == "true" or v == "on" or v == "yes" or tonumber(v) == 1
                  end
                  return false
              end
              local function activeLabel(rule)
                  local value = getConfigValue(rule.key, false)
                  if rule.key == "encounter_spend_indicator"
                      or rule.key == "dev_mode" or rule.key == "catch_info"
                      or rule.key == "stat_info" or rule.key == "move_info"
                      or rule.key == "area_guide_enabled" then
                      return nil
                  elseif rule.key == "world_building_tier" then
                      local tier = tonumber(value) or 0
                      if tier > 0 then return Strings("World %s", Strings(
                          ({ [1] = "TIER 1", [2] = "TIER 2", [3] = "TIER 3" })[tier])) end
                      return nil
                  elseif rule.key == "level_cap_scope" then
                      local rawScope = mod.save:get("level_cap_scope", nil)
                      local scope = rawScope == nil and legacyLevelCapScope() or (tonumber(rawScope) or 0)
                      if scope > 0 then return Strings("Level Caps %s", Strings(
                          ({ [1] = "GYMS", [2] = "E4", [3] = "CHAMP", [4] = "POST" })[scope])) end
                      return nil
                  elseif rule.key == "dupes_mode" then
                      local mode = tonumber(value) or 0
                      if mode == 1 then return Strings("Dupes SPEC") end
                      if mode == 2 then return Strings("Dupes FAM") end
                      return nil
                  elseif rule.key == "evolution_limit" then
                      local mode = tonumber(value) or 0
                      if mode == 1 then return Strings("No Final Evo") end
                      if mode == 2 then return Strings("No Evolution") end
                      return nil
                  elseif rule.key == "party_size_limit" then
                      local limit = tonumber(value) or 6
                      if limit < 6 then return Strings("Party Limit %d", limit) end
                      return nil
                  elseif rule.key == "travel_restrictions" then
                      local mode = tonumber(value) or 0
                      if mode == 1 then return Strings("No Fly") end
                      if mode == 2 then return Strings("No Fly+Teleport") end
                      return nil
                  elseif rule.key == "shiny_clause" then
                      local mode = tonumber(value) or 0
                      if mode == 4 then return Strings("Shiny UNLIMITED") end
                      if mode > 0 then
                          local used = math.max(0, math.floor(tonumber(mod.save:get("shiny_clause_used", 0)) or 0))
                          return Strings("Shiny %d/%d", math.max(0, mode - used), mode)
                      end
                      return nil
                  elseif rule.key == "encounter_ball_limit" then
                      local limit = mod.exports.__beta26.encounterBallLimitValues[
                          tonumber(value) or 0] or 0
                      return limit > 0 and Strings("Ball Limit %d", limit) or nil
                  elseif rule.key == "no_catching" then
                      return value == true and Strings("No Catching") or nil
                  elseif rule.key == "badge_boosts" then
                      return value == false and Strings("No Badge Boosts") or nil
                  elseif rule.key == "mt_moon_splits" then
                      return (tonumber(value) or 0) == 1 and Strings("Mt Moon COMMON") or nil
                  elseif rule.key == "safari_zone_splits" then
                      return (tonumber(value) or 0) == 1 and Strings("Safari COMMON") or nil
                  elseif rule.key == "trainer_money_multiplier" then
                      local mode = tonumber(value) or 4
                      return Strings("Trainer Money %s", Strings(
                          mod.exports.__beta26.trainerMoneyPresetLabels[mode]
                              or Strings.source("100%")))
                  elseif rule.key == "maximum_bst" then
                      local limit = tonumber(value) or 0
                      return limit > 0 and Strings("Max BST %d", limit) or nil
                  elseif rule.key == "randomizer_seed" then
                      local starterOwned = mod.save:get("random_starter", false) == true
                          and not (externalRuleDelegation and externalRuleDelegation("random_starter", self.game))
                      local encountersOwned = mod.save:get("random_encounter_tables", false) == true
                          and not (externalRuleDelegation and externalRuleDelegation("random_encounter_tables", self.game))
                      local learnsetsOwned = mod.save:get("random_learnsets", false) == true
                          and not (externalRuleDelegation and externalRuleDelegation("random_learnsets", self.game))
                      local seed = tonumber(value) or 0
                      return (starterOwned or encountersOwned or learnsetsOwned) and seed > 0
                          and Strings("RNG %08d v%d", seed, mod.exports.__beta26.randomizerAlgorithmVersion()) or nil
                  elseif rule.key == "random_starter_style" then
                      if mod.save:get("random_starter", false) ~= true
                          or (externalRuleDelegation and externalRuleDelegation("random_starter", self.game)) then return nil end
                      return Strings("Starter %s", ({ [0]="ANY", [1]="3-STAGE", [2]="BASE", [3]="SIM BST" })[tonumber(value) or 0] or "ANY")
                  elseif rule.key == "random_encounter_balance" then
                      if mod.save:get("random_encounter_tables", false) ~= true
                          or (externalRuleDelegation and externalRuleDelegation("random_encounter_tables", self.game)) then return nil end
                      return Strings("Enc %s", ({ [0]="CHAOS", [1]="SIM BST", [2]="EVO", [3]="BALANCED" })[tonumber(value) or 0] or "CHAOS")
                  elseif rule.key == "randomizer_info_policy" then
                      if mod.save:get("random_encounter_tables", false) ~= true then return nil end
                      return tonumber(value) == 1 and Strings("RNG BLIND") or Strings("RNG OPEN")
                  elseif rule.key == "gold_egg_encounter_mode" then
                      local mode = tonumber(value) or 0
                      return mode > 0 and Strings("Egg %s",
                          ({ [1]="RECEIVED", [2]="HATCHED", [3]="GIFT" })[mode]
                              or "RECEIVED") or nil
                  elseif rule.key == "gold_bug_contest_mode" then
                      local mode = tonumber(value) or 0
                      return mode > 0 and Strings("Contest %s",
                          ({ [1]="EXEMPT", [2]="SLOT" })[mode]
                              or "EXEMPT") or nil
                  elseif rule.numeric then
                      return (tonumber(value) or 0) > 0 and Strings(rule.name) or nil
                  elseif boolSetting(value) then
                      return Strings(rule.name)
                  end
                  return nil
              end
              for _, cat in ipairs(ruleCategories) do
                  for _, rule in ipairs(cat.rules) do
                      local label = activeLabel(rule)
                      if label then names[#names + 1] = label end
                  end
              end

              -- Gym Guide Rare Candy is a live gameplay toggle, but it is
              -- intentionally outside ruleCategories because it lives in the
              -- MISC utility section of the Rules screen. It still belongs on
              -- the Trainer Card when enabled. Save/Recover controls are not
              -- rules and are never listed here.
              if boolSetting(mod.save:get("infinite_rare_candies", false)) then
                  names[#names + 1] = Strings("Gym Guide Candy")
              end

              -- Immutable NEW GAME setup choices live in the same scrolling
              -- Nuzlocke status/rules list rather than creating a third Trainer
              -- Card page. These values are captured on the save at NEW GAME
              -- construction and never follow the player's current resources.
              local save = self.game and self.game.save or {}
              if save.nuzlockeRunStartMoney ~= nil then
                  names[#names + 1] = Strings("Start ¥%d",
                      tonumber(save.nuzlockeRunStartMoney) or 0)
              end
              if save.nuzlockeRunStartBalls ~= nil then
                  names[#names + 1] = Strings("Start Balls %d",
                      tonumber(save.nuzlockeRunStartBalls) or 0)
              end
              if save.nuzlockeRunStartCandies ~= nil then
                  names[#names + 1] = Strings("Start Candy %d",
                      tonumber(save.nuzlockeRunStartCandies) or 0)
              end

              return names
          end

          -- 2.1.22: the R/B/Y START-menu status surface now uses the engine's
          -- stable mod-facing ListMenu instead of a hand-drawn custom state.
          -- Runtime testing on Yellow showed the custom NUZ ST. state could
          -- still hard-crash before its deferred draw guard could recover.
          -- Build the same status/rule information as inert list rows so the
          -- host owns scrolling, drawing, cancel input, and StateStack timing.
          if statusOnly then
              local function metric(label, fn, fallback)
                  local ok, value = pcall(fn)
                  if not ok then value = fallback end
                  return { label = Strings(label), right = tostring(value or fallback or "?") }
              end
              local items = {}
              items[#items + 1] = { label = Strings("RUN STATUS"), right = "" }
              items[#items + 1] = metric("CAUGHT", function()
                  return countTrackerCatches()
              end, 0)
              items[#items + 1] = metric("DEATHS", function()
                  return tonumber(mod.save:get("nuzlocke_losses", 0)) or 0
              end, 0)
              items[#items + 1] = metric("CAUGHT A.", function()
                  return string.format("%d/%d", countCaughtAreas(), #getDisplayRoutes(game))
              end, "0/0")
              items[#items + 1] = metric("VISITED A.", function()
                  return string.format("%d/%d", countVisitedAreas(game), #getDisplayRoutes(game))
              end, "0/0")
              items[#items + 1] = metric("NEXT CAP", function()
                  local cap = nextLevelCap(game and game.save)
                  return cap >= 100 and Strings("MAX") or Strings("LV%d", cap)
              end, "?")

              items[#items + 1] = {
                  label = Strings("ACTIVE RULES:"),
                  right = "",
                  nuzlockeBoldHeader = true,
              }
              local okRules, names = pcall(activeRuleNames)
              if okRules and type(names) == "table" then
                  if #names == 0 then
                      items[#items + 1] = { label = Strings("NONE"), right = "" }
                  end
                  for _, name in ipairs(names) do
                      items[#items + 1] = { label = tostring(name), right = "" }
                  end
              else
                  items[#items + 1] = { label = Strings("RULE READ ERROR"), right = "" }
              end

              local menu = mod.ui.ListMenu.new(game, Strings("NUZ STATUS"), items, {
                  kind = "nuzlocke_status",
                  pageJump = true,
                  wrap = false,
              })
              -- Keep ListMenu lifecycle/input unchanged. Redraw only the visible
              -- ACTIVE RULES: header one pixel to the right for a native-style
              -- bold echo, matching the presentation vocabulary used elsewhere.
              if type(menu) == "table" and type(menu.draw) == "function" then
                  local baseDraw = menu.draw
                  menu.draw = function(self)
                      baseDraw(self)
                      local headerIndex = nil
                      for i, row in ipairs(self.items or {}) do
                          if row.nuzlockeBoldHeader == true then
                              headerIndex = i
                              break
                          end
                      end
                      if headerIndex then
                          local visibleRow = headerIndex - (self.scroll or 0)
                          if visibleRow >= 1 and visibleRow <= (self.rows or 7) then
                              local Font = require("src.render.Font")
                              local y = 8 + visibleRow * 16
                              Font.draw(Strings("ACTIVE RULES:"), 17, y)
                          end
                      end
                  end
              end
              return menu
          end

          -- Optional semantic presentation used by Gen1 Modern UI.
          -- This remains source-owned data/actions: the classic draw path below
          -- is untouched and stays the fallback whenever no presenter is active.
          function self:nuzlockeModernUiModel()
              local save = self.game and self.game.save or {}
              if self.nuzlockeStatusPage then
                  local names = activeRuleNames()
                  local rows = {}
                  for i, name in ipairs(names) do
                      rows[#rows + 1] = {
                          label = tostring(name),
                          right = i == self.ruleScroll + 1 and ">" or nil,
                      }
                  end
                  return {
                      title = Strings("NUZLOCKE STATUS"),
                      rows = rows,
                      index = math.min(#rows, self.ruleScroll + 1),
                      scroll = self.ruleScroll,
                      footer = { Strings("A: CARD"), Strings("B: BACK") },
                      details = {
                          Strings("Active challenge rules"),
                          Strings("CAP %s", tostring(nextLevelCap(save))),
                      },
                  }
              end

              local player = save.player or {}
              local badges = 0
              local okBadges, Badges = pcall(require, "src.inventory.Badges")
              if okBadges and Badges and type(Badges.count) == "function" then
                  local okCount, count = pcall(Badges.count,
                      self.game and self.game.data, save)
                  if okCount then badges = tonumber(count) or 0 end
              end
              local seconds = math.floor(tonumber(save.playTime) or 0)
              local money = math.floor(tonumber(save.money) or 0)
              return {
                  title = Strings("TRAINER CARD"),
                  rows = {
                      { label = Strings("NAME"), right = tostring(player.name or "PLAYER") },
                      { label = Strings("ID"), right = tostring(player.id or player.trainerId or "--") },
                      { label = Strings("MONEY"), right = ("¥%d"):format(money) },
                      { label = Strings("TIME"), right = ("%d:%02d"):format(
                          math.floor(seconds / 3600), math.floor(seconds / 60) % 60) },
                      { label = Strings("BADGES"), right = tostring(badges) },
                      { label = Strings("NEXT CAP"), right = tostring(nextLevelCap(save)) },
                  },
                  index = 1,
                  scroll = 0,
                  footer = { Strings("A: NUZLOCKE"), Strings("B: BACK") },
              }
          end

          function self:nuzlockeModernUiAction(action)
              if action == "back" then
                  self.game.stack:pop()
                  return true
              elseif not self.statusOnly
                  and (action == "select" or action == "right" or action == "left") then
                  self.nuzlockeStatusPage = not self.nuzlockeStatusPage
                  self.ruleScroll = 0
                  self.ruleArrowTime = 0
                  self.ruleMarqueeTime = 0
                  return true
              elseif self.nuzlockeStatusPage and (action == "up" or action == "down") then
                  local names = activeRuleNames()
                  local maxScroll = math.max(0, #names - 2)
                  if action == "up" then
                      self.ruleScroll = math.max(0, self.ruleScroll - 1)
                  else
                      self.ruleScroll = math.min(maxScroll, self.ruleScroll + 1)
                  end
                  self.ruleMarqueeTime = 0
                  return true
              end
              return false
          end

          function self:update(dt)
              local input = self.game.input
              local revision = tonumber(mod.save:get("nuzlocke_rule_revision", 0)) or 0
              if revision ~= self.ruleRevision then
                  self.ruleRevision = revision
                  self.ruleScroll = 0
                  self.ruleArrowTime = 0
                  self.ruleMarqueeTime = 0
              end

              if input:wasPressed("a") and not self.statusOnly then
                  self.nuzlockeStatusPage = not self.nuzlockeStatusPage
                  self.ruleScroll = 0
                  self.ruleArrowTime = 0
                  self.ruleMarqueeTime = 0
                  return
              end

              if input:wasPressed("b") then
                  self.game.stack:pop()
                  return
              end

              if self.nuzlockeStatusPage then
                  local names = activeRuleNames()
                  -- draw() has two physical rule rows in the beta.21 layout.
                  -- Keep update() on that same window size so the final rule is
                  -- reachable and the native more-arrow disappears correctly.
                  local visible = 2
                  local maxScroll = math.max(0, #names - visible)

                  if input:wasPressed("down") and self.ruleScroll < maxScroll then
                      self.ruleScroll = self.ruleScroll + 1
                      self.ruleMarqueeTime = 0
                  elseif input:wasPressed("up") and self.ruleScroll > 0 then
                      self.ruleScroll = self.ruleScroll - 1
                      self.ruleMarqueeTime = 0
                  else
                      self.ruleMarqueeTime = self.ruleMarqueeTime + (dt or 0)
                  end

                  -- Clamp the scroll position every update.  The arrow is
                  -- driven by the same condition used to advance the list,
                  -- so it cannot remain visible after the final rule.
                  if self.ruleScroll > maxScroll then
                      self.ruleScroll = maxScroll
                  end

                  local canScrollDown = (self.ruleScroll + visible) < #names
                  if canScrollDown then
                      self.ruleArrowTime = self.ruleArrowTime + (dt or 0)
                  else
                      self.ruleArrowTime = 0
                  end
              else
                  self.ruleScroll = 0
                  self.ruleArrowTime = 0
                  self.ruleMarqueeTime = 0
              end
          end

          function self:draw()
              local Font = mod.ui.Font

              if not self.nuzlockeStatusPage and self.vanilla then
                  self.vanilla:draw()
                  -- Flip hint lives in the open band between the trainer
                  -- information/sprite area and the badge sprites.  Keep it
                  -- on the RIGHT side, clear of the WORD badges and dots.
                  Font.draw(Strings("A:NUZ"), 112, 78)
                  return
              end

              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 0, 0, 160, 144)
              Font.drawBox(0, 0, 20, 18)

              Font.draw(Strings("NUZ STATUS"), 28, 8)

              local caught = countTrackerCatches()
              local deaths = tonumber(mod.save:get("nuzlocke_losses", 0)) or 0
              local lostEncounters = 0
              local states = mod.save:get("encounter_states", {})
              if type(states) == "table" then
                  for key, state in pairs(states) do
                      if key ~= "__LEGACY__" and type(state) == "table"
                          and state.status == "FAILED" and isTrackedArea(key) then
                          lostEncounters = lostEncounters + 1
                      end
                  end
              end
              local caughtAreasCount = countCaughtAreas()
              local visitedAreasCount = countVisitedAreas(self.game)
              local totalAreas = #getDisplayRoutes(self.game)
              local cap = nextLevelCap(self.game and self.game.save)

              -- LOST ENC. means an eligible area encounter was consumed without
              -- a catch (KO, flee/escape, etc.). nuzlocke_losses has always been
              -- the Pokemon death counter, so expose it honestly as DEATHS.
              Font.draw(Strings("CAUGHT"), 16, 22)
              Font.draw(("%3d"):format(caught), 108, 22)
              Font.draw(Strings("LOST ENC."), 16, 34)
              Font.draw(("%3d"):format(lostEncounters), 108, 34)
              Font.draw(Strings("DEATHS"), 16, 46)
              Font.draw(("%3d"):format(deaths), 108, 46)
              Font.draw(Strings("CAUGHT A."), 16, 58)
              Font.draw(("%2d/%2d"):format(caughtAreasCount, totalAreas), 88, 58)
              Font.draw(Strings("VISITED A."), 16, 70)
              Font.draw(("%2d/%2d"):format(visitedAreasCount, totalAreas), 88, 70)
              Font.draw(Strings("NEXT CAP"), 16, 82)
              Font.draw(cap >= 100 and Strings("MAX")
                  or Strings("LV%d", cap), 88, 82)

              local names = activeRuleNames()
              local visible = 2
              local maxScroll = math.max(0, #names - visible)
              if self.ruleScroll > maxScroll then
                  self.ruleScroll = maxScroll
              end
              local canScrollDown = (self.ruleScroll + visible) < #names

              local rulesY = 94
              local ruleRowsY = rulesY + 10
              Font.draw(Strings("RULES"), 16, rulesY)
              if #names == 0 then
                  Font.draw(Strings("NONE"), 16, ruleRowsY)
              else
                  for row = 1, visible do
                      local idx = self.ruleScroll + row
                      local name = names[idx]
                      if name then
                          Font.draw(marqueeText(name, 14, self.ruleMarqueeTime),
                              16, ruleRowsY + (row - 1) * 10)
                      end
                  end
              end

              -- Bottom navigation strip. The down marker uses the same native Gen 1 glyph as TextBox.
              -- when the player reaches the last rule, the scroll indicator
              -- disappears completely instead of changing into another arrow.
              -- This leaves the prompts unobstructed and makes the down-arrow
              -- mean exactly one thing: more rules are available below.
              if canScrollDown then
                  local blinkOn = math.floor(self.ruleArrowTime / 0.8) % 2 == 0
                  if blinkOn then
                       local Theme = require("src.ui.Theme")
                       Font.drawCode(Theme.moreArrow or 0xEE, 94, 122)
                   end
              end

              if self.statusOnly then
                  Font.draw(Strings("B:EXIT"), 104, 126)
              else
                  Font.draw(Strings("A:CARD"), 8, 126)
                  Font.draw(Strings("B:EXIT"), 104, 126)
              end
          end

          -- 2.1.20: status-only START-menu screen uses the same deferred
          -- recovery rule as NUZ RULES. Never pop a state from inside draw().
          do
              local function queueStatusFail(phase, err)
                  if self.__nuzStatusRuntimeError then return end
                  local msg = tostring(err or "unknown status-screen runtime error")
                  self.__nuzStatusRuntimeError = {
                      phase = tostring(phase or "runtime"), message = msg,
                  }
                  mod.exports.__beta26.lastStatusScreenError =
                      self.__nuzStatusRuntimeError.phase .. ": " .. msg
                  -- 2.4.60: status-screen update/draw failures are independent
                  -- from config-screen failures and should retain their own
                  -- full traceback plus point-in-time Dev snapshot.
                  local Dev = mod.exports.__beta26.Dev
                  if Dev and type(Dev.recordError) == "function" then
                      pcall(Dev.recordError,
                          "status_screen_" .. self.__nuzStatusRuntimeError.phase,
                          msg, self.game)
                  end
              end
              local function presentStatusFail()
                  local failure = self.__nuzStatusRuntimeError
                  if not failure or self.__nuzStatusRuntimeErrorPresented then return false end
                  self.__nuzStatusRuntimeErrorPresented = true
                  local g = self.game
                  if not (g and g.stack) then return true end
                  pcall(function()
                      if type(g.stack.pop) == "function" then g.stack:pop() end
                  end)
                  local short = tostring(failure.message):gsub("^.-:%s*", "")
                  if #short > 180 then short = short:sub(1, 180) .. "..." end
                  local body = mod.exports.__beta26.manualPagedErrorText(
                      "NUZ STATUS " .. tostring(failure.phase):upper() .. " ERROR",
                      short)
                  local okText, TextBox = pcall(require, "src.render.TextBox")
                  if okText and TextBox then
                      pcall(function() g.stack:push(TextBox.new(g, body)) end)
                  end
                  return true
              end
              local rawUpdate = self.update
              self.update = function(...)
                  if presentStatusFail() then return end
                  local args = { ... }
                  local ok, result = xpcall(function()
                      return rawUpdate((table.unpack or unpack)(args))
                  end, debug and debug.traceback or tostring)
                  if not ok then
                      queueStatusFail("update", result)
                      presentStatusFail()
                      return
                  end
                  return result
              end
              local rawDraw = self.draw
              self.draw = function(...)
                  if self.__nuzStatusRuntimeError then return end
                  local args = { ... }
                  local ok, result = xpcall(function()
                      return rawDraw((table.unpack or unpack)(args))
                  end, debug and debug.traceback or tostring)
                  if not ok then
                      queueStatusFail("draw", result)
                      return
                  end
                  return result
              end
          end

          return self
      end
  })


  ---------------------------------------------------------------------
  -- INFINITE RARE CANDY / GYM GUIDE
  --
  -- This is deliberately isolated from the existing Nuzlocke enforcement
  -- hooks.  When disabled, the vanilla Gym Guide handler is replayed and
  -- nothing else happens.  When enabled, the vanilla conversation finishes
  -- first, then the Guide offers a repeatable quantity menu.
  --
  -- The menu is a normal mod screen rather than a replacement for the
  -- engine's item UI.  Bag.add still enforces the normal inventory rules and
  -- the quantity is capped at 99 per conversation.
  ---------------------------------------------------------------------

  local GYM_GUIDE_TALKS = {
      PEWTER_GYM    = "TEXT_PEWTERGYM_GYM_GUIDE",
      CERULEAN_GYM  = "TEXT_CERULEANGYM_GYM_GUIDE",
      VERMILION_GYM = "TEXT_VERMILIONGYM_GYM_GUIDE",
      FUCHSIA_GYM   = "TEXT_FUCHSIAGYM_GYM_GUIDE",
      SAFFRON_GYM   = "TEXT_SAFFRONGYM_GYM_GUIDE",
      CELADON_GYM   = "TEXT_CELADONGYM_GYM_GUIDE",
      CINNABAR_GYM  = "TEXT_CINNABARGYM_GYM_GUIDE",
      VIRIDIAN_GYM  = "TEXT_VIRIDIANGYM_GYM_GUIDE",
  }

  local RARE_CANDY_CHOICES = { 1, 10, 25, 50, 99 }

  -- A small foreground screen.  It intentionally has no dependency on the
  -- Nuzlocke config screen, so it can be used safely from any Gym Guide.
  mod.content.screens:register("NuzlockeRareCandyMenu", {
      new = function(game, context)
          context = context or {}
          local self = {
              game = game,
              selected = 1,
              choices = RARE_CANDY_CHOICES,
              isOpaque = false,
              onSelect = context.onSelect,
              onCancel = context.onCancel,
          }

          function self:update(dt)
              local input = self.game.input
              if input:wasPressed("up") then
                  self.selected = self.selected - 1
                  if self.selected < 1 then self.selected = #self.choices end
              elseif input:wasPressed("down") then
                  self.selected = self.selected + 1
                  if self.selected > #self.choices then self.selected = 1 end
              elseif input:wasPressed("a") then
                  local amount = self.choices[self.selected]
                  local callback = self.onSelect
                  self.game.stack:pop()
                  if callback then callback(amount) end
                  return
              elseif input:wasPressed("b") then
                  local callback = self.onCancel
                  self.game.stack:pop()
                  if callback then callback() end
                  return
              end
          end

          function self:draw()
              local Font = mod.ui.Font
              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 16, 18, 128, 108)
              Font.drawBox(16, 18, 16, 13)
              -- Keep every row visually centered inside the 16-tile box.
              -- This helper is local to draw() so the large main chunk does not
              -- gain another long-lived top-level local. Gen1's UI font is an
              -- 8px fixed-width grid for these ASCII labels.
              local function centeredX(text)
                  return 80 - math.floor((#tostring(text) * 8) / 2)
              end

              Font.draw(Strings("RARE CANDY"), centeredX(Strings("RARE CANDY")), 26)
              Font.draw(Strings("How many?"), centeredX(Strings("How many?")), 42)

              for i, amount in ipairs(self.choices) do
                  local y = 56 + (i - 1) * 10
                  local valueText = tostring(amount)
                  local valueX = centeredX(valueText)
                  if i == self.selected then
                      local Theme = require("src.ui.Theme")
                      Font.drawCode(Theme.cursor, valueX - 12, y)
                  end
                  Font.draw(valueText, valueX, y)
              end

              Font.draw(Strings("B:CANCEL"), centeredX(Strings("B:CANCEL")), 108)
              Font.draw(Strings("A:OK"), centeredX(Strings("A:OK")), 118)
          end

          return self
      end,
  })

  -- R/B/Y-only command access. Gold deliberately does not seed the Gen 1
  -- command table, and its VM must never receive one of those handlers. Keep
  -- the private module name behind an explicit generation gate so a future
  -- shared call site cannot accidentally patch dead Gen 1 code on Gold.
  mod.exports.__beta26.rbyCommandsFor = function(game)
      if mod.exports.__beta26.runtimeIsGold(game) then return nil end
      local moduleName = "src.script." .. "Commands"
      local ok, Commands = pcall(require, moduleName)
      if not ok or type(Commands) ~= "table" then return nil end
      return Commands
  end

  mod.content.commands:register("nuzlocke:infinite_rare_candy", {
      foreground = true,
      fn = function(ctx)
          if ctx and ctx.generation == 2 then return end
          if mod.save:get("infinite_rare_candies", false) ~= true then return end
          if providerExclusive("npc_talk", ctx and ctx.game, nil) then return end

          local Commands = mod.exports.__beta26.rbyCommandsFor(ctx and ctx.game)
          if not Commands then return end
          Commands.show_text(ctx,
              "Psst... doing a Nuzlocke?\nI won't tell the League.\nHow many RARE CANDY do you want?")

          local tier = worldTier(ctx.game)
          if tier >= 2 and levelCapScope() > 0 then
              local cap, leader = nextLevelCapInfo(ctx.game.save)
              Commands.show_text(ctx,
                  tier >= 3
                      and ("Gym Guide: Careful!\nYour current cap is LV. " .. tostring(cap) .. ".\n" .. tostring(leader) .. " won't be impressed.")
                      or ("Nice try.\nRare Candies don't beat the level cap.\nCurrent cap: LV. " .. tostring(cap) .. "."))
          end

          local selectedAmount
          Commands.push_screen(ctx, "NuzlockeRareCandyMenu", {
              onSelect = function(amount) selectedAmount = tonumber(amount) end,
              onCancel = function() selectedAmount = nil end,
          })
          if not selectedAmount then return end

          local okBag, Bag = pcall(require, "src.inventory.Bag")
          if not okBag or not Bag then
              Commands.show_text(ctx, "Rare Candy service is unavailable.")
              return
          end

          local inventory = ctx.save.inventory or {}
          local room = math.max(0, 99 - (tonumber(inventory.RARE_CANDY) or 0))
          local give = math.min(selectedAmount, room)
          if give <= 0 then
              Commands.show_text(ctx, "You already have\n99 RARE CANDY!")
              return
          end
          if not Bag.add(ctx.save, "RARE_CANDY", give, ctx.game.data) then
              Commands.show_text(ctx, "Your BAG is full!")
              return
          end
          Commands.show_text(ctx,
              ("You got %d %s!"):format(give, give == 1 and "RARE CANDY" or "RARE CANDIES"))
      end,
  })

  -- Compose the actual vanilla talk rows with our post-dialogue command.
  -- This is the long-lived beta.8-beta.16 R/B/Y implementation: baseTalk()
  -- returns ScriptRunner rows, so copy those rows and append the candy command
  -- directly. Do not nest a second foreground command/runner around them.
  local function registerGymGuideCandyTalk(mapId, textId)
      local MapScripts = require("src.script.MapScripts")
      local baseRows = MapScripts.baseTalk(mapId, textId)
      local rows = {}
      if type(baseRows) == "table" then
          for i, row in ipairs(baseRows) do rows[i] = row end
      end
      rows[#rows + 1] = { "nuzlocke:infinite_rare_candy" }
      mod.content.map_scripts:register(mapId, {
          priority = 10,
          talk = { [textId] = rows },
      })
  end

  local function gymGuideObjectName(mapDef, textId, mapId)
      if not (mapDef and type(mapDef.objects) == "table") then return nil end

      local fallback
      local upperText = tostring(textId or ""):upper()
      local compactMap = tostring(mapId or ""):gsub("_", ""):upper()

      for _, obj in ipairs(mapDef.objects) do
          local name = tostring(obj.name or "")
          local upperName = name:upper()

          local text = tostring(obj.text or obj.textId or obj.textID or ""):upper()
          local sprite = tostring(obj.sprite or obj.spriteId or ""):upper()

          -- Never mistake a trainer merely because another mod reused its
          -- sprite. Actual trainer objects carry trainer metadata.
          if not isTrainerDefinition(obj) then
              -- Strongest match: the object points at this Gym Guide text.
              if text ~= "" and text == upperText then
                  return name
              end

              -- Generated object names normally preserve the ROM constant, e.g.
              -- PEWTERGYM_GYM_GUIDE.
              if compactMap ~= "" and upperName:find(compactMap, 1, true)
                  and upperName:find("GYM", 1, true)
                  and (upperName:find("GUIDE", 1, true)
                       or upperName:find("GUY", 1, true)) then
                  fallback = name
              end

              -- Some generated builds retain the sprite constant even if the
              -- object name was normalized.
              if sprite == "SPRITE_GYM_GUIDE" then
                  fallback = name
              end
          end
      end

      return fallback
  end

  refreshGymGuideVisibility = function(game)
      if saveSchemaTooNew then return end
      -- The Gym Guide candy bridge is an R/B/Y map-script feature. Gold has a
      -- separate script VM and no Gen 2 consumer for the map_scripts registry.
      if game and tonumber(game.generation) == 2 then return end
      if mod.save:get("infinite_rare_candies", false) ~= true then
          return
      end

      local save = game and game.save
      if not save then return end

      -- If another active mod explicitly owns NPC visibility, it gets the final
      -- say. Otherwise ordinary NPC visibility behavior continues to compose
      -- with the Guide.
      if providerExclusive("npc_visibility", game, nil)
          or providerExclusive("npc_behavior", game, nil) then
          return
      end

      save.objectToggles = save.objectToggles or {}

      for mapId, textId in pairs(GYM_GUIDE_TALKS) do
          local def
          if game.overworld and game.overworld.map
              and game.overworld.map.id == mapId
              and game.overworld.map.def then
              def = game.overworld.map.def
          end

          local data = game.data
          if not def and data and data.maps then def = data.maps[mapId] end
          if not def and data and data.mapsById then def = data.mapsById[mapId] end

          local objectName = gymGuideObjectName(def, textId, mapId)
          if objectName then
              save.objectToggles[mapId] = save.objectToggles[mapId] or {}
              save.objectToggles[mapId][objectName] = true

              -- Restore the live NPC immediately if the player is already in
              -- this gym. Commands.show_object uses the engine's public seam
              -- and updates the NPC/entity lists without rebuilding the map.
              local ow = game.overworld
              if ow and ow.map and ow.map.id == mapId then
                  local Commands = mod.exports.__beta26.rbyCommandsFor(game)
                  if Commands and type(Commands.show_object) == "function" then
                      pcall(Commands.show_object, {
                          game = game, save = save, overworld = ow
                      }, mapId, objectName)
                  end
              end
          end
      end
  end

  -- Keep late-runtime/checkpoint consumers off this main-scope local so the
  -- large reconciliation closure stays below the project upvalue ceiling.
  mod.exports.__beta26.refreshGymGuideVisibility = refreshGymGuideVisibility

  -- The Gym Guide bridge is a Gen 1 map-script feature. Determine the boot
  -- target from GameVersion rather than mod.game: at mod entry time mod.game
  -- is not guaranteed to carry the active generation, which could suppress
  -- the R/B/Y registrations entirely. This restores the established R/B/Y
  -- registration path while keeping Gold away from the Gen 1 registry.
  local gymGuideGoldBoot = false
  do
      local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
      if okVersion and type(GameVersion) == "table"
          and type(GameVersion.isGold) == "function" then
          local okGold, isGold = pcall(GameVersion.isGold)
          gymGuideGoldBoot = okGold and isGold == true
      end
  end
  if not gymGuideGoldBoot then
      for mapId, textId in pairs(GYM_GUIDE_TALKS) do
          registerGymGuideCandyTalk(mapId, textId)
      end
  end

  mod.events:on("save.loaded", function(ev)
      if saveSchemaTooNew then return end
      if ev and ev.save then
          if type(mod.save:get("nuzlocke_e4_defeated")) ~= "table" then
              mod.save:set("nuzlocke_e4_defeated", {})
          end
          refreshGymGuideVisibility(currentGame)
      end
  end)

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      refreshGymGuideVisibility(game)
  end)

  mod.events:on("map.entered", function(ev)
      if refreshGymGuideVisibility and currentGame then
          refreshGymGuideVisibility(currentGame)
      end
  end)

  -- Map reloads are another way an overworld object list can be rebuilt.
  -- Reapply once after the rebuild instead of polling or fighting another mod
  -- every frame.
  mod.events:on("map.reloaded", function()
      if refreshGymGuideVisibility and currentGame then
          refreshGymGuideVisibility(currentGame)
      end
  end)

  -- Gym victory scripts can hide the Guide after the map was already entered.
  -- Refresh once at battle teardown instead of fighting other mods every frame.
  mod.events:on("battle.ended", function()
      if refreshGymGuideVisibility and currentGame then
          refreshGymGuideVisibility(currentGame)
      end
  end)

  -- Scripted CANLOSE/tournament mods may intentionally heal survivors after
  -- battle. Compose with that behavior, but never allow an already-recorded
  -- Permadeath loss to be made usable again by a later battle.ended listener.
  -- Gold trainer scripts can reload the map without map.entered, so repeat the
  -- owned invariant at map.reloaded as well.
  local function reconcileExternalSaveState(saveOverride)
      if saveSchemaTooNew then return false end
      local save = saveOverride or (currentGame and currentGame.save) or currentSave
      if type(save) ~= "table" then return end

      local enabled = mod.save:get("nuzlocke_enabled", true) ~= false
      local permadeath = mod.save:get("permadeath", true) == true
      if enabled and permadeath then
          -- Save editors and recovery tools may legitimately restore HP on the
          -- underlying Pokemon object. The persistent Nuzlocke death marker is
          -- historical challenge state, so it remains authoritative on load
          -- and after external post-battle healing. Never resurrect it merely
          -- because an external tool wrote a positive HP value.
          for _, mon in ipairs(save.party or {}) do
              if type(mon) == "table" and mon.nuzlockeDead == true then
                  mon.hp = 0
              end
          end
      end

      -- External editors know the engine's six-Pokemon capacity, not this
      -- run's optional 1-6 challenge cap. Detect an over-cap edited save but
      -- do not auto-delete, auto-box, or reorder anything. Existing acquisition
      -- and PC gates already forbid further growth until the party is legal.
      local limit = math.max(1, math.min(6, math.floor(tonumber(
          mod.save:get("party_size_limit", defaultRuleValue("party_size_limit"))) or 6)))
      local count = #(save.party or {})
      local over = enabled and count > limit
      mod.save:set("nuzlocke_external_party_over_cap", over)
      mod.save:set("nuzlocke_external_party_count", count)
      mod.save:set("nuzlocke_external_party_limit", limit)
  end
  mod.exports.__beta26.reconcileExternalSaveState = reconcileExternalSaveState

  mod.events:on("save.loaded", function(ev)
      pcall(reconcileExternalSaveState, ev and ev.save)
  end)
  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev
      pcall(reconcileExternalSaveState, game and game.save)
  end)
  mod.events:on("battle.ended", function()
      pcall(reconcileExternalSaveState)
  end)
  mod.events:on("map.reloaded", function()
      pcall(reconcileExternalSaveState)
  end)
  mod.events:on("map.entered", function()
      pcall(reconcileExternalSaveState)
  end)


  ---------------------------------------------------------------------
  -- TRACKER SCREEN
  ---------------------------------------------------------------------
  ---------------------------------------------------------------------
  -- LEGACY CATCH RECOVERY SCREEN
  --
  -- Select a legacy Pokemon, then select one of the areas that the current
  -- encounter data says could contain that species. Choosing an area records
  -- it as a retroactive catch and removes it from LEGACY.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeLegacyRecoveryScreen", {
      new = function(game)
          local self = {
              game = game,
              isOpaque = true,
              cursor = 1,
              areaCursor = 1,
              mode = "list",
              scroll = 0,
              actionCursor = 1,
              typeCursor = 1,
              pendingArea = nil,
          }

          local recoveryTypes = {
              "wild", "grass", "surf", "fishing", "overworld",
              "static", "gift", "trade", "safari", "unknown",
          }

          local function entries()
              local out = {}
              local legacy = trackerLog().__LEGACY__
              local mons = collectLegacyMons(game.save or {})
              local usedLegacyMons = {}

              if type(legacy) == "table" then
                  for _, savedEntry in ipairs(legacy) do
                      if type(savedEntry) == "table" then
                          -- IMPORTANT: tracker_log is persisted save data.
                          -- Never attach live Pokemon objects or UI-only fields
                          -- directly to a saved legacy record. 29.3.16 could
                          -- mutate savedEntry.mon here and REMOVE ENTRY would
                          -- later serialize that live object back through
                          -- mod.save:set("tracker_log"), which can fatally
                          -- break save serialization on existing Yellow saves.
                          local entry = {}
                          for k, v in pairs(savedEntry) do
                              if k ~= "mon" and k ~= "logEntry" then entry[k] = v end
                          end
                          entry.provenance = entry.provenance or "LEGACY"
                          entry.savedEntry = savedEntry

                          -- Attach the actual save Pokemon only to the detached
                          -- UI view. Manual assignment/removal can still update
                          -- the real mon without contaminating tracker_log.
                          local sp = tostring(entry.species or ""):upper()
                          for i, mon in ipairs(mons) do
                              local idMatch = entry.pokemonId
                                  and Identity.pokemonIdentity(mon) == entry.pokemonId
                              local speciesMatch = tostring(mon and mon.species or ""):upper() == sp
                              if not usedLegacyMons[i]
                                  and type(mon) == "table"
                                  and (idMatch or speciesMatch)
                                  and (mon.nuzlockeOrigin == "LEGACY"
                                      or mon.nuzlockeOrigin == "EDITED"
                                      or mon.nuzlockeOrigin == "PLAYER_CONFIRMED")
                                  and not mon.catchLocation then
                                  entry.mon = mon
                                  usedLegacyMons[i] = true
                                  break
                              end
                          end
                          out[#out + 1] = entry
                      end
                  end
              end

              -- Edited Pokemon are current-save objects that were not present
              -- in the Nuzlocke baseline and were not registered by an
              -- acquisition hook. They can be recovered exactly like unknown
              -- legacy Pokemon, but retain EDITED provenance.
              for i, mon in ipairs(mons) do
                  if not usedLegacyMons[i] and type(mon) == "table" and mon.species
                      and mon.nuzlockeOrigin == "EDITED"
                      and not mon.catchLocation then
                      out[#out + 1] = {
                          species = mon.species,
                          isShiny = Identity.isShiny(mon),
                          provenance = "EDITED",
                          mon = mon,
                      }
                      usedLegacyMons[i] = true
                  end
              end

              -- Recovered/player-confirmed records remain editable. Limit the
              -- editor to recovery provenance so ordinary catches cannot be
              -- rewritten accidentally from this maintenance screen.
              for area, catches in pairs(trackerLog()) do
                  if area ~= "__LEGACY__" and type(catches) == "table" then
                      for _, catch in ipairs(catches) do
                          local provenance = type(catch) == "table"
                              and tostring(catch.provenance or "") or ""
                          local editable = type(catch) == "table"
                              and (catch.retroactive == true
                                  or catch.recoveryStatus == "PLAYER_CONFIRMED"
                                  or provenance == "LEGACY"
                                  or provenance == "EDITED"
                                  or provenance == "PLAYER_CONFIRMED")
                          if editable then
                              local attached
                              for i, mon in ipairs(mons) do
                                  local idMatch = catch.pokemonId
                                      and Identity.pokemonIdentity(mon) == catch.pokemonId
                                  local locationMatch = routeKey(mon and mon.catchLocation)
                                      == routeKey(area)
                                  local speciesMatch = tostring(
                                      mon and mon.species or ""):upper()
                                      == tostring(catch.species or ""):upper()
                                  if not usedLegacyMons[i] and type(mon) == "table"
                                      and (idMatch or (locationMatch and speciesMatch)) then
                                      attached = mon
                                      usedLegacyMons[i] = true
                                      break
                                  end
                              end
                              out[#out + 1] = {
                                  assigned = true,
                                  area = area,
                                  species = catch.species,
                                  pokemonId = catch.pokemonId,
                                  fingerprint = catch.fingerprint,
                                  isShiny = catch.isShiny == true,
                                  encounterType = catch.encounterType or "unknown",
                                  provenance = provenance ~= "" and provenance
                                      or "PLAYER_CONFIRMED",
                                  possibleAreas = catch.possibleAreas,
                                  logEntry = catch,
                                  mon = attached,
                              }
                          end
                      end
                  end
              end
              return out
          end

          local function recoveryEncounterLimitApplies()
              if mod.save:get("nuzlocke_enabled", true) == false then return false end
              return mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) == true
          end

          local function areaAlreadyHasEncounter(log, areas, area, ignoredCatch)
              if not area then return false end
              local catches = log[area]
              if type(catches) == "table" then
                  for _, catch in ipairs(catches) do
                      if catch ~= ignoredCatch then return true end
                  end
              end
              -- caught_areas is a summary and cannot identify ownership. It is
              -- safe to ignore only when this editor record is the sole log row.
              if areas[area] ~= nil then
                  return not (ignoredCatch ~= nil and type(catches) == "table"
                      and #catches == 1 and catches[1] == ignoredCatch)
              end
              return false
          end

          local function filterRecoveryAreas(rawAreas, entry)
              local log = trackerLog()
              local areas = caughtAreas()
              local filtered = {}
              for _, area in ipairs(rawAreas or {}) do
                  if type(area) == "table" then
                      area = area.id or area.mapId or area.key
                  end
                  if area and (not recoveryEncounterLimitApplies()
                      or not areaAlreadyHasEncounter(log, areas, area,
                          entry and entry.logEntry)) then
                      filtered[#filtered + 1] = area
                  end
              end
              return filtered
          end

          local function candidates(entry)
              if not entry then return {} end

              local raw = nil
              if not entry.assigned and type(entry.possibleAreas) == "table"
                  and #entry.possibleAreas > 0 then
                  raw = entry.possibleAreas
              end

              if not raw and not entry.assigned then
                  local providerHistory = mod.save:get("encounter_provider_history")
                  local providerWasUsed = type(providerHistory) == "table" and next(providerHistory) ~= nil
                  if not providerWasUsed and not activeCompatProvider("encounters", game, nil) then
                      local inferred = legacyCandidates(game, entry.species)
                      if #inferred > 0 then raw = inferred end
                  end
              end

              -- UNKNOWN means the engine data cannot prove a wild source.
              -- At that point the player is explicitly confirming history,
              -- so offer the full known area list instead of inventing a
              -- location automatically.
              if not raw then
                  raw = {}
                  for _, route in ipairs(getDisplayRoutes(game)) do
                      if type(route) == "table" then
                          raw[#raw + 1] = route.id
                      elseif route ~= nil then
                          raw[#raw + 1] = route
                      end
                  end
              end

              return filterRecoveryAreas(raw, entry)
          end

          local function refreshCaughtArea(log, areas, area)
              if not area then return end
              local catches = log[area]
              if type(catches) == "table" and #catches > 0 then
                  areas[area] = catches[1].species or areas[area]
              else
                  areas[area] = nil
              end
          end

          local function detachAssignedEntry(entry, keepPending)
              if not (entry and entry.assigned and entry.area and entry.logEntry) then
                  return false
              end
              local log = trackerLog()
              local areas = caughtAreas()
              local catches = log[entry.area]
              if type(catches) == "table" then
                  local remaining = {}
                  for _, catch in ipairs(catches) do
                      if catch ~= entry.logEntry then remaining[#remaining + 1] = catch end
                  end
                  log[entry.area] = #remaining > 0 and remaining or nil
              end
              refreshCaughtArea(log, areas, entry.area)

              if keepPending then
                  log.__LEGACY__ = type(log.__LEGACY__) == "table"
                      and log.__LEGACY__ or {}
                  log.__LEGACY__[#log.__LEGACY__ + 1] = {
                      species = entry.species,
                      pokemonId = entry.pokemonId,
                      fingerprint = entry.fingerprint,
                      isShiny = entry.isShiny == true,
                      possibleAreas = entry.possibleAreas,
                      provenance = entry.provenance or "PLAYER_CONFIRMED",
                      encounterType = entry.encounterType or "unknown",
                  }
              end

              if entry.mon then
                  entry.mon.catchLocation = nil
                  entry.mon.encounterType = entry.encounterType or "unknown"
                  entry.mon.nuzlockeTrackerRegistered = nil
                  local id = Identity.pokemonIdentity(entry.mon)
                  local registry = Identity.identityRegistry()
                  if id and type(registry[id]) == "table" then
                      registry[id].catchLocation = nil
                      mod.save:set(ID_REGISTRY_KEY, registry)
                  end
              end
              -- Defensive migration guard: old 29.3.16 recovery UI
              -- sessions could have leaked transient live-Pokemon references
              -- into __LEGACY__. Strip only known UI-only fields before the
              -- tracker table crosses the save serializer again.
              if type(log.__LEGACY__) == "table" then
                  for _, legacyEntry in ipairs(log.__LEGACY__) do
                      if type(legacyEntry) == "table" then
                          legacyEntry.mon = nil
                          legacyEntry.logEntry = nil
                          legacyEntry.savedEntry = nil
                      end
                  end
              end
              mod.save:set("tracker_log", log)
              mod.save:set("caught_areas", areas)
              return true
          end

          local function chooseArea(entry, area, encounterType)
              local log = trackerLog()
              local areas = caughtAreas()
              local legacy = log.__LEGACY__ or {}
              local sp = tostring(entry.species or ""):upper()
              local sourceMon = entry.mon

              -- A manual recovery is a new player confirmation, so it must not
              -- create a second current encounter in an area that already has
              -- one when the 1st Catch rule is active. Existing historical log
              -- entries are preserved; only new assignments are blocked.
              if recoveryEncounterLimitApplies()
                  and areaAlreadyHasEncounter(log, areas, area, entry.logEntry) then
                  return false
              end

              local oldArea = entry.assigned and entry.area or nil
              if entry.assigned then
                  detachAssignedEntry(entry, false)
                  log = trackerLog()
                  areas = caughtAreas()
              end

              registerArea(area)
              log[area] = log[area] or {}
              local recoveredId = sourceMon
                  and Identity.ensurePokemonIdentity(sourceMon, self.game and self.game.save, entry.provenance or "PLAYER_CONFIRMED")
                  or nil
              table.insert(log[area], {
                  species = sp,
                  pokemonId = recoveredId,
                  fingerprint = sourceMon and Identity.fingerprint(sourceMon) or entry.fingerprint,
                  isShiny = entry.isShiny == true,
                  encounterType = encounterType or entry.encounterType or "wild",
                  encounterSource = "manual",
                  recoveryStatus = "PLAYER_CONFIRMED",
                  provenance = entry.provenance or "PLAYER_CONFIRMED",
                  retroactive = true,
              })

              if sourceMon then
                  sourceMon.catchLocation = area
                  sourceMon.encounterType = encounterType
                      or entry.encounterType or "wild"
                  sourceMon.nuzlockeTrackerRegistered = true
                  Identity.setPokemonOrigin(sourceMon, "PLAYER_CONFIRMED")
                  Identity.baselineAdd(sourceMon, "PLAYER_CONFIRMED")
              end
              if areas[area] == nil then
                  areas[area] = sp
              end
              markVisited(area)
              if oldArea then refreshCaughtArea(log, areas, oldArea) end

              local remaining = {}
              local removed = false
              local savedEntry = entry.savedEntry or entry
              for _, e in ipairs(legacy) do
                  if not removed and e == savedEntry then
                      removed = true
                  else
                      table.insert(remaining, e)
                  end
              end

              if #remaining > 0 then
                  log.__LEGACY__ = remaining
              else
                  log.__LEGACY__ = nil
              end

              if type(log.__LEGACY__) == "table" then
                  for _, legacyEntry in ipairs(log.__LEGACY__) do
                      if type(legacyEntry) == "table" then
                          legacyEntry.mon = nil
                          legacyEntry.logEntry = nil
                          legacyEntry.savedEntry = nil
                      end
                  end
              end
              mod.save:set("tracker_log", log)
              mod.save:set("caught_areas", areas)
              return true
          end

          local function updateEncounterType(entry, encounterType)
              if not (entry and entry.assigned and entry.logEntry) then return false end
              entry.logEntry.encounterType = encounterType
              entry.logEntry.encounterSource = "manual"
              entry.encounterType = encounterType
              if entry.mon then entry.mon.encounterType = encounterType end
              mod.save:set("tracker_log", trackerLog())
              return true
          end

          function self:update(dt)
              local list = entries()
              if #list == 0 then
                  if self.game.input:wasPressed("b") or self.game.input:wasPressed("a") then
                      self.game.stack:pop()
                  end
                  return
              end

              if self.game.input:wasPressed("b") then
                  if self.mode == "areas" or self.mode == "actions" then
                      self.mode = "list"
                      self.areaCursor = 1
                      self.actionCursor = 1
                      self.pendingArea = nil
                  elseif self.mode == "types" then
                      self.mode = self.pendingArea and "areas" or "actions"
                      self.typeCursor = 1
                  else
                      self.game.stack:pop()
                  end
                  return
              end

              if self.mode == "list" then
                  if self.game.input:wasPressed("down") then
                      self.cursor = math.min(#list, self.cursor + 1)
                  elseif self.game.input:wasPressed("up") then
                      self.cursor = math.max(1, self.cursor - 1)
                  elseif self.game.input:wasPressed("a") then
                      local entry = list[self.cursor]
                      if entry and entry.assigned then
                          self.mode = "actions"
                          self.actionCursor = 1
                      else
                          local c = candidates(entry)
                          if #c > 0 then
                              self.mode = "areas"
                              self.areaCursor = 1
                          end
                      end
                  end
              elseif self.mode == "actions" then
                  local entry = list[self.cursor]
                  local actions = { "CHANGE AREA", "CHANGE TYPE", "REMOVE ENTRY" }
                  if self.game.input:wasPressed("down") then
                      self.actionCursor = math.min(#actions, self.actionCursor + 1)
                  elseif self.game.input:wasPressed("up") then
                      self.actionCursor = math.max(1, self.actionCursor - 1)
                  elseif self.game.input:wasPressed("a") then
                      if self.actionCursor == 1 then
                          self.mode = "areas"
                          self.areaCursor = 1
                      elseif self.actionCursor == 2 then
                          self.pendingArea = nil
                          self.mode = "types"
                          for i, value in ipairs(recoveryTypes) do
                              if value == entry.encounterType then self.typeCursor = i end
                          end
                      elseif self.actionCursor == 3
                          and detachAssignedEntry(entry, true) then
                          self.cursor = math.min(self.cursor, math.max(1, #entries()))
                          self.mode = "list"
                      end
                  end
              elseif self.mode == "areas" then
                  local entry = list[self.cursor]
                  local c = candidates(entry)
                  if #c == 0 then
                      self.mode = "list"
                      return
                  end

                  if self.game.input:wasPressed("down") then
                      self.areaCursor = math.min(#c, self.areaCursor + 1)
                  elseif self.game.input:wasPressed("up") then
                      self.areaCursor = math.max(1, self.areaCursor - 1)
                  elseif self.game.input:wasPressed("a") then
                      local area = c[self.areaCursor]
                      if type(area) == "table" then
                          area = area.id or area.mapId or area.key
                      end
                      self.pendingArea = area
                      self.mode = "types"
                      self.typeCursor = 1
                      for i, value in ipairs(recoveryTypes) do
                          if value == (entry.encounterType or "wild") then
                              self.typeCursor = i
                          end
                      end
                  end
              elseif self.mode == "types" then
                  local entry = list[self.cursor]
                  if self.game.input:wasPressed("down") then
                      self.typeCursor = math.min(#recoveryTypes, self.typeCursor + 1)
                  elseif self.game.input:wasPressed("up") then
                      self.typeCursor = math.max(1, self.typeCursor - 1)
                  elseif self.game.input:wasPressed("a") then
                      local encounterType = recoveryTypes[self.typeCursor]
                      local ok = self.pendingArea
                          and chooseArea(entry, self.pendingArea, encounterType)
                          or updateEncounterType(entry, encounterType)
                      if ok then
                          self.cursor = math.min(self.cursor, math.max(1, #entries()))
                          self.mode = "list"
                          self.pendingArea = nil
                      end
                  end
              end
          end

          function self:draw()
              local Font = mod.ui.Font
              local list = entries()
              local function fitRecoveryText(value, glyphBudget)
                  local out = tostring(value or "")
                  if type(Font.split) ~= "function" then return out end
                  local spans = Font.split(out)
                  if #spans <= glyphBudget then return out end
                  local span = spans[glyphBudget]
                  return span and span.to and out:sub(1, span.to) or out
              end

              Font.drawBox(0, 0, 20, 18)

              if #list == 0 then
                  Font.draw(Strings("RECOVER CATCHES"), 12, 10)
                  Font.draw(Strings("ALL RECOVERED!"), 18, 52)
                  Font.draw(Strings("B:BACK"), 54, 122)
                  return
              end

              if self.mode == "list" then
                  Font.draw(Strings("RECOVER CATCHES"), 16, 10)
                  Font.draw(Strings("SELECT A POKEMON"), 12, 24)

                  local start = math.max(1, math.min(self.cursor - 3, #list - 5))
                  for i = start, math.min(#list, start + 5) do
                      local y = 40 + ((i - start) * 14)
                      if i == self.cursor then Font.drawCode((require("src.ui.Theme")).cursor, 12, y) end
                      local entry = list[i]
                      local sp = tostring(entry.species or "???")
                      local prefix = entry.assigned and "* "
                          or (entry.provenance == "EDITED" and "E " or "L ")
                      Font.draw(prefix .. sp:sub(1, 10), 30, y)
                      if entry.assigned then
                          Font.draw(Strings("EDIT"), 122, y)
                      else
                          local count = type(entry.possibleAreas) == "table"
                              and #entry.possibleAreas or 0
                          Font.draw(count > 0 and tostring(count) or "?", 128, y)
                      end
                  end

                  Font.draw(Strings("A:CHOOSE"), 16, 126)
                  Font.draw(Strings("B:BACK"), 100, 126)
              elseif self.mode == "actions" then
                  local entry = list[self.cursor]
                  Font.draw(Strings("EDIT RECOVERY"), 22, 10)
                  Font.draw(tostring(entry.species or "???"):sub(1, 12), 48, 24)
                  local actions = { "CHANGE AREA", "CHANGE TYPE", "REMOVE ENTRY" }
                  for i, action in ipairs(actions) do
                      local y = 48 + (i - 1) * 20
                      if i == self.actionCursor then
                          Font.drawCode((require("src.ui.Theme")).cursor, 12, y)
                      end
                      Font.draw(Strings(action), 30, y)
                  end
                  Font.draw(Strings("A:CHOOSE"), 16, 126)
                  Font.draw(Strings("B:BACK"), 100, 126)
              elseif self.mode == "types" then
                  local entry = list[self.cursor]
                  Font.draw(Strings("ENCOUNTER TYPE"), 16, 10)
                  Font.draw(tostring(entry.species or "???"):sub(1, 12), 48, 24)
                  local start = math.max(1,
                      math.min(self.typeCursor - 3, #recoveryTypes - 5))
                  for i = start, math.min(#recoveryTypes, start + 5) do
                      local y = 42 + ((i - start) * 14)
                      if i == self.typeCursor then
                          Font.drawCode((require("src.ui.Theme")).cursor, 12, y)
                      end
                      Font.draw(Strings(recoveryTypes[i]:upper()), 30, y)
                  end
                  Font.draw(Strings("A:CONFIRM"), 16, 126)
                  Font.draw(Strings("B:BACK"), 100, 126)
              elseif self.mode == "areas" then
                  local entry = list[self.cursor]
                  local c = candidates(entry)
                  Font.draw(Strings(entry.assigned and "CHANGE AREA?"
                      or "WHERE CAUGHT?"), 26, 10)
                  Font.draw(tostring(entry.species or "???"):sub(1, 12), 48, 24)

                  if #c == 0 then
                      Font.draw(Strings("NO AVAILABLE AREAS"), 16, 58)
                      if recoveryEncounterLimitApplies() then
                          Font.draw(Strings("AREAS ALREADY TAKEN"), 10, 76)
                      else
                          Font.draw(Strings("NO KNOWN AREAS"), 30, 76)
                      end
                      Font.draw(Strings("B:BACK"), 100, 126)
                      return
                  end

                  local start = math.max(1, math.min(self.areaCursor - 3, #c - 5))
                  for i = start, math.min(#c, start + 5) do
                      local y = 42 + ((i - start) * 14)
                      if i == self.areaCursor then Font.drawCode((require("src.ui.Theme")).cursor, 12, y) end
                      local areaId = c[i]
                      if type(areaId) == "table" then
                          areaId = areaId.id or areaId.mapId or areaId.key
                      end
                      Font.draw(fitRecoveryText(routeName(areaId), 15), 30, y)
                  end

                  Font.draw(Strings("A:ASSIGN"), 16, 126)
                  Font.draw(Strings("B:BACK"), 100, 126)
              end
          end

          return self
      end
  })

  mod.content.screens:register("NuzlockeDevToolsScreen", {
      new = function(game)
          local self = {
              game = game,
              screenId = "NuzlockeDevToolsScreen",
              isOpaque = true,
              cursor = 1,
              status = "READY",
              exportInfo = nil,
              reportScroll = 0,
              viewingReport = false,
              viewingFileInfo = false,
              fileInfoScroll = 0,
          }
          self.nuzlockeUi = mod.exports.nuzlocke_ui.describeScreen(self)

          local function cachedReport()
              if type(self.liveReportText) == "string"
                  and self.liveReportText ~= "" then
                  return self.liveReportText
              end
              return tostring(mod.exports.__beta26.Dev.lastExportText or "")
          end

          local function refreshLiveReport()
              local ok, text, report = pcall(
                  mod.exports.__beta26.Dev.selfTestText, self.game)
              if ok and type(text) == "string" and text ~= "" then
                  self.liveReportText = text
                  self.liveReport = report
                  self.reportCode = type(report) == "table"
                      and report.report_code or nil
                  self.status = "LIVE REPORT"
                  return true
              end
              self.status = "REPORT FAIL"
              return false
          end

          local function reloadStoredReport()
              local ok, info =
                  mod.exports.__beta26.Dev.reloadStoredSelfTest(self.game)
              if ok and type(info) == "table" then
                  self.exportInfo = info
                  self.liveReportText = nil
                  self.liveReport = nil
                  self.reportCode = nil
                  self.status = "LOADED"
                  return true
              end
              self.status = "LOAD FAIL"
              return false
          end

          -- 2.5.7: Dev diagnostics must stay readable on the native 160px R/B/Y
          -- surface. The general wrapText helper is word-aware but deliberately
          -- leaves a single long token intact, which is wrong for report codes,
          -- playthrough IDs, storage keys, and other diagnostic identifiers.
          -- Keep a Dev-only hard wrapper so every emitted row respects the
          -- viewport width without changing normal menu/description wrapping.
          local function devUiWrapText(text, width)
              width = math.max(8, math.floor(tonumber(width) or 16))
              local out = {}
              local line = ""

              local function flush()
                  if line ~= "" then
                      out[#out + 1] = line
                      line = ""
                  end
              end

              local function appendToken(token)
                  token = tostring(token or "")
                  while #token > width do
                      if line ~= "" then flush() end
                      out[#out + 1] = token:sub(1, width)
                      token = token:sub(width + 1)
                  end
                  if token == "" then return end
                  if line == "" then
                      line = token
                  elseif #line + 1 + #token <= width then
                      line = line .. " " .. token
                  else
                      flush()
                      line = token
                  end
              end

              for token in tostring(text or ""):gmatch("%S+") do
                  appendToken(token)
              end
              flush()
              if #out == 0 then out[1] = "" end
              return out
          end

          local function appendReportCodeLines(code, width, out)
              out[#out + 1] = "REPORT CODE:"
              local line = ""
              for group in tostring(code or ""):gmatch("[^-]+") do
                  local candidate = line == "" and group or (line .. "-" .. group)
                  if #candidate <= width then
                      line = candidate
                  else
                      if line ~= "" then out[#out + 1] = line end
                      line = group
                  end
              end
              if line ~= "" then out[#out + 1] = line end
          end

          -- v0.2.x storage is deliberately opaque. Show the bound context and
          -- logical key without pretending Gen1Recomp gave the mod a host path.
          local function storageInfoLines(width)
              width = math.max(8, math.floor(tonumber(width) or 16))
              local e = mod.exports.__beta26.Dev.lastExport or {}
              local context = type(e.storageContext) == "table"
                  and e.storageContext or {}
              local lines = {}

              local function appendWrapped(text)
                  local wrapped = devUiWrapText(tostring(text or ""), width)
                  for _, wrappedLine in ipairs(wrapped) do
                      lines[#lines + 1] = wrappedLine
                  end
              end

              local function add(label, value)
                  appendWrapped(tostring(label))
                  value = tostring(value or "(none)")
                  if value == "" then value = "(empty)" end
                  appendWrapped(value)
              end

              appendWrapped("DEV STORAGE INFO")
              add("ENGINE:", context.engineVersion)
              add("GAME:", context.gameVersion)
              add("PLAYTHROUGH:", context.playthroughId)
              add("STORAGE KEY:", e.storageKey or "dev/self_test_latest")
              appendWrapped("HOST PATH: NOT EXPOSED")
              appendWrapped("WRITE CALL: " .. tostring(e.writeReturned == true))
              appendWrapped("READ: " .. tostring(e.readSucceeded == true))
              appendWrapped("READBACK: " .. (e.readBackMatches == nil
                  and "N/A" or tostring(e.readBackMatches == true)))
              appendWrapped("VERIFIED: " .. tostring(e.verified == true))
              if e.historyKey then add("HISTORY:", e.historyKey) end
              if e.historyCount ~= nil then
                  appendWrapped("HISTORY COUNT: " .. tostring(e.historyCount))
              end
              if e.breadcrumbCount ~= nil then
                  appendWrapped("BREADCRUMBS: " .. tostring(e.breadcrumbCount))
              end
              appendWrapped("SIZE: " .. tostring(e.bytesRead or "?")
                  .. "/" .. tostring(e.expectedBytes or "?"))
              if e.storageCode then add("CODE:", e.storageCode) end
              if e.storageMessage then add("DETAIL:", e.storageMessage) end
              return lines
          end

          -- 2.5.6: self:update() can enter report-view mode before the helper's
          -- later assignment. Forward-declare it so the closure captures this
          -- local instead of resolving a nil global on the next frame.
          local devReportDisplayLines

          function self:update()
              local input = self.game and self.game.input
              if not input then return end

              if self.viewingReport then
                  if input:wasPressed("b") or input:wasPressed("start") then
                      self.viewingReport = false
                      self.reportScroll = 0
                      return
                  end
                  local width = mod.exports.__beta26.runtimeIsGold(self.game)
                      and 18 or 16
                  local visible = mod.exports.__beta26.runtimeIsGold(self.game)
                      and 9 or 8
                  local lines = devReportDisplayLines(cachedReport(), width)
                  local maxScroll = math.max(0, #lines - visible)
                  if input:wasPressed("down") then
                      self.reportScroll = math.min(maxScroll,
                          (self.reportScroll or 0) + 1)
                  elseif input:wasPressed("up") then
                      self.reportScroll = math.max(0,
                          (self.reportScroll or 0) - 1)
                  elseif input:wasPressed("a")
                      or input:wasPressed("left")
                      or input:wasPressed("right") then
                      refreshLiveReport()
                      self.reportScroll = 0
                  end
                  return
              end

              if self.viewingFileInfo then
                  if input:wasPressed("b") or input:wasPressed("start") then
                      self.viewingFileInfo = false
                      self.fileInfoScroll = 0
                      return
                  end
                  local width = mod.exports.__beta26.runtimeIsGold(self.game)
                      and 18 or 16
                  local lines = storageInfoLines(width)
                  local visible = mod.exports.__beta26.runtimeIsGold(self.game)
                      and 8 or 8
                  local maxScroll = math.max(0, #lines - visible)
                  if input:wasPressed("down") then
                      self.fileInfoScroll = math.min(maxScroll,
                          (self.fileInfoScroll or 0) + 1)
                  elseif input:wasPressed("up") then
                      self.fileInfoScroll = math.max(0,
                          (self.fileInfoScroll or 0) - 1)
                  end
                  return
              end

              if input:wasPressed("b") or input:wasPressed("start") then
                  self.game.stack:pop()
                  return
              end

              if input:wasPressed("down") then
                  self.cursor = math.min(5, self.cursor + 1)
                  return
              elseif input:wasPressed("up") then
                  self.cursor = math.max(1, self.cursor - 1)
                  return
              end

              if input:wasPressed("a")
                  or input:wasPressed("left")
                  or input:wasPressed("right") then
                  if self.cursor == 1 then
                      local ok, info =
                          mod.exports.__beta26.Dev.exportSelfTest(self.game)
                      self.exportInfo = type(info) == "table" and info or nil
                      if ok and self.exportInfo then
                          if self.exportInfo.verified then
                              self.status = "SAVED"
                          elseif self.exportInfo.writeReturned then
                              self.status = "UNVERIFIED"
                          else
                              self.status = "LOG ONLY"
                          end
                      else
                          self.status = "FAILED"
                      end
                  elseif self.cursor == 2 then
                      if refreshLiveReport() then
                          self.viewingReport = true
                          self.reportScroll = 0
                      end
                  elseif self.cursor == 3 then
                      reloadStoredReport()
                  elseif self.cursor == 4 then
                      self.viewingFileInfo = true
                      self.fileInfoScroll = 0
                  else
                      pcall(mod.exports.__beta26.Dev.logSnapshot,
                          "dev_tools_manual", self.game)
                      self.status = "LOGGED"
                  end
              end
          end

          devReportDisplayLines = function(text, width)
              width = math.max(8, math.floor(tonumber(width) or 16))
              local out = {}
              for raw in (tostring(text or "") .. "\n"):gmatch("(.-)\n") do
                  if raw == "" then
                      out[#out + 1] = ""
                  else
                      local reportCode = raw:match("^report_code=(NZR%d+%-.+)$")
                      if reportCode then
                          appendReportCodeLines(reportCode, width, out)
                      else
                          local wrapped = devUiWrapText(raw, width)
                          for _, wrappedLine in ipairs(wrapped) do
                              out[#out + 1] = wrappedLine
                          end
                      end
                  end
              end
              return out
          end

          function self:draw()
              if mod.exports.__beta26.runtimeIsGold(self.game) then
                  local Chrome = require("src.ui.gen2.Chrome")
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)

                  if self.viewingReport then
                      Chrome.print(Strings("DEV REPORT"), 5, 1)
                      local lines = devReportDisplayLines(cachedReport(), 18)
                      for i = 1, 9 do
                          local line = lines[(self.reportScroll or 0) + i]
                          if not line then break end
                          Chrome.print(line, 1, 2 + i)
                      end
                      if self.reportScroll > 0 then
                          Chrome.cursor(18, 2, true)
                      end
                      if self.reportScroll + 9 < #lines then
                          local GoldFont = require("src.render.Font")
                          GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, 12 * 8)
                      end
                      Chrome.print(Strings("A:REFRESH B:BACK"), 3, 16)
                      return
                  end

                  if self.viewingFileInfo then
                      Chrome.print(Strings("STORAGE INFO"), 5, 1)
                      local lines = storageInfoLines(18)
                      for i = 1, 8 do
                          local line = lines[(self.fileInfoScroll or 0) + i]
                          if not line then break end
                          Chrome.print(line, 1, 2 + i)
                      end
                      if self.fileInfoScroll > 0 then
                          Chrome.cursor(18, 2, true)
                      end
                      if self.fileInfoScroll + 8 < #lines then
                          local GoldFont = require("src.render.Font")
                          GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, 12 * 8)
                      end
                      Chrome.print(Strings("UP/DN B:BACK"), 4, 16)
                      return
                  end

                  Chrome.print(Strings("DEV TOOLS"), 5, 1)
                  local rows = {
                      "RUN + SAVE", "VIEW REPORT", "RELOAD SAVED",
                      "STORAGE INFO", "LOG SNAP"
                  }
                  for i, label in ipairs(rows) do
                      local y = 2 + (i - 1) * 2
                      if self.cursor == i then
                          Chrome.cursor(1, y)
                      end
                      Chrome.print(Strings(label), 3, y)
                  end
                  Chrome.print(Strings("STATUS"), 2, 13)
                  Chrome.print(Strings(self.status), 2, 14)
                  Chrome.print(Strings("B:BACK"), 12, 16)
                  return
              end

              local Font = mod.ui.Font
              local Theme = require("src.ui.Theme")
              love.graphics.setColor(1, 1, 1, 1)
              love.graphics.rectangle("fill", 0, 0, 160, 144)
              love.graphics.setColor(0, 0, 0, 1)
              love.graphics.rectangle("line", 6, 6, 148, 132)
              love.graphics.rectangle("line", 8, 8, 144, 128)
              love.graphics.setColor(1, 1, 1, 1)

              if self.viewingReport then
                  Font.draw(Strings("DEV REPORT"), 50, 14)
                  local lines = devReportDisplayLines(cachedReport(), 16)
                  local y = 30
                  for i = 1, 8 do
                      local line = lines[(self.reportScroll or 0) + i]
                      if not line then break end
                      Font.draw(line, 12, y)
                      y = y + 11
                  end
                  if self.reportScroll > 0 then
                      Font.drawCode(Theme.cursor, 146, 28)
                  end
                  if self.reportScroll + 8 < #lines then
                      Font.drawCode(Theme.moreArrow or 0xEE, 146, 112)
                  end
                  Font.draw(Strings("A:REFRESH B:BACK"), 20, 126)
                  return
              end

              if self.viewingFileInfo then
                  Font.draw(Strings("STORAGE INFO"), 52, 14)
                  local lines = storageInfoLines(16)
                  local y = 30
                  for i = 1, 8 do
                      local line = lines[(self.fileInfoScroll or 0) + i]
                      if not line then break end
                      Font.draw(line, 12, y)
                      y = y + 12
                  end
                  if self.fileInfoScroll > 0 then
                      Font.drawCode(Theme.cursor, 146, 28)
                  end
                  if self.fileInfoScroll + 8 < #lines then
                      Font.drawCode(Theme.moreArrow or 0xEE, 146, 112)
                  end
                  Font.draw(Strings("UP/DN  B:BACK"), 22, 126)
                  return
              end

              Font.draw(Strings("DEV TOOLS"), 50, 14)
              local rows = {
                  "RUN + SAVE", "VIEW REPORT", "RELOAD SAVED",
                  "STORAGE INFO", "LOG SNAP"
              }
              local ys = { 34, 50, 66, 82, 98 }
              for i, label in ipairs(rows) do
                  if self.cursor == i then
                      Font.drawCode(Theme.cursor, 12, ys[i])
                  end
                  Font.draw(Strings(label), 28, ys[i])
              end
              Font.draw(Strings("STATUS:"), 20, 116)
              Font.draw(Strings(self.status), 72, 116)
          end

          return self
      end
  })

  mod.content.screens:register("NuzlockeTrackerScreen", {
      new = function(game)
          local self = {
              game = game,
              screenId = "NuzlockeTrackerScreen",
              isOpaque = true,
              tab = 1,
              scroll = 0,
              log = trackerLog(),
              marqueeTime = 0,
              arrowTime = 0,
          }

          self.nuzlockeUi = mod.exports.nuzlocke_ui.describeScreen(self)
          self.presentationRole = "tracker"
          self.presentationStateOwner = "nuzlocke"
          self.presentationNativeFallback = true

          -- 2.3.31 tracker presentation stabilization:
          -- Runtime testing showed the 304x144 override makes the tracker
          -- appear physically shrunk because the engine scales the oversized
          -- logical surface down even though the tracker content remains in
          -- the native 160px region. Keep the screen opt-out markers, but use
          -- the native Gen 1 surface again.
          self.uiModLayout = "classic"
          self.keepClassicUi = true
          self.__nuzlockeOwnsTrackerLayout = true

          -- Prepare tracker state once per refresh. All presentation paths
          -- consume the same row snapshot instead of repeating projection,
          -- cleanup, route sorting, and row construction within one frame.
          function self:refreshTrackerRows()
              syncCurrentArea(self.game)
              if type(mod.exports.__beta26.ensureEncounterProjection) == "function" then
                  pcall(mod.exports.__beta26.ensureEncounterProjection)
              end
              mod.exports.__beta26.cleanupStarterDuplicate()
              if type(mod.exports.__beta26.syncTrackerDeathProjection) == "function" then
                  pcall(mod.exports.__beta26.syncTrackerDeathProjection)
              end
              self.__trackerLogRows = getTrackerLogRows(true)
              self.__trackerMapRows = getTrackerMapRows(self.game, true)
          end

          function self:trackerRows(tab)
              if type(self.__trackerLogRows) ~= "table"
                  or type(self.__trackerMapRows) ~= "table" then
                  self:refreshTrackerRows()
              end
              return tab == 1 and self.__trackerLogRows or self.__trackerMapRows
          end

          self:refreshTrackerRows()

          function self:nuzlockeModernUiModel()
              local guideEnabled = mod.save:get("area_guide_enabled", true) == true
              local rawRows = self:trackerRows(self.tab)
              local rows = {}
              for _, row in ipairs(rawRows) do
                  local areaLabel
                  local catch
                  if self.tab == 1 then
                      areaLabel = row.area == "__LEGACY__"
                          and Strings("LEGACY") or routeName(row.area)
                      catch = row.catch or {}
                  else
                      areaLabel = row.area and (row.area.name or row.area.id) or "???"
                      catch = row.catch
                  end
                  local result = "..."
                  if catch then
                      if catch.dead == true or catch.status == "DEAD" then
                          result = Strings("DEAD %s", tostring(catch.species or "???"))
                      elseif catch.failed then
                          result = Strings("FAILED %s", tostring(catch.species or "???"))
                      elseif catch.isShiny then
                          result = "*" .. tostring(catch.species or "???")
                      else
                          result = tostring(catch.species or "???")
                      end
                  end
                  local context = mod.exports.__beta26.compat21
                      and mod.exports.__beta26.compat21.trackerCatchContext
                      and mod.exports.__beta26.compat21.trackerCatchContext(
                          self.game, catch, areaLabel) or nil
                  rows[#rows + 1] = {
                      label = tostring(Strings(areaLabel)),
                      right = tostring(Strings(result)),
                      detail = context and tostring(context.tag) or nil,
                      provider = context and context.provider or nil,
                  }
              end
              local actualCount = #rows
              if actualCount == 0 then
                  rows[1] = {
                      label = tostring(Strings("NO ENTRIES YET")),
                      right = "",
                      empty = true,
                  }
              end
              local cap = nextLevelCap(self.game and self.game.save)
              return {
                  title = Strings(self.tab == 1 and "ENCOUNTER LOG" or "AREA GUIDE"),
                  rows = rows,
                  index = actualCount > 0
                      and math.min(actualCount, self.scroll + 1) or nil,
                  scroll = actualCount > 0 and self.scroll or 0,
                  footer = guideEnabled
                      and { Strings("A/LEFT/RIGHT: PAGE"), Strings("B: BACK") }
                      or { Strings("B: BACK") },
                  details = (function()
                      local details = {
                          cap >= 100 and Strings("NEXT CAP: MAX")
                              or Strings("NEXT CAP: %d", cap),
                          Strings("%d entries", actualCount),
                      }
                      local rc = mod.exports.__beta26.compat21
                          and mod.exports.__beta26.compat21.randomizerTrackerContext
                          and mod.exports.__beta26.compat21.randomizerTrackerContext(self.game)
                      if rc then
                          details[#details + 1] = Strings("RNG: %s", rc.provider)
                      end
                      local selected = actualCount > 0
                          and rows[math.min(actualCount, self.scroll + 1)] or nil
                      if selected and selected.detail then
                          details[#details + 1] =
                              Strings("TYPE: %s", tostring(selected.detail))
                      end
                      if selected and selected.provider then
                          details[#details + 1] =
                              Strings("FROM: %s", tostring(selected.provider))
                      end
                      return details
                  end)(),
              }
          end

          function self:nuzlockeModernUiAction(action)
              local guideEnabled = mod.save:get("area_guide_enabled", true) == true
              if action == "back" then
                  self.game.stack:pop()
                  return true
              elseif guideEnabled and (action == "select"
                  or action == "left" or action == "right") then
                  if action == "left" then
                      self.tab = 1
                  elseif action == "right" then
                      self.tab = 2
                  else
                      self.tab = self.tab == 1 and 2 or 1
                  end
                  self.scroll = 0
                  self.marqueeTime = 0
                  return true
              elseif action == "up" or action == "down" then
                  local count = #self:trackerRows(self.tab)
                  local maxScroll = math.max(0, count - 4)
                  if action == "up" then
                      self.scroll = math.max(0, self.scroll - 1)
                  else
                      self.scroll = math.min(maxScroll, self.scroll + 1)
                  end
                  self.marqueeTime = 0
                  return true
              end
              return false
          end

          function self:update(dt)
              self:refreshTrackerRows()

              if self.game.input:wasPressed("b") then
                  self.game.stack:pop()
                  return
              end

              local guideEnabled = mod.save:get("area_guide_enabled", true) == true
              if not guideEnabled then
                  self.tab = 1
              end

              -- A is the page toggle. It is deliberately unavailable when
              -- Area Guide is locked OFF.
              if guideEnabled and self.game.input:wasPressed("a") then
                  self.tab = (self.tab == 1) and 2 or 1
                  self.scroll = 0
                  self.marqueeTime = 0
              end

              -- Keep left/right as a convenient secondary page control only
              -- when the Area Guide is enabled.
              if guideEnabled and self.game.input:wasPressed("left") then
                  self.tab = 1
                  self.scroll = 0
                  self.marqueeTime = 0
              elseif guideEnabled and self.game.input:wasPressed("right") then
                  self.tab = 2
                  self.scroll = 0
                  self.marqueeTime = 0
              end

              local listCount = #self:trackerRows(self.tab)
              local maxScroll = math.max(0, listCount - 4)

              if self.game.input:wasPressed("down") and self.scroll < maxScroll then
                  self.scroll = self.scroll + 1
                  self.marqueeTime = 0
              elseif self.game.input:wasPressed("up") and self.scroll > 0 then
                  self.scroll = self.scroll - 1
                  self.marqueeTime = 0
              end

              self.marqueeTime = self.marqueeTime + (dt or 0)

              -- The arrow has its own timer so reaching the last page makes
              -- it completely inert/invisible instead of continuing a hidden
              -- blink animation. It restarts calmly when another page exists.
              local arrowListCount = #self:trackerRows(self.tab)
              local arrowMaxScroll = math.max(0, arrowListCount - 4)
              if self.scroll < arrowMaxScroll then
                  self.arrowTime = self.arrowTime + (dt or 0)
              else
                  self.arrowTime = 0
              end
          end

          function self:draw()
              -- Gold tracker presentation: native Gen 2 tile-grid chrome with
              -- the same tracker data/model and tab semantics as R/B/Y.
              if mod.exports.__beta26.runtimeIsGold(self.game) then
                  local Chrome = require("src.ui.gen2.Chrome")
                  local GoldFont = require("src.render.Font")
                  local guideEnabled = mod.save:get("area_guide_enabled", true) == true
                  Chrome.clear()
                  Chrome.box(0, 0, 20, 18)
                  Chrome.print(Strings("ENC TRACKER"), 2, 1)
                  Chrome.print(Strings(self.tab == 1 and "LOG" or "MAP"), 15, 1)
                  Chrome.print(Strings("AREA"), 2, 3)
                  Chrome.print(Strings("RESULT"), 11, 3)

                  local rows = self:trackerRows(self.tab)
                  local listCount = #rows
                  if listCount == 0 then
                      Chrome.print(Strings("NO ENTRIES YET"), 2, 5)
                  end
                  for slot = 1, 4 do
                      local i = self.scroll + slot
                      local row = rows[i]
                      if not row then break end
                      local ty = 5 + (slot - 1) * 2
                      local areaLabel
                      local catch
                      if self.tab == 1 then
                          areaLabel = row.area == "__LEGACY__"
                              and Strings("LEGACY") or routeName(row.area)
                          catch = row.catch or {}
                      else
                          areaLabel = row.area and (row.area.name or row.area.id) or "???"
                          catch = row.catch
                      end
                      local result = "..."
                      if catch then
                          if catch.dead == true or catch.status == "DEAD" then
                              result = Strings("DEAD %s", tostring(catch.species or "???"))
                          elseif catch.failed then
                              result = Strings("FAIL %s", tostring(catch.species or "???"))
                          elseif catch.isShiny then
                              result = "*" .. tostring(catch.species or "???")
                          else
                              result = tostring(catch.species or "???")
                          end
                      end
                      Chrome.print(marqueeText(Strings(areaLabel), 8,
                          self.marqueeTime, 3.8), 2, ty)
                      Chrome.print(marqueeText(Strings(result), 8,
                          self.marqueeTime, 3.8), 11, ty)
                      local context = mod.exports.__beta26.compat21
                          and mod.exports.__beta26.compat21.trackerCatchContext
                          and mod.exports.__beta26.compat21.trackerCatchContext(
                              self.game, catch, areaLabel)
                      if context and context.tag then
                          Chrome.print(Strings(tostring(context.tag)), 11, ty + 1)
                      end
                  end

                  local maxScroll = math.max(0, listCount - 4)
                  if self.scroll > 0 then Chrome.cursor(18, 3, true) end
                  if self.scroll < maxScroll then
                      GoldFont.drawCode(Chrome.DOWN_ARROW, 18 * 8, 13 * 8)
                  end
                  local cap = nextLevelCap(self.game and self.game.save)
                  Chrome.print(cap >= 100 and Strings("CAP MAX")
                      or Strings("CAP LV%d", cap), 2, 15)
                  if guideEnabled then Chrome.print(Strings("A:PAGE"), 10, 15) end
                  Chrome.print(Strings("B:BACK"), 12, 16)
                  return
              end

              local Font = mod.ui.Font
              local guideEnabled = mod.save:get("area_guide_enabled", true) == true

              -- Native Gen 1 160x144 / 20-column surface. All tracker
              -- content is intentionally kept inside this region.
              local trackerCols = 20
              Font.drawBox(0, 0, trackerCols, 18)
              -- "ENC TRACKER" = 11 chars from X=14 -> ends ~X=124, safe.
              -- Tab indicator [1]/[2] shown at right to show current page.
              Font.draw(Strings("ENC TRACKER"), 14, 8)
              local tabLabel = Strings(self.tab == 1 and "[LOG]" or "[MAP]")
              Font.draw(tabLabel, 110, 8)

              local y = 26
              local listCount

              if self.tab == 1 then
                  Font.draw(Strings("AREA      RESULT"), 16, y)
                  y = y + 12
                  local rows = self:trackerRows(1)
                  listCount = #rows

                  for i = self.scroll + 1, math.min(self.scroll + 4, #rows) do
                      local row = rows[i]
                      local catch = row.catch or {}
                      local species = catch.species or "???"
                      if catch.dead == true or catch.status == "DEAD" then
                          species = Strings("DEAD %s", tostring(catch.species or "???"))
                      elseif catch.failed then
                          -- beta.26.4: FAIL-W/FAIL-O was compact but cryptic.
                          -- Show a plain-language result plus the encountered
                          -- species; the existing marquee now exposes the full
                          -- label in the seven-character result column.
                          species = Strings("FAILED %s", tostring(catch.species or "???"))
                      elseif catch.isShiny then
                          species = "*" .. species
                      end
                      local routeLabel = (row.area == "__LEGACY__")
                          and Strings("LEGACY") or routeName(row.area)
                      Font.draw(marqueeText(routeLabel, 8, self.marqueeTime), 16, y)
                      Font.draw(marqueeText(species, 7, self.marqueeTime), 96, y)
                      local context = mod.exports.__beta26.compat21
                          and mod.exports.__beta26.compat21.trackerCatchContext
                          and mod.exports.__beta26.compat21.trackerCatchContext(
                              self.game, catch, routeLabel)
                      if context and context.tag then
                          Font.draw(Strings(tostring(context.tag)), 96, y + 8)
                      end
                      y = y + 18
                  end
              else
                  Font.draw(Strings("AREA      RESULT"), 16, y)
                  y = y + 12
                  local rows = self:trackerRows(2)
                  listCount = #rows

                  for i = self.scroll + 1, math.min(self.scroll + 4, #rows) do
                      local row = rows[i]
                      local r = row.area
                      local catch = row.catch
                      local status = "..."
                      if catch then
                          if catch.dead == true or catch.status == "DEAD" then
                              status = Strings("DEAD %s", tostring(catch.species or "???"))
                          elseif catch.failed then
                              status = Strings("FAILED %s", tostring(catch.species or "???"))
                          elseif catch.isShiny then
                              status = "*" .. tostring(catch.species or "???")
                          else
                              status = tostring(catch.species or "???")
                          end
                      end
                      Font.draw(marqueeText(Strings(r.name), 8,
                          self.marqueeTime, 3.8), 16, y)
                      Font.draw(marqueeText(status, 7, self.marqueeTime), 96, y)
                      local context = mod.exports.__beta26.compat21
                          and mod.exports.__beta26.compat21.trackerCatchContext
                          and mod.exports.__beta26.compat21.trackerCatchContext(
                              self.game, catch, r and (r.name or r.id))
                      if context and context.tag then
                          Font.draw(Strings(tostring(context.tag)), 96, y + 8)
                      end
                      y = y + 18
                  end
              end

              if listCount == 0 then
                  Font.draw(Strings("NO ENTRIES YET"), 16, y)
              end

              local maxScroll = math.max(0, listCount - 4)
              local canScrollUp = self.scroll > 0
              local canScrollDown = self.scroll < maxScroll
              local blinkOn = math.floor(self.arrowTime / 1.0) % 2 == 0

              if canScrollUp and blinkOn then
                  Font.draw(Strings("^"), 72, 18)
              end

              -- Bottom bar: navigation hints + level cap reminder.
              local cap = nextLevelCap(self.game and self.game.save)
              local capStr = cap >= 100 and Strings("CAP:MAX")
                  or Strings("CAP:%d", cap)
              Font.draw(capStr, 14, 112)
              local rc = mod.exports.__beta26.compat21
                  and mod.exports.__beta26.compat21.randomizerTrackerContext
                  and mod.exports.__beta26.compat21.randomizerTrackerContext(self.game)
              if rc and not mod.exports.__beta26.runtimeIsGold(self.game) then
                  Font.draw(Strings("RNG"), 54, 112)
              end
              if guideEnabled then
                  Font.draw(Strings("A:PG"), 72, 112)
              end
              Font.draw(Strings("B:X"), 122, 112)

              if canScrollDown and blinkOn then
                  local Theme = require("src.ui.Theme")
                  Font.drawCode(Theme.moreArrow or 0xEE, 72, 122)
              end
          end

          return self
      end
  })

  ---------------------------------------------------------------------
  -- CATCH INFO SCREEN
  -- Uses the same compact layout as the working catch-info page, but now
  -- includes the Nuzlocke encounter type and a factual loss summary.
  ---------------------------------------------------------------------
  mod.content.screens:register("NuzlockeCatchInfoScreen", {
      new = function(game, ctx)
          local mon = ctx and ctx.mon

          -- R/B/Y starters are canonically a Pallet Town encounter. Keep the
          -- established repair here because NUZ INFO may be the first screen
          -- that receives the concrete mon after an older acquisition callback.
          if type(mon) == "table" and mon.species then
              local ver = getGameVersion and getGameVersion() or "RED"
              local sp = tostring(mon.species or ""):upper()
              local locText = tostring(mon.catchLocation or ""):upper()
              local rbyStarter = (ver == "YELLOW" and sp == "PIKACHU")
                  or ((ver == "RED" or ver == "BLUE")
                      and (sp == "BULBASAUR" or sp == "CHARMANDER"
                          or sp == "SQUIRTLE"))
              if rbyStarter and (locText == "" or locText == "UNKNOWN"
                  or locText:find("OAK", 1, true)
                  or locText:find("LAB", 1, true)) then
                  mon.catchLocation = "PALLET_TOWN"
                  mon.encounterType = mon.encounterType or "gift"
                  mon.nuzlockeTrackerRegistered = true
                  Identity.setPokemonOrigin(mon, mon.nuzlockeOrigin or "NORMAL")
                  Identity.baselineAdd(mon, mon.nuzlockeOrigin or "NORMAL")
              end
          end

          local self = {
              game = game,
              screenId = "NuzlockeCatchInfoScreen",
              isOpaque = true,
              mon = mon,
              pageIndex = 1,
              marqueeTime = 0,
          }

          local function enabledPages()
              local pages = {}
              if mod.save:get("catch_info", true) == true then
                  pages[#pages + 1] = "catch"
              end
              if mod.save:get("stat_info", true) == true then
                  pages[#pages + 1] = "stat"
              end
              if mod.save:get("move_info", true) == true then
                  pages[#pages + 1] = "move"
              end
              -- A stale party menu can still have NUZ INFO open while every
              -- toggle is switched off elsewhere. Fail safe to one catch page
              -- rather than constructing a zero-page screen.
              if #pages == 0 then pages[1] = "catch" end
              return pages
          end

          local function currentPage()
              local pages = enabledPages()
              if self.pageIndex > #pages then self.pageIndex = 1 end
              if self.pageIndex < 1 then self.pageIndex = #pages end
              return pages[self.pageIndex], pages
          end

          local function cycle(delta)
              local _, pages = currentPage()
              if #pages <= 1 then return end
              self.pageIndex = self.pageIndex + delta
              if self.pageIndex > #pages then self.pageIndex = 1 end
              if self.pageIndex < 1 then self.pageIndex = #pages end
          end

          function self:update(dt)
              self.marqueeTime = (self.marqueeTime or 0) + (tonumber(dt) or 0)
              local input = self.game and self.game.input
              if not input then return end
              if input:wasPressed("b") then
                  self.game.stack:pop()
              elseif input:wasPressed("right") or input:wasPressed("a") then
                  cycle(1)
              elseif input:wasPressed("left") then
                  cycle(-1)
              end
          end

          local function displayOrigin(value)
              value = value and value.nuzlockeOrigin
              if value == "LEGACY" then return Strings("LEGACY") end
              if value == "EDITED" then return Strings("EXTERNAL") end
              if value == "PLAYER_CONFIRMED" then return Strings("CONFIRMED") end
              return Strings("NORMAL")
          end

          local function displayEncounterType(value)
              if value and (value.nuzlockeGlitch == true
                  or mod.exports.__beta26.getGlitchSpeciesInfo(
                      game, value.species).isGlitch) then
                  return Strings("GLITCH")
              end
              local kind = value and (value.encounterType
                  or value.nuzlockeEncounterType)
              if not kind then return Strings("UNKNOWN") end
              local labels = {
                  overworld = "OVERWORLD", wild = "WILD", town = "TOWN",
                  safari = "SAFARI", grass = "GRASS", surf = "SURF",
                  fishing = "FISHING", old_rod = "OLD ROD",
                  good_rod = "GOOD ROD", super_rod = "SUPER ROD",
                  gift = "GIFT", starter = "STARTER", static = "STATIC",
                  trade = "TRADE", wonder_trade = "WONDER TRADE",
              }
              return Strings(labels[kind] or tostring(kind):upper())
          end

          local function legalityInfo(value)
              if not value then return nil end
              local compat21 = mod.exports.__beta26.compat21
              return compat21 and compat21.pokemonLegality
                  and compat21.pokemonLegality(self.game, value) or nil
          end

          local function provenanceInfo(value)
              if not value then return nil end
              local compat21 = mod.exports.__beta26.compat21
              return compat21 and compat21.pokemonProvenance
                  and compat21.pokemonProvenance(self.game, value) or nil
          end

          local function pokemonLabel(value)
              if not value then return Strings("NO DATA") end
              local label = value.nickname
              if label == nil or label == "" then
                  label = mod.exports.__beta26.safeSpeciesLabel(
                      self.game, value.species)
              end
              return Strings(tostring(label))
          end

          local function hpDV(dvs)
              dvs = type(dvs) == "table" and dvs or {}
              if tonumber(dvs.hp) then return math.floor(tonumber(dvs.hp)) end
              local special = tonumber(dvs.special)
                  or tonumber(dvs.specialAttack)
                  or tonumber(dvs.specialDefense) or 0
              return ((tonumber(dvs.attack) or 0) % 2) * 8
                  + ((tonumber(dvs.defense) or 0) % 2) * 4
                  + ((tonumber(dvs.speed) or 0) % 2) * 2
                  + (special % 2)
          end

          local function statLine(label, value, dv, exp)
              local stat = tonumber(value)
              local d = tonumber(dv)
              local e = tonumber(exp)
              return ("%s %s D%s E%s"):format(
                  tostring(label),
                  stat and tostring(math.floor(stat)) or "--",
                  d and tostring(math.floor(d)) or "--",
                  e and tostring(math.floor(e)) or "--")
          end

          local function statLines(value)
              if not value then
                  return { Strings("STAT INFO"), Strings("NO DATA") }
              end
              local stats = type(value.stats) == "table" and value.stats or {}
              local dvs = type(value.dvs) == "table" and value.dvs or {}
              local exp = type(value.statExp) == "table" and value.statExp or {}
              local gold = mod.exports.__beta26.runtimeIsGold(self.game)
              local maxHp = tonumber(value.maxHp) or tonumber(stats.hp)
                  or tonumber(value.hp) or 0
              local curHp = tonumber(value.hp) or maxHp
              local lines = {
                  Strings("STAT INFO"),
                  pokemonLabel(value),
                  Strings("LV %d  HP %d/%d",
                      math.floor(tonumber(value.level) or 0),
                      math.floor(curHp), math.floor(maxHp)),
                  Strings("STAT VALUE DV STATEXP"),
                  statLine("HP ", stats.hp or maxHp, hpDV(dvs), exp.hp),
                  statLine("ATK", stats.attack, dvs.attack, exp.attack),
                  statLine("DEF", stats.defense, dvs.defense, exp.defense),
                  statLine("SPE", stats.speed, dvs.speed, exp.speed),
              }
              if gold then
                  local sdv = dvs.special or dvs.specialAttack
                      or dvs.specialDefense
                  local sexp = exp.special or exp.specialAttack
                      or exp.specialDefense
                  lines[#lines + 1] =
                      statLine("SPA", stats.specialAttack, sdv, sexp)
                  lines[#lines + 1] =
                      statLine("SDF", stats.specialDefense, sdv, sexp)
                  lines[#lines + 1] = Strings("SPA/SDF SHARE DV+EXP")
              else
                  lines[#lines + 1] =
                      statLine("SPC", stats.special, dvs.special, exp.special)
              end
              return lines
          end

          local function cleanType(value)
              value = tostring(value or "?"):upper()
              value = value:gsub("_TYPE$", "")
              if value == "PSYCHIC_TYPE" then value = "PSYCHIC" end
              return value
          end

          local function accuracyText(value)
              local n = tonumber(value)
              if not n or n <= 0 then return "--" end
              if n > 100 and n <= 255 then
                  n = math.floor((n * 100 / 255) + 0.5)
              end
              return tostring(math.floor(n))
          end

          local function moveLines(value)
              local lines = { Strings("MOVE INFO"), pokemonLabel(value) }
              if not value then
                  lines[#lines + 1] = Strings("NO DATA")
                  return lines
              end
              local moves = type(value.moves) == "table" and value.moves or {}
              for slot = 1, 4 do
                  local move = moves[slot]
                  if move then
                      local id = type(move) == "table" and move.id or move
                      local def = self.game and self.game.data
                          and self.game.data.moves
                          and self.game.data.moves[id] or nil
                      local name = (def and def.name) or tostring(id or "?")
                      if #tostring(name) > 15 then
                          name = tostring(name):sub(1, 15)
                      end
                      local currentPp = type(move) == "table"
                          and tonumber(move.pp) or nil
                      local maxPp = type(move) == "table"
                          and tonumber(move.maxPp) or nil
                      maxPp = maxPp or (def and tonumber(def.pp)) or currentPp
                      local power = def and tonumber(def.power)
                      local typeName = cleanType(def and def.type)
                      lines[#lines + 1] =
                          Strings("%d %s", slot, tostring(name))
                      lines[#lines + 1] = Strings("%s PWR%s ACC%s",
                          typeName,
                          power and power > 0 and tostring(math.floor(power)) or "--",
                          accuracyText(def and def.accuracy))
                      lines[#lines + 1] = Strings("PP %s/%s",
                          currentPp and tostring(math.floor(currentPp)) or "--",
                          maxPp and tostring(math.floor(maxPp)) or "--")
                  else
                      lines[#lines + 1] = Strings("%d --", slot)
                      lines[#lines + 1] = Strings("-- PWR-- ACC--")
                      lines[#lines + 1] = Strings("PP --/--")
                  end
              end
              return lines
          end

          function self:nuzlockeModernUiModel()
              local page, pages = currentPage()
              local rows = {}
              local title = "CATCH INFO"

              if page == "stat" then
                  title = "STAT INFO"
                  local lines = statLines(self.mon)
                  table.remove(lines, 1)
                  for _, line in ipairs(lines) do
                      rows[#rows + 1] = { label = tostring(Strings(tostring(line))) }
                  end
              elseif page == "move" then
                  title = "MOVE INFO"
                  local lines = moveLines(self.mon)
                  table.remove(lines, 1)
                  for _, line in ipairs(lines) do
                      rows[#rows + 1] = { label = tostring(Strings(tostring(line))) }
                  end
              else
                  local value = self.mon
                  if not value then
                      rows[1] = { label = Strings("NO DATA") }
                  else
                      local loc = routeName(value.catchLocation or "UNKNOWN")
                      local legality = legalityInfo(value)
                      local provenance = provenanceInfo(value)
                      rows = {
                          { label = Strings("POKéMON"), right = pokemonLabel(value) },
                          { label = Strings("LOCATION"), right = Strings(loc) },
                          { label = Strings("ENCOUNTER"), right = displayEncounterType(value) },
                          { label = Strings("ORIGIN"), right = displayOrigin(value) },
                          { label = Strings("STATUS"),
                            right = Strings(value.nuzlockeDead == true and "LOST" or "ALIVE") },
                          { label = Strings("LEGALITY"),
                            right = Strings(legality and legality.status or "UNKNOWN") },
                      }
                      if legality and type(legality.reasons) == "table"
                          and #legality.reasons > 0 then
                          rows[#rows + 1] = {
                              label = Strings("RULE"),
                              right = Strings(table.concat(legality.reasons, "/")),
                          }
                      end
                      if provenance and provenance.provider then
                          rows[#rows + 1] = {
                              label = Strings("PROVIDER"),
                              right = Strings(tostring(provenance.provider)),
                          }
                      end
                      if provenance and provenance.source then
                          rows[#rows + 1] = {
                              label = Strings("SOURCE"),
                              right = Strings(tostring(provenance.source)),
                          }
                      end
                      if value.nuzlockeDead == true then
                          rows[#rows + 1] = {
                              label = Strings("CAUSE"),
                              right = tostring(value.deathCauseText
                                  or value.deathCause or "BATTLE"),
                          }
                      elseif Identity.isShiny(value) then
                          rows[#rows + 1] = { label = Strings("SHINY"), right = "*" }
                      end
                  end
              end

              return {
                  title = Strings(title),
                  rows = rows,
                  index = 1,
                  scroll = 0,
                  footer = #pages > 1
                      and { Strings("A/LEFT/RIGHT: PAGE"), Strings("B: BACK") }
                      or { Strings("B: BACK") },
                  details = {
                      Strings("PAGE %d/%d", self.pageIndex, #pages),
                  },
              }
          end

          function self:nuzlockeModernUiAction(action)
              if action == "back" then
                  self.game.stack:pop()
                  return true
              elseif action == "select" or action == "right" then
                  cycle(1)
                  return true
              elseif action == "left" then
                  cycle(-1)
                  return true
              end
              return false
          end

          local function drawGoldLines(lines, title)
              local Chrome = require("src.ui.gen2.Chrome")
              Chrome.clear()
              Chrome.box(0, 0, 20, 18)
              if title then Chrome.print(Strings(title), 2, 1) end
              for i, line in ipairs(lines or {}) do
                  if i <= 14 then
                      Chrome.print(marqueeText(Strings(tostring(line)), 16,
                          self.marqueeTime, 3.8), 2, 1 + i)
                  end
              end
              local _, pages = currentPage()
              if #pages > 1 then
                  Chrome.print(Strings("A/<>:PG"), 2, 16)
              end
              Chrome.print(Strings("B:BACK"), 12, 16)
          end

          local function drawRbyLines(lines, title)
              local Font = mod.ui.Font
              Font.drawBox(0, 0, 20, 18)
              if title then Font.draw(Strings(title), 16, 12) end
              for i, line in ipairs(lines or {}) do
                  if i <= 13 then
                      Font.draw(marqueeText(Strings(tostring(line)), 18,
                          self.marqueeTime, 3.8), 8, 14 + i * 8)
                  end
              end
              local _, pages = currentPage()
              if #pages > 1 then Font.draw(Strings("A/<>:PG"), 8, 132) end
              Font.draw(Strings("B:BACK"), 104, 132)
          end

          local function drawCatch(value)
              local lines = {}
              if not value then
                  lines = { Strings("NO DATA") }
              else
                  local loc = routeName(value.catchLocation or "UNKNOWN")
                  local encounter = displayEncounterType(value)
                  local origin = displayOrigin(value)
                  local dead = value.nuzlockeDead == true
                  local legality = legalityInfo(value)
                  local provenance = provenanceInfo(value)
                  lines = {
                      pokemonLabel(value),
                      Strings("LOCATION"),
                      Strings(loc),
                      Strings("ENCOUNTER"),
                      Strings(encounter),
                      Strings("ORIGIN %s", tostring(origin)),
                      Strings("STATUS %s", dead and "LOST" or "ALIVE"),
                      Strings("LEGAL %s",
                          legality and tostring(legality.status) or "UNKNOWN"),
                  }
                  if legality and type(legality.reasons) == "table"
                      and #legality.reasons > 0 then
                      lines[#lines + 1] =
                          Strings("RULE %s", table.concat(legality.reasons, "/"))
                  end
                  if provenance and provenance.provider then
                      lines[#lines + 1] =
                          Strings("FROM %s", tostring(provenance.provider))
                  end
                  if provenance and provenance.source then
                      lines[#lines + 1] =
                          Strings("SRC %s", tostring(provenance.source))
                  end
                  if dead then
                      lines[#lines + 1] = Strings("CAUSE %s", tostring(
                          value.deathCauseText or value.deathCause or "BATTLE"))
                  elseif Identity.isShiny(value) then
                      lines[#lines + 1] = Strings("SHINY")
                  end
              end
              if mod.exports.__beta26.runtimeIsGold(self.game) then
                  drawGoldLines(lines, "CATCH INFO")
              else
                  drawRbyLines(lines, "CATCH INFO")
              end
          end

          function self:draw()
              local page = currentPage()
              if page == "stat" then
                  local lines = statLines(self.mon)
                  -- The first entry is the page title; the backend draws the
                  -- title separately so the usable body starts with the mon.
                  table.remove(lines, 1)
                  if mod.exports.__beta26.runtimeIsGold(self.game) then
                      drawGoldLines(lines, "STAT INFO")
                  else
                      drawRbyLines(lines, "STAT INFO")
                  end
              elseif page == "move" then
                  local lines = moveLines(self.mon)
                  table.remove(lines, 1)
                  if mod.exports.__beta26.runtimeIsGold(self.game) then
                      drawGoldLines(lines, "MOVE INFO")
                  else
                      drawRbyLines(lines, "MOVE INFO")
                  end
              else
                  drawCatch(self.mon)
              end
          end

          return self
      end
  })

  ---------------------------------------------------------------------
  -- 0.1.86+ CUSTOM-SCREEN CRASH GUARD
  --
  -- Screens.push() isolates a failing mod-owned screen factory, then tries a
  -- built-in fallback. NuzlockeConfigScreen is custom-only, so a failed
  -- construction can turn into a second missing-builtin failure and CTD.
  --
  -- Deliberately stored on exports rather than as another top-level local:
  -- this monolithic chunk is already at Lua's 200-local ceiling.
  ---------------------------------------------------------------------
  mod.exports.__beta26.lastConfigScreenError = nil
  mod.exports.__beta26.pushNuzlockeConfigScreen = function(game, opts)
      local ok, result = pcall(mod.ui.push, game, "NuzlockeConfigScreen",
          opts or {})
      if ok and result then
          mod.exports.__beta26.lastConfigScreenError = nil
          return result
      end

      local err = tostring(result or "unknown setup-screen construction error")
      mod.exports.__beta26.lastConfigScreenError = err
      local short = err:gsub("^.-:%s*", "")
      if #short > 180 then short = short:sub(1, 180) .. "..." end
      local body = mod.exports.__beta26.manualPagedErrorText(
          "NUZLOCKE SETUP ERROR", short)

      local okText, TextBox = pcall(require, "src.render.TextBox")
      if okText and TextBox and game and game.stack then
          local shown = pcall(function()
              game.stack:push(TextBox.new(game, body))
          end)
          if shown then return false end
      end
      return false
  end

  ---------------------------------------------------------------------
  -- TITLE MENU HOOK
  --
  -- SETUP is a NEW-GAME-only entry. The engine's own final title menu is
  -- authoritative: if it contains CONTINUE, a valid save exists for the
  -- currently selected version/slot and SETUP must stay hidden.
  ---------------------------------------------------------------------
  mod.hooks:wrap("ui.title_menu.items", function(next, game, items)
      local result = next(game, items)
      if type(result) ~= "table" then
          result = items
      end

      local goldMode = mod.exports.__beta26.runtimeIsGold(game)
      if goldMode and type(mod.exports.__beta26.installGoldTitleSetupAdapter) == "function" then
          pcall(mod.exports.__beta26.installGoldTitleSetupAdapter)
      end
      local function titleLabel(item)
          if type(item) ~= "table" then return nil end
          local label = item.label
          if type(label) == "table" then
              label = label.source or label.text or label.label
          end
          return type(label) == "string" and label:upper() or nil
      end
      local function isContinueItem(item)
          if type(item) ~= "table" then return false end
          if item.value == "continue" then return true end
          local label = titleLabel(item)
          return label == "CONTINUE" or label == tostring(Strings("CONTINUE")):upper()
      end
      local function isNewGameItem(item)
          if type(item) ~= "table" then return false end
          if item.value == "new" then return true end
          local label = titleLabel(item)
          return label == "NEW GAME" or label == tostring(Strings("NEW GAME")):upper()
      end
      local function insertSetupBeforeNewGame(setup)
          for index, item in ipairs(result) do
              if isNewGameItem(item) then
                  table.insert(result, index, setup)
                  return true
              end
          end
          return false
      end

      for _, item in ipairs(result) do
          -- NEW GAME: stage the pending rules for the upcoming save.
          -- This is the established R/B/Y callback path used by beta.20 and
          -- earlier. Gold uses its native value-dispatch adapter below.
          if isNewGameItem(item) and type(item.onSelect) == "function"
              and item.nuzlockeNewGameWrapped ~= true then
              local originalNewGame = item.onSelect
              item.nuzlockeNewGameWrapped = true
              item.onSelect = function()
                  pcall(installAutomaticDefaultNameAdapters)
                  mod.exports.__beta26.selectSetupProfileScope(game)
                  if not pendingNewGameRules then
                      pendingNewGameRules = loadSetupProfileFromDisk()
                          or makeDefaultPreGameRules()
                  end
                  saveSetupProfileToDisk(pendingNewGameRules)
                  stageNewGameProfile()
                  originalNewGame()
              end
          end

          -- CONTINUE: discard any staged setup so it can never override
          -- the existing save's rules.
          if isContinueItem(item) and type(item.onSelect) == "function"
              and item.nuzlockeContinueWrapped ~= true then
              local originalContinue = item.onSelect
              item.nuzlockeContinueWrapped = true
              item.onSelect = function()
                  pendingNewGameRulesForNextSave = false
                  pendingRulesDirty = false
                  newGameRulesSnapshot = nil
                  newGameRulesCommitPending = false
                  newGameCommitPassesRemaining = 0
                  clearPersistedStagedProfile()
                  originalContinue()
              end
          end
      end

      -- Beta.20's R/B/Y rule: trust the FINAL vanilla menu only for whether
      -- CONTINUE exists, then insert SETUP before NEW GAME. Do not require a
      -- particular NEW GAME row shape before inserting the R/B/Y entry.
      local hasContinue = false
      local hasSetup = false
      for _, item in ipairs(result) do
          if isContinueItem(item) then hasContinue = true end
          if type(item) == "table" and (item.nuzlockeSetup == true
              or item.value == "nuzlocke_setup") then hasSetup = true end
      end

      if not goldMode then
          if not hasContinue and not hasSetup then
              insertSetupBeforeNewGame({
                  label = Strings("SETUP"),
                  nuzlockeSetup = true,
                  onSelect = function()
                      mod.exports.__beta26.selectSetupProfileScope(game)
                      if not pendingNewGameRules or not pendingRulesDirty then
                          pendingNewGameRules = loadSetupProfileFromDisk()
                              or makeDefaultPreGameRules()
                          pendingRulesDirty = false
                      end
                      mod.exports.__beta26.pushNuzlockeConfigScreen(game,
                          { preGame = true, goldMode = false })
                  end
              })
          end
      else
          -- Preserve Gold's dedicated row/value path, but obey the same
          -- NEW-GAME-only contract as R/B/Y. Gold exposes both CONTINUE and
          -- NEW GAME when a save exists, so checking only the NEW GAME value
          -- incorrectly left SETUP visible beside CONTINUE.
          local newGameRow
          for _, item in ipairs(result) do
              if isNewGameItem(item) then
                  newGameRow = item
                  break
              end
          end
          if not hasContinue and not hasSetup and newGameRow
              and newGameRow.value == "new" then
              insertSetupBeforeNewGame({
                  label = Strings("SETUP"),
                  value = "nuzlocke_setup",
                  nuzlockeSetup = true,
              })
          end
      end

      return result
  end)

  ---------------------------------------------------------------------
  -- 0.1.86 TITLE-SETUP COMPATIBILITY FALLBACK
  --
  -- The public ui.title_menu.items seam remains the primary path. Runtime
  -- testing on 0.1.86 showed that a genuinely fresh Blue AND Gold boot could
  -- nevertheless reach the vanilla title list without our SETUP row. Because
  -- this mod already requests engine_internals, install a conservative
  -- belt-and-suspenders adapter around each generation's title-list builder.
  --
  -- The fallback runs AFTER vanilla/public-hook construction and changes
  -- nothing when SETUP is already present. It therefore cannot double-insert.
  ---------------------------------------------------------------------
  -- 2.3.10 / Yellow 0.1.98 boot safety: the public
  -- ui.title_menu.items path is runtime-confirmed working in 2.3.9. Keep the
  -- historical compatibility file in the unchanged package tree, but do not
  -- execute its engine-internal TitleState fallback during startup.
  mod.exports.__beta26.legacyTitleSetupFallbackDeferred = true

  -- Gold's title list dispatches values through MainMenu:choose(). The shared
  -- title hook above can therefore add the row, while this tiny Gen2 adapter
  -- owns only the new value. Every built-in value still delegates unchanged.
  -- Keep the installer scoped in a block so this very large mod does not add
  -- another long-lived top-level local.
  do
      mod.exports.__beta26.installGoldTitleSetupAdapter = function()
          if mod.exports.__beta26.isSaveEditorSession() then return true end
          local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
          if not okVersion or type(GameVersion) ~= "table"
              or type(GameVersion.isGold) ~= "function" then return false end
          local okGold, isGold = pcall(GameVersion.isGold)
          if not okGold or isGold ~= true then return true end

          local okMenu, MainMenu = pcall(require, "src.ui.gen2.MainMenu")
          if not okMenu or type(MainMenu) ~= "table"
              or type(MainMenu.choose) ~= "function" then return false end
          if MainMenu.__nuzlockeTitleSetupOwner == mod
              and MainMenu.choose == MainMenu.__nuzlockeTitleSetupFunction then
              return true
          end
          -- If the previous Nuzlocke loader session is still the live top-level
          -- wrapper, unwrap exactly that function before composing this session.
          -- If another mod wrapped after us, preserve its live chain instead.
          if MainMenu.__nuzlockeTitleSetupOwner ~= nil
              and MainMenu.__nuzlockeTitleSetupOwner ~= mod
              and MainMenu.choose == MainMenu.__nuzlockeTitleSetupFunction
              and type(MainMenu.__nuzlockeTitleSetupPrevious) == "function" then
              MainMenu.choose = MainMenu.__nuzlockeTitleSetupPrevious
          end

          local vanillaChoose = MainMenu.choose
          local chooseWrapper
          chooseWrapper = function(self, value, ...)
              if value == "nuzlocke_setup" then
                  mod.exports.__beta26.selectSetupProfileScope(self.game)
                  pendingNewGameRules = loadSetupProfileFromDisk()
                      or makeDefaultPreGameRules()
                  pendingRulesDirty = false
                  mod.exports.__beta26.pushNuzlockeConfigScreen(self.game,
                      { preGame = true, goldMode = true })
                  return
              elseif value == "new" then
                  pcall(installAutomaticDefaultNameAdapters)
                  mod.exports.__beta26.selectSetupProfileScope(self.game)
                  if not pendingNewGameRules then
                      pendingNewGameRules = loadSetupProfileFromDisk()
                          or makeDefaultPreGameRules()
                  end
                  saveSetupProfileToDisk(pendingNewGameRules)
                  stageNewGameProfile()
              elseif value == "continue" then
                  pendingNewGameRulesForNextSave = false
                  pendingRulesDirty = false
                  newGameRulesSnapshot = nil
                  newGameRulesCommitPending = false
                  newGameCommitPassesRemaining = 0
                  clearPersistedStagedProfile()
              end
              return vanillaChoose(self, value, ...)
          end
          MainMenu.choose = chooseWrapper
          MainMenu.__nuzlockeTitleSetupOwner = mod
          MainMenu.__nuzlockeTitleSetupPrevious = vanillaChoose
          MainMenu.__nuzlockeTitleSetupFunction = chooseWrapper
          return true
      end
      mod.events:on("game.ready", function()
          pcall(mod.exports.__beta26.installGoldTitleSetupAdapter)
      end)
  end


  ---------------------------------------------------------------------
  -- START MENU HOOKS
  --
  -- IMPORTANT: build from the VANILLA result first, then modify that
  -- returned list.  Calling insertBefore() on the incoming `items` and
  -- then calling next() causes the vanilla hook to rebuild the list and
  -- silently discard our inserted entries.  That was why RULES/TRACKER
  -- disappeared in the previous build.
  ---------------------------------------------------------------------
  mod.hooks:wrap("ui.start_menu.items", function(next, game, items)
      local result = next(game, items)
      if type(result) ~= "table" then
          result = items
      end

      -- The hook already supplies the game whose menu is being built.
      -- Do not consult the global/current-game version here: during Gold menu
      -- construction that can lag behind and select the wider R/B/Y labels,
      -- which draw through Gold's narrow native START-menu border.
      local goldMenu = mod.exports.__beta26.runtimeIsGold(game)
      -- Gen 1 localizes this row before the hook; Gold currently exposes a
      -- raw label plus a stable id. Resolve the actual rendered label so both
      -- implementations and translation mods remain valid insertion anchors.
      -- 2.2.9: a full Permadeath wipe can leave an empty party before
      -- vanilla recovery. Runtime testing confirmed entering the native POKEMON
      -- screen in that state can CTD. Preserve the native row but reject its
      -- action until the party contains a Pokemon again.
      for _, item in ipairs(result) do
          if type(item) == "table" then
              local id = tostring(item.id or item.action or item.value or ""):upper()
              local label = tostring(item.label or ""):upper()
              if id == "POKEMON" or label == "POKEMON" then
                  local nativeSelect = item.onSelect
                  if type(nativeSelect) == "function"
                      and item.__nuzlockeEmptyPartyGuard ~= true then
                      item.onSelect = function(...)
                          local party = game and game.save and game.save.party
                          if mod.save:get("nuzlocke_enabled", true) == true
                              and mod.save:get("permadeath", true) == true
                              and type(party) == "table" and #party == 0 then
                              mod.exports.__beta26.pushWorldText(game,
                                  "Your party is empty. Use the PC before opening POKEMON.")
                              return
                          end
                          return nativeSelect(...)
                      end
                      item.__nuzlockeEmptyPartyGuard = true
                  end
              end
          end
      end

      local optionAnchor = "OPTION"
      for _, item in ipairs(result) do
          if type(item) == "table" and (
              tostring(item.id or ""):upper() == "OPTION"
              or tostring(item.action or ""):upper() == "OPTION"
              or tostring(item.value or ""):upper() == "OPTION"
              or tostring(item.label or ""):upper() == "OPTION"
              or item.label == Strings("OPTION")) then
              optionAnchor = item.label or optionAnchor
              break
          end
      end

      -- R/B/Y keeps the established Trainer Card flip/status integration.
      -- Gold's native card already owns multiple pages, so beta.27.5 stops
      -- hijacking that row and exposes a dedicated status screen through the
      -- shared public ui.start_menu.items hook instead.
      -- 2.1.18: never replace the native Trainer Card row. A runtime crash
      -- was reproduced on Yellow while the Nuzlocke wrapper owned that row.
      -- Keep the engine card entirely upstream-owned and expose run status as
      -- a dedicated START-menu item in every supported generation.
      mod.ui.insertBefore(result, optionAnchor, {
          -- Gold's native START box has only seven safe label tiles after its
          -- cursor gutter, so use the same compact label on every game.
          label = goldMenu and Strings("NUZ ST.") or Strings("NUZ STS."),
          desc = { Strings("Nuzlocke"), Strings("run status") },
          onSelect = function()
              if goldMenu then
                  mod.ui.push(game, "NuzlockeGoldStatusScreen")
              else
                  mod.ui.push(game, "NuzlockeTrainerCardScreen", { statusOnly = true })
              end
          end
      })

      if mod.exports.__beta26.Dev.enabled() then
          mod.ui.insertBefore(result, optionAnchor, {
              label = goldMenu and Strings("DEV") or Strings("DEV TOOLS"),
              desc = goldMenu and { Strings("Developer"), Strings("diagnostics") }
                  or nil,
              onSelect = function()
                  mod.ui.push(game, "NuzlockeDevToolsScreen")
              end
          })
      end

      mod.ui.insertBefore(result, optionAnchor, {
          label = goldMenu and Strings("MOD CMP") or Strings("MOD COMPAT"),
          desc = goldMenu and { Strings("Active mod"), Strings("ownership") } or nil,
          onSelect = function()
              mod.ui.push(game, "NuzlockeModCompatScreen")
          end
      })

      mod.ui.insertBefore(result, optionAnchor, {
          label = goldMenu and Strings("ENC TRK") or Strings("ENC TRACKER"),
          desc = goldMenu and { Strings("Encounter"), Strings("tracker") } or nil,
          onSelect = function()
              mod.ui.push(game, "NuzlockeTrackerScreen")
          end
      })

      mod.ui.insertBefore(result, optionAnchor, {
          -- Gold's native menu has a seven-tile safe label field. R/B/Y retain
          -- the clearer full label because their START menu is wider.
          label = goldMenu and Strings("NUZ RUL") or Strings("NUZ RULES"),
          desc = goldMenu and { Strings("Nuzlocke"), Strings("rules") } or nil,
          onSelect = function()
              mod.exports.__beta26.pushNuzlockeConfigScreen(game)
          end
      })

      return result
  end)

  ---------------------------------------------------------------------
  -- R/B/Y NATIVE NUZ INFO
  -- 2.2.0: NUZ ST. and MOD COMPAT became stable after moving off custom
  -- hand-drawn states in 2.1.22. Party NUZ INFO was the remaining R/B/Y
  -- outlier and still opened NuzlockeCatchInfoScreen. Build the same API-27
  -- read-only Pokemon data into Gen1Recomp's host-owned ListMenu instead.
  -- Gold retains the native-styled custom page implementation below.
  ---------------------------------------------------------------------
  mod.exports.__beta26.pushRbyNuzInfoNative = function(game, mon)
      local api = mod.exports.nuzlocke_compat
      local info, infoError
      if api and type(api.getPokemonNuzInfo) == "function" then
          local ok, value = pcall(api.getPokemonNuzInfo, game, mon)
          if ok and type(value) == "table" then
              info = value
          elseif not ok then
              infoError = tostring(value)
          end
      end

      -- Preserve the player's page toggles exactly. A previous safety fallback
      -- silently collapsed an empty/failed page list back to CATCH only, which
      -- made NUZ INFO look incomplete. If the API page helper fails, read the
      -- same three save-backed toggles directly instead.
      local pages
      if api and type(api.getNuzInfoPages) == "function" then
          local ok, value = pcall(api.getNuzInfoPages)
          if ok and type(value) == "table" then pages = value end
      end
      if type(pages) ~= "table" then
          pages = {}
          if mod.save:get("catch_info", true) == true then pages[#pages + 1] = "catch" end
          if mod.save:get("stat_info", true) == true then pages[#pages + 1] = "stat" end
          if mod.save:get("move_info", true) == true then pages[#pages + 1] = "move" end
      end
      local enabled = {}
      for _, page in ipairs(pages) do enabled[tostring(page)] = true end

      -- If the richer API model ever fails, build a complete read-only model
      -- directly from the selected Pokemon instead of degrading to four CATCH
      -- rows. This keeps the crash-safe host ListMenu while retaining Catch,
      -- Stats, and Moves information.
      if not info then
          local directMoves = {}
          for i, move in ipairs(type(mon and mon.moves) == "table" and mon.moves or {}) do
              local id = type(move) == "table" and move.id or move
              local def = game and game.data and game.data.moves
                  and game.data.moves[id] or nil
              directMoves[i] = {
                  id = id,
                  name = def and def.name or tostring(id or "?"),
                  type = def and def.type or nil,
                  power = def and def.power or nil,
                  accuracy = def and def.accuracy or nil,
                  pp = type(move) == "table" and move.pp or nil,
                  maxPp = (type(move) == "table" and move.maxPp)
                      or (def and def.pp) or nil,
              }
          end
          info = {
              catch = {
                  location = mon and mon.catchLocation,
                  encounterType = mon and (mon.encounterType or mon.nuzlockeEncounterType),
                  origin = mon and mon.nuzlockeOrigin,
                  dead = mon and mon.nuzlockeDead == true,
                  cause = mon and (mon.deathCauseText or mon.deathCause),
              },
              stats = {
                  level = mon and mon.level,
                  hp = mon and mon.hp,
                  maxHp = mon and (mon.maxHp or (mon.stats and mon.stats.hp)),
                  values = type(mon and mon.stats) == "table" and mon.stats or {},
                  dvs = type(mon and mon.dvs) == "table" and mon.dvs or {},
                  statExp = type(mon and mon.statExp) == "table" and mon.statExp or {},
              },
              moves = directMoves,
              safeMode = true,
          }
      end

      local items = {}
      local activeNuzInfoPage = nil
      local function text(v, fallback)
          if v == nil or v == "" then return fallback or "--" end
          return tostring(v)
      end
      local function numberText(v)
          v = tonumber(v)
          return v and tostring(math.floor(v)) or "--"
      end
      local function nuzInfoRight(value, glyphBudget)
          if value == nil then return nil end
          local raw = tostring(value)
          local Font = mod.exports.__beta26.getFontModule
              and mod.exports.__beta26.getFontModule() or nil
          if Font and type(Font.split) == "function" then
              local ok, spans = pcall(Font.split, raw)
              if ok and type(spans) == "table" and #spans > (glyphBudget or 9) then
                  local last = spans[glyphBudget or 9]
                  if type(last) == "table" and tonumber(last.to) then
                      return raw:sub(1, tonumber(last.to))
                  end
              end
          end
          return raw
      end

      local function add(label, right)
          items[#items + 1] = {
              label = Strings(tostring(label or "")),
              right = right ~= nil and Strings(nuzInfoRight(right, 9)) or nil,
              nuzInfoPage = activeNuzInfoPage,
          }
      end
      local function section(label, page)
          activeNuzInfoPage = page
      end
      local function pageOff(label)
          local page = tostring(label):lower():match("catch") and "catch"
              or tostring(label):lower():match("stat") and "stat"
              or "move"
          section(label, page)
          add("PAGE", "OFF")
      end

      if enabled.catch then
          section("CATCH INFO", "catch")
          local catch = type(info.catch) == "table" and info.catch or {}
          add("POKEMON", mod.exports.__beta26.safeSpeciesLabel(game, mon and mon.species))
          local location = catch.location or (mon and mon.catchLocation) or "UNKNOWN"
          local okRoute, routeLabel = pcall(routeName, location)
          add("LOC.", okRoute and routeLabel or tostring(location))
          add("ENCOUNTER", text(catch.encounterType, "UNKNOWN"):upper())
          add("ORIGIN", text(catch.origin, "NORMAL"):upper())
          add("STATUS", catch.dead and "LOST" or "ALIVE")
          if catch.shiny ~= nil then add("SHINY", catch.shiny and "YES" or "NO") end
          if catch.cause ~= nil and tostring(catch.cause) ~= "" then
              add("CAUSE", tostring(catch.cause))
          end
          local legal = catch.legality
          if type(legal) == "table" then
              add("LEGALITY", text(legal.status, legal.legal == false and "RESTRICTED" or "LEGAL"))
              if type(legal.reasons) == "table" and #legal.reasons > 0 then
                  add("RULE", table.concat(legal.reasons, "/"))
              end
              if legal.bst ~= nil then add("BST", numberText(legal.bst)) end
              if legal.maximumBST and tonumber(legal.maximumBST) and tonumber(legal.maximumBST) > 0 then
                  add("BST LIMIT", numberText(legal.maximumBST))
              end
          else
              add("LEGALITY", "UNKNOWN")
          end
          local provenance = catch.provenance
          if type(provenance) == "table" then
              if provenance.provider then add("PROVIDER", tostring(provenance.provider)) end
              if provenance.source then add("SOURCE", tostring(provenance.source)) end
              if provenance.identityProvider
                  and provenance.identityProvider ~= provenance.provider then
                  add("IDENTITY", tostring(provenance.identityProvider))
              end
              if provenance.externalIdentity ~= nil then
                  add("EXTERNAL", provenance.externalIdentity and "YES" or "NO")
              end
          end
          if info.safeMode or infoError then add("DETAIL", "SAFE MODE") end
      else
          pageOff("CATCH INFO")
      end

      if enabled.stat then
          section("STAT INFO", "stat")
          local stats = type(info.stats) == "table" and info.stats or {}
          add("LEVEL", numberText(stats.level))
          add("HP", ("%s/%s"):format(numberText(stats.hp), numberText(stats.maxHp)))
          local values = type(stats.values) == "table" and stats.values or {}
          local dvs = type(stats.dvs) == "table" and stats.dvs or {}
          local exp = type(stats.statExp) == "table" and stats.statExp or {}
          local function statRow(label, value, dv, statExp)
              add(label, ("%s D%s E%s"):format(
                  numberText(value), numberText(dv), numberText(statExp)))
          end
          statRow("ATK", values.attack, dvs.attack, exp.attack)
          statRow("DEF", values.defense, dvs.defense, exp.defense)
          statRow("SPE", values.speed, dvs.speed, exp.speed)
          statRow("SPC", values.special or values.spAttack,
              dvs.special or dvs.spAttack, exp.special or exp.spAttack)
      else
          pageOff("STAT INFO")
      end

      if enabled.move then
          section("MOVE INFO", "move")
          local moves = type(info.moves) == "table" and info.moves or {}
          for slot = 1, 4 do
              local move = moves[slot]
              if move then
                  local name = text(move.name or move.id, "?")
                  local typeName = text(move.type, "?"):upper():gsub("_TYPE$", "")
                  items[#items + 1] = {
                      label = Strings(tostring(slot) .. " " .. name),
                      right = Strings(typeName),
                      nuzInfoPage = "move",
                      nuzInfoMove = {
                          slot = slot,
                          name = name,
                          type = typeName,
                          power = numberText(move.power),
                          accuracy = numberText(move.accuracy),
                          pp = numberText(move.pp),
                          maxPp = numberText(move.maxPp),
                      },
                  }
              else
                  items[#items + 1] = {
                      label = Strings(tostring(slot) .. " --"),
                      right = "",
                      nuzInfoPage = "move",
                      nuzInfoMove = {
                          slot = slot,
                          name = "--",
                          type = "--",
                          power = "--",
                          accuracy = "--",
                          pp = "--",
                          maxPp = "--",
                      },
                  }
              end
          end
      else
          pageOff("MOVE INFO")
      end

      if #items == 0 then
          add("NO PAGES", "ENABLE IN RULES")
      end

      local pageOrder = {}
      if enabled.catch then pageOrder[#pageOrder + 1] = "catch" end
      if enabled.stat then pageOrder[#pageOrder + 1] = "stat" end
      if enabled.move then pageOrder[#pageOrder + 1] = "move" end
      if #pageOrder == 0 then pageOrder[1] = "catch" end

      local pageTitles = {
          catch = Strings("CATCH INFO"),
          stat = Strings("STAT INFO"),
          move = Strings("MOVE INFO"),
      }
      local pageBuckets = { catch = {}, stat = {}, move = {} }
      for _, item in ipairs(items) do
          local key = item.nuzInfoPage
          if key and pageBuckets[key] then
              pageBuckets[key][#pageBuckets[key] + 1] = item
          end
      end

      local okMenu, menu = pcall(mod.ui.ListMenu.new, game, Strings("NUZ INFO"),
          pageBuckets[pageOrder[1]] or {}, {
              keyRepeat = true,
              wrap = false,
              rows = 6,
              kind = "nuzlocke_nuz_info",
          })
      if not okMenu or type(menu) ~= "table" then
          local TextBox = require("src.render.TextBox")
          local box = TextBox.new(game, Strings("NUZ INFO could not open.\nYour Pokemon is safe."))
          game.stack:push(box)
          return box
      end

      menu.nuzInfoPageOrder = pageOrder
      menu.nuzInfoPageIndex = 1
      menu.nuzInfoPageBuckets = pageBuckets
      menu.rows = pageOrder[1] == "move" and 2 or 6
      menu.marqueeTime = 0

      local function setNuzInfoPage(self, index)
          local count = #self.nuzInfoPageOrder
          if count <= 0 then return end
          self.nuzInfoPageIndex = ((index - 1) % count) + 1
          local key = self.nuzInfoPageOrder[self.nuzInfoPageIndex]
          self.items = self.nuzInfoPageBuckets[key] or {}
          self.rows = key == "move" and 2 or 6
          self.index = 1
          self.scroll = 0
          self.marqueeTime = 0
      end

      local baseUpdate = menu.update
      menu.update = function(self, dt)
          self.marqueeTime = (self.marqueeTime or 0) + (dt or 0)
          local count = #self.nuzInfoPageOrder
          if count > 1 and (self.game.input:wasPressed("right")
              or self.game.input:wasPressed("a")) then
              setNuzInfoPage(self, self.nuzInfoPageIndex + 1)
              return
          elseif count > 1 and self.game.input:wasPressed("left") then
              setNuzInfoPage(self, self.nuzInfoPageIndex - 1)
              return
          end
          return baseUpdate(self, dt)
      end

      menu.draw = function(self)
          local Font = require("src.render.Font")
          local Theme = require("src.ui.Theme")
          Font.drawBox(0, 0, 20, 18)

          -- Slight tracking between glyphs without inserting literal spaces.
          -- This keeps translated strings semantically intact while making
          -- the two title lines breathe a little more on the native surface.
          local function trackedWidth(label, tracking)
              local spans = type(Font.split) == "function" and Font.split(label) or nil
              if type(spans) ~= "table" or #spans == 0 then
                  return (type(Font.width) == "function" and Font.width(label)
                      or #tostring(label) * 8)
              end
              local width = 0
              for i, span in ipairs(spans) do
                  local glyph = label:sub(span.from, span.to)
                  width = width + (type(Font.width) == "function"
                      and Font.width(glyph) or 8)
                  if i < #spans then width = width + tracking end
              end
              return width
          end

          local function centeredTrackedBold(value, y, tracking)
              local label = Strings(value)
              tracking = tracking or 1
              local spans = type(Font.split) == "function" and Font.split(label) or nil
              if type(spans) ~= "table" or #spans == 0 then
                  local width = trackedWidth(label, tracking)
                  local x = math.max(8, math.floor((160 - width) / 2))
                  Font.draw(label, x, y)
                  Font.draw(label, x + 1, y)
                  return
              end
              local x = math.max(8,
                  math.floor((160 - trackedWidth(label, tracking)) / 2))
              for i, span in ipairs(spans) do
                  local glyph = label:sub(span.from, span.to)
                  Font.draw(glyph, x, y)
                  Font.draw(glyph, x + 1, y)
                  x = x + (type(Font.width) == "function"
                      and Font.width(glyph) or 8)
                  if i < #spans then x = x + tracking end
              end
          end

          centeredTrackedBold("NUZ INFO", 6, 1)
          local pageKey = self.nuzInfoPageOrder[self.nuzInfoPageIndex] or "catch"
          centeredTrackedBold(pageTitles[pageKey] or "CATCH INFO", 22, 1)

          if pageKey == "move" then
              -- Two compact move cards fit cleanly on the native 160x144
              -- surface. Long move names get the full row and marquee;
              -- type/power and accuracy/PP are moved onto their own lines.
              for row = 1, self.rows do
                  local i = (self.scroll or 0) + row
                  local item = self.items[i]
                  if not item then break end
                  local move = item.nuzInfoMove or {}
                  local baseY = 38 + (row - 1) * 42
                  local name = tostring(move.name or "--")
                  local title = tostring(move.slot or i) .. " "
                      .. marqueeText(name, 14, self.marqueeTime, 2.8)
                  Font.draw(title, 12, baseY)

                  -- 2.3.35: keep each move card single-column. The previous
                  -- TYPE/PWR and ACC/PP split columns still collided on the
                  -- native 160px surface with long type names and 3-digit
                  -- values. Give TYPE its own full row, then compress numeric
                  -- combat data into stable short labels on the third row.
                  local typeLine = Strings("TYPE %s",
                      tostring(move.type or "--"))
                  Font.draw(marqueeText(typeLine, 17,
                      self.marqueeTime, 2.8), 20, baseY + 13)

                  local statsLine = Strings("P%s  A%s  PP%s/%s",
                      tostring(move.power or "--"),
                      tostring(move.accuracy or "--"),
                      tostring(move.pp or "--"),
                      tostring(move.maxPp or "--"))
                  Font.draw(marqueeText(statsLine, 17,
                      self.marqueeTime, 2.8), 20, baseY + 26)
              end
          else
              -- Catch/Stat rows use normal weight. Only the two title lines
              -- above are bold.
              for row = 1, self.rows do
                  local i = (self.scroll or 0) + row
                  local item = self.items[i]
                  if not item then break end
                  local y = 34 + (row - 1) * 14
                  local label = tostring(item.label or "")
                  local right = tostring(item.right or "")
                  Font.draw(label, 12, y)
                  if right ~= "" then
                      Font.draw(marqueeText(right, 8, self.marqueeTime, 2.8),
                          88, y)
                  end
              end
          end

          if (self.scroll or 0) > 0 then
              Font.draw(Strings("^"), 148, 32)
          end
          if (self.scroll or 0) + self.rows < #self.items then
              Font.drawCode(Theme.moreArrow or 0xEE, 148, 108)
          end

          if #self.nuzInfoPageOrder > 1 then
              Font.draw(Strings("A/<>:PG"), 8, 132)
              Font.draw(Strings("%d/%d", self.nuzInfoPageIndex,
                  #self.nuzInfoPageOrder), 76, 132)
          end
          Font.draw(Strings("B:BACK"), 104, 132)
      end

      menu.nuzlockeModernUiModel = function(self)
          local key = self.nuzInfoPageOrder[self.nuzInfoPageIndex] or "catch"
          local rows = {}
          for _, item in ipairs(self.items or {}) do
              rows[#rows + 1] = {
                  label = tostring(item.label or ""),
                  right = tostring(item.right or ""),
              }
          end
          return {
              title = Strings("NUZ INFO"),
              subtitle = pageTitles[key],
              rows = rows,
              index = self.index or 1,
              scroll = self.scroll or 0,
              details = { Strings("PAGE %d/%d",
                  self.nuzInfoPageIndex, #self.nuzInfoPageOrder) },
              footer = #self.nuzInfoPageOrder > 1
                  and { Strings("A/LEFT/RIGHT: PAGE"), Strings("B: BACK") }
                  or { Strings("B: BACK") },
          }
      end

      game.stack:push(menu)
      return menu
  end

  ---------------------------------------------------------------------
  -- PARTY SUBMENU HOOK
  ---------------------------------------------------------------------
  mod.hooks:wrap("ui.party.submenu", function(next, game, items, mon, ctx)
      -- Compose from the predecessor result first. Other mods may filter,
      -- replace, or rebuild the party submenu.
      local result = next(game, items, mon, ctx)
      if type(result) ~= "table" then result = items end
      if type(result) ~= "table" then return result end

      local anyNuzInfo = mod.save:get("catch_info", true) == true
          or mod.save:get("stat_info", true) == true
          or mod.save:get("move_info", true) == true
      if anyNuzInfo and mon then
          for _, item in ipairs(result) do
              if type(item) == "table" and (item.nuzlockeCatchInfo == true
                  or item.nuzlockeNuzInfo == true
                  or item.id == "nuzlocke_catch_info"
                  or item.id == "nuzlocke_nuz_info") then
                  -- Upgrade a preserved older row instead of inserting a
                  -- duplicate when another compatibility layer re-enters.
                  item.id = "nuzlocke_nuz_info"
                  item.nuzlockeNuzInfo = true
                  item.label = Strings("NUZ INFO")
                  item.onSelect = function()
                      if mod.exports.__beta26.runtimeIsGold(game) then
                          mod.ui.push(game, "NuzlockeCatchInfoScreen", { mon = mon })
                      else
                          mod.exports.__beta26.pushRbyNuzInfoNative(game, mon)
                      end
                  end
                  return result
              end
          end

          local cancelAnchor = "CANCEL"
          for _, item in ipairs(result) do
              if type(item) == "table" and (item.label == "CANCEL"
                  or item.label == Strings("CANCEL")
                  or item.id == "CANCEL" or item.id == "cancel"
                  or item.action == "cancel" or item.cancel == true) then
                  cancelAnchor = item.label or cancelAnchor
                  break
              end
          end
          mod.ui.insertBefore(result, cancelAnchor, {
              id = "nuzlocke_nuz_info",
              nuzlockeNuzInfo = true,
              label = Strings("NUZ INFO"),
              onSelect = function()
                  if mod.exports.__beta26.runtimeIsGold(game) then
                      mod.ui.push(game, "NuzlockeCatchInfoScreen", { mon = mon })
                  else
                      mod.exports.__beta26.pushRbyNuzInfoNative(game, mon)
                  end
              end
          })
      end

      return result
  end)

  ---------------------------------------------------------------------
  -- BATTLE CATCH ENFORCEMENT
  --
  -- The recomp's BagMenu calls BattleState:throwBall after consuming the
  -- selected ball. Bryan's original Nuzlocke implementation intercepts
  -- this exact method, refunds the ball, displays the rejection message,
  -- and returns before vanilla capture processing.
  --
  -- We use that same engine seam for the actual first-catch / No Dupes
  -- decision. The important difference from Bryan's strict mode is that
  -- duplicate encounters NEVER consume the area's encounter in this mod.
  -- Shinies always bypass No Dupes, and bypass 1st Catch when Shiny Clause
  -- is enabled.
  ---------------------------------------------------------------------
  mod.events:on("game.ready", function(game)
      local ok, BattleState = pcall(require, "src.battle.BattleState")
      local okBag, Bag = pcall(require, "src.inventory.Bag")
      if not ok or type(BattleState) ~= "table"
          or type(BattleState.throwBall) ~= "function"
          or not okBag or type(Bag) ~= "table"
          or type(Bag.add) ~= "function" then
          return
      end

      -- 2.5.14: these direct engine wrappers must survive a second ModLoader
      -- session in the same Lua process.  A bare boolean marker can outlive the
      -- mod instance and leave a wrapper closing over an obsolete mod.save.
      local function ownedMethodSession(key, method)
          local session = BattleState[key]
          if type(session) == "table" and session.owner ~= mod
              and BattleState[method] == session.wrapper
              and type(session.previous) == "function" then
              BattleState[method] = session.previous
              session = nil
          end
          local healthy = type(session) == "table" and session.owner == mod
              and BattleState[method] == session.wrapper
          return healthy, session
      end
      BattleState.__nuzlockeFinal23Patched = true -- historical marker only

      -- Current Gen1Recomp emits the public battle.ended event from finish().
      -- Older builds were less consistent, so keep a private fallback for our
      -- own bookkeeping only. Never synthesize a second public engine event:
      -- unrelated mods may treat battle.ended as a transactional boundary.
      if type(BattleState.finish) == "function" then
          local healthy = ownedMethodSession(
              "__nuzlockeCatchFinishSession", "finish")
          if not healthy then
              local vanillaCatchFinish = BattleState.finish
              local finishWrapper
              finishWrapper = function(self, ...)
                  local result = vanillaCatchFinish(self, ...)
                  if type(finalizeNuzlockeBattle) == "function" then
                      pcall(finalizeNuzlockeBattle, self, self and self.result)
                  end
                  return result
              end
              BattleState.finish = finishWrapper
              BattleState.__nuzlockeCatchFinishSession = {
                  owner = mod, previous = vanillaCatchFinish,
                  wrapper = finishWrapper,
              }
          end
          BattleState.__nuzlockeCatchFinishPatched = true -- historical marker
      end

      -- The public battle.nickname hook is not present in every recomp build.
      -- Patch the engine's actual nickname-screen seam as well, so enabling
      -- Nicknames cannot silently fall through to the normal auto-skip path.
      do
          local healthy = ownedMethodSession(
              "__nuzlockeNicknameScreenSession", "askNicknameUI")
          local vanillaAskNicknameUI = BattleState.askNicknameUI
          local okStrings, Strings = pcall(require, "src.core.Strings")

          if not healthy and type(vanillaAskNicknameUI) == "function" then
              local nicknameWrapper
              nicknameWrapper = function(self, mon, displayName)
                  if active(self and self.game, self)
                      and mod.save:get("nickname_rule", defaultRuleValue("nickname_rule"))
                      and okStrings and Strings then
                      self.lockedBall, self.blankForAskName = nil, false

                      local namingOpts
                      namingOpts = {
                          title = Strings("NICKNAME?"),
                          maxLen = 10,
                          onDone = function(name)
                              name = tostring(name or "")
                              if name ~= "" then
                                  mon.nickname = name
                                  mon.nuzlockeNeedsNickname = nil
                                  mon.nuzlockeNicknameRequired = nil
                                  return
                              end

                              -- NamingScreen intentionally permits an empty
                              -- confirm for vanilla's "decline nickname" flow.
                              -- Under Nickname Rule, immediately reopen it.
                              local okScreens, Screens =
                                  pcall(require, "src.ui.Screens")
                              if okScreens and Screens
                                  and type(Screens.push) == "function" then
                                  pcall(Screens.push, self.game,
                                      "NamingScreen", namingOpts)
                              end
                          end,
                      }
                      return self:buildScreen("NamingScreen", namingOpts)
                  end
                  return vanillaAskNicknameUI(self, mon, displayName)
              end
              BattleState.askNicknameUI = nicknameWrapper
              BattleState.__nuzlockeNicknameScreenSession = {
                  owner = mod, previous = vanillaAskNicknameUI,
                  wrapper = nicknameWrapper,
              }
          end
          BattleState.__nuzlockeNicknameScreenPatched = true -- historical marker
      end

      -- BattleState's message queue does not soft-wrap mod-authored text on
      -- every supported recomp build. Keep Nuzlocke battle messages inside the
      -- native 18-column window and use CONT markers after the first two lines
      -- so longer messages wait for A/B instead of scrolling past automatically.
      mod.exports.__beta26.formatBattleText = function(text)
          local lines = wrapText(mod.exports.__beta26.cleanWorldText(text), 18)
          if #lines == 0 then return "" end
          if #lines == 1 then return lines[1] end
          local out = lines[1] .. "\n" .. lines[2]
          for i = 3, #lines do
              out = out .. "\v" .. lines[i]
          end
          return out
      end

      local throwHealthy = ownedMethodSession(
          "__nuzlockeCatchGateSession", "throwBall")
      if not throwHealthy then
          local vanillaThrowBall = BattleState.throwBall
          local throwWrapper
          throwWrapper = function(self, ball)
          local gameRef = self and self.game

          -- BagMenu has already consumed the selected Ball at this seam. Check
          -- the use-only Ball rule before Soft Start can arm, and refund on denial.
          local useAllowed, useDecision = true, nil
          if type(evaluateItemUsePolicy) == "function" then
              local okUse, allowed, decision = pcall(evaluateItemUsePolicy,
                  gameRef, gameRef and gameRef.data, gameRef and gameRef.save,
                  ball, nil, { battle = self, inBattle = true, isBall = true })
              if okUse and allowed == false then
                  useAllowed, useDecision = false, decision
              end
          end
          if not useAllowed then
              pcall(function()
                  Bag.add(gameRef.save, ball, 1, gameRef.data)
              end)
              local message = useDecision and useDecision.message
                  or Strings("No Catching is ON!")
              local tier = worldTier(gameRef)
              if tier >= 3 and useDecision and useDecision.tier3 then
                  message = useDecision.tier3
              elseif tier >= 2 and useDecision and useDecision.tier2 then
                  message = useDecision.tier2
              end
              if type(self.say) == "function" then
                  self:say(mod.exports.__beta26.formatBattleText(message))
              elseif type(self.sayNext) == "function" then
                  self:sayNext(mod.exports.__beta26.formatBattleText(message))
              end
              return
          end

          -- Possessing/using the first usable Ball permanently arms encounter
          -- bookkeeping for this run. The flag never disarms at zero Balls.
          if gameRef and mod.exports.__beta26.armEncounterRulesNow then
              mod.exports.__beta26.armEncounterRulesNow(gameRef)
          end
          local species = self and self.enemy and self.enemy.mon
              and self.enemy.mon.species

          local reason
          local reasonOk, reasonValue = pcall(function()
              return catchDeniedReason(gameRef, self, species)
          end)
          if reasonOk then
              reason = reasonValue
          end

          if reason then
              -- BagMenu has already removed the ball. Use Bryan's exact
              -- refund mechanism and original messages.
              pcall(function()
                  Bag.add(gameRef.save, ball, 1, gameRef.data)
              end)

              local message = mod.exports.__beta26.catchRejectionMessage(gameRef, reason, species)

              -- Use the same message entry point as Bryan's implementation.
              -- If a stripped/older build does not expose say(), fall back
              -- to the queue-based API rather than touching phase/queue state.
              if message then
                  if type(self.say) == "function" then
                      self:say(mod.exports.__beta26.formatBattleText(message))
                  elseif type(self.sayNext) == "function" then
                      self:sayNext(mod.exports.__beta26.formatBattleText(message))
                  end
              end

              return
          end

          local ballAllowed, ballLimit =
              mod.exports.__beta26.encounterBallThrowAvailable(gameRef, self)
          if not ballAllowed then
              -- R/B/Y BagMenu consumed the selected Ball before throwBall.
              -- An exhausted budget is a refusal, not an attempted throw.
              pcall(function()
                  Bag.add(gameRef.save, ball, 1, gameRef.data)
              end)
              local message =
                  mod.exports.__beta26.encounterBallLimitMessage(ballLimit)
              if type(self.say) == "function" then
                  self:say(mod.exports.__beta26.formatBattleText(message))
              elseif type(self.sayNext) == "function" then
                  self:sayNext(mod.exports.__beta26.formatBattleText(message))
              end
              return
          end
          mod.exports.__beta26.consumeEncounterBallThrow(gameRef, self)

          return vanillaThrowBall(self, ball)
          end
          BattleState.throwBall = throwWrapper
          BattleState.__nuzlockeCatchGateSession = {
              owner = mod, previous = vanillaThrowBall, wrapper = throwWrapper,
          }
      end
  end)

  ---------------------------------------------------------------------
  -- NICKNAME ENFORCEMENT
  --
  -- hooks:wrap("battle.nickname") fires after a successful catch,
  -- before the nickname prompt. Returning true forces the prompt to
  -- appear even when the player has auto-skip turned on. Returning
  -- false skips it. We always return true when the Nicknames rule is
  -- enabled so the player cannot avoid naming their catch.
  ---------------------------------------------------------------------
  mod.hooks:wrap("battle.nickname", function(next, battle, mon)
      if active(battle and battle.game, battle)
          and not mod.exports.__beta26.runtimeIsGold(battle and battle.game)
          and mod.save:get("nickname_rule", defaultRuleValue("nickname_rule")) then
          -- Force the naming screen open regardless of options.
          return true
      end
      return next(battle, mon)
  end)

  -- Fallback for engine builds where battle.nickname is only a notification
  -- hook. If a caught Pokemon reaches the tracker without a custom nickname,
  -- mark it for the engine's nickname flow rather than silently accepting the
  -- species name. This does not invent a nickname; the player must supply it.
  mod.events:on("pokemon.caught", function(ev)
      if not (ev and ev.mon and ev.game) then return end
      if not active(ev.game, ev.battle) then return end
      if mod.exports.__beta26.runtimeIsGold(ev.game) then return end
      if not mod.save:get("nickname_rule", defaultRuleValue("nickname_rule")) then return end
      local mon = ev.mon
      if mon.nickname == nil or mon.nickname == "" or mon.nickname == mon.species then
          mon.nuzlockeNeedsNickname = true
          mon.nuzlockeNicknameRequired = true
          -- The mandatory NamingScreen is the feedback for this rule. Do not
          -- stack another World Building box on the catch message or naming
          -- flow from this post-catch compatibility listener.
      end
  end)

  ---------------------------------------------------------------------
  -- ITEM USE ENFORCEMENT / SHARED POLICY
  --
  -- One pure legality decision feeds our engine gate and cooperative mods that
  -- want to ask BEFORE mutating inventory. Presentation stays outside policy.
  ---------------------------------------------------------------------
  local ItemPolicy = {
      fieldHealing = {
          POTION = true, SUPER_POTION = true, HYPER_POTION = true,
          MAX_POTION = true, FULL_RESTORE = true,
          REVIVE = true, MAX_REVIVE = true,
          ANTIDOTE = true, BURN_HEAL = true, ICE_HEAL = true,
          AWAKENING = true, PARLYZ_HEAL = true, PARALYZE_HEAL = true,
          FULL_HEAL = true,
          FRESH_WATER = true, SODA_POP = true, LEMONADE = true,
          MOOMOO_MILK = true,
          BERRY_JUICE = true, RAGECANDYBAR = true,
          -- Gold's medicine, herb, whole-party Sacred Ash, and held-Berry healing families.
          SACRED_ASH = true,
          ENERGYPOWDER = true, ENERGY_ROOT = true, HEAL_POWDER = true,
          REVIVAL_HERB = true,
          BERRY = true, GOLD_BERRY = true,
          BITTER_BERRY = true, MINT_BERRY = true,
          PRZCUREBERRY = true, PSNCUREBERRY = true,
          ICE_BERRY = true, BURNT_BERRY = true, MIRACLEBERRY = true,
      },
      ppRecovery = {
          ETHER = true, MAX_ETHER = true,
          ELIXER = true, MAX_ELIXER = true,
          -- Gen 1 uses PP_UP. PP_MAX is accepted for merged/later data.
          PP_UP = true, PP_MAX = true,
          -- Compatibility spellings retained for merged item datasets.
          ELIXIR = true, MAX_ELIXIR = true,
          -- Gold restores PP with MysteryBerry through the same party-target
          -- item path as Ether-family items.
          MYSTERYBERRY = true, MYSTERY_BERRY = true,
      },
      xBattle = {
          X_ATTACK = true, X_DEFEND = true, X_SPEED = true,
          X_SPECIAL = true, X_ACCURACY = true,
          DIRE_HIT = true, GUARD_SPEC = true,
      },
      repels = { REPEL = true, SUPER_REPEL = true, MAX_REPEL = true },
      fishingRods = { OLD_ROD = true, GOOD_ROD = true, SUPER_ROD = true },
      vanillaBalls = {
          POKE_BALL = true, GREAT_BALL = true, ULTRA_BALL = true,
          MASTER_BALL = true, SAFARI_BALL = true,
      },
  }

  function ItemPolicy.normalize(item)
      local value = type(item) == "table"
          and (item.id or item.key or item.value or item.name)
          or item
      value = tostring(value or ""):upper()
      return value:gsub("[%s%-]+", "_")
  end

  -- A few UI/data paths may hand the item policy a display-facing name rather
  -- than the canonical data key.  For the two runtime-failing rule families,
  -- accept either representation without changing the already-confirmed PP or
  -- healing-item classification paths.
  function ItemPolicy.matchesSet(data, itemId, set)
      local id = ItemPolicy.normalize(itemId)
      if set[id] then return true end
      local record = ItemPolicy.record(data, itemId)
      if type(record) == "table" then
          local byName = ItemPolicy.normalize(record.name)
          if set[byName] then return true end
      end
      return false
  end

  function ItemPolicy.record(data, itemId)
      if type(itemId) == "table"
          and (itemId.ball ~= nil or itemId.machine ~= nil or itemId.effect ~= nil) then
          return itemId
      end
      local items = data and data.items
      if type(items) ~= "table" then return nil end
      local id = ItemPolicy.normalize(itemId)
      return items[id] or items[itemId]
  end

  function ItemPolicy.isBall(data, itemId, itemEffects)
      local id = ItemPolicy.normalize(itemId)
      if ItemPolicy.vanillaBalls[id] then return true end
      local record = ItemPolicy.record(data, itemId)
      if type(record) == "table" then
          if record.ball ~= nil and record.ball ~= false then return true end
          if ItemPolicy.normalize(record.pocket) == "BALL" then return true end
      end

      -- API-2 content mods can register custom capture devices in a dedicated
      -- merged balls registry while the item record itself stays intentionally
      -- minimal. Prefer that live registry when present so No Catching and
      -- other ball-aware policy never fall back to a hard-coded vanilla list.
      local mergedBalls = data and (data.balls or data.ballRegistry
          or data.ball_registry)
      if type(mergedBalls) == "table" then
          local entry = mergedBalls[id] or mergedBalls[itemId]
          if entry ~= nil and entry ~= false then return true end
      end

      local balls = itemEffects and itemEffects.BALLS
      return type(balls) == "table" and balls[id] ~= nil and balls[id] ~= false
  end

  function ItemPolicy.isFishingRod(data, itemId)
      local id = ItemPolicy.normalize(itemId)
      if ItemPolicy.fishingRods[id] then return true end
      local record = ItemPolicy.record(data, itemId)
      if type(record) ~= "table" then return false end
      local name = ItemPolicy.normalize(record.name)
      if ItemPolicy.fishingRods[name] then return true end
      local effect = ItemPolicy.normalize(record.effect)
      local kind = ItemPolicy.normalize(record.kind or record.type or record.category)
      return effect:find("FISH", 1, true) ~= nil or effect:find("ROD", 1, true) ~= nil
          or kind == "FISHING_ROD" or kind == "ROD"
  end

  function ItemPolicy.ballUseBlocked(data, itemId, itemEffects, forceIsBall)
      if mod.save:get("no_catching", false) ~= true then return false end
      if forceIsBall == true then return true end
      return ItemPolicy.isBall(data, itemId, itemEffects)
  end

  function ItemPolicy.isTM(data, itemId)
      local record = ItemPolicy.record(data, itemId)
      if type(record) == "table" and record.machine ~= nil then
          local machine = record.machine
          local kind
          if type(machine) == "table" then
              kind = ItemPolicy.normalize(machine.kind or machine.type)
          else
              kind = ItemPolicy.normalize(machine)
          end
          if kind == "HM" then return false end
          if kind == "TM" then return true end
      end
      local id = ItemPolicy.normalize(itemId)
      if id:match("^HM_?%d+") then return false end
      if id:match("^TM_?%d+") then return true end
      if type(record) == "table" then
          local name = ItemPolicy.normalize(record.name)
          if name:match("^HM_?%d+") then return false end
          if name:match("^TM_?%d+") then return true end
      end
      return false
  end

  function ItemPolicy.denied(code, key, plain, tier2, tier3, extra)
      local decision = {
          code = code, key = key, message = plain,
          tier2 = tier2 or plain, tier3 = tier3 or tier2 or plain,
      }
      if type(extra) == "table" then
          for k, v in pairs(extra) do decision[k] = v end
      end
      return false, decision
  end

  function ItemPolicy.deniedRule(game, code, key, fallback1, fallback2, fallback3, extra)
      local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
          game, key, fallback1, fallback2, fallback3)
      return ItemPolicy.denied(code, key, t1, t2, t3, extra)
  end


  -- Item-aware presentation for the three rules most often tested repeatedly
  -- from the Pack/Bag. Legality stays exactly the same; only the rejection
  -- copy changes. This gives Potion/Revive/status medicine, individual TMs,
  -- and Rare Candy more useful feedback than one repeated generic sentence.
  function ItemPolicy.deniedItemRule(game, data, code, key, itemId, target)
      local id = ItemPolicy.normalize(itemId)
      local def = ItemPolicy.record(data, itemId) or {}
      local itemName = tostring(def.name or id:gsub("_", " "))

      if key == "no_rare_candy_use" then
          local label = target and (target.nickname
              or mod.exports.__beta26.safeSpeciesLabel(game, target.species))
          local t1 = "Rare Candy use is banned."
          local t2 = label and (tostring(label)
              .. " does not get a candy level on this ruleset.")
              or "The Rare Candy stays wrapped; this run does not allow candy levels."
          local t3 = mod.exports.__beta26.runtimeIsGold(game)
              and "The badge case has no candy shortcut written into it. Keep the Rare Candy for collection or sale."
              or "The Gym Guide taps the rule card: no candy levels on this challenge. Keep it for collection or sale."
          return ItemPolicy.denied(code, key, Strings(t1), Strings(t2),
              Strings(t3), { item = id })
      end

      if key == "no_tm_use" then
          local teaches = def.teaches
          if not teaches and type(def.machine) == "table" then
              teaches = def.machine.move or def.machine.id
          end
          local moveDef = teaches and data and data.moves
              and data.moves[teaches] or nil
          local moveName = moveDef and moveDef.name
          local t1 = itemName .. " cannot be used to teach a move."
          local t2 = moveName
              and (itemName .. " stays sealed. " .. tostring(moveName)
                  .. " must be learned another way.")
              or (itemName .. " stays sealed. TMs are collection-only on this ruleset.")
          local t3 = mod.exports.__beta26.runtimeIsGold(game)
              and (moveName
                  and ("The TM pocket can keep " .. itemName .. ", but Johto's rule card will not teach "
                      .. tostring(moveName) .. " from it. HMs still work.")
                  or ("The TM pocket can keep " .. itemName
                      .. ", but Johto's challenge does not allow TM teaching. HMs still work."))
              or (moveName
                  and ("The TM case can keep " .. itemName .. ", but Kanto's rule card will not teach "
                      .. tostring(moveName) .. " from it. HMs still work.")
                  or ("The TM case can keep " .. itemName
                      .. ", but Kanto's challenge does not allow TM teaching. HMs still work."))
          return ItemPolicy.denied(code, key, Strings(t1), Strings(t2),
              Strings(t3), { item = id, move = teaches })
      end

      if key == "no_field_healing" then
          local revive = id == "REVIVE" or id == "MAX_REVIVE"
          local status = id == "ANTIDOTE" or id == "BURN_HEAL"
              or id == "ICE_HEAL" or id == "AWAKENING"
              or id == "PARLYZ_HEAL" or id == "PARALYZE_HEAL"
              or id == "FULL_HEAL"
          local t1 = itemName .. " cannot be used in the field."
          local t2
          if revive then
              t2 = itemName .. " stays in the bag. A field Revive would erase the consequence this rule is preserving."
          elseif status then
              t2 = itemName .. " has to wait. Field status medicine is disabled until your rules allow healing."
          else
              t2 = itemName .. " stays corked. Roadside HP recovery is disabled on this run."
          end
          local t3
          if mod.exports.__beta26.runtimeIsGold(game) then
              t3 = revive
                  and ("Johto's trail ledger does not accept " .. itemName
                      .. " as a roadside reset. Carry the damage forward.")
                  or status
                      and ("The Johto route ahead keeps its teeth. " .. itemName
                          .. " waits until a legal healing seam.")
                      or ("No trail-side potion stop in Johto. " .. itemName
                          .. " stays packed and the team carries its bruises onward.")
          else
              t3 = revive
                  and ("Kanto's route ledger does not accept " .. itemName
                      .. " as a roadside reset. Carry the consequence forward.")
                  or status
                      and ("The Kanto road keeps its teeth. " .. itemName
                          .. " waits until a legal healing seam.")
                      or ("No roadside potion stop in Kanto. " .. itemName
                          .. " stays packed and the team carries its bruises onward.")
          end
          return ItemPolicy.denied(code, key, Strings(t1), Strings(t2),
              Strings(t3), { item = id })
      end

      return ItemPolicy.deniedRule(game, code, key,
          tostring(itemName) .. " is blocked by your Nuzlocke rules.")
  end

  evaluateItemUsePolicy = function(game, data, save, itemId, target, context)
      context = type(context) == "table" and context or {}
      local battle = context.battle
      local inBattle = context.inBattle
      if inBattle == nil then inBattle = battle ~= nil end

      -- v0.1.79 can reach ItemEffects.use with a valid save/data pair while a
      -- convenient Game reference is absent. Legality is save-owned; presentation
      -- is the only part that needs a Game/stack. Resolve every known context but
      -- never silently allow a restricted item merely because `game` is nil.
      game = game or (battle and battle.game)
          or (context.overworld and context.overworld.game)
          or currentGame or mod.game
      save = save or (game and game.save) or currentSave
      data = data or (game and game.data)
          or (currentGame and currentGame.data)

      if mod.save:get("nuzlocke_enabled", true) == false or not save then
          return true
      end
      if battle and (battle.demo or battle.ghost) then return true end

      local id = ItemPolicy.normalize(itemId)
      if id == "" then return true end

      -- These rules prohibit USE only. Inventory acquisition, PC storage,
      -- tossing, buying, and selling remain owned by their normal/other rule paths.
      if mod.save:get("no_rare_candy_use", false) == true and id == "RARE_CANDY" then
          return ItemPolicy.deniedItemRule(game, data,
              "no_rare_candy_use", "no_rare_candy_use", itemId, target)
      end

      if mod.save:get("no_player_stat_exp_gain", false) == true then
          if mod.exports.__beta26.nativeStatVitaminSet[id] then
              return ItemPolicy.deniedRule(game,
                  "no_player_stat_exp_gain", "no_player_stat_exp_gain",
                  "Stat EXP gain is banned.")
          end
      end

      if mod.save:get("no_tm_use", false) == true and ItemPolicy.isTM(data, itemId) then
          return ItemPolicy.deniedItemRule(game, data,
              "no_tm_use", "no_tm_use", itemId, target)
      end

      if ItemPolicy.ballUseBlocked(data, itemId, context.itemEffects,
          context.isBall == true) then
          local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
              game, "no_catching", "No Catching is ON!",
              "That capture is off limits. Your run allows no catches.",
              "This challenge leaves wild Pokemon wild. Put the Ball away.")
          return ItemPolicy.denied(
              "no_catching", "no_catching", t1, t2, t3)
      end

      -- A level cap constrains level advancement, not only EXP gain.
      if id == "RARE_CANDY" and levelCapScope() > 0 and type(target) == "table" then
          local cap = nextLevelCap(save)
          local level = tonumber(target.level) or 0
          if cap < 100 and level >= cap then
              return ItemPolicy.deniedRule(game,
                  "level_cap", "level_cap_scope",
                  "The level cap blocks that Rare Candy.", nil, nil,
                  { cap = cap, level = level })
          end
      end

      if mod.save:get("no_pp_items", false) == true and ItemPolicy.matchesSet(data, itemId, ItemPolicy.ppRecovery) then
          return ItemPolicy.deniedRule(game,
              "no_pp_items", "no_pp_items", "PP items are banned.")
      end

      if not inBattle then
          if mod.save:get("no_fishing", false) == true
              and ItemPolicy.isFishingRod(data, itemId) then
              return ItemPolicy.deniedRule(game,
                  "no_fishing", "no_fishing", "Fishing is banned.")
          end
          if mod.save:get("no_repels", false) == true and ItemPolicy.matchesSet(data, itemId, ItemPolicy.repels) then
              return ItemPolicy.deniedRule(game,
                  "no_repels", "no_repels", "Repels are banned.")
          end
          if id == "ESCAPE_ROPE" and type(mod.exports.__beta26.dungeonLockActive) == "function"
              and mod.exports.__beta26.dungeonLockActive(game) then
              return ItemPolicy.deniedRule(game,
                  "dungeon_lock_in", "dungeon_lock_in",
                  "Dungeon Lock-In blocks the Escape Rope.")
          end
          if mod.save:get("no_escape_rope", false) == true and id == "ESCAPE_ROPE" then
              return ItemPolicy.deniedRule(game,
                  "no_escape_rope", "no_escape_rope", "Escape Rope is banned.")
          end
          if mod.save:get("no_field_healing", false) == true
              and ItemPolicy.matchesSet(data, itemId, ItemPolicy.fieldHealing) then
              return ItemPolicy.deniedItemRule(game, data,
                  "no_field_healing", "no_field_healing", itemId, target)
          end
          return true
      end

      -- Catch legality is separate. Dynamic ball detection prevents custom balls
      -- from being caught by the legacy combined No Items compatibility rule.
      if ItemPolicy.isBall(data, itemId, context.itemEffects) then return true end

      if mod.save:get("no_healing_items", false) == true
          and ItemPolicy.matchesSet(data, itemId, ItemPolicy.fieldHealing) then
          return ItemPolicy.deniedRule(game,
              "no_healing_items", "no_healing_items",
              "Healing items are banned in battle.")
      end
      if mod.save:get("no_battle_items", false) == true and ItemPolicy.matchesSet(data, itemId, ItemPolicy.xBattle) then
          return ItemPolicy.deniedRule(game,
              "no_battle_items", "no_battle_items",
              "X Items are banned in battle.")
      end
      return true
  end

  function ItemPolicy.present(game, decision, context)
      if type(decision) ~= "table" then return "failed", { "Item use is blocked!" } end
      game = game or currentGame or mod.game
      context = type(context) == "table" and context or {}
      local tier = worldTier(game)
      local message = decision.message or "Item use is blocked!"
      if tier >= 3 then
          message = decision.tier3 or decision.tier2 or message
      elseif tier >= 2 then
          message = decision.tier2 or message
      end

      -- 2.4.95: field-item rejection text must be player-paced. The Bag's
      -- native ItemEffects result-message path advances these longer Nuzlocke
      -- strings too quickly on handheld runtime. Outside battle, present the
      -- exact same selected rule text through our blocking world paginator:
      -- 18-glyph wrapping, max two lines per page, A-driven continuation.
      -- Return an empty native result-message list when that TextBox was
      -- successfully pushed so the Bag does not flash a duplicate fast line.
      if context.inBattle ~= true and context.battle == nil then
          local shown = mod.exports.__beta26.pushWorldText(game, message)
          if shown then
              return "failed", {}
          end
      end

      -- Battle use retains the native result channel; stacking an overworld
      -- TextBox into BattleState would be unsafe and would alter turn/UI flow.
      return "failed", { mod.exports.__beta26.cleanWorldText(message) }
  end

  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.canUseItem = function(game, itemId, context)
          context = type(context) == "table" and context or {}
          local allowed, decision = evaluateItemUsePolicy(
              game, context.data or (game and game.data),
              context.save or (game and game.save), itemId, context.target, context)
          return allowed, decision and decision.code or nil, decision
      end
      mod.exports.nuzlocke_compat.canPurchase = function(game, context)
          context = type(context) == "table" and context or {}
          if mod.save:get("nuzlocke_enabled", true) == false
              or not (game and game.save) then return true end
          local kind = tostring(context.kind or ""):lower()
          if (kind == "item_shop" or kind == "shop_item")
              and mod.save:get("no_buying", false) == true then
              return false, "no_buying"
          end
          return true
      end
      mod.exports.nuzlocke_compat.canSell = function(game, context)
          context = type(context) == "table" and context or {}
          if mod.save:get("nuzlocke_enabled", true) == false
              or not (game and game.save) then return true end
          local kind = tostring(context.kind or ""):lower()
          if (kind == "item_shop" or kind == "shop_item")
              and mod.save:get("no_selling", false) == true then
              return false, "no_selling"
          end
          return true
      end
  end

  -- Gen1Recomp 0.1.98 exposes contextual field actions through mod.world.
  -- Those helpers deliberately call the active overworld directly instead of
  -- re-opening the Pack, so Pack-only policy hooks are not an authoritative
  -- veto. Guard the underlying fishing/Gold field-item seams as a backstop;
  -- normal Pack use still gets the richer ItemPolicy presentation above.
  function ItemPolicy.installFieldActionGuards()
      if mod.exports.__beta26.isSaveEditorSession() then return true end
      if mod.exports.__beta26.runtimeIsGold(currentGame or mod.game) then
          local ok, World = pcall(require, "src.world.gen2.World")
          if not ok or type(World) ~= "table"
              or type(World.useFieldItem) ~= "function" then return false end
          local session = World.__nuzlockeFieldActionGuardSession
          if type(session) == "table" and session.owner == mod
              and World.useFieldItem == session.wrapper then return true end
          if type(session) == "table" and session.owner ~= mod
              and World.useFieldItem == session.wrapper
              and type(session.previous) == "function" then
              World.useFieldItem = session.previous
          end
          local previous = World.useFieldItem
          local wrapper = function(self, itemId, ...)
              local game = self and self.game or currentGame or mod.game
              local allowed, decision = evaluateItemUsePolicy(
                  game, game and game.data, game and game.save, itemId, nil,
                  { inBattle = false, overworld = self, generation = 2 })
              if allowed == false then
                  if self then self.nuzlockeItemUseBlocked = decision and decision.code end
                  return "nowhere"
              end
              return previous(self, itemId, ...)
          end
          World.useFieldItem = wrapper
          World.__nuzlockeFieldActionGuardSession = {
              owner = mod, previous = previous, wrapper = wrapper,
          }
          return true
      end

      local ok, Overworld = pcall(require, "src.world.OverworldController")
      if not ok or type(Overworld) ~= "table"
          or type(Overworld.useFishingRod) ~= "function" then return false end
      local session = Overworld.__nuzlockeFishingGuardSession
      if type(session) == "table" and session.owner == mod
          and Overworld.useFishingRod == session.wrapper then return true end
      if type(session) == "table" and session.owner ~= mod
          and Overworld.useFishingRod == session.wrapper
          and type(session.previous) == "function" then
          Overworld.useFishingRod = session.previous
      end
      local previous = Overworld.useFishingRod
      local wrapper = function(self, rod, ...)
          local game = currentGame or mod.game
          local allowed, decision = evaluateItemUsePolicy(
              game, game and game.data, game and game.save, rod, nil,
              { inBattle = false, overworld = self, generation = 1 })
          if allowed == false and decision and decision.code == "no_fishing" then
              return false
          end
          return previous(self, rod, ...)
      end
      Overworld.useFishingRod = wrapper
      Overworld.__nuzlockeFishingGuardSession = {
          owner = mod, previous = previous, wrapper = wrapper,
      }
      return true
  end

  function ItemPolicy.install()
      local engineState = mod.exports.__beta26.compat
          and mod.exports.__beta26.compat.Engine
          and mod.exports.__beta26.compat.Engine.state
      if mod.exports.__beta26.isSaveEditorSession() then
          if type(engineState) == "table" then
              engineState.item_use = { ok = true, environment = "save_editor", runtime_patch = "skipped" }
          end
          refreshPublicCompatSnapshots()
          return true
      end
      local ok, ItemEffects = pcall(require, "src.inventory.ItemEffects")
      if not ok or type(ItemEffects) ~= "table" or type(ItemEffects.use) ~= "function" then
          if type(engineState) == "table" then
              engineState.item_use = { ok = false, reason = "ItemEffects.use unavailable" }
          end
          refreshPublicCompatSnapshots()
          return false
      end

      -- Identity validation matters more than an owner string. If another mod
      -- legitimately wraps/replaces ItemEffects.use after us, a later safe
      -- lifecycle boundary composes around the *current* live function instead
      -- of assuming our old closure is still active. No per-frame rebinding.
      if ItemEffects.__nuzlockeItemRuleGateOwner == mod
          and ItemEffects.use == ItemEffects.__nuzlockeItemRuleGateFunction then
          if type(engineState) == "table" then
              engineState.item_use = { ok = true, owner = "current_session", relationship = "compose" }
          end
          refreshPublicCompatSnapshots()
          return true
      end

      if ItemEffects.__nuzlockeItemRuleGateOwner ~= nil
          and ItemEffects.__nuzlockeItemRuleGateOwner ~= mod
          and ItemEffects.use == ItemEffects.__nuzlockeItemRuleGateFunction
          and type(ItemEffects.__nuzlockeItemRuleGatePrevious) == "function" then
          ItemEffects.use = ItemEffects.__nuzlockeItemRuleGatePrevious
      end

      local previousUse = ItemEffects.use
      local gate
      gate = function(data, save, itemId, target, battle, moveIndex, ow)
          local game = (battle and battle.game) or (ow and ow.game)
              or currentGame or mod.game
          local allowed, decision = evaluateItemUsePolicy(
              game, data, save, itemId, target,
              { battle = battle, inBattle = battle ~= nil, overworld = ow,
                moveIndex = moveIndex, itemEffects = ItemEffects })
          if not allowed then
              return ItemPolicy.present(game, decision, {
                  battle = battle,
                  inBattle = battle ~= nil,
                  overworld = ow,
                  itemId = itemId,
              })
          end
          return previousUse(data, save, itemId, target, battle, moveIndex, ow)
      end
      ItemEffects.use = gate
      ItemEffects.__nuzlockeItemRuleGateInstalled = true
      ItemEffects.__nuzlockeItemRuleGateOwner = mod
      ItemEffects.__nuzlockeItemRuleGateFunction = gate
      ItemEffects.__nuzlockeItemRuleGatePrevious = previousUse
      if type(engineState) == "table" then
          engineState.item_use = { ok = true, owner = "current_session", relationship = "compose" }
      end
      refreshPublicCompatSnapshots()
      return true
  end

  -- 2.3.10: item/field engine adapters install only after lifecycle events.
  -- Re-check only at coarse lifecycle boundaries. This repairs a live function
  -- replaced during startup/mod composition without introducing battle-frame work.
  mod.events:on("game.ready", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("save.loaded", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("mods.loaded", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("map.entered", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)
  mod.events:on("battle.started", function()
      pcall(ItemPolicy.install); pcall(ItemPolicy.installFieldActionGuards)
  end)

  ---------------------------------------------------------------------
  -- BATTLE ITEM FALLBACK HOOK
  ---------------------------------------------------------------------
  mod.hooks:wrap("battle.use_item", function(next, battle, item)
      local game = battle and battle.game or currentGame
      if not active(game, battle) then return next(battle, item) end
      local okEffects, ItemEffects = pcall(require, "src.inventory.ItemEffects")
      local allowed, decision = evaluateItemUsePolicy(
          game, game and game.data, game and game.save, item,
          type(item) == "table" and item.target or nil,
          { battle = battle, inBattle = true,
            itemEffects = okEffects and ItemEffects or nil })
      if not allowed then
          local _, messages = ItemPolicy.present(game, decision, {
              battle = battle, inBattle = true, itemId = item,
          })
          return false, messages and messages[1] or "Item use is blocked!"
      end
      return next(battle, item)
  end)

  ---------------------------------------------------------------------
  -- NO ESCAPE
  --
  -- BattleState exposes the Gen 1 escape calculation through the public
  -- battle.run hook. Returning false from this hook makes both the RUN
  -- command and the faint-screen "Use next POKeMON? -> NO" escape attempt
  -- fail normally, which means the player gets the vanilla "Can't escape!"
  -- result and the turn is consumed. Trainer battles never reach this hook
  -- because the engine rejects RUN before attempting the escape roll.
  ---------------------------------------------------------------------
  mod.hooks:wrap("battle.run", function(next, ctx)
      local battle = ctx and ctx.battle
      -- Gold's pure Battle model carries save/data but no `battle.game`; the
      -- shared battle.run hook still passes that Battle as ctx.battle. Resolve
      -- the live game generation-neutrally so No Escape is not silently inert
      -- on Gold while retaining R/B/Y's direct battle.game when available.
      local game = battle and battle.game or currentGame or mod.game
      if active(game, battle)
          and mod.save:get("no_escape", false) == true then
          local provider = activeCompatProvider("escape", game, battle)
          local relationship = provider and
              mod.exports.__beta26.compat.Mods.relationshipFor(provider.id, "escape")
          if provider and (relationship == "delegate" or relationship == "exclusive") then
              return next(ctx)
          end
          -- Returning false already produces the engine's native
          -- "Can't escape!" result and consumes the turn. Do not stack a
          -- second World Building TextBox into the battle flow.
          return false
      end
      return next(ctx)
  end, 100000)

  ---------------------------------------------------------------------
  -- MAP ENTRY
  --
  -- map.entered gives the actual engine map ID.
  -- via="boot" is important: an old save loaded in Pallet Town is
  -- immediately recorded without requiring the player to walk.
  ---------------------------------------------------------------------
  mod.events:on("map.entered", function(ev)
      if not ev or not ev.mapId then
          return
      end

      local map = ev.map
      local x, y = mod.exports.__beta26.encounterPosition(currentGame)
      local physical = mod.exports.__beta26.cardinalPhysicalArea(ev.mapId, x, y,
          map and map.widthCells, map and map.heightCells)
      local key = registerArea(mod.exports.__beta26.projectEncounterArea(physical))

      if not isTrackedArea(key) then
          return
      end

      markVisited(physical)
  end)

  ---------------------------------------------------------------------
  -- WORLD STEP
  -- Keep the tracker synchronized with the actual map the player is on.
  -- This is intentionally redundant with map.entered: world.stepped is a
  -- cheap, reliable fallback for connections/transitions and old saves.
  ---------------------------------------------------------------------
  mod.events:on("world.stepped", function(ev)
      if not ev or not ev.mapId then
          return
      end

      local map = currentGame and currentGame.overworld
          and currentGame.overworld.map
      local physical = mod.exports.__beta26.cardinalPhysicalArea(
          ev.mapId, ev.x, ev.y,
          map and map.widthCells, map and map.heightCells)
      local key = registerArea(mod.exports.__beta26.projectEncounterArea(physical))
      if key then
          markVisited(physical)
      end
  end)

  ---------------------------------------------------------------------
  -- OVERWORLD ENCOUNTER DETECTION
  --
  -- Different overworld-spawn mods may annotate the catch event/battle in
  -- different ways. Accept the common explicit flags first, then treat a
  -- catch with no battle object as an overworld capture. Normal wild battles
  -- remain eligible regardless of this setting.
  ---------------------------------------------------------------------
  mod.exports.__beta26.isOverworldEncounter = function(ev)
      if not ev then
          return false
      end

      if ev.overworldEncounter == true
          or ev.overworld == true
          or ev.isOverworld == true
          or ev.encounterType == "overworld"
          or ev.source == "overworld" then
          return true
      end

      local battle = ev.battle
      if battle then
          if battle.overworldEncounter == true
              or battle.overworld == true
              or battle.isOverworld == true
              or battle.encounterType == "overworld"
              or battle.source == "overworld" then
              return true
          end
      else
          -- A capture event without a battle is treated as an overworld
          -- capture. This is useful for mods that spawn/capture Pokemon
          -- directly without constructing the vanilla wild-battle state.
          return true
      end

      return false
  end

  ---------------------------------------------------------------------
  -- VERSION DETECTION
  --
  -- Detects RBY and GSC-family version ids exposed by the live engine.
  -- Falls back to RED only when the engine exposes no recognizable version.
  ---------------------------------------------------------------------
  getGameVersion = function()
      local candidates = {}
      local ok, GameVersion = pcall(require, "src.core.GameVersion")
      if ok and GameVersion then
          if type(GameVersion.get) == "function" then
              local okGet, detected = pcall(GameVersion.get)
              if okGet then candidates[#candidates+1] = detected end
          end
          candidates[#candidates+1] = GameVersion.version
      end
      if currentGame then
          candidates[#candidates+1] = currentGame.version
          candidates[#candidates+1] = currentGame.gameVersion
          candidates[#candidates+1] = currentGame.data and currentGame.data.version
          candidates[#candidates+1] = currentGame.data and currentGame.data.gameVersion
      end
      for _, v in ipairs(candidates) do
          local upper = tostring(v or ""):upper()
          if upper:find("CRYSTAL",1,true) or upper:find("CRY",1,true) then return "CRYSTAL" end
          if upper:find("SILVER",1,true) or upper:find("SLV",1,true) then return "SILVER" end
          if upper:find("GOLD",1,true) or upper == "G" then return "GOLD" end
          if upper:find("YELLOW",1,true) or upper:find("YLW",1,true) then return "YELLOW" end
          if upper:find("BLUE",1,true) or upper:find("BLU",1,true) then return "BLUE" end
          if upper:find("RED",1,true) then return "RED" end
      end
      return "RED"
  end

  mod.exports.__beta26.getGameProfile = function()
      local version = getGameVersion()
      return VersionCompat.profiles[version] or {family="UNKNOWN",region="UNKNOWN",status="unknown"}
  end

  ---------------------------------------------------------------------
  -- GOLD PRE-NEW-GAME SETUP
  --
  -- Gold Setup is handled at the title menu above through the native
  -- {label,value} row shape and MainMenu:choose() dispatch. Previous
  -- post-NEW-GAME intro insertion experiments are intentionally removed.
  ---------------------------------------------------------------------


  ---------------------------------------------------------------------
  -- GIFT POKEMON TABLE  (version-tagged)
  -- area = where the gift is received; takes up that slot.
  -- version: nil=all R/B/Y, RB=Red/Blue, YLW=Yellow, RY=Red/Yellow, BY=Blue/Yellow.
  -- This is a Gen-I source catalog; Gold never inherits nil-tagged entries.
  ---------------------------------------------------------------------
  local GIFT_LOCATIONS = {
      { species = "MAGIKARP",   area = "ROUTE_4",         version = nil   },
      { species = "HITMONCHAN", area = "SAFFRON_CITY",    version = nil   },
      { species = "HITMONLEE",  area = "SAFFRON_CITY",    version = nil   },
      { species = "LAPRAS",     area = "SILPH_CO",        version = nil   },
      { species = "EEVEE",      area = "CELADON_CITY",    version = nil   },
      { species = "OMANYTE",    area = "CINNABAR_ISLAND", version = nil   },
      { species = "KABUTO",     area = "CINNABAR_ISLAND", version = nil   },
      { species = "AERODACTYL", area = "CINNABAR_ISLAND", version = nil   },
      { species = "SCYTHER",    area = "CELADON_CITY",    version = "RY"  },
      { species = "PORYGON",    area = "CELADON_CITY",    version = nil   },
      { species = "DRATINI",    area = "CELADON_CITY",    version = "RB"  },
      { species = "PINSIR",     area = "CELADON_CITY",    version = "BY"  },
      { species = "BULBASAUR",  area = "CERULEAN_CITY",   version = "YLW" },
      { species = "CHARMANDER", area = "ROUTE_24",        version = "YLW" },
      { species = "SQUIRTLE",   area = "VERMILION_CITY",  version = "YLW" },
  }

  mod.exports.__beta26.buildGiftLookup = function()
      local ver = getGameVersion()
      local lookup = {}
      if ver ~= "RED" and ver ~= "BLUE" and ver ~= "YELLOW" then
          return lookup
      end
      for _, g in ipairs(GIFT_LOCATIONS) do
          if g.version == nil
              or (g.version == "RB"  and (ver == "RED" or ver == "BLUE"))
              or (g.version == "YLW" and ver == "YELLOW")
              or (g.version == "RY" and (ver == "RED" or ver == "YELLOW"))
              or (g.version == "BY" and (ver == "BLUE" or ver == "YELLOW")) then
              lookup[g.species] = g.area
          end
      end
      return lookup
  end

  ---------------------------------------------------------------------
  -- IN-GAME TRADE TABLE  (version-tagged)
  -- gives = species you receive; area = where the NPC lives.
  ---------------------------------------------------------------------
  local TRADE_DATA = {
      -- English Red/Blue (pret/pokered data/events/trades.asm).
      { gives = "NIDORINA",  wants = "NIDORINO",  area = "ROUTE_11",        version = "RB"  },
      { gives = "MR_MIME",   wants = "ABRA",      area = "ROUTE_2",         version = "RB"  },
      { gives = "SEEL",      wants = "PONYTA",    area = "CINNABAR_ISLAND", version = "RB"  },
      { gives = "FARFETCHD", wants = "SPEAROW",   area = "VERMILION_CITY",  version = "RB"  },
      { gives = "LICKITUNG", wants = "SLOWBRO",   area = "ROUTE_18",        version = "RB"  },
      { gives = "JYNX",      wants = "POLIWHIRL", area = "CERULEAN_CITY",   version = "RB"  },
      { gives = "ELECTRODE", wants = "RAICHU",    area = "CINNABAR_ISLAND", version = "RB"  },
      { gives = "TANGELA",   wants = "VENONAT",   area = "CINNABAR_ISLAND", version = "RB"  },
      { gives = "NIDORAN_F", wants = "NIDORAN_M", area = "ROUTE_5",         version = "RB"  },
      -- Yellow (pret/pokeyellow data/events/trades.asm).
      { gives = "DUGTRIO",   wants = "LICKITUNG", area = "ROUTE_11",        version = "YLW" },
      { gives = "MR_MIME",   wants = "CLEFAIRY",  area = "ROUTE_2",         version = "YLW" },
      { gives = "MUK",       wants = "KANGASKHAN",area = "CINNABAR_ISLAND", version = "YLW" },
      { gives = "PARASECT",  wants = "TANGELA",   area = "ROUTE_18",        version = "YLW" },
      { gives = "RHYDON",    wants = "GOLDUCK",   area = "CINNABAR_ISLAND", version = "YLW" },
      { gives = "DEWGONG",   wants = "GROWLITHE", area = "CINNABAR_ISLAND", version = "YLW" },
      { gives = "MACHOKE",   wants = "CUBONE",    area = "ROUTE_5",         version = "YLW" },
  }

  mod.exports.__beta26.buildTradeLookup = function()
      local ver = getGameVersion()
      local lookup = {}
      if ver ~= "RED" and ver ~= "BLUE" and ver ~= "YELLOW" then
          return lookup
      end
      for _, t in ipairs(TRADE_DATA) do
          if t.version == nil
              or (t.version == "RB"  and (ver == "RED" or ver == "BLUE"))
              or (t.version == "YLW" and ver == "YELLOW") then
              lookup[t.gives] = t.area
          end
      end
      return lookup
  end

  -- When a source-less compatibility event has no usable location, infer a
  -- vanilla acquisition kind only for species whose provenance is actually
  -- deterministic in that version. Native transaction wrappers carry explicit
  -- provenance, so ambiguous prize/wild or trade/wild species do not need a
  -- guess here.
  mod.exports.__beta26.deterministicSourceFallback = function(kind, species)
      local ver = getGameVersion()
      local key = tostring(species or ""):upper()
      if kind == "gift" then
          local common = {
              HITMONCHAN = true, HITMONLEE = true, LAPRAS = true,
              EEVEE = true, OMANYTE = true, KABUTO = true,
              AERODACTYL = true, PORYGON = true,
          }
          if common[key] then return true end
          return ver == "YELLOW"
              and (key == "BULBASAUR" or key == "CHARMANDER"
                  or key == "SQUIRTLE")
      end
      if kind == "trade" then
          if ver == "YELLOW" then return key == "MR_MIME" end
          if ver == "RED" or ver == "BLUE" then
              return key == "JYNX" or key == "FARFETCHD"
                  or key == "MR_MIME" or key == "LICKITUNG"
          end
      end
      return false
  end

  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.giftLocationFor = function(species)
          return mod.exports.__beta26.buildGiftLookup()[tostring(species or ""):upper()]
      end
      mod.exports.nuzlocke_compat.tradeLocationFor = function(species)
          return mod.exports.__beta26.buildTradeLookup()[tostring(species or ""):upper()]
      end
      mod.exports.nuzlocke_compat.isDeterministicGiftSource = function(species)
          return mod.exports.__beta26.deterministicSourceFallback("gift", species)
      end
      mod.exports.nuzlocke_compat.isDeterministicTradeSource = function(species)
          return mod.exports.__beta26.deterministicSourceFallback("trade", species)
      end
  end


  -- Gifts and in-game trades are transactions, not battles. Any rule that
  -- rejects one must do so BEFORE the engine removes/gives Pokemon or sets the
  -- NPC's completed-trade/gift state. Post-acquisition deletion can permanently
  -- destroy the player's offered Pokemon or burn a one-time gift.
  --
  -- 2.4.36: one shared slot-conflict predicate now owns CAUGHT/FAILED semantics
  -- for wild catches and special acquisitions. FAILED only blocks while the
  -- Failed Encounter rule is actually enabled; stale FAILED rows must not keep
  -- blocking gifts/trades/eggs after that rule is turned OFF.
  mod.exports.__beta26.encounterSlotConflict = function(game, area, requireArmed)
      area = routeKey(area) or area
      if not area or area == "UNKNOWN" or area == "__LEGACY__" then
          return nil
      end
      if mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) ~= true then
          return nil
      end
      if requireArmed == true
          and not mod.exports.__beta26.encounterRulesArmed(game) then
          return nil
      end
      syncCaughtAreasFromLog()
      if caughtAreas()[area] ~= nil then return "caught" end
      local state = getEncounterState and getEncounterState(area) or nil
      if type(state) == "table" and state.status == "CAUGHT" then
          return "caught"
      end
      if mod.save:get("failed_encounter", true) == true
          and type(state) == "table" and state.status == "FAILED" then
          return "failed"
      end
      return nil
  end

  mod.exports.__beta26.specialAreaUnavailable = function(area)
      return mod.exports.__beta26.encounterSlotConflict(
          currentGame or mod.game, area, false) ~= nil
  end


  -- Compatibility-facing acquisition-source classifier. Explicit provider
  -- provenance wins; source-less inference requires the reported/current area
  -- to agree with the version-aware vanilla source. UNKNOWN may still use a
  -- deterministic vanilla source as a last-resort compatibility fallback.
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.classifyAcquisition = function(game, species, source, location)
          local key = tostring(species or ""):upper()
          local src = tostring(source or ""):lower()
          local locKey = routeKey(location) or (location and tostring(location):upper()) or "UNKNOWN"
          if src == "gift" or src == "fossil" or src == "prize" then
              local area = locKey ~= "UNKNOWN" and locKey
                  or mod.exports.__beta26.buildGiftLookup()[key] or "UNKNOWN"
              return { kind = "gift", area = area, explicit = true }
          end
          if src == "trade" then
              local area = locKey ~= "UNKNOWN" and locKey
                  or mod.exports.__beta26.buildTradeLookup()[key] or "UNKNOWN"
              return { kind = "trade", area = area, explicit = true }
          end
          if src ~= "" then return { kind = src, area = locKey, explicit = true } end
          local gift = mod.exports.__beta26.buildGiftLookup()[key]
          if gift and ((routeKey(gift) or gift) == locKey
              or (locKey == "UNKNOWN" and mod.exports.__beta26.deterministicSourceFallback("gift", key))) then
              return { kind = "gift", area = gift, inferred = true }
          end
          local trade = mod.exports.__beta26.buildTradeLookup()[key]
          if trade and ((routeKey(trade) or trade) == locKey
              or (locKey == "UNKNOWN" and mod.exports.__beta26.deterministicSourceFallback("trade", key))) then
              return { kind = "trade", area = trade, inferred = true }
          end
          return { kind = "unknown", area = locKey, inferred = false }
      end
  end

  mod.exports.__beta26.currentSpecialArea = function(game, species, kind)
      species = tostring(species or ""):upper()
      -- The live map is stronger provenance than a species table and lets
      -- third-party gifts/trades reuse vanilla species in new locations.
      local current = areaKey(game, nil)
      current = routeKey(current) or current
      if current and current ~= "UNKNOWN" then return current end
      local lookup = kind == "trade" and mod.exports.__beta26.buildTradeLookup() or mod.exports.__beta26.buildGiftLookup()
      local known = lookup[species]
      return routeKey(known) or known or "UNKNOWN"
  end

  mod.exports.__beta26.configuredPartySizeLimit = function()
      return math.max(1, math.min(6, math.floor(tonumber(
          mod.save:get("party_size_limit", defaultRuleValue("party_size_limit"))) or 6)))
  end

  mod.exports.__beta26.partyAtConfiguredLimit = function(save)
      local limit = mod.exports.__beta26.configuredPartySizeLimit()
      -- 6 is the native party capacity, so preserve vanilla auto-box behavior.
      return limit < 6 and active(currentGame or mod.game, nil)
          and #(save and save.party or {}) >= limit
  end

  specialAcquisitionDenied = function(game, species, area, kind, mon)
      if not active(game, nil) then return nil end
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
      species = glitch.key

      if kind == "gift" and mod.save:get("allow_gifts", defaultRuleValue("allow_gifts")) ~= true then
          return "disabled"
      end
      if kind == "trade" and mod.save:get("allow_trades", defaultRuleValue("allow_trades")) ~= true then
          return "disabled"
      end
      if glitch.isGlitch and not mod.exports.__beta26.glitchCatchesAllowed() then
          return "glitch"
      end
      local typeAllowed = type(mon) == "table"
          and mod.exports.__beta26.typeLockAllowsPokemon(game, mon)
          or mod.exports.__beta26.typeLockAllowsSpecies(game, species)
      if not typeAllowed then return "type_lock" end

      if Identity.isLegendarySpecies(game, species)
          and mod.save:get("ban_legendaries", false) == true then
          return "legendary"
      end
      if Identity.isMythicalSpecies(game, species)
          and mod.save:get("ban_mythicals", false) == true then
          return "mythical"
      end
      if Identity.isPseudoSpecies(game, species)
          and mod.save:get("ban_pseudos", false) == true then
          return "pseudo"
      end
      local bstLimit = mod.exports.__beta26.getMaximumBST()
      local bst = bstLimit > 0
          and mod.exports.__beta26.getSpeciesBST(game, species) or nil
      if bst and bst > bstLimit then
          return "bst"
      end
      if mod.exports.__beta26.specialAreaUnavailable(area) then
          return "area"
      end
      if (kind == "gift" or kind == "trade")
          and mod.exports.__beta26.partyAtConfiguredLimit(game and game.save) then
          return "party_size"
      end
      return nil
  end

  ---------------------------------------------------------------------
  -- STARTER SPECIES LOOKUP  (version-aware)
  ---------------------------------------------------------------------
  local STARTERS_BY_VERSION = {
      RED    = { BULBASAUR = true, CHARMANDER = true, SQUIRTLE = true },
      BLUE   = { BULBASAUR = true, CHARMANDER = true, SQUIRTLE = true },
      YELLOW = { PIKACHU   = true },
  }

  mod.exports.__beta26.isStarterSpecies = function(species)
      local ver = getGameVersion()
      local starters = STARTERS_BY_VERSION[ver] or STARTERS_BY_VERSION["RED"]
      return starters[tostring(species or ""):upper()] == true
  end

  -- 2.4.96: Random Starter can turn the opening Pokemon into any legal
  -- species, so species-family heuristics alone cannot identify it afterward.
  -- Use the committed accepted random-starter scalar plus first-party/opening
  -- location provenance. Preview rolls are intentionally ignored.
  mod.exports.__beta26.isOpeningStarterAcquisition = function(
      game, species, source, location, mon)
      game = game or currentGame or mod.game
      species = tostring(species or ""):upper()
      source = tostring(source or ""):lower()
      local loc = tostring(location or ""):upper()
      local openingLoc = loc == "" or loc == "UNKNOWN"
          or loc == "PALLET_TOWN"
          or loc:find("OAK", 1, true) ~= nil
          or loc:find("LAB", 1, true) ~= nil

      if source == "starter" then return true end
      if source ~= "" then return false end
      if mod.exports.__beta26.isStarterSpecies(species) and openingLoc then
          return true
      end

      if mod.exports.__beta26.runtimeIsGold(game) then return false end
      if mod.save:get("random_starter", false) ~= true then return false end
      if externalRuleDelegation
          and externalRuleDelegation("random_starter", game) then
          return false
      end

      local accepted = tostring(
          mod.save:get("__nuzlocke_random_starter_choice", "") or ""):upper()
      if accepted == "" or accepted ~= species or not openingLoc then
          return false
      end

      local save = game and game.save
      local party = save and save.party or {}
      if #party > 1 then return false end
      if mon and type(party[1]) == "table" then
          if party[1] == mon then return true end
          local a = Identity.pokemonIdentity(party[1])
          local b = Identity.pokemonIdentity(mon)
          if a ~= nil and b ~= nil and tostring(a) == tostring(b) then
              return true
          end
      end
      return #party <= 1
  end

  ---------------------------------------------------------------------
  -- REGISTER STARTER IN PALLET TOWN
  -- Always records the starter in PALLET_TOWN regardless of the
  -- town_catches toggle. Pallet Town is the one mandatory town slot.
  ---------------------------------------------------------------------
  mod.exports.__beta26.registerStarterCatch = function(species, mon)
      if not species then return end
      species = tostring(species):upper()
      local area = "PALLET_TOWN"
      registerArea(area)
      markVisited(area)

      local areas = caughtAreas()
      if areas[area] then
          -- A starter can emit both received and caught events. If the slot is
          -- already registered, tag this event's mon as handled so the later
          -- pokemon.caught event cannot create a second log entry.
          if mon then
              mon.catchLocation = area
              mon.encounterType = "gift"
              mon.nuzlockeTrackerRegistered = true
              Identity.setPokemonOrigin(mon, "NORMAL")
              Identity.baselineAdd(mon, "NORMAL")
          end
          return
      end

      local log = trackerLog()
      log[area] = log[area] or {}
      local monId = mon and Identity.ensurePokemonIdentity(mon, currentSave, "NORMAL") or nil
      table.insert(log[area], {
          species       = species,
          pokemonId     = monId,
          fingerprint   = mon and Identity.fingerprint(mon) or nil,
          isShiny       = mon and Identity.isShiny(mon),
          encounterType = "gift",
      })
      mod.save:set("tracker_log", log)
      markCaught(area, species)

      if mon then
          mon.catchLocation = area
          mon.encounterType = "gift"
          mon.nuzlockeDead  = false
          mon.nuzlockeTrackerRegistered = true
          Identity.setPokemonOrigin(mon, "NORMAL")
          Identity.baselineAdd(mon, "NORMAL")
      end

      local history = mod.save:get("nuzlocke_history", {})
      if type(history) ~= "table" then history = {} end
      table.insert(history, {
          name          = (mon and (mon.nickname or mon.species)) or species,
          species       = species,
          pokemonId     = monId,
          catchLocation = area,
          encounterType = "gift",
          status        = "ALIVE",
      })
      mod.save:set("nuzlocke_history", history)
  end

  -- 2.5.23: repair the exact fresh-R/B/Y regression where the native starter
  -- transaction completed while the command resolver wrapper was missing.
  -- Stay conservative: use the committed random choice when present, otherwise
  -- only the vanilla starter-choice event flags. Never guess from an arbitrary
  -- one-Pokemon party later in the run.
  mod.exports.__beta26.repairOpeningStarterTrackerLocation = function(game)
      if saveSchemaTooNew then return false end
      game = game or currentGame or mod.game
      if mod.exports.__beta26.runtimeIsGold(game) then return false end
      local save = game and game.save
      local flags = save and save.flags or {}
      if not save or not (flags.EVENT_GOT_STARTER == true
          or tonumber(flags.EVENT_GOT_STARTER) == 1) then
          return false
      end

      local accepted = tostring(mod.save:get(
          "__nuzlocke_random_starter_choice", "") or ""):upper()
      if accepted == "" then
          if flags.EVENT_CHOSE_PIKACHU == true or tonumber(flags.EVENT_CHOSE_PIKACHU) == 1 then
              accepted = "PIKACHU"
          elseif flags.EVENT_CHOSE_CHARMANDER == true or tonumber(flags.EVENT_CHOSE_CHARMANDER) == 1 then
              accepted = "CHARMANDER"
          elseif flags.EVENT_CHOSE_SQUIRTLE == true or tonumber(flags.EVENT_CHOSE_SQUIRTLE) == 1 then
              accepted = "SQUIRTLE"
          elseif flags.EVENT_CHOSE_BULBASAUR == true or tonumber(flags.EVENT_CHOSE_BULBASAUR) == 1 then
              accepted = "BULBASAUR"
          end
      end
      if accepted == "" then return false end

      local mon
      for _, candidate in ipairs(save.party or {}) do
          if tostring(candidate and candidate.species or ""):upper() == accepted then
              mon = candidate; break
          end
      end
      if not mon then
          for _, box in ipairs(save.boxes or {}) do
              for _, candidate in ipairs(box or {}) do
                  if tostring(candidate and candidate.species or ""):upper() == accepted then
                      mon = candidate; break
                  end
              end
              if mon then break end
          end
      end
      if type(mon) ~= "table" then return false end

      local monId = Identity.pokemonIdentity(mon)
      local log = trackerLog()
      local changed = false
      for area, rows in pairs(log) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN" and type(rows) == "table"
              and (areaText == "UNKNOWN" or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true)) then
              for i = #rows, 1, -1 do
                  local row = rows[i]
                  local same = false
                  if type(row) == "table" and monId ~= nil and row.pokemonId ~= nil then
                      same = tostring(row.pokemonId) == tostring(monId)
                  elseif type(row) == "table" then
                      same = tostring(row.species or ""):upper() == accepted
                  end
                  if same then table.remove(rows, i); changed = true end
              end
              if #rows == 0 then log[area] = nil end
          end
      end

      local areas = caughtAreas()
      for area, value in pairs(areas) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN"
              and (areaText == "UNKNOWN" or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true))
              and tostring(value or ""):upper() == accepted then
              areas[area] = nil
              changed = true
          end
      end
      if changed then
          mod.save:set("tracker_log", log)
          mod.save:set("caught_areas", areas)
      end
      mod.exports.__beta26.registerStarterCatch(accepted, mon)
      return true
  end

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev or currentGame or mod.game
      pcall(mod.exports.__beta26.repairOpeningStarterTrackerLocation, game)
  end)
  mod.events:on("save.loaded", function(ev)
      local game = type(ev) == "table" and ev.game or currentGame or mod.game
      pcall(mod.exports.__beta26.repairOpeningStarterTrackerLocation, game)
  end)

  -- Repair a randomized opening starter that an older build logged under
  -- Oak's Lab/UNKNOWN instead of PALLET_TOWN. Identity wins; species-only is
  -- used only while the save still has exactly one Pokemon and the committed
  -- accepted starter matches it.
  mod.exports.__beta26.repairRandomStarterTrackerLocation = function(game)
      if saveSchemaTooNew then return false end
      game = game or currentGame or mod.game
      if mod.exports.__beta26.runtimeIsGold(game)
          or mod.save:get("random_starter", false) ~= true then
          return false
      end
      local accepted = tostring(
          mod.save:get("__nuzlocke_random_starter_choice", "") or ""):upper()
      if accepted == "" then return false end
      local save = game and game.save
      local party = save and save.party or {}
      local mon = party[1]
      if type(mon) ~= "table" or tostring(mon.species or ""):upper() ~= accepted then
          return false
      end
      local monId = Identity.pokemonIdentity(mon)
      local log = trackerLog()
      local foundWrong = false
      for area, rows in pairs(log) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN" and type(rows) == "table"
              and (areaText == "UNKNOWN"
                  or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true)) then
              for i = #rows, 1, -1 do
                  local row = rows[i]
                  local same = false
                  if type(row) == "table" and monId ~= nil
                      and row.pokemonId ~= nil then
                      same = tostring(row.pokemonId) == tostring(monId)
                  elseif type(row) == "table" and #party == 1 then
                      same = tostring(row.species or ""):upper() == accepted
                  end
                  if same then
                      table.remove(rows, i)
                      foundWrong = true
                  end
              end
              if #rows == 0 then log[area] = nil end
          end
      end
      if not foundWrong and mon.catchLocation == "PALLET_TOWN"
          and type(log.PALLET_TOWN) == "table" then
          return false
      end

      -- Clear only a wrong opening-area ledger entry matching this starter.
      local areas = caughtAreas()
      for area, value in pairs(areas) do
          local areaText = tostring(area or ""):upper()
          if area ~= "PALLET_TOWN"
              and (areaText == "UNKNOWN"
                  or areaText:find("OAK", 1, true)
                  or areaText:find("LAB", 1, true))
              and tostring(value or ""):upper() == accepted then
              areas[area] = nil
          end
      end
      mod.save:set("caught_areas", areas)
      mod.save:set("tracker_log", log)

      -- registerStarterCatch is idempotent and hydrates the concrete Pokemon.
      mod.exports.__beta26.registerStarterCatch(accepted, mon)
      return true
  end

  mod.events:on("game.ready", function(ev)
      local game = type(ev) == "table" and ev.game or ev or currentGame or mod.game
      pcall(mod.exports.__beta26.repairRandomStarterTrackerLocation, game)
  end)
  mod.events:on("save.loaded", function(ev)
      local game = type(ev) == "table" and ev.game or currentGame or mod.game
      pcall(mod.exports.__beta26.repairRandomStarterTrackerLocation, game)
  end)

  ---------------------------------------------------------------------
  -- REGISTER GIFT / TRADE CATCH IN ITS PROPER AREA
  ---------------------------------------------------------------------
  mod.exports.__beta26.registerSpecialCatch = function(species, area, encounterType, mon, opts)
      if not species or not area then return false end
      opts = type(opts) == "table" and opts or {}
      local consume = opts.consume ~= false
      local origin = tostring(opts.origin or "NORMAL")
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(currentGame, species)
      local rawSpecies = species
      species = glitch.key
      area = routeKey(area) or area
      registerArea(area)
      markVisited(area)

      local log = trackerLog()
      log[area] = log[area] or {}
      local monId = mon and Identity.ensurePokemonIdentity(mon, currentSave, origin) or nil

      local function hydrateRegisteredMon(existing)
          if not mon then return end
          mon.catchLocation = area
          mon.encounterType = (type(existing) == "table" and existing.encounterType)
              or encounterType
          mon.nuzlockeDead = false
          mon.nuzlockeTrackerRegistered = true
          mon.nuzlockeGlitch = glitch.isGlitch or nil
          mon.nuzlockeMissingNo = glitch.missingNo or nil
          mon.nuzlockeRawSpecies = glitch.isGlitch and rawSpecies or nil
          Identity.setPokemonOrigin(mon, origin)
          Identity.baselineAdd(mon, origin)
      end

      -- A current/future engine path may report the same acquisition through
      -- both the script command wrapper and pokemon.received. Persistent ID is
      -- authoritative; fingerprint is the pre-ID compatibility fallback.
      -- Dedupe must still hydrate the concrete mon: Catch Info reads its
      -- provenance fields while Tracker/count reads this persistent log.
      for _, existing in ipairs(log[area]) do
          if type(existing) == "table" then
              if monId and existing.pokemonId
                  and tostring(existing.pokemonId) == tostring(monId) then
                  hydrateRegisteredMon(existing)
                  return true
              end
              if not monId and mon and existing.fingerprint
                  and existing.fingerprint == Identity.fingerprint(mon) then
                  hydrateRegisteredMon(existing)
                  return true
              end
          end
      end

      table.insert(log[area], {
          species       = species,
          rawSpecies    = glitch.isGlitch and rawSpecies or nil,
          glitch        = glitch.isGlitch or nil,
          missingNo     = glitch.missingNo or nil,
          pokemonId     = monId,
          fingerprint   = mon and Identity.fingerprint(mon) or nil,
          isShiny       = mon and Identity.isShiny(mon),
          encounterType = encounterType,
          consumedArea = consume,
          encounterMethod = opts.encounterMethod,
          encounterTime = opts.encounterTime,
          roamerSpecies = opts.roamerSpecies,
          eggCreatedLocation = opts.eggCreatedLocation,
          eggHatchLocation = opts.eggHatchLocation,
          provenance = origin,
      })
      mod.save:set("tracker_log", log)
      if consume then markCaught(area, species) end
      if mon then
          mon.catchLocation = area
          mon.encounterType = encounterType
          mon.nuzlockeEncounterMethod = opts.encounterMethod
          mon.nuzlockeEncounterTime = opts.encounterTime
          mon.nuzlockeRoamerSpecies = opts.roamerSpecies
          mon.eggCreatedLocation = opts.eggCreatedLocation or mon.eggCreatedLocation
          mon.eggHatchLocation = opts.eggHatchLocation or mon.eggHatchLocation
          mon.nuzlockeDead  = false
          mon.nuzlockeTrackerRegistered = true
          mon.nuzlockeGlitch = glitch.isGlitch or nil
          mon.nuzlockeMissingNo = glitch.missingNo or nil
          mon.nuzlockeRawSpecies = glitch.isGlitch and rawSpecies or nil
          Identity.setPokemonOrigin(mon, origin)
          Identity.baselineAdd(mon, origin)
      end

      local history = mod.save:get("nuzlocke_history", {})
      if type(history) ~= "table" then history = {} end
      table.insert(history, {
          name          = (mon and mon.nickname) or glitch.label or species,
          species       = species,
          rawSpecies    = glitch.isGlitch and rawSpecies or nil,
          glitch        = glitch.isGlitch or nil,
          missingNo     = glitch.missingNo or nil,
          pokemonId     = monId,
          catchLocation = area,
          encounterType = encounterType,
          encounterMethod = opts.encounterMethod,
          encounterTime = opts.encounterTime,
          roamerSpecies = opts.roamerSpecies,
          eggCreatedLocation = opts.eggCreatedLocation,
          eggHatchLocation = opts.eggHatchLocation,
          provenance = origin,
          consumedArea = consume,
          status        = "ALIVE",
      })
      mod.save:set("nuzlocke_history", history)
      return true
  end

  -- REVIEWED: acquisition registration intentionally stays at its proven
  -- transaction point. Mandatory naming may finish afterward, so synchronize
  -- only the matching history snapshot by persistent Pokemon identity rather
  -- than moving tracker/area registration across a naming-screen yield.
  mod.exports.__beta26.syncHistoryNickname = function(mon)
      if type(mon) ~= "table" then return false end
      local nickname = tostring(mon.nickname or "")
      if not nickname:find("%S") then return false end
      local monId = Identity.pokemonIdentity(mon)
          or Identity.ensurePokemonIdentity(mon, currentSave,
              mon.nuzlockeOrigin or "NORMAL")
      if monId == nil then return false end

      local history = mod.save:get("nuzlocke_history", {})
      if type(history) ~= "table" then return false end
      local changed = false
      for _, record in ipairs(history) do
          if type(record) == "table" and record.pokemonId ~= nil
              and tostring(record.pokemonId) == tostring(monId)
              and record.status == "ALIVE" and record.name ~= nickname then
              record.name = nickname
              changed = true
          end
      end
      if changed then mod.save:set("nuzlocke_history", history) end
      return changed
  end

  ---------------------------------------------------------------------
  -- POKEMON.RECEIVED  —  starters, gifts, trades
  --
  -- ev fields (varies by engine build):
  --   ev.mon / ev.species   — the Pokemon received
  --   ev.source             — "starter" | "gift" | "trade" | "fossil" | "prize"
  --   ev.location / ev.mapId / ev.area — where it was received
  --   ev.game               — game reference
  --
  -- Priority:
  --   1. Starter        → always PALLET_TOWN, bypasses town_catches.
  --   2. Gift (allowed) → area from GIFT_LOCATIONS or current map.
  --   3. Gift (blocked) → native transaction is rejected before mutation.
  --   4. Trade (allowed)→ area from TRADE_DATA or current map.
  --   5. Trade (blocked)→ native transaction is rejected before exchange.
  ---------------------------------------------------------------------
  mod.exports.__beta26.isWonderTradeEvent = function(ev, source)
      if type(ev) ~= "table" then return false end
      if ev.wonderTrade == true or ev.isWonderTrade == true or ev.wonder_trade == true then return true end
      source = tostring(source or ""):lower():gsub("[%s%-]", "_")
      return source == "wonder_trade" or source == "wondertrade" or source == "wt"
  end

  -- Wonderlocke is intentionally dormant. Keep the public adapter so Wonder
  -- Trade mods can probe the compatibility surface safely, but never mutate a
  -- Pokemon or transaction until the feature is completed and re-enabled.
  if mod.exports.nuzlocke_compat then
      mod.exports.nuzlocke_compat.handleWonderTrade = function(game, mon, area, providerId)
          return false
      end
  end

  mod.events:on("pokemon.received", function(ev)
      if not ev then return end
      local game    = ev.game or currentGame
      local mon     = ev.mon
      local rawSpecies = ev.species or (mon and mon.species)
      if rawSpecies == nil or rawSpecies == "" then return end
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, rawSpecies)
      local species = glitch.key

      -- Post-transaction events may be emitted by external mods. Preserve the
      -- received object and annotate it; native command wrappers perform any
      -- configured rejection before mutation.
      if mon and glitch.isGlitch then
          mon.nuzlockeGlitch = true
          mon.nuzlockeMissingNo = glitch.missingNo or nil
          mon.nuzlockeRawSpecies = rawSpecies
      end

      local source = tostring(ev.source or ""):lower()

      local rawLoc = ev.location or ev.mapId or ev.area
          or (game and game.overworld and game.overworld.map
              and game.overworld.map.id)
          or (game and game.save and game.save.player
              and game.save.player.map)
      local loc = routeKey(rawLoc) or "UNKNOWN"

      -- Gold's starter may be randomized to any valid species, so species-family
      -- heuristics cannot identify it after acquisition. The Gen 2 transaction
      -- wrapper normally registers it synchronously; this event fallback covers
      -- engine/provider paths that emit only pokemon.received. A first owned mon
      -- explicitly reported as a starter is always New Bark Town.
      if getGameVersion() == "GOLD" and source == "starter" then
          local party = game and game.save and game.save.party or {}
          if #party <= 1 then
              mod.exports.__beta26.registerStarterCatch(species, mon)
              return
          end
      end

      -- 1. Starter (explicit flag or species+location heuristic). Some
      -- current R/B/Y event paths report Oak's Lab rather than PALLET_TOWN,
      -- and may omit source="starter". Canonicalize those opening acquisitions
      -- immediately so they cannot create a second non-Pallet encounter row.
      local locText = tostring(loc or rawLoc or ""):upper()
      local isStarter = mod.exports.__beta26.isOpeningStarterAcquisition(
          game, species, source, locText, mon)
      -- Yellow's vanilla Pikachu fallback is retained for historical/provider
      -- event shapes; Random Starter species are now covered by the same
      -- provenance-based resolver above.
      local isYellowPikachu = (getGameVersion() == "YELLOW")
          and species == "PIKACHU"
          and (source == "starter"
              or (source == ""
                  and (loc == "PALLET_TOWN" or loc == "UNKNOWN")))

      if isStarter or isYellowPikachu then
          -- Nuzlocke must be active for tracking; but we still register
          -- even if the master toggle is off so the slot stays coherent.
          mod.exports.__beta26.registerStarterCatch(species, mon)
          return
      end

      -- Only enforce gifts/trades when Nuzlocke is active.
      if not active(game, nil) then return end

      local giftLookup  = mod.exports.__beta26.buildGiftLookup()
      local tradeLookup = mod.exports.__beta26.buildTradeLookup()

      -- Fallback/external acquisition events do not always pass through the
      -- native Commands.give_pokemon / Commands.trade wrappers. Prefer an
      -- explicit event source when supplied; only use species lookup as a
      -- compatibility fallback when source is absent so a normal acquisition
      -- cannot be reclassified merely because that species is also gift/trade
      -- eligible somewhere else in the game.
      local function sourceLookupMatches(lookup, kind)
          local expected = lookup[species]
          if expected == nil then return false end
          if loc == "UNKNOWN" then
              return mod.exports.__beta26.deterministicSourceFallback(kind, species)
          end
          return (routeKey(expected) or tostring(expected):upper()) == loc
      end
      local inferredGift = source == "" and sourceLookupMatches(giftLookup, "gift")
      local inferredTrade = source == "" and sourceLookupMatches(tradeLookup, "trade")
      local isGift = source == "gift" or source == "fossil"
          or source == "prize" or inferredGift
      local isTrade = source == "trade" or inferredTrade

      -- Wonderlocke is WIP. Wonder Trade transactions belong entirely to the
      -- provider mod for now: do not block them, remove the received Pokemon,
      -- consume an encounter slot, or write Wonderlocke provenance.
      if mod.exports.__beta26.wonderlockeWip
          and mod.exports.__beta26.isWonderTradeEvent(ev, source) then
          return
      end

      -- 2-3. Gift
      if isGift and not isTrade then
          local giftArea = loc ~= "UNKNOWN" and loc or giftLookup[species] or loc
          if mon and mon.nuzlockeTrackerRegistered == true then return end
          local denied = specialAcquisitionDenied(game, species, giftArea, "gift")
          if denied then
              -- Never delete a Pokemon here. pokemon.received is post-transaction
              -- in some engine/mod paths, so rollback would be unsafe. Native
              -- give_pokemon is rejected before mutation by the command wrapper.
              if mon then mon.nuzlockeInvalidAcquisition = denied end
              worldMechanic(game, "gift_post_denied:" .. tostring(species),
                  "This gift conflicts with your Nuzlocke rules.",
                  "Gift received through an external path.\nReview your rules before using it.",
                  "A mod bypassed the normal gift transaction gate.\nThe Pokemon was preserved instead of deleting data.")
              return
          end
          mod.exports.__beta26.registerSpecialCatch(species, giftArea, "gift", mon)
          return
      end

      -- 4-5. Trade
      if isTrade then
          local tradeArea = loc ~= "UNKNOWN" and loc or tradeLookup[species] or loc
          if mon and mon.nuzlockeTrackerRegistered == true then return end
          local denied = specialAcquisitionDenied(game, species, tradeArea, "trade")
          if denied then
              -- Same safety rule as gifts: never attempt a destructive rollback
              -- after another mod/engine has already completed the exchange.
              if mon then mon.nuzlockeInvalidAcquisition = denied end
              worldMechanic(game, "trade_post_denied:" .. tostring(species),
                  "This trade conflicts with your Nuzlocke rules.",
                  "Trade completed through an external path.\nThe Pokemon was preserved instead of risking data loss.",
                  "A mod bypassed the normal trade gate.\nNo destructive rollback was attempted.")
              return
          end
          mod.exports.__beta26.registerSpecialCatch(species, tradeArea, "trade", mon)
      end
  end)

  ---------------------------------------------------------------------
  -- CATCH RULE ENFORCEMENT
  ---------------------------------------------------------------------
  mod.exports.__beta26.pokemonFamily = function(game, species)
      if mod.exports.__beta26.getGlitchSpeciesInfo(game, species).isGlitch then
          return {}
      end
      local found, pending = {}, { species }
      local data = game and game.data and game.data.pokemon or {}
      while #pending > 0 do
          local id = table.remove(pending)
          if id and not found[id] then
              found[id] = true
              local def = data[id]
              for _, evo in ipairs((def and def.evolutions) or {}) do
                  if evo and evo.species then pending[#pending + 1] = evo.species end
              end
              for parent, parentDef in pairs(data) do
                  for _, evo in ipairs((parentDef and parentDef.evolutions) or {}) do
                      if evo and evo.species == id then
                          pending[#pending + 1] = parent
                      end
                  end
              end
          end
      end
      return found
  end

  mod.exports.__beta26.caughtSpeciesSet = function(game)
      local caught = {}

      -- Tracker history is authoritative for "previously caught", so a dead,
      -- boxed-out, released, or traded-away Pokemon still counts for Dupes.
      for area, entries in pairs(trackerLog()) do
          if area ~= "__LEGACY__" and type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  local sp = type(entry) == "table"
                      and tostring(entry.species or ""):upper() or ""
                  if sp ~= "" then caught[sp] = true end
              end
          end
      end

      -- Current owned Pokemon are a safety net for imported/modded saves whose
      -- tracker reconstruction has not run yet.
      for _, mon in ipairs(Identity.allCurrentMons(game and game.save or {})) do
          local sp = type(mon) == "table"
              and tostring(mon.species or ""):upper() or ""
          if sp ~= "" then caught[sp] = true end
      end

      return caught
  end

  mod.exports.__beta26.dupesMode = function()
      local value = mod.save:get("dupes_mode", defaultRuleValue("dupes_mode"))
      if type(value) == "boolean" then return value and 2 or 0 end
      return math.max(0, math.min(2, math.floor(tonumber(value) or 0)))
  end

  mod.exports.__beta26.isDuplicateSpecies = function(game, species)
      local mode = mod.exports.__beta26.dupesMode()
      if mode <= 0 then return false end

      -- Glitch identities are not stable evolution-family members. Treat each
      -- allowed glitch encounter independently instead of traversing missing or
      -- malformed evolution data.
      if mod.exports.__beta26.getGlitchSpeciesInfo(game, species).isGlitch then
          return false
      end

      species = tostring(species or ""):upper()
      if species == "" then return false end

      local caught = mod.exports.__beta26.caughtSpeciesSet(game)
      if mode == 1 then
          return caught[species] == true
      end

      local members = mod.exports.__beta26.pokemonFamily(game, species)
      for caughtSpecies in pairs(caught) do
          if members[caughtSpecies] == true then return true end
      end
      return false
  end

  -- Shared ordinary-clause conflict used both by the Ball legality check and
  -- by successful-catch accounting. A finite Shiny Clause allowance may only
  -- be spent when this exact helper says the catch genuinely needed an area,
  -- failed-state, or Dupes exception. This lives after mod.exports.__beta26.isDuplicateSpecies so
  -- the closure binds the actual local Dupes classifier rather than a global.
  mod.exports.__beta26.catchClauseConflict = function(game, battle, species)
      local key = areaKey(game, battle)
      local slotConflict = mod.exports.__beta26.encounterSlotConflict(
          game, key, true)
      if slotConflict ~= nil then return slotConflict end
      if mod.exports.__beta26.isDuplicateSpecies(game, species) then return "dupes" end
      return nil
  end

  ---------------------------------------------------------------------
  -- FAILED ENCOUNTER STATE
  -- A failed eligible wild encounter consumes the area's encounter slot.
  -- Dupes encounters do not consume the slot while Dupes Clause is ON.
  ---------------------------------------------------------------------
  mod.exports.__beta26.encounterStates = function()
      local states = mod.save:get("encounter_states")
      if type(states) ~= "table" then
          states = {}
          mod.save:set("encounter_states", states)
      end
      return states
  end

  getEncounterState = function(key)
      if not key then return nil end
      return mod.exports.__beta26.encounterStates()[key]
  end

  mod.exports.__beta26.markEncounterFailed = function(key, species, encounterType, sourceMapId,
      provenance)
      local policyGame = currentGame or mod.game
      if not mod.exports.__beta26.shouldEnforceNuzlocke(policyGame, nil) then return end
      if not key or mod.save:get("failed_encounter", true) ~= true then return end
      key = registerArea(key)
      if not isTrackedArea(key) then return end
      provenance = type(provenance) == "table" and provenance or {}
      local states = mod.exports.__beta26.encounterStates()

      -- 2.4.57: successful consumed-catch evidence is monotonic. A delayed
      -- battle-ended/provider callback must never downgrade an area that was
      -- already recorded CAUGHT into FAILED.
      local existing = states[key]
      if caughtAreas()[key] ~= nil
          or (type(existing) == "table" and existing.status == "CAUGHT") then
          return
      end
      local existingLog = trackerLog()[key]
      if type(existingLog) == "table" then
          for _, entry in ipairs(existingLog) do
              if type(entry) == "table" and entry.species
                  and entry.consumedArea ~= false then
                  return
              end
          end
      end
      local physical = routeKey(sourceMapId)
          or routeKey(provenance.encounterMapId) or key
      local record = {
          status = "FAILED", species = species,
          encounterType = encounterType or "wild", encounterMapId = physical,
          encounterMethod = provenance.encounterMethod,
          encounterTime = provenance.encounterTime,
          roamerSpecies = provenance.roamerSpecies,
          eggCreatedLocation = provenance.eggCreatedLocation,
          eggHatchLocation = provenance.eggHatchLocation,
      }
      states[key] = record
      mod.save:set("encounter_states", states)
      local ledger = mod.save:get("encounter_area_state_ledger", {})
      if type(ledger) ~= "table" then ledger = {} end
      local ledgerKey = mod.exports.__beta26.goldEncounterLedgerKey(
          currentGame or mod.game, physical, record) or physical
      ledger[ledgerKey] = record
      mod.save:set("encounter_area_state_ledger", ledger)
      mod.save:set("last_failed_encounter", {
          area = key, encounterMapId = physical, species = species,
          encounterType = record.encounterType,
          encounterMethod = record.encounterMethod,
          encounterTime = record.encounterTime,
          roamerSpecies = record.roamerSpecies,
      })
  end

  mod.exports.__beta26.markEncounterCaught = function(key, species, encounterType, sourceMapId,
      consumedArea, provenance)
      if not key then return end
      key = registerArea(key)
      if not isTrackedArea(key) then return end
      provenance = type(provenance) == "table" and provenance or {}
      local states = mod.exports.__beta26.encounterStates()
      local physical = routeKey(sourceMapId)
          or routeKey(provenance.encounterMapId) or key
      local record = {
          status = "CAUGHT", species = species,
          encounterType = encounterType or "wild", encounterMapId = physical,
          consumedArea = consumedArea ~= false,
          encounterMethod = provenance.encounterMethod,
          encounterTime = provenance.encounterTime,
          roamerSpecies = provenance.roamerSpecies,
          eggCreatedLocation = provenance.eggCreatedLocation,
          eggHatchLocation = provenance.eggHatchLocation,
      }
      states[key] = record
      mod.save:set("encounter_states", states)
      local ledger = mod.save:get("encounter_area_state_ledger", {})
      if type(ledger) ~= "table" then ledger = {} end
      local ledgerKey = mod.exports.__beta26.goldEncounterLedgerKey(
          currentGame or mod.game, physical, record) or physical
      ledger[ledgerKey] = record
      mod.save:set("encounter_area_state_ledger", ledger)
  end

  -- 2.4.57 CAPTURE LEDGER INTEGRITY
  -- Successful consumed-catch evidence is stronger than FAILED state. Keep
  -- tracker_log, caught_areas, encounter_states, and the physical state ledger
  -- mutually consistent without inventing catches from party/species guesses.
  mod.exports.__beta26.reconcileEncounterCaptureState = function()
      local log = trackerLog()
      local areas = caughtAreas()
      local states = mod.exports.__beta26.encounterStates()
      local ledger = mod.save:get("encounter_area_state_ledger", {})
      if type(ledger) ~= "table" then ledger = {} end
      local changed = false

      local function caughtRecord(key, species, source)
          local existing = states[key]
          if type(existing) == "table" and existing.status == "CAUGHT" then
              if existing.species == nil and species ~= nil then
                  existing.species = species
                  changed = true
              end
              return existing
          end
          local record = {
              status = "CAUGHT",
              species = species,
              encounterType = type(source) == "table"
                  and (source.encounterType or "wild") or "wild",
              encounterMapId = type(source) == "table"
                  and (routeKey(source.encounterMapId) or key) or key,
              consumedArea = true,
              encounterMethod = type(source) == "table"
                  and source.encounterMethod or nil,
              encounterTime = type(source) == "table"
                  and source.encounterTime or nil,
              roamerSpecies = type(source) == "table"
                  and source.roamerSpecies or nil,
              eggCreatedLocation = type(source) == "table"
                  and source.eggCreatedLocation or nil,
              eggHatchLocation = type(source) == "table"
                  and source.eggHatchLocation or nil,
              reconciledCapture = true,
          }
          states[key] = record
          changed = true
          return record
      end

      -- Tracker rows are strongest: they are written only after a successful
      -- acquisition. Exempt catches (consumedArea=false) intentionally do not
      -- claim the area's one-per-area slot.
      for key, catches in pairs(log) do
          if key ~= "__LEGACY__" and type(catches) == "table" then
              for _, entry in ipairs(catches) do
                  if type(entry) == "table" and entry.species
                      and entry.consumedArea ~= false then
                      if areas[key] == nil then
                          areas[key] = entry.species
                          changed = true
                      end
                      local record = caughtRecord(key, entry.species, entry)
                      local physical = routeKey(record.encounterMapId) or key
                      local ledgerKey =
                          mod.exports.__beta26.goldEncounterLedgerKey(
                              currentGame or mod.game, physical, record)
                          or physical
                      local old = ledger[ledgerKey]
                      if type(old) ~= "table" or old.status ~= "CAUGHT" then
                          ledger[ledgerKey] = record
                          changed = true
                      end
                      break
                  end
              end
          end
      end

      -- caught_areas is older successful-catch evidence used by legacy saves.
      -- It may repair a conflicting FAILED state, but it never creates tracker
      -- history and never guesses provenance beyond the logical area.
      for key, species in pairs(areas) do
          if key ~= "__LEGACY__" and species ~= nil then
              local state = states[key]
              if type(state) ~= "table" or state.status ~= "CAUGHT" then
                  local record = caughtRecord(key, species, state)
                  local physical = routeKey(record.encounterMapId) or key
                  local ledgerKey =
                      mod.exports.__beta26.goldEncounterLedgerKey(
                          currentGame or mod.game, physical, record)
                      or physical
                  local old = ledger[ledgerKey]
                  if type(old) ~= "table" or old.status ~= "CAUGHT" then
                      ledger[ledgerKey] = record
                      changed = true
                  end
              end
          end
      end

      if changed then
          mod.save:set("caught_areas", areas)
          mod.save:set("encounter_states", states)
          mod.save:set("encounter_area_state_ledger", ledger)
      end
      return changed
  end

  -- Rebuild the active encounter views from immutable physical-map
  -- provenance. This is called on load and immediately after either split
  -- selector changes. It never deletes catch rows: COMMON separates them and
  -- OFF groups them back under the parent while preserving every row.
  mod.exports.__beta26.reprojectEncounterAreas = function()
      -- Reconcile successful-catch evidence before any projection can choose
      -- a representative state for collapsed/split areas.
      pcall(mod.exports.__beta26.reconcileEncounterCaptureState)

      -- Legacy selector translation now runs in the coordinator's semantic
      -- phase. Projection has one job: deterministically rebuild logical views
      -- from preserved physical provenance without also mutating rule schema.
      local oldLog = trackerLog()
      local newLog = {}

      -- REVIEWED: split families can collapse multiple physical buckets into
      -- one logical area. Lua pairs() order is deliberately unspecified, so
      -- collect and sort the physical/source keys before projection. This
      -- makes the representative CAUGHT row/state stable across reloads and
      -- repeated split toggles while preserving each bucket's ipairs order.
      local function orderedKeys(tbl)
          local keys = {}
          for key in pairs(tbl or {}) do keys[#keys + 1] = key end
          table.sort(keys, function(a, b)
              local ar = routeKey(a) or tostring(a or "")
              local br = routeKey(b) or tostring(b or "")
              if ar == br then return tostring(a) < tostring(b) end
              return tostring(ar) < tostring(br)
          end)
          return keys
      end

      for _, oldKey in ipairs(orderedKeys(oldLog)) do
          local entries = oldLog[oldKey]
          if oldKey == "__LEGACY__" then
              newLog[oldKey] = entries
          elseif type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  if type(entry) == "table" then
                      local physical = routeKey(entry.encounterMapId)
                      local normalizedOld = routeKey(oldKey)
                      if not physical then
                          physical = normalizedOld
                          if mod.exports.__beta26.splitFamilyFor(normalizedOld) then
                              entry.encounterMapId = normalizedOld
                          end
                      end
                      local base = mod.exports.__beta26.projectEncounterArea(
                          physical) or normalizedOld or oldKey
                      local target = mod.exports.__beta26.projectGoldEncounterArea(
                          currentGame or mod.game, base, entry) or base
                      newLog[target] = newLog[target] or {}
                      newLog[target][#newLog[target] + 1] = entry
                  end
              end
          else
              newLog[oldKey] = entries
          end
      end
      mod.save:set("tracker_log", newLog)

      local oldStates = mod.exports.__beta26.encounterStates()
      local stateLedger = mod.save:get("encounter_area_state_ledger", {})
      if type(stateLedger) ~= "table" then stateLedger = {} end
      for _, oldKey in ipairs(orderedKeys(oldStates)) do
          local state = oldStates[oldKey]
          if type(state) == "table" then
              local physical = routeKey(state.encounterMapId) or routeKey(oldKey)
              if physical then
                  local ledgerKey = mod.exports.__beta26.goldEncounterLedgerKey(
                      currentGame or mod.game, physical, state) or physical
                  if stateLedger[ledgerKey] == nil
                      or state.projectedFromSplits ~= true then
                      local copy = {}
                      for k, v in pairs(state) do copy[k] = v end
                      copy.encounterMapId = physical
                      copy.projectedFromSplits = nil
                      stateLedger[ledgerKey] = copy
                  end
              end
          end
      end

      local newStates = {}
      for _, ledgerKey in ipairs(orderedKeys(stateLedger)) do
          local state = stateLedger[ledgerKey]
          if type(state) == "table" then
              local physical = routeKey(state.encounterMapId) or routeKey(ledgerKey)
              local base = mod.exports.__beta26.projectEncounterArea(physical)
                  or physical
              local target = mod.exports.__beta26.projectGoldEncounterArea(
                  currentGame or mod.game, base, state) or base
              if target then
                  local existing = newStates[target]
                  local existingConsumes = existing and
                      (existing.status == "FAILED"
                          or existing.consumedArea ~= false)
                  local stateConsumes = state.status == "FAILED"
                      or state.consumedArea ~= false
                  if not existing or (not existingConsumes and stateConsumes)
                      or (existingConsumes == stateConsumes
                          and existing.status ~= "CAUGHT"
                          and state.status == "CAUGHT") then
                      local copy = {}
                      for k, v in pairs(state) do copy[k] = v end
                      copy.encounterMapId = routeKey(physical) or physical
                      copy.projectedFromSplits = target ~= copy.encounterMapId
                      newStates[target] = copy
                  end
              end
          end
      end
      mod.save:set("encounter_area_state_ledger", stateLedger)
      mod.save:set("encounter_states", newStates)

      local oldCaught = caughtAreas()
      local covered = {}
      for key in pairs(oldLog) do covered[key] = true end
      for key in pairs(oldStates) do covered[key] = true end
      local newCaught = {}
      for key, entries in pairs(newLog) do
          if key ~= "__LEGACY__" and type(entries) == "table" then
              for _, entry in ipairs(entries) do
                  if type(entry) == "table" and entry.species
                      and entry.consumedArea ~= false then
                      newCaught[key] = entry.species
                      break
                  end
              end
          end
      end
      for key, state in pairs(newStates) do
          if newCaught[key] == nil and type(state) == "table"
              and state.status == "CAUGHT" and state.species
              and state.consumedArea ~= false then
              newCaught[key] = state.species
          end
      end
      for oldKey, species in pairs(oldCaught) do
          if oldKey == "__LEGACY__" then
              newCaught[oldKey] = species
          elseif not covered[oldKey] then
              local target = mod.exports.__beta26.projectEncounterArea(oldKey)
                  or routeKey(oldKey) or oldKey
              if newCaught[target] == nil then newCaught[target] = species end
          end
      end
      mod.save:set("caught_areas", newCaught)

      local oldVisited = visitedAreas()
      local visitLedger = mod.save:get("encounter_visited_map_ids", {})
      if type(visitLedger) ~= "table" then visitLedger = {} end
      for key, value in pairs(oldVisited) do
          if value == true and visitLedger[key] == nil then
              local projectedParent = false
              for _, family in pairs(mod.exports.__beta26.encounterSplitAreas) do
                  if key == family.parent then
                      for member in pairs(family.members) do
                          if visitLedger[member] == true then
                              projectedParent = true
                              break
                          end
                      end
                  end
                  if projectedParent then break end
              end
              if not projectedParent then visitLedger[key] = true end
          end
      end
      local newVisited = {}
      for physical, value in pairs(visitLedger) do
          if value == true then
              local target = mod.exports.__beta26.projectEncounterArea(physical)
                  or routeKey(physical)
              if target then newVisited[target] = true end
          end
      end
      mod.save:set("encounter_visited_map_ids", visitLedger)
      mod.save:set("visited_areas", newVisited)

      -- Keep Catch Info and history aligned with the same live projection.
      -- The physical map field remains stable, while catchLocation is the
      -- current player-facing area name/key used throughout existing UI.
      for _, mon in ipairs(Identity.allCurrentMons(
          currentGame and currentGame.save or currentSave or {})) do
          if type(mon) == "table" then
              local physical = routeKey(mon.nuzlockeEncounterMapId)
              local oldLocation = routeKey(mon.catchLocation)
              if not physical
                  and mod.exports.__beta26.splitFamilyFor(oldLocation) then
                  physical = oldLocation
                  mon.nuzlockeEncounterMapId = physical
              end
              if physical then
                  local base = mod.exports.__beta26.projectEncounterArea(physical)
                      or mon.catchLocation
                  mon.catchLocation = mod.exports.__beta26.projectGoldEncounterArea(
                      currentGame or mod.game, base, mon) or base
              end
          end
      end
      local history = mod.save:get("nuzlocke_history", {})
      if type(history) == "table" then
          for _, row in ipairs(history) do
              if type(row) == "table" then
                  local physical = routeKey(row.encounterMapId)
                  local oldLocation = routeKey(row.catchLocation)
                  if not physical
                      and mod.exports.__beta26.splitFamilyFor(oldLocation) then
                      physical = oldLocation
                      row.encounterMapId = physical
                  end
                  if physical then
                      local base = mod.exports.__beta26.projectEncounterArea(physical)
                          or row.catchLocation
                      row.catchLocation = mod.exports.__beta26.projectGoldEncounterArea(
                          currentGame or mod.game, base, row) or base
                  end
              end
          end
          mod.save:set("nuzlocke_history", history)
      end
      local lastFailed = mod.save:get("last_failed_encounter", {})
      if type(lastFailed) == "table" then
          local physical = routeKey(lastFailed.encounterMapId)
          if physical then
              local base = mod.exports.__beta26.projectEncounterArea(physical)
                  or lastFailed.area
              lastFailed.area = mod.exports.__beta26.projectGoldEncounterArea(
                  currentGame or mod.game, base, lastFailed) or base
              mod.save:set("last_failed_encounter", lastFailed)
          end
      end
      mod.save:set("encounter_projection_signature",
          tostring(mod.exports.__beta26.routeSplitActive("route_2_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_10_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_20_split") and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(1, math.floor(tonumber(
              mod.save:get("mt_moon_splits", 0)) or 0)))) .. ":"
          .. tostring(math.max(0, math.min(1, math.floor(tonumber(
              mod.save:get("safari_zone_splits", 0)) or 0)))) .. ":"
          .. tostring(mod.save:get("gold_time_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_headbutt_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_roamer_clause", false) == true and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(2, math.floor(tonumber(
              mod.save:get("gold_bug_contest_mode", 0)) or 0))))
      )
      return true
  end

  mod.exports.__beta26.ensureEncounterProjection = function()
      local signature = tostring(mod.exports.__beta26.routeSplitActive("route_2_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_10_split") and 1 or 0) .. ":"
          .. tostring(mod.exports.__beta26.routeSplitActive("route_20_split") and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(1, math.floor(tonumber(
          mod.save:get("mt_moon_splits", 0)) or 0)))) .. ":"
          .. tostring(math.max(0, math.min(1, math.floor(tonumber(
              mod.save:get("safari_zone_splits", 0)) or 0)))) .. ":"
          .. tostring(mod.save:get("gold_time_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_headbutt_split", false) == true and 1 or 0) .. ":"
          .. tostring(mod.save:get("gold_roamer_clause", false) == true and 1 or 0) .. ":"
          .. tostring(math.max(0, math.min(2, math.floor(tonumber(
              mod.save:get("gold_bug_contest_mode", 0)) or 0))))
      if mod.save:get("encounter_projection_signature", nil) ~= signature then
          return mod.exports.__beta26.reprojectEncounterAreas()
      end
      return false
  end

  mod.exports.__beta26.registerSaveUpgradeStep("projection",
      "encounter_area_projection", function()
          mod.exports.__beta26.reprojectEncounterAreas()
          return true
      end)
  -- game.ready remains a runtime synchronization seam, not a migration path:
  -- it handles title/new-game/adopted-save lifecycle cases after the canonical
  -- save-loaded upgrade pipeline has already done its ordered work.
  mod.events:on("game.ready", function()
      pcall(mod.exports.__beta26.reprojectEncounterAreas)
  end)

  -- Persist a self-consistent capture ledger. This does not create new catch
  -- history; it only makes already-recorded successful consumed catches
  -- monotonic across save/reload and provider/event ordering.
  mod.events:on("save.writing", function()
      pcall(mod.exports.__beta26.reconcileEncounterCaptureState)
  end)

  -- BETA.26 ENCOUNTER ARMING / SOFT START
  -- Keep this helper namespace on the existing beta export table instead of
  -- adding more long-lived locals to the main mod chunk. This is intentionally
  -- initialization-safe: the prior B5 feature batch caused the entire mod to
  -- disappear before title/start-menu hooks became usable on Blue and Gold.
  ---------------------------------------------------------------------
  mod.exports.__beta26.tableContainsOwnedBall = function(game, tbl, seen)
      if type(tbl) ~= "table" then return false end
      seen = seen or {}
      if seen[tbl] then return false end
      seen[tbl] = true
      for key, value in pairs(tbl) do
          if type(value) == "number" and value > 0 then
              local ok, result = pcall(ItemPolicy.isBall,
                  game and game.data, key, nil)
              if ok and result == true then
                  local okBlocked, blocked = pcall(ItemPolicy.ballUseBlocked,
                      game and game.data, key, nil, true)
                  if not okBlocked or blocked ~= true then return true end
              end
          elseif type(value) == "table"
              and mod.exports.__beta26.tableContainsOwnedBall(game, value, seen) then
              return true
          end
      end
      return false
  end

  mod.exports.__beta26.hasLegacyEncounterEvidence = function()
      -- Pallet Town's starter is established before the player owns Balls and
      -- MUST NOT arm Soft Start by itself. Only meaningful non-starter route
      -- history reconstructs an older save as already armed.
      -- Repair the old B7 Oak/Lab starter duplicate before using history as
      -- evidence that encounter rules should already be armed.
      mod.exports.__beta26.cleanupStarterDuplicate()

      local areas = mod.save:get("caught_areas", nil)
      if type(areas) == "table" then
          for key, value in pairs(areas) do
              if key ~= "PALLET_TOWN" and value ~= nil then
                  local k = tostring(key or ""):upper()
                  local sp = tostring(value or ""):upper()
                  local starter = sp == "BULBASAUR" or sp == "CHARMANDER"
                      or sp == "SQUIRTLE" or sp == "PIKACHU"
                  if not (starter and (k:find("OAK", 1, true)
                      or k:find("LAB", 1, true))) then
                      return true
                  end
              end
          end
      end
      local states = mod.save:get("encounter_states", nil)
      if type(states) == "table" then
          for key, state in pairs(states) do
              if key ~= "PALLET_TOWN" and type(state) == "table"
                  and (state.status == "FAILED" or state.status == "CAUGHT") then
                  return true
              end
          end
      end
      local log = mod.save:get("tracker_log", nil)
      if type(log) == "table" then
          for key, entries in pairs(log) do
              if key ~= "PALLET_TOWN" and key ~= "__LEGACY__"
                  and type(entries) == "table" and #entries > 0 then
                  local k = tostring(key or ""):upper()
                  local onlyStarter = true
                  for _, entry in ipairs(entries) do
                      local sp = tostring(entry and entry.species or ""):upper()
                      if sp ~= "BULBASAUR" and sp ~= "CHARMANDER"
                          and sp ~= "SQUIRTLE" and sp ~= "PIKACHU" then
                          onlyStarter = false
                          break
                      end
                  end
                  if not (onlyStarter and (k:find("OAK", 1, true)
                      or k:find("LAB", 1, true))) then
                      return true
                  end
              end
          end
      end
      return false
  end

  mod.exports.__beta26.clearPreArmEncounterState = function()
      -- Pre-Ball encounters are intentionally invisible to the route ledger.
      -- Clear only transient encounter-state rows; successful catch history and
      -- the starter tracker row live in separate tables and are preserved.
      mod.save:set("encounter_states", {})
  end

  mod.exports.__beta26.encounterRulesArmed = function(game)
      if not mod.exports.__beta26.canWriteNuzlockeSave(game) then return false end
      if mod.save:get("nuzlocke_encounters_armed", false) == true then return true end

      -- Compatibility for older saves: genuine route history means the run
      -- already passed the first-Ball boundary. A starter-only Pallet row does
      -- not count as evidence and leaves a fresh run unarmed.
      if mod.exports.__beta26.hasLegacyEncounterEvidence() then
          mod.save:set("nuzlocke_encounters_armed", true)
          return true
      end

      local save = game and game.save
      if save and (mod.exports.__beta26.tableContainsOwnedBall(game, save.inventory)
          or mod.exports.__beta26.tableContainsOwnedBall(game, save.pcItems)
          or mod.exports.__beta26.tableContainsOwnedBall(game, save.bag)
          or mod.exports.__beta26.tableContainsOwnedBall(game, save.pockets)) then
          mod.exports.__beta26.clearPreArmEncounterState()
          mod.save:set("nuzlocke_encounters_armed", true)
          local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
              game, "encounter_armed")
          worldMechanic(game, "encounter_armed", t1, t2, t3)
          return true
      end
      return false
  end

  mod.exports.__beta26.armEncounterRulesNow = function(game)
      if not mod.exports.__beta26.canWriteNuzlockeSave(game) then return false end
      if mod.save:get("nuzlocke_encounters_armed", false) ~= true then
          mod.exports.__beta26.clearPreArmEncounterState()
          mod.save:set("nuzlocke_encounters_armed", true)
      end
      return true
  end

  local activeWildEncounter = nil

  mod.exports.__beta26.isTrainerBattleForNuzlocke = function(battle)
      if not battle then return false end
      if battle.kind == "trainer" or battle.type == "trainer" then return true end
      if battle.trainerBattle == true or battle.isTrainerBattle == true then return true end
      if battle.trainer ~= nil or battle.opponentTrainer ~= nil then return true end
      if battle.opponent and type(battle.opponent) == "table" and battle.opponent.name then return true end
      return false
  end

  -- Rival identity is deliberately behavioral and generation-neutral. Trainer
  -- IDs/classes are preferred, with the familiar default names retained as a
  -- compatibility fallback for engine builds that expose only display text.
  mod.exports.__beta26.isRivalBattle = function(battle)
      if type(battle) ~= "table" or not mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then
          return false
      end
      local trainer = type(battle.trainer) == "table" and battle.trainer
          or type(battle.opponentTrainer) == "table" and battle.opponentTrainer
          or nil
      local fields = {
          tostring(battle.oppClass or ""),
          tostring(battle.trainerClass or ""),
          tostring(battle.opponentClass or ""),
          tostring(battle.trainerId or ""),
          tostring(battle.trainerID or ""),
          tostring(battle.opponentId or ""),
          tostring(battle.trainerName or ""),
          tostring(battle.opponentName or ""),
          tostring(trainer and trainer.class or ""),
          tostring(trainer and trainer.trainerClass or ""),
          tostring(trainer and trainer.id or ""),
          tostring(trainer and trainer.name or ""),
      }
      for _, value in ipairs(fields) do
          local compact = value:upper():gsub("[^A-Z0-9]", "")
          if compact:find("RIVAL", 1, true)
              or compact == "BLUE" or compact == "SILVER" then
              return true
          end
      end
      return false
  end

  -- Avoid granting a newly-added option to a later Rival battle on an old
  -- save. Canonical opening locations and the shared level-5/zero-badge battle
  -- profile identify Red/Blue/Yellow and Gold without depending on mod names.
  mod.exports.__beta26.isOpeningRivalBattle = function(game, battle)
      if not mod.exports.__beta26.isRivalBattle(battle) then return false end
      local key = areaKey(game, battle)
      local area = tostring(key or ""):upper():gsub("[^A-Z0-9]", "")
      local openingArea = area:find("OAKSLAB", 1, true) ~= nil
          or area:find("PALLETTOWN", 1, true) ~= nil
          or area:find("ROUTE29", 1, true) ~= nil
          or area:find("CHERRYGROVE", 1, true) ~= nil

      local enemy = battle.enemy
      if type(enemy) == "table" and type(enemy.mon) == "table" then
          enemy = enemy.mon
      end
      local enemyLevel = type(enemy) == "table"
          and tonumber(enemy.level or enemy.lv) or nil
      local badges = currentBadgeCount(game and game.save)
      return openingArea or (badges == 0 and enemyLevel ~= nil and enemyLevel <= 6)
  end

  ---------------------------------------------------------------------
  -- GENERATION-NEUTRAL BATTLE CLASSIFIER
  --
  -- This is a read-only compatibility surface. It consolidates the battle
  -- shapes already understood by individual rules without making a rule
  -- decision or invoking another mod's callbacks. Consumers should prefer
  -- flags over `kind` when categories can overlap (a Rival is also a trainer;
  -- a scripted fixed encounter is also wild/catchable).
  ---------------------------------------------------------------------
  mod.exports.__beta26.classifyBattle = function(game, battle, species)
      local wrapper = type(battle) == "table" and battle or {}
      local core = type(wrapper.battle) == "table" and wrapper.battle or wrapper
      game = game or wrapper.game or core.game or currentGame or mod.game

      local source = tostring(core.encounterType or core.encounterSource
          or core.source or wrapper.encounterType or wrapper.encounterSource
          or wrapper.source or ""):lower()
      local trainer = mod.exports.__beta26.isTrainerBattleForNuzlocke(core)
      local tutorial = wrapper.tutorial == true or core.tutorial == true
          or wrapper.isTutorial == true or core.isTutorial == true
          or source == "tutorial" or source == "catch_tutorial"
      local demo = wrapper.demo == true or core.demo == true
      local ghost = wrapper.ghost == true or core.ghost == true
      local rival = trainer and mod.exports.__beta26.isRivalBattle(core)
      local openingRival = rival
          and mod.exports.__beta26.isOpeningRivalBattle(game, core) or false
      local static = mod.exports.__beta26.isStaticEncounter(game, core)
      local roamer = core.nuzlockeRoamingEncounter == true
          or core.roamingEncounter == true or core.isRoamer == true
          or core.roamer == true or source == "roamer" or source == "roaming"
          or source:find("roam", 1, true) ~= nil
      local scripted = static or core.scriptedEncounter == true
          or core.isScriptedEncounter == true or core.storyEncounter == true
          or source == "script" or source == "scripted" or source == "event"
          or source == "fixed"

      local enemy = core.enemy or wrapper.enemy or core.wildMon
      if type(enemy) == "table" and type(enemy.mon) == "table" then
          enemy = enemy.mon
      end
      species = species or (type(enemy) == "table"
          and (enemy.species or enemy.id or enemy.name))
          or core.species or wrapper.species
      local speciesKey = mod.exports.__beta26.getGlitchSpeciesInfo(
          game, species).key

      local kindText = tostring(core.kind or core.type or ""):lower()
      local wild = not trainer and (core.wild == true or wrapper.wild == true
          or kindText == "wild" or source == "wild" or source == "grass"
          or source == "surf" or source == "fishing" or source == "overworld"
          or static or roamer or type(enemy) == "table")
      local overworld = core.overworldEncounter == true
          or core.overworld == true or core.isOverworld == true
          or source == "overworld"
      local externalProvider = core.nuzlockeEncounterProvider
          or core.encounterProvider or wrapper.nuzlockeEncounterProvider
          or wrapper.encounterProvider
      local externalVersion = core.nuzlockeEncounterProviderVersion
          or core.encounterProviderVersion
          or wrapper.nuzlockeEncounterProviderVersion
          or wrapper.encounterProviderVersion

      local flags = {
          tutorial = tutorial,
          demo = demo,
          ghost = ghost,
          trainer = trainer,
          rival = rival,
          opening_rival = openingRival,
          wild = wild,
          ordinary_wild = wild and not static and not roamer and not scripted,
          static = static,
          fixed = static,
          roaming = roamer,
          scripted = scripted,
          overworld = overworld,
          legendary = Identity.isLegendarySpecies(game, speciesKey),
          mythical = Identity.isMythicalSpecies(game, speciesKey),
          external = externalProvider ~= nil,
      }
      flags.excluded = tutorial or demo or ghost
      flags.catchable = wild and not trainer and not flags.excluded
      flags.unknown = not trainer and not wild and not flags.excluded

      local kind = "unknown"
      if tutorial then kind = "tutorial"
      elseif demo or ghost then kind = "excluded"
      elseif rival then kind = "rival"
      elseif trainer then kind = "trainer"
      elseif roamer then kind = "roaming"
      elseif static then kind = "static"
      elseif scripted then kind = "scripted"
      elseif wild then kind = "wild"
      end

      local trainerRecord = type(core.trainer) == "table" and core.trainer
          or type(core.opponentTrainer) == "table" and core.opponentTrainer
          or nil
      return {
          api = 1,
          kind = kind,
          flags = flags,
          generation = mod.exports.__beta26.runtimeIsGold(game) and 2 or 1,
          area = areaKey(game, core),
          source = source ~= "" and source or nil,
          species = speciesKey,
          trainer = {
              id = core.trainerId or core.trainerID or core.opponentId
                  or (trainerRecord and trainerRecord.id),
              class = core.oppClass or core.trainerClass or core.opponentClass
                  or (trainerRecord and (trainerRecord.class
                      or trainerRecord.trainerClass)),
              name = core.trainerName or core.opponentName
                  or (trainerRecord and trainerRecord.name),
          },
          provider = externalProvider and {
              id = externalProvider,
              version = externalVersion,
          } or nil,
      }
  end

  mod.exports.__beta26.engineBattleSnapshot = function()
      local battle = mod.battle
      if type(battle) ~= "table" or type(battle.snapshot) ~= "function" then
          return nil, "mod.battle snapshot unavailable"
      end
      local ok, snapshot = pcall(battle.snapshot, battle)
      if not ok then return nil, tostring(snapshot) end
      if snapshot == nil then return nil end
      if type(snapshot) ~= "table" then
          return nil, "invalid mod.battle snapshot"
      end
      return snapshot
  end

  mod.exports.battle_classifier = {
      api = 1,
      build = mod.exports.__beta26.build,
      classify = function(game, battle, species)
          return mod.exports.__beta26.classifyBattle(game, battle, species)
      end,
      -- 0.1.98+ current-battle view. The engine returns detached records, so
      -- consumers can render/inspect them without mutating battle state.
      snapshot = function()
          return mod.exports.__beta26.engineBattleSnapshot()
      end,
  }

  mod.exports.__beta26.armFirstRivalForgiveness = function(game, battle)
      if not mod.exports.__beta26.isRivalBattle(battle) then return false end
      if mod.save:get("nuzlocke_first_rival_battle_seen", false) == true then
          return false
      end

      local opening = mod.exports.__beta26.isOpeningRivalBattle(game, battle)
      battle.nuzlockeFirstRivalBattle = opening == true

      -- A rival-shaped battle that is not the canonical opening encounter is
      -- rejected without consuming the durable one-shot. isOpeningRivalBattle
      -- already protects old saves from receiving mercy on later Rival fights;
      -- leaving the semaphore untouched also lets a rewound/reordered run reach
      -- the genuine opener later without having silently burned the feature.
      if not opening then return false end

      -- Once the actual opening Rival battle is reached, the slot is consumed
      -- regardless of whether the option is enabled or whether anybody faints.
      mod.save:set("nuzlocke_first_rival_battle_seen", true)

      local enabled = mod.save:get("first_rival_forgiveness", true) == true
      -- REVIEWED: nuzlocke_first_rival_battle_seen is the only durable
      -- one-shot state. Armed/triggered state is battle-local because no
      -- resume or status path consumes separate persisted telemetry.
      battle.nuzlockeRivalForgiveness = enabled
      return enabled
  end

  mod.exports.__beta26.isFirstRivalForgivenessActive = function(game, battle)
      return type(battle) == "table"
          and battle.nuzlockeFirstRivalBattle == true
          and battle.nuzlockeRivalForgiveness == true
          and mod.save:get("nuzlocke_enabled", true) ~= false
  end

    -- 2.4.20 Limited Shiny Clause. Historical boolean ON is interpreted as
    -- UNLIMITED so existing saves retain their prior behavior without a schema
    -- migration. The run counter records successful shiny exceptions only.
    mod.exports.__beta26.shinyClauseMode = function()
        local raw = mod.save:get("shiny_clause", defaultRuleValue("shiny_clause"))
        if type(raw) == "boolean" then raw = raw and 4 or 0 end
        return math.max(0, math.min(4, math.floor(tonumber(raw) or 0)))
    end

    mod.exports.__beta26.shinyClauseUsed = function()
        return math.max(0, math.floor(tonumber(
            mod.save:get("shiny_clause_used", 0)) or 0))
    end

    mod.exports.__beta26.shinyClauseAvailable = function()
        local mode = mod.exports.__beta26.shinyClauseMode()
        if mode == 4 then return true end
        return mode > 0 and mod.exports.__beta26.shinyClauseUsed() < mode
    end

    mod.exports.__beta26.consumeShinyClauseAllowance = function()
        local mode = mod.exports.__beta26.shinyClauseMode()
        if mode <= 0 then return false end
        if mode == 4 then return true end
        local used = mod.exports.__beta26.shinyClauseUsed()
        if used >= mode then return false end
        mod.save:set("shiny_clause_used", used + 1)
        return true
    end

    -- 2.4.85 Encounter Ball Limit. Stored value is a compact selector mode
    -- so ordinary A/LEFT/RIGHT cycling stays predictable while the displayed
    -- budgets can use the useful OFF/1/2/3/5/10 sequence.
    mod.exports.__beta26.encounterBallLimitValues = { [0]=0, [1]=1, [2]=2, [3]=3, [4]=5, [5]=10 }

    mod.exports.__beta26.encounterBallLimit = function()
        local mode = math.max(0, math.min(5, math.floor(tonumber(
            mod.save:get("encounter_ball_limit", 0)) or 0)))
        return mod.exports.__beta26.encounterBallLimitValues[mode] or 0
    end

    mod.exports.__beta26.encounterBallThrowsUsed = function(battle)
        return type(battle) == "table"
            and math.max(0, math.floor(tonumber(
                battle.nuzlockeEncounterBallThrowsUsed) or 0)) or 0
    end

    mod.exports.__beta26.encounterBallThrowAvailable = function(game, battle)
        local limit = mod.exports.__beta26.encounterBallLimit()
        if limit <= 0 or mod.save:get("nuzlocke_enabled", true) ~= true then
            return true, limit, mod.exports.__beta26.encounterBallThrowsUsed(battle)
        end
        local used = mod.exports.__beta26.encounterBallThrowsUsed(battle)
        return used < limit, limit, used
    end

    mod.exports.__beta26.consumeEncounterBallThrow = function(game, battle)
        local allowed, limit, used =
            mod.exports.__beta26.encounterBallThrowAvailable(game, battle)
        if not allowed then return false, limit, used end
        if limit > 0 and type(battle) == "table" then
            battle.nuzlockeEncounterBallThrowsUsed = used + 1
            return true, limit, used + 1
        end
        return true, limit, used
    end

    mod.exports.__beta26.encounterBallLimitMessage = function(limit)
        return Strings("Ball Limit reached! This encounter allows %d throw%s.",
            tonumber(limit) or 0, tonumber(limit) == 1 and "" or "s")
    end


  mod.exports.__beta26.beginWildEncounter = function(payload)
      if not payload then return end
      local battle = payload.battle or payload
      if not battle then return end
      if not currentGame then currentGame = payload.game end
      local game = payload.game or currentGame
      local classification = mod.exports.__beta26.classifyBattle(game, battle)
      if classification.flags.trainer or classification.flags.excluded then return end
      if not active(game, battle) then return end
      if not mod.exports.__beta26.encounterRulesArmed(game) then return end

      local key = areaKey(game, battle)
      if not key then return end
      local encounterMapId = battle and battle.nuzlockeEncounterMapId
          or mod.exports.__beta26.currentPhysicalArea(game,
              game and game.save and game.save.player
              and game.save.player.map)
      local species = battle.enemy and battle.enemy.mon and battle.enemy.mon.species
          or battle.enemy and battle.enemy.species
          or payload.species
      if species == nil or species == "" then return end
      local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
      local rawSpecies = species
      species = glitch.key

      -- 2.2.18: Failed Encounter eligibility must be derived from the same
      -- authoritative capture policy as an actual Ball throw. Otherwise an
      -- encounter forbidden by No Catching/species/BST/glitch/Solo rules can
      -- consume the area, and Shiny Clause can accidentally change that result.
      local denied = type(catchDeniedReason) == "function"
          and catchDeniedReason(game, battle, species) or nil
      if denied then
          battle.nuzlockeFreeEncounterReason = denied
          battle.nuzlockeEncounterEligible = false
          battle.nuzlockeEncounterWillSpendArea = false
          return
      end

      local shiny = enemyIsShiny(battle)
      local shinyClause = mod.exports.__beta26.shinyClauseAvailable()
      local town = key ~= nil and isTownArea(key, routeName(key)) or false
      local overworld = battle.overworldEncounter == true
          or battle.overworld == true
          or battle.isOverworld == true
          or battle.encounterType == "overworld"
          or battle.source == "overworld"
      local static = mod.exports.__beta26.isStaticEncounter(game, battle)

      if static and mod.exports.__beta26.ruleActive(
          game, "no_static_encounters", battle) then return end
      if overworld and not mod.save:get("overworld_encounters", false) then return end
      if town and not mod.save:get("town_catches", false) then return end
      if not mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) then return end
      if mod.save:get("failed_encounter", true) ~= true then return end
      if caughtAreas()[key] ~= nil then return end

      local existing = getEncounterState(key)
      if existing and (existing.status == "FAILED" or existing.status == "CAUGHT") then return end

      if mod.exports.__beta26.isDuplicateSpecies(game, species)
          and not (shiny and shinyClause) then
          -- Persist the eligibility decision on the battle itself. The failed-
          -- encounter finalizer must never reclassify this encounter after
          -- battle-side mutations or another provider callback changes state.
          battle.nuzlockeFreeEncounterReason = "dupes"
          battle.nuzlockeEncounterEligible = false
          battle.nuzlockeEncounterWillSpendArea = false
          return
      end
      battle.nuzlockeEncounterEligible = true
      battle.nuzlockeEncounterWillSpendArea = true
      battle.nuzlockeEncounterSpendArea = key

      local provider = activeCompatProvider("encounters", game, battle)
      local delegatedEncounter = externalRuleDelegation
          and externalRuleDelegation("random_encounter_tables", game) or nil
      if provider then
          rememberEncounterProvider(provider.id, provider.version)
      elseif delegatedEncounter then
          rememberEncounterProvider(delegatedEncounter.id, delegatedEncounter.version)
      end
      activeWildEncounter = {
          battle = battle, game = game, key = key, species = species,
          encounterMapId = encounterMapId,
          rawSpecies = glitch.isGlitch and rawSpecies or nil,
          glitch = glitch.isGlitch or nil,
          missingNo = glitch.missingNo or nil,
          encounterType = (battle.nuzlockeEncounterMethod == "roamer"
                  or battle.nuzlockeEncounterMethod == "headbutt"
                  or battle.nuzlockeEncounterMethod == "bug_contest")
              and battle.nuzlockeEncounterMethod
              or (static and "static"
                  or (overworld and "overworld" or (town and "town" or "wild"))),
          encounterMethod = battle.nuzlockeEncounterMethod or "wild",
          encounterTime = battle.nuzlockeEncounterTime,
          roamerSpecies = battle.nuzlockeRoamerSpecies,
          encounterSource = (provider or delegatedEncounter) and "provider" or "vanilla",
          encounterProvider = provider and provider.id
              or (delegatedEncounter and delegatedEncounter.id) or nil,
          encounterProviderVersion = provider and provider.version
              or (delegatedEncounter and delegatedEncounter.version) or nil,
          encounterContext = providerContext(provider, game, battle),
          resolved = false,
      }
  end

  -- 2.4.38: player-facing encounter-spend presentation. This is deliberately
  -- a read-only projection of the same pre-catch state used by enforcement;
  -- it never decides legality itself.
  mod.exports.__beta26.encounterSpendIndicator = function(targetBattle)
      if mod.save:get("encounter_spend_indicator", true) ~= true
          or mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) ~= true then return nil end
      local b = targetBattle or (activeWildEncounter and activeWildEncounter.battle)
      if type(b) ~= "table" then return nil end
      local game = b.game or currentGame or mod.game
      local class = mod.exports.__beta26.classifyBattle(game, b)
      if class and class.flags and (class.flags.trainer or class.flags.excluded) then return nil end
      if not active(game, b) or not mod.exports.__beta26.encounterRulesArmed(game) then return nil end

      local conflict = b.nuzlockeClauseConflictChecked == true
          and b.nuzlockeClauseConflict or nil
      local mon = b.enemy and (b.enemy.mon or b.enemy) or nil
      local shiny = Identity.isShiny(mon)
      if conflict ~= nil and shiny and mod.exports.__beta26.shinyClauseAvailable() then
          return { active=true, state="shiny_free", area=areaKey(game,b),
              text=Strings("SHINY:FREE"), conflict=conflict }
      end
      if conflict == "dupes" or b.nuzlockeFreeEncounterReason == "dupes" then
          return { active=true, state="dupe_free", area=areaKey(game,b),
              text=Strings("DUPE:FREE"), conflict="dupes" }
      end
      if conflict == "caught" or conflict == "failed"
          or b.nuzlockeFreeEncounterReason == "area" then
          return { active=true, state="spent", area=areaKey(game,b),
              text=Strings("AREA:SPENT"), conflict=conflict or "caught" }
      end
      if b.nuzlockeFreeEncounterReason ~= nil then
          return { active=true, state="blocked", area=areaKey(game,b),
              text=Strings("NO CATCH"), reason=b.nuzlockeFreeEncounterReason }
      end
      return { active=true, state="counts", area=areaKey(game,b),
          text=Strings("AREA:COUNT") }
  end

  mod.exports.__beta26.installEncounterSpendHUD = function()
      local function install(path)
          local ok, BattleState = pcall(require, path)
          if not ok or type(BattleState) ~= "table"
              or type(BattleState.draw) ~= "function" then return false end
          if BattleState.__nuzlockeEncounterSpendHudOwner == mod
              and BattleState.draw == BattleState.__nuzlockeEncounterSpendHudFunction then
              return true
          end
          if BattleState.__nuzlockeEncounterSpendHudOwner ~= nil
              and BattleState.__nuzlockeEncounterSpendHudOwner ~= mod
              and BattleState.draw == BattleState.__nuzlockeEncounterSpendHudFunction
              and type(BattleState.__nuzlockeEncounterSpendHudPrevious) == "function" then
              BattleState.draw = BattleState.__nuzlockeEncounterSpendHudPrevious
          end
          local previous = BattleState.draw
          local wrapper = function(self, ...)
              local result = previous(self, ...)
              local info = mod.exports.__beta26.encounterSpendIndicator(self)
              if info and info.active and love and love.graphics then
                  local Font = require("src.render.Font")
                  local text = tostring(info.text or "")
                  local width = math.max(56, math.min(88, (#text * 8) + 8))
                  local x = math.floor((160 - width) / 2)
                  love.graphics.setColor(0.10, 0.10, 0.10, 0.92)
                  love.graphics.rectangle("fill", x, 84, width, 10)
                  love.graphics.setColor(1, 1, 1, 1)
                  Font.draw(text, x + 4, 85)
                  love.graphics.setColor(1, 1, 1, 1)
              end
              return result
          end
          BattleState.draw = wrapper
          BattleState.__nuzlockeEncounterSpendHudOwner = mod
          BattleState.__nuzlockeEncounterSpendHudFunction = wrapper
          BattleState.__nuzlockeEncounterSpendHudPrevious = previous
          return true
      end
      local g1 = install("src.battle.BattleState")
      local g2 = install("src.ui.gen2.BattleState")
      return g1 or g2
  end
  mod.events:on("game.ready", function() pcall(mod.exports.__beta26.installEncounterSpendHUD) end)
  mod.events:on("save.loaded", function() pcall(mod.exports.__beta26.installEncounterSpendHUD) end)
  mod.events:on("mods.loaded", function() pcall(mod.exports.__beta26.installEncounterSpendHUD) end)

  -- beta.30.0.0.16: approved second module split.
  -- Trainer money, Forgiveness Token rewards/shop bridge, and trainer
  -- progression bookkeeping are isolated to reduce main.lua's active-local
  -- pressure while preserving their existing public exports.
  mod.exports.__beta26.TrainerRewards = assert(load(
      mod:read("trainer_rewards.lua"),
      "@mods/nuzlocke/trainer_rewards.lua"))()
  mod.exports.__beta26.TrainerRewards.install(mod, {
      Strings = Strings,
      active = active,
      canWriteNuzlockeSave = mod.exports.__beta26.canWriteNuzlockeSave,
      shouldEnforceNuzlocke = mod.exports.__beta26.shouldEnforceNuzlocke,
      isTrainerBattle = mod.exports.__beta26.isTrainerBattleForNuzlocke,
      isSaveEditorSession = mod.exports.__beta26.isSaveEditorSession,
      worldMechanic = worldMechanic,
      worldRuleTriplet = mod.exports.__beta26.worldRuleTriplet,
      externalRuleDelegation = mod.exports.__beta26.externalRuleDelegation,
      pushWorldText = mod.exports.__beta26.pushWorldText,
      worldRuleText = mod.exports.__beta26.worldRuleText,
      gymLeaderForMap = mod.exports.__beta26.gymLeaderForMap,
      getCurrentGame = function() return currentGame end,
      getGameVersion = getGameVersion,
      VersionCompat = VersionCompat,
      gscProgress = gscProgress,
      gscStages = VersionCompat.gscStages,
      levelCapGymLeaders = LEVEL_CAP_GYM_LEADERS,
      gymProgress = gymProgress,
      gymProgressKey = GYM_PROGRESS_KEY,
      eliteFourCaps = ELITE_FOUR_CAPS,
      eliteFourDefeated = eliteFourDefeated,
      currentGymProgressCount = currentGymProgressCount,
      nextEliteFourCapInfo = nextEliteFourCapInfo,
  })

  -- 2.2.18: Gold fishing has its own encounter hook and does not carry a
  -- method field into BattleState. Arm provenance only after the hook returns
  -- a real species so a failed bite can never poison the next wild battle.
  mod.hooks:wrap("encounter.fishing", function(next, ...)
      local result, b, c, d, e = next(...)
      local game = currentGame or mod.game
      if mod.exports.__beta26.runtimeIsGold(game)
          and type(result) == "table" and result.species then
          mod.exports.__beta26.pendingGoldEncounterMethod = { kind = "fishing" }
      end
      return result, b, c, d, e
  end)

  mod.events:on("battle.started", function(payload)
      local battle = payload and (payload.battle or payload)
      local game = payload and payload.game or currentGame
      local pendingStatic = mod.exports.__beta26.pendingStaticEncounter
      if battle and type(pendingStatic) == "table" then
          -- REVIEWED: pendingStaticEncounter is single-use provenance for the
          -- next battle only. Any intervening battle, including a trainer,
          -- consumes it so stale static state cannot leak into a later wild.
          mod.exports.__beta26.pendingStaticEncounter = nil
          if not mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then
              battle.nuzlockeStaticEncounter = true
              battle.encounterType = battle.encounterType or "static"
          end
      end

      -- Gold method provenance is armed before mod.exports.__beta26.beginWildEncounter so areaKey
      -- can project the correct rule slot on the very first policy read.
      if battle and mod.exports.__beta26.runtimeIsGold(game) then
          local pendingRoamer = mod.exports.__beta26.pendingGoldRoamer
          local pendingMethod = mod.exports.__beta26.pendingGoldEncounterMethod
          mod.exports.__beta26.pendingGoldRoamer = nil
          mod.exports.__beta26.pendingGoldEncounterMethod = nil
          if not mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then
              if type(pendingRoamer) == "table" then
                  local enemy = battle.enemy and (battle.enemy.mon or battle.enemy)
                  local species = tostring(enemy and enemy.species or pendingRoamer.species or ""):upper()
                  if species == tostring(pendingRoamer.species or species):upper() then
                      battle.nuzlockeRoamerEncounter = true
                      battle.nuzlockeRoamerSpecies = pendingRoamer.species or species
                      battle.nuzlockeEncounterMethod = "roamer"
                      battle.encounterType = "roamer"
                  end
              elseif type(pendingMethod) == "table"
                  and pendingMethod.kind == "headbutt" then
                  battle.nuzlockeHeadbuttEncounter = true
                  battle.nuzlockeEncounterMethod = "headbutt"
                  battle.encounterType = "headbutt"
              elseif type(pendingMethod) == "table"
                  and pendingMethod.kind == "fishing" then
                  battle.nuzlockeEncounterMethod = "fishing"
                  battle.encounterType = "fishing"
              end
              local contest = game and game.save and game.save.bugContest
              if type(contest) == "table" and contest.active == true then
                  battle.nuzlockeBugContest = true
                  battle.nuzlockeEncounterMethod = "bug_contest"
                  battle.encounterType = "bug_contest"
              end
              -- Gold step encounters do not pass their terrain into BattleState.
              -- Once explicit special/fishing/static provenance has had first
              -- claim, the live surf state distinguishes water from grass.
              if not battle.nuzlockeEncounterMethod
                  and not battle.nuzlockeStaticEncounter
                  and tostring(battle.encounterType or ""):lower() ~= "static" then
                  local playerState = tostring(game and game.world
                      and game.world.playerState or ""):lower()
                  if playerState == "surf" or playerState == "surf_pika" then
                      battle.nuzlockeEncounterMethod = "water"
                      battle.encounterType = battle.encounterType or "water"
                  else
                      battle.nuzlockeEncounterMethod = "grass"
                      battle.encounterType = battle.encounterType or "grass"
                  end
              end
              battle.nuzlockeEncounterTime =
                  mod.exports.__beta26.goldTimeBucket(game)
          end
      end

      -- Gold has a separate battle model. Apply the same absolute creation
      -- presets at the shared battle.started seam when its live model exposes
      -- Pokemon tables. R/B/Y may reach this after the constructor wrapper;
      -- absolute assignment makes that harmless and idempotent.
      if battle and game and active(game, battle) then
          if mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then
              local difficulty = mod.exports.__beta26.Difficulty
              local selected = type(difficulty) == "table"
                  and type(difficulty.selected) == "function"
                  and difficulty.selected() or nil
              local difficultyOwns = type(selected) == "table"
                  and tostring(selected.id or "vanilla") ~= "vanilla"
              local enemyParty = battle.enemyParty
                  or (type(battle.trainer) == "table" and battle.trainer.party)
              if not difficultyOwns and type(enemyParty) == "table" then
                  for _, mon in ipairs(enemyParty) do
                      if type(mon) == "table" and mon.species then
                          mod.exports.__beta26.StatRules.applyStarting(game.data, mon,
                              "trainer_start_stat_exp", "perfect_trainer_ivs", false)
                      end
                  end
              elseif not difficultyOwns and type(battle.enemy) == "table" then
                  local mon = battle.enemy.mon or battle.enemy
                  if mon.species then
                      mod.exports.__beta26.StatRules.applyStarting(game.data, mon,
                          "trainer_start_stat_exp", "perfect_trainer_ivs", false)
                  end
              end
          elseif type(battle.enemy) == "table" then
              local mon = battle.enemy.mon or battle.enemy
              if mon.species then
                  mod.exports.__beta26.StatRules.applyStarting(game.data, mon,
                      "wild_start_stat_exp", "perfect_wild_ivs", false)
              end
          end
      end

      -- Badge Boosts is an independent battle-mechanics rule and must cover
      -- wild as well as trainer battles. Apply its policy before the
      -- trainer-only difficulty transforms below.
      if battle and game then
          local difficulty = mod.exports.__beta26.Difficulty
          if type(difficulty) == "table"
              and type(difficulty.applyBadgeBoostPolicy) == "function" then
              difficulty.applyBadgeBoostPolicy(game, battle)
          end
      end

      -- Game Difficulty is not a Nuzlocke rule.  Apply its trainer stats and
      -- native AI after the manual Nuzlocke creation presets so a selected
      -- built-in profile remains authoritative even with the master switch OFF.
      if battle and game and mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then
          local difficulty = mod.exports.__beta26.Difficulty
          local enemyParty = battle.enemyParty
              or (type(battle.trainer) == "table" and battle.trainer.party)
          if type(difficulty) == "table" then
              if type(enemyParty) == "table" then
                  for _, mon in ipairs(enemyParty) do
                      if type(mon) == "table" and mon.species then
                          difficulty.applyTrainerStats(game, mon)
                      end
                  end
              elseif type(battle.enemy) == "table" then
                  local mon = battle.enemy.mon or battle.enemy
                  if mon.species then difficulty.applyTrainerStats(game, mon) end
              end
              difficulty.applyBattleAI(game, battle)
          end
      end

      mod.exports.__beta26.TrainerRewards.rememberWallet(game, battle)

      mod.exports.__beta26.beginWildEncounter(payload)

      if battle and game then
          pcall(mod.exports.__beta26.armFirstRivalForgiveness, game, battle)
      end
      if not battle or not game or not active(game, battle) or not mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then return end
      local oppClass = tostring(battle.oppClass or battle.trainerClass or battle.opponentClass or ""):upper()
      local trainerName = tostring((battle.trainer and battle.trainer.name) or battle.trainerName or battle.opponentName or ""):upper()
      local label = oppClass .. " " .. trainerName

      -- battle.started fires after the vanilla intro queue is assembled but
      -- before that queue has actually played. Pushing a separate TextBox here
      -- made the rival flavor appear before the rival sprite. Queue the flavor
      -- onto the battle itself instead, so the vanilla trainer reveal/send-out
      -- sequence remains first.
      local function queueTrainerFlavor(key, message, minimumTier)
          if worldTier(game) < (minimumTier or 3) then return false end
          local flags = worldFlags()
          if flags[key] then return false end
          if type(battle.say) == "function" then
              local cleaned = mod.exports.__beta26.cleanWorldText(message)
              local ok = pcall(battle.say, battle,
                  mod.exports.__beta26.formatBattleText
                      and mod.exports.__beta26.formatBattleText(cleaned) or cleaned)
              if ok then
                  flags[key] = true
                  mod.save:set("nuzlocke_world_flags", flags)
                  return true
              end
          elseif type(battle.emit) == "function" then
              -- Gold's battle model has an event queue rather than Gen 1's
              -- say() queue.  A message emitted during battle.started is
              -- drained after the native intro, preserving story order.
              local cleaned = mod.exports.__beta26.cleanWorldText(message)
              local ok = pcall(battle.emit, battle, {
                  kind = "message", text = cleaned,
              })
              if ok then
                  flags[key] = true
                  mod.save:set("nuzlocke_world_flags", flags)
                  return true
              end
          end
          return worldOnce(game, key, message, minimumTier)
      end

      if battle.nuzlockeRivalForgiveness == true then
          queueTrainerFlavor("first_rival_forgiveness",
              mod.exports.__beta26.worldRuleText(
                  game, "first_rival_forgiveness"), 1)
      elseif label:find("RIVAL", 1, true) or label:find("BLUE", 1, true) then
          queueTrainerFlavor("rival_notice", "Your Rival notices the rule card.\n\"Fine. Just don't change those rules after I beat you.\"")
      elseif label:find("BROCK", 1, true) then
          queueTrainerFlavor("brock_notice", "Brock looks over your team.\n\"I've heard about your little challenge.\"\n\"Don't worry. My team won't go easy on you.\"")
      elseif label:find("MISTY", 1, true) then
          queueTrainerFlavor("misty_notice", "Misty smirks.\n\"Let's see how long those rules last.\"")
      elseif label:find("LT SURGE", 1, true) or label:find("LT_SURGE", 1, true) then
          queueTrainerFlavor("surge_notice", "Lt. Surge grins.\n\"Hardcore rules? Good. I like a serious challenger.\"")
      elseif label:find("ERIKA", 1, true) or label:find("KOGA", 1, true) or label:find("SABRINA", 1, true) or label:find("BLAINE", 1, true) or label:find("GIOVANNI", 1, true) then
          queueTrainerFlavor("gym_leader_notice:" .. label, "The Gym Leader has heard about your Nuzlocke.\n\"Let's see whether you can follow your own rules under pressure.\"")
      elseif label:find("FALKNER", 1, true) then
          queueTrainerFlavor("falkner_notice", "Falkner glances at the rule card.\n\"A self-imposed challenge? Then show me how high your team can fly.\"")
      elseif label:find("BUGSY", 1, true) then
          queueTrainerFlavor("bugsy_notice", "Bugsy lights up at the challenge.\n\"Great! Let's see how your rules handle my research.\"")
      elseif label:find("WHITNEY", 1, true) then
          queueTrainerFlavor("whitney_notice", "Whitney reads the rules twice.\n\"No changing them if this gets hard, okay?\"")
      elseif label:find("MORTY", 1, true) then
          queueTrainerFlavor("morty_notice", "Morty studies your team quietly.\n\"A journey where every loss matters... I understand.\"")
      elseif label:find("CHUCK", 1, true) or label:find("JASMINE", 1, true)
          or label:find("PRYCE", 1, true) or label:find("CLAIR", 1, true) then
          queueTrainerFlavor("johto_gym_notice:" .. label,
              "The Gym Leader knows about your Nuzlocke.\n\"Your rules are yours. My job is to test them.\"")
      end
  end)

  -- beta.30.0.0.16: late runtime installers live in a nested function
  -- scope so their helper locals do not contribute to main.lua's Lua 200-local
  -- compiler ceiling. This preserves closure access to the existing main-state
  -- variables without introducing another module boundary.
  -- 2.2.7: Lua 5.1 limits each function to 60 upvalues. The former
  -- monolithic late-runtime closure exceeded that limit. Run the same
  -- initialization in two sequential closures so each captures only
  -- the outer state it actually uses.
  -- 2.2.9 project compiler budget: keep runtime phases well below Lua 5.1 limits.
  mod.exports.__beta26._lateRuntimeInit = function()
    -- Some composable battle-format mods temporarily narrow/reorder the player's
    -- party and restore the original Pokemon objects at battle.ended. A Pokemon
    -- that died while selected can therefore be reinserted by that later restore
    -- even though Nuzlocke removed it before vanilla faint handling. Keep this
    -- generic: dead provenance on the Pokemon object is authoritative, regardless
    -- of which mod temporarily owned the party layout.
    local function pruneRestoredDeadPokemon(game)
        local party = game and game.save and game.save.party
        if type(party) ~= "table" then return 0 end
        local removed = 0
        for i = #party, 1, -1 do
            local mon = party[i]
            if type(mon) == "table" and mon.nuzlockeDead == true then
                table.remove(party, i)
                removed = removed + 1
            end
        end
        return removed
    end
    mod.exports.__beta26.pruneRestoredDeadPokemon = pruneRestoredDeadPokemon
  
    -- Run after ordinary battle.ended listeners. This lets temporary-party mods
    -- restore their snapshot first, then removes only Pokemon already marked dead
    -- by Nuzlocke. Priority is intentionally lower than the normal default (0).
    -- IPC 1.1.0's CANLOSE tournament loss handler is one concrete case: it heals
    -- living survivors at battle.ended, then this invariant runs later so a
    -- Nuzlocke-dead Pokemon cannot be revived by that survivor-heal pass.
    mod.events:on("battle.ended", function(payload)
        local battle = payload and (payload.battle or payload)
        local game = battle and battle.game or currentGame
        if not (battle and battle.nuzlockeRivalForgivenessTriggered == true)
            and mod.exports.__beta26.shouldEnforceNuzlocke(game, battle)
            and mod.save:get("permadeath", true) == true then
            pruneRestoredDeadPokemon(game)
        end
    end, -1000)
  
    -- One private, idempotent battle finalizer owns every Nuzlocke task that
    -- depends on battle completion. The genuine engine battle.ended event calls
    -- it, and the BattleState.finish wrapper above is only a private fallback for
    -- older builds. External mods never see a fabricated duplicate event.
    local finalizedNuzlockeBattles = setmetatable({}, { __mode = "k" })
  
    local function finalizeFailedEncounter(battle)
        local pending = activeWildEncounter
        activeWildEncounter = nil
  
        local game = (battle and battle.game) or currentGame
        if not battle or not game or not game.save then return end
        if not mod.exports.__beta26.shouldEnforceNuzlocke(game, battle) then return end
        if pending and pending.battle and battle ~= pending.battle then pending = nil end
        if mod.exports.__beta26.isTrainerBattleForNuzlocke(battle) then return end
        if battle.nuzlockeFreeEncounterReason == "dupes"
            or battle.nuzlockeEncounterEligible == false then return end
        if battle.nuzlockeEncounterMethod == "roamer"
            and mod.save:get("gold_roamer_clause", false) == true then return end
        if battle.nuzlockeEncounterMethod == "bug_contest"
            and math.max(0, math.min(2, math.floor(tonumber(
                mod.save:get("gold_bug_contest_mode", 0)) or 0))) > 0 then return end
        if not mod.exports.__beta26.encounterRulesArmed(game) then return end
        if mod.save:get("nuzlocke_enabled", true) ~= true
            or mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) ~= true
            or mod.save:get("failed_encounter", true) ~= true then
            return
        end
  
        local key = battle.nuzlockeEncounterAreaKey
            or areaKey(game, battle)
        local species = battle.enemy and battle.enemy.mon and battle.enemy.mon.species
        if not key or species == nil or species == "" then return end
        local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
        species = glitch.key
  
        local enemyMon = battle.enemy and (battle.enemy.mon or battle.enemy)
        if not mod.exports.__beta26.typeLockAllowsPokemon(game, enemyMon) then return end
  
        local shiny = enemyIsShiny(battle)
        if shiny and mod.exports.__beta26.shinyClauseAvailable() then return end
  
        local town = isTownArea(key, routeName(key))
        local overworld = battle.overworldEncounter == true
            or battle.overworld == true
            or battle.isOverworld == true
            or battle.encounterType == "overworld"
            or battle.source == "overworld"
        local static = mod.exports.__beta26.isStaticEncounter(game, battle)
        if static and mod.exports.__beta26.ruleActive(
            game, "no_static_encounters", battle) then return end
        if overworld and mod.save:get("overworld_encounters", false) ~= true then return end
        if town and mod.save:get("town_catches", false) ~= true then return end
        if caughtAreas()[key] ~= nil then return end
  
        local state = getEncounterState(key)
        if state and (state.status == "FAILED" or state.status == "CAUGHT") then return end
        if mod.exports.__beta26.isDuplicateSpecies(game, species) then return end
  
        local encounterType = (battle.nuzlockeEncounterMethod == "roamer"
                or battle.nuzlockeEncounterMethod == "headbutt"
                or battle.nuzlockeEncounterMethod == "bug_contest")
            and battle.nuzlockeEncounterMethod
            or (glitch.isGlitch and "glitch"
                or (static and "static"
                    or (overworld and "overworld" or (town and "town" or "wild"))))
        local sourceMap = battle.nuzlockeEncounterMapId
            or (pending and pending.encounterMapId)
  
        local function consumeFailure()
            mod.exports.__beta26.markEncounterFailed(key, species, encounterType, sourceMap, {
                encounterMethod = battle.nuzlockeEncounterMethod or "wild",
                encounterTime = battle.nuzlockeEncounterTime,
                roamerSpecies = battle.nuzlockeRoamerSpecies,
            })
            local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
                game, "failed_encounter")
            worldMechanic(game, "failed:" .. tostring(key), t1, t2, t3)
        end
  
        if mod.exports.__beta26.TrainerRewards.forgivenessEnabled(game, battle)
            and mod.exports.__beta26.TrainerRewards.forgivenessTokens() > 0
            and mod.ui and type(mod.ui.push) == "function" then
            mod.ui.push(game, "NuzlockeForgivenessPrompt", {
                onChoice = function(spend)
                    if spend
                        and mod.exports.__beta26.TrainerRewards.forgivenessTokens() > 0 then
                        mod.exports.__beta26.TrainerRewards.setForgivenessTokens(
                            mod.exports.__beta26.TrainerRewards.forgivenessTokens() - 1)
                        local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
                            game, "route_forgiveness_used")
                        worldMechanic(game, "forgiven:" .. tostring(key), t1, t2, t3)
                    else
                        consumeFailure()
                    end
                end,
            })
            return
        end
  
        consumeFailure()
    end
  
    finalizeNuzlockeBattle = function(battle, result)
        if type(battle) ~= "table" then return false end
        if finalizedNuzlockeBattles[battle] then return false end
        finalizedNuzlockeBattles[battle] = true

        local game = battle.game or currentGame
        local finalResult = result or battle.result or "run"

        -- PASSIVE_PROGRESS: keep boss progression synchronized even while the
        -- player temporarily disables Nuzlocke, but never write through a
        -- future/newer save schema this build does not understand.
        if mod.exports.__beta26.canWriteNuzlockeSave(game) then
            mod.exports.__beta26.TrainerRewards.recordLeagueProgression(
                battle, finalResult)
        end

        -- RULE_ENFORCEMENT: rewards, money rewriting, and failed-encounter
        -- consequences exist only while the challenge is actually active.
        if not mod.exports.__beta26.shouldEnforceNuzlocke(game, battle) then
            return true
        end
        mod.exports.__beta26.TrainerRewards.awardGymLeaderForgiveness(
            battle, finalResult)
        mod.exports.__beta26.TrainerRewards.scaleTrainerMoney(
            battle, finalResult)
        finalizeFailedEncounter(battle)
        return true
    end
  
    mod.events:on("battle.ended", function(payload)
        local battle = payload and (payload.battle or payload)
        local result = payload and payload.result or (battle and battle.result)
        if type(finalizeNuzlockeBattle) == "function" then
            finalizeNuzlockeBattle(battle, result)
        end
    end)
  
    enemyIsShiny = function(battle)
        if not (battle and battle.enemy) then return false end
        local mon = battle.enemy.mon or battle.enemy
        return Identity.isShiny(mon)
    end
  
    catchDeniedReason = function(game, battle, species)
        if not active(game, battle) then
            return nil
        end
  
        -- A nil/empty species means the enemy slot is not populated yet (for
        -- example transition frames). Other malformed or numeric identities are
        -- passed through the conservative glitch classifier.
        if species == nil or species == "" then
            return nil
        end
        local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(game, species)
        species = glitch.key
  
        -- beta.29.3.4: No Catching is semantic, not a list of Ball ids. This
        -- catches custom capture providers that consult nuzlocke_compat.canCapture
        -- as well as the built-in item-use gates. Non-capture gifts/trades never
        -- pass through this policy.
        if mod.save:get("no_catching", false) == true then
            return "no_catching"
        end
        local enemyMon = battle and battle.enemy and (battle.enemy.mon or battle.enemy)
        local typeAllowed = enemyMon
            and mod.exports.__beta26.typeLockAllowsPokemon(game, enemyMon)
            or mod.exports.__beta26.typeLockAllowsSpecies(game, species)
        if not typeAllowed then return "type_lock" end
  
        local key = battle and battle.nuzlockeEncounterAreaKey
            or areaKey(game, battle)
        -- Compatible/custom battle providers may omit a resolvable area.
        -- Fail open only for checks that actually require an area; absolute
        -- and species-wide restrictions below still remain enforceable.
  
        syncCaughtAreasFromLog()
  
        local overworld = false
        if battle then
            overworld = battle.overworldEncounter == true
                or battle.overworld == true
                or battle.isOverworld == true
                or battle.encounterType == "overworld"
                or battle.source == "overworld"
        end
  
        local town = key ~= nil and isTownArea(key, routeName(key)) or false
        local shiny = enemyIsShiny(battle)
        local shinyClause = mod.exports.__beta26.shinyClauseAvailable()
        local encounterArmed = mod.exports.__beta26.encounterRulesArmed(game)
  
        if glitch.isGlitch and not mod.exports.__beta26.glitchCatchesAllowed() then
            return "glitch"
        end
  
        -- Static is an absolute capture ban. It is checked before Shiny, area,
        -- and Dupes exceptions so those clauses cannot accidentally bypass it.
        if mod.exports.__beta26.ruleActive(game, "no_static_encounters", battle)
            and mod.exports.__beta26.isStaticEncounter(game, battle) then
            return "static"
        end
  
        if overworld and not mod.save:get("overworld_encounters", false) then
            return "overworld"
        end
  
        if town and not mod.save:get("town_catches", false) then
            return "town"
        end
  
        if mod.save:get("ban_legendaries", false) and Identity.isLegendarySpecies(game, species) then
            return "legendary"
        end
  
        if mod.save:get("ban_mythicals", false) and Identity.isMythicalSpecies(game, species) then
            return "mythical"
        end
  
        if mod.save:get("ban_pseudos", false) and Identity.isPseudoSpecies(game, species) then
            return "pseudo"
        end
  
        local clauseConflict = mod.exports.__beta26.catchClauseConflict(
            game, battle, species)
        if type(battle) == "table" then
            -- Preserve the pre-catch ordinary-clause state. At pokemon.caught
            -- time the new mon may already be in the party/Pokedex, so a fresh
            -- species can no longer be safely reclassified for Dupes there.
            battle.nuzlockeClauseConflictChecked = true
            battle.nuzlockeClauseConflict = clauseConflict
        end
        if clauseConflict and not (shiny and shinyClause) then
            return clauseConflict == "dupes" and "dupes" or "area"
        end
  
        -- Dupes remains the earlier eligibility decision: an over-limit species
        -- that is also a duplicate should still be treated as a free duplicate
        -- encounter rather than as the area's rejected BST encounter.
        local bstLimit = mod.exports.__beta26.getMaximumBST()
        local bst = bstLimit > 0
            and mod.exports.__beta26.getSpeciesBST(game, species) or nil
        if bst and bst > bstLimit then
            return "bst"
        end
  
        if mod.exports.__beta26.partyAtConfiguredLimit(game and game.save) then
            return "party_size"
        end
  
        return nil
    end
  
    ---------------------------------------------------------------------
    -- ENCOUNTER TYPE
    -- Stored on each Pokemon and tracker entry for Catch Info and history.
    ---------------------------------------------------------------------
    local function encounterTypeFor(ev, key)
        local rawSpecies = ev and (ev.species or (ev.mon and ev.mon.species))
        if rawSpecies ~= nil
            and mod.exports.__beta26.getGlitchSpeciesInfo(
                ev and ev.game or currentGame, rawSpecies).isGlitch then
            return "glitch"
        end
        if ev and ev.battle then
            local method = mod.exports.__beta26.goldEncounterMethod(ev.battle)
            if method == "roamer" or method == "headbutt"
                or method == "bug_contest" then return method end
            if ev.ball ~= nil and ev.battle.trainer then
                return "trainer_capture"
            end
        end
        if ev and mod.exports.__beta26.isStaticEncounter(
            ev.game or currentGame, ev.battle or ev) then return "static" end
        if mod.exports.__beta26.isOverworldEncounter(ev) then return "overworld" end
        if ev and ev.battle and ev.battle.safari then return "safari" end
        if isTownArea(key, routeName(key)) then return "town" end
        return "wild"
    end
  
    ---------------------------------------------------------------------
    -- BETA.26 DEFERRED STARTING BALLS
    -- Configured starting Balls are released only after Oak's Pokedex handoff.
    ---------------------------------------------------------------------
    mod.exports.__beta26.releaseDeferredStartingBalls = function(game)
        if saveSchemaTooNew then return false end
        local save = game and game.save
        if not save or tonumber(game and game.generation) == 2 then return false end
        local amount = math.max(0, math.min(99,
            math.floor(tonumber(save.nuzlockeDeferredStartingBalls) or 0)))
        if amount <= 0 then return false end
        local flags = save.flags
        local gotDex = type(flags) == "table"
            and (flags.EVENT_GOT_POKEDEX == true
                 or tonumber(flags.EVENT_GOT_POKEDEX) == 1)
        if not gotDex then return false end
  
        save.pcItems = save.pcItems or {}
        local have = math.max(0, tonumber(save.pcItems.POKE_BALL) or 0)
        save.pcItems.POKE_BALL = math.min(99, have + amount)
        save.nuzlockeDeferredStartingBalls = nil
        mod.exports.__beta26.encounterRulesArmed(game)
        worldMechanic(game, "starting_balls_released",
            "Your starting Poke Balls are waiting in your PC at home.",
            "Pokedex ready. Your challenge Poke Balls are waiting in your PC at home.",
            "Oak finished the paperwork! Your challenge Poke Balls are waiting in your PC at home.")
        return true
    end
  
    mod.events:on("world.stepped", function()
        if currentGame then mod.exports.__beta26.releaseDeferredStartingBalls(currentGame) end
    end)
  
    ---------------------------------------------------------------------
    -- POKEMON CAUGHT
    ---------------------------------------------------------------------
    mod.events:on("pokemon.caught", function(ev)
        if not active(ev.game, ev.battle) then
            return
        end
        if mod.exports.__beta26.runtimeIsGold(ev.game)
            and ev.battle and ev.battle.nuzlockeEncounterMethod == "bug_contest"
            and math.max(0, math.min(2, math.floor(tonumber(
                mod.save:get("gold_bug_contest_mode", 0)) or 0))) > 0 then
            if ev.mon then
                ev.mon.nuzlockeOrigin = ev.mon.nuzlockeOrigin or "NORMAL"
                ev.mon.encounterType = "bug_contest"
                ev.mon.nuzlockeEncounterMethod = "bug_contest"
            end
            return
        end
  
        local key = ev.battle and ev.battle.nuzlockeEncounterAreaKey
            or areaKey(ev.game, ev.battle)
        if not key then return end
        local encounterMapId = ev.battle and ev.battle.nuzlockeEncounterMapId
            or (activeWildEncounter and activeWildEncounter.encounterMapId)
            or mod.exports.__beta26.currentPhysicalArea(ev.game,
                ev.game and ev.game.save and ev.game.save.player
                    and ev.game.save.player.map)
  
        local rawSpecies = ev.species or (ev.mon and ev.mon.species)
        if rawSpecies == nil or rawSpecies == "" then return end
        local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(ev.game, rawSpecies)
        local caughtSpecies = glitch.key
        if ev.battle and not mod.exports.__beta26.isTrainerBattleForNuzlocke(ev.battle) then
            local drafted, slot, draftedType, complete = mod.exports.__beta26.recordTypeLockDraftCatch(ev.game, ev.mon, caughtSpecies)
            if drafted then
                local shown = draftedType == "PSYCHIC_TYPE" and "PSYCHIC" or draftedType
                local t1 = ("Catch Draft: Type %d became %s."):format(slot, shown)
                local t2 = complete and ("Your %s is set. Type Locke is now active."):format(mod.exports.__beta26.typeLockModeName(mod.exports.__beta26.typeLockMode())) or ("Catch Draft added %s. Opening catches remain unrestricted until all lanes are filled."):format(shown)
                worldMechanic(ev.game, "type_lock_draft:" .. tostring(slot), t1, t2, t2)
            end
        end
        local isShiny = Identity.isShiny(ev.mon)
        local shinyClauseReason = nil
        if isShiny and type(ev.battle) == "table"
            and ev.battle.nuzlockeClauseConflictChecked == true then
            shinyClauseReason = ev.battle.nuzlockeClauseConflict
        elseif isShiny then
            -- A source that reaches pokemon.caught without the ordinary Ball
            -- policy cannot safely recompute Dupes after acquisition because
            -- the new mon may already be owned. Area state is still safe to
            -- inspect because this handler has not registered the catch yet.
            local fallbackKey = key
            shinyClauseReason = mod.exports.__beta26.encounterSlotConflict(
                ev.game, fallbackKey, true)
        end
        local shinyClauseApplies = isShiny and shinyClauseReason ~= nil
            and mod.exports.__beta26.shinyClauseAvailable()
        local consumesArea = not shinyClauseApplies
        local encounterType = encounterTypeFor(ev, key)
  
        -- R/B/Y starter acquisition may emit received and caught events on
        -- different Pokemon tables while the player is physically in Oak's Lab.
        -- Pallet Town is the canonical starter encounter slot; never create a
        -- second Oak's Lab tracker row for the same starter.
        local catchSource = tostring(ev.source or ""):lower()
        local openingStarter = mod.exports.__beta26.isOpeningStarterAcquisition(
            ev.game, caughtSpecies, catchSource, key, ev.mon)
        if key ~= "PALLET_TOWN" and openingStarter then
            local keyText = tostring(key or ""):upper()
            if keyText:find("OAK", 1, true) or keyText:find("LAB", 1, true) then
                mod.exports.__beta26.registerStarterCatch(caughtSpecies, ev.mon)
                mod.exports.__beta26.cleanupStarterDuplicate()
                return
            end
  
            local pallet = trackerLog()["PALLET_TOWN"]
            local sameStarter = false
            if type(pallet) == "table" then
                for _, entry in ipairs(pallet) do
                    if tostring(entry and entry.species or ""):upper() == caughtSpecies then
                        sameStarter = true
                        break
                    end
                end
            end
            local sourceText = tostring(ev.source or ""):lower()
            if sameStarter and ev.battle == nil
                and (sourceText == "" or sourceText == "starter") then
                -- The earlier OAK/LAB branch already handled explicit lab
                -- locations. This fallback covers starter acquisition events
                -- with no battle that report a post-selection/current map.
                if ev.mon then
                    ev.mon.catchLocation = "PALLET_TOWN"
                    ev.mon.encounterType = "gift"
                    ev.mon.nuzlockeTrackerRegistered = true
                    Identity.setPokemonOrigin(ev.mon, "NORMAL")
                    Identity.baselineAdd(ev.mon, "NORMAL")
                end
                return
            end
        end
  
        -- Snapshot encounter provenance at catch time. This is deliberately
        -- tied to the battle that generated the Pokemon, not to the provider
        -- that happens to be active later in the save.
        local encounterSource = "vanilla"
        local encounterProvider = nil
        local encounterProviderVersion = nil
        local encounterContext = nil
        if activeWildEncounter and activeWildEncounter.battle == ev.battle then
            encounterSource = activeWildEncounter.encounterSource or "vanilla"
            encounterProvider = activeWildEncounter.encounterProvider
            encounterProviderVersion = activeWildEncounter.encounterProviderVersion
            encounterContext = activeWildEncounter.encounterContext
        else
            local provider = activeCompatProvider("encounters", ev.game, ev.battle)
            local delegatedEncounter = externalRuleDelegation
                and externalRuleDelegation("random_encounter_tables", ev.game) or nil
            if provider then
                encounterSource = "provider"
                encounterProvider = provider.id
                encounterProviderVersion = provider.version
                encounterContext = providerContext(provider, ev.game, ev.battle)
            elseif delegatedEncounter then
                encounterSource = "provider"
                encounterProvider = delegatedEncounter.id
                encounterProviderVersion = delegatedEncounter.version
            end
        end
        rememberEncounterProvider(encounterProvider, encounterProviderVersion)
  
        -- Starters/gifts/trades can emit both pokemon.received and
        -- pokemon.caught in the same acquisition flow. Do not log the same mon
        -- twice or overwrite its authoritative received location.
        local alreadyRegistered = ev.mon and ev.mon.nuzlockeTrackerRegistered == true
        if alreadyRegistered then
            markVisited(encounterMapId or key)
            return
        end
  
        if ev.mon then
            ev.mon.catchLocation = key
            ev.mon.encounterType = encounterType
            ev.mon.nuzlockeEncounterMapId = encounterMapId
            ev.mon.nuzlockeEncounterMethod = ev.battle and ev.battle.nuzlockeEncounterMethod or "wild"
            ev.mon.nuzlockeEncounterTime = ev.battle and ev.battle.nuzlockeEncounterTime or nil
            ev.mon.nuzlockeRoamerSpecies = ev.battle and ev.battle.nuzlockeRoamerSpecies or nil
            ev.mon.nuzlockeDead = false
            ev.mon.deathCause = nil
            ev.mon.deathCauseText = nil
            ev.mon.nuzlockeTrackerRegistered = true
            ev.mon.nuzlockeGlitch = glitch.isGlitch or nil
            ev.mon.nuzlockeMissingNo = glitch.missingNo or nil
            ev.mon.nuzlockeRawSpecies = glitch.isGlitch and rawSpecies or nil
            Identity.setPokemonOrigin(ev.mon, "NORMAL")
            Identity.baselineAdd(ev.mon, "NORMAL")
            ev.mon.nuzlockeEncounterSource = encounterSource
            ev.mon.nuzlockeEncounterProvider = encounterProvider
            ev.mon.nuzlockeEncounterProviderVersion = encounterProviderVersion
            if encounterContext then ev.mon.nuzlockeEncounterContext = encounterContext end
  
            local history = mod.save:get("nuzlocke_history", {})
            if type(history) ~= "table" then history = {} end
            table.insert(history, {
                name = ev.mon.nickname or glitch.label,
                species = caughtSpecies,
                rawSpecies = glitch.isGlitch and rawSpecies or nil,
                glitch = glitch.isGlitch or nil,
                missingNo = glitch.missingNo or nil,
                pokemonId = Identity.pokemonIdentity(ev.mon),
                catchLocation = key,
                encounterMapId = encounterMapId,
                encounterType = encounterType,
                encounterMethod = ev.battle and ev.battle.nuzlockeEncounterMethod or "wild",
                encounterTime = ev.battle and ev.battle.nuzlockeEncounterTime or nil,
                roamerSpecies = ev.battle and ev.battle.nuzlockeRoamerSpecies or nil,
                encounterSource = encounterSource,
                encounterProvider = encounterProvider,
                encounterProviderVersion = encounterProviderVersion,
                encounterContext = encounterContext,
                status = "ALIVE",
            })
            mod.save:set("nuzlocke_history", history)
        end
  
        markVisited(encounterMapId or key)
        mod.exports.__beta26.markEncounterCaught(key, caughtSpecies, encounterType, encounterMapId,
            consumesArea, {
                encounterMethod = ev.battle and ev.battle.nuzlockeEncounterMethod or "wild",
                encounterTime = ev.battle and ev.battle.nuzlockeEncounterTime or nil,
                roamerSpecies = ev.battle and ev.battle.nuzlockeRoamerSpecies or nil,
            })
        if activeWildEncounter and activeWildEncounter.key == key then
            activeWildEncounter.resolved = true
        end
  
        local log = trackerLog()
        log[key] = log[key] or {}
  
        -- Never append the same species twice to one area. This is especially
        -- important for acquisition flows where the engine can emit both a
        -- received event and a caught event on separate Pokemon tables.
        local duplicate = false
        local speciesKey = caughtSpecies
        local caughtId = ev.mon and Identity.ensurePokemonIdentity(ev.mon, ev.game and ev.game.save, "NORMAL") or nil
        for _, entry in ipairs(log[key]) do
            local entryId = entry and entry.pokemonId
            if caughtId and entryId then
                duplicate = tostring(entryId) == tostring(caughtId)
            elseif tostring(entry and entry.species or ""):upper() == speciesKey then
                -- Compatibility fallback for a pre-beta.19 tracker row.
                duplicate = true
                if caughtId and entry then entry.pokemonId = caughtId end
            end
            if duplicate then break end
        end
  
        if not duplicate then
            table.insert(log[key], {
                species = caughtSpecies,
                rawSpecies = glitch.isGlitch and rawSpecies or nil,
                glitch = glitch.isGlitch or nil,
                missingNo = glitch.missingNo or nil,
                pokemonId = caughtId,
                fingerprint = ev.mon and Identity.fingerprint(ev.mon) or nil,
                isShiny = isShiny,
                consumedArea = consumesArea,
                encounterType = encounterType,
                encounterMapId = encounterMapId,
                encounterMethod = ev.battle and ev.battle.nuzlockeEncounterMethod or "wild",
                encounterTime = ev.battle and ev.battle.nuzlockeEncounterTime or nil,
                roamerSpecies = ev.battle and ev.battle.nuzlockeRoamerSpecies or nil,
                encounterSource = encounterSource,
                encounterProvider = encounterProvider,
                encounterProviderVersion = encounterProviderVersion,
                encounterContext = encounterContext,
                provenance = "NORMAL"
            })
            mod.save:set("tracker_log", log)
        end
  
        -- Only successful eligible catches consume the area's encounter.
        if consumesArea then
            if mod.save:get("encounter_limit", defaultRuleValue("encounter_limit")) then
                markCaught(key, caughtSpecies)
            end
        end
  
        if shinyClauseApplies then
            mod.exports.__beta26.consumeShinyClauseAllowance()
            if mod.exports.__beta26.Dev then
                mod.exports.__beta26.Dev.push("shiny_clause",
                    "bypass=" .. tostring(shinyClauseReason or "unknown")
                        .. " area=" .. tostring(key), ev.game)
            end
            local t1, t2, t3 = mod.exports.__beta26.worldRuleTriplet(
                ev.game, "shiny_clause",
                "SHINY!\nThe Shiny Clause says this one gets a pass.",
                "Whoa. SHINY!\nThe rules can wait for this one.",
                "Even the Nuzlocke gods make exceptions for sparkle.")
            worldMechanic(ev.game,
                "shiny:" .. tostring(ev.mon and (ev.mon.nickname or ev.mon.species) or ev.species),
                t1, t2, t3)
        else
            local displaySpecies = ev.mon and ev.mon.nickname or glitch.label
            worldMechanic(ev.game, "catch:" .. tostring(key) .. ":" .. caughtSpecies,
                Strings("FIRST ENCOUNTER!\n%s joins the run.", tostring(displaySpecies)),
                "New teammate acquired.\nDon't get attached. You know the rules.",
                Strings("%s is officially part of the story now.",
                    tostring(routeName(key))))
        end
    end)
  
    -- NOTE: Legendary and Mythical catch blocking is enforced entirely at the
    -- throwBall level via catchDeniedReason. The engine refunds the ball and
    -- the catch never registers, so no post-catch removal is needed here.
    -- A secondary removal would incorrectly consume the ball without refund.
  
    ---------------------------------------------------------------------
    -- WHITEOUT STATE
    ---------------------------------------------------------------------
    local function hasHealthyParty(game)
        local party = game and game.save and game.save.party or {}
        for _, mon in ipairs(party) do
            if mon then
                local hp = tonumber(mon.hp or mon.currentHp or mon.health)
                if hp ~= nil then
                    if hp > 0 then return true end
                elseif mon.fainted ~= true and mon.status ~= "fainted" then
                    return true
                end
            end
        end
        return false
    end
  
    ---------------------------------------------------------------------
    -- FIELD-WHITEOUT RUN END (2.5.15)
    --
    -- Battle whiteouts already own dedicated run-ending flows below, but an
    -- overworld poison wipe never enters either battle finish path. Keep the
    -- field repair independent from Permadeath: once the engine has shown the
    -- native poison-faint sequence, suppress only its final heal-point warp and
    -- end/delete the Nuzlocke run through the same save/title policy.
    ---------------------------------------------------------------------
    mod.exports.__beta26.finishFieldWhiteoutRun = function(game)
        game = game or currentGame or mod.game
        if not game then return false end
        if game.__nuzlockeFieldWhiteoutEnding == true then return true end
        game.__nuzlockeFieldWhiteoutEnding = true

        local function returnToTitle()
            local okScreens, Screens = pcall(require, "src.ui.Screens")
            local function finishTitle()
                game.__nuzlockeFieldWhiteoutEnding = nil
                local musicOk, Music = pcall(require, "src.core.Music")
                if musicOk and Music then Music.stop() end
                if game.stack and game.stack.top then
                    while game.stack:top() do game.stack:pop() end
                    if game.makeTitleState then
                        game.stack:push(game:makeTitleState())
                    end
                end
            end
            if okScreens and Screens and game.stack then
                local screenId = mod.exports.__beta26.runtimeIsGold(game)
                    and "Gen2Credits" or "Credits"
                local okPush, ending = pcall(Screens.push, game, screenId, finishTitle)
                if okPush and ending then
                    ending.phase, ending.timer = "end_wait", 0
                    return
                end
            end
            finishTitle()
        end

        local function deleteCurrentRunSave()
            local okSave, SaveData = pcall(require, "src.core.SaveData")
            if not okSave or not SaveData then
                return false, "SaveData unavailable"
            end
            local version = game.save and game.save.version or nil
            local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
            if okVersion and GameVersion
                and type(GameVersion.get) == "function" then
                local okGet, detected = pcall(GameVersion.get)
                if okGet and detected ~= nil then version = detected end
            end
            if version == nil then return false, "game version unavailable" end

            local mainName
            if type(SaveData.saveFilename) == "function" then
                local okName, value = pcall(SaveData.saveFilename, version)
                if okName and type(value) == "string" and value ~= "" then
                    mainName = value
                end
            end
            local slot
            if type(SaveData.activeSlot) == "function" then
                local okSlot, value = pcall(SaveData.activeSlot, version)
                if okSlot then slot = value end
            end

            local deleted = false
            local detail
            if slot and type(SaveData.deleteSlot) == "function" then
                local okDelete, result, err = pcall(
                    SaveData.deleteSlot, version, slot)
                if okDelete and result == true then
                    deleted = true
                else
                    detail = tostring(err or result or "slot delete failed")
                end
            end
            if mainName and type(SaveData.persistenceFs) == "function" then
                local okFs, fs = pcall(SaveData.persistenceFs)
                if okFs and fs and type(fs.remove) == "function" then
                    pcall(fs.remove, mainName)
                    pcall(fs.remove, mainName .. ".bak")
                    pcall(fs.remove, mainName .. ".tmp")
                    if type(fs.getInfo) == "function" then
                        local okInfo, info = pcall(fs.getInfo, mainName)
                        if okInfo and info == nil then deleted = true end
                    elseif not slot then
                        deleted = true
                    end
                end
            end
            return deleted, detail
        end

        local function deleteSaveAndReturn()
            local deleted, deleteError = deleteCurrentRunSave()
            if not deleted then
                local okText, TextBox = pcall(require, "src.render.TextBox")
                if okText and TextBox and game.stack then
                    local message = Strings(
                        "SAVE DELETE FAILED.\nThis Nuzlocke run is over.\nDelete the save manually.")
                    if deleteError and deleteError ~= "" then
                        message = message .. "\n" .. tostring(deleteError)
                    end
                    game.stack:push(TextBox.new(game, message, returnToTitle))
                    return
                end
            end
            returnToTitle()
        end

        local tier = worldTier(game)
        local message
        if tier >= 3 then
            local losses = tonumber(mod.save:get("nuzlocke_losses", 0)) or 0
            local catches = countTrackerCatches()
            local badges = game.save and currentBadgeCount(game.save) or 0
            local last = mod.save:get("last_loss", {}) or {}
            message = Strings(
                "NUZLOCKE OVER\nBADGES: %d\nCAUGHT: %d  DEATHS: %d\nLAST DEATH: %s\n%s",
                badges, catches, losses, tostring(last.name or "NONE"),
                routeName(last.location or "UNKNOWN"))
        else
            message = mod.exports.__beta26.worldRuleText(
                game, "whiteout_clause", "Whiteout: the run is over.")
        end

        if type(mod.exports.__beta26.pushWorldText) == "function"
            and mod.exports.__beta26.pushWorldText(
                game, message, deleteSaveAndReturn) then
            return true
        end
        deleteSaveAndReturn()
        return true
    end
  
    ---------------------------------------------------------------------
    -- FIELD-POISON PERMADEATH
    --
    -- Gen1Recomp applies overworld poison outside the battle faint lifecycle:
    -- R/B/Y mutates party HP in OverworldState:applyFieldPoison, while Gold's
    -- StepEvents produces poisonFaint events consumed by World:poisonFaintScript.
    -- Neither path emits battle.fainted. Record the death here, then prune the
    -- actual party member before any later native blackout heal can revive it.
    -- Native poison SFX/text/whiteout flow remains owned by the engine.
    ---------------------------------------------------------------------
    mod.exports.__beta26.recordFieldPoisonDeath = function(game, mon)
        if not (game and mon and active(game, nil)) then return false end
        if mod.save:get("permadeath", true) ~= true or mon.nuzlockeDead then
            return false
        end

        local key = areaKey(game, nil)
        local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(
            game, mon.species)
        local monLabel = tostring(mon.nickname or glitch.label or "Pokemon")
        local causeText = monLabel .. " died from poison in the field."

        mon.nuzlockeDead = true
        mon.deathLocation = key
        mon.deathCause = causeText
        mon.deathCauseText = causeText
        mon.deathEncounterType = "field"
        mon.deathOpponentSpecies = nil
        mon.deathMove = nil
        mon.deathCritical = false
        mon.deathStatusCondition = "POISON"

        local history = mod.save:get("nuzlocke_history", {})
        if type(history) ~= "table" then history = {} end
        table.insert(history, {
            name = mon.nickname or glitch.label,
            species = glitch.key,
            rawSpecies = glitch.isGlitch and mon.species or nil,
            glitch = glitch.isGlitch or nil,
            missingNo = glitch.missingNo or nil,
            pokemonId = Identity.ensurePokemonIdentity(
                mon, game.save or currentSave, mon.nuzlockeOrigin or "NORMAL"),
            catchLocation = mon.catchLocation,
            encounterType = mon.encounterType,
            status = "DEAD",
            deathLocation = key,
            deathCause = causeText,
            deathStatusCondition = "POISON",
        })
        mod.save:set("nuzlocke_history", history)
        if type(mod.exports.__beta26.syncTrackerDeathProjection) == "function" then
            pcall(mod.exports.__beta26.syncTrackerDeathProjection)
        end

        mod.save:set("nuzlocke_losses",
            (tonumber(mod.save:get("nuzlocke_losses", 0)) or 0) + 1)
        mod.save:set("last_loss", {
            name = mon.nickname or glitch.label,
            species = glitch.key,
            rawSpecies = glitch.isGlitch and mon.species or nil,
            glitch = glitch.isGlitch or nil,
            missingNo = glitch.missingNo or nil,
            pokemonId = Identity.pokemonIdentity(mon),
            location = key,
            cause = causeText,
        })
        return true
    end

    mod.exports.__beta26.pruneFieldPoisonDeaths = function(party, deaths)
        if type(party) ~= "table" or type(deaths) ~= "table" then return end
        for i = #party, 1, -1 do
            if deaths[party[i]] == true then table.remove(party, i) end
        end
    end

    mod.exports.__beta26.installRbyFieldPoisonPermadeathGate = function()
        local game = currentGame or mod.game
        if not game or mod.exports.__beta26.runtimeIsGold(game) then
            return false
        end
        local okWorld, OverworldState = pcall(
            require, "src.world.OverworldController")
        if not okWorld or type(OverworldState) ~= "table"
            or type(OverworldState.applyFieldPoison) ~= "function" then
            return false
        end

        local poisonInstalled = installOwnedMethodWrapper(
            OverworldState, "__nuzlockeFieldPoisonPermadeathSession",
            "applyFieldPoison", function(previous)
                return function(self, ...)
                    local liveGame = currentGame or mod.game
                    local party = liveGame and liveGame.save and liveGame.save.party
                    local watched = {}
                    if type(party) == "table" and active(liveGame, nil)
                        and mod.save:get("permadeath", true) == true then
                        for _, mon in ipairs(party) do
                            local hp = type(mon) == "table"
                                and tonumber(mon.hp or mon.currentHp or mon.health)
                                or nil
                            if hp and hp > 0 then watched[#watched + 1] = mon end
                        end
                    end

                    local result = previous(self, ...)

                    if #watched > 0 then
                        local deaths = {}
                        for _, mon in ipairs(watched) do
                            local hp = tonumber(
                                mon.hp or mon.currentHp or mon.health)
                            if hp and hp <= 0 then
                                local recorded =
                                    mod.exports.__beta26.recordFieldPoisonDeath(
                                        liveGame, mon)
                                if recorded or mon.nuzlockeDead == true then
                                    deaths[mon] = true
                                end
                            end
                        end
                        mod.exports.__beta26.pruneFieldPoisonDeaths(party, deaths)
                    end

                    -- applyFieldPoison returns true only when its poison-faint /
                    -- blackout text owns the step. Mark the final warp for
                    -- interception after the engine has finished those native
                    -- messages. This check is independent of Permadeath.
                    if result == true and self and active(liveGame, nil)
                        and mod.save:get("whiteout_clause", false) == true
                        and not hasHealthyParty(liveGame) then
                        self.__nuzlockeFieldPoisonWhiteoutPending = true
                    end
                    return result
                end
            end)

        local warpInstalled = false
        if type(OverworldState.warpToHealPoint) == "function" then
            warpInstalled = installOwnedMethodWrapper(
                OverworldState, "__nuzlockeFieldPoisonWarpSession29315",
                "warpToHealPoint", function(previousWarp)
                    return function(self, ...)
                        local liveGame = currentGame or mod.game
                        if self
                            and self.__nuzlockeFieldPoisonWhiteoutPending == true then
                            self.__nuzlockeFieldPoisonWhiteoutPending = nil
                            if active(liveGame, nil)
                                and mod.save:get("whiteout_clause", false) == true
                                and mod.exports.__beta26.finishFieldWhiteoutRun(
                                    liveGame) then
                                return true
                            end
                        end
                        return previousWarp(self, ...)
                    end
                end)
        end
        return poisonInstalled and warpInstalled
    end

    ---------------------------------------------------------------------
    -- PERMADEATH / WHITEOUT ENFORCEMENT
    --
    -- Use BattleState:onFaint itself, following Bryan's implementation seam.
    -- This is important because the battle's own faint lifecycle is the point
    -- where the last usable party member is determined. The previous event-only
    -- implementation could lose the race with the vanilla blackout/restore
    -- flow, which is why a trainer loss could appear to revive the party.
    ---------------------------------------------------------------------
    -- 2.3.11: phase 1 itself now activates at game.ready, so install this
    -- battle patch directly instead of subscribing too late to the event
    -- currently being dispatched. Keep it in its own function so historical
    -- early returns cannot abort the remainder of late runtime phase 1.
    local function installPermadeathWhiteoutGate()
        local ok, BattleState = pcall(require, "src.battle.BattleState")
        local okRuntime, Runtime = pcall(require, "src.mods.Runtime")
        local okScreens, Screens = pcall(require, "src.ui.Screens")
        local okSave, SaveData = pcall(require, "src.core.SaveData")
        local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
  
        if not ok or type(BattleState) ~= "table"
            or type(BattleState.onFaint) ~= "function"
            or type(BattleState.playerMonFainted) ~= "function"
            or type(BattleState.finish) ~= "function" then
            return
        end
        -- 2.5.14 lifecycle hardening. A previous gameplay/Save Editor loader
        -- can leave these module tables alive after its mod instance is gone.
        -- Unwrap only a wrapper that is still exactly the old Nuzlocke top
        -- level; never overwrite a function another mod installed above it.
        local priorCatchFinish = BattleState.__nuzlockeCatchFinishSession
        if type(priorCatchFinish) == "table"
            and priorCatchFinish.owner ~= mod
            and BattleState.finish == priorCatchFinish.wrapper
            and type(priorCatchFinish.previous) == "function" then
            BattleState.finish = priorCatchFinish.previous
        end

        local priorSession = BattleState.__nuzlockePermadeathSession
        local priorSessionLive = type(priorSession) == "table"
            and priorSession.owner == mod
        if priorSessionLive then
            for method, rec in pairs(priorSession.methods or {}) do
                if type(rec) ~= "table" or BattleState[method] ~= rec.wrapper then
                    priorSessionLive = false
                    break
                end
            end
            local status = priorSession.status
            if priorSessionLive and type(status) == "table"
                and type(status.module) == "table"
                and status.module[status.method] ~= status.wrapper then
                priorSessionLive = false
            end
        end
        if priorSessionLive then
            return
        elseif type(priorSession) == "table" then
            for method, rec in pairs(priorSession.methods or {}) do
                if type(rec) == "table" and BattleState[method] == rec.wrapper
                    and type(rec.previous) == "function" then
                    BattleState[method] = rec.previous
                end
            end
            local status = priorSession.status
            if type(status) == "table" and type(status.module) == "table"
                and status.module[status.method] == status.wrapper
                and type(status.previous) == "function" then
                status.module[status.method] = status.previous
            end
            if type(status) == "table" and type(status.module) == "table" then
                status.module.__nuzlockeDeathStatusPatched = nil
            end
            BattleState.__nuzlockePermadeathSession = nil
            BattleState.__nuzlockeDamagePatched = nil
            BattleState.__nuzlockeFinal25FaintPatched = nil
        end
        BattleState.__nuzlockeFinal25FaintPatched = true -- historical marker
        local permadeathSessionMethods = {}
        local permadeathStatusSession = nil
  
        -------------------------------------------------------------------
        -- Capture the final damaging move exactly where Gen 1 computes it.
        -- Damage.compute returns { crit = bool }, so the death record can
        -- report a real critical hit instead of guessing.
        -------------------------------------------------------------------
        if not BattleState.__nuzlockeDamagePatched
            and type(BattleState.computeDamage) == "function" then
            BattleState.__nuzlockeDamagePatched = true
            local vanillaComputeDamage = BattleState.computeDamage
            BattleState.computeDamage = function(self, user, target, move, opts)
                local damage, result = vanillaComputeDamage(self, user, target, move, opts)
                if target and target.isPlayer and tonumber(damage) and damage > 0 then
                    self.nuzlockeLastDamage = {
                        target = target,
                        attacker = user,
                        move = move and (move.name or move.id) or "UNKNOWN",
                        moveId = move and move.id,
                        critical = result and result.crit == true or false,
                    }
                end
                return damage, result
            end
            permadeathSessionMethods.computeDamage = {
                previous = vanillaComputeDamage, wrapper = BattleState.computeDamage,
            }
        end
  
        -------------------------------------------------------------------
        -- Status/residual deaths are recorded before BattleState:onFaint is
        -- reached, so poison/burn/Leech Seed can be distinguished from the
        -- previous damaging move.
        -------------------------------------------------------------------
        local okStatus, StatusModule = pcall(require, "src.battle.Status")
        if okStatus and type(StatusModule) == "table"
            and type(StatusModule.residual) == "function"
            and not StatusModule.__nuzlockeDeathStatusPatched then
            StatusModule.__nuzlockeDeathStatusPatched = true
            local vanillaResidual = StatusModule.residual
            StatusModule.residual = function(battler, opponent, battle, ...)
                local before = battler and battler.mon and tonumber(battler.mon.hp) or nil
                local result = vanillaResidual(battler, opponent, battle, ...)
                if battler and battler.isPlayer and battler.mon then
                    local after = tonumber(battler.mon.hp)
                    if before and after and before > 0 and after <= 0 then
                        local status = tostring(battler.mon.status or "")
                        local label = nil
                        if status == "POISON" or status == "PSN" or status == "BADLY_POISONED" or status == "TOX" then
                            label = "POISON"
                        elseif status == "BURN" or status == "BRN" then
                            label = "BURN"
                        elseif battler.leechSeeded then
                            label = "LEECH SEED"
                        end
                        battle.nuzlockeLastResidual = label or "STATUS DAMAGE"
                    end
                end
                return result
            end
            permadeathStatusSession = {
                module = StatusModule, method = "residual",
                previous = vanillaResidual, wrapper = StatusModule.residual,
            }
        end
  
        local vanillaOnFaint = BattleState.onFaint
        BattleState.onFaint = function(self, battler)
            if not (battler and battler.isPlayer and active(self.game, self)) then
                return vanillaOnFaint(self, battler)
            end
  
            -- The opening Rival exception leaves the native faint/loss flow
            -- intact but skips every Nuzlocke-owned death and Whiteout mutation.
            -- This applies to all player Pokemon in that one battle only.
            if mod.exports.__beta26.isFirstRivalForgivenessActive(
                self.game, self) then
                if battler.mon then battler.mon.nuzlockeRivalForgiven = true end
                self.nuzlockeRivalForgivenessTriggered = true
                return vanillaOnFaint(self, battler)
            end
  
            if mod.save:get("permadeath", true) then
                local mon = battler.mon
                if mon and not mon.nuzlockeDead then
                    local key = areaKey(self.game, nil)
                    local enemy = self.enemy and self.enemy.mon
                    local enemyName = self.enemy and self.enemy.name
                    local enemySpecies = enemyName or (enemy and enemy.species) or "BATTLE"
                    local source = "Wild " .. tostring(enemySpecies)
                    local trainerName = self.trainer and self.trainer.name
                    local oppClass = tostring(self.oppClass or "")
  
                    if self.kind == "trainer" then
                        local upperClass = oppClass:upper()
                        if upperClass:find("RIVAL", 1, true) then
                            source = "Your Rival " .. tostring(trainerName or "BLUE") .. "'s " .. tostring(enemySpecies)
                        elseif upperClass:find("BROCK", 1, true)
                            or upperClass:find("MISTY", 1, true)
                            or upperClass:find("LT_SURGE", 1, true)
                            or upperClass:find("ERIKA", 1, true)
                            or upperClass:find("KOGA", 1, true)
                            or upperClass:find("SABRINA", 1, true)
                            or upperClass:find("BLAINE", 1, true)
                            or upperClass:find("GIOVANNI", 1, true) then
                            source = "Gym Leader " .. tostring(trainerName or oppClass) .. "'s " .. tostring(enemySpecies)
                        elseif upperClass:find("LORELEI", 1, true)
                            or upperClass:find("BRUNO", 1, true)
                            or upperClass:find("AGATHA", 1, true)
                            or upperClass:find("LANCE", 1, true) then
                            source = "Elite Four " .. tostring(trainerName or oppClass) .. "'s " .. tostring(enemySpecies)
                        elseif upperClass:find("ROCKET", 1, true) then
                            source = "Team Rocket " .. tostring(trainerName or "Trainer") .. "'s " .. tostring(enemySpecies)
                        elseif trainerName then
                            source = tostring(trainerName) .. "'s " .. tostring(enemySpecies)
                        else
                            source = "Trainer's " .. tostring(enemySpecies)
                        end
                    end
  
                    local damage = self.nuzlockeLastDamage
                    local glitch = mod.exports.__beta26.getGlitchSpeciesInfo(
                        self.game, mon.species)
                    local monLabel = tostring(mon.nickname or glitch.label or "Pokemon")
                    local causeText
                    if self.nuzlockeLastResidual then
                        causeText = monLabel
                            .. " died to " .. source
                            .. " after " .. tostring(self.nuzlockeLastResidual) .. "."
                    elseif damage and damage.target == battler then
                        local moveName = tostring(damage.move or "UNKNOWN")
                        local critPrefix = damage.critical and "a critical " or ""
                        if damage.attacker == battler then
                            causeText = monLabel
                                .. " died after " .. critPrefix .. moveName .. "."
                        else
                            causeText = monLabel
                                .. " died to " .. source
                                .. " after " .. critPrefix .. moveName .. "."
                        end
                    else
                        causeText = monLabel
                            .. " died in battle against " .. source .. "."
                    end
  
                    mon.nuzlockeDead = true
                    mon.deathLocation = key
                    mon.deathCause = causeText
                    mon.deathCauseText = causeText
                    mon.deathEncounterType =
                        (self.kind == "trainer") and "trainer" or "wild"
                    mon.deathOpponentSpecies = enemySpecies
                    mon.deathMove = damage and damage.move or nil
                    mon.deathCritical = damage and damage.critical == true or false
                    mon.deathStatusCondition = self.nuzlockeLastResidual
  
                    local history = mod.save:get("nuzlocke_history", {})
                    if type(history) ~= "table" then history = {} end
                    table.insert(history, {
                        name = mon.nickname or glitch.label,
                        species = glitch.key,
                        rawSpecies = glitch.isGlitch and mon.species or nil,
                        glitch = glitch.isGlitch or nil,
                        missingNo = glitch.missingNo or nil,
                        pokemonId = Identity.ensurePokemonIdentity(mon, currentSave, mon.nuzlockeOrigin or "NORMAL"),
                        catchLocation = mon.catchLocation,
                        encounterType = mon.encounterType,
                        status = "DEAD",
                        deathLocation = key,
                        deathCause = causeText,
                        deathOpponentSpecies = enemySpecies,
                        deathMove = mon.deathMove,
                        deathCritical = mon.deathCritical,
                        deathStatusCondition = mon.deathStatusCondition,
                    })
                    mod.save:set("nuzlocke_history", history)
                    if type(mod.exports.__beta26.syncTrackerDeathProjection) == "function" then
                        pcall(mod.exports.__beta26.syncTrackerDeathProjection)
                    end

                    mod.save:set(
                        "nuzlocke_losses",
                        (tonumber(mod.save:get("nuzlocke_losses", 0)) or 0) + 1
                    )
  
                    mod.save:set("last_loss", {
                        name = mon.nickname or glitch.label,
                        species = glitch.key,
                        rawSpecies = glitch.isGlitch and mon.species or nil,
                        glitch = glitch.isGlitch or nil,
                        missingNo = glitch.missingNo or nil,
                        pokemonId = Identity.pokemonIdentity(mon),
                        location = key,
                        cause = causeText,
                    })
  
                    worldMechanic(self.game, "death:" .. monLabel .. ":" .. tostring(key),
                        Strings("%s has fallen.\nThe Nuzlocke remembers.", monLabel),
                        "Ouch. Another one bites the dust.\nYou knew the rules.",
                        Strings("RIP, %s.\nKanto won't forget what happened here.",
                            monLabel))
  
                    -- Remove the dead mon before vanilla's playerMonFainted()
                    -- checks for a usable party. This prevents the normal
                    -- blackout routine from healing/restoring a dead member.
                    if self.game and self.game.save and self.game.save.party then
                        for i, partyMon in ipairs(self.game.save.party) do
                            if partyMon == mon then
                                table.remove(self.game.save.party, i)
                                break
                            end
                        end
                    end
                end
  
            end
  
            -- These are transient battle facts, not Permadeath state. Clear them
            -- after every player faint so toggling rules cannot reuse stale data.
            self.nuzlockeLastDamage = nil
            self.nuzlockeLastResidual = nil
  
            -- Whiteout is an independent rule: with Permadeath OFF a full party
            -- faint still ends the run; with Permadeath ON removed dead Pokemon
            -- naturally produce the same result.
            if mod.save:get("whiteout_clause", false)
                and not hasHealthyParty(self.game) then
                self.nuzlockeGameOver = true
            end
  
            -- Preserve the engine's normal faint animation, cry, text, and
            -- battle queue. We only alter the save/party state before it runs.
            return vanillaOnFaint(self, battler)
        end
        permadeathSessionMethods.onFaint = {
            previous = vanillaOnFaint, wrapper = BattleState.onFaint,
        }
  
        local vanillaPlayerFainted = BattleState.playerMonFainted
        BattleState.playerMonFainted = function(self)
            if self.nuzlockeGameOver then
                -- Keep the public battle result inside the engine's standard
                -- result vocabulary. The separate flag owns Nuzlocke teardown.
                self.result = "lose"
                self.afterQueue = "finish"
                -- Try every known message API in priority order.
                local msg = mod.exports.__beta26.worldRuleText(
                    self.game, "whiteout_clause",
                    "Whiteout: the run is over.")
                if worldTier(self.game) >= 3 then
                    local losses = tonumber(mod.save:get("nuzlocke_losses", 0)) or 0
                    msg = Strings("%s\nDEATHS: %d", tostring(msg), losses)
                end
                if type(self.sayNext) == "function" then
                    pcall(self.sayNext, self, msg)
                elseif type(self.say) == "function" then
                    pcall(self.say, self, msg)
                elseif type(self.message) == "function" then
                    pcall(self.message, self, msg)
                end
                return
            end
            return vanillaPlayerFainted(self)
        end
        permadeathSessionMethods.playerMonFainted = {
            previous = vanillaPlayerFainted, wrapper = BattleState.playerMonFainted,
        }
  
        -- 2.5.5 First Rival Mercy hardening.
        -- Runtime Blue 2.5.4 showed the mercy message but the opening loss could
        -- still fall into destructive/restart behavior. The native Oak-lab
        -- script owns the correct loss continuation (heal party + set
        -- EVENT_BATTLED_RIVAL_IN_OAKS_LAB), so preserve that callback chain and
        -- make the Nuzlocke invariant explicit before finish() decides anything.
        local function restoreFirstRivalMercyParty(battle)
            if type(battle) ~= "table"
                or battle.nuzlockeRivalForgivenessTriggered ~= true then
                return false
            end
            battle.nuzlockeGameOver = nil
            battle.nuzlockeRunEnded = nil

            local save = battle.game and battle.game.save
            local party = save and save.party
            local playerMon = battle.player and battle.player.mon
            if type(playerMon) == "table"
                and playerMon.nuzlockeRivalForgiven == true then
                playerMon.nuzlockeDead = nil
                playerMon.deathLocation = nil
                playerMon.deathCause = nil
                playerMon.deathCauseText = nil
                playerMon.deathEncounterType = nil
                playerMon.deathOpponentSpecies = nil
                playerMon.deathMove = nil
                playerMon.deathCritical = nil
                playerMon.deathStatusCondition = nil
                if (tonumber(playerMon.hp) or 0) <= 0 then
                    playerMon.hp = 1
                end
                if type(party) == "table" then
                    local present = false
                    for _, mon in ipairs(party) do
                        if mon == playerMon then present = true break end
                    end
                    if not present then
                        table.insert(party, 1, playerMon)
                    end
                end
            end
            return true
        end
        mod.exports.__beta26.restoreFirstRivalMercyParty =
            restoreFirstRivalMercyParty

        -- Whiteout is still a Nuzlocke-specific run-ending flow, but battle
        -- teardown itself belongs to the engine. Call through the already-wrapped
        -- finish() chain so Mimic restoration, low-health alarm shutdown, map
        -- music restoration, stack pop, battle.ended, and our catch finalizer all
        -- execute exactly once. Suppress only onFinish so vanilla's normal
        -- blackout/heal-point warp does not run before we delete the ended run.
        local vanillaFinish = BattleState.finish
        BattleState.finish = function(self)
            if self.nuzlockeRivalForgivenessTriggered == true then
                restoreFirstRivalMercyParty(self)
            end
            if not self.nuzlockeGameOver then
                -- REVIEWED: battle.ended fires before the engine invokes the
                -- battle's onFinish callback. A scripted trainer/gym callback
                -- can therefore restore or replace party state after our normal
                -- battle.ended prune has already run. Prune once more after the
                -- complete native finish/onFinish chain so a dead Pokemon cannot
                -- be reinserted and later healed back into service.
                local results = { vanillaFinish(self) }
                if self.nuzlockeRivalForgivenessTriggered ~= true
                    and mod.save:get("nuzlocke_enabled", true) == true
                    and mod.save:get("permadeath", true) == true then
                    pruneRestoredDeadPokemon(self.game)
                end
                return unpack(results)
            end
  
            self.nuzlockeGameOver = nil
            self.nuzlockeRunEnded = true
            self.result = "lose"
  
            local savedOnFinish = self.onFinish
            self.onFinish = nil
            local finishOk = pcall(vanillaFinish, self)
            self.onFinish = savedOnFinish
  
            -- battle.ended has now run. A composable format mod may have restored
            -- healthy reserve Pokemon that were temporarily outside the battle
            -- party. Re-prune any restored dead Pokemon, then re-evaluate the
            -- destructive Whiteout decision against the real post-battle party.
            -- If a healthy reserve exists, this was an ordinary battle loss, not
            -- a Nuzlocke Whiteout: resume the engine's normal loss callback once.
            if finishOk then
                pruneRestoredDeadPokemon(self.game)
                if hasHealthyParty(self.game) then
                    self.nuzlockeRunEnded = nil
                    if savedOnFinish then pcall(savedOnFinish, "lose") end
                    return
                end
            end
  
            if not finishOk then
                -- Defensive fallback for an engine/API mismatch. Only reproduce
                -- the minimum teardown needed to avoid leaving a dead battle on
                -- the stack; do not synthesize a second public event if vanilla
                -- already managed to emit one before throwing.
                if type(finalizeNuzlockeBattle) == "function" then
                    pcall(finalizeNuzlockeBattle, self, "lose")
                end
                if self.game and self.game.stack
                    and self.game.stack.top and self.game.stack:top() == self then
                    pcall(function() self.game.stack:pop() end)
                end
            end
  
            local function showCreditsAndTitle()
                if okScreens and Screens then
                    local ending = Screens.push(self.game, "Credits", function()
                        local musicOk, Music = pcall(require, "src.core.Music")
                        if musicOk and Music then Music.stop() end
                        while self.game.stack:top() do self.game.stack:pop() end
                        if self.game.makeTitleState then
                            self.game.stack:push(self.game:makeTitleState())
                        end
                    end)
                    if ending then ending.phase, ending.timer = "end_wait", 0 end
                end
            end
  
            local function deleteCurrentRunSave()
                if not (okSave and SaveData) then
                    return false, "SaveData unavailable"
                end
  
                local version = self.game and self.game.save
                    and self.game.save.version or nil
                if okVersion and GameVersion
                    and type(GameVersion.get) == "function" then
                    local okGet, detected = pcall(GameVersion.get)
                    if okGet and detected ~= nil then version = detected end
                end
                if version == nil then
                    return false, "game version unavailable"
                end
  
                -- Capture the exact current path before deleteSlot changes the
                -- active-slot registry to a different surviving slot.
                local mainName
                if type(SaveData.saveFilename) == "function" then
                    local okName, value = pcall(SaveData.saveFilename, version)
                    if okName and type(value) == "string" and value ~= "" then
                        mainName = value
                    end
                end
  
                local slot
                if type(SaveData.activeSlot) == "function" then
                    local okSlot, value = pcall(SaveData.activeSlot, version)
                    if okSlot then slot = value end
                end
  
                local deleted = false
                local detail
  
                if slot and type(SaveData.deleteSlot) == "function" then
                    local okDelete, result, err =
                        pcall(SaveData.deleteSlot, version, slot)
                    if okDelete and result == true then
                        deleted = true
                    else
                        detail = tostring(err or result or "slot delete failed")
                    end
                end
  
                -- activeSlot() may legitimately be nil for an unmigrated legacy
                -- flat save. This fallback also handles a registered slot whose
                -- registry delete failed: remove only the path captured above.
                if mainName and type(SaveData.persistenceFs) == "function" then
                    local okFs, fs = pcall(SaveData.persistenceFs)
                    if okFs and fs and type(fs.remove) == "function" then
                        pcall(fs.remove, mainName)
                        pcall(fs.remove, mainName .. ".bak")
                        pcall(fs.remove, mainName .. ".tmp")
  
                        if type(fs.getInfo) == "function" then
                            local okInfo, info = pcall(fs.getInfo, mainName)
                            if okInfo and info == nil then deleted = true end
                        elseif not slot then
                            -- Best effort for older persistence adapters that
                            -- expose remove but not getInfo.
                            deleted = true
                        end
                    end
                end
  
                return deleted, detail
            end
  
            local function deleteSaveAndShowTitle()
                local deleted, deleteError = deleteCurrentRunSave()
                if not deleted then
                    local okText, TextBox = pcall(require, "src.render.TextBox")
                    if okText and TextBox and self.game and self.game.stack then
                        local message = Strings("SAVE DELETE FAILED.\nThis Nuzlocke run is over.\nDelete the save manually.")
                        if deleteError and deleteError ~= "" then
                            message = message .. "\n" .. tostring(deleteError)
                        end
                        self.game.stack:push(TextBox.new(self.game, message,
                            function() showCreditsAndTitle() end))
                        return
                    end
                end
                showCreditsAndTitle()
            end
  
            if worldTier(self.game) >= 3 then
                local losses = tonumber(mod.save:get("nuzlocke_losses", 0)) or 0
                local catches = countTrackerCatches()
                local badges = currentBadgeCount(self.game.save)
                local last = mod.save:get("last_loss", {}) or {}
                local lastName = tostring(last.name or "NONE")
                local lastLoc = routeName(last.location or "UNKNOWN")
                local summary = Strings("NUZLOCKE OVER\nBADGES: %d\nCAUGHT: %d  DEATHS: %d\nLAST DEATH: %s\n%s",
                    badges, catches, losses, lastName, lastLoc)
                if mod.exports.__beta26.pushWorldText(self.game, summary,
                    function() deleteSaveAndShowTitle() end) then
                    return
                end
            end
  
            deleteSaveAndShowTitle()
        end
        permadeathSessionMethods.finish = {
            previous = vanillaFinish, wrapper = BattleState.finish,
        }
        BattleState.__nuzlockePermadeathSession = {
            owner = mod, methods = permadeathSessionMethods,
            status = permadeathStatusSession,
        }
    end
    pcall(installPermadeathWhiteoutGate)
    pcall(mod.exports.__beta26.installRbyFieldPoisonPermadeathGate)
    mod.events:on("game.ready", function()
        pcall(mod.exports.__beta26.installRbyFieldPoisonPermadeathGate)
    end)
    mod.events:on("save.loaded", function()
        pcall(mod.exports.__beta26.installRbyFieldPoisonPermadeathGate)
    end)
    mod.events:on("mods.loaded", function()
        pcall(mod.exports.__beta26.installRbyFieldPoisonPermadeathGate)
    end)
  
    ---------------------------------------------------------------------
    -- POKé MART / POKéMON CENTER ENFORCEMENT
    --
    -- Install the live command patch as soon as the command module is
    -- available, and retry on save.loaded/game.ready.  This avoids the
    -- previous failure mode where the map scripts had already cached their
    -- command resolver before the one-time game.ready patch ran.
    ---------------------------------------------------------------------
    mod.exports.__beta26.installPartySizePCGate = function()
        if mod.exports.__beta26.isSaveEditorSession() then return true end

        local function atLimit(game)
            if not active(game, nil) then return false end
            return #(game and game.save and game.save.party or {})
                >= mod.exports.__beta26.configuredPartySizeLimit()
        end
        local function message(game)
            return mod.exports.__beta26.worldRuleText(game, "party_size_limit")
        end

        -- R/B/Y Bill's PC: the public BoxMenu.new returns a Menu whose first
        -- row owns WITHDRAW. Wrap that row rather than replacing storage code.
        local ok1, BoxMenu = pcall(require, "src.ui.BoxMenu")
        if ok1 and type(BoxMenu) == "table" and type(BoxMenu.new) == "function" then
            installOwnedMethodWrapper(
                BoxMenu, "__nuzlockePartyLimitNewSession29315", "new",
                function(previousNew)
                    return function(game, ...)
                        local menu = previousNew(game, ...)
                        if type(menu) == "table" and type(menu.items) == "table" then
                            for _, item in ipairs(menu.items) do
                                local label = tostring(item.label or ""):upper()
                                if label:find("WITHDRAW", 1, true)
                                    and type(item.onSelect) == "function" then
                                    local previous = item.onSelect
                                    item.onSelect = function(...)
                                        if atLimit(game) then
                                            local okText, TextBox = pcall(
                                                require, "src.render.TextBox")
                                            if okText and TextBox and game
                                                and game.stack then
                                                game.stack:push(TextBox.new(
                                                    game, message(game)))
                                            end
                                            return
                                        end
                                        return previous(...)
                                    end
                                    break
                                end
                            end
                        end
                        return menu
                    end
                end)
            BoxMenu.__nuzlockePartyLimit = true -- historical marker only
        end

        -- Gold has explicit withdraw and MOVE-to-party methods. Compose at the
        -- method boundaries so deposits, party-to-box moves and party swaps stay legal.
        local ok2, G2Box = pcall(require, "src.ui.gen2.BoxMenu")
        if ok2 and type(G2Box) == "table" then
            if type(G2Box.doWithdraw) == "function" then
                installOwnedMethodWrapper(
                    G2Box, "__nuzlockePartyLimitWithdrawSession29315",
                    "doWithdraw", function(previousWithdraw)
                        return function(self, ...)
                            local game = self and self.game
                            if atLimit(game) then
                                self.message = message(game)
                                return
                            end
                            return previousWithdraw(self, ...)
                        end
                    end)
            end
            if type(G2Box.checkSpaceInDestination) == "function" then
                installOwnedMethodWrapper(
                    G2Box, "__nuzlockePartyLimitSpaceSession29315",
                    "checkSpaceInDestination", function(previousSpace)
                        return function(self, ...)
                            local from = self and self.moveFrom
                            local destinationIsParty = self and self.isParty
                                and self:isParty(self.boxIndex)
                            local sourceIsParty = from and self and self.isParty
                                and self:isParty(from.box)
                            if destinationIsParty and not sourceIsParty
                                and atLimit(self and self.game) then
                                return false, message(self and self.game)
                            end
                            return previousSpace(self, ...)
                        end
                    end)
            end
            G2Box.__nuzlockePartyLimit = true -- historical marker only
        end
        return true
    end

    local function installNuzlockeFieldCommandPatches()
        if mod.exports.__beta26.isSaveEditorSession() then return true end
        if mod.exports.__beta26.runtimeIsGold(currentGame or mod.game) then
            return true
        end
        local Commands = mod.exports.__beta26.rbyCommandsFor(currentGame or mod.game)
        if not Commands then return false end

        -- Keep these predicates inside the installer. Cross-phase local helper
        -- references compile as globals in Lua 5.1, so a lifecycle split must
        -- never be able to strand the Mom/Center wrappers from their map test.
        local function commandMapTag(ctx)
            local ow = (ctx and ctx.overworld)
                or (currentGame and currentGame.overworld)
            local map = ow and ow.map
            local def = map and map.def
            local parts = {
                map and map.id, map and map.name,
                def and def.id, def and def.name, def and def.label,
            }
            local out = {}
            for _, value in ipairs(parts) do
                if value ~= nil then out[#out + 1] = tostring(value):upper() end
            end
            return table.concat(out, " ")
        end
        local function isPokemonCenterMap(ctx)
            local tag = commandMapTag(ctx)
            return (tag:find("POKEMON", 1, true) and tag:find("CENTER", 1, true))
                or (tag:find("POKE", 1, true) and tag:find("CENTER", 1, true))
        end
        local function isMomsHouseMap(ctx)
            local tag = commandMapTag(ctx)
            return tag:find("REDS_HOUSE", 1, true) ~= nil
                or tag:find("REDSHOUSE", 1, true) ~= nil
        end
  
        local priorSession = Commands.__nuzlockeRulesSession
        if type(priorSession) == "table" and priorSession.owner == mod then
            -- 2.4.94: an owner marker is not proof that the live command
            -- functions are still our wrappers. Current Gen1Recomp and other
            -- mods may rebind Commands after our first install. The old
            -- unconditional early-return left Mom's heal_party/fade path
            -- unguarded while the stale marker still claimed success.
            local healthy = true
            for name, rec in pairs(priorSession.methods or {}) do
                if type(rec) == "table" and type(rec.wrapper) == "function"
                    and Commands[name] ~= rec.wrapper then
                    healthy = false
                    break
                end
            end
            if healthy then return true end

            -- Remove only wrappers that are still exactly ours. Never stomp a
            -- function that another mod has composed above/replaced. The fresh
            -- install below wraps whatever the current live top-level is.
            for name, rec in pairs(priorSession.methods or {}) do
                if type(rec) == "table" and Commands[name] == rec.wrapper
                    and type(rec.previous) == "function" then
                    Commands[name] = rec.previous
                end
            end
            Commands.__nuzlockeRulesSession = nil
            Commands.__nuzlockeRulesPatched = nil
            Commands.__nuzlockeRulesOwner = nil
        elseif type(priorSession) == "table" and priorSession.owner ~= mod then
            for name, rec in pairs(priorSession.methods or {}) do
                if type(rec) == "table" and Commands[name] == rec.wrapper
                    and type(rec.previous) == "function" then
                    Commands[name] = rec.previous
                end
            end
        end
  
        local sessionMethods = {}
        local originalHeal = Commands.heal_party
        local originalFade = Commands.fade
        local originalTrade = Commands.trade
        local originalGivePokemon = Commands.give_pokemon
        local originalStaticBattle = Commands.static_battle
        if type(originalHeal) ~= "function" then
            return false
        end
  
        local function showRuleMessage(ctx, msg)
            -- One Nuzlocke denial/flavor box per ScriptRunner transaction.
            -- Several compatibility seams can observe the same interaction;
            -- once one of them owns the response the others must stay silent.
            if ctx and ctx.__nuzlockeRuleMessageShown == true then return false end
            msg = mod.exports.__beta26.formatWorldText(msg)
            local shown = false
            if type(Commands.show_text) == "function" then
                local ok = pcall(Commands.show_text, ctx, msg)
                shown = ok
            elseif type(Commands.text) == "function" then
                local ok = pcall(Commands.text, ctx, msg)
                shown = ok
            elseif type(Commands.message) == "function" then
                local ok = pcall(Commands.message, ctx, msg)
                shown = ok
            end
  
            if not shown then
                local game = ctx and (ctx.game or (ctx.env and ctx.env.game))
                if game and game.stack then
                    local okText, TextBox = pcall(require, "src.render.TextBox")
                    if okText and TextBox then
                        local okPush = pcall(function()
                            game.stack:push(TextBox.new(game, msg))
                        end)
                        shown = okPush == true
                    end
                end
            end
            if shown and ctx then ctx.__nuzlockeRuleMessageShown = true end
            return shown
        end
  
        -- Hook callbacks run inside the hook bus's protected call, so they must
        -- not yield.  Push the TextBox directly here; the hook returns "end"
        -- and the script is finished underneath it.
        local function showRuleMessageImmediate(ctx, msg)
            if ctx and ctx.__nuzlockeRuleMessageShown == true then return false end
            msg = mod.exports.__beta26.formatWorldText(msg)
            local game = ctx and (ctx.game or (ctx.env and ctx.env.game))
            if not game or not game.stack then return false end
            local okText, TextBox = pcall(require, "src.render.TextBox")
            if okText and TextBox then
                local okPush = pcall(function()
                    game.stack:push(TextBox.new(game, msg))
                end)
                if okPush and ctx then ctx.__nuzlockeRuleMessageShown = true end
                return okPush == true
            end
            return false
        end
  
        local function acquisitionDeniedMessage(kind, reason, area)
            local game = currentGame or mod.game
            if reason == "disabled" then
                return mod.exports.__beta26.worldRuleText(
                    game, kind == "trade" and "allow_trades" or "allow_gifts")
            elseif reason == "area" then
                local areaName = routeName(area or "UNKNOWN")
                local base = mod.exports.__beta26.worldRuleText(
                    game, "encounter_area")
                return Strings("%s\n%s", tostring(base), tostring(areaName))
            elseif reason == "party_size" then
                return mod.exports.__beta26.worldRuleText(game, "party_size_limit")
            elseif reason == "type_lock" then
                return mod.exports.__beta26.catchRejectionMessage(game, "type_lock", nil)
            elseif reason == "legendary" then
                return mod.exports.__beta26.worldRuleText(game, "ban_legendaries")
            elseif reason == "mythical" then
                return mod.exports.__beta26.worldRuleText(game, "ban_mythicals")
            elseif reason == "pseudo" then
                return mod.exports.__beta26.worldRuleText(game, "ban_pseudos")
            elseif reason == "bst" then
                return mod.exports.__beta26.worldRuleText(game, "maximum_bst")
            elseif reason == "glitch" then
                return mod.exports.__beta26.worldRuleText(game, "allow_glitch_pokemon")
            end
            return Strings("This Pokemon is blocked by your Nuzlocke rules.")
        end
  
        -- Native in-game trade gate. The engine's Commands.trade removes the
        -- selected outgoing Pokemon and creates the incoming Pokemon in one
        -- transaction. Reject before calling it; never try to reconstruct the
        -- outgoing Pokemon afterward.
        local function nuzlockeTrade(ctx, tradeIndex, doneFlag)
            if type(originalTrade) ~= "function" then return end
  
            local game = ctx and ctx.game
            local trade = game and game.data and game.data.field
                and game.data.field.trades
                and game.data.field.trades[tradeIndex]
            if not trade or not active(game, nil) then
                return originalTrade(ctx, tradeIndex, doneFlag)
            end
  
            local receivedSpecies = tostring(trade.get or ""):upper()
            local area = mod.exports.__beta26.currentSpecialArea(game, receivedSpecies, "trade")
            local denied = specialAcquisitionDenied(
                game, receivedSpecies, area, "trade")
  
            if denied then
                showRuleMessage(ctx,
                    acquisitionDeniedMessage("trade", denied, area))
                return
            end
  
            -- Snapshot object identities before the transaction. Commands.trade
            -- creates a fresh Pokemon table for the received mon.
            local before = {}
            for _, mon in ipairs(ctx.save and ctx.save.party or {}) do
                before[mon] = true
            end
  
            local result = originalTrade(ctx, tradeIndex, doneFlag)
  
            local received
            for _, mon in ipairs(ctx.save and ctx.save.party or {}) do
                if not before[mon]
                    and tostring(mon and mon.species or ""):upper()
                        == receivedSpecies then
                    received = mon
                    break
                end
            end
  
            if received then
                mod.exports.__beta26.StatRules.applyPlayer(game, received)
                mod.exports.__beta26.registerSpecialCatch(receivedSpecies, area, "trade", received)
            end
            return result
        end
  
        -- Native scripted gift gate. give_pokemon mutates party/boxes and many
        -- giver scripts set one-time flags afterward, so reject before entering
        -- the vanilla command. Starters are deliberately exempt.
        local function nuzlockeGivePokemon(ctx, species, level, skipNickname)
            if type(originalGivePokemon) ~= "function" then return end
            local game = ctx and ctx.game
            if not active(game, nil) then
                return originalGivePokemon(ctx, species, level, skipNickname)
            end
  
            local sp = tostring(species or ""):upper()
            local save = ctx and ctx.save
            local loc = areaKey(game, nil)
            local locText = tostring(loc or ""):upper()
            local ctxArea = tostring((ctx and (ctx.mapId or ctx.map))
                or (ctx and ctx.overworld and ctx.overworld.map
                    and ctx.overworld.map.id)
                or (save and save.player and save.player.map)
                or ""):upper()
            local starterLocation = loc == "PALLET_TOWN"
                or locText:find("OAK", 1, true) ~= nil
                or locText:find("LAB", 1, true) ~= nil
                or ctxArea == "PALLET_TOWN"
                or ctxArea:find("OAK", 1, true) ~= nil
                or ctxArea:find("LAB", 1, true) ~= nil
            local flags = save and save.flags or {}
            local gotStarter = flags.EVENT_GOT_STARTER == true
                or tonumber(flags.EVENT_GOT_STARTER) == 1
            local gotDex = flags.EVENT_GOT_POKEDEX == true
                or tonumber(flags.EVENT_GOT_POKEDEX) == 1
            local partyCount = type(save and save.party) == "table"
                and #save.party or 0
            -- PokemonRecompRandomizer may replace Oak's mandatory starter with
            -- any eligible species. During the opening Oak/Pallet transaction,
            -- an empty party before the starter event is enough story context
            -- to identify it without trusting the vanilla species family.
            local openingStarter = starterLocation and not gotStarter
                and not gotDex and partyCount == 0
            local starter = openingStarter or (starterLocation
                and (mod.exports.__beta26.isStarterSpecies(sp)
                    or (getGameVersion() == "YELLOW" and sp == "PIKACHU")))
  
            if not starter then
                local area = mod.exports.__beta26.currentSpecialArea(game, sp, "gift")
                local denied = specialAcquisitionDenied(game, sp, area, "gift")
                if denied then
                    -- Match give_pokemon's failure contract so scripts that check
                    -- carry/lastCheck do not burn their one-time completion flag.
                    ctx.lastCheck = false
                    showRuleMessage(ctx,
                        acquisitionDeniedMessage("gift", denied, area))
                    return
                end
            end
  
            -- Snapshot object identities before the transaction so we can find
            -- the exact new Pokemon even when the engine reports Oak's Lab as
            -- the physical map. This is also the reliable seam for mandatory
            -- starter/gift nicknames in current Gen1Recomp.
            local before = {}
            for _, mon in ipairs(ctx.save and ctx.save.party or {}) do before[mon] = true end
            for _, box in ipairs(ctx.save and ctx.save.boxes or {}) do
                for _, mon in ipairs(box or {}) do before[mon] = true end
            end
  
            local forceNickname = mod.save:get("nickname_rule", defaultRuleValue("nickname_rule")) == true
                and ctx and ctx.runner ~= nil
            -- 2.4.83: current Gen1Recomp fixed Yellow's Oak-lab Pikachu script
            -- (#1013) so its native give_pokemon path once again owns the normal
            -- AskName prompt. Preserve that native prompt in Yellow instead of
            -- pre-emptively passing skipNickname=true. If the player declines
            -- while Nickname Rule is active, the mandatory fallback below still
            -- opens NamingScreen, so the rule remains enforced. Red/Blue retain
            -- the already runtime-confirmed direct mandatory flow.
            local yellowNativeStarterPrompt = forceNickname and starter
                and getGameVersion() == "YELLOW"
            local result = originalGivePokemon(ctx, species, level,
                (forceNickname and not yellowNativeStarterPrompt)
                    and true or skipNickname)
            if forceNickname and not yellowNativeStarterPrompt then
                -- Vanilla AskName normally consumes this temporary substitution
                -- token. We skipped that YES/NO box, so clear it here before a
                -- later unrelated script text can accidentally inherit it.
                ctx.pendingPokemonName = nil
            end
  
            if ctx.lastCheck ~= true then return result end
  
            local received
            for _, mon in ipairs(ctx.save and ctx.save.party or {}) do
                if not before[mon] and (starter
                    or tostring(mon and mon.species or ""):upper() == sp) then
                    received = mon; break
                end
            end
            if not received then
                for _, box in ipairs(ctx.save and ctx.save.boxes or {}) do
                    for _, mon in ipairs(box or {}) do
                        if not before[mon] and (starter
                            or tostring(mon and mon.species or ""):upper() == sp) then
                            received = mon; break
                        end
                    end
                    if received then break end
                end
            end
  
            if received then
                mod.exports.__beta26.StatRules.applyPlayer(game, received)
                local actualSpecies = tostring(received.species or sp):upper()
                if starter then
                    mod.exports.__beta26.registerStarterCatch(actualSpecies, received)
                    mod.exports.__beta26.cleanupStarterDuplicate()
                else
                    local area = mod.exports.__beta26.currentSpecialArea(game, sp, "gift")
                    mod.exports.__beta26.registerSpecialCatch(sp, area, "gift", received)
                end
  
                if forceNickname and type(Commands.push_screen) == "function" then
                    local existingNick = tostring(received.nickname or "")
                    local speciesName = tostring(received.species or sp)
                    local alreadyNamed = existingNick:find("%S") ~= nil
                        and existingNick:upper() ~= speciesName:upper()
                    -- Yellow now gets the engine's native AskName first. Only
                    -- fall back to Nuzlocke's mandatory screen if that prompt
                    -- was declined/left blank. Red/Blue behavior is unchanged.
                    if not alreadyNamed then
                        local nick = ""
                        repeat
                            Commands.push_screen(ctx, "NamingScreen", {
                                title = "NICKNAME?", maxLen = 10,
                                onDone = function(name) nick = tostring(name or "") end,
                            })
                        until nick ~= ""
                        received.nickname = nick
                    end
                    received.nuzlockeNeedsNickname = nil
                    received.nuzlockeNicknameRequired = nil
                    mod.exports.__beta26.syncHistoryNickname(received)
                end
            end
            return result
        end
  
        -- Commands.static_battle is the canonical R/B/Y fixed-wild seam. Keep
        -- its coroutine behavior untouched and carry only provenance across to
        -- battle.started, where the actual battle object becomes available.
        local function nuzlockeStaticBattle(ctx, species, level, beatFlag)
            if type(originalStaticBattle) ~= "function" then return end
            mod.exports.__beta26.pendingStaticEncounter = {
                generation = 1,
                species = species,
                level = level,
            }
            local result = originalStaticBattle(ctx, species, level, beatFlag)
            -- battle.started normally consumes this immediately. Clearing here
            -- also prevents a stale marker if an alternate engine skips battle.
            mod.exports.__beta26.pendingStaticEncounter = nil
            return result
        end
  
        if type(originalStaticBattle) == "function" then
            Commands.static_battle = nuzlockeStaticBattle
            sessionMethods.static_battle = {
                previous = originalStaticBattle, wrapper = nuzlockeStaticBattle,
            }
        end

        local function blockedHeal(ctx)
            -- Mom's R/B/Y script uses heal_party directly. Keep this command-level
            -- gate as the authoritative fallback even if hook ordering changes.
            if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_mom_heal")
                and isMomsHouseMap(ctx) then
                if ctx.__nuzlockeMomResponseShown ~= true then
                    ctx.__nuzlockeMomResponseShown = true
                    showRuleMessage(ctx,
                        mod.exports.__beta26.worldRuleText(
                            ctx and ctx.game, "no_mom_heal"))
                end
                return "end"
            end
  
            -- Pokemon Center healing is not implemented through heal_party in
            -- current Gen1Recomp, but retain this fallback for compatible builds.
            if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_poke_center")
                and isPokemonCenterMap(ctx) then
                showRuleMessage(ctx,
                    mod.exports.__beta26.worldRuleText(
                        ctx and ctx.game, "no_poke_center"))
                return "end"
            end
            return originalHeal(ctx)
        end
  
        Commands.heal_party = blockedHeal
        sessionMethods.heal_party = { previous = originalHeal, wrapper = blockedHeal }
  
        -- Mom fades to white immediately before heal_party. Mirror the command
        -- gate at the fade verb too so the refusal remains on the room screen
        -- even if the public script hook is unavailable or reordered.
        local function blockedFade(ctx, ...)
            if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_mom_heal")
                and isMomsHouseMap(ctx) then
                return
            end
            if type(originalFade) == "function" then
                return originalFade(ctx, ...)
            end
        end
        if type(originalFade) == "function" then
            Commands.fade = blockedFade
            sessionMethods.fade = { previous = originalFade, wrapper = blockedFade }
        end
  
        -- Force the resolver to return the wrapped commands too. This is the
        -- important part for map scripts that resolve command names at runtime.
        if type(Commands.resolve) == "function" then
            local originalResolve = Commands.resolve
            local resolveWrapper
            resolveWrapper = function(data, name)
                if name == "heal_party" then
                    return blockedHeal, Commands.meta and Commands.meta[name]
                elseif name == "fade" and type(originalFade) == "function" then
                    return blockedFade, Commands.meta and Commands.meta[name]
                elseif name == "trade" and type(originalTrade) == "function" then
                    return nuzlockeTrade, Commands.meta and Commands.meta[name]
                elseif name == "give_pokemon"
                    and type(originalGivePokemon) == "function" then
                    return nuzlockeGivePokemon, Commands.meta and Commands.meta[name]
                elseif name == "static_battle"
                    and type(originalStaticBattle) == "function" then
                    return nuzlockeStaticBattle, Commands.meta and Commands.meta[name]
                end
                return originalResolve(data, name)
            end
            Commands.resolve = resolveWrapper
            sessionMethods.resolve = { previous = originalResolve, wrapper = resolveWrapper }
        end
  
        -- Secondary hook seams for builds that expose field healing through the
        -- public hook layer instead of the script command table.
        local function denyCenter(next, ctx, ...)
            if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_poke_center")
                and isPokemonCenterMap(ctx) then
                showRuleMessage(ctx,
                    mod.exports.__beta26.worldRuleText(
                        ctx and ctx.game, "no_poke_center"))
                return false
            end
            return next(ctx, ...)
        end
  
        for _, hookName in ipairs({
            "pokemon_center.heal",
            "poke_center.heal",
            "pokemon.center.heal",
            "heal_party",
            "field.heal_party"
        }) do
            pcall(mod.hooks.wrap, mod.hooks, hookName, denyCenter, 1000)
        end
  
        for _, name in ipairs({ "mom_heal", "heal_mom", "mom_rest", "mom_heals" }) do
            if type(Commands[name]) == "function" then
                local originalMom = Commands[name]
                local momWrapper
                momWrapper = function(ctx)
                    if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_mom_heal") then
                        if ctx.__nuzlockeMomResponseShown ~= true then
                            ctx.__nuzlockeMomResponseShown = true
                            showRuleMessage(ctx,
                                mod.exports.__beta26.worldRuleText(
                                    ctx and ctx.game, "no_mom_heal"))
                        end
                        return
                    end
                    return originalMom(ctx)
                end
                Commands[name] = momWrapper
                sessionMethods[name] = { previous = originalMom, wrapper = momWrapper }
            end
        end
  
        Commands.__nuzlockeRulesPatched = true
        Commands.__nuzlockeRulesOwner = mod
        Commands.__nuzlockeRulesSession = { owner = mod, methods = sessionMethods }
        return true
  
  end
  -- 2.3.11 / Gen1Recomp 0.1.98: this first late-runtime block performs
  -- battle/runtime/screen/save module imports and behavior installation.
  -- The engine lifecycle explicitly permits behavioral subscriptions/hooks at
  -- game.ready, after services initialization. Keep the full phase intact but
  -- do not execute it during the entry-chunk load phase.
  mod.exports.__beta26._lateRuntimePhase1 = mod.exports.__beta26._lateRuntimeInit
  mod.exports.__beta26._lateRuntimeInit = nil
  mod.events:on("game.ready", function()
      local phase = mod.exports.__beta26._lateRuntimePhase1
      if type(phase) ~= "function" then return end
      mod.exports.__beta26._lateRuntimePhase1 = nil
      local ok, err = pcall(phase)
      mod.exports.__beta26.lateRuntimePhase1Ready = ok == true
      if not ok then
          mod.exports.__beta26.lateRuntimePhase1Error = tostring(err)
          if mod.log and type(mod.log.error) == "function" then
              mod.log:error("Nuzlocke late runtime phase 1 failed: %s", tostring(err))
          end
          if mod.exports.__beta26.Dev and mod.exports.__beta26.Dev.recordError then
              pcall(mod.exports.__beta26.Dev.recordError,
                  "late_runtime_phase_1", err, currentGame or mod.game)
          end
      end

      -- A phase-1 retry stages phase 2 again. The entry-chunk run already
      -- executed it once; only retry here if that first execution failed due to
      -- a late engine dependency, then clear the staging slot either way.
      if type(mod.exports.__beta26._lateRuntimeInit) == "function" then
          if mod.exports.__beta26.lateRuntimePhase2Ready ~= true then
              mod.exports.__beta26.lateRuntimePhase2Ready,
              mod.exports.__beta26.lateRuntimePhase2Error =
                  pcall(mod.exports.__beta26._lateRuntimeInit)
          end
          mod.exports.__beta26._lateRuntimeInit = nil
      end
  end)

  mod.exports.__beta26._lateRuntimeInit = function()
    ---------------------------------------------------------------------
    -- AUTHORITATIVE SCRIPT-COMMAND HEAL GATE
    --
    -- The recomp's ScriptRunner resolves every script row through the live
    -- Runtime "script.command" hook. Mom's R/B/Y house script uses
    -- heal_party directly. Pokemon Centers use a separate overworld nurse path
    -- and are gated below; the Center test here remains only as a compatibility
    -- fallback for builds that route healing through the script command table.
    ---------------------------------------------------------------------
    local function nuzlockeMapTag(ctx)
        local ow = (ctx and ctx.overworld)
            or (currentGame and currentGame.overworld)
        local map = ow and ow.map
        local def = map and map.def
        local parts = {
            map and map.id,
            map and map.name,
            def and def.id,
            def and def.name,
            def and def.label,
        }
        local out = {}
        for _, value in ipairs(parts) do
            if value ~= nil then
                out[#out + 1] = tostring(value):upper()
            end
        end
        return table.concat(out, " ")
    end
  
    local function isPokemonCenterMap(ctx)
        local tag = nuzlockeMapTag(ctx)
        return (tag:find("POKEMON", 1, true) and tag:find("CENTER", 1, true))
            or (tag:find("POKE", 1, true) and tag:find("CENTER", 1, true))
    end
  
    local function isMomsHouseMap(ctx)
        local tag = nuzlockeMapTag(ctx)
        return tag:find("REDS_HOUSE", 1, true) ~= nil
            or tag:find("REDSHOUSE", 1, true) ~= nil
    end
  
    -- 2.2.3: one authoritative NEW GAME-only query for catch-demo skipping.
    -- The Setup snapshot is stamped into mod.save, while older builds also
    -- carried a transient top-level save field for delayed tutorial seams.
    -- Accept both so Yellow's Pallet demo, the R/B/Y old-man command, and
    -- Gold's Route 29 callback all observe the same player choice.
    function mod.exports.__beta26.skipCatchTutorialRequested(save)
        if saveSchemaTooNew then return false end
        local delegatedRule = mod.exports.__beta26.externalRuleDelegation
        if type(delegatedRule) == "function"
            and delegatedRule("skip_catch_tutorial", currentGame or mod.game) then
            return false
        end
        if save and save.nuzlockeSkipCatchTutorial == true then return true end
        local ok, value = pcall(function()
            return mod.save:get("skip_catch_tutorial", false)
        end)
        if ok and value == true then return true end
        local staged = newGameRulesSnapshot or pendingNewGameRules
        return type(staged) == "table"
            and staged.skip_catch_tutorial == true
    end

    local nuzlockeScriptHealGateInstalled = false
    local function installNuzlockeScriptHealGate()
        -- 2.4.90: always re-check the direct Yellow Oak demo seam. The
        -- generic script.command listener below remains one-shot.
  
        -- Yellow's opening Professor Oak capture demonstration is hand-ported
        -- in story2.lua: BattleState.newWild(PIKACHU, 5), then
        -- battle:makeOldManDemo("PROF.OAK"), then Commands.pushBattle(ctx,battle).
        -- Intercept that exact semantic demo before the battle stack. Running
        -- its onFinish callback preserves Whew -> Come With Me -> lab escort.
        local okCommands, Commands = pcall(require, "src.script.Commands")
        if okCommands and type(Commands) == "table"
            and type(Commands.pushBattle) == "function" then
            local session = Commands.__nuzlockeSkipOakDemoSession
            if type(session) == "table" and session.owner ~= mod
                and Commands.pushBattle == session.wrapper
                and type(session.previous) == "function" then
                Commands.pushBattle = session.previous
                session = nil
            end
            if not (type(session) == "table" and session.owner == mod
                and Commands.pushBattle == session.wrapper) then
                local previous = Commands.pushBattle
                local wrapper = function(ctx, battle, ...)
                    local game = ctx and ctx.game or currentGame or mod.game
                    local save = game and game.save or ctx and ctx.save
                    local demoName = tostring(battle and battle.demoName or ""):upper()
                    local enemySpecies = battle and battle.enemy and battle.enemy.mon
                        and tostring(battle.enemy.mon.species or ""):upper() or ""
                    local flags = save and save.flags or {}
                    local oakPalletDemo = battle and battle.demo == true
                        and (demoName == "PROF.OAK"
                            or demoName == "PROF OAK"
                            or (demoName:find("PROF", 1, true)
                                and demoName:find("OAK", 1, true)))
                        and (enemySpecies == "" or enemySpecies == "PIKACHU")
                        and flags.EVENT_GOT_STARTER ~= true
                    if oakPalletDemo and mod.exports.__beta26.skipCatchTutorialRequested(save) then
                        battle.__nuzlockeTutorialSkipped = true
                        local done = battle.onFinish
                        battle.onFinish = nil
                        if type(done) == "function" then done("caught") end
                        return battle
                    end
                    return previous(ctx, battle, ...)
                end
                Commands.pushBattle = wrapper
                Commands.__nuzlockeSkipOakDemoSession = {
                    owner = mod, previous = previous, wrapper = wrapper,
                }
            end
        end

        if not nuzlockeScriptHealGateInstalled then
            nuzlockeScriptHealGateInstalled = true
            mod.hooks:wrap("script.command", function(next, ctx, name, args)
            -- Red/Blue and Yellow's Viridian old-man demonstration use the
            -- semantic old_man_demo command. Skip only that command; all
            -- surrounding vanilla questions, flags, movement, and cleanup run.
            if name == "old_man_demo" and ctx
                and mod.exports.__beta26.skipCatchTutorialRequested(ctx.save) then
                ctx.__nuzlockeCatchTutorialSkipped = true
                return
            end

            -- beta.26.3: when Mom healing is allowed, replace the final vanilla
            -- "looking great" beat with one T3 home-flavor line once per save.
            -- Later allowed heals keep vanilla dialogue, preventing repeated T3
            -- Mom chatter from stacking on every visit.
            if name == "show_text" and isMomsHouseMap(ctx)
                and worldTier(ctx and ctx.game) >= 3
                and mod.save:get("no_mom_heal", false) ~= true then
                local textId = type(args) == "table"
                    and (args[1] or args.textId or args.text) or args
                if tostring(textId or "") == "_RedsHouse1FMomLookingGreatText" then
                    local flags = worldFlags()
                    if not flags["mom_allowed_heal_t3"] then
                        flags["mom_allowed_heal_t3"] = true
                        mod.save:set("nuzlocke_world_flags", flags)
                        showRuleMessageImmediate(ctx,
                            "Mom: There we go!\nYour team looks great.\fBRYAN is staying here\nfor a while, honey.\fHe says your computer\nis his dev machine now.\fAnd, well... he has\nbeen keeping me up\npretty late lately.\fBe careful out there!")
                        return "end"
                    end
                end
            end
  
            -- Own Mom's blocked-heal interaction from the first post-starter
            -- rest line. Gen1Recomp's RedsHouse1F script uses the exact
            -- _RedsHouse1FMomYouShouldRestText row immediately before fade ->
            -- heal_party. Replacing that row and ending the script prevents the
            -- vanilla "take a rest" text from playing before our refusal.
            if name == "show_text"
                and mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_mom_heal")
                and isMomsHouseMap(ctx) then
                local textId = type(args) == "table"
                    and (args[1] or args.textId or args.text) or args
                if tostring(textId or "") == "_RedsHouse1FMomYouShouldRestText" then
                    if ctx.__nuzlockeMomResponseShown ~= true then
                        ctx.__nuzlockeMomResponseShown = true
                        showRuleMessageImmediate(ctx,
                            mod.exports.__beta26.worldRuleText(
                                ctx and ctx.game, "no_mom_heal"))
                    end
                    return "end"
                end
            end
  
            -- Mom's vanilla heal script fades to white immediately before
            -- heal_party.  If healing is disabled, suppress both fades so the
            -- personalized refusal is shown on the normal room screen.
            if name == "fade"
                and mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_mom_heal")
                and isMomsHouseMap(ctx) then
                return
            end
  
            if name == "heal_party" then
                if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_mom_heal")
                    and isMomsHouseMap(ctx) then
                    -- The earlier Mom rest-text branch owns the normal
                    -- interaction.  This remains a fallback for reordered or
                    -- provider scripts, but it must never emit a second box in
                    -- the same script transaction.
                    if ctx.__nuzlockeMomResponseShown ~= true then
                        ctx.__nuzlockeMomResponseShown = true
                        showRuleMessageImmediate(ctx,
                            mod.exports.__beta26.worldRuleText(ctx.game, "no_mom_heal"))
                    end
                    return "end"
                end
  
                if mod.exports.__beta26.ruleActive(ctx and ctx.game, "no_poke_center")
                    and isPokemonCenterMap(ctx) then
                    showRuleMessageImmediate(ctx,
                        mod.exports.__beta26.worldRuleText(ctx.game, "no_poke_center"))
                    return "end"
                end
            end
  
            -- 2.2.8: do not rewrite vanilla ScriptRunner text through the
            -- Nuzlocke paginator. Gen1's native \v continuation semantics are
            -- part of the engine text format; converting them globally caused
            -- ordinary interactions (for example Yellow's bedroom SNES) to
            -- replay/overlap text. Nuzlocke-authored T3 dialogue still uses the
            -- shared formatWorldText / ownership path at its own call sites.

            return next(ctx, name, args)
            end, 10000)
        end
    end
  
    ---------------------------------------------------------------------
    -- POKEMON BOIS CLUB - TIER 3 WORLD BUILDING
    --
    -- T3 cosmetically rebrands Vermilion's Pokemon Fan Club as the Pokemon
    -- Bois Club and gives the chairman a Bryan-the-Boi tribute appearance
    -- using a genuine native engine walker. No repository asset is added, and
    -- the exact vanilla renderer/story state is restored/left untouched at T0-T2.
    -- R/B/Y and Gold use the same map id but different chairman object indices
    -- (R/B/Y #5, Gold #1), matching their native object tables.
    ---------------------------------------------------------------------
    local BOIS_CLUB_MAP = "POKEMON_FAN_CLUB"
    local fanClubOriginalSprites = setmetatable({}, { __mode = "k" })
  
    -- 2.2.4: the old hand-painted Bryan renderer was intentionally retired.
    -- Build the Fan Club tribute from a genuine engine SpriteRenderer instead,
    -- matching Bryan-at-Home's native-walker strategy. This keeps proportions,
    -- palette behavior, animation and outline language identical to surrounding
    -- NPCs without adding a repository asset.
    local function makeNativeBryanBoiRenderer(game, npc)
        local data = game and game.data
        local spriteRegistry = data and data.sprites
        if not spriteRegistry then return nil end

        local seedSprite
        for _, preferred in ipairs({
            "SPRITE_GAMBLER", "GAMBLER",
            "SPRITE_BLACK_HAIR_BOY_1", "BLACK_HAIR_BOY_1",
        }) do
            if spriteRegistry[preferred] then
                seedSprite = preferred
                break
            end
        end

        -- Compatibility fallback: reuse the definition of another native NPC
        -- already present on this map rather than inventing custom art.
        if not seedSprite then
            local ow = game and game.overworld
            for _, native in ipairs(ow and ow.npcs or {}) do
                if native ~= npc and native and native.def and native.def.sprite
                    and spriteRegistry[native.def.sprite] then
                    seedSprite = native.def.sprite
                    break
                end
            end
        end
        if not seedSprite then return nil end

        local okRenderer, SpriteRenderer = pcall(require, "src.render.SpriteRenderer")
        if not okRenderer or type(SpriteRenderer) ~= "table"
            or type(SpriteRenderer.new) ~= "function" then
            return nil
        end
        local ok, renderer = pcall(
            SpriteRenderer.new,
            spriteRegistry[seedSprite],
            tostring(npc and npc.id or "nuzlocke_bryan_boi") .. ":bois"
        )
        return ok and renderer or nil
    end

    do
    ---------------------------------------------------------------------
    -- BRYAN AT HOME - TIER 3 WORLD BUILDING
    --
    -- Strings alone cannot make Bryan "live" in the house.  Insert one
    -- runtime NPC into REDS_HOUSE_1F through the same NPC object contract the
    -- engine uses for generated object_event rows, and attach a contributed
    -- map-script text id below.  The object exists only at T3, never mutates
    -- the map definition/save object table, and is removed cleanly if the
    -- world-building tier is lowered while the player is still in the room.
    ---------------------------------------------------------------------
    local BRYAN_HOME_TEXT = "TEXT_NUZLOCKE_BRYAN_HOME"
    local BRYAN_HOME_NAME = "NUZLOCKE_BRYAN_HOME"
    local BRYAN_HOME_INDEX = 98

    local function removeBryanHomeNpc(ow)
        if not ow then return false end
        local removed = false
        for i = #(ow.npcs or {}), 1, -1 do
            local npc = ow.npcs[i]
            if npc and (npc.__nuzlockeBryanHome == true
                or (npc.def and npc.def.name == BRYAN_HOME_NAME)) then
                if ow.npcPool then ow.npcPool[npc.id] = nil end
                table.remove(ow.npcs, i)
                removed = true
            end
        end
        for i = #(ow.entities or {}), 1, -1 do
            local npc = ow.entities[i]
            if npc and (npc.__nuzlockeBryanHome == true
                or (npc.def and npc.def.name == BRYAN_HOME_NAME)) then
                table.remove(ow.entities, i)
            end
        end
        return removed
    end

    local function refreshBryanHomeNpc(game)
        local ow = game and game.overworld
        local mapId = tostring(ow and ow.map and ow.map.id or ""):upper()
        if mapId ~= "REDS_HOUSE_1F" then return false end

        if mod.exports.__beta26.runtimeIsGold(game) or worldTier(game) < 3 then
            removeBryanHomeNpc(ow)
            return false
        end

        for _, npc in ipairs(ow.npcs or {}) do
            if npc and (npc.__nuzlockeBryanHome == true
                or (npc.def and npc.def.name == BRYAN_HOME_NAME)) then
                return true
            end
        end

        local okNpc, NPC = pcall(require, "src.world.NPC")
        if not okNpc or type(NPC) ~= "table" or type(NPC.new) ~= "function" then
            return false
        end

        -- 2.2.0: Bryan now uses a genuine engine NPC walker rather than the
        -- rough hand-painted 16x16 renderer. Prefer a native gambler/bearded
        -- male sprite when the active registry exposes one, then fall back to
        -- a known-good house NPC sprite. This keeps palette, proportions,
        -- animation and outline language identical to surrounding NPCs without
        -- adding an asset file.
        local seedSprite
        local spriteRegistry = game.data and game.data.sprites
        for _, preferred in ipairs({
            "SPRITE_GAMBLER", "GAMBLER",
            "SPRITE_BLACK_HAIR_BOY_1", "BLACK_HAIR_BOY_1",
        }) do
            if spriteRegistry and spriteRegistry[preferred] then
                seedSprite = preferred
                break
            end
        end
        if not seedSprite then
            for _, native in ipairs(ow.npcs or {}) do
                if native and native.def and native.def.sprite
                    and spriteRegistry and spriteRegistry[native.def.sprite] then
                    seedSprite = native.def.sprite
                    break
                end
            end
        end
        if not seedSprite then return false end

        -- Prefer the bedroom-side/open floor cells, but verify every candidate
        -- against the live map and occupants so another map-content mod cannot
        -- make Bryan spawn in furniture, a warp, the player, or another NPC.
        local candidates = {
            { 2, 4 }, { 6, 4 }, { 2, 5 }, { 6, 5 },
            { 4, 3 }, { 1, 4 }, { 7, 4 },
        }
        local bx, by
        for _, cell in ipairs(candidates) do
            local x, y = cell[1], cell[2]
            local valid = ow.map and ow.map.inBounds
                and ow.map:inBounds(x, y)
                and ow.map:isWalkableCell(x, y)
                and not (ow.map.warpAtCell and ow.map:warpAtCell(x, y))
                and not (ow.player and ow.player.cellX == x and ow.player.cellY == y)
            if valid then
                for _, other in ipairs(ow.npcs or {}) do
                    if other and other.cellX == x and other.cellY == y then
                        valid = false
                        break
                    end
                end
            end
            if valid then bx, by = x, y break end
        end
        if bx == nil then return false end

        local def = {
            index = BRYAN_HOME_INDEX,
            name = BRYAN_HOME_NAME,
            sprite = seedSprite,
            movement = "STAY",
            range = "DOWN",
            x = bx, y = by,
            text = BRYAN_HOME_TEXT,
            runtime = true,
        }
        local okCreate, npc = pcall(NPC.new, game.data, "REDS_HOUSE_1F", def)
        if not okCreate or not npc then return false end
        npc.__nuzlockeBryanHome = true
        -- Keep NPC.new's native SpriteRenderer intact.
        ow.npcs = ow.npcs or {}
        ow.entities = ow.entities or {}
        ow.npcPool = ow.npcPool or {}
        table.insert(ow.npcs, npc)
        table.insert(ow.entities, npc)
        ow.npcPool[npc.id] = npc
        return true
    end
    mod.exports.__beta26.refreshBryanHomeNpc = refreshBryanHomeNpc

    mod.events:on("map.entered", function()
        pcall(refreshBryanHomeNpc, currentGame or mod.game)
    end)
    mod.events:on("map.reloaded", function()
        pcall(refreshBryanHomeNpc, currentGame or mod.game)
    end)
    mod.events:on("world.stepped", function()
        local game = currentGame or mod.game
        if tostring(game and game.overworld and game.overworld.map
            and game.overworld.map.id or ""):upper() == "REDS_HOUSE_1F" then
            pcall(refreshBryanHomeNpc, game)
        end
    end)

    end

    local function fanClubChairman(game)
        local ow = game and game.overworld
        local mapId = tostring(ow and ow.map and ow.map.id or ""):upper()
        if mapId ~= BOIS_CLUB_MAP then return nil end
        local index = mod.exports.__beta26.runtimeIsGold(game) and 1 or 5
        if ow and type(ow.npcByIndex) == "function" then
            local npc = ow:npcByIndex(index)
            if npc then return npc end
        end
        return ow and ow.npcs and ow.npcs[index] or nil
    end
  
    local function refreshPokemonBoisClubSprite(game)
        local npc = fanClubChairman(game)
        if not npc then return false end

        if worldTier(game) >= 3 then
            if not fanClubOriginalSprites[npc] then
                fanClubOriginalSprites[npc] = npc.sprite
            end
            if npc.__nuzlockePokemonBoisSprite ~= true then
                local renderer = makeNativeBryanBoiRenderer(game, npc)
                if renderer then
                    npc.sprite = renderer
                    npc.__nuzlockePokemonBoisRenderer = renderer
                    npc.__nuzlockePokemonBoisSprite = true
                end
            end
        elseif npc.__nuzlockePokemonBoisSprite == true then
            local original = fanClubOriginalSprites[npc]
            local ours = npc.__nuzlockePokemonBoisRenderer
            -- Restore only if our renderer still owns the slot. If another mod
            -- replaced the chairman after us, do not clobber its live sprite.
            if original and (ours == nil or npc.sprite == ours) then
                npc.sprite = original
            end
            npc.__nuzlockePokemonBoisSprite = nil
            npc.__nuzlockePokemonBoisRenderer = nil
            fanClubOriginalSprites[npc] = nil
        end
        return true
    end
    mod.exports.__beta26.refreshPokemonBoisClubSprite = refreshPokemonBoisClubSprite
    mod.events:on("map.entered", function() pcall(refreshPokemonBoisClubSprite, currentGame or mod.game) end)
    mod.events:on("world.stepped", function()
        local game = currentGame or mod.game
        if tostring(game and game.overworld and game.overworld.map
            and game.overworld.map.id or ""):upper() == BOIS_CLUB_MAP then
            pcall(refreshPokemonBoisClubSprite, game)
        end
    end)
  
    -- R/B/Y background signs use the compose-capable map_scripts registry.
    -- T0-T2 explicitly fall back to the extracted vanilla text.
    if mod.content and mod.content.map_scripts then
        local function fanClubText(game, body, done, worldOwned)
            if worldOwned and mod.exports.__beta26.pushWorldText(game, body, done) then
                return
            end
            local okText, TextBox = pcall(require, "src.render.TextBox")
            if okText and TextBox then
                game.stack:push(TextBox.new(game, body, done))
            elseif done then
                done()
            end
        end
        mod.content.map_scripts:register("VERMILION_CITY", {
            priority = 20,
            talk = {
                TEXT_VERMILIONCITY_POKEMON_FAN_CLUB_SIGN = function(game, _ow, _npc, done)
                    local text = worldTier(game) >= 3
                        and Strings("POKEMON BOIS CLUB\nPOKEMON lovers and\nchallenge runners welcome!")
                        or (game.data.text._VermilionCityPokemonFanClubSignText
                            or Strings("POKEMON FAN CLUB"))
                    fanClubText(game, text, done, worldTier(game) >= 3)
                end,
            },
        })
        mod.content.map_scripts:register(BOIS_CLUB_MAP, {
            priority = 20,
            talk = {
                TEXT_POKEMONFANCLUB_SIGN_1 = function(game, _ow, _npc, done)
                    local text = worldTier(game) >= 3
                        and Strings("POKEMON BOIS CLUB\nRule #1:\nLove your POKEMON.")
                        or (game.data.text._PokemonFanClubSign1Text
                            or Strings("Let's all listen politely to other trainers."))
                    fanClubText(game, text, done, worldTier(game) >= 3)
                end,
                TEXT_POKEMONFANCLUB_SIGN_2 = function(game, _ow, _npc, done)
                    local text = worldTier(game) >= 3
                        and Strings("POKEMON BOIS CLUB\nRule #2:\nBrag respectfully.")
                        or (game.data.text._PokemonFanClubSign2Text
                            or Strings("If someone brags, brag right back!"))
                    fanClubText(game, text, done, worldTier(game) >= 3)
                end,
            },
        })
    end
  
    -- Dialogue rebrand only. Story flags, gifts, yes/no branches and the Bike
    -- Voucher / Rare Candy transactions continue through the untouched scripts.
    mod.hooks:wrap("script.command", function(next, ctx, name, args, cmd)
        local game = ctx and ctx.game or currentGame or mod.game
        local mapId = tostring((ctx and (ctx.mapId or ctx.map))
            or (ctx and ctx.overworld and ctx.overworld.map and ctx.overworld.map.id)
            or (game and game.overworld and game.overworld.map and game.overworld.map.id)
            or ""):upper()
        if worldTier(game) < 3 then return next(ctx, name, args, cmd) end
  
        if ctx and ctx.generation ~= 2 and mapId == BOIS_CLUB_MAP then
            if name == "ask" and type(args) == "table"
                and tostring(args[1] or "") == "_PokemonFanClubChairmanIntroText" then
                local rewritten = {}
                for i, value in ipairs(args) do rewritten[i] = value end
                rewritten[1] = "I'm BRYAN, boi!\nCHAIRMAN of the\nPOKEMON BOIS CLUB!\fI made the NUZLOCKE\nmod, boi.\fBeen coding GEN1\nRECOMP on your PC.\fWant to hear about\nmy favorite POKEMON?"
                return next(ctx, name, rewritten, cmd)
            elseif name == "show_text" and type(args) == "table"
                and tostring(args[1] or "") == "_PokemonFanClubReceptionistText" then
                local rewritten = {}
                for i, value in ipairs(args) do rewritten[i] = value end
                rewritten[1] = "Welcome to the\nPOKEMON BOIS CLUB!\fBRYAN says boi a lot.\fHe also says he made\nthe NUZLOCKE mod\nand codes GEN1 RECOMP\nfrom a kid's bedroom."
                return next(ctx, name, rewritten, cmd)
            end
        elseif ctx and ctx.generation == 2 then
            local textId = tostring(cmd and cmd.text or "")
            local vm = ctx.vm
            local function raw(body, terminal)
                if vm and type(vm.showRaw) == "function" then vm:showRaw(body) end
                return terminal and "end" or nil
            end
            if mapId == BOIS_CLUB_MAP then
                if name == "writetext"
                    and textId:find("PokemonFanClubChairmanDidYouVisitToHearAboutMyMonText", 1, true) then
                    return raw("I'm BRYAN, boi!\nCHAIRMAN of the\nPOKEMON BOIS CLUB!\fI made the NUZLOCKE\nmod, boi.\fI've raised over\n150 POKEMON.\fWant to hear about\nmy favorite POKEMON?", false)
                elseif name == "jumptextfaceplayer"
                    and textId:find("PokemonFanClubReceptionistText", 1, true) then
                    return raw("Welcome to the\nPOKEMON BOIS CLUB!\fOur CHAIRMAN gets\nvery vocal about\nPOKEMON...", true)
                elseif name == "jumptext"
                    and textId:find("PokemonFanClubListenSignText", 1, true) then
                    return raw("POKEMON BOIS CLUB\nRule #1:\nListen politely.", true)
                elseif name == "jumptext"
                    and textId:find("PokemonFanClubBraggingSignText", 1, true) then
                    return raw("POKEMON BOIS CLUB\nRule #2:\nBrag right back!", true)
                end
            elseif mapId == "VERMILION_CITY"
                and (name == "jumptext" or name == "jumptextfaceplayer")
                and textId:find("PokemonFanClub", 1, true) then
                return raw("POKEMON BOIS CLUB\nPOKEMON lovers and\nchallenge runners welcome!", true)
            end
        end
        return next(ctx, name, args, cmd)
    end, 50)
  
    ---------------------------------------------------------------------
    -- RED'S HOUSE 1F TV - TIER 3 WORLD BUILDING
    --
    -- Gen1Recomp dispatches hidden/background interactions through the
    -- map_scripts compose chain. onInteract handlers run in priority order and
    -- the first truthy result consumes the interaction, so this contribution
    -- handles only the actual TV tile (3,1) at T3 and returns false everywhere
    -- else. That preserves the engine's vanilla TV at T0-T2 and every non-TV
    -- interaction. Keep this nested in the existing install section instead of
    -- adding another top-level helper; the large main chunk is initialization
    -- sensitive to extra top-level locals.
    ---------------------------------------------------------------------
    if mod.content and mod.content.map_scripts then
        mod.content.map_scripts:register("REDS_HOUSE_1F", {
            priority = 20,
            talk = {
            TEXT_NUZLOCKE_BRYAN_HOME = function(game, ow, npc, done)
                if worldTier(game) < 3 then
                    if done then done() end
                    return
                end
                if npc and npc.facePlayer and ow and ow.player then
                    npc:facePlayer(ow.player)
                end
                local lines = {
                    "Boi! I'm BRYAN.\fI use your PC to\nwork on GEN1RECOMP.\fI made this NUZLOCKE\nmod too. Probably.",
                    "Boi, your game\nconsole is sick.\fI was coding between\nrounds, I swear.\fPOKEMON BOIS CLUB\nbusiness never stops.",
                    "Your MOM said I can\nstay a while, boi.\fShe says I keep her\nup too late...\fCoding! Mostly coding.\nDon't make it weird.",
                    "Boi! I pushed another\nNUZLOCKE change.\fYour computer survived.\nThat's a runtime PASS.",
                }
                local cycle = math.floor(tonumber(
                    mod.save:get("nuzlocke_bryan_home_cycle", 0)) or 0)
                local index = (cycle % #lines) + 1
                mod.save:set("nuzlocke_bryan_home_cycle", index)
                if not mod.exports.__beta26.pushWorldText(game, lines[index], done)
                    and done then done() end
            end,
            TEXT_REDSHOUSE1F_TV = function(game, ow, npc, done)
                if worldTier(game) < 3 then
                    local t = game.data.text
                    local text = ow.player.facing == "up"
                        and t._RedsHouse1FTVStandByMeMovieText
                        or t._RedsHouse1FTVWrongSideText
                    local okText, TextBox = pcall(require, "src.render.TextBox")
                    if okText and TextBox then
                        game.stack:push(TextBox.new(game, text, done))
                        return
                    end
                    if done then done() end
                    return
                end
  
                -- beta.26.4: the home TV is a live run recap rather than one
                -- static rule gag. It combines current story progression, route
                -- outcomes, team history, losses, the next active cap, and one
                -- relevant rule reminder. Nothing here changes gameplay state.
                local save = game and game.save or {}
                local flags = save.flags or {}
                local gotDex = flags.EVENT_GOT_POKEDEX == true
                    or tonumber(flags.EVENT_GOT_POKEDEX) == 1
                local caughtCount = countTrackerCatches()
                local losses = tonumber(mod.save:get("nuzlocke_losses", 0)) or 0
                local failedCount = 0
                local states = mod.save:get("encounter_states", {})
                if type(states) == "table" then
                    for _, state in pairs(states) do
                        if type(state) == "table" and state.status == "FAILED" then
                            failedCount = failedCount + 1
                        end
                    end
                end
  
                local latestCaught
                local history = mod.save:get("nuzlocke_history", {})
                if type(history) == "table" then
                    for i = #history, 1, -1 do
                        local row = history[i]
                        if type(row) == "table" and row.status ~= "LOST"
                            and row.status ~= "DEAD"
                            and (row.name or row.species) then
                            latestCaught = tostring(row.name or row.species)
                            break
                        end
                    end
                end
  
                local lastLoss = mod.save:get("last_loss", {})
                if type(lastLoss) ~= "table" then lastLoss = {} end
                local lastFailed = mod.save:get("last_failed_encounter", {})
                if type(lastFailed) ~= "table" then lastFailed = {} end
                if not lastFailed.species and type(states) == "table" then
                    for area, state in pairs(states) do
                        if type(state) == "table" and state.status == "FAILED" then
                            lastFailed = { area = area, species = state.species }
                            break
                        end
                    end
                end
  
                local badges = currentGymProgressCount(save)
                local cap, capName = nextLevelCapInfo(save)
                local capLine = nil
                if tonumber(cap) and tonumber(cap) < 100 then
                    capLine = "Next: " .. tostring(capName or "CAP")
                        .. " LV" .. tostring(cap) .. "."
                end
                -- Build every report that is meaningful for this save and
                -- cycle through them on repeated TV interactions. This keeps a
                -- single old failed route or loss from permanently hiding later
                -- catches/progression while still letting the TV remember it.
                local reports = {}
                local progress = {}
                if gotDex then
                    progress[#progress + 1] = "TV: AREA GUIDE LIVE"
                    progress[#progress + 1] = tostring(caughtCount) .. " caught, "
                        .. tostring(failedCount) .. " failed."
                    progress[#progress + 1] = tostring(badges) .. " badge"
                        .. (badges == 1 and "" or "s") .. " earned."
                else
                    progress[#progress + 1] = "TV: PALLET NEWS"
                    progress[#progress + 1] = "Oak's lab is busy today."
                    progress[#progress + 1] = "The journey is just starting."
                end
                if capLine then progress[#progress + 1] = capLine end
                reports[#reports + 1] = progress
  
                if latestCaught then
                    local caughtReport = {
                        "TV: TEAM UPDATE",
                        latestCaught .. " joined the run.",
                        tostring(caughtCount) .. " caught so far.",
                    }
                    if capLine then caughtReport[#caughtReport + 1] = capLine end
                    reports[#reports + 1] = caughtReport
                end
  
                if failedCount > 0 then
                    reports[#reports + 1] = {
                        "TV: ROUTE REPORT",
                        tostring(lastFailed.species or "An encounter") .. " got away.",
                        tostring(failedCount) .. " area"
                            .. (failedCount == 1 and "" or "s") .. " marked failed.",
                    }
                end
  
                if losses > 0 then
                    reports[#reports + 1] = {
                        "TV: KANTO REPORT",
                        tostring(lastLoss.name or lastLoss.species or "A teammate")
                            .. " was lost.",
                        tostring(losses) .. " teammate"
                            .. (losses == 1 and "" or "s") .. " lost so far.",
                    }
                end
  
                -- beta.30.1.23: T3 Pallet local-news / Bryan sitcom beats.
                -- These are flavor-only reports in the existing rotating TV
                -- recap and never affect story flags or Nuzlocke state.
                reports[#reports + 1] = {
                    "TV: PALLET LOCAL",
                    "A man matching the",
                    "POKEMON BOIS CLUB",
                    "leader was seen",
                    "walking around town.",
                }
                reports[#reports + 1] = {
                    "TV: NIGHT WATCH",
                    "Witnesses report the",
                    "same man sneaking",
                    "through Pallet windows",
                    "after dark. Boi?",
                }
                reports[#reports + 1] = {
                    "TV: TECH REPORT",
                    "BRYAN claims he coded",
                    "GEN1 RECOMP on a",
                    "Pallet bedroom PC.",
                    "He also claims he made",
                    "the NUZLOCKE mod. Boi.",
                }
                reports[#reports + 1] = {
                    "TV: HOME & GAMES",
                    "A local houseguest was",
                    "seen hogging a game",
                    "console between long",
                    "coding sessions.",
                }

                local cycle = math.floor(tonumber(mod.save:get("nuzlocke_tv_cycle", 0)) or 0)
                local index = (cycle % #reports) + 1
                mod.save:set("nuzlocke_tv_cycle", index)
                local parts = reports[index]

                -- Keep each report self-contained and explicitly paginate it.
                -- Gen1 textboxes are narrow; relying on one long newline-joined
                -- paragraph caused words to run together in Yellow. Wrap each
                -- report beat to 18 glyphs and separate beats with a page break.
                local function wrapTvBeat(value)
                    local words = {}
                    for word in tostring(value or ""):gmatch("%S+") do
                        words[#words + 1] = word
                    end
                    local lines, line = {}, ""
                    for _, word in ipairs(words) do
                        local candidate = line == "" and word or (line .. " " .. word)
                        if #candidate <= 18 then
                            line = candidate
                        else
                            if line ~= "" then lines[#lines + 1] = line end
                            line = word
                        end
                    end
                    if line ~= "" then lines[#lines + 1] = line end
                    return table.concat(lines, "\n")
                end
                local pages = {}
                for _, part in ipairs(parts) do
                    pages[#pages + 1] = wrapTvBeat(part)
                end
                local msg = table.concat(pages, "\f")
  
                if not mod.exports.__beta26.pushWorldText(game, msg, done)
                    and done then done() end
            end,
            },
        })
    end
  
    installNuzlockeScriptHealGate()
    mod.events:on("game.ready", function()
        pcall(installNuzlockeScriptHealGate)
    end)
    mod.events:on("save.loaded", function()
        pcall(installNuzlockeScriptHealGate)
    end)
    mod.events:on("save.created", function()
        pcall(installNuzlockeScriptHealGate)
    end)
  
    end
  
    mod.exports.__beta26.oakCatchTutorialGateHealth = function(game)
        if mod.exports.__beta26.runtimeIsGold(game or currentGame or mod.game) then
            return { state="N/A", detail="Gold uses its native Route 29 adapter" }
        end
        local Commands = mod.exports.__beta26.rbyCommandsFor(
            game or currentGame or mod.game)
        if type(Commands) ~= "table" then
            return { state="PENDING", detail="R/B/Y Commands unavailable" }
        end
        local session = Commands.__nuzlockeSkipOakDemoSession
        local healthy = type(session) == "table" and session.owner == mod
            and type(session.wrapper) == "function"
            and Commands.pushBattle == session.wrapper
        return {
            state = healthy and "HEALTHY" or "MISSING",
            live = healthy == true,
            detail = "pushBattle=" .. tostring(healthy == true),
        }
    end

    mod.exports.__beta26.momHealGateHealth = function(game)
        local Commands = mod.exports.__beta26.rbyCommandsFor(game or currentGame or mod.game)
        if type(Commands) ~= "table" then
            return { state="PENDING", detail="R/B/Y Commands unavailable" }
        end
        local session = Commands.__nuzlockeRulesSession
        local methods = type(session) == "table" and session.methods or nil
        local heal = type(methods) == "table" and methods.heal_party or nil
        local fade = type(methods) == "table" and methods.fade or nil
        local resolve = type(methods) == "table" and methods.resolve or nil
        local healLive = type(heal) == "table"
            and Commands.heal_party == heal.wrapper
        local fadeLive = type(fade) ~= "table"
            or Commands.fade == fade.wrapper
        local resolveLive = type(resolve) ~= "table"
            or Commands.resolve == resolve.wrapper
        local healthy = type(session) == "table" and session.owner == mod
            and healLive and fadeLive and resolveLive
        return {
            state = healthy and "HEALTHY" or "MISSING",
            heal_live = healLive == true,
            fade_live = fadeLive == true,
            resolve_live = resolveLive == true,
            detail = string.format("heal=%s fade=%s resolve=%s",
                tostring(healLive == true), tostring(fadeLive == true),
                tostring(resolveLive == true)),
        }
    end

    -- Try immediately and again at both lifecycle points.  The helper is
    -- idempotent, so whichever point sees Commands first performs the install.

    -- 2.4.10: Gen 1 ShopMenu formats BUY-row prices from item data. Our
    -- synthetic token must use a representable settlement value internally,
    -- so restore the published ¥1,000,000 label at the ListMenu presentation
    -- seam. This wrapper is deliberately scoped to the BUY list and token id.
    local function installForgivenessTokenMillionPricePresentation()
        if mod.exports.__beta26.isSaveEditorSession() then return true end
        local okList, ListMenu = pcall(require, "src.ui.ListMenu")
        if not okList or type(ListMenu) ~= "table"
            or type(ListMenu.new) ~= "function" then return false end
        local prior = ListMenu.__nuzlockeMillionTokenPriceSession
        if type(prior) == "table" and prior.owner == mod
            and ListMenu.new == prior.wrapper then return true end
        if type(prior) == "table" and prior.owner ~= mod
            and ListMenu.new == prior.wrapper
            and type(prior.previous) == "function" then
            ListMenu.new = prior.previous
        end
        local previous = ListMenu.new
        local wrapper
        wrapper = function(game, title, items, opts, ...)
            if tostring(title or ""):upper() == "BUY"
                and type(items) == "table" then
                for _, row in ipairs(items) do
                    if row and tostring(row.value or "")
                        == mod.exports.__beta26.forgivenessTokenShopId then
                        row.right = ("¥%d"):format(
                            mod.exports.__beta26.forgivenessTokenShopPrice)
                    end
                end
            end
            return previous(game, title, items, opts, ...)
        end
        ListMenu.new = wrapper
        ListMenu.__nuzlockeMillionTokenPriceSession = {
            owner = mod, previous = previous, wrapper = wrapper,
        }
        return true
    end

    -- Install immediately while the owning closure is live, then revalidate on
    -- every save/game lifecycle that can replace the active playthrough. NEW
    -- GAME emits save.created rather than save.loaded, so it is an explicit
    -- retry boundary instead of relying on a later unrelated event.
    pcall(installNuzlockeFieldCommandPatches)
    mod.events:on("game.ready", function()
        pcall(mod.exports.__beta26.installPartySizePCGate)
        pcall(installNuzlockeFieldCommandPatches)
    end)
    mod.events:on("save.loaded", function()
        pcall(mod.exports.__beta26.installPartySizePCGate)
        pcall(installNuzlockeFieldCommandPatches)
    end)
    mod.events:on("save.created", function()
        pcall(installNuzlockeFieldCommandPatches)
    end)
  
    ---------------------------------------------------------------------
    -- R/B/Y POKEMON CENTER GATE
    --
    -- Current Gen1Recomp dispatches a nurse directly from OverworldState:talkTo
    -- after resolving the TX_SCRIPT text entry. Gate that exact transaction
    -- before nurseHeal starts. nurseHeal is also wrapped as a narrow fallback.
    ---------------------------------------------------------------------
    local function installNuzlockeCenterGate()
        if mod.exports.__beta26.isSaveEditorSession() then return true end
        local okVersion, GameVersion = pcall(require, "src.core.GameVersion")
        if okVersion and type(GameVersion) == "table"
            and type(GameVersion.isGold) == "function" then
            local okGold, gold = pcall(GameVersion.isGold)
            if okGold and gold == true then return true end
        end
  
        local okOverworld, OverworldState =
            pcall(require, "src.world.OverworldController")
        if not okOverworld or type(OverworldState) ~= "table"
            or type(OverworldState.talkTo) ~= "function"
            or type(OverworldState.nurseHeal) ~= "function" then
            return false
        end
        local priorSession = OverworldState.__nuzlockeCenterGateSession
        if type(priorSession) == "table" and priorSession.owner == mod
            and OverworldState.talkTo == priorSession.talkTo
            and OverworldState.nurseHeal == priorSession.nurseHeal then
            return true
        end
        if type(priorSession) == "table" and priorSession.owner ~= mod then
            if OverworldState.talkTo == priorSession.talkTo
                and type(priorSession.previousTalkTo) == "function" then
                OverworldState.talkTo = priorSession.previousTalkTo
            end
            if OverworldState.nurseHeal == priorSession.nurseHeal
                and type(priorSession.previousNurseHeal) == "function" then
                OverworldState.nurseHeal = priorSession.previousNurseHeal
            end
        end
  
        local vanillaTalkTo = OverworldState.talkTo
        local vanillaNurseHeal = OverworldState.nurseHeal
  
        local function liveGame()
            local game = mod.game
            if type(game) == "table" and game.stack and game.data then return game end
            if type(currentGame) == "table" and currentGame.stack and currentGame.data then
                return currentGame
            end
            return nil
        end
  
        local function denyCenter(game, self, npc, onDone)
            if npc and type(npc.facePlayer) == "function" and self and self.player then
                pcall(npc.facePlayer, npc, self.player)
            end
            local msg = mod.exports.__beta26.worldRuleText(
                game, "no_poke_center")
            if not mod.exports.__beta26.pushWorldText(game, msg, onDone)
                and onDone then
                onDone()
            end
        end
  
        local talkToWrapper
        talkToWrapper = function(self, npc, ...)
            local game = liveGame()
            if mod.exports.__beta26.ruleActive(game, "no_poke_center")
                and npc and type(npc.def) == "table" then
                local data = game and game.data
                local map = self and self.map
                local def = map and map.def
                local entry
                if data and def and type(data.textEntry) == "function" then
                    local okEntry, resolved = pcall(data.textEntry, data, def.label, npc.def.text)
                    if okEntry then entry = resolved end
                end
                if type(entry) == "table" and entry.nurse then
                    npc.frozen = true
                    denyCenter(game, self, npc, function() npc.frozen = false end)
                    return
                end
            end
            return vanillaTalkTo(self, npc, ...)
        end
  
        local nurseHealWrapper
        nurseHealWrapper = function(self, onDone, npc, ...)
            local game = liveGame()
            if mod.exports.__beta26.ruleActive(game, "no_poke_center") then
                denyCenter(game, self, npc, onDone)
                return
            end
            return vanillaNurseHeal(self, onDone, npc, ...)
        end
        OverworldState.talkTo = talkToWrapper
        OverworldState.nurseHeal = nurseHealWrapper
        OverworldState.__nuzlockeCenterGateOwner = mod
        OverworldState.__nuzlockeCenterGateSession = {
            owner = mod,
            talkTo = talkToWrapper, previousTalkTo = vanillaTalkTo,
            nurseHeal = nurseHealWrapper, previousNurseHeal = vanillaNurseHeal,
        }
        return true
    end
  
    -- 2.3.10: deferred until game.ready/save.loaded.
    mod.events:on("game.ready", function()
        pcall(installNuzlockeCenterGate)
    end)
    mod.events:on("save.loaded", function()
        pcall(installNuzlockeCenterGate)
    end)
  
    ---------------------------------------------------------------------
    -- GAME CORNER WAGER / PRIZE GATE
    --
    -- Celadon's slot screen subtracts coins only after its bet confirmation,
    -- and its three prize-counter talk handlers grant the prize before charging
    -- coins. Block both entry points, leaving the Rocket story path, coin clerk,
    -- free-coin NPCs, and ordinary movement untouched.
    ---------------------------------------------------------------------
    -- These are intentionally different engine IDs. R/B/Y calls the room
    -- GAME_CORNER_PRIZE_ROOM; Gold's postgame Kanto data prefixes the city.
    -- Keep every Game Corner adapter on one named table so the two generations
    -- cannot be accidentally "corrected" into the same, wrong identifier.
    mod.exports.__beta26.gameCornerMapIds = {
        rbyPrizeRoom = "GAME_CORNER_PRIZE_ROOM",
        gscGoldenrod = "GOLDENROD_GAME_CORNER",
        gscCeladonPrizeRoom = "CELADON_GAME_CORNER_PRIZE_ROOM",
    }
  
    mod.exports.__beta26.installGameCornerRuleGate = function()
        if mod.exports.__beta26.isSaveEditorSession() then return true end
  
        local okWorld, OverworldState = pcall(require, "src.world.OverworldController")
        local okSlots, SlotMachine = pcall(require, "src.ui.SlotMachine")
        if not okWorld or type(OverworldState) ~= "table"
            or type(OverworldState.showMapText) ~= "function"
            or not okSlots or type(SlotMachine) ~= "table"
            or type(SlotMachine.update) ~= "function"
            or type(SlotMachine.draw) ~= "function" then
            return false
        end
  
        local worldSession = OverworldState.__nuzlockeGameCornerSession
        if not (type(worldSession) == "table" and worldSession.owner == mod
            and OverworldState.showMapText == worldSession.wrapper) then
            if type(worldSession) == "table" and worldSession.owner ~= mod
                and OverworldState.showMapText == worldSession.wrapper
                and type(worldSession.previous) == "function" then
                OverworldState.showMapText = worldSession.previous
            end
            local previousShowMapText = OverworldState.showMapText
            local showMapTextWrapper
            showMapTextWrapper = function(self, textConst, npc, onDone, ...)
                local mapId = self and self.map and self.map.id
                local prize = tostring(textConst or ""):find(
                    "TEXT_GAMECORNERPRIZEROOM_PRIZE_VENDOR_", 1, true) == 1
                local game = currentGame or mod.game
                if mapId == mod.exports.__beta26.gameCornerMapIds.rbyPrizeRoom
                    and prize
                    and mod.exports.__beta26.ruleActive(game, "no_gambling") then
                    if npc and type(npc.facePlayer) == "function" and self.player then
                        pcall(npc.facePlayer, npc, self.player)
                    end
                    local done = type(onDone) == "function" and onDone or function() end
                    if not mod.exports.__beta26.pushWorldText(game,
                        mod.exports.__beta26.worldRuleText(game, "no_gambling"), done) then
                        done()
                    end
                    return
                end
                return previousShowMapText(self, textConst, npc, onDone, ...)
            end
            OverworldState.showMapText = showMapTextWrapper
            OverworldState.__nuzlockeGameCornerSession = {
                owner = mod, previous = previousShowMapText,
                wrapper = showMapTextWrapper,
            }
        end
  
        local slotSession = SlotMachine.__nuzlockeGameCornerSession
        if type(slotSession) == "table" and slotSession.owner == mod
            and SlotMachine.update == slotSession.update
            and SlotMachine.draw == slotSession.draw then
            return true
        end
        if type(slotSession) == "table" and slotSession.owner ~= mod then
            if SlotMachine.update == slotSession.update
                and type(slotSession.previousUpdate) == "function" then
                SlotMachine.update = slotSession.previousUpdate
            end
            if SlotMachine.draw == slotSession.draw
                and type(slotSession.previousDraw) == "function" then
                SlotMachine.draw = slotSession.previousDraw
            end
        end
  
        local previousUpdate, previousDraw = SlotMachine.update, SlotMachine.draw
        local blockedUpdate, blockedDraw
        blockedUpdate = function(self, dt)
            local game = self and self.game
            if mod.exports.__beta26.ruleActive(game, "no_gambling") then
                local input = game and game.input
                if input and (input:wasPressed("a") or input:wasPressed("b"))
                    and game.stack then
                    game.stack:pop()
                end
                return
            end
            return previousUpdate(self, dt)
        end
        blockedDraw = function(self)
            local game = self and self.game
            if not mod.exports.__beta26.ruleActive(game, "no_gambling") then
                return previousDraw(self)
            end
            local okFont, Font = pcall(require, "src.render.Font")
            love.graphics.setColor(1, 1, 1, 1)
            love.graphics.rectangle("fill", 0, 0, 160, 144)
            love.graphics.setColor(0, 0, 0, 1)
            if okFont and Font then
                Font.draw(Strings("NO GAMBLING"), 32, 32)
                local lines = wrapText(mod.exports.__beta26.worldRuleText(
                    game, "no_gambling"), 18)
                for i = 1, math.min(4, #lines) do
                    Font.draw(lines[i], 8, 48 + (i - 1) * 12)
                end
                Font.draw(Strings("A/B: LEAVE"), 32, 108)
            end
            love.graphics.setColor(1, 1, 1, 1)
        end
        SlotMachine.update, SlotMachine.draw = blockedUpdate, blockedDraw
        SlotMachine.__nuzlockeGameCornerSession = {
            owner = mod,
            previousUpdate = previousUpdate, update = blockedUpdate,
            previousDraw = previousDraw, draw = blockedDraw,
        }
        return true
    end
  
    -- 2.3.10: deferred until game.ready/save.loaded.
    mod.events:on("game.ready", function()
        pcall(mod.exports.__beta26.installGameCornerRuleGate)
    end)
    mod.events:on("save.loaded", function()
        pcall(mod.exports.__beta26.installGameCornerRuleGate)
    end)
  
  
    ---------------------------------------------------------------------
    -- SHOP BUY / SELL GATE
    --
    -- Keep the normal Mart menu and only replace the selected action. This is
    -- safer than blocking open_mart: BUY and SELL can be controlled separately,
    -- QUIT always works, and vanilla/custom stock handling remains untouched.
    ---------------------------------------------------------------------
    local function installShopRuleGate()
        if mod.exports.__beta26.isSaveEditorSession() then return true end
        local okShop, ShopMenu = pcall(require, "src.ui.ShopMenu")
        if not okShop or type(ShopMenu) ~= "table"
            or type(ShopMenu.new) ~= "function" then
            return false
        end
        local priorSession = ShopMenu.__nuzlockeShopRuleGateSession
        if type(priorSession) == "table" and priorSession.owner == mod
            and ShopMenu.new == priorSession.wrapper then
            return true
        end
        if type(priorSession) == "table" and priorSession.owner ~= mod
            and ShopMenu.new == priorSession.wrapper
            and type(priorSession.previous) == "function" then
            ShopMenu.new = priorSession.previous
        end
  
        local vanillaNew = ShopMenu.new
  
        local function deny(game, kind)
            local key = kind == "BUY" and "no_buying" or "no_selling"
            mod.exports.__beta26.pushWorldText(
                game, mod.exports.__beta26.worldRuleText(game, key))
        end
  
        local shopNewWrapper
        shopNewWrapper = function(game, stock, onQuit)
            pcall(mod.exports.__beta26.installForgivenessTokenBagBridge)
            local shownStock = mod.exports.__beta26.withForgivenessTokenStock(game, stock)
            local menu = vanillaNew(game, shownStock, onQuit)
            local translatedBuy = tostring(Strings("BUY"))
            local translatedSell = tostring(Strings("SELL"))
            for _, item in ipairs(menu and menu.items or {}) do
                local label = tostring(item and item.label or "")
                local upper = label:upper()
                if ((item.id and tostring(item.id):upper() == "BUY")
                    or (item.action and tostring(item.action):upper() == "BUY")
                    or (item.value and tostring(item.value):upper() == "BUY")
                    or upper == "BUY" or label == translatedBuy)
                    and type(item.onSelect) == "function" then
                    local vanillaBuy = item.onSelect
                    item.onSelect = function(...)
                        local allowed = mod.exports.nuzlocke_compat.canPurchase(
                            game, { kind = "item_shop" })
                        if allowed == false then
                            deny(game, "BUY")
                            return
                        end
                        return vanillaBuy(...)
                    end
                elseif ((item.id and tostring(item.id):upper() == "SELL")
                    or (item.action and tostring(item.action):upper() == "SELL")
                    or (item.value and tostring(item.value):upper() == "SELL")
                    or upper == "SELL" or label == translatedSell)
                    and type(item.onSelect) == "function" then
                    local vanillaSell = item.onSelect
                    item.onSelect = function(...)
                        local allowed = mod.exports.nuzlocke_compat.canSell(
                            game, { kind = "item_shop" })
                        if allowed == false then
                            deny(game, "SELL")
                            return
                        end
                        return vanillaSell(...)
                    end
                end
            end
            return menu
        end
  
        ShopMenu.new = shopNewWrapper
        ShopMenu.__nuzlockeShopRuleGateInstalled = true
        ShopMenu.__nuzlockeShopRuleGateOwner = mod
        ShopMenu.__nuzlockeShopRuleGateSession = {
            owner = mod, previous = vanillaNew, wrapper = shopNewWrapper,
        }
        return true
    end
  
    -- 2.3.10: deferred until game.ready/save.loaded.
    mod.events:on("game.ready", function()
        pcall(installShopRuleGate)
        pcall(installForgivenessTokenMillionPricePresentation)
    end)
    mod.events:on("save.loaded", function()
        pcall(installShopRuleGate)
        pcall(installForgivenessTokenMillionPricePresentation)
    end)
  
  
    ---------------------------------------------------------------------
    -- CHECKPOINT / SAVESTATE RECONCILIATION
    --
    -- Public checkpoint restores rewind canonical game state and mod.save but
    -- intentionally do not serialize arbitrary Lua locals. Rebind only our
    -- progress-derived runtime references/caches after a successful restore.
    -- Do not run migrations or reconstruct canonical tracker history here: the
    -- restored mod.save is already authoritative.
    ---------------------------------------------------------------------
    mod.events:on("checkpoint.restored", function(ev)
        local game = type(ev) == "table" and ev.game or ev
        if game then
            currentGame = game
            currentSave = game.save or currentSave
        elseif currentGame then
            currentSave = currentGame.save or currentSave
        end
  
        -- A restore can move backward across a battle boundary. These values are
        -- runtime-only observations and must never survive that rewind.
        activeWildEncounter = nil
        finalizedNuzlockeBattles = setmetatable({}, { __mode = "k" })
        mod.exports.__beta26.pendingStaticEncounter = nil
  
        -- Rebuild only mirrors/projections derived from the restored canonical
        -- save. The projection helper is additive and preserves physical catch
        -- provenance while immediately reflecting restored split settings.
        pcall(refreshRuleMirrorFromSave)
        if mod.exports.__beta26.ensureEncounterProjection then
            pcall(mod.exports.__beta26.ensureEncounterProjection)
        end
        local refreshGuide = mod.exports.__beta26.refreshGymGuideVisibility
        if refreshGuide and currentGame then
            pcall(refreshGuide, currentGame)
        end
    end)
  
  end
  mod.exports.__beta26._lateRuntimeInit()
  -- Phase 1 stages the second closure into _lateRuntimeInit. 2.5.22 then
  -- cleared that slot without ever executing it, leaving the Yellow Oak demo
  -- skip and the authoritative Mom script-command gate dormant. Execute the
  -- staged closure exactly once and retain a machine-readable health result.
  if type(mod.exports.__beta26._lateRuntimeInit) == "function" then
      mod.exports.__beta26.lateRuntimePhase2Ready,
      mod.exports.__beta26.lateRuntimePhase2Error =
          pcall(mod.exports.__beta26._lateRuntimeInit)
      if mod.exports.__beta26.lateRuntimePhase2Ready ~= true then
          mod.exports.__beta26.lateRuntimePhase2Error =
              tostring(mod.exports.__beta26.lateRuntimePhase2Error or "unknown error")
      end
  else
      mod.exports.__beta26.lateRuntimePhase2Ready = false
      mod.exports.__beta26.lateRuntimePhase2Error = "phase 2 was not staged"
  end
  mod.exports.__beta26._lateRuntimeInit = nil

  mod.exports.__beta26._lateRuntimeInit = function()
    -- 2.2.7: duplicated intentionally across the two late-runtime phases.
    -- Keeping it local to each phase avoids another main-scope local or a
    -- cross-phase upvalue solely for this small shared predicate.
    local function hasHealthyParty(game)
        local party = game and game.save and game.save.party or {}
        for _, mon in ipairs(party) do
            if mon then
                local hp = tonumber(mon.hp or mon.currentHp or mon.health)
                if hp ~= nil then
                    if hp > 0 then return true end
                elseif mon.fainted ~= true and mon.status ~= "fainted" then
                    return true
                end
            end
        end
        return false
    end

    ---------------------------------------------------------------------
    -- GOLD CORE-RULE ADAPTERS
    --
    -- Gold has a separate battle UI, script VM, naming screen and mart UI.
    -- Keep the established R/B/Y paths above untouched and bridge the same
    -- Nuzlocke policy into the live Gen 2 modules here.
    ---------------------------------------------------------------------
    do
        local G2 = {}
  
        function G2.isGold(game)
            return mod.exports.__beta26.runtimeIsGold(
                game or currentGame or mod.game)
        end
  
        function G2.catchMessage(game, reason, species)
            return mod.exports.__beta26.catchRejectionMessage(game, reason, species)
        end
  
        function G2.installCaptureGate()
            if not G2.isGold() then return false end
            local ok, BS = pcall(require, "src.ui.gen2.BattleState")
            if not ok or type(BS) ~= "table" or type(BS.useItem) ~= "function" then return false end

            local session = BS.__nuzlockeCaptureGateSession
            if type(session) == "table" and session.owner ~= mod
                and BS.useItem == session.wrapper
                and type(session.previous) == "function" then
                BS.useItem = session.previous
                session = nil
            end
            if type(session) == "table" and session.owner == mod
                and BS.useItem == session.wrapper then
                return true
            end

            local vanilla = BS.useItem
            local captureWrapper
            captureWrapper = function(self, itemId)
                local data = self and self.game and self.game.data or {}
                local def = data.items and data.items[itemId]
                if self and self.battle and not self.tutorial
                    and not (def and def.pocket == "BALL") then
                    local allowed, decision = evaluateItemUsePolicy(
                        self.game, data, self.game and self.game.save, itemId, nil,
                        { battle = self.battle, inBattle = true,
                          generation = 2,
                          isBall = def and def.pocket == "BALL" })
                    -- 0.1.98's Gold battle Pack now routes healing/status/revive,
                    -- PP recovery, stat/X items, and balls through this one
                    -- semantic useItem path. Any authoritative Nuzlocke item
                    -- denial must stop here; do not whitelist only two codes.
                    if allowed == false then
                        local tier = worldTier(self.game)
                        local message = decision and decision.message
                            or Strings("Item use is blocked!")
                        if tier >= 3 and decision and decision.tier3 then
                            message = decision.tier3
                        elseif tier >= 2 and decision and decision.tier2 then
                            message = decision.tier2
                        end
                        self.queue = {}
                        self.message = mod.exports.__beta26.cleanWorldText(message)
                        self.messageTimer = 48
                        self.phase = "resolving"
                        return
                    end
                end
                -- Native Gold uses battle.wild for every non-trainer battle,
                -- including loadwildmon-driven static encounters. Also accept
                -- explicit static provenance for compatibility with mods that
                -- construct a fixed battle without the native opts.wild shape.
                local catchableBattle = self and self.battle
                    and (self.battle.wild
                        or mod.exports.__beta26.isStaticEncounter(
                            self.game, self.battle))
                if def and def.pocket == "BALL" and self and self.battle
                    and catchableBattle and not self.tutorial then
                    local allowed, decision = evaluateItemUsePolicy(
                        self.game, data, self.game and self.game.save, itemId, nil,
                        { battle = self.battle, inBattle = true, isBall = true })
                    if allowed == false then
                        local tier = worldTier(self.game)
                        local message = decision and decision.message
                            or Strings("No Catching is ON!")
                        if tier >= 3 and decision and decision.tier3 then
                            message = decision.tier3
                        elseif tier >= 2 and decision and decision.tier2 then
                            message = decision.tier2
                        end
                        self.queue = {}
                        self.message = mod.exports.__beta26.cleanWorldText(message)
                        self.messageTimer = 48
                        self.phase = "resolving"
                        return
                    end
                    local enemy = self.battle.enemy
                    local species = enemy and enemy.species
                    local okReason, reason = pcall(catchDeniedReason,
                        self.game, self.battle, species)
                    if okReason and reason then
                        self.queue = {}
                        self.message = G2.catchMessage(self.game, reason, species)
                            or Strings("That catch is not allowed by your Nuzlocke rules.")
                        self.messageTimer = 48
                        self.phase = "resolving"
                        return
                    end
                    local ballAllowed, ballLimit =
                        mod.exports.__beta26.encounterBallThrowAvailable(
